func init() {
	min_set_ch = 1
	command_frame_height = TRUE
	main_errors = [3]Ptr[byte]{S("Unknown option argument"), S("Too many \"+command\", \"-c command\" or \"--cmd command\" arguments"), S("Invalid argument for")}
}

// C: the five buffheader_T initializers {{nullptr, 0, (char_u[1]){NUL}},
// nullptr, 0, 0, FALSE}: each head's b_str is a byte of its own, holding a
// NUL; every other member is zero.
func init() {
	redobuff.bh_first.b_str = Mk[byte](1)
	old_redobuff.bh_first.b_str = Mk[byte](1)
	recordbuff.bh_first.b_str = Mk[byte](1)
	readbuf1.bh_first.b_str = Mk[byte](1)
	readbuf2.bh_first.b_str = Mk[byte](1)
}

// ==== from f01.go ====
// Transpiled by hand from editor.c: musl_strlen .. ex_history.

func musl_strlen(s Ptr[byte]) usize {
	a := s
	for ; s.Get() != 0; s = s.Add(1) {
	}
	return usize(s.Sub(a))
}

func musl_strcpy(dest Ptr[byte], src Ptr[byte]) Ptr[byte] {
	d := dest
	for {
		d.Put(src.Get())
		if d.Get() == 0 {
			break
		}
		d = d.Add(1)
		src = src.Add(1)
	}
	return dest
}

func musl_strncpy(dest Ptr[byte], src Ptr[byte], n usize) Ptr[byte] {
	d := dest
	for ; n != 0 && src.Get() != 0; n-- {
		d.Put(src.Get())
		d = d.Add(1)
		src = src.Add(1)
	}
	for ; n != 0; n-- {
		d.Put(0)
		d = d.Add(1)
	}
	return dest
}

func musl_strcat(dest Ptr[byte], src Ptr[byte]) Ptr[byte] {
	musl_strcpy(dest.Add(int(musl_strlen(dest))), src)
	return dest
}

func musl_strcmp(l Ptr[byte], r Ptr[byte]) int32 {
	for ; l.Get() == r.Get() && l.Get() != 0; l, r = l.Add(1), r.Add(1) {
	}
	return int32(l.Get()) - int32(r.Get())
}

func musl_strncmp(ls Ptr[byte], rs Ptr[byte], n usize) int32 {
	l := ls
	r := rs
	if n == 0 {
		return 0
	}
	n--
	for ; l.Get() != 0 && r.Get() != 0 && n != 0 && l.Get() == r.Get(); l, r, n = l.Add(1), r.Add(1), n-1 {
	}
	return int32(l.Get()) - int32(r.Get())
}

func musl_strcasecmp(ls Ptr[byte], rs Ptr[byte]) int32 {
	// fold is the expression `(unsigned)c - 'A' < 26 ? c | 32 : c`.
	fold := func(c byte) int32 {
		if uint32(c)-'A' < 26 {
			return int32(c | 32)
		}
		return int32(c)
	}
	l := ls
	r := rs
	for ; l.Get() != 0 && r.Get() != 0 && fold(l.Get()) == fold(r.Get()); l, r = l.Add(1), r.Add(1) {
	}
	return fold(l.Get()) - fold(r.Get())
}

func musl_strncasecmp(ls Ptr[byte], rs Ptr[byte], n usize) int32 {
	// fold is the expression `(unsigned)c - 'A' < 26 ? c | 32 : c`.
	fold := func(c byte) int32 {
		if uint32(c)-'A' < 26 {
			return int32(c | 32)
		}
		return int32(c)
	}
	l := ls
	r := rs
	if n == 0 {
		return 0
	}
	n--
	for ; l.Get() != 0 && r.Get() != 0 && n != 0 && fold(l.Get()) == fold(r.Get()); l, r, n = l.Add(1), r.Add(1), n-1 {
	}
	return fold(l.Get()) - fold(r.Get())
}

func musl_strchr(s Ptr[byte], c int32) Ptr[byte] {
	ch := byte(c)
	for ; s.Get() != 0 && s.Get() != ch; s = s.Add(1) {
	}
	if s.Get() == ch {
		return s
	}
	return Ptr[byte]{}
}

func musl_strstr(h Ptr[byte], n Ptr[byte]) Ptr[byte] {
	var i usize
	if n.At(0) == 0 {
		return h
	}
	for ; h.Get() != 0; h = h.Add(1) {
		for i = 0; n.At(int(i)) != 0 && h.At(int(i)) == n.At(int(i)); i++ {
		}
		if n.At(int(i)) == 0 {
			return h
		}
	}
	return Ptr[byte]{}
}

func musl_strpbrk(s Ptr[byte], b Ptr[byte]) Ptr[byte] {
	var c Ptr[byte]
	for ; s.Get() != 0; s = s.Add(1) {
		for c = b; c.Get() != 0; c = c.Add(1) {
			if s.Get() == c.Get() {
				return s
			}
		}
	}
	return Ptr[byte]{}
}

func musl_isdigit(c int32) int32 {
	return B2i(uint32(c)-'0' < 10)
}

func musl_isalpha(c int32) int32 {
	return B2i((uint32(c)|32)-'a' < 26)
}

func musl_isupper(c int32) int32 {
	return B2i(uint32(c)-'A' < 26)
}

func musl_islower(c int32) int32 {
	return B2i(uint32(c)-'a' < 26)
}

func musl_isgraph(c int32) int32 {
	return B2i(uint32(c)-0x21 < 0x5e)
}

func musl_isspace(c int32) int32 {
	return B2i(uint32(c)-'\t' < 5 || c == ' ')
}

func musl_isalnum(c int32) int32 {
	return B2i(musl_isalpha(c) != 0 || musl_isdigit(c) != 0)
}

func musl_iscntrl(c int32) int32 {
	return B2i(uint32(c) < 0x20 || c == 0x7f)
}

func musl_ispunct(c int32) int32 {
	return B2i(musl_isgraph(c) != 0 && musl_isalnum(c) == 0)
}

func musl_tolower(c int32) int32 {
	if musl_isupper(c) != 0 {
		return c | 32
	}
	return c
}

func musl_toupper(c int32) int32 {
	if musl_islower(c) != 0 {
		return c & 0x5f
	}
	return c
}

func musl_atoi(s Ptr[byte]) int32 {
	var n int32 = 0
	var neg int32 = 0

	for musl_isspace(int32(s.Get())) != 0 {
		s = s.Add(1)
	}
	if s.Get() == '-' {
		neg = 1
		s = s.Add(1)
	} else if s.Get() == '+' {
		s = s.Add(1)
	}
	for musl_isdigit(int32(s.Get())) != 0 {
		c := s.Get()
		s = s.Add(1)
		n = 10*n - (int32(c) - '0')
	}
	if neg != 0 {
		return n
	}
	return -n
}

func musl_atol(s Ptr[byte]) int64 {
	var n int64 = 0
	var neg int32 = 0

	for musl_isspace(int32(s.Get())) != 0 {
		s = s.Add(1)
	}
	if s.Get() == '-' {
		neg = 1
		s = s.Add(1)
	} else if s.Get() == '+' {
		s = s.Add(1)
	}
	for musl_isdigit(int32(s.Get())) != 0 {
		c := s.Get()
		s = s.Add(1)
		n = 10*n - (int64(c) - '0')
	}
	if neg != 0 {
		return n
	}
	return -n
}

func musl_strtol(s Ptr[byte], end *Ptr[byte], base int32) int64 {
	p := s
	var n uint64 = 0
	var lim uint64
	var neg int32 = 0
	var any_ int32 = 0
	var over int32 = 0

	for musl_isspace(int32(p.Get())) != 0 {
		p = p.Add(1)
	}
	if p.Get() == '-' {
		neg = 1
		p = p.Add(1)
	} else if p.Get() == '+' {
		p = p.Add(1)
	}
	lim = (^uint64(0) >> 1) + uint64(neg)
	for base == 10 && musl_isdigit(int32(p.Get())) != 0 {
		c := p.Get()
		p = p.Add(1)
		d := uint64(int32(c) - '0')

		any_ = 1
		if over != 0 || n > (lim-d)/10 {
			over = 1
		} else {
			n = 10*n + d
		}
	}
	if end != nil {
		if any_ != 0 {
			*end = p
		} else {
			*end = s
		}
	}
	if over != 0 {
		n = lim
	}
	if neg != 0 {
		return int64(0 - n)
	}
	return int64(n)
}

func musl_abs(a int32) int32 {
	if a > 0 {
		return a
	}
	return -a
}

func musl_labs(a int64) int64 {
	if a > 0 {
		return a
	}
	return -a
}

func gettext_(x Ptr[byte]) Ptr[byte] {
	return x
}

func NGETTEXT(x Ptr[byte], xs Ptr[byte], n uint64) Ptr[byte] {
	if n == 1 {
		return x
	}
	return xs
}

