func vim_memsave(p Ptr[byte], len_ usize) Ptr[byte] {
	ret := Alloc(int(len_))

	if !ret.Nil() {
		Memmove(ret, p, int(len_))
	}
	return ret
}

func ga_clear(gap *S_growarray) {
	ga_init(gap)
}

func ga_clear_strings(gap *S_growarray) {
	// C frees every string here; the collector owns them.
	ga_clear(gap)
}

func ga_init(gap *S_growarray) {
	gap.ga_data = nil
	gap.ga_maxlen = 0
	gap.ga_len = 0
}

func ga_init2(gap *S_growarray, itemsize usize, growsize int32) {
	ga_init(gap)
	gap.ga_itemsize = int32(itemsize)
	gap.ga_growsize = growsize
}

func ga_grow(gap *S_growarray, n int32) int32 {
	if gap.ga_maxlen-gap.ga_len < n {
		return ga_grow_inner(gap, n)
	}
	return OK
}

func ga_grow_inner(gap *S_growarray, n int32) int32 {
	if n < gap.ga_growsize {
		n = gap.ga_growsize
	}

	if n < gap.ga_len/2 {
		n = gap.ga_len / 2
	}

	if n > 0 && usize(gap.ga_len+n) > SIZE_MAX/usize(gap.ga_itemsize) {
		return FAIL
	}
	// C allocates, copies and clears new_len bytes here; GaGrowTo does it
	// in elements of the storage's type.
	gap.ga_maxlen = gap.ga_len + n
	GaGrowTo(gap, int(gap.ga_maxlen))
	return OK
}

func ga_concat(gap *S_growarray, s Ptr[byte]) {
	var len_ int32

	if s.Nil() || s.Get() == NUL {
		return
	}
	len_ = int32(musl_strlen(s))
	if ga_grow(gap, len_) == OK {
		Memmove(GaData[byte](gap).Add(int(gap.ga_len)), s, int(usize(len_)))
		gap.ga_len += len_
	}
}

func ga_concat_len(gap *S_growarray, s Ptr[byte], len_ usize) {
	if s.Nil() || s.Get() == NUL || len_ == 0 {
		return
	}
	if ga_grow(gap, int32(len_)) == OK {
		Memmove(GaData[byte](gap).Add(int(gap.ga_len)), s, int(len_))
		gap.ga_len += int32(len_)
	}
}

func ga_append(gap *S_growarray, c int32) int32 {
	if ga_grow(gap, 1) == FAIL {
		return FAIL
	}
	GaData[byte](gap).Set(int(gap.ga_len), byte(c))
	gap.ga_len++
	return OK
}

