func ins_tab() int32 {
	var ind int32
	var i int32
	var temp int32

	ind = inindent(0)
	if curbuf.b_p_et == 0 && !(p_sta != 0 && ind != 0 && curbuf.b_p_ts != get_sw_value(curbuf)) && get_sts_value() == 0 {
		return TRUE
	}

	if stop_arrow() == FAIL {
		return TRUE
	}

	did_ai = FALSE
	did_si = FALSE
	can_si = FALSE
	can_si_back = FALSE
	AppendToRedobuff(S("\t"))

	if p_sta != 0 && ind != 0 {
		temp = int32(get_sw_value(curbuf))
	} else if curbuf.b_p_sts != 0 {
		temp = int32(get_sts_value())
	} else {
		temp = int32(curbuf.b_p_ts)
	}
	temp -= get_nolist_virtcol() % temp

	ins_char(' ')
	for {
		temp--
		if !(temp > 0) {
			break
		}
		if State&VREPLACE_FLAG != 0 {
			ins_char(' ')
		} else {
			ins_str(S(" "), 1)
			if State&REPLACE_FLAG != 0 {
				replace_push(NUL)
			}
		}
	}

	if curbuf.b_p_et == 0 && (get_sts_value() != 0 || (p_sta != 0 && ind != 0)) {
		var ptr Ptr[byte]
		var saved_line Ptr[byte] = Ptr[byte]{}
		var pos pos_T
		var fpos pos_T
		var cursor *pos_T
		var want_vcol colnr_T
		var vcol colnr_T
		var change_col int32 = -1
		var save_list int32 = curwin.w_onebuf_opt.wo_list
		var tab Ptr[byte] = S("\t")
		var cts chartabsize_T

		if State&VREPLACE_FLAG != 0 {
			pos = curwin.w_cursor
			cursor = &pos
			{
				len := ml_get_curline_len()

				saved_line = vim_strnsave(ml_get_curline(), usize(len))
			}
			ptr = saved_line.Add(int(pos.col))
		} else {
			ptr = ml_get_cursor()
			cursor = &curwin.w_cursor
		}

		if vim_strchr(p_cpo, CPO_LISTWM).Nil() {
			curwin.w_onebuf_opt.wo_list = FALSE
		}

		fpos = curwin.w_cursor
		for fpos.col > 0 && (ptr.At(-1) == ' ' || ptr.At(-1) == '\t') {
			fpos.col--
			ptr = ptr.Add(-1)
		}

		if State&REPLACE_FLAG != 0 && fpos.lnum == Insstart.lnum && fpos.col < Insstart.col {
			ptr = ptr.Add(int(Insstart.col - fpos.col))
			fpos.col = Insstart.col
		}

		getvcol(curwin, &fpos, &vcol, nil, nil, 0)
		getvcol(curwin, cursor, &want_vcol, nil, nil, 0)

		init_chartabsize_arg(&cts, curwin, 0, vcol, tab, tab)

		for ptr.Get() == ' ' || ptr.Get() == '\t' {
			i = lbr_chartabsize(&cts)
			if cts.cts_vcol+i > want_vcol {
				break
			}
			if ptr.Get() != TAB {
				ptr.Put(TAB)
				if change_col < 0 {
					change_col = fpos.col
					if fpos.lnum == Insstart.lnum && fpos.col < Insstart.col {
						Insstart.col = fpos.col
					}
				}
			}
			fpos.col++
			ptr = ptr.Add(1)
			cts.cts_vcol += i
		}
		vcol = cts.cts_vcol

		if change_col >= 0 {
			var repl_off int32 = 0

			init_chartabsize_arg(&cts, curwin, 0, vcol, ptr, ptr)
			for cts.cts_vcol < want_vcol && cts.cts_ptr.Get() == ' ' {
				cts.cts_vcol += lbr_chartabsize(&cts)
				cts.cts_ptr = cts.cts_ptr.Add(1)
				repl_off++
			}
			ptr = cts.cts_ptr
			vcol = cts.cts_vcol

			if vcol > want_vcol {
				ptr = ptr.Add(-1)
				repl_off--
			}
			fpos.col += repl_off

			i = cursor.col - fpos.col
			if i > 0 {
				Memmove(ptr, ptr.Add(int(i)), int(musl_strlen(ptr.Add(int(i))))+1)
				if State&REPLACE_FLAG != 0 && State&VREPLACE_FLAG == 0 {
					for temp = i; ; {
						temp--
						if !(temp >= 0) {
							break
						}
						replace_join(repl_off)
					}
				}
			}
			cursor.col -= i

			if State&VREPLACE_FLAG != 0 {
				backspace_until_column(change_col)

				ins_bytes_len(saved_line.Add(int(change_col)), cursor.col-change_col)
			}
		}

		curwin.w_onebuf_opt.wo_list = save_list
	}

	return FALSE
}

func ins_eol(c int32) int32 {
	var i int32

	if stop_arrow() == FAIL {
		return FAIL
	}
	undisplay_dollar()

	if State&REPLACE_FLAG != 0 && State&VREPLACE_FLAG == 0 {
		replace_push(NUL)
	}

	if virtual_active() != 0 && curwin.w_cursor.coladd > 0 {
		coladvance(getviscol())
	}

	AppendToRedobuff(S("\012"))
	i = open_line(FORWARD, 0, old_indent, nil)
	old_indent = 0

	return i
}

func ins_copychar(lnum linenr_T) int32 {
	var c int32
	var ptr Ptr[byte]
	var prev_ptr Ptr[byte]
	var line Ptr[byte]
	var cts chartabsize_T

	if lnum < 1 || lnum > curbuf.b_ml.ml_line_count {
		vim_beep(BO_COPY)
		return NUL
	}

	validate_virtcol()
	line = ml_get(lnum)
	prev_ptr = line
	init_chartabsize_arg(&cts, curwin, lnum, 0, line, line)
	for cts.cts_vcol < curwin.w_virtcol && cts.cts_ptr.Get() != NUL {
		prev_ptr = cts.cts_ptr
		cts.cts_vcol += lbr_chartabsize_adv(&cts)
	}
	if cts.cts_vcol > curwin.w_virtcol {
		ptr = prev_ptr
	} else {
		ptr = cts.cts_ptr
	}

	c = utf_ptr2char(ptr)
	if c == NUL {
		vim_beep(BO_COPY)
	}
	return c
}

func ins_ctrl_ey(tc int32) int32 {
	var c int32 = tc

	if ctrl_x_mode_scroll() != 0 {
		if c == Ctrl_Y {
			scrolldown_clamp()
		} else {
			scrollup_clamp()
		}
		redraw_later(UPD_VALID)
	} else {
		var d linenr_T
		if c == Ctrl_Y {
			d = -1
		} else {
			d = 1
		}
		c = ins_copychar(curwin.w_cursor.lnum + d)
		if c != NUL {
			var tw_save int64

			if c < 256 && musl_isalnum(int32(byte(c))) == 0 {
				AppendToRedobuff(S("\026"))
			}
			tw_save = curbuf.b_p_tw
			curbuf.b_p_tw = -1
			insert_special(c, TRUE, FALSE)
			curbuf.b_p_tw = tw_save
			c = Ctrl_V
		}
	}
	return c
}

func get_nolist_virtcol() colnr_T {
	if curwin.w_buffer == nil || curwin.w_buffer.b_ml.ml_root == nil || curwin.w_cursor.lnum > curwin.w_buffer.b_ml.ml_line_count {
		return 0
	}
	if curwin.w_onebuf_opt.wo_list != 0 && vim_strchr(p_cpo, CPO_LISTWM).Nil() {
		return getvcol_nolist(&curwin.w_cursor)
	}
	validate_virtcol()
	return curwin.w_virtcol
}

func do_ascii(eap *S_exarg) {
	var c int32
	var cval int32
	var buf1 Ptr[byte] = Mk[byte](20)
	var buf2 Ptr[byte] = Mk[byte](20)
	var buf3 Ptr[byte] = Mk[byte](7)
	var cc Ptr[int32] = Mk[int32](MAX_MCO)
	var ci int32 = 0
	var len_ int32

	c = utfc_ptr2char(ml_get_cursor(), cc)
	if c == NUL {
		msg(S("NUL"))
		return
	}

	IObuff.Set(0, NUL)
	if c < 0x80 {
		if c == NL {
			c = NUL
		}
		cval = c
		if vim_isprintc_strict(c) != 0 && (c < ' ' || c > '~') {
			transchar_nonprint(curbuf, buf3, c)
			vim_snprintf(buf1, 20, S("  <%s>"), buf3)
		} else {
			buf1.Set(0, NUL)
		}
		if c >= 0x80 {
			vim_snprintf(buf2, 20, S("  <M-%s>"), transchar(c&0x7f))
		} else {
			buf2.Set(0, NUL)
		}
		vim_snprintf(IObuff, 1024+1, gettext_(S("<%s>%s%s  %d,  Hex %02x,  Octal %03o")), transchar(c), buf1, buf2, cval, cval, cval)
		c = cc.At(int(ci))
		ci++
	}

	for c >= 0x100 || c >= 0x80 {
		len_ = int32(musl_strlen(IObuff))
		if len_ > 0 {
			IObuff.Set(int(len_), ' ')
			len_++
		}
		IObuff.Set(int(len_), '<')
		len_++
		if utf_iscomposing(c) != 0 {
			IObuff.Set(int(len_), ' ')
			len_++
		}
		len_ += utf_char2bytes(c, IObuff.Add(int(len_)))
		var f Ptr[byte]
		if c < 0x10000 {
			f = gettext_(S("> %d, Hex %04x, Octal %o"))
		} else {
			f = gettext_(S("> %d, Hex %08x, Octal %o"))
		}
		vim_snprintf(IObuff.Add(int(len_)), usize(1024+1-len_), f, c, c, c)
		if ci == MAX_MCO {
			break
		}
		c = cc.At(int(ci))
		ci++
	}

	msg(IObuff)
}

func do_move(line1 linenr_T, line2 linenr_T, dest linenr_T) int32 {
	var str Ptr[byte]
	var l linenr_T
	var extra linenr_T
	var num_lines linenr_T
	var last_line linenr_T

	if dest >= line1 && dest < line2 {
		emsg(gettext_(e_cannot_move_range_of_lines_into_itself))
		return FAIL
	}

	if dest == line1-1 || dest == line2 {
		if dest >= line1 {
			curwin.w_cursor.lnum = dest
		} else {
			curwin.w_cursor.lnum = dest + (line2 - line1) + 1
		}

		return OK
	}

	num_lines = line2 - line1 + 1

	if u_save(dest, dest+1) == FAIL {
		return FAIL
	}
	extra = 0
	for l = line1; l <= line2; l++ {
		{
			len := ml_get_len(l + extra)

			str = vim_strnsave(ml_get(l+extra), usize(len))
		}
		ml_append(dest+l-line1, str, 0)
		if dest < line1 {
			extra++
		}
	}

	last_line = curbuf.b_ml.ml_line_count
	mark_adjust_nofold(line1, line2, last_line-line2, 0)
	if dest >= line2 {
		mark_adjust_nofold(line2+1, dest, -num_lines, 0)
		if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
			curbuf.b_op_start.lnum = dest - num_lines + 1
			curbuf.b_op_end.lnum = dest
		}
	} else {
		mark_adjust_nofold(dest+1, line1-1, num_lines, 0)
		if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
			curbuf.b_op_start.lnum = dest + 1
			curbuf.b_op_end.lnum = dest + num_lines
		}
	}
	if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
		curbuf.b_op_end.col = 0
		curbuf.b_op_start.col = 0
	}
	mark_adjust_nofold(last_line-num_lines+1, last_line, -(last_line - dest - extra), 0)

	if u_save(line1+extra-1, line2+extra+1) == FAIL {
		return FAIL
	}

	for l = line1; l <= line2; l++ {
		ml_delete_flags(line1+extra, ML_DEL_MESSAGE)
	}

	if global_busy == 0 && num_lines > p_report {
		vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("%ld line moved"), S("%ld lines moved"), uint64(num_lines)), int64(num_lines))
		msg(iobuff_or(NGETTEXT(S("%ld line moved"), S("%ld lines moved"), uint64(num_lines))))
	}

	if dest >= line1 {
		curwin.w_cursor.lnum = dest
	} else {
		curwin.w_cursor.lnum = dest + (line2 - line1) + 1
	}

	if line1 < dest {
		dest += num_lines + 1
		last_line = curbuf.b_ml.ml_line_count
		if dest > last_line+1 {
			dest = last_line + 1
		}
		changed_lines(line1, 0, dest, 0)
	} else {
		changed_lines(dest+1, 0, line1+num_lines, 0)
	}

	return OK
}

func ex_copy(line1 linenr_T, line2 linenr_T, n linenr_T) {
	var count linenr_T
	var p Ptr[byte]

	count = line2 - line1 + 1
	if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
		curbuf.b_op_start.lnum = n + 1
		curbuf.b_op_end.lnum = n + count
		curbuf.b_op_end.col = 0
		curbuf.b_op_start.col = 0
	}

	if u_save(n, n+1) == FAIL {
		return
	}

	curwin.w_cursor.lnum = n
	for line1 <= line2 {
		{
			len := ml_get_len(line1)

			p = vim_strnsave(ml_get(line1), usize(len))
		}
		ml_append(curwin.w_cursor.lnum, p, 0)
		if line1 == n {
			line1 = curwin.w_cursor.lnum
		}
		line1++
		if curwin.w_cursor.lnum < line1 {
			line1++
		}
		if curwin.w_cursor.lnum < line2 {
			line2++
		}
		curwin.w_cursor.lnum++
	}

	appended_lines_mark(n, count)
	if VIsual_active != 0 {
		check_pos(curbuf, &VIsual)
	}

	msgmore(int64(count))
}

func do_fixdel(eap *S_exarg) {
	var p Ptr[byte]

	p = find_termcode(S("kb"))
	var s Ptr[byte]
	if !p.Nil() && p.Get() == DEL {
		s = S("\010")
	} else {
		s = S("\177")
	}
	add_termcode(S("kD"), s, FALSE)
}

func print_line_no_prefix(lnum linenr_T, use_number int32, list int32) {
	var numbuf Ptr[byte] = Mk[byte](30)

	if curwin.w_onebuf_opt.wo_nu != 0 || use_number != 0 {
		vim_snprintf(numbuf, 30, S("%*ld "), int32(7), int64(lnum))
		msg_puts_attr(numbuf, highlight_attr[HLF_N])
	}
	msg_prt_line(ml_get(lnum), list)
}

func print_line(lnum linenr_T, use_number int32, list int32) {

	if message_filtered(ml_get(lnum)) != 0 {
		return
	}

	msg_start()
	info_message = TRUE
	print_line_no_prefix(lnum, use_number, list)
	info_message = FALSE
}

func ex_append(eap *S_exarg) {
	var theline Ptr[byte]
	var did_undo int32 = FALSE
	var lnum linenr_T = eap.line2
	var indent int32 = 0
	var p Ptr[byte]
	var vcol int32
	var empty int32 = curbuf.b_ml.ml_flags & ML_EMPTY

	if eap.forceit != 0 {
		curbuf.b_p_ai = B2i(curbuf.b_p_ai == 0)
	}

	if eap.cmdidx != CMD_change && curbuf.b_p_ai != 0 && lnum > 0 {
		append_indent = get_indent_lnum(lnum)
	}

	if eap.cmdidx != CMD_append {
		lnum--
	}

	if empty != 0 && lnum == 1 {
		lnum = 0
	}

	State = MODE_INSERT
	for {
		msg_scroll = TRUE
		need_wait_return = FALSE
		if curbuf.b_p_ai != 0 {
			if append_indent >= 0 {
				indent = append_indent
				append_indent = -1
			} else if lnum > 0 {
				indent = get_indent_lnum(lnum)
			}
		}
		ex_keep_indent = FALSE
		if eap.ea_getline == nil {
			if eap.nextcmd.Nil() {
				break
			}
			p = vim_strchr(eap.nextcmd, NL)
			if p.Nil() {
				p = eap.nextcmd.Add(int(musl_strlen(eap.nextcmd)))
			}
			theline = vim_strnsave(eap.nextcmd, usize(p.Sub(eap.nextcmd)))
			if p.Get() != NUL {
				p = p.Add(1)
			} else {
				p = Ptr[byte]{}
			}
			eap.nextcmd = p
		} else {
			var save_State int32 = State

			State = MODE_CMDLINE
			theline = eap.ea_getline(NUL, eap.cookie, indent, GETLINE_CONCAT_CONT)
			State = save_State
		}
		lines_left = int32(Rows - 1)
		if theline.Nil() {
			break
		}

		if ex_keep_indent != 0 {
			append_indent = indent
		}

		vcol = 0
		for p = theline; indent > vcol; p = p.Add(1) {
			if p.Get() == ' ' {
				vcol++
			} else if p.Get() == TAB {
				vcol += 8 - vcol%8
			} else {
				break
			}
		}
		var e linenr_T
		if empty != 0 {
			e = 1
		} else {
			e = 0
		}
		if (p.At(0) == '.' && p.At(1) == NUL) || (did_undo == 0 && u_save(lnum, lnum+1+e) == FAIL) {
			break
		}

		if p.At(0) == NUL {
			theline.Set(0, NUL)
		}

		did_undo = TRUE
		ml_append(lnum, theline, 0)
		if empty != 0 {
			appended_lines(lnum, 1)
		} else {
			appended_lines_mark(lnum, 1)
		}

		lnum++

		if empty != 0 {
			ml_delete(2)
			empty = FALSE
		}
	}
	State = MODE_NORMAL

	if eap.forceit != 0 {
		curbuf.b_p_ai = B2i(curbuf.b_p_ai == 0)
	}

	if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
		if eap.line2 < curbuf.b_ml.ml_line_count {
			curbuf.b_op_start.lnum = eap.line2 + 1
		} else {
			curbuf.b_op_start.lnum = curbuf.b_ml.ml_line_count
		}
		if eap.cmdidx != CMD_append {
			curbuf.b_op_start.lnum--
		}
		if eap.line2 < lnum {
			curbuf.b_op_end.lnum = lnum
		} else {
			curbuf.b_op_end.lnum = curbuf.b_op_start.lnum
		}
		curbuf.b_op_end.col = 0
		curbuf.b_op_start.col = 0
	}
	curwin.w_cursor.lnum = lnum
	check_cursor_lnum()
	beginline(BL_SOL | BL_FIX)

	need_wait_return = FALSE
}

func ex_change(eap *S_exarg) {
	var lnum linenr_T

	if eap.line2 >= eap.line1 && u_save(eap.line1-1, eap.line2+1) == FAIL {
		return
	}

	var ai int32
	if eap.forceit != 0 {
		ai = B2i(curbuf.b_p_ai == 0)
	} else {
		ai = curbuf.b_p_ai
	}
	if ai != 0 {
		append_indent = get_indent_lnum(eap.line1)
	}

	for lnum = eap.line2; lnum >= eap.line1; lnum-- {
		if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
			break
		}
		ml_delete(eap.line1)
	}

	check_cursor_lnum()
	deleted_lines_mark(eap.line1, int64(eap.line2-lnum))

	eap.line2 = eap.line1
	ex_append(eap)
}

func ex_z(eap *S_exarg) {
	var x Ptr[byte]
	var bigness int64
	var kind Ptr[byte]
	var minus int32 = 0
	var start linenr_T
	var end linenr_T
	var curs linenr_T
	var i linenr_T
	var j int32
	var lnum linenr_T = eap.line2

	if eap.forceit != 0 {
		bigness = Rows - 1
	} else if TRUE == 0 {
		bigness = int64(curwin.w_height - 3)
	} else {
		bigness = curwin.w_onebuf_opt.wo_scr * 2
	}
	if bigness < 1 {
		bigness = 1
	}

	x = eap.arg
	kind = x
	if kind.Get() == '-' || kind.Get() == '+' || kind.Get() == '=' || kind.Get() == '^' || kind.Get() == '.' {
		x = x.Add(1)
	}
	for x.Get() == '-' || x.Get() == '+' {
		x = x.Add(1)
	}

	if x.Get() != 0 {
		if !(uint32(x.Get())-'0' < 10) {
			emsg(gettext_(e_non_numeric_argument_to_z))
			return
		} else {
			bigness = musl_atol(x)

			if bigness > 2*curbuf.b_ml.ml_line_count || bigness < 0 {
				bigness = 2 * curbuf.b_ml.ml_line_count
			}

			p_window = bigness
			if kind.Get() == '=' {
				bigness += 2
			}
		}
	}

	if kind.Get() == '-' || kind.Get() == '+' {
		for x = kind.Add(1); x.Get() == kind.Get(); x = x.Add(1) {
		}
	}

	switch kind.Get() {
	case '-':
		start = lnum - bigness*linenr_T(x.Sub(kind)) + 1
		end = start + bigness - 1
		curs = end

	case '=':
		start = lnum - (bigness+1)/2 + 1
		end = lnum + (bigness+1)/2 - 1
		curs = lnum
		minus = 1

	case '^':
		start = lnum - bigness*2
		end = lnum - bigness
		curs = lnum - bigness

	case '.':
		start = lnum - (bigness+1)/2 + 1
		end = lnum + (bigness+1)/2 - 1
		curs = end

	default:
		start = lnum
		if kind.Get() == '+' {
			start += bigness*linenr_T(x.Sub(kind)-1) + 1
		} else if eap.addr_count == 0 {
			start++
		}
		end = start + bigness - 1
		curs = end
	}

	if start < 1 {
		start = 1
	}

	if end > curbuf.b_ml.ml_line_count {
		end = curbuf.b_ml.ml_line_count
	}

	if curs > curbuf.b_ml.ml_line_count {
		curs = curbuf.b_ml.ml_line_count
	} else if curs < 1 {
		curs = 1
	}

	for i = start; i <= end; i++ {
		if minus != 0 && i == lnum {
			msg_putchar('\n')

			for j = 1; int64(j) < Columns; j++ {
				msg_putchar('-')
			}
		}

		print_line(i, eap.flags&EXFLAG_NR, eap.flags&EXFLAG_LIST)

		if minus != 0 && i == lnum {
			msg_putchar('\n')

			for j = 1; int64(j) < Columns; j++ {
				msg_putchar('-')
			}
		}
	}

	if curwin.w_cursor.lnum != curs {
		curwin.w_cursor.lnum = curs
		curwin.w_cursor.col = 0
	}
}

func skip_substitute(start Ptr[byte], delimiter int32) Ptr[byte] {
	var p Ptr[byte] = start

	for p.At(0) != 0 {
		if int32(p.At(0)) == delimiter {
			p.Put(NUL)
			p = p.Add(1)
			break
		}
		if p.At(0) == '\\' && p.At(1) != 0 {
			p = p.Add(1)
		}
		p = p.Add(int(utfc_ptr2len(p)))
	}
	return p
}

func check_regexp_delim(c int32) int32 {
	if musl_isalpha(int32(byte(c))) != 0 {
		emsg(gettext_(e_regular_expressions_cant_be_delimited_by_letters))
		return FAIL
	}
	return OK
}

func init() {
	ex_substitute_subflags = subflags_T{FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, 0}
}

func ex_substitute(eap *S_exarg) {
	var lnum linenr_T
	var i int64 = 0
	var regmatch regmmatch_T
	var subflags *subflags_T = &ex_substitute_subflags
	var save_do_all int32
	var save_do_ask int32
	var sub Ptr[byte] = Ptr[byte]{}
	var pat string_T = string_T{Ptr[byte]{}, 0}
	var delimiter int32
	var sublen usize
	var got_quit int32 = FALSE
	var got_match int32 = FALSE
	var which_pat int32
	var cmd Ptr[byte]
	var p Ptr[byte]
	var save_State int32
	var first_line linenr_T = 0
	var last_line linenr_T = 0
	var old_line_count linenr_T = curbuf.b_ml.ml_line_count
	var line2 linenr_T
	var nmatch int64
	var sub_firstline string_T
	var endcolumn int32 = FALSE
	var old_cursor pos_T = curwin.w_cursor
	var start_nsubs int32
	var keeppatterns int32 = cmdmod.cmod_flags & CMOD_KEEPPATTERNS

	cmd = eap.arg
	if global_busy == 0 {
		sub_nsubs = 0
		sub_nlines = 0
	}
	start_nsubs = int32(sub_nsubs)

	if eap.cmdidx == CMD_tilde {
		which_pat = RE_LAST
	} else {
		which_pat = RE_SUBST
	}

	if eap.cmd.At(0) == 's' && cmd.Get() != NUL && !(cmd.Get() == ' ' || cmd.Get() == '\t') && vim_strchr(S("0123456789cegriIp|\""), int32(cmd.Get())).Nil() {
		if check_regexp_delim(int32(cmd.Get())) == FAIL {
			return
		}

		if cmd.Get() == '\\' {
			cmd = cmd.Add(1)
			if vim_strchr(S("/?&"), int32(cmd.Get())).Nil() {
				emsg(gettext_(e_backslash_should_be_followed_by))
				return
			}
			if cmd.Get() != '&' {
				which_pat = RE_SEARCH
			}
			pat.string_ = S("")
			pat.length = 0
			delimiter = int32(cmd.Get())
			cmd = cmd.Add(1)
		} else {
			which_pat = RE_LAST
			delimiter = int32(cmd.Get())
			cmd = cmd.Add(1)
			pat.string_ = cmd
			cmd = skip_regexp_ex(cmd, delimiter, magic_isset(), &eap.arg, nil, nil)
			pat.length = usize(cmd.Sub(pat.string_))
			if int32(cmd.At(0)) == delimiter {
				cmd.Put(NUL)
				cmd = cmd.Add(1)
			}
		}

		p = cmd
		cmd = skip_substitute(cmd, delimiter)
		sub = vim_strsave(p)

		if musl_strcmp(sub, S("%")) == 0 && !vim_strchr(p_cpo, CPO_SUBPERCENT).Nil() {
			if old_sub.Nil() {
				emsg(gettext_(e_no_previous_substitute_regular_expression))
				return
			}
			sub = vim_strsave(old_sub)
		} else if keeppatterns == 0 {
			old_sub = vim_strsave(sub)
		}
	} else {
		if old_sub.Nil() {
			emsg(gettext_(e_no_previous_substitute_regular_expression))
			return
		}
		pat.string_ = Ptr[byte]{}
		pat.length = 0
		sub = vim_strsave(old_sub)

		endcolumn = B2i(curwin.w_curswant == MAXCOL)
	}

	if !pat.string_.Nil() && musl_strcmp(pat.string_, S("\\n")) == 0 && sub.Get() == NUL && (cmd.Get() == NUL || (cmd.At(1) == NUL && (cmd.Get() == 'g' || cmd.Get() == 'l' || cmd.Get() == 'p' || cmd.Get() == '#'))) {
		var joined_lines_count linenr_T

		curwin.w_cursor.lnum = eap.line1
		if cmd.Get() == 'l' {
			eap.flags = EXFLAG_LIST
		} else if cmd.Get() == '#' {
			eap.flags = EXFLAG_NR
		} else if cmd.Get() == 'p' {
			eap.flags = EXFLAG_PRINT
		}

		joined_lines_count = eap.line2 - eap.line1 + 1
		if eap.line2 < curbuf.b_ml.ml_line_count {
			joined_lines_count++
		}
		if joined_lines_count > 1 {
			do_join(joined_lines_count, FALSE, TRUE, FALSE, TRUE)
			sub_nsubs = joined_lines_count - 1
			sub_nlines = 1
			do_sub_msg(FALSE)
			ex_may_print(eap)
		}

		if keeppatterns == 0 {
			save_re_pat(RE_SUBST, pat.string_, pat.length, magic_isset())
		}
		add_to_history(HIST_SEARCH, pat.string_, pat.length, TRUE, NUL)

		return
	}

	if cmd.Get() == '&' {
		cmd = cmd.Add(1)
	} else {
		if p_ed == 0 {
			if p_gd != 0 {
				subflags.do_all = TRUE
			} else {
				subflags.do_all = FALSE
			}
			subflags.do_ask = FALSE
		}
		subflags.do_error = TRUE
		subflags.do_print = FALSE
		subflags.do_list = FALSE
		subflags.do_count = FALSE
		subflags.do_number = FALSE
		subflags.do_ic = 0
	}
	for cmd.Get() != 0 {
		if cmd.Get() == 'g' {
			subflags.do_all = B2i(subflags.do_all == 0)
		} else if cmd.Get() == 'c' {
			subflags.do_ask = B2i(subflags.do_ask == 0)
		} else if cmd.Get() == 'n' {
			subflags.do_count = TRUE
		} else if cmd.Get() == 'e' {
			subflags.do_error = B2i(subflags.do_error == 0)
		} else if cmd.Get() == 'r' {
			which_pat = RE_LAST
		} else if cmd.Get() == 'p' {
			subflags.do_print = TRUE
		} else if cmd.Get() == '#' {
			subflags.do_print = TRUE
			subflags.do_number = TRUE
		} else if cmd.Get() == 'l' {
			subflags.do_print = TRUE
			subflags.do_list = TRUE
		} else if cmd.Get() == 'i' {
			subflags.do_ic = 'i'
		} else if cmd.Get() == 'I' {
			subflags.do_ic = 'I'
		} else {
			break
		}
		cmd = cmd.Add(1)
	}
	if subflags.do_count != 0 {
		subflags.do_ask = FALSE
	}

	save_do_all = subflags.do_all
	save_do_ask = subflags.do_ask

	cmd = skipwhite(cmd)
	if uint32(cmd.Get())-'0' < 10 {
		i = getdigits(Addr(&cmd))
		if i <= 0 && subflags.do_error != 0 {
			emsg(gettext_(e_positive_count_required))
			return
		} else if i >= INT_MAX {
			var buf Ptr[byte] = Mk[byte](20)
			vim_snprintf(buf, 20, S("%ld"), i)
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_val_too_large), buf)
			emsg(iobuff_or(gettext_(e_val_too_large)))
			return
		}
		eap.line1 = eap.line2
		eap.line2 += i - 1
		if eap.line2 > curbuf.b_ml.ml_line_count {
			eap.line2 = curbuf.b_ml.ml_line_count
		}
	}

	cmd = skipwhite(cmd)
	if cmd.Get() != 0 {
		set_nextcmd(eap, cmd)
		if eap.nextcmd.Nil() {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_trailing_characters_str), cmd)
			emsg(iobuff_or(gettext_(e_trailing_characters_str)))
			return
		}
	}

	if subflags.do_count == 0 && curbuf.b_p_ma == 0 {
		emsg(gettext_(e_cannot_make_changes_modifiable_is_off))
		return
	}

	if search_regcomp(pat.string_, pat.length, nil, RE_SUBST, which_pat, SEARCH_HIS, &regmatch) == FAIL {
		if subflags.do_error != 0 {
			emsg(gettext_(e_invalid_command))
		}
		return
	}

	if subflags.do_ic == 'i' {
		regmatch.rmm_ic = TRUE
	} else if subflags.do_ic == 'I' {
		regmatch.rmm_ic = FALSE
	}

	sub_firstline.string_ = Ptr[byte]{}
	sub_firstline.length = 0

	if sub.At(0) == '\\' && sub.At(1) == '=' {
		p = vim_strsave(sub)
		sub = p
	} else {
		p = regtilde(sub, magic_isset())

		if p != sub {
			sub = p
		}
	}

	line2 = eap.line2
	for lnum = eap.line1; lnum <= line2 && got_quit == 0; lnum++ {
		nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, lnum, 0, nil)
		if nmatch != 0 {
			var copycol colnr_T
			var matchcol colnr_T
			var prev_matchcol colnr_T = MAXCOL
			var new_start string_T = string_T{Ptr[byte]{}, 0}
			var new_start_size usize = 0
			var new_end Ptr[byte]
			var did_sub int32 = FALSE
			var lastone int32
			var copy_len usize
			var needed_size usize
			var nmatch_tl int64 = 0
			var do_again int32
			var skip_match int32 = FALSE
			var sub_firstlnum linenr_T
			var did_split bool = false

			sub_firstlnum = lnum
			copycol = 0
			matchcol = 0

			if got_match == 0 {
				setpcmark()
				got_match = TRUE
			}

			for {
				var tmp string_T
				var p1 Ptr[byte]
				var n usize
				var mflag int32
				var cond bool

				if regmatch.startpos[0].lnum > 0 {
					lnum += regmatch.startpos[0].lnum
					sub_firstlnum += regmatch.startpos[0].lnum
					nmatch -= regmatch.startpos[0].lnum
					sub_firstline.string_ = Ptr[byte]{}
					sub_firstline.length = 0
				}

				if lnum > curbuf.b_ml.ml_line_count {
					break
				}

				if sub_firstline.string_.Nil() {
					sub_firstline.length = usize(ml_get_len(sub_firstlnum))
					sub_firstline.string_ = vim_strnsave(ml_get(sub_firstlnum), sub_firstline.length)
					if sub_firstline.string_.Nil() {
						goto outofmem
					}
				}

				curwin.w_cursor.lnum = lnum
				do_again = FALSE

				if matchcol == prev_matchcol && regmatch.endpos[0].lnum == 0 && matchcol == regmatch.endpos[0].col {
					if sub_firstline.string_.At(int(matchcol)) == NUL {
						skip_match = TRUE
					} else {
						matchcol += utfc_ptr2len(sub_firstline.string_.Add(int(matchcol)))
					}
					goto skip
				}

				matchcol = regmatch.endpos[0].col
				prev_matchcol = matchcol

				if subflags.do_count != 0 {
					if nmatch > 1 {
						matchcol = colnr_T(sub_firstline.length)
						nmatch = 1
						skip_match = TRUE
					}
					sub_nsubs++
					did_sub = TRUE
					goto skip
				}

				if subflags.do_ask != 0 {
					var typed int32 = 0

					save_State = State
					State = MODE_CONFIRM
					curwin.w_cursor.col = regmatch.startpos[0].col

					if !vim_strchr(p_cpo, CPO_UNDO).Nil() {
						no_u_sync++
					}

					for subflags.do_ask != 0 {
						var orig_line string_T = string_T{Ptr[byte]{}, 0}
						var len_change int32 = 0
						var save_p_lz int32 = p_lz
						var save_RedrawingDisabled int32 = RedrawingDisabled
						RedrawingDisabled = 0

						p_lz = FALSE

						if !new_start.string_.Nil() {
							orig_line.length = usize(ml_get_len(lnum))
							orig_line.string_ = vim_strnsave(ml_get(lnum), orig_line.length)
							var new_line string_T

							new_line.string_ = concat_str(new_start.string_, sub_firstline.string_.Add(int(copycol)))
							if new_line.string_.Nil() {
								orig_line.string_ = Ptr[byte]{}
								orig_line.length = 0
							} else {
								new_line.length = new_start.length + (sub_firstline.length - usize(copycol))
								len_change = int32(new_line.length) - int32(orig_line.length)
								curwin.w_cursor.col += len_change
								ml_replace(lnum, new_line.string_, FALSE)
							}
						}

						search_match_lines = regmatch.endpos[0].lnum - regmatch.startpos[0].lnum
						search_match_endcol = regmatch.endpos[0].col + len_change
						if search_match_lines == 0 && search_match_endcol == 0 {
							search_match_endcol = 1
						}
						highlight_match = TRUE

						update_topline()
						validate_cursor()
						update_screen(UPD_SOME_VALID)
						highlight_match = FALSE
						redraw_later(UPD_SOME_VALID)

						if int64(msg_row) == Rows-1 {
							msg_didout = FALSE
						}
						msg_starthere()
						i = int64(msg_scroll)
						msg_scroll = 0
						msg_no_more = TRUE
						vim_snprintf(IObuff, iobuff_room(), gettext_(S("replace with %s (y/n/a/q/l/^E/^Y)?")), sub)
						msg_attr(iobuff_or(gettext_(S("replace with %s (y/n/a/q/l/^E/^Y)?"))), highlight_attr[HLF_R])
						msg_no_more = FALSE
						msg_scroll = int32(i)
						showruler(TRUE)
						windgoto(msg_row, cmdline_col_off+msg_col)
						RedrawingDisabled = save_RedrawingDisabled

						no_mapping++
						allow_keys++
						typed = plain_vgetc()
						allow_keys--
						no_mapping--

						msg_didout = FALSE
						msg_col = 0
						gotocmdline(TRUE)
						p_lz = save_p_lz

						if !orig_line.string_.Nil() {
							ml_replace(lnum, orig_line.string_, FALSE)
						}

						need_wait_return = FALSE
						if typed == 'q' || typed == ESC || typed == Ctrl_C || typed == intr_char {
							got_quit = TRUE
							break
						}
						if typed == 'n' {
							break
						}
						if typed == 'y' {
							break
						}
						if typed == 'l' {
							subflags.do_all = FALSE
							line2 = lnum
							break
						}
						if typed == 'a' {
							subflags.do_ask = FALSE
							break
						}
						if typed == Ctrl_E {
							scrollup_clamp()
						} else if typed == Ctrl_Y {
							scrolldown_clamp()
						}
					}
					State = save_State
					if !vim_strchr(p_cpo, CPO_UNDO).Nil() {
						no_u_sync--
					}

					if typed == 'n' {
						if nmatch > 1 {
							matchcol = colnr_T(sub_firstline.length)
							skip_match = TRUE
						}
						goto skip
					}
					if got_quit != 0 {
						goto skip
					}
				}

				curwin.w_cursor.col = regmatch.startpos[0].col

				if magic_isset() != 0 {
					mflag = REGSUB_MAGIC
				} else {
					mflag = 0
				}
				sublen = usize(vim_regsub_multi(&regmatch, sub_firstlnum-regmatch.startpos[0].lnum, sub, sub_firstline.string_, 0, REGSUB_BACKSLASH|mflag))

				if nmatch > curbuf.b_ml.ml_line_count-sub_firstlnum+1 {
					nmatch = curbuf.b_ml.ml_line_count - sub_firstlnum + 1
					skip_match = TRUE
					if nmatch < 0 {
						goto skip
					}
				}

				if nmatch == 1 {
					tmp.string_ = sub_firstline.string_
					tmp.length = sub_firstline.length
				} else {
					var lastlnum linenr_T = sub_firstlnum + nmatch - 1
					tmp.string_ = ml_get(lastlnum)
					tmp.length = usize(ml_get_len(lastlnum))
					nmatch_tl += nmatch - 1
				}

				copy_len = usize(regmatch.startpos[0].col - copycol)
				needed_size = copy_len + (tmp.length - usize(regmatch.endpos[0].col)) + sublen + 1

				if new_start.string_.Nil() {
					new_start_size = needed_size + 50
					new_start.string_ = Alloc(int(new_start_size))
					new_start.string_.Put(NUL)
					new_start.length = 0
				} else {
					needed_size += new_start.length
					if needed_size > new_start_size {
						new_start_size = needed_size + 50
						p1 = Alloc(int(new_start_size))
						Memmove(p1, new_start.string_, int(new_start.length+1))
						new_start.string_ = p1
					}
				}

				Memmove(new_start.string_.Add(int(new_start.length)), sub_firstline.string_.Add(int(copycol)), int(copy_len))
				new_start.length += copy_len

				new_end = new_start.string_.Add(int(new_start.length))

				if new_start_size-copy_len < sublen {
					sublen = new_start_size - copy_len - 1
				}

				if magic_isset() != 0 {
					mflag = REGSUB_MAGIC
				} else {
					mflag = 0
				}
				n = usize(vim_regsub_multi(&regmatch, sub_firstlnum-regmatch.startpos[0].lnum, sub, new_end, int32(sublen), REGSUB_COPY|REGSUB_BACKSLASH|mflag))

				if n > 0 {
					new_start.length += n - 1
				}

				sub_nsubs++
				did_sub = TRUE

				curwin.w_cursor.col = 0

				if nmatch > 1 {
					sub_firstlnum += nmatch - 1
					sub_firstline.length = usize(ml_get_len(sub_firstlnum))
					sub_firstline.string_ = vim_strnsave(ml_get(sub_firstlnum), sub_firstline.length)
					if sub_firstline.string_.Nil() {
						goto outofmem
					}
					if sub_firstlnum <= line2 {
						do_again = TRUE
					} else {
						subflags.do_all = FALSE
					}
				}

				copycol = regmatch.endpos[0].col

				if skip_match != 0 {
					sub_firstline.string_ = vim_strnsave(S(""), 0)
					sub_firstline.length = 0
					copycol = 0
				}

				for p1 = new_end; p1.Get() != 0; p1 = p1.Add(1) {
					if p1.At(0) == '\\' && p1.At(1) != NUL {
						n = new_start.length - usize(p1.Sub(new_start.string_))
						Memmove(p1, p1.Add(1), int(n+1))
						new_start.length--
					} else if p1.Get() == CAR {
						if u_inssub(lnum) == OK {
							var plen colnr_T = colnr_T(p1.Sub(new_start.string_) + 1)

							p1.Put(NUL)
							ml_append(lnum-1, new_start.string_, plen)
							mark_adjust(lnum+1, linenr_T(LONG_MAX), 1, 0)
							if subflags.do_ask != 0 {
								appended_lines(lnum-1, 1)
							} else {
								if first_line == 0 {
									first_line = lnum
								}
								last_line = lnum + 1
							}
							sub_firstlnum++
							lnum++
							line2++
							did_split = true
							curwin.w_cursor.lnum++
							n = new_start.length - usize(plen)
							Memmove(new_start.string_, p1.Add(1), int(n+1))
							new_start.length = n
							p1 = new_start.string_.Add(-1)
						}
					} else {
						p1 = p1.Add(int(utfc_ptr2len(p1) - 1))
					}
				}

			skip:
				lastone = B2i(skip_match != 0 || got_int != 0 || got_quit != 0 || lnum > line2 || !(subflags.do_all != 0 || do_again != 0) || (sub_firstline.string_.At(int(matchcol)) == NUL && nmatch <= 1 && re_multiline(regmatch.regprog) == 0))
				nmatch = -1

				cond = lastone != 0 || nmatch_tl > 0 || (subflags.do_ask != 0 && did_split)
				if !cond {
					nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, sub_firstlnum, matchcol, nil)
					cond = nmatch == 0 || regmatch.startpos[0].lnum > 0
				}
				if cond {
					if !new_start.string_.Nil() {
						musl_strcpy(new_start.string_.Add(int(new_start.length)), sub_firstline.string_.Add(int(copycol)))
						new_start.length += sub_firstline.length - usize(copycol)
						matchcol = colnr_T(sub_firstline.length - usize(matchcol))
						prev_matchcol = colnr_T(sub_firstline.length - usize(prev_matchcol))

						if u_savesub(lnum) != OK {
							break
						}
						ml_replace(lnum, new_start.string_, TRUE)
						if nmatch_tl > 0 {
							lnum++
							if u_savedel(lnum, nmatch_tl) != OK {
								break
							}
							for i = 0; i < nmatch_tl; i++ {
								ml_delete(lnum)
							}
							if copycol > 0 {
								mark_adjust(lnum, lnum+nmatch_tl-1, LONG_MAX, -nmatch_tl)
							} else {
								mark_adjust(lnum-1, lnum-1, LONG_MAX, -nmatch_tl)
							}
							if subflags.do_ask != 0 {
								deleted_lines(lnum, nmatch_tl)
							}
							lnum--
							line2 -= nmatch_tl
							nmatch_tl = 0
						}

						if subflags.do_ask != 0 {
							changed_bytes(lnum, 0)
						} else {
							if first_line == 0 {
								first_line = lnum
							}
							last_line = lnum + 1
						}

						sub_firstlnum = lnum
						sub_firstline.string_ = new_start.string_
						sub_firstline.length = new_start.length
						new_start.string_ = Ptr[byte]{}
						new_start.length = 0
						matchcol = colnr_T(sub_firstline.length - usize(matchcol))
						prev_matchcol = colnr_T(sub_firstline.length - usize(prev_matchcol))
						copycol = 0
						did_split = false
					}
					if nmatch == -1 && lastone == 0 {
						nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, sub_firstlnum, matchcol, nil)
					}

					if nmatch <= 0 {
						if nmatch == -1 {
							lnum -= regmatch.startpos[0].lnum
						}
						break
					}
				}

				line_breakcheck()
			}

			if did_sub != 0 {
				sub_nlines++
			}
			sub_firstline.string_ = Ptr[byte]{}
			sub_firstline.length = 0
		}

		line_breakcheck()
	}

	if first_line != 0 {
		i = curbuf.b_ml.ml_line_count - old_line_count
		changed_lines(first_line, 0, last_line-i, i)
	}

outofmem:

	if subflags.do_count != 0 {
		curwin.w_cursor = old_cursor
	}

	if sub_nsubs > int64(start_nsubs) {
		if cmdmod.cmod_flags&CMOD_LOCKMARKS == 0 {
			curbuf.b_op_start.lnum = eap.line1
			curbuf.b_op_end.lnum = line2
			curbuf.b_op_end.col = 0
			curbuf.b_op_start.col = 0
		}

		if global_busy == 0 {
			if subflags.do_ask == 0 {
				if endcolumn != 0 {
					coladvance(colnr_T(MAXCOL))
				} else {
					beginline(BL_WHITE | BL_FIX)
				}
			}
			if do_sub_msg(subflags.do_count) == 0 && subflags.do_ask != 0 {
				msg(S(""))
			}
		} else {
			global_need_beginline = TRUE
		}
		if subflags.do_print != 0 {
			print_line(curwin.w_cursor.lnum, subflags.do_number, subflags.do_list)
		}
	} else if global_busy == 0 {
		if got_int != 0 {
			emsg(gettext_(e_interrupted))
		} else if got_match != 0 {
			msg(S(""))
		} else if subflags.do_error != 0 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_pattern_not_found_str), get_search_pat())
			emsg(iobuff_or(gettext_(e_pattern_not_found_str)))
		}
	}

	vim_regfree(regmatch.regprog)

	subflags.do_all = save_do_all
	subflags.do_ask = save_do_ask
}

func do_sub_msg(count_only int32) int32 {
	if ((sub_nsubs > p_report && (KeyTyped != 0 || sub_nlines > 1 || p_report < 1)) || count_only != 0) && messaging() != 0 {
		var msg_single Ptr[byte]
		var msg_plural Ptr[byte]

		if got_int != 0 {
			musl_strcpy(msg_buf, gettext_(S("(Interrupted) ")))
		} else {
			msg_buf.Put(NUL)
		}

		if count_only != 0 {
			msg_single = NGETTEXT(S("%ld match on %ld line"), S("%ld matches on %ld line"), uint64(sub_nsubs))
		} else {
			msg_single = NGETTEXT(S("%ld substitution on %ld line"), S("%ld substitutions on %ld line"), uint64(sub_nsubs))
		}
		if count_only != 0 {
			msg_plural = NGETTEXT(S("%ld match on %ld lines"), S("%ld matches on %ld lines"), uint64(sub_nsubs))
		} else {
			msg_plural = NGETTEXT(S("%ld substitution on %ld lines"), S("%ld substitutions on %ld lines"), uint64(sub_nsubs))
		}

		vim_snprintf(msg_buf.Add(int(musl_strlen(msg_buf))), append_room(msg_buf, 480), NGETTEXT(msg_single, msg_plural, uint64(sub_nlines)), sub_nsubs, int64(sub_nlines))

		if msg(msg_buf) != 0 {
			set_keep_msg(msg_buf, 0)
		}
		return TRUE
	}
	if got_int != 0 {
		emsg(gettext_(e_interrupted))
		return TRUE
	}
	return FALSE
}

func global_exe_one(cmd Ptr[byte], lnum linenr_T) {
	curwin.w_cursor.lnum = lnum
	curwin.w_cursor.col = 0
	if cmd.Get() == NUL || cmd.Get() == '\n' {
		do_cmdline(S("p"), nil, nil, DOCMD_NOWAIT)
	} else {
		do_cmdline(cmd, nil, nil, DOCMD_NOWAIT)
	}
}

func ex_global(eap *S_exarg) {
	var lnum linenr_T
	var ndone int32 = 0
	var type_ int32
	var cmd Ptr[byte]

	var delim byte
	var pat Ptr[byte]
	var patlen usize
	var used_pat Ptr[byte]
	var regmatch regmmatch_T
	var match int32
	var which_pat int32

	if global_busy != 0 && (eap.line1 != 1 || eap.line2 != curbuf.b_ml.ml_line_count) {
		emsg(gettext_(e_cannot_do_global_recursive_with_range))
		return
	}

	if eap.forceit != 0 {
		type_ = 'v'
	} else {
		type_ = int32(eap.cmd.Get())
	}
	cmd = eap.arg
	which_pat = RE_LAST

	if cmd.Get() == '\\' {
		cmd = cmd.Add(1)
		if vim_strchr(S("/?&"), int32(cmd.Get())).Nil() {
			emsg(gettext_(e_backslash_should_be_followed_by))
			return
		}
		if cmd.Get() == '&' {
			which_pat = RE_SUBST
		} else {
			which_pat = RE_SEARCH
		}
		cmd = cmd.Add(1)
		pat = S("")
		patlen = 0
	} else if cmd.Get() == NUL {
		emsg(gettext_(e_regular_expression_missing_from_global))
		return
	} else if check_regexp_delim(int32(cmd.Get())) == FAIL {
		return
	} else {
		delim = cmd.Get()
		cmd = cmd.Add(1)
		pat = cmd
		cmd = skip_regexp_ex(cmd, int32(delim), magic_isset(), &eap.arg, nil, nil)
		if cmd.At(0) == delim {
			cmd.Put(NUL)
			cmd = cmd.Add(1)
		}
		patlen = musl_strlen(pat)
	}

	if search_regcomp(pat, patlen, &used_pat, RE_BOTH, which_pat, SEARCH_HIS, &regmatch) == FAIL {
		emsg(gettext_(e_invalid_command))
		return
	}

	if global_busy != 0 {
		lnum = curwin.w_cursor.lnum
		match = int32(vim_regexec_multi(&regmatch, curwin, curbuf, lnum, 0, nil))
		if (type_ == 'g' && match != 0) || (type_ == 'v' && match == 0) {
			global_exe_one(cmd, lnum)
		}
	} else {
		for lnum = eap.line1; lnum <= eap.line2 && got_int == 0; lnum++ {
			match = int32(vim_regexec_multi(&regmatch, curwin, curbuf, lnum, 0, nil))
			if regmatch.regprog == nil {
				break
			}
			if (type_ == 'g' && match != 0) || (type_ == 'v' && match == 0) {
				ml_setmarked(lnum)
				ndone++
			}
			line_breakcheck()
		}

		if got_int != 0 {
			msg(gettext_(e_interrupted))
		} else if ndone == 0 {
			if type_ == 'v' {
				vim_snprintf(IObuff, iobuff_room(), gettext_(S("Pattern found in every line: %s")), used_pat)
				msg(iobuff_or(gettext_(S("Pattern found in every line: %s"))))
			} else {
				vim_snprintf(IObuff, iobuff_room(), gettext_(S("Pattern not found: %s")), used_pat)
				msg(iobuff_or(gettext_(S("Pattern not found: %s"))))
			}
		} else {
			global_exe(cmd)
		}

		ml_clearmarked()
	}

	vim_regfree(regmatch.regprog)
}

func global_exe(cmd Ptr[byte]) {
	var old_lcount linenr_T
	var old_buf *S_file_buffer = curbuf
	var lnum linenr_T

	setpcmark()

	msg_didout = TRUE

	sub_nsubs = 0
	sub_nlines = 0
	global_need_beginline = FALSE
	global_busy = 1
	old_lcount = curbuf.b_ml.ml_line_count
	for {
		if got_int != 0 {
			break
		}
		lnum = ml_firstmarked()
		if !(lnum != 0 && global_busy == 1) {
			break
		}
		global_exe_one(cmd, lnum)
		ui_breakcheck()
	}

	global_busy = 0
	if global_need_beginline != 0 {
		beginline(BL_WHITE | BL_FIX)
	} else {
		check_cursor()
	}

	changed_line_abv_curs()

	if msg_col == 0 && msg_scrolled == 0 {
		msg_didout = FALSE
	}

	if do_sub_msg(FALSE) == 0 && curbuf == old_buf {
		msgmore(curbuf.b_ml.ml_line_count - old_lcount)
	}
}

func skip_vimgrep_pat(p Ptr[byte], s *Ptr[byte], flags *int32) Ptr[byte] {
	return skip_vimgrep_pat_ext(p, s, flags, nil, nil)
}

func skip_vimgrep_pat_ext(p Ptr[byte], s *Ptr[byte], flags *int32, nulp *Ptr[byte], cp *int32) Ptr[byte] {
	var c int32

	if vim_isIDc(int32(p.Get())) != 0 {
		if s != nil {
			*s = p
		}
		p = skiptowhite(p)
		if s != nil && p.Get() != NUL {
			if nulp != nil {
				*nulp = p
				*cp = int32(p.Get())
			}
			p.Put(NUL)
			p = p.Add(1)
		}
	} else {
		if s != nil {
			*s = p.Add(1)
		}
		c = int32(p.Get())
		p = skip_regexp(p.Add(1), c, TRUE)
		if int32(p.Get()) != c {
			return Ptr[byte]{}
		}

		if s != nil {
			if nulp != nil {
				*nulp = p
				*cp = int32(p.Get())
			}
			p.Put(NUL)
		}
		p = p.Add(1)

		for p.Get() == 'g' || p.Get() == 'j' || p.Get() == 'f' {
			if flags != nil {
				if p.Get() == 'g' {
					*flags |= VGR_GLOBAL
				} else if p.Get() == 'j' {
					*flags |= VGR_NOJUMP
				} else {
					*flags |= VGR_FUZZY
				}
			}
			p = p.Add(1)
		}
	}
	return p
}

func check_fname() int32 {
	emsg(gettext_(e_no_file_name))
	return FAIL
}

func msg_verbose_cmd(lnum linenr_T, cmd Ptr[byte]) {
	no_wait_return++
	verbose_enter_scroll()

	if lnum == 0 {
		vim_snprintf(IObuff, iobuff_room(), gettext_(S("Executing: %s")), cmd)
		msg(iobuff_or(gettext_(S("Executing: %s"))))
	} else {
		vim_snprintf(IObuff, iobuff_room(), gettext_(S("line %ld: %s")), int64(lnum), cmd)
		msg(iobuff_or(gettext_(S("line %ld: %s"))))
	}
	if msg_silent == 0 {
		msg_puts(S("\n"))
	}

	verbose_leave_scroll()
	no_wait_return--
}

func do_cmdline_cmd(cmd Ptr[byte]) int32 {
	return do_cmdline(cmd, nil, nil, DOCMD_VERBOSE|DOCMD_NOWAIT|DOCMD_KEYTYPED)
}

// ==== from f04.go ====
// Transpiled by hand from editor.c: do_cmdline .. alloc_cmdbuff.

func init() {
	do_cmdline_recursive = 0
	do_cmdline_call_depth = 0
}

func do_cmdline(cmdline Ptr[byte], fgetline func(int32, any, int32, getline_opt_T) Ptr[byte], cookie any, flags int32) int32 {
	var next_cmdline Ptr[byte]
	var cmdline_copy Ptr[byte]
	var used_getline int32 = FALSE
	var msg_didout_before_start int32 = 0
	var count int32 = 0
	var did_inc_RedrawingDisabled int32 = FALSE
	var retval int32 = OK

	if do_cmdline_call_depth >= 200 {
		emsg(gettext_(e_command_too_recursive))
		return FAIL
	}
	do_cmdline_call_depth++

	did_emsg = FALSE

	if !(flags&DOCMD_KEYTYPED != 0) && getline_equal(fgetline, cookie, getexline) == 0 {
		KeyTyped = FALSE
	}

	next_cmdline = cmdline
	for {
		if next_cmdline.Nil() {
			did_emsg = FALSE
		}

		if next_cmdline.Nil() {
			if count == 1 && getline_equal(fgetline, cookie, getexline) != 0 {
				msg_didout = TRUE
			}
			fail := fgetline == nil
			if !fail {
				next_cmdline = fgetline(':', cookie, 0, GETLINE_CONCAT_CONT)
				fail = next_cmdline.Nil()
			}
			if fail {
				if KeyTyped != 0 && !(flags&DOCMD_REPEAT != 0) {
					need_wait_return = FALSE
				}
				retval = FAIL
				break
			}
			used_getline = TRUE

			if flags&DOCMD_KEEPLINE != 0 {
				if count == 0 {
					repeat_cmdline = vim_strsave(next_cmdline)
				} else {
					repeat_cmdline = Ptr[byte]{}
				}
			}
		} else if cmdline_copy.Nil() {
			next_cmdline = vim_strsave(next_cmdline)
		}
		cmdline_copy = next_cmdline

		c0 := count
		count++
		if c0 == 0 {
			if !(flags&DOCMD_NOWAIT != 0) && do_cmdline_recursive == 0 {
				msg_didout_before_start = msg_didout
				msg_didany = FALSE
				msg_start()
				msg_scroll = TRUE
				no_wait_return++
				RedrawingDisabled++
				did_inc_RedrawingDisabled = TRUE
			}
		}

		if (p_verbose >= 15 && !GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name.Nil()) || p_verbose >= 16 {
			msg_verbose_cmd(GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_lnum, cmdline_copy)
		}

		do_cmdline_recursive++
		next_cmdline = do_one_cmd(&cmdline_copy, flags, fgetline, cookie)
		do_cmdline_recursive--

		if next_cmdline.Nil() {
			cmdline_copy = Ptr[byte]{}

			if getline_equal(fgetline, cookie, getexline) != 0 && !new_last_cmdline.Nil() {
				last_cmdline = new_last_cmdline
				new_last_cmdline = Ptr[byte]{}
			}
		} else {
			Memmove(cmdline_copy, next_cmdline, int(musl_strlen(next_cmdline)+1))
			next_cmdline = cmdline_copy
		}

		if !(got_int == 0 && !(did_emsg != 0 && used_getline != 0 && getline_equal(fgetline, cookie, getexline) != 0) && (!next_cmdline.Nil() || flags&DOCMD_REPEAT != 0)) {
			break
		}
	}

	if did_inc_RedrawingDisabled != 0 {
		if RedrawingDisabled > 0 {
			RedrawingDisabled--
		}
		no_wait_return--
		msg_scroll = FALSE

		if retval == FAIL {
			need_wait_return = FALSE
			msg_didany = FALSE
		} else if need_wait_return != 0 {
			msg_didout |= msg_didout_before_start
			wait_return(FALSE)
		}
	}

	do_cmdline_call_depth--
	return retval
}

// Go cannot compare two func values with ==; the code pointers are compared.
func getline_equal(fgetline func(int32, any, int32, getline_opt_T) Ptr[byte], cookie any, func_ func(int32, any, int32, getline_opt_T) Ptr[byte]) int32 {
	if fgetline == nil || func_ == nil {
		return B2i(fgetline == nil && func_ == nil)
	}
	return B2i(reflect.ValueOf(fgetline).Pointer() == reflect.ValueOf(func_).Pointer())
}

func do_one_cmd(cmdlinep *Ptr[byte], flags int32, fgetline func(int32, any, int32, getline_opt_T) Ptr[byte], cookie any) Ptr[byte] {
	var p Ptr[byte]
	var lnum linenr_T
	var n int64
	var errormsg Ptr[byte]
	var after_modifier Ptr[byte]
	var ea exarg_T
	var save_cmdmod cmdmod_T
	var save_reg_executing int32 = reg_executing
	var save_pending_end_reg_executing int32 = pending_end_reg_executing
	var cmd Ptr[byte]
	var sourcing int32 = flags & DOCMD_VERBOSE
	var did_append_cmd int32 = FALSE

	ea = exarg_T{}
	ea.line1 = 1
	ea.line2 = 1

	if quitmore != 0 {
		quitmore--
	}

	save_cmdmod = cmdmod

	if (*cmdlinep).At(0) == '#' && (*cmdlinep).At(1) == '!' {
		goto doend
	}

	ea.cmd = *cmdlinep
	ea.cmdlinep = cmdlinep
	ea.ea_getline = fgetline
	ea.cookie = cookie
	if parse_command_modifiers(&ea, &errormsg, &cmdmod, FALSE) == FAIL {
		goto doend
	}
	apply_cmdmod(&cmdmod)
	after_modifier = ea.cmd

	cmd = ea.cmd

	ea.cmd = skip_range(ea.cmd, TRUE, nil)

	p = find_ex_command(&ea, nil)

	ea.cmd = cmd

	if ea.cmdidx != CMD_SIZE {
		ea.addr_type = cmdnames[int(ea.cmdidx)].cmd_addr_type
	} else {
		ea.addr_type = ADDR_LINES
	}

	if parse_cmd_address(&ea, &errormsg, FALSE) == FAIL {
		goto doend
	}

	ea.cmd = skipwhite(ea.cmd)
	for ea.cmd.Get() == ':' {
		ea.cmd = skipwhite(ea.cmd.Add(1))
	}

	if ea.cmd.Get() == NUL {
		errormsg = ex_range_without_command(&ea)
		goto doend
	}
	ea.nextcmd = check_nextcmd(ea.cmd)
	if !ea.nextcmd.Nil() {
		errormsg = ex_range_without_command(&ea)
		goto doend
	}

	if p.Nil() {
		errormsg = gettext_(e_ambiguous_use_of_user_defined_command)
		goto doend
	}
	if p.Get() == '!' && ea.cmd.At(1) == 0o151 && ea.cmd.At(0) == 78 {
		errormsg = uc_fun_cmd()
		goto doend
	}

	if ea.cmdidx == CMD_SIZE {
		musl_strcpy(IObuff, gettext_(e_not_an_editor_command))
		if sourcing == 0 {
			if !after_modifier.Nil() {
				append_command(after_modifier)
			} else {
				append_command(*cmdlinep)
			}
			did_append_cmd = TRUE
		}
		errormsg = IObuff
		goto doend
	}

	if p.Get() == '!' && ea.cmdidx != CMD_substitute && ea.cmdidx != CMD_smagic && ea.cmdidx != CMD_snomagic {
		p = p.Add(1)
		ea.forceit = TRUE
	} else {
		ea.forceit = FALSE
	}

	ea.argt = int64(cmdnames[int(ea.cmdidx)].cmd_argt)

	if curbuf.b_p_ma == 0 && ea.argt&EX_MODIFY != 0 {
		errormsg = gettext_(e_cannot_make_changes_modifiable_is_off)
		goto doend
	}

	if text_locked() != 0 && !(ea.argt&EX_LOCK_OK != 0) {
		errormsg = gettext_(get_text_locked_msg())
		goto doend
	}

	if !(ea.argt&(EX_CMDWIN|EX_LOCK_OK) != 0) && curbuf_locked() != 0 {
		goto doend
	}

	if !(ea.argt&EX_RANGE != 0) && ea.addr_count > 0 {
		errormsg = gettext_(e_no_range_allowed)
		goto doend
	}

	if !(ea.argt&EX_BANG != 0) && ea.forceit != 0 {
		errormsg = gettext_(e_no_bang_allowed)
		goto doend
	}

	if ea.argt&EX_RANGE != 0 {
		if global_busy == 0 && ea.line1 > ea.line2 {
			if msg_silent == 0 {
				if sourcing != 0 {
					errormsg = gettext_(e_backwards_range_given)
					goto doend
				}
				if ask_yesno(gettext_(S("Backwards range given, OK to swap")), FALSE) != 'y' {
					goto doend
				}
			}
			lnum = ea.line1
			ea.line1 = ea.line2
			ea.line2 = lnum
		}
		errormsg = invalid_range(&ea)
		if !errormsg.Nil() {
			goto doend
		}
	}

	if (ea.addr_type == ADDR_OTHER) && ea.addr_count == 0 {
		ea.line2 = 1
	}

	correct_range(&ea)

	ea.arg = skipwhite(p)

	if ea.cmdidx == CMD_lshift || ea.cmdidx == CMD_rshift {
		ea.amount = 1
		for ea.arg.Get() == ea.cmd.Get() {
			ea.arg = ea.arg.Add(1)
			ea.amount++
		}
		ea.arg = skipwhite(ea.arg)
	}

	if ea.argt&EX_CMDARG != 0 {
		ea.do_ecmd_cmd = getargcmd(&ea.arg)
	}

	if ea.argt&EX_TRLBAR != 0 {
		separate_nextcmd(&ea, FALSE)
	} else if ea.cmdidx == CMD_global || ea.cmdidx == CMD_vglobal {
		for p = ea.arg; p.Get() != 0; p = p.Add(1) {
			if p.Get() == '\\' && p.At(1) == '\n' {
				Memmove(p, p.Add(1), int(musl_strlen(p.Add(1))+1))
			} else if p.Get() == '\n' {
				ea.nextcmd = p.Add(1)
				p.Put(NUL)
				break
			}
		}
	}

	if (ea.argt&EX_DFLALL != 0) && ea.addr_count == 0 {
		address_default_all(&ea)
	}

	if (ea.argt&EX_REGSTR != 0) && ea.arg.Get() != NUL && !((ea.argt&EX_COUNT != 0) && (uint32(ea.arg.Get())-'0' < 10)) {
		if ea.arg.Get() == '*' || ea.arg.Get() == '+' {
			errormsg = gettext_(e_invalid_register_name)
			goto doend
		}
		if valid_yank_reg(int32(ea.arg.Get()), B2i(ea.cmdidx != CMD_put && ea.cmdidx != CMD_iput)) != 0 {
			ea.regname = int32(ea.arg.Get())
			ea.arg = ea.arg.Add(1)
			ea.arg = skipwhite(ea.arg)
		}
	}

	if (ea.argt&EX_COUNT != 0) && (uint32(ea.arg.Get())-'0' < 10) {
		n = getdigits_quoted(&ea.arg)
		ea.arg = skipwhite(ea.arg)
		if n <= 0 && (ea.argt&EX_ZEROR) == 0 {
			errormsg = gettext_(e_positive_count_required)
			goto doend
		}
		if ea.addr_type != ADDR_LINES {
			ea.line2 = n
			if ea.addr_count == 0 {
				ea.addr_count = 1
			}
		} else {
			ea.line1 = ea.line2
			if ea.line2 >= LONG_MAX-(n-1) {
				ea.line2 = LONG_MAX
			} else {
				ea.line2 += n - 1
			}
			ea.addr_count++
			if ea.line2 > curbuf.b_ml.ml_line_count {
				ea.line2 = curbuf.b_ml.ml_line_count
			}
		}
	}

	if ea.argt&EX_FLAGS != 0 {
		get_flags(&ea)
	}
	if !(ea.argt&EX_EXTRA != 0) && ea.arg.Get() != NUL {
		errormsg = ex_errmsg(e_trailing_characters_str, ea.arg)
		goto doend
	}

	if (ea.argt&EX_NEEDARG != 0) && ea.arg.Get() == NUL {
		errormsg = gettext_(e_argument_required)
		goto doend
	}

	cmdnames[ea.cmdidx].cmd_func(&ea)
	if !ea.errmsg.Nil() {
		errormsg = ea.errmsg
	}

doend:
	if curwin.w_cursor.lnum == 0 {
		curwin.w_cursor.lnum = 1
		curwin.w_cursor.col = 0
	}

	if !errormsg.Nil() && errormsg.Get() != NUL && did_emsg == 0 {
		if (sourcing != 0 || KeyTyped == 0) && did_append_cmd == 0 {
			if errormsg != IObuff {
				musl_strcpy(IObuff, errormsg)
				errormsg = IObuff
			}
			append_command(*cmdlinep)
		}
		emsg(errormsg)
	}

	undo_cmdmod(&cmdmod)
	cmdmod = save_cmdmod
	reg_executing = save_reg_executing
	pending_end_reg_executing = save_pending_end_reg_executing

	if !ea.nextcmd.Nil() && ea.nextcmd.Get() == NUL {
		ea.nextcmd = Ptr[byte]{}
	}

	return ea.nextcmd
}

func ex_errmsg(msg Ptr[byte], arg Ptr[byte]) Ptr[byte] {
	vim_snprintf(ex_error_buf, MSG_BUF_LEN, gettext_(msg), arg)
	return ex_error_buf
}

func ex_range_without_command(eap *S_exarg) Ptr[byte] {
	var errormsg Ptr[byte]

	if eap.addr_count != 0 {
		if eap.line2 > curbuf.b_ml.ml_line_count {
			if !vim_strchr(p_cpo, CPO_MINUS).Nil() {
				eap.line2 = -1
			} else {
				eap.line2 = curbuf.b_ml.ml_line_count
			}
		}

		if eap.line2 < 0 {
			errormsg = gettext_(e_invalid_range)
		} else {
			if eap.line2 == 0 {
				curwin.w_cursor.lnum = 1
			} else {
				curwin.w_cursor.lnum = eap.line2
			}
			beginline(BL_SOL | BL_FIX)
		}
	}
	return errormsg
}

func checkforcmd_opt(pp *Ptr[byte], cmd Ptr[byte], len_ int32, noparen int32) int32 {
	var i int32

	for i = 0; cmd.At(int(i)) != NUL; i++ {
		if cmd.At(int(i)) != (*pp).At(int(i)) {
			break
		}
	}
	c := (*pp).At(int(i))
	if i >= len_ && !(uint32(c)-'A' < 26 || uint32(c)-'a' < 26) && c != '_' && (noparen == 0 || (c != '(' && c != '.')) {
		*pp = skipwhite((*pp).Add(int(i)))
		return TRUE
	}
	return FALSE
}

func checkforcmd_noparen(pp *Ptr[byte], cmd Ptr[byte], len_ int32) int32 {
	return checkforcmd_opt(pp, cmd, len_, TRUE)
}

func parse_command_modifiers(eap *S_exarg, errormsg *Ptr[byte], cmod *cmdmod_T, skip_only int32) int32 {
	var orig_cmd Ptr[byte] = eap.cmd
	var cmd_start Ptr[byte]
	var has_visual_range int32 = FALSE

	*cmod = cmdmod_T{}
	cmod.cmod_flags = sticky_cmdmod_flags

	if musl_strncmp(eap.cmd, S("'<,'>"), 5) == 0 {
		eap.cmd = eap.cmd.Add(5)
		cmd_start = eap.cmd
		has_visual_range = TRUE
	}

	for {
		var p Ptr[byte]

		for eap.cmd.Get() == ' ' || eap.cmd.Get() == '\t' || eap.cmd.Get() == ':' {
			eap.cmd = eap.cmd.Add(1)
		}

		if eap.cmd.Get() == '\n' {
			eap.nextcmd = eap.cmd.Add(1)
			return FAIL
		}
		if eap.cmd.Get() == NUL {
			return FAIL
		}

		p = skip_range(eap.cmd, TRUE, nil)

		switch p.Get() {
		case 'k':
			if checkforcmd_noparen(&eap.cmd, S("keepmarks"), 3) != 0 {
				cmod.cmod_flags |= CMOD_KEEPMARKS
				continue
			}
			if checkforcmd_noparen(&eap.cmd, S("keeppatterns"), 5) != 0 {
				cmod.cmod_flags |= CMOD_KEEPPATTERNS
				continue
			}
			if checkforcmd_noparen(&eap.cmd, S("keepjumps"), 5) == 0 {
				break
			}
			cmod.cmod_flags |= CMOD_KEEPJUMPS
			continue

		case 'f':
			{
				var reg_pat Ptr[byte]
				var nulp Ptr[byte]
				var c int32 = 0

				if checkforcmd_noparen(&p, S("filter"), 4) == 0 || p.Get() == NUL || ends_excmd(int32(p.Get())) != 0 {
					break
				}
				if p.Get() == '!' {
					cmod.cmod_filter_force = TRUE
					p = skipwhite(p.Add(1))
					if p.Get() == NUL || ends_excmd(int32(p.Get())) != 0 {
						break
					}
				}
				if skip_only != 0 {
					p = skip_vimgrep_pat(p, nil, nil)
				} else {
					p = skip_vimgrep_pat_ext(p, &reg_pat, nil, &nulp, &c)
				}
				if p.Nil() || p.Get() == NUL {
					break
				}
				if skip_only == 0 {
					cmod.cmod_filter_regmatch.regprog = vim_regcomp(reg_pat, RE_MAGIC)
					if cmod.cmod_filter_regmatch.regprog == nil {
						break
					}
					if !nulp.Nil() {
						nulp.Put(byte(c))
					}
				}
				eap.cmd = p
				continue
			}

		case 'l':
			if checkforcmd_noparen(&eap.cmd, S("lockmarks"), 3) != 0 {
				cmod.cmod_flags |= CMOD_LOCKMARKS
				continue
			}
			break

		case 's':
			if checkforcmd_noparen(&eap.cmd, S("silent"), 3) == 0 {
				break
			}
			cmod.cmod_flags |= CMOD_SILENT
			if eap.cmd.Get() == '!' && !(eap.cmd.At(-1) == ' ' || eap.cmd.At(-1) == '\t') {
				eap.cmd = skipwhite(eap.cmd.Add(1))
				cmod.cmod_flags |= CMOD_ERRSILENT
			}
			continue

		case 'u':
			if checkforcmd_noparen(&eap.cmd, S("unsilent"), 3) == 0 {
				break
			}
			cmod.cmod_flags |= CMOD_UNSILENT
			continue

		case 'v':
			if checkforcmd_noparen(&p, S("verbose"), 4) == 0 {
				break
			}
			if vim_isdigit(int32(eap.cmd.Get())) != 0 {
				cmod.cmod_verbose = musl_atoi(eap.cmd) + 1
			} else {
				cmod.cmod_verbose = 2
			}
			eap.cmd = p
			continue
		}
		break
	}

	if has_visual_range != 0 {
		if eap.cmd.Gt(cmd_start) {
			Memmove(cmd_start.Add(-5), cmd_start, eap.cmd.Sub(cmd_start))
			eap.cmd = eap.cmd.Add(-5)
			Memmove(eap.cmd.Add(-1), S(":'<,'>"), 6)
		} else {
			eap.cmd = orig_cmd
		}
	}

	return OK
}

func apply_cmdmod(cmod *cmdmod_T) {
	if cmod.cmod_verbose > 0 {
		if cmod.cmod_verbose_save == 0 {
			cmod.cmod_verbose_save = p_verbose + 1
		}
		p_verbose = int64(cmod.cmod_verbose - 1)
	}

	if (cmod.cmod_flags&(CMOD_SILENT|CMOD_UNSILENT) != 0) && cmod.cmod_save_msg_silent == 0 {
		cmod.cmod_save_msg_silent = msg_silent + 1
		cmod.cmod_save_msg_scroll = msg_scroll
	}
	if cmod.cmod_flags&CMOD_SILENT != 0 {
		msg_silent++
	}
	if cmod.cmod_flags&CMOD_UNSILENT != 0 {
		msg_silent = 0
	}

	if cmod.cmod_flags&CMOD_ERRSILENT != 0 {
		emsg_silent++
		cmod.cmod_did_esilent++
	}
}

func undo_cmdmod(cmod *cmdmod_T) {
	if cmod.cmod_verbose_save > 0 {
		p_verbose = cmod.cmod_verbose_save - 1
		cmod.cmod_verbose_save = 0
	}

	vim_regfree(cmod.cmod_filter_regmatch.regprog)

	if cmod.cmod_save_msg_silent > 0 {
		if did_emsg == 0 || msg_silent > cmod.cmod_save_msg_silent-1 {
			msg_silent = cmod.cmod_save_msg_silent - 1
		}
		emsg_silent -= cmod.cmod_did_esilent
		if emsg_silent < 0 {
			emsg_silent = 0
		}
		msg_scroll = cmod.cmod_save_msg_scroll

		cmod.cmod_save_msg_silent = 0
		cmod.cmod_did_esilent = 0
	}
}

func parse_cmd_address(eap *S_exarg, errormsg *Ptr[byte], silent int32) int32 {
	var address_count int32 = 1
	var lnum linenr_T
	var need_check_cursor int32 = FALSE
	var ret int32 = FAIL

	for {
		eap.line1 = eap.line2
		eap.line2 = default_address(eap)
		eap.cmd = skipwhite(eap.cmd)
		ac := address_count
		address_count++
		lnum = get_address(eap, &eap.cmd, eap.addr_type, FALSE, silent, B2i(eap.addr_count == 0), ac)
		if eap.cmd.Nil() {
			goto theend
		}
		if lnum == LONG_MAX {
			if eap.cmd.Get() == '%' {
				eap.cmd = eap.cmd.Add(1)
				switch eap.addr_type {
				case ADDR_LINES, ADDR_OTHER:
					eap.line1 = 1
					eap.line2 = curbuf.b_ml.ml_line_count
				case ADDR_WINDOWS:
					*errormsg = gettext_(e_invalid_range)
					goto theend
				case ADDR_UNSIGNED:
					*errormsg = gettext_(e_invalid_range)
					goto theend
				case ADDR_NONE:
				}
				eap.addr_count++
			} else if eap.cmd.Get() == '*' && vim_strchr(p_cpo, CPO_STAR).Nil() {
				var fp Ptr[pos_T]

				if eap.addr_type != ADDR_LINES {
					*errormsg = gettext_(e_invalid_range)
					goto theend
				}

				eap.cmd = eap.cmd.Add(1)
				fp = getmark('<', FALSE)
				if check_mark(fp) == FAIL {
					goto theend
				}
				eap.line1 = fp.P().lnum
				fp = getmark('>', FALSE)
				if check_mark(fp) == FAIL {
					goto theend
				}
				eap.line2 = fp.P().lnum
				eap.addr_count++
			}
		} else {
			eap.line2 = lnum
		}
		eap.addr_count++

		if eap.cmd.Get() == ';' {
			curwin.w_cursor.lnum = eap.line2

			if eap.line2 > 0 {
				check_cursor()
			} else {
				check_cursor_col()
			}
			need_check_cursor = TRUE
		} else if eap.cmd.Get() != ',' {
			break
		}
		eap.cmd = eap.cmd.Add(1)
	}

	if eap.addr_count == 1 {
		eap.line1 = eap.line2
		if lnum == LONG_MAX {
			eap.addr_count = 0
		}
	}
	ret = OK

theend:
	if need_check_cursor != 0 {
		check_cursor()
	}
	return ret
}

func append_command(cmd Ptr[byte]) {
	var len_ usize = musl_strlen(IObuff)
	var s Ptr[byte] = cmd
	var d Ptr[byte]

	if len_ > (1024+1)-100 {
		d = IObuff.Add((1024 + 1) - 100)
		d = d.Add(-int(utf_head_off(IObuff, d)))
		musl_strcpy(d, S("..."))
	}
	musl_strcat(IObuff, S(": "))
	d = IObuff.Add(int(musl_strlen(IObuff)))
	for s.Get() != NUL && d.Sub(IObuff)+5 < (1024+1) {
		if s.At(0) == 0xc2 && s.At(1) == 0xa0 {
			s = s.Add(2)
			musl_strcpy(d, S("<a0>"))
			d = d.Add(4)
		} else if d.Sub(IObuff)+int(utfc_ptr2len(s))+1 >= (1024 + 1) {
			break
		} else {
			mb_copy_char(&s, &d)
		}
	}
	d.Put(NUL)
}

func one_letter_cmd(p Ptr[byte], idx *cmdidx_T) int32 {
	if p.At(0) == 'k' && (p.At(1) != 'e' || (p.At(1) == 'e' && p.At(2) != 'e')) {
		*idx = CMD_k
		return TRUE
	}
	if p.At(0) == 's' && ((p.At(1) == 'c' && (p.At(2) == NUL || (p.At(2) != 's' && p.At(2) != 'r' && (p.At(3) == NUL || (p.At(3) != 'i' && p.At(4) != 'p'))))) || p.At(1) == 'g' || (p.At(1) == 'i' && p.At(2) != 'm' && p.At(2) != 'l' && p.At(2) != 'g') || p.At(1) == 'I' || (p.At(1) == 'r' && p.At(2) != 'e')) {
		*idx = CMD_substitute
		return TRUE
	}
	return FALSE
}

func find_ex_command(eap *S_exarg, full *int32) Ptr[byte] {
	var len_ int32
	var p Ptr[byte]
	var i int32

	p = eap.cmd
	if one_letter_cmd(p, &eap.cmdidx) != 0 {
		p = p.Add(1)
		if full != nil {
			*full = TRUE
		}
	} else {
		for uint32(p.Get())-'A' < 26 || uint32(p.Get())-'a' < 26 {
			p = p.Add(1)
		}

		if p == eap.cmd && !vim_strchr(S("@*=><&~#"), int32(p.Get())).Nil() {
			p = p.Add(1)
		}
		len_ = int32(p.Sub(eap.cmd))
		if eap.cmd.Get() == 'd' && (p.At(-1) == 'l' || p.At(-1) == 'p') {
			for i = 0; i < len_; i++ {
				if eap.cmd.At(int(i)) != S("delete").At(int(i)) {
					break
				}
			}
			if i == len_-1 {
				len_--
				if p.At(-1) == 'l' {
					eap.flags |= EXFLAG_LIST
				} else {
					eap.flags |= EXFLAG_PRINT
				}
			}
		}

		for eap.cmdidx = cmdidx_T(0); int32(eap.cmdidx) < int32(CMD_SIZE); eap.cmdidx = cmdidx_T(int32(eap.cmdidx) + 1) {
			if len_ >= cmdnames[int(eap.cmdidx)].cmd_minlen && musl_strncmp(cmdnames[int(eap.cmdidx)].cmd_name, eap.cmd, usize(len_)) == 0 {
				break
			}
		}

		if eap.cmdidx == CMD_star && vim_strchr(p_cpo, CPO_STAR).Nil() {
			p = eap.cmd
		}

		if (eap.cmdidx == CMD_SIZE || eap.cmdidx == CMD_Print) && eap.cmd.Get() >= 'A' && eap.cmd.Get() <= 'Z' {
			for (uint32(p.Get())-'A' < 26 || uint32(p.Get())-'a' < 26) || uint32(p.Get())-'0' < 10 {
				p = p.Add(1)
			}
		}
		if p.Nil() || p == eap.cmd {
			eap.cmdidx = CMD_SIZE
		}
	}

	return p
}

func skip_range(cmd_start Ptr[byte], skip_star int32, ctx *int32) Ptr[byte] {
	var cmd Ptr[byte] = cmd_start
	var delim uint32

	for !vim_strchr(S(" \t0123456789.$%'/?-+,;\\"), int32(cmd.Get())).Nil() {
		if cmd.Get() == '\\' {
			if cmd.At(1) == '?' || cmd.At(1) == '/' || cmd.At(1) == '&' {
				cmd = cmd.Add(1)
			} else {
				break
			}
		} else if cmd.Get() == '\'' {
			var p Ptr[byte] = cmd

			for p.Gt(cmd_start) {
				p = p.Add(-1)
				if !(p.Get() == ' ' || p.Get() == '\t') {
					break
				}
			}
			if cmd.Gt(cmd_start) && !(p.Get() == ' ' || p.Get() == '\t') && p.Get() != ',' && p.Get() != ';' {
				break
			}
			cmd = cmd.Add(1)
			if cmd.Get() == NUL && ctx != nil {
				*ctx = EXPAND_NOTHING
			}
		} else if cmd.Get() == '/' || cmd.Get() == '?' {
			delim = uint32(cmd.Get())
			cmd = cmd.Add(1)
			for cmd.Get() != NUL && uint32(cmd.Get()) != delim {
				c := cmd.Get()
				cmd = cmd.Add(1)
				if c == '\\' && cmd.Get() != NUL {
					cmd = cmd.Add(1)
				}
			}
			if cmd.Get() == NUL && ctx != nil {
				*ctx = EXPAND_NOTHING
			}
		}
		if cmd.Get() != NUL {
			cmd = cmd.Add(1)
		}
	}

	for cmd.Get() == ':' {
		cmd = skipwhite(cmd.Add(1))
	}

	if skip_star != 0 && cmd.Get() == '*' && vim_strchr(p_cpo, CPO_STAR).Nil() {
		cmd = skipwhite(cmd.Add(1))
	}

	return cmd
}

func addr_error(addr_type cmd_addr_T) {
	if addr_type == ADDR_NONE {
		emsg(gettext_(e_no_range_allowed))
	} else {
		emsg(gettext_(e_invalid_range))
	}
}

func default_address(eap *S_exarg) linenr_T {
	var lnum linenr_T = 0

	switch eap.addr_type {
	case ADDR_LINES, ADDR_OTHER:
		if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
			lnum = curbuf.b_ml.ml_line_count
		} else {
			lnum = curwin.w_cursor.lnum
		}
	case ADDR_WINDOWS:
		lnum = 1
	case ADDR_UNSIGNED:
		lnum = 1
	case ADDR_NONE:
	}
	return lnum
}

func get_address(eap *S_exarg, ptr *Ptr[byte], addr_type cmd_addr_T, skip int32, silent int32, to_other_file int32, address_count int32) linenr_T {
	var c int32
	var i int32
	var n int64
	var cmd Ptr[byte]
	var pos pos_T
	var fp Ptr[pos_T]
	var lnum linenr_T

	cmd = skipwhite(*ptr)
	lnum = LONG_MAX
	for {
		switch cmd.Get() {
		case '.':
			cmd = cmd.Add(1)
			switch addr_type {
			case ADDR_LINES, ADDR_OTHER:
				lnum = curwin.w_cursor.lnum
			case ADDR_WINDOWS:
				lnum = 1
			case ADDR_NONE, ADDR_UNSIGNED:
				addr_error(addr_type)
				cmd = Ptr[byte]{}
				goto error
			}

		case '$':
			cmd = cmd.Add(1)
			switch addr_type {
			case ADDR_LINES, ADDR_OTHER:
				lnum = curbuf.b_ml.ml_line_count
			case ADDR_WINDOWS:
				lnum = 1
			case ADDR_NONE, ADDR_UNSIGNED:
				addr_error(addr_type)
				cmd = Ptr[byte]{}
				goto error
			}

		case '\'':
			cmd = cmd.Add(1)
			if cmd.Get() == NUL {
				cmd = Ptr[byte]{}
				goto error
			}
			if addr_type != ADDR_LINES {
				addr_error(addr_type)
				cmd = Ptr[byte]{}
				goto error
			}
			if skip != 0 {
				cmd = cmd.Add(1)
			} else {
				fp = getmark(int32(cmd.Get()), B2i(to_other_file != 0 && cmd.At(1) == NUL))
				cmd = cmd.Add(1)
				if check_mark(fp) == FAIL {
					cmd = Ptr[byte]{}
					goto error
				}
				lnum = fp.P().lnum
			}

		case '/', '?':
			c = int32(cmd.Get())
			cmd = cmd.Add(1)
			if addr_type != ADDR_LINES {
				addr_error(addr_type)
				cmd = Ptr[byte]{}
				goto error
			}
			if skip != 0 {
				cmd = skip_regexp(cmd, c, magic_isset())
				if int32(cmd.Get()) == c {
					cmd = cmd.Add(1)
				}
			} else {
				var flags int32

				pos = curwin.w_cursor

				if lnum > 0 && lnum != LONG_MAX {
					if lnum > curbuf.b_ml.ml_line_count {
						curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
					} else {
						curwin.w_cursor.lnum = lnum
					}
				}

				if c == '/' && curwin.w_cursor.lnum > 0 {
					curwin.w_cursor.col = MAXCOL
				} else {
					curwin.w_cursor.col = 0
				}
				searchcmdlen = 0
				if silent != 0 {
					flags = SEARCH_KEEP
				} else {
					flags = SEARCH_HIS | SEARCH_MSG
				}
				if do_search(nil, c, c, cmd, musl_strlen(cmd), 1, flags, nil) == 0 {
					curwin.w_cursor = pos
					cmd = Ptr[byte]{}
					goto error
				}
				lnum = curwin.w_cursor.lnum
				curwin.w_cursor = pos
				cmd = cmd.Add(int(searchcmdlen))
			}

		case '\\':
			cmd = cmd.Add(1)
			if addr_type != ADDR_LINES {
				addr_error(addr_type)
				cmd = Ptr[byte]{}
				goto error
			}
			if cmd.Get() == '&' {
				i = RE_SUBST
			} else if cmd.Get() == '?' || cmd.Get() == '/' {
				i = RE_SEARCH
			} else {
				emsg(gettext_(e_backslash_should_be_followed_by))
				cmd = Ptr[byte]{}
				goto error
			}

			if skip == 0 {
				if lnum != LONG_MAX {
					pos.lnum = lnum
				} else {
					pos.lnum = curwin.w_cursor.lnum
				}

				if cmd.Get() != '?' {
					pos.col = MAXCOL
				} else {
					pos.col = 0
				}
				pos.coladd = 0
				var dir int32
				if cmd.Get() == '?' {
					dir = -1
				} else {
					dir = FORWARD
				}
				if searchit(curwin, curbuf, &pos, nil, dir, S(""), 0, 1, SEARCH_MSG, i, nil) != FAIL {
					lnum = pos.lnum
				} else {
					cmd = Ptr[byte]{}
					goto error
				}
			}
			cmd = cmd.Add(1)

		default:
			if uint32(cmd.Get())-'0' < 10 {
				lnum = getdigits(Addr(&cmd))
			}
		}

		for {
			cmd = skipwhite(cmd)
			if cmd.Get() != '-' && cmd.Get() != '+' && !(uint32(cmd.Get())-'0' < 10) {
				break
			}

			if lnum == LONG_MAX {
				switch addr_type {
				case ADDR_LINES, ADDR_OTHER:
					lnum = curwin.w_cursor.lnum
				case ADDR_WINDOWS:
					lnum = 1
				case ADDR_NONE, ADDR_UNSIGNED:
					lnum = 0
				}
			}

			if uint32(cmd.Get())-'0' < 10 {
				i = '+'
			} else {
				i = int32(cmd.Get())
				cmd = cmd.Add(1)
			}
			if !(uint32(cmd.Get())-'0' < 10) {
				n = 1
			} else {
				n = getdigits(Addr(&cmd))
				if n == LONG_MAX {
					emsg(gettext_(e_line_number_out_of_range))
					cmd = Ptr[byte]{}
					goto error
				}
			}

			if i == '-' {
				lnum -= n
			} else {
				if lnum >= 0 && n >= LONG_MAX-lnum {
					emsg(gettext_(e_line_number_out_of_range))
					cmd = Ptr[byte]{}
					goto error
				}
				lnum += n
			}
		}
		if !(cmd.Get() == '/' || cmd.Get() == '?') {
			break
		}
	}

error:
	*ptr = cmd
	return lnum
}

func address_default_all(eap *S_exarg) {
	eap.line1 = 1
	switch eap.addr_type {
	case ADDR_LINES, ADDR_OTHER:
		eap.line2 = curbuf.b_ml.ml_line_count
	case ADDR_WINDOWS:
		eap.line2 = 1
	case ADDR_NONE, ADDR_UNSIGNED:
		iemsg(S("Cannot use EX_DFLALL with ADDR_NONE or ADDR_UNSIGNED"))
	}
}

func get_flags(eap *S_exarg) {
	for !vim_strchr(S("lp#"), int32(eap.arg.Get())).Nil() {
		if eap.arg.Get() == 'l' {
			eap.flags |= EXFLAG_LIST
		} else if eap.arg.Get() == 'p' {
			eap.flags |= EXFLAG_PRINT
		} else {
			eap.flags |= EXFLAG_NR
		}
		eap.arg = skipwhite(eap.arg.Add(1))
	}
}

func invalid_range(eap *S_exarg) Ptr[byte] {
	if eap.line1 < 0 || eap.line2 < 0 || eap.line1 > eap.line2 {
		return gettext_(e_invalid_range)
	}

	if eap.argt&EX_RANGE != 0 {
		switch eap.addr_type {
		case ADDR_LINES:
			if eap.line2 > curbuf.b_ml.ml_line_count {
				return gettext_(e_invalid_range)
			}
		case ADDR_WINDOWS:
			if eap.line2 > 1 {
				return gettext_(e_invalid_range)
			}
		case ADDR_OTHER:
		case ADDR_UNSIGNED, ADDR_NONE:
		}
	}
	return Ptr[byte]{}
}

func correct_range(eap *S_exarg) {
	if !(eap.argt&EX_ZEROR != 0) {
		if eap.line1 == 0 {
			eap.line1 = 1
		}
		if eap.line2 == 0 {
			eap.line2 = 1
		}
	}
}

func separate_nextcmd(eap *S_exarg, keep_backslash int32) {
	var p Ptr[byte]

	p = eap.arg

	for ; p.Get() != 0; p = p.Add(int(utfc_ptr2len(p))) {
		if p.Get() == Ctrl_V {
			if eap.argt&EX_CTRLV != 0 {
				p = p.Add(1)
			} else {
				Memmove(p, p.Add(1), int(musl_strlen(p.Add(1))+1))
			}
			if p.Get() == NUL {
				break
			}
		} else if p.Get() == '\n' {
			if (vim_strchr(p_cpo, CPO_BAR).Nil() || !(eap.argt&EX_CTRLV != 0)) && p.At(-1) == '\\' {
				Memmove(p.Add(-1), p, int(musl_strlen(p)+1))
				p = p.Add(-1)
			} else {
				set_nextcmd(eap, p)
				p.Put(NUL)
				break
			}
		}
	}

	if !(eap.argt&EX_NOTRLCOM != 0) {
		del_trailing_spaces(eap.arg)
	}
}

func getargcmd(argp *Ptr[byte]) Ptr[byte] {
	var arg Ptr[byte] = *argp
	var command Ptr[byte]

	if arg.Get() == '+' {
		arg = arg.Add(1)
		if vim_isspace(int32(arg.Get())) != 0 || arg.Get() == NUL {
			command = dollar_command
		} else {
			command = arg
			arg = skip_cmd_arg(command, TRUE)
			if arg.Get() != NUL {
				arg.Put(NUL)
				arg = arg.Add(1)
			}
		}

		arg = skipwhite(arg)
		*argp = arg
	}
	return command
}

func skip_cmd_arg(p Ptr[byte], rembs int32) Ptr[byte] {
	for p.Get() != 0 && vim_isspace(int32(p.Get())) == 0 {
		if p.Get() == '\\' && p.At(1) != NUL {
			if rembs != 0 {
				Memmove(p, p.Add(1), int(musl_strlen(p.Add(1))+1))
			} else {
				p = p.Add(1)
			}
		}
		p = p.Add(int(utfc_ptr2len(p)))
	}
	return p
}

func ends_excmd(c int32) int32 {
	return B2i(c == NUL || c == '\n')
}

func ends_excmd2(cmd_start Ptr[byte], cmd Ptr[byte]) int32 {
	var c int32 = int32(cmd.Get())

	return B2i(c == NUL || c == '\n')
}

func find_nextcmd(p Ptr[byte]) Ptr[byte] {
	for p.Get() != '\n' {
		if p.Get() == NUL {
			return Ptr[byte]{}
		}
		p = p.Add(1)
	}
	return p.Add(1)
}

func check_nextcmd(p Ptr[byte]) Ptr[byte] {
	var s Ptr[byte] = skipwhite(p)

	if s.Get() == '\n' {
		return s.Add(1)
	} else {
		return Ptr[byte]{}
	}
}

func set_nextcmd(eap *S_exarg, arg Ptr[byte]) {
	var p Ptr[byte] = skipwhite(arg)

	p = check_nextcmd(p)

	if eap.nextcmd.Nil() {
		eap.nextcmd = p
	} else if !p.Nil() {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_cannot_use_bar_to_separate_commands_here_str), arg)
		emsg(iobuff_or(gettext_(e_cannot_use_bar_to_separate_commands_here_str)))
	}
}

func ex_highlight(eap *S_exarg) {
	if eap.arg.Get() == NUL && eap.cmd.At(2) == '!' {
		msg(gettext_(S("Greetings, Vim user!")))
	}
	do_highlight(eap.arg, eap.forceit, FALSE)
}

func before_quit_autocmds(wp *S_window_S, quit_all int32, forceit int32) int32 {
	if win_valid(wp) == 0 || curbuf_locked() != 0 || (wp.w_buffer.b_nwindows == 1 && wp.w_buffer.b_locked > 0) {
		return TRUE
	}

	if win_valid(wp) == 0 || curbuf_locked() != 0 || (curbuf.b_nwindows == 1 && curbuf.b_locked > 0) {
		return TRUE
	}

	return FALSE
}

func ex_quit(eap *S_exarg) {
	var wp *S_window_S

	if text_locked() != 0 {
		text_locked_msg()
		return
	}
	wp = curwin

	if curbuf_locked() != 0 {
		return
	}

	if before_quit_autocmds(wp, FALSE, eap.forceit) != 0 {
		return
	}

	getout(0)
}

func ex_cquit(eap *S_exarg) {
	if eap.addr_count > 0 {
		getout(int32(eap.line2))
	} else {
		getout(EXIT_FAILURE)
	}
}

func ex_stop(eap *S_exarg) {
	windgoto(int32(Rows)-1, cmdline_col_off)
	out_char('\n')
	out_flush()
	stoptermcap()
	out_flush()
	ui_suspend()
	starttermcap()
	scroll_start()
	redraw_later_clear()
	shell_resized()
}

func ex_print(eap *S_exarg) {
	if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
		emsg(gettext_(e_empty_buffer))
	} else {
		for ; got_int == 0; ui_breakcheck() {
			print_line(eap.line1, B2i(eap.cmdidx == CMD_number || eap.cmdidx == CMD_pound || eap.flags&EXFLAG_NR != 0), B2i(eap.cmdidx == CMD_list || eap.flags&EXFLAG_LIST != 0))
			eap.line1++
			if eap.line1 > eap.line2 {
				break
			}
			out_flush()
		}
		setpcmark()
		curwin.w_cursor.lnum = eap.line2
		beginline(BL_SOL | BL_FIX)
	}
}

func ex_wrongmodifier(eap *S_exarg) {
	eap.errmsg = ex_errmsg(e_invalid_command_str, eap.cmd)
}

func ex_equal(eap *S_exarg) {
	vim_snprintf(IObuff, iobuff_room(), S("%ld"), int64(eap.line2))
	msg(iobuff_or(S("%ld")))
	ex_may_print(eap)
}

func do_sleep(msec int64, hide_cursor int32) {
	var done int64 = 0
	var wait_now int64
	var start_tv int64

	start_tv = musl_now_ms()

	if hide_cursor != 0 {
		cursor_sleep()
	} else {
		cursor_on()
	}

	out_flush_cursor(FALSE, FALSE)
	for got_int == 0 && done < msec {
		if msec-done > 1000 {
			wait_now = 1000
		} else {
			wait_now = msec - done
		}
		ui_delay(wait_now, TRUE)

		ui_breakcheck()

		done = musl_now_ms() - start_tv
	}

	if got_int != 0 {
		vpeekc()
	}

	if hide_cursor != 0 {
		cursor_unsleep()
	}
}

func ex_winsize(eap *S_exarg) {
	var w int32
	var h int32
	var arg Ptr[byte] = eap.arg
	var p Ptr[byte]

	if musl_isdigit(int32(arg.Get())) == 0 {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), arg)
		emsg(iobuff_or(gettext_(e_invalid_argument_str)))
		return
	}
	w = int32(getdigits(Addr(&arg)))
	arg = skipwhite(arg)
	p = arg
	h = int32(getdigits(Addr(&arg)))
	if p.Get() != NUL && arg.Get() == NUL {
		set_shellsize(w, h, TRUE)
	} else {
		emsg(gettext_(e_winsize_requires_two_number_arguments))
	}
}

func ex_operators(eap *S_exarg) {
	var oa S_oparg_S

	clear_oparg(&oa)
	oa.regname = eap.regname
	oa.start.lnum = eap.line1
	oa.end.lnum = eap.line2
	oa.line_count = eap.line2 - eap.line1 + 1
	oa.motion_type = MLINE
	virtual_op = FALSE
	if eap.cmdidx != CMD_yank {
		setpcmark()
		curwin.w_cursor.lnum = eap.line1
		beginline(BL_SOL | BL_FIX)
	}

	if VIsual_active != 0 {
		end_visual_mode()
	}

	switch eap.cmdidx {
	case CMD_delete:
		oa.op_type = OP_DELETE
		op_delete(&oa)

	case CMD_yank:
		oa.op_type = OP_YANK
		op_yank(&oa, FALSE, TRUE)

	default:
		if eap.cmdidx == CMD_rshift {
			oa.op_type = OP_RSHIFT
		} else {
			oa.op_type = OP_LSHIFT
		}
		op_shift(&oa, FALSE, eap.amount)
	}
	virtual_op = MAYBE
	ex_may_print(eap)
}

func ex_put(eap *S_exarg) {
	if eap.line2 == 0 {
		eap.line2 = 1
		eap.forceit = TRUE
	}
	curwin.w_cursor.lnum = eap.line2
	check_cursor_col()
	var dir int32
	if eap.forceit != 0 {
		dir = -1
	} else {
		dir = FORWARD
	}
	do_put(eap.regname, Ptr[byte]{}, dir, 1, PUT_LINE|PUT_CURSLINE)
}

func ex_iput(eap *S_exarg) {
	if eap.line2 == 0 {
		eap.line2 = 1
		eap.forceit = TRUE
	}
	curwin.w_cursor.lnum = eap.line2
	check_cursor_col()
	var dir int32
	if eap.forceit != 0 {
		dir = -1
	} else {
		dir = FORWARD
	}
	do_put(eap.regname, Ptr[byte]{}, dir, 1, PUT_LINE|PUT_CURSLINE|PUT_FIXINDENT)
}

func ex_copymove(eap *S_exarg) {
	var n int64

	n = get_address(eap, &eap.arg, eap.addr_type, FALSE, FALSE, FALSE, 1)
	if eap.arg.Nil() {
		eap.nextcmd = Ptr[byte]{}
		return
	}
	get_flags(eap)

	if n == LONG_MAX || n < 0 || n > curbuf.b_ml.ml_line_count {
		emsg(gettext_(e_invalid_range))
		return
	}

	if eap.cmdidx == CMD_move {
		if do_move(eap.line1, eap.line2, n) == FAIL {
			return
		}
	} else {
		ex_copy(eap.line1, eap.line2, n)
	}
	u_clearline()
	beginline(BL_SOL | BL_FIX)
	ex_may_print(eap)
}

func ex_may_print(eap *S_exarg) {
	if eap.flags != 0 {
		print_line(curwin.w_cursor.lnum, eap.flags&EXFLAG_NR, eap.flags&EXFLAG_LIST)
	}
}

func ex_submagic(eap *S_exarg) {
	var saved optmagic_T = magic_overruled

	if eap.cmdidx == CMD_smagic {
		magic_overruled = OPTION_MAGIC_ON
	} else {
		magic_overruled = OPTION_MAGIC_OFF
	}
	ex_substitute(eap)
	magic_overruled = saved
}

func ex_join(eap *S_exarg) {
	curwin.w_cursor.lnum = eap.line1
	if eap.line1 == eap.line2 {
		if eap.addr_count >= 2 {
			return
		}
		if eap.line2 == curbuf.b_ml.ml_line_count {
			beep_flush()
			return
		}
		eap.line2++
	}
	do_join(eap.line2-eap.line1+1, B2i(eap.forceit == 0), TRUE, TRUE, TRUE)
	beginline(BL_WHITE | BL_FIX)
	ex_may_print(eap)
}

func ex_at(eap *S_exarg) {
	var c int32
	var prev_len int32 = typebuf.tb_len

	curwin.w_cursor.lnum = eap.line2
	check_cursor_col()

	c = int32(eap.arg.Get())
	if c == NUL || (c == '*' && eap.cmd.Get() == '*') {
		c = '@'
	}
	if do_execreg(c, TRUE, B2i(!vim_strchr(p_cpo, CPO_EXECBUF).Nil()), TRUE) == FAIL {
		beep_flush()
		return
	}

	var save_efr int32 = exec_from_reg

	exec_from_reg = TRUE

	for stuff_empty() == 0 || typebuf.tb_len > prev_len {
		do_cmdline(Ptr[byte]{}, getexline, nil, DOCMD_NOWAIT|DOCMD_VERBOSE)
	}

	exec_from_reg = save_efr
}

func ex_undo(eap *S_exarg) {
	if eap.addr_count == 1 {
		undo_time(eap.line2, FALSE, FALSE, TRUE)
	} else {
		u_undo(1)
	}
}

func ex_redo(eap *S_exarg) {
	u_redo(1)
}

func ex_later(eap *S_exarg) {
	var count int64 = 0
	var sec int32 = FALSE
	var file int32 = FALSE
	var p Ptr[byte] = eap.arg

	if p.Get() == NUL {
		count = 1
	} else if musl_isdigit(int32(p.Get())) != 0 {
		count = getdigits(Addr(&p))
		switch p.Get() {
		case 's':
			p = p.Add(1)
			sec = TRUE
		case 'm':
			p = p.Add(1)
			sec = TRUE
			count *= 60
		case 'h':
			p = p.Add(1)
			sec = TRUE
			count *= 60 * 60
		case 'd':
			p = p.Add(1)
			sec = TRUE
			count *= 24 * 60 * 60
		case 'f':
			p = p.Add(1)
			file = TRUE
		}
	}

	if p.Get() != NUL {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), eap.arg)
		emsg(iobuff_or(gettext_(e_invalid_argument_str)))
	} else {
		if eap.cmdidx == CMD_earlier {
			undo_time(-count, sec, file, FALSE)
		} else {
			undo_time(count, sec, file, FALSE)
		}
	}
}

func ex_redraw(eap *S_exarg) {
	redraw_cmd(eap.forceit)
}

func redraw_cmd(clear_ int32) {
	var save_RedrawingDisabled int32 = RedrawingDisabled
	RedrawingDisabled = 0

	var save_p_lz int32 = p_lz
	p_lz = FALSE

	validate_cursor()
	update_topline()
	var t int32
	if clear_ != 0 {
		t = UPD_CLEAR
	} else if VIsual_active != 0 {
		t = UPD_INVERTED
	} else {
		t = 0
	}
	update_screen(t)
	if (State & MODE_CMDLINE) == 0 {
		setcursor()
	}
	RedrawingDisabled = save_RedrawingDisabled
	p_lz = save_p_lz

	screen_stop_highlight()

	msg_didout = FALSE
	msg_col = 0

	need_wait_return = FALSE

	if State&MODE_CMDLINE != 0 {
		redrawcmdline()
	}

	out_flush()
}

func ex_redrawstatus(eap *S_exarg) {
	if eap.forceit != 0 {
		status_redraw_all()
	} else {
		status_redraw_curbuf()
	}
	redraw_vseps = TRUE
	if msg_scrolled != 0 && (State&MODE_CMDLINE != 0) {
		return
	}

	var save_RedrawingDisabled int32 = RedrawingDisabled
	RedrawingDisabled = 0

	var save_p_lz int32 = p_lz
	p_lz = FALSE

	if State&MODE_CMDLINE != 0 {
		redraw_statuslines()
	} else {
		if VIsual_active != 0 {
			update_screen(UPD_INVERTED)
		} else {
			update_screen(0)
		}
	}
	RedrawingDisabled = save_RedrawingDisabled
	p_lz = save_p_lz
	out_flush()
}

func ex_mark(eap *S_exarg) {
	var pos pos_T

	if eap.arg.Get() == NUL {
		emsg(gettext_(e_argument_required))
		return
	}

	if eap.arg.At(1) != NUL {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_trailing_characters_str), eap.arg)
		emsg(iobuff_or(gettext_(e_trailing_characters_str)))
		return
	}

	pos = curwin.w_cursor
	curwin.w_cursor.lnum = eap.line2
	beginline(BL_WHITE | BL_FIX)
	if setmark(int32(eap.arg.Get())) == FAIL {
		emsg(gettext_(e_argument_must_be_letter_or_forward_backward_quote))
	}
	curwin.w_cursor = pos
}

func update_topline_cursor() {
	check_cursor()
	update_topline()
	if curwin.w_onebuf_opt.wo_wrap == 0 {
		validate_cursor()
	}
	update_curswant()
}

func save_current_state(sst *save_state_T) int32 {
	sst.save_msg_scroll = msg_scroll
	sst.save_restart_edit = restart_edit
	sst.save_msg_didout = msg_didout
	sst.save_State = State
	sst.save_insertmode = p_im
	sst.save_finish_op = finish_op
	sst.save_opcount = int32(opcount)
	sst.save_reg_executing = reg_executing
	sst.save_pending_end_reg_executing = pending_end_reg_executing

	msg_scroll = FALSE
	restart_edit = 0
	p_im = FALSE

	sst.save_script_version = current_sctx.sc_version
	current_sctx.sc_version = 1

	save_typeahead(&sst.tabuf)
	return sst.tabuf.typebuf_valid
}

func restore_current_state(sst *save_state_T) {
	restore_typeahead(&sst.tabuf, FALSE)

	msg_scroll = sst.save_msg_scroll
	restart_edit = sst.save_restart_edit
	p_im = sst.save_insertmode
	finish_op = sst.save_finish_op
	opcount = int64(sst.save_opcount)
	reg_executing = sst.save_reg_executing
	pending_end_reg_executing = sst.save_pending_end_reg_executing
	msg_didout |= sst.save_msg_didout
	current_sctx.sc_version = sst.save_script_version

	State = sst.save_State
}

func ex_normal(eap *S_exarg) {
	var save_state save_state_T
	var arg Ptr[byte]
	var l int32
	var p Ptr[byte]

	if ex_normal_lock > 0 {
		emsg(gettext_(e_not_allowed_here))
		return
	}
	if int64(ex_normal_busy) >= p_mmd {
		emsg(gettext_(e_recursive_use_of_normal_too_deep))
		return
	}

	var len_ int32 = 0

	for p = eap.arg; p.Get() != NUL; p = p.Add(1) {
		for l = utfc_ptr2len(p) - 1; l > 0; l-- {
			p = p.Add(1)
			if p.Get() == 0x80 {
				len_ += 2
			}
		}
	}
	if len_ > 0 {
		arg = Alloc(int(musl_strlen(eap.arg) + usize(len_) + 1))
		len_ = 0
		for p = eap.arg; p.Get() != NUL; p = p.Add(1) {
			arg.Set(int(len_), p.Get())
			len_++
			for l = utfc_ptr2len(p) - 1; l > 0; l-- {
				p = p.Add(1)
				arg.Set(int(len_), p.Get())
				len_++
				if p.Get() == 0x80 {
					arg.Set(int(len_), KS_SPECIAL)
					len_++
					arg.Set(int(len_), 'X')
					len_++
				}
			}
			arg.Set(int(len_), NUL)
		}
	}

	ex_normal_busy++
	if save_current_state(&save_state) != 0 {
		for {
			if eap.addr_count != 0 {
				curwin.w_cursor.lnum = eap.line1
				eap.line1++
				curwin.w_cursor.col = 0
				check_cursor_moved(curwin)
			}

			var cmd Ptr[byte]
			if !arg.Nil() {
				cmd = arg
			} else {
				cmd = eap.arg
			}
			var remap int32
			if eap.forceit != 0 {
				remap = -1
			} else {
				remap = REMAP_YES
			}
			exec_normal_cmd(cmd, remap, FALSE)
			if !(eap.addr_count > 0 && eap.line1 <= eap.line2 && got_int == 0) {
				break
			}
		}
	}

	update_topline_cursor()

	restore_current_state(&save_state)
	ex_normal_busy--
}

func exec_normal_cmd(cmd Ptr[byte], remap int32, silent int32) {
	ins_typebuf(cmd, remap, 0, TRUE, silent)
	exec_normal(FALSE, FALSE, FALSE)
}

func exec_normal(was_typed int32, use_vpeekc int32, may_use_terminal_loop int32) {
	var oa S_oparg_S
	var c int32

	clear_oparg(&oa)
	finish_op = FALSE
	for {
		cond := stuff_empty() == 0 || ((was_typed != 0 || typebuf_typed() == 0) && typebuf.tb_len > 0)
		if !cond && use_vpeekc != 0 {
			c = vpeekc()
			cond = c != NUL && c != Ctrl_C
		}
		if !(cond && got_int == 0) {
			break
		}
		update_topline_cursor()
		normal_cmd(&oa, TRUE)
	}
}

func set_no_hlsearch(flag int32) {
	no_hlsearch = flag
}

func ex_nohlsearch(eap *S_exarg) {
	set_no_hlsearch(TRUE)
	redraw_all_later(UPD_SOME_VALID)
}

func abandon_cmdline() {
	dealloc_cmdbuff()
	if msg_scrolled == 0 {
		compute_cmdrow()
	}
	msg(S(""))
	redraw_cmdline = TRUE
}

func empty_pattern(p Ptr[byte], len_ usize, delim int32) int32 {
	var magic_val magic_T = MAGIC_ON

	if len_ > 0 {
		skip_regexp_ex(p, delim, magic_isset(), nil, nil, &magic_val)
	} else {
		return TRUE
	}

	return empty_pattern_magic(p, len_, magic_val)
}

func empty_pattern_magic(p Ptr[byte], len_ usize, magic_val magic_T) int32 {
	for len_ >= 2 && p.At(int(len_-2)) == '\\' && !vim_strchr(S("mMvVcCZ"), int32(p.At(int(len_-1)))).Nil() {
		len_ -= 2
	}

	return B2i(len_ == 0 ||
		(len_ > 1 && p.At(int(len_-1)) == '|' && ((p.At(int(len_-2)) == '\\' && magic_val == MAGIC_ON) || (p.At(int(len_-2)) != '\\' && magic_val == MAGIC_ALL))))
}

func save_viewstate(vs *viewstate_T) {
	vs.vs_curswant = curwin.w_curswant
	vs.vs_leftcol = curwin.w_leftcol
	vs.vs_skipcol = curwin.w_skipcol
	vs.vs_topline = curwin.w_topline
	vs.vs_botline = curwin.w_botline
	vs.vs_empty_rows = linenr_T(curwin.w_empty_rows)
}

func restore_viewstate(vs *viewstate_T) {
	curwin.w_curswant = vs.vs_curswant
	curwin.w_leftcol = vs.vs_leftcol
	curwin.w_skipcol = vs.vs_skipcol
	curwin.w_topline = vs.vs_topline
	curwin.w_botline = vs.vs_botline
	curwin.w_empty_rows = int32(vs.vs_empty_rows)
}

func init_incsearch_state(is_state *incsearch_state_T) {
	is_state.match_start = curwin.w_cursor
	is_state.did_incsearch = FALSE
	is_state.incsearch_postponed = FALSE
	is_state.magic_overruled_save = magic_overruled
	is_state.match_end.lnum = 0
	is_state.match_end.col = 0
	is_state.match_end.coladd = 0
	is_state.save_cursor = curwin.w_cursor
	is_state.search_start = curwin.w_cursor
	save_viewstate(&is_state.init_viewstate)
	save_viewstate(&is_state.old_viewstate)
}

func set_search_match(t *pos_T) {
	t.lnum += search_match_lines
	t.col = search_match_endcol
	if t.lnum > curbuf.b_ml.ml_line_count {
		t.lnum = curbuf.b_ml.ml_line_count
		coladvance(colnr_T(MAXCOL))
	}
}

func parse_pattern_and_range(incsearch_start *pos_T, search_delim *int32, skiplen *int32, patlen *int32) int32 {
	var cmd Ptr[byte]
	var p Ptr[byte]
	var end Ptr[byte]
	var dummy_cmdmod cmdmod_T
	var ea exarg_T
	var save_cursor pos_T
	var delim_optional int32 = FALSE
	var delim int32
	var use_last_pat int32
	var magic magic_T = 0
	var dummy Ptr[byte]

	// max(p - cmd, m) of the C macro
	maxlen := func(m int) usize {
		if p.Sub(cmd) > m {
			return usize(p.Sub(cmd))
		}
		return usize(m)
	}

	*skiplen = 0
	*patlen = ccline.cmdlen

	search_first_line = 0
	search_last_line = LONG_MAX

	ea = exarg_T{}
	ea.line1 = 1
	ea.line2 = 1
	ea.cmd = ccline.cmdbuff
	ea.addr_type = ADDR_LINES

	parse_command_modifiers(&ea, &dummy, &dummy_cmdmod, TRUE)

	cmd = skip_range(ea.cmd, TRUE, nil)

	if vim_strchr(S("sgvlu"), int32(cmd.Get())).Nil() {
		return FALSE
	}

	for p = cmd; uint32(p.Get())-'A' < 26 || uint32(p.Get())-'a' < 26; p = p.Add(1) {
	}
	if skipwhite(p).Get() == NUL {
		return FALSE
	}

	if musl_strncmp(cmd, S("substitute"), usize(p.Sub(cmd))) == 0 || musl_strncmp(cmd, S("smagic"), usize(p.Sub(cmd))) == 0 || musl_strncmp(cmd, S("snomagic"), maxlen(3)) == 0 || musl_strncmp(cmd, S("vglobal"), usize(p.Sub(cmd))) == 0 {
		if cmd.Get() == 's' && cmd.At(1) == 'm' {
			magic_overruled = OPTION_MAGIC_ON
		} else if cmd.Get() == 's' && cmd.At(1) == 'n' {
			magic_overruled = OPTION_MAGIC_OFF
		}
	} else if musl_strncmp(cmd, S("sort"), maxlen(3)) == 0 || musl_strncmp(cmd, S("uniq"), maxlen(3)) == 0 {
		if p.Get() == '!' {
			p = skipwhite(p.Add(1))
		}
		for {
			p = skipwhite(p)
			if !(uint32(p.Get())-'A' < 26) {
				p = skipwhite(p)
				if !(uint32(p.Get())-'a' < 26) {
					break
				}
			}
			p = p.Add(1)
		}
		if p.Get() == NUL {
			return FALSE
		}
	} else if musl_strncmp(cmd, S("vimgrep"), maxlen(3)) == 0 || musl_strncmp(cmd, S("vimgrepadd"), maxlen(8)) == 0 || musl_strncmp(cmd, S("lvimgrep"), maxlen(2)) == 0 || musl_strncmp(cmd, S("lvimgrepadd"), maxlen(9)) == 0 || musl_strncmp(cmd, S("global"), usize(p.Sub(cmd))) == 0 {
		if p.Get() == '!' {
			p = p.Add(1)
			if skipwhite(p).Get() == NUL {
				return FALSE
			}
		}
		if cmd.Get() != 'g' {
			delim_optional = TRUE
		}
	} else {
		return FALSE
	}

	p = skipwhite(p)
	if delim_optional != 0 && vim_isIDc(int32(p.Get())) != 0 {
		delim = ' '
	} else {
		delim = int32(p.Get())
		p = p.Add(1)
	}
	*search_delim = delim

	end = skip_regexp_ex(p, delim, magic_isset(), nil, nil, &magic)
	use_last_pat = B2i(end == p && int32(end.Get()) == delim)

	if end == p && use_last_pat == 0 {
		return FALSE
	}

	if use_last_pat == 0 {
		var c byte = end.Get()
		var empty int32

		end.Put(NUL)
		empty = empty_pattern_magic(p, usize(end.Sub(p)), magic)
		end.Put(c)
		if empty != 0 {
			return FALSE
		}
	}

	*skiplen = int32(p.Sub(ccline.cmdbuff))
	*patlen = int32(end.Sub(p))

	save_cursor = curwin.w_cursor
	curwin.w_cursor = *incsearch_start

	parse_cmd_address(&ea, &dummy, TRUE)

	if ea.addr_count > 0 {
		var reverse_match int32 = B2i(ea.line2 < ea.line1)
		if reverse_match != 0 {
			search_first_line = ea.line2
			search_last_line = ea.line1
		} else {
			search_first_line = ea.line1
			search_last_line = ea.line2
		}
	} else if cmd.At(0) == 's' && cmd.At(1) != 'o' {
		search_last_line = curwin.w_cursor.lnum
		search_first_line = search_last_line
	}

	curwin.w_cursor = save_cursor
	return TRUE
}

func do_incsearch_highlighting(firstc int32, search_delim *int32, is_state *incsearch_state_T, skiplen *int32, patlen *int32) int32 {
	var retval int32 = FALSE

	*skiplen = 0
	*patlen = ccline.cmdlen

	if p_is == 0 || cmd_silent != 0 {
		return FALSE
	}

	search_first_line = 0
	search_last_line = LONG_MAX

	if firstc == '/' || firstc == '?' {
		*search_delim = firstc
		return TRUE
	}

	if firstc != ':' {
		return FALSE
	}

	emsg_off++
	retval = parse_pattern_and_range(&is_state.search_start, search_delim, skiplen, patlen)
	emsg_off--

	return retval
}

func finish_incsearch_highlighting(gotesc int32, is_state *incsearch_state_T, call_update_screen int32) {
	if is_state.did_incsearch == 0 {
		return
	}

	is_state.did_incsearch = FALSE
	if gotesc != 0 {
		curwin.w_cursor = is_state.save_cursor
	} else {
		if !(is_state.save_cursor.lnum == is_state.search_start.lnum && is_state.save_cursor.col == is_state.search_start.col && is_state.save_cursor.coladd == is_state.search_start.coladd) {
			curwin.w_cursor = is_state.save_cursor
			setpcmark()
		}
		curwin.w_cursor = is_state.search_start
	}
	restore_viewstate(&is_state.old_viewstate)
	highlight_match = FALSE

	search_first_line = 0
	search_last_line = LONG_MAX

	magic_overruled = is_state.magic_overruled_save

	validate_cursor()
	status_redraw_all()
	redraw_all_later(UPD_SOME_VALID)
	if call_update_screen != 0 {
		update_screen(UPD_SOME_VALID)
	}
}

func may_do_incsearch_highlighting(firstc int32, count int64, is_state *incsearch_state_T) {
	var skiplen int32
	var patlen int32
	var found int32
	var end_pos pos_T
	var next_char int32
	var use_last_pat int32
	var did_do_incsearch int32 = is_state.did_incsearch
	var search_delim int32

	save_last_search_pattern()

	if do_incsearch_highlighting(firstc, &search_delim, is_state, &skiplen, &patlen) == 0 {
		restore_last_search_pattern()
		finish_incsearch_highlighting(FALSE, is_state, TRUE)
		if did_do_incsearch != 0 && vpeekc() == NUL {
			redrawcmd()
		}
		return
	}

	if char_avail() != 0 {
		restore_last_search_pattern()
		is_state.incsearch_postponed = TRUE
		return
	}
	is_state.incsearch_postponed = FALSE

	if search_first_line == 0 {
		curwin.w_cursor = is_state.search_start
	} else if search_first_line > curbuf.b_ml.ml_line_count {
		curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
		curwin.w_cursor.col = MAXCOL
	} else {
		curwin.w_cursor.lnum = search_first_line
		curwin.w_cursor.col = 0
	}

	next_char = int32(ccline.cmdbuff.At(int(skiplen + patlen)))
	use_last_pat = B2i(patlen == 0 && skiplen > 0 && int32(ccline.cmdbuff.At(int(skiplen-1))) == next_char)

	if patlen == 0 && use_last_pat == 0 {
		found = 0
		set_no_hlsearch(TRUE)
		redraw_all_later(UPD_SOME_VALID)
	} else {
		var search_flags int32 = SEARCH_OPT + SEARCH_NOOF + SEARCH_PEEK

		cursor_off()
		out_flush()
		emsg_off++
		if p_hls == 0 {
			search_flags += SEARCH_KEEP
		}
		if search_first_line != 0 {
			search_flags += SEARCH_START
		}
		ccline.cmdbuff.Set(int(skiplen+patlen), NUL)
		var dirc int32
		if firstc == ':' {
			dirc = '/'
		} else {
			dirc = firstc
		}
		found = do_search(nil, dirc, search_delim, ccline.cmdbuff.Add(int(skiplen)), usize(patlen), count, search_flags, nil)
		ccline.cmdbuff.Set(int(skiplen+patlen), byte(next_char))
		emsg_off--

		if curwin.w_cursor.lnum < search_first_line || curwin.w_cursor.lnum > search_last_line {
			found = 0
			curwin.w_cursor = is_state.search_start
		}

		if got_int != 0 {
			vpeekc()
			got_int = FALSE
			found = 0
		} else if char_avail() != 0 {
			is_state.incsearch_postponed = TRUE
		}
	}
	if found != 0 {
		highlight_match = TRUE
	} else {
		highlight_match = FALSE
	}

	restore_viewstate(&is_state.old_viewstate)
	changed_cline_bef_curs()
	update_topline()

	if found != 0 {
		var save_pos pos_T = curwin.w_cursor

		is_state.match_start = curwin.w_cursor
		set_search_match(&curwin.w_cursor)
		validate_cursor()
		end_pos = curwin.w_cursor
		is_state.match_end = end_pos
		curwin.w_cursor = save_pos
	} else {
		end_pos = curwin.w_cursor
	}

	if use_last_pat == 0 {
		next_char = int32(ccline.cmdbuff.At(int(skiplen + patlen)))
		ccline.cmdbuff.Set(int(skiplen+patlen), NUL)
		if empty_pattern(ccline.cmdbuff.Add(int(skiplen)), usize(patlen), search_delim) != 0 && no_hlsearch == 0 {
			redraw_all_later(UPD_SOME_VALID)
			set_no_hlsearch(TRUE)
		}
		ccline.cmdbuff.Set(int(skiplen+patlen), byte(next_char))
	}

	validate_cursor()

	if p_ru != 0 && curwin.w_status_height > 0 {
		curwin.w_redr_status = true
	}

	update_screen(UPD_SOME_VALID)
	highlight_match = FALSE
	restore_last_search_pattern()

	if ccline.cmdbuff.At(int(skiplen+patlen)) != NUL {
		curwin.w_cursor = is_state.search_start
	} else if found != 0 {
		curwin.w_cursor = end_pos
	}

	msg_starthere()
	redrawcmdline()
	is_state.did_incsearch = TRUE
}

func may_adjust_incsearch_highlighting(firstc int32, count int64, is_state *incsearch_state_T, c int32) int32 {
	var skiplen int32
	var patlen int32
	var t pos_T
	var pat Ptr[byte]
	var dircp Ptr[byte]
	var searchstr Ptr[byte]
	var strcopy Ptr[byte]
	var searchstrlen usize
	var patlen_s usize
	var offset soffset_T
	var search_flags int32 = SEARCH_NOOF
	var i int32
	var search_delim int32

	save_last_search_pattern()

	if do_incsearch_highlighting(firstc, &search_delim, is_state, &skiplen, &patlen) == 0 {
		restore_last_search_pattern()
		return OK
	}
	if patlen == 0 && ccline.cmdbuff.At(int(skiplen)) == NUL {
		restore_last_search_pattern()
		return FAIL
	}

	pat = ccline.cmdbuff.Add(int(skiplen))
	searchstr = pat
	searchstrlen = usize(patlen)
	patlen_s = usize(ccline.cmdlen - skiplen)

	parse_search_pattern_offset(&pat, &patlen_s, search_delim, SEARCH_OPT, &strcopy, &searchstr, &searchstrlen, &dircp, &offset)

	cursor_off()
	out_flush()
	if c == Ctrl_G {
		t = is_state.match_end
		var lt bool
		if is_state.match_start.lnum != is_state.match_end.lnum {
			lt = is_state.match_start.lnum < is_state.match_end.lnum
		} else if is_state.match_start.col != is_state.match_end.col {
			lt = is_state.match_start.col < is_state.match_end.col
		} else {
			lt = is_state.match_start.coladd < is_state.match_end.coladd
		}
		if lt {
			decl(&t)
		}
		search_flags += SEARCH_COL
	} else {
		t = is_state.match_start
	}
	if p_hls == 0 {
		search_flags += SEARCH_KEEP
	}
	emsg_off++
	var dir int32
	if c == Ctrl_G {
		dir = FORWARD
	} else {
		dir = -1
	}
	i = searchit(curwin, curbuf, &t, nil, dir, searchstr, searchstrlen, count, search_flags, RE_SEARCH, nil)
	emsg_off--
	if !dircp.Nil() {
		dircp.Put(byte(search_delim))
	}
	if i != 0 {
		var match_start pos_T = is_state.match_start
		var match_end pos_T = is_state.match_end
		var off int64 = offset.off

		is_state.search_start = match_start
		if offset.line == 0 && (offset.end != 0 || off != 0) {
			if offset.end != 0 {
				is_state.search_start = match_end
				decl(&is_state.search_start)
			}
			for off > 0 {
				if incl(&is_state.search_start) == -1 {
					break
				}
				off--
			}
			for off < 0 {
				if decl(&is_state.search_start) == -1 {
					break
				}
				off++
			}
		}
		is_state.match_end = t
		is_state.match_start = t
		if c == Ctrl_T && firstc != '?' {
			is_state.search_start = t
			decl(&is_state.search_start)
		} else if c == Ctrl_G && firstc == '?' {
			is_state.search_start = t
			incl(&is_state.search_start)
		}
		var lt bool
		if t.lnum != is_state.search_start.lnum {
			lt = t.lnum < is_state.search_start.lnum
		} else if t.col != is_state.search_start.col {
			lt = t.col < is_state.search_start.col
		} else {
			lt = t.coladd < is_state.search_start.coladd
		}
		if lt && c == Ctrl_G {
			is_state.search_start = t
			if firstc == '?' {
				incl(&is_state.search_start)
			} else {
				decl(&is_state.search_start)
			}
		}

		set_search_match(&is_state.match_end)
		curwin.w_cursor = is_state.match_start
		changed_cline_bef_curs()
		update_topline()
		validate_cursor()
		highlight_match = TRUE
		save_viewstate(&is_state.old_viewstate)
		update_screen(UPD_NOT_VALID)
		highlight_match = FALSE
		redrawcmdline()
		curwin.w_cursor = is_state.match_end
	} else {
		vim_beep(BO_ERROR)
	}
	restore_last_search_pattern()
	return FAIL
}

func may_add_char_to_search(firstc int32, c *int32, is_state *incsearch_state_T) int32 {
	var skiplen int32
	var patlen int32
	var search_delim int32

	save_last_search_pattern()

	if do_incsearch_highlighting(firstc, &search_delim, is_state, &skiplen, &patlen) == 0 {
		restore_last_search_pattern()
		return FAIL
	}
	restore_last_search_pattern()

	if is_state.did_incsearch != 0 {
		curwin.w_cursor = is_state.match_end
		*c = gchar_cursor()
		if *c != NUL {
			if p_ic != 0 && p_scs != 0 && pat_has_uppercase(ccline.cmdbuff.Add(int(skiplen))) == 0 {
				*c = vim_tolower(*c)
			}
			var chars Ptr[byte]
			if magic_isset() != 0 {
				chars = S("\\~^$.*[")
			} else {
				chars = S("\\^$")
			}
			if *c == search_delim || !vim_strchr(chars, *c).Nil() {
				stuffcharReadbuff(*c)
				*c = '\\'
			}
			if utf_char2len(*c) != utfc_ptr2len(ml_get_cursor()) {
				var save_c int32 = *c

				for utf_char2len(*c) != utfc_ptr2len(ml_get_cursor()) {
					curwin.w_cursor.col += utf_char2len(*c)
					*c = gchar_cursor()
					stuffcharReadbuff(*c)
				}
				*c = save_c
			}
			return FAIL
		}
	}
	return OK
}

func cmdline_init() {
	ccline = cmdline_info_T{}
}

func cmdline_handle_ctrl_bsl(c int32, gotesc *int32) int32 {
	no_mapping++
	allow_keys++
	c = plain_vgetc()
	no_mapping--
	allow_keys--

	if c != Ctrl_N && c != Ctrl_G && (c != 'e' || (ccline.cmdfirstc == '=' && KeyTyped != 0)) {
		vungetc(c)
		return PROCESS_NEXT_KEY
	}

	if c == Ctrl_G && p_im != 0 && restart_edit == 0 {
		restart_edit = 'a'
	}
	*gotesc = TRUE
	return GOTO_NORMAL_MODE
}

func cmdline_erase_chars(c int32, indent int32, isp *incsearch_state_T) int32 {
	var i int32
	var j int32

	if c == -(KS_EXTRA + (int32(KE_KDEL) << 8)) {
		c = -('k' + ('D' << 8))
	}

	if c == -('k'+('D'<<8)) && ccline.cmdpos != ccline.cmdlen {
		ccline.cmdpos++
	}
	if c == -('k' + ('D' << 8)) {
		ccline.cmdpos += mb_off_next(ccline.cmdbuff, ccline.cmdbuff.Add(int(ccline.cmdpos)))
	}
	if ccline.cmdpos > 0 {
		var p Ptr[byte]

		j = ccline.cmdpos
		p = ccline.cmdbuff.Add(int(j))
		p = mb_prevptr(ccline.cmdbuff, p)
		if c == Ctrl_W {
			for p.Gt(ccline.cmdbuff) && vim_isspace(int32(p.Get())) != 0 {
				p = mb_prevptr(ccline.cmdbuff, p)
			}
			i = mb_get_class(p)
			for p.Gt(ccline.cmdbuff) && mb_get_class(p) == i {
				p = mb_prevptr(ccline.cmdbuff, p)
			}
			if mb_get_class(p) != i {
				p = p.Add(int(utfc_ptr2len(p)))
			}
		}
		ccline.cmdpos = int32(p.Sub(ccline.cmdbuff))
		ccline.cmdlen -= j - ccline.cmdpos
		i = ccline.cmdpos
		for i < ccline.cmdlen {
			ccline.cmdbuff.Set(int(i), ccline.cmdbuff.At(int(j)))
			i++
			j++
		}

		ccline.cmdbuff.Set(int(ccline.cmdlen), NUL)
		if ccline.cmdlen == 0 {
			isp.search_start = isp.save_cursor
			isp.old_viewstate = isp.init_viewstate
		}
		redrawcmd()
	} else if ccline.cmdlen == 0 && c != Ctrl_W && ccline.cmdprompt.Nil() && indent == 0 {
		dealloc_cmdbuff()

		if cmd_silent == 0 {
			msg_col = 0
			msg_putchar(' ')
		}
		isp.search_start = isp.save_cursor
		redraw_cmdline = TRUE
		return GOTO_NORMAL_MODE
	}
	return CMDLINE_CHANGED
}

func cmdline_insert_reg(gotesc *int32) int32 {
	var i int32
	var c int32
	var literally int32 = FALSE

	putcmdline('"', TRUE)
	no_mapping++
	allow_keys++
	c = plain_vgetc()
	i = c
	if i == Ctrl_O {
		i = Ctrl_R
	}
	if i == Ctrl_R {
		c = plain_vgetc()
	}
	extra_char = NUL
	no_mapping--
	allow_keys--
	if c != ESC {
		literally = B2i(i == Ctrl_R)
		cmdline_paste(c, literally, FALSE)

		KeyTyped = FALSE
	}

	redrawcmd()

	if literally != 0 {
		return CMDLINE_CHANGED
	}
	return CMDLINE_NOT_CHANGED
}

func cmdline_browse_history(c int32, firstc int32, curcmdstr *Ptr[byte], curcmdstrlen *usize, histype int32, hiscnt_p *int32, xp *S_expand) int32 {
	var orig_hiscnt int32
	orig_hiscnt = *hiscnt_p
	var hiscnt int32 = orig_hiscnt
	var lookfor Ptr[byte] = *curcmdstr
	var lookforlen usize = *curcmdstrlen
	var res int32

	if get_hislen() == 0 || firstc == NUL {
		return CMDLINE_NOT_CHANGED
	}

	if lookfor.Nil() {
		lookfor = vim_strnsave(ccline.cmdbuff, usize(ccline.cmdlen))
		lookfor.Set(int(ccline.cmdpos), NUL)
		lookforlen = usize(ccline.cmdpos)
	}

	for {
		if c == -('k'+('u'<<8)) || c == -(KS_EXTRA+(int32(KE_S_UP)<<8)) || c == Ctrl_P || c == -('k'+('P'<<8)) || c == -('K'+('3'<<8)) {
			if hiscnt == get_hislen() {
				hiscnt = get_hisidx(histype).Get()
			} else if hiscnt == 0 && get_hisidx(histype).Get() != get_hislen()-1 {
				hiscnt = get_hislen() - 1
			} else if hiscnt != get_hisidx(histype).Get()+1 {
				hiscnt--
			} else {
				hiscnt = orig_hiscnt
				break
			}
		} else {
			if hiscnt == get_hisidx(histype).Get() {
				hiscnt = get_hislen()
				break
			}

			if hiscnt == get_hislen() {
				break
			}
			if hiscnt == get_hislen()-1 {
				hiscnt = 0
			} else {
				hiscnt++
			}
		}
		if hiscnt < 0 || get_histentry(histype).At(int(hiscnt)).hisstr.Nil() {
			hiscnt = orig_hiscnt
			break
		}
		if (c != -('k'+('u'<<8)) && c != -('k'+('d'<<8))) || hiscnt == orig_hiscnt || musl_strncmp(get_histentry(histype).At(int(hiscnt)).hisstr, lookfor, lookforlen) == 0 {
			break
		}
	}

	if hiscnt != orig_hiscnt {
		var p Ptr[byte]
		var plen usize
		var old_firstc int32

		dealloc_cmdbuff()

		xp.xp_context = EXPAND_NOTHING
		if hiscnt == get_hislen() {
			p = lookfor
			plen = lookforlen
		} else {
			p = get_histentry(histype).At(int(hiscnt)).hisstr
			plen = get_histentry(histype).At(int(hiscnt)).hisstrlen
		}

		cond := histype == HIST_SEARCH && p != lookfor
		if cond {
			old_firstc = int32(p.At(int(plen + 1)))
			cond = old_firstc != firstc
		}
		if cond {
			var i int32
			var j int32
			var len_ usize

			for i = 0; i <= 1; i++ {
				len_ = 0
				for j = 0; p.At(int(j)) != NUL; j++ {
					if int32(p.At(int(j))) == old_firstc && (j == 0 || p.At(int(j-1)) != '\\') {
						if i > 0 {
							ccline.cmdbuff.Set(int(len_), byte(firstc))
						}
					} else {
						if int32(p.At(int(j))) == firstc && (j == 0 || p.At(int(j-1)) != '\\') {
							if i > 0 {
								ccline.cmdbuff.Set(int(len_), '\\')
							}
							len_++
						}
						if i > 0 {
							ccline.cmdbuff.Set(int(len_), p.At(int(j)))
						}
					}
					len_++
				}
				if i == 0 {
					alloc_cmdbuff(len_)
					if ccline.cmdbuff.Nil() {
						res = GOTO_NORMAL_MODE
						goto done
					}
				}
			}
			ccline.cmdbuff.Set(int(len_), NUL)
			ccline.cmdlen = int32(len_)
			ccline.cmdpos = ccline.cmdlen
		} else {
			alloc_cmdbuff(plen)
			if ccline.cmdbuff.Nil() {
				res = GOTO_NORMAL_MODE
				goto done
			}
			musl_strcpy(ccline.cmdbuff, p)
			ccline.cmdlen = int32(plen)
			ccline.cmdpos = ccline.cmdlen
		}

		redrawcmd()
		res = CMDLINE_CHANGED
		goto done
	}
	beep_flush()
	res = CMDLINE_NOT_CHANGED

done:
	*curcmdstr = lookfor
	*curcmdstrlen = lookforlen
	*hiscnt_p = hiscnt
	return res
}

func init_ccline(firstc int32, indent int32) int32 {
	ccline.overstrike = FALSE

	if firstc == '@' {
		ccline.cmdfirstc = 0
	} else {
		ccline.cmdfirstc = firstc
	}
	if firstc > 0 {
		ccline.cmdindent = indent
	} else {
		ccline.cmdindent = 0
	}

	alloc_cmdbuff(usize(indent + 50))
	ccline.cmdpos = 0
	ccline.cmdlen = ccline.cmdpos
	if ccline.cmdbuff.Nil() {
		ccline.cmdbufflen = 0
		return FAIL
	}
	ccline.cmdbuff.Set(0, NUL)
	sb_text_start_cmdline()

	if firstc <= 0 {
		Memset(ccline.cmdbuff, ' ', int(indent))
		ccline.cmdbuff.Set(int(indent), NUL)
		ccline.cmdpos = indent
		ccline.cmdspos = indent
		ccline.cmdlen = indent
	}

	return OK
}

func getcmdline(firstc int32, count int64, indent int32, do_concat getline_opt_T) Ptr[byte] {
	return getcmdline_int(firstc, count, indent, TRUE)
}

func init() {
	getcmdline_int_depth = 0
}

func getcmdline_int(firstc int32, count int64, indent int32, clear_ccline int32) Ptr[byte] {
	var c int32 = 0
	var i int32
	var j int32
	var gotesc int32 = FALSE
	var do_abbr int32
	var lookfor Ptr[byte]
	var lookforlen usize = 0
	var hiscnt int32
	var histype int32
	var is_state incsearch_state_T
	var res int32
	var save_msg_scroll int32 = msg_scroll
	var save_State int32 = State
	var some_key_typed int32 = FALSE
	var xpc expand_T
	var save_ccline cmdline_info_T
	var did_save_ccline int32 = FALSE
	var wild_type int32 = 0
	var prev_cmdbuff Ptr[byte]

	getcmdline_int_depth++

	if !ccline.cmdbuff.Nil() {
		save_cmdline(&save_ccline)
		did_save_ccline = TRUE
	}
	if clear_ccline != 0 {
		ccline = cmdline_info_T{}
	}

	init_incsearch_state(&is_state)

	if init_ccline(firstc, indent) != OK {
		goto theend
	}

	if getcmdline_int_depth == 50 {
		emsg(gettext_(e_command_too_recursive))
		goto theend
	}

	ExpandInit(&xpc)
	ccline.xpc = &xpc
	clear_cmdline_orig()

	if cmd_silent == 0 {
		i = msg_scrolled
		msg_scrolled = 0
		gotocmdline(TRUE)
		msg_scrolled += i
		redrawcmdprompt()
		set_cmdspos()
	}
	xpc.xp_context = EXPAND_NOTHING
	xpc.xp_backslash = XP_BS_NONE
	xpc.xp_shell = FALSE

	msg_scroll = FALSE

	State = MODE_CMDLINE

	term_enter()

	init_history()
	hiscnt = get_hislen()
	histype = hist_char2type(firstc)

	if did_emsg != 0 {
		redrawcmd()
	}

	did_emsg = FALSE
	got_int = FALSE

	for {
		var trigger_cmdlinechanged int32 = TRUE
		var prev_cmdpos int32 = ccline.cmdpos
		prev_cmdbuff = Ptr[byte]{}

		quit_more = FALSE

		did_emsg = FALSE

		if ex_normal_busy == 0 && stuff_empty() != 0 && typebuf.tb_len == 0 {
			some_key_typed = TRUE
		}

		may_trigger_safestate(TRUE)

		if !ccline.cmdbuff.Nil() {
			prev_cmdbuff = vim_strsave(ccline.cmdbuff)
		}

		for {
			cursorcmd()
			c = safe_vgetc()
			if !(c == -(KS_EXTRA+(int32(KE_IGNORE)<<8)) || c == -(KS_EXTRA+(int32(KE_NOP)<<8))) {
				break
			}
		}

		ccline.cmdbuff_replaced = FALSE

		if c == -(KS_EXTRA+(int32(KE_COMMAND)<<8)) || c == -(KS_EXTRA+(int32(KE_SCRIPT_COMMAND)<<8)) {
			var clen int32 = ccline.cmdlen
			var cc_count int32 = aucmd_cmdline_changed_count

			if do_cmdkey_command(c, DOCMD_NOWAIT) == OK {
				if clen == ccline.cmdlen || cc_count != aucmd_cmdline_changed_count {
					trigger_cmdlinechanged = FALSE
				}
				goto cmdline_changed
			}
		}

		if KeyTyped != 0 {
			some_key_typed = TRUE
		}

		if (c == Ctrl_C || c == intr_char) && global_busy == 0 {
			got_int = FALSE
		}

		if !lookfor.Nil() && c != -(KS_EXTRA+(int32(KE_S_DOWN)<<8)) && c != -(KS_EXTRA+(int32(KE_S_UP)<<8)) && c != -('k'+('d'<<8)) && c != -('k'+('u'<<8)) && c != -('k'+('N'<<8)) && c != -('k'+('P'<<8)) && c != -('K'+('5'<<8)) && c != -('K'+('3'<<8)) && c != -('k'+('l'<<8)) && c != -('k'+('r'<<8)) && (xpc.xp_numfiles > 0 || (c != Ctrl_P && c != Ctrl_N)) {
			lookfor = Ptr[byte]{}
			lookforlen = 0
		}

		if c == Ctrl_BSL {
			res = cmdline_handle_ctrl_bsl(c, &gotesc)
			if res == CMDLINE_CHANGED {
				goto cmdline_changed
			} else if res == CMDLINE_NOT_CHANGED {
				goto cmdline_not_changed
			} else if res == GOTO_NORMAL_MODE {
				goto returncmd
			}
			c = Ctrl_BSL
		}

		if c == '\n' || c == '\r' || c == -('K'+('A'<<8)) || (c == ESC && (KeyTyped == 0 || !vim_strchr(p_cpo, CPO_ESC).Nil())) {
			gotesc = FALSE
			if cmd_silent == 0 {
				windgoto(msg_row, cmdline_col_off)
				out_flush()
			}
			break
		}

		gotesc = FALSE

		if c == NUL || c == -(KS_ZERO+('X'<<8)) {
			c = NL
		}

		do_abbr = TRUE

		if wild_type == WILD_CANCEL || wild_type == WILD_APPLY {
			if KeyTyped != 0 || vpeekc() == NUL {
				may_do_incsearch_highlighting(firstc, count, &is_state)
			}
			wild_type = 0
			goto cmdline_not_changed
		}

		switch c {
		case -('k' + ('b' << 8)), Ctrl_H, -('k' + ('D' << 8)), -(KS_EXTRA + (int32(KE_KDEL) << 8)), Ctrl_W:
			res = cmdline_erase_chars(c, indent, &is_state)
			if res == CMDLINE_NOT_CHANGED {
				goto cmdline_not_changed
			} else if res == GOTO_NORMAL_MODE {
				goto returncmd
			}
			goto cmdline_changed

		case -('k' + ('I' << 8)), -(KS_EXTRA + (int32(KE_KINS) << 8)):
			ccline.overstrike = B2i(ccline.overstrike == 0)
			status_redraw_curbuf()
			redraw_statuslines()
			goto cmdline_not_changed

		case Ctrl_HAT:
			goto cmdline_not_changed

		case Ctrl_U:
			j = ccline.cmdpos
			ccline.cmdlen -= j
			ccline.cmdpos = 0
			i = ccline.cmdpos
			for i < ccline.cmdlen {
				ccline.cmdbuff.Set(int(i), ccline.cmdbuff.At(int(j)))
				i++
				j++
			}
			ccline.cmdbuff.Set(int(ccline.cmdlen), NUL)
			if ccline.cmdlen == 0 {
				is_state.search_start = is_state.save_cursor
			}
			redrawcmd()
			goto cmdline_changed

		case ESC, Ctrl_C:
			gotesc = TRUE
			goto returncmd

		case Ctrl_R:
			res = cmdline_insert_reg(&gotesc)
			if res == GOTO_NORMAL_MODE {
				goto returncmd
			}
			if res == CMDLINE_CHANGED {
				goto cmdline_changed
			}
			goto cmdline_not_changed

		case -('k' + ('r' << 8)), -('%' + ('i' << 8)), -(KS_EXTRA + (int32(KE_C_RIGHT) << 8)):
			for {
				if ccline.cmdpos >= ccline.cmdlen {
					break
				}
				i = cmdline_charsize(ccline.cmdpos)
				if KeyTyped != 0 && int64(ccline.cmdspos+i) >= int64(cmdline_width)*Rows {
					break
				}
				ccline.cmdspos += i
				ccline.cmdpos += utfc_ptr2len(ccline.cmdbuff.Add(int(ccline.cmdpos)))
				if !((c == -('%'+('i'<<8)) || c == -(KS_EXTRA+(int32(KE_C_RIGHT)<<8)) || mod_mask&(MOD_MASK_SHIFT|MOD_MASK_CTRL) != 0) && ccline.cmdbuff.At(int(ccline.cmdpos)) != ' ') {
					break
				}
			}
			set_cmdspos_cursor()
			goto cmdline_not_changed

		case -('k' + ('l' << 8)), -('#' + ('4' << 8)), -(KS_EXTRA + (int32(KE_C_LEFT) << 8)):
			if ccline.cmdpos == 0 {
				goto cmdline_not_changed
			}
			for {
				ccline.cmdpos--
				ccline.cmdpos -= utf_head_off(ccline.cmdbuff, ccline.cmdbuff.Add(int(ccline.cmdpos)))
				ccline.cmdspos -= cmdline_charsize(ccline.cmdpos)
				if !(ccline.cmdpos > 0 && (c == -('#'+('4'<<8)) || c == -(KS_EXTRA+(int32(KE_C_LEFT)<<8)) || mod_mask&(MOD_MASK_SHIFT|MOD_MASK_CTRL) != 0) && ccline.cmdbuff.At(int(ccline.cmdpos-1)) != ' ') {
					break
				}
			}
			set_cmdspos_cursor()
			goto cmdline_not_changed

		case -(KS_EXTRA + (int32(KE_IGNORE) << 8)):
			goto cmdline_not_changed

		case -(KS_SELECT + ('X' << 8)):
			goto cmdline_not_changed

		case Ctrl_B, -('k' + ('h' << 8)), -('K' + ('1' << 8)), -('#' + ('2' << 8)), -(KS_EXTRA + (int32(KE_C_HOME) << 8)):
			ccline.cmdpos = 0
			set_cmdspos()
			goto cmdline_not_changed

		case Ctrl_E, -('@' + ('7' << 8)), -('K' + ('4' << 8)), -('*' + ('7' << 8)), -(KS_EXTRA + (int32(KE_C_END) << 8)):
			ccline.cmdpos = ccline.cmdlen
			set_cmdspos_cursor()
			goto cmdline_not_changed

		case Ctrl_L:
			if may_add_char_to_search(firstc, &c, &is_state) == OK {
				goto cmdline_not_changed
			}

		case Ctrl_N, Ctrl_P, -('k' + ('u' << 8)), -('k' + ('d' << 8)), -(KS_EXTRA + (int32(KE_S_UP) << 8)), -(KS_EXTRA + (int32(KE_S_DOWN) << 8)), -('k' + ('P' << 8)), -('K' + ('3' << 8)), -('k' + ('N' << 8)), -('K' + ('5' << 8)):
			res = cmdline_browse_history(c, firstc, &lookfor, &lookforlen, histype, &hiscnt, &xpc)
			if res == CMDLINE_CHANGED {
				goto cmdline_changed
			} else if res == GOTO_NORMAL_MODE {
				goto returncmd
			}
			goto cmdline_not_changed

		case Ctrl_G, Ctrl_T:
			if may_adjust_incsearch_highlighting(firstc, count, &is_state, c) == FAIL {
				goto cmdline_not_changed
			}

		case Ctrl_V, Ctrl_Q:
			{
				putcmdline('^', TRUE)

				c = get_literal(mod_mask & MOD_MASK_SHIFT)

				do_abbr = FALSE
				extra_char = NUL
				if utf_iscomposing(c) != 0 && cmd_silent == 0 {
					draw_cmdline(ccline.cmdpos, ccline.cmdlen-ccline.cmdpos)
					msg_putchar(' ')
					cursorcmd()
				}
			}

		case -('P' + ('S' << 8)):
			bracketed_paste(PASTE_CMDLINE, FALSE, nil)
			goto cmdline_changed

		default:
			if c == intr_char {
				gotesc = TRUE
				goto returncmd
			}
			if !(c < 0) {
				mod_mask = 0x0
			}
		}

		if do_abbr != 0 && (c < 0 || vim_iswordc(c) == 0) && c == Ctrl_RSB {
			goto cmdline_changed
		}

		if c < 0 || mod_mask != 0 {
			put_on_cmdline(get_special_key_name(c, mod_mask), -1, TRUE)
		} else {
			j = utf_char2bytes(c, IObuff)
			IObuff.Set(int(j), NUL)
			put_on_cmdline(IObuff, j, TRUE)
		}
		goto cmdline_changed

	cmdline_not_changed:
		if ccline.cmdpos != prev_cmdpos {
			prev_cmdpos = ccline.cmdpos
		}

		if is_state.incsearch_postponed == 0 {
			continue
		}

	cmdline_changed:
		if KeyTyped != 0 || vpeekc() == NUL {
			may_do_incsearch_highlighting(firstc, count, &is_state)
		}
		if trigger_cmdlinechanged != 0 && (ccline.cmdpos != prev_cmdpos || (!prev_cmdbuff.Nil() && musl_strcmp(prev_cmdbuff, ccline.cmdbuff) != 0)) {
		}

	}

returncmd:

	ExpandCleanup(&xpc)
	ccline.xpc = nil
	clear_cmdline_orig()

	finish_incsearch_highlighting(gotesc, &is_state, FALSE)

	if !ccline.cmdbuff.Nil() {
		if ccline.cmdlen != 0 && firstc != NUL && (some_key_typed != 0 || histype == HIST_SEARCH) {
			var sep int32
			if histype == HIST_SEARCH {
				sep = firstc
			} else {
				sep = NUL
			}
			add_to_history(histype, ccline.cmdbuff, usize(ccline.cmdlen), TRUE, sep)
			if firstc == ':' {
				new_last_cmdline = vim_strnsave(ccline.cmdbuff, usize(ccline.cmdlen))
			}
		}

		if gotesc != 0 {
			abandon_cmdline()
		}
	}

	msg_check()
	msg_scroll = save_msg_scroll

	if some_key_typed != 0 {
		need_wait_return = FALSE
	}

	State = save_State

	sb_text_end_cmdline()

theend:
	{
		var p Ptr[byte] = ccline.cmdbuff

		getcmdline_int_depth--
		if did_save_ccline != 0 {
			restore_cmdline(&save_ccline)
		} else {
			ccline.cmdbuff = Ptr[byte]{}
		}

		return p
	}
}

func text_locked() int32 {
	return B2i(textlock != 0)
}

func text_locked_msg() {
	emsg(gettext_(get_text_locked_msg()))
}

func get_text_locked_msg() Ptr[byte] {
	return e_not_allowed_to_change_text_or_change_window
}

func curbuf_locked() int32 {
	if curbuf_lock > 0 {
		emsg(gettext_(e_not_allowed_to_edit_another_buffer_now))
		return TRUE
	}
	return allbuf_locked()
}

func allbuf_locked() int32 {
	if allbuf_lock > 0 {
		emsg(gettext_(e_not_allowed_to_change_buffer_information_now))
		return TRUE
	}
	return FALSE
}

func cmdline_charsize(idx int32) int32 {
	return ptr2cells(ccline.cmdbuff.Add(int(idx)))
}

func set_cmdspos() {
	if ccline.cmdfirstc != NUL {
		ccline.cmdspos = 1 + ccline.cmdindent
	} else {
		ccline.cmdspos = 0 + ccline.cmdindent
	}
}

func set_cmdspos_cursor() {
	var i int32
	var m int32
	var c int32

	set_cmdspos()
	if KeyTyped != 0 {
		m = int32(int64(cmdline_width) * Rows)
		if m < 0 {
			m = MAXCOL
		}
	} else {
		m = MAXCOL
	}
	for i = 0; i < ccline.cmdlen && i < ccline.cmdpos; i++ {
		c = cmdline_charsize(i)
		correct_cmdspos(i, c)
		ccline.cmdspos += c
		if ccline.cmdspos >= m {
			ccline.cmdspos -= c
			break
		}
		i += utfc_ptr2len(ccline.cmdbuff.Add(int(i))) - 1
	}
}

func correct_cmdspos(idx int32, cells int32) {
	if utfc_ptr2len(ccline.cmdbuff.Add(int(idx))) > 1 && utf_ptr2cells(ccline.cmdbuff.Add(int(idx))) > 1 && ccline.cmdspos%cmdline_width+cells > cmdline_width {
		ccline.cmdspos++
	}
}

func getexline(c int32, cookie any, indent int32, options getline_opt_T) Ptr[byte] {
	if exec_from_reg != 0 && vpeekc() == ':' {
		vgetc()
	}
	return getcmdline(c, 1, indent, options)
}

func dealloc_cmdbuff() {
	ccline.cmdbuff = Ptr[byte]{}
	ccline.cmdbufflen = 0
	ccline.cmdlen = ccline.cmdbufflen
}

func alloc_cmdbuff(len_ usize) {
	if len_ < 80 {
		len_ = 100
	} else {
		len_ += 20
	}

	ccline.cmdbuff = Alloc(int(len_))
	ccline.cmdbufflen = int32(len_)
}

// ==== from f05.go ====
// Transpiled by hand from editor.c: realloc_cmdbuff .. highlight_set_startstop_termcode.

func realloc_cmdbuff(len_ int32) int32 {
	var p Ptr[byte]
	var plen int32

	if len_ < ccline.cmdbufflen {
		return OK
	}

	p = ccline.cmdbuff
	plen = ccline.cmdbufflen

	alloc_cmdbuff(usize(len_))
	if ccline.cmdbuff.Nil() {
		ccline.cmdbuff = p
		ccline.cmdbufflen = plen
		return FAIL
	}
	Memmove(ccline.cmdbuff, p, int(usize(ccline.cmdlen)))
	ccline.cmdbuff.Set(int(ccline.cmdlen), NUL)

	if ccline.xpc != nil && !ccline.xpc.xp_pattern.Nil() && ccline.xpc.xp_context != EXPAND_NOTHING && ccline.xpc.xp_context != (-2) {
		i := int32(ccline.xpc.xp_pattern.Sub(p))

		if i >= 0 && i <= ccline.cmdlen {
			ccline.xpc.xp_pattern = ccline.cmdbuff.Add(int(i))
		}
	}

	return OK
}

func draw_cmdline(start int32, len_ int32) {
	msg_outtrans_len(ccline.cmdbuff.Add(int(start)), len_)
}

func putcmdline(c int32, shift int32) {
	if cmd_silent != 0 {
		return
	}
	msg_no_more = TRUE
	msg_putchar(c)
	if shift != 0 {
		draw_cmdline(ccline.cmdpos, ccline.cmdlen-ccline.cmdpos)
	}
	msg_no_more = FALSE
	cursorcmd()
	extra_char = c
	extra_char_shift = shift
}

func unputcmdline() {
	if cmd_silent != 0 {
		return
	}
	msg_no_more = TRUE
	if ccline.cmdlen == ccline.cmdpos {
		msg_putchar(' ')
	} else {
		draw_cmdline(ccline.cmdpos, utfc_ptr2len(ccline.cmdbuff.Add(int(ccline.cmdpos))))
	}
	msg_no_more = FALSE
	cursorcmd()
	extra_char = NUL
}

func put_on_cmdline(str Ptr[byte], len_ int32, redraw int32) int32 {
	var retval int32
	var i int32
	var m int32
	var c int32

	if len_ < 0 {
		len_ = int32(musl_strlen(str))
	}

	if ccline.cmdlen+len_+1 >= ccline.cmdbufflen {
		retval = realloc_cmdbuff(ccline.cmdlen + len_ + 1)
	} else {
		retval = OK
	}
	if retval == OK {
		if ccline.overstrike == 0 {
			Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos+len_)), ccline.cmdbuff.Add(int(ccline.cmdpos)), int(usize(ccline.cmdlen-ccline.cmdpos)))
			ccline.cmdlen += len_
		} else {
			m = 0
			for i = 0; i < len_; i += utfc_ptr2len(str.Add(int(i))) {
				m++
			}
			for i = ccline.cmdpos; i < ccline.cmdlen && m > 0; i += utfc_ptr2len(ccline.cmdbuff.Add(int(i))) {
				m--
			}
			if i < ccline.cmdlen {
				Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos+len_)), ccline.cmdbuff.Add(int(i)), int(usize(ccline.cmdlen-i)))
				ccline.cmdlen += ccline.cmdpos + len_ - i
			} else {
				ccline.cmdlen = ccline.cmdpos + len_
			}
		}
		Memmove(ccline.cmdbuff.Add(int(ccline.cmdpos)), str, int(usize(len_)))
		ccline.cmdbuff.Set(int(ccline.cmdlen), NUL)

		i = 0
		c = utf_ptr2char(ccline.cmdbuff.Add(int(ccline.cmdpos)))
		for ccline.cmdpos > 0 && utf_iscomposing(c) != 0 {
			i = utf_head_off(ccline.cmdbuff, ccline.cmdbuff.Add(int(ccline.cmdpos)-1)) + 1
			ccline.cmdpos -= i
			len_ += i
			c = utf_ptr2char(ccline.cmdbuff.Add(int(ccline.cmdpos)))
		}
		if i != 0 {
			i = ptr2cells(ccline.cmdbuff.Add(int(ccline.cmdpos)))
			ccline.cmdspos -= i
			msg_col -= i
			if msg_col < 0 {
				msg_col += cmdline_width
				msg_row--
			}
		}

		if redraw != 0 && cmd_silent == 0 {
			msg_no_more = TRUE
			i = cmdline_row
			cursorcmd()
			draw_cmdline(ccline.cmdpos, ccline.cmdlen-ccline.cmdpos)
			if cmdline_row != i || ccline.overstrike != 0 {
				msg_clr_eos()
			}
			msg_no_more = FALSE
		}
		if KeyTyped != 0 {
			m = int32(int64(cmdline_width) * Rows)
			if m < 0 {
				m = MAXCOL
			}
		} else {
			m = MAXCOL
		}
		for i = 0; i < len_; i++ {
			c = cmdline_charsize(ccline.cmdpos)
			correct_cmdspos(ccline.cmdpos, c)
			if ccline.cmdspos+c < m {
				ccline.cmdspos += c
			}

			c = utfc_ptr2len(ccline.cmdbuff.Add(int(ccline.cmdpos))) - 1
			if c > len_-i-1 {
				c = len_ - i - 1
			}
			ccline.cmdpos += c
			i += c
			ccline.cmdpos++
		}
	}
	if redraw != 0 {
		msg_check()
	}
	return retval
}

func save_cmdline(ccp *cmdline_info_T) {
	if prev_ccline_used == 0 {
		prev_ccline = cmdline_info_T{}
		prev_ccline_used = TRUE
	}
	*ccp = prev_ccline
	prev_ccline = ccline
	ccline.cmdbuff = Ptr[byte]{}
}

func restore_cmdline(ccp *cmdline_info_T) {
	ccline = prev_ccline
	prev_ccline = *ccp
}

func cmdline_paste(regname int32, literally int32, remcr int32) int32 {
	var i int64
	var arg Ptr[byte]
	var p Ptr[byte]
	var allocated int32

	if regname != Ctrl_F && regname != Ctrl_P && regname != Ctrl_W && regname != Ctrl_A && regname != Ctrl_L && valid_yank_reg(regname, FALSE) == 0 {
		return FAIL
	}

	line_breakcheck()
	if got_int != 0 {
		return FAIL
	}

	textlock++
	i = int64(get_spec_reg(regname, &arg, &allocated, TRUE))
	textlock--

	if i != 0 {
		if arg.Nil() {
			return FAIL
		}

		p = arg
		if p_is != 0 && regname == Ctrl_W {
			var w Ptr[byte]
			var len_ int32

			for w = ccline.cmdbuff.Add(int(ccline.cmdpos)); w.Gt(ccline.cmdbuff); {
				len_ = utf_head_off(ccline.cmdbuff, w.Add(-1)) + 1
				if vim_iswordc(utf_ptr2char(w.Add(-int(len_)))) == 0 {
					break
				}
				w = w.Add(-int(len_))
			}
			len_ = int32(ccline.cmdbuff.Add(int(ccline.cmdpos)).Sub(w))
			var eq bool
			if p_ic != 0 {
				eq = musl_strncasecmp(w, arg, usize(len_)) == 0
			} else {
				eq = musl_strncmp(w, arg, usize(len_)) == 0
			}
			if eq {
				p = p.Add(int(len_))
			}
		}

		cmdline_paste_str(p, literally)
		return OK
	}

	return cmdline_paste_reg(regname, literally, remcr)
}

func cmdline_paste_str(s Ptr[byte], literally int32) {
	var c int32
	var cv int32

	if literally != 0 {
		put_on_cmdline(s, -1, TRUE)
	} else {
		for s.Get() != NUL {
			cv = int32(s.Get())
			if cv == Ctrl_V && s.At(1) != 0 {
				s = s.Add(1)
			}
			c = mb_cptr2char_adv(&s)
			if cv == Ctrl_V || c == ESC || c == Ctrl_C || c == CAR || c == NL || c == Ctrl_L || c == intr_char || (c == Ctrl_BSL && s.Get() == Ctrl_N) {
				stuffcharReadbuff(Ctrl_V)
			}
			stuffcharReadbuff(c)
		}
	}
}

