func hl_set_ctermbg_normal_group(color int32) {
	cterm_normal_bg_color = color + 1
	{
		set_must_redraw(UPD_CLEAR)
		if color >= 0 {
			dark := int32(-1)

			if termcap_active != 0 {
				term_bg_color(color)
			}
			if t_colors < 16 {
				dark = B2i(color == 0 || color == 4)
			} else if color < 16 {
				dark = B2i(color < 7 || color == 8)
			}
			if dark != -1 && dark != B2i(p_bg.Get() == 'd') && option_was_set(S("bg")) == 0 {
				var val Ptr[byte]
				if dark != 0 {
					val = S("dark")
				} else {
					val = S("light")
				}
				set_option_value_give_err(S("bg"), 0, val, 0)
				reset_option_was_set(S("bg"))
			}
		}
	}
}

