func highlight_set_cterm_font(idx int32, arg Ptr[byte], init_ int32) int32 {
	var font int32

	if init_ != 0 && (GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_set&SG_CTERM) != 0 {
		return FALSE
	}

	if init_ == 0 {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_set |= SG_CTERM
	}

	if uint32(arg.Get())-'0' < 10 {
		font = musl_atoi(arg)
	} else if musl_strcasecmp(arg, S("NONE")) == 0 {
		font = -1
	} else {
		return FALSE
	}

	GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm_font = font + 1
	return TRUE
}

func highlight_set_cterm_color(idx int32, key Ptr[byte], key_start Ptr[byte], arg Ptr[byte], is_normal_group int32, init_ int32) int32 {
	var color int32

	if init_ != 0 && (GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_set&SG_CTERM) != 0 {
		return FALSE
	}

	if init_ == 0 {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_set |= SG_CTERM
	}

	if key.At(5) == 'F' && GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_cterm_bold != 0 {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm &= ^HL_BOLD
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm_bold = FALSE
	}

	if uint32(arg.Get())-'0' < 10 {
		color = musl_atoi(arg)
	} else if musl_strcasecmp(arg, S("fg")) == 0 {
		if cterm_normal_fg_color != 0 {
			color = cterm_normal_fg_color - 1
		} else {
			emsg(gettext_(e_fg_color_unknown))
			return FALSE
		}
	} else if musl_strcasecmp(arg, S("bg")) == 0 {
		if cterm_normal_bg_color > 0 {
			color = cterm_normal_bg_color - 1
		} else {
			emsg(gettext_(e_bg_color_unknown))
			return FALSE
		}
	} else if musl_strcasecmp(arg, S("ul")) == 0 {
		if cterm_normal_ul_color > 0 {
			color = cterm_normal_ul_color - 1
		} else {
			emsg(gettext_(e_ul_color_unknown))
			return FALSE
		}
	} else {
		bold := int32(MAYBE)
		var target keyvalue_T
		var entry Ptr[keyvalue_T]

		target.key = 0
		target.value.string_ = arg
		target.value.length = 0
		entry = keyvalue_bsearch(&target, color_name_tab, 28, cmp_keyvalue_value_i)
		if entry.Nil() {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_color_name_or_number_not_recognized_str), key_start)
			emsg(iobuff_or(gettext_(e_color_name_or_number_not_recognized_str)))
			return FALSE
		}

		color = lookup_color(entry.P().key, B2i(key.At(5) == 'F'), &bold)

		if bold == TRUE {
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm |= HL_BOLD
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm_bold = TRUE
		} else if bold == FALSE {
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm &= ^HL_BOLD
		}
	}

	if key.At(5) == 'F' {
		highlight_set_ctermfg(idx, color, is_normal_group)
	} else if key.At(5) == 'B' {
		highlight_set_ctermbg(idx, color, is_normal_group)
	} else {
		highlight_set_ctermul(idx, color, is_normal_group)
	}

	return TRUE
}

func highlight_set_startstop_termcode(idx int32, key Ptr[byte], arg Ptr[byte], init_ int32) int32 {
	var off int32
	buf := Mk[byte](100)
	var len_ int32
	var tname Ptr[byte]
	var p Ptr[byte]

	if init_ == 0 {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_set |= SG_TERM
	}

	if musl_strncmp(arg, S("t_"), 2) == 0 {
		off = 0
		buf.Set(0, 0)
		for arg.At(int(off)) != NUL {
			for len_ = 0; arg.At(int(off+len_)) != 0 && arg.At(int(off+len_)) != ','; len_++ {
			}
			tname = vim_strnsave(arg.Add(int(off)), usize(len_))
			p = get_term_code(tname)
			if p.Nil() {
				p = S("")
			}

			if int32(musl_strlen(buf)+musl_strlen(p)) >= 99 {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_terminal_code_too_long_str), arg)
				emsg(iobuff_or(gettext_(e_terminal_code_too_long_str)))
				return FALSE
			}
			musl_strcat(buf, p)

			off += len_
			if arg.At(int(off)) == ',' {
				off++
			}
		}
	} else {
		p = arg
		for off = 0; off < 100-6 && p.Get() != 0; {
			len_ = trans_special(&p, buf.Add(int(off)), FSK_SIMPLIFY, FALSE, nil)
			if len_ > 0 {
				off += len_
			} else {
				buf.Set(int(off), p.Get())
				off++
				p = p.Add(1)
			}
		}
		buf.Set(int(off), NUL)
	}

	if musl_strcmp(buf, S("NONE")) == 0 {
		p = Ptr[byte]{}
	} else {
		p = vim_strsave(buf)
	}
	if key.At(2) == 'A' {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_start = p
	} else {
		GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_stop = p
	}
	return TRUE
}

// ==== from f06.go ====
// Transpiled by hand from editor.c: do_highlight .. mark_line.

func do_highlight(line Ptr[byte], forceit int32, init_ int32) {
	var name_end Ptr[byte]
	var linep Ptr[byte]
	var key_start Ptr[byte]
	var arg_start Ptr[byte]
	var key Ptr[byte] = Ptr[byte]{}
	var arg Ptr[byte] = Ptr[byte]{}
	var i int64
	var id int32
	var idx int32
	var item_before hl_group_T
	var did_change int32 = FALSE
	var dodefault int32 = FALSE
	var doclear int32 = FALSE
	var dolink int32 = FALSE
	var error_ int32 = FALSE
	var is_normal_group int32 = FALSE

	if init_ == 0 && ends_excmd2(line.Add(-1), line) != 0 {
		for i = 1; i <= int64(highlight_ga.ga_len) && got_int == 0; i++ {
			highlight_list_one(int32(i))
		}
		return
	}

	name_end = skiptowhite(line)
	linep = skipwhite(name_end)

	if musl_strncmp(line, S("default"), usize(name_end.Sub(line))) == 0 {
		dodefault = TRUE
		line = linep
		name_end = skiptowhite(line)
		linep = skipwhite(name_end)
	}

	if musl_strncmp(line, S("clear"), usize(name_end.Sub(line))) == 0 {
		doclear = TRUE
	}
	if musl_strncmp(line, S("link"), usize(name_end.Sub(line))) == 0 {
		dolink = TRUE
	}

	if doclear == 0 && dolink == 0 && ends_excmd2(line, linep) != 0 {
		id = syn_namen2id(line, int32(name_end.Sub(line)))
		if id == 0 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_highlight_group_name_not_found_str), line)
			emsg(iobuff_or(gettext_(e_highlight_group_name_not_found_str)))
		} else {
			highlight_list_one(id)
		}
		return
	}

	if dolink != 0 {
		var from_start Ptr[byte] = linep
		var from_end Ptr[byte]
		var from_len int32
		var to_start Ptr[byte]
		var to_end Ptr[byte]
		var to_len int32

		from_end = skiptowhite(from_start)
		to_start = skipwhite(from_end)
		to_end = skiptowhite(to_start)

		if ends_excmd2(line, from_start) != 0 || ends_excmd2(line, to_start) != 0 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_not_enough_arguments_highlight_link_str), from_start)
			emsg(iobuff_or(gettext_(e_not_enough_arguments_highlight_link_str)))
			return
		}

		if ends_excmd2(line, skipwhite(to_end)) == 0 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_too_many_arguments_highlight_link_str), from_start)
			emsg(iobuff_or(gettext_(e_too_many_arguments_highlight_link_str)))
			return
		}

		from_len = int32(from_end.Sub(from_start))
		to_len = int32(to_end.Sub(to_start))
		highlight_group_link(from_start, from_len, to_start, to_len, dodefault, forceit, init_)
		return
	}

	if doclear != 0 {
		if ends_excmd2(line, linep) != 0 {
			highlight_reset_all()
			return
		}
		line = linep
		name_end = skiptowhite(line)
		linep = skipwhite(name_end)
	}

	id = syn_check_group(line, int32(name_end.Sub(line)))
	if id == 0 {
		return
	}
	idx = id - 1

	if dodefault != 0 && hl_has_settings(idx, TRUE) != 0 {
		return
	}

	item_before = GaData[hl_group_T](&highlight_ga).At(int(idx))

	if musl_strcmp(GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_name_u, S("NORMAL")) == 0 {
		is_normal_group = TRUE
	}

	if doclear != 0 || (forceit != 0 && init_ != 0) {
		highlight_clear(idx)
		if doclear == 0 {
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_set = 0
		}
	}

	if doclear == 0 {
		for ends_excmd2(line, linep) == 0 {
			key_start = linep
			if linep.Get() == '=' {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_unexpected_equal_sign_str), key_start)
				emsg(iobuff_or(gettext_(e_unexpected_equal_sign_str)))
				error_ = TRUE
				break
			}

			for linep.Get() != 0 && !(linep.Get() == ' ' || linep.Get() == '\t') && linep.Get() != '=' {
				linep = linep.Add(1)
			}
			key = vim_strnsave_up(key_start, usize(linep.Sub(key_start)))
			linep = skipwhite(linep)

			if musl_strcmp(key, S("NONE")) == 0 {
				if init_ == 0 || GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_set == 0 {
					if init_ == 0 {
						GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_set |= SG_TERM + SG_CTERM + SG_GUI
					}
					highlight_clear(idx)
				}
				continue
			}

			if linep.Get() != '=' {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_missing_equal_sign_str_2), key_start)
				emsg(iobuff_or(gettext_(e_missing_equal_sign_str_2)))
				error_ = TRUE
				break
			}
			linep = linep.Add(1)

			linep = skipwhite(linep)
			if linep.Get() == '\'' {
				linep = linep.Add(1)
				arg_start = linep
				linep = vim_strchr(linep, '\'')
				if linep.Nil() {
					vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_argument_str), key_start)
					emsg(iobuff_or(gettext_(e_invalid_argument_str)))
					error_ = TRUE
					break
				}
			} else {
				arg_start = linep
				linep = skiptowhite(linep)
			}
			if linep == arg_start {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_missing_argument_str), key_start)
				emsg(iobuff_or(gettext_(e_missing_argument_str)))
				error_ = TRUE
				break
			}
			arg = vim_strnsave(arg_start, usize(linep.Sub(arg_start)))
			if linep.Get() == '\'' {
				linep = linep.Add(1)
			}

			if musl_strcmp(key, S("TERM")) == 0 || musl_strcmp(key, S("CTERM")) == 0 || musl_strcmp(key, S("GUI")) == 0 {
				if highlight_set_termgui_attr(idx, key, arg, init_) == 0 {
					error_ = TRUE
					break
				}
			} else if musl_strcmp(key, S("FONT")) == 0 {
			} else if musl_strcmp(key, S("CTERMFG")) == 0 || musl_strcmp(key, S("CTERMBG")) == 0 || musl_strcmp(key, S("CTERMUL")) == 0 {
				if highlight_set_cterm_color(idx, key, key_start, arg, is_normal_group, init_) == 0 {
					error_ = TRUE
					break
				}
			} else if musl_strcmp(key, S("CTERMFONT")) == 0 {
				if highlight_set_cterm_font(idx, arg, init_) == 0 {
					error_ = TRUE
					break
				}
			} else if musl_strcmp(key, S("GUIFG")) == 0 {
			} else if musl_strcmp(key, S("GUIBG")) == 0 {
			} else if musl_strcmp(key, S("GUISP")) == 0 {
			} else if musl_strcmp(key, S("START")) == 0 || musl_strcmp(key, S("STOP")) == 0 {
				if highlight_set_startstop_termcode(idx, key, arg, init_) == 0 {
					error_ = TRUE
					break
				}
			} else {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_illegal_argument_str_3), key_start)
				emsg(iobuff_or(gettext_(e_illegal_argument_str_3)))
				error_ = TRUE
				break
			}
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cleared = FALSE

			if init_ == 0 || GaData[hl_group_T](&highlight_ga).At(int(idx)).sg_set&SG_LINK == 0 {
				GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_link = 0
			}

			linep = skipwhite(linep)
		}
	}

	if error_ != 0 && idx == highlight_ga.ga_len {
		syn_unadd_group()
	} else {
		if is_normal_group != 0 {
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_term_attr = 0
			GaData[hl_group_T](&highlight_ga).Ref(int(idx)).sg_cterm_attr = 0
			resolve_fallback_fg_to_rgb()
			resolve_fallback_bg_to_rgb()
		} else {
			set_hl_attr(idx)
		}
	}

	// C: memcmp of the whole struct; hl_group_T is comparable in Go.
	if did_change != 0 || GaData[hl_group_T](&highlight_ga).At(int(idx)) != item_before {
		if updating_screen == 0 {
			redraw_all_later(UPD_NOT_VALID)
		}
		need_highlight_changed = TRUE
	}
}

func restore_cterm_colors() {
	cterm_normal_fg_color = 0
	cterm_normal_fg_bold = 0
	cterm_normal_bg_color = 0
	fallback_fg_rgb = int64(0x1ffffff)
	fallback_bg_rgb = int64(0x1ffffff)
}

func hl_has_settings(idx int32, check_link int32) int32 {
	hl := GaData[hl_group_T](&highlight_ga)
	return B2i(hl.At(int(idx)).sg_cleared == 0 &&
		(hl.At(int(idx)).sg_term_attr != 0 || hl.At(int(idx)).sg_cterm_attr != 0 || hl.At(int(idx)).sg_cterm_fg != 0 || hl.At(int(idx)).sg_cterm_bg != 0 || hl.At(int(idx)).sg_cterm_font != 0 || (check_link != 0 && hl.At(int(idx)).sg_set&SG_LINK != 0)))
}

func highlight_clear(idx int32) {
	hl := GaData[hl_group_T](&highlight_ga).Ref(int(idx))
	hl.sg_cleared = TRUE

	hl.sg_term = 0
	hl.sg_start = Ptr[byte]{}
	hl.sg_stop = Ptr[byte]{}
	hl.sg_term_attr = 0
	hl.sg_cterm = 0
	hl.sg_cterm_bold = FALSE
	hl.sg_cterm_fg = 0
	hl.sg_cterm_bg = 0
	hl.sg_cterm_attr = 0
	hl.sg_cterm_font = 0
	hl.sg_link = hl.sg_deflink
}

func get_attr_entry(table *S_growarray, aep *S_attr_entry) int32 {
	var i int32
	var taep *S_attr_entry

	table.ga_itemsize = 24 // C: sizeof(attrentry_T) on x86-64
	table.ga_growsize = 7

	for i = 0; i < table.ga_len; i++ {
		taep = GaData[S_attr_entry](table).Ref(int(i))
		if aep.ae_attr == taep.ae_attr && ((table == &term_attr_table && (aep.ae_u.term.start.Nil()) == (taep.ae_u.term.start.Nil()) && (aep.ae_u.term.start.Nil() || musl_strcmp(aep.ae_u.term.start, taep.ae_u.term.start) == 0) && (aep.ae_u.term.stop.Nil()) == (taep.ae_u.term.stop.Nil()) && (aep.ae_u.term.stop.Nil() || musl_strcmp(aep.ae_u.term.stop, taep.ae_u.term.stop) == 0)) || (table == &cterm_attr_table && aep.ae_u.cterm.fg_color == taep.ae_u.cterm.fg_color && aep.ae_u.cterm.bg_color == taep.ae_u.cterm.bg_color && aep.ae_u.cterm.ul_color == taep.ae_u.cterm.ul_color && aep.ae_u.cterm.font == taep.ae_u.cterm.font)) {
			return i + (HL_ALL + 1)
		}
	}

	if table.ga_len+(HL_ALL+1) > MAX_TYPENR {
		if get_attr_entry_recursive != 0 {
			emsg(gettext_(e_too_many_different_highlighting_attributes_in_use))
			return 0
		}
		get_attr_entry_recursive = TRUE

		clear_hl_tables()

		set_must_redraw(UPD_CLEAR)

		for i = 0; i < highlight_ga.ga_len; i++ {
			set_hl_attr(i)
		}

		get_attr_entry_recursive = FALSE
	}

	if ga_grow(table, 1) == FAIL {
		return 0
	}

	taep = GaData[S_attr_entry](table).Ref(int(table.ga_len))
	*taep = S_attr_entry{}
	taep.ae_attr = aep.ae_attr
	if table == &term_attr_table {
		if aep.ae_u.term.start.Nil() {
			taep.ae_u.term.start = Ptr[byte]{}
		} else {
			taep.ae_u.term.start = vim_strsave(aep.ae_u.term.start)
		}
		if aep.ae_u.term.stop.Nil() {
			taep.ae_u.term.stop = Ptr[byte]{}
		} else {
			taep.ae_u.term.stop = vim_strsave(aep.ae_u.term.stop)
		}
	} else if table == &cterm_attr_table {
		taep.ae_u.cterm.fg_color = aep.ae_u.cterm.fg_color
		taep.ae_u.cterm.bg_color = aep.ae_u.cterm.bg_color
		taep.ae_u.cterm.ul_color = aep.ae_u.cterm.ul_color
		taep.ae_u.cterm.font = aep.ae_u.cterm.font
	}
	table.ga_len++
	return table.ga_len - 1 + (HL_ALL + 1)
}

func clear_hl_tables() {
	var i int32

	for i = 0; i < term_attr_table.ga_len; i++ {
	}
	ga_clear(&term_attr_table)
	ga_clear(&cterm_attr_table)
}

func hl_combine_attr(char_attr int32, prim_attr int32) int32 {
	var char_aep *S_attr_entry = nil
	var prim_aep *S_attr_entry
	var new_en S_attr_entry

	if char_attr == 0 {
		return prim_attr
	}
	if char_attr <= HL_ALL && prim_attr <= HL_ALL {
		var t int32
		if prim_attr&HL_NOCOMBINE != 0 {
			t = prim_attr
		} else {
			t = char_attr
		}
		return t | prim_attr
	}

	if t_colors > 1 {
		if char_attr > HL_ALL {
			char_aep = syn_cterm_attr2entry(char_attr)
		}
		if char_aep != nil {
			new_en = *char_aep
		} else {
			new_en = S_attr_entry{}
			if char_attr <= HL_ALL {
				new_en.ae_attr = int16(char_attr)
			}
		}

		if prim_attr <= HL_ALL {
			var t int32
			if prim_attr&HL_NOCOMBINE != 0 {
				t = prim_attr
			} else {
				t = int32(new_en.ae_attr)
			}
			new_en.ae_attr = int16(t | prim_attr)
		} else {
			prim_aep = syn_cterm_attr2entry(prim_attr)
			if prim_aep != nil {
				var t int32
				if int32(prim_aep.ae_attr)&HL_NOCOMBINE != 0 {
					t = int32(prim_aep.ae_attr)
				} else {
					t = int32(new_en.ae_attr)
				}
				new_en.ae_attr = int16(t | int32(prim_aep.ae_attr))
				if prim_aep.ae_u.cterm.fg_color > 0 {
					new_en.ae_u.cterm.fg_color = prim_aep.ae_u.cterm.fg_color
				}
				if prim_aep.ae_u.cterm.bg_color > 0 {
					new_en.ae_u.cterm.bg_color = prim_aep.ae_u.cterm.bg_color
				}
				if prim_aep.ae_u.cterm.ul_color > 0 {
					new_en.ae_u.cterm.ul_color = prim_aep.ae_u.cterm.ul_color
				}
				if prim_aep.ae_u.cterm.font > 0 {
					new_en.ae_u.cterm.font = prim_aep.ae_u.cterm.font
				}
			}
		}
		return get_attr_entry(&cterm_attr_table, &new_en)
	}

	if char_attr > HL_ALL {
		char_aep = syn_term_attr2entry(char_attr)
	}
	if char_aep != nil {
		new_en = *char_aep
	} else {
		new_en = S_attr_entry{}
		if char_attr <= HL_ALL {
			new_en.ae_attr = int16(char_attr)
		}
	}

	if prim_attr <= HL_ALL {
		var t int32
		if prim_attr&HL_NOCOMBINE != 0 {
			t = prim_attr
		} else {
			t = int32(new_en.ae_attr)
		}
		new_en.ae_attr = int16(t | prim_attr)
	} else {
		prim_aep = syn_term_attr2entry(prim_attr)
		if prim_aep != nil {
			var t int32
			if int32(prim_aep.ae_attr)&HL_NOCOMBINE != 0 {
				t = int32(prim_aep.ae_attr)
			} else {
				t = int32(new_en.ae_attr)
			}
			new_en.ae_attr = int16(t | int32(prim_aep.ae_attr))
			if !prim_aep.ae_u.term.start.Nil() {
				new_en.ae_u.term.start = prim_aep.ae_u.term.start
				new_en.ae_u.term.stop = prim_aep.ae_u.term.stop
			}
		}
	}
	return get_attr_entry(&term_attr_table, &new_en)
}

func init() {
	cterm_idx_to_rgb_cube = [6]int32{0x00, 0x5F, 0x87, 0xAF, 0xD7, 0xFF}
	rgb_to_cterm_idx_cube = [6]int32{0x00, 0x5F, 0x87, 0xAF, 0xD7, 0xFF}
}

func cterm_idx_to_rgb(idx int32, r *int32, g *int32, b *int32) {
	if idx < 0 || idx > 255 {
		*b = 0
		*g = *b
		*r = *g
		return
	}
	if idx < 16 {
		var rgb long_u = cterm_color_16[idx]
		*r = int32((rgb >> 16) & 0xFF)
		*g = int32((rgb >> 8) & 0xFF)
		*b = int32(rgb & 0xFF)
	} else if idx < 232 {
		var n int32 = idx - 16
		*r = cterm_idx_to_rgb_cube[n/36%6]
		*g = cterm_idx_to_rgb_cube[n/6%6]
		*b = cterm_idx_to_rgb_cube[n%6]
	} else {
		var v int32 = 8 + (idx-232)*10
		*b = v
		*g = *b
		*r = *g
	}
}

func rgb_to_cterm_idx(r int32, g int32, b int32) int32 {
	var best int32 = 0
	var best_d int64 = -1
	var i int32

	for i = 16; i < 232; i++ {
		var n int32 = i - 16
		var cr int32 = rgb_to_cterm_idx_cube[n/36%6]
		var cg int32 = rgb_to_cterm_idx_cube[n/6%6]
		var cb int32 = rgb_to_cterm_idx_cube[n%6]
		var d int64 = int64((cr-r)*(cr-r) + (cg-g)*(cg-g) + (cb-b)*(cb-b))
		if best_d < 0 || d < best_d {
			best_d = d
			best = i
		}
	}
	for i = 232; i < 256; i++ {
		var v int32 = 8 + (i-232)*10
		var d int64 = int64((v-r)*(v-r) + (v-g)*(v-g) + (v-b)*(v-b))
		if d < best_d {
			best_d = d
			best = i
		}
	}
	return best
}

func resolve_color_to_rgb(cterm_c int32, rgb int64, r *int32, g *int32, b *int32) bool {
	if cterm_c > 0 {
		cterm_idx_to_rgb(cterm_c-1, r, g, b)
		return true
	}
	return false
}

func resolve_fallback_color(cterm_c int32, rgb int64, default_rgb int64) int64 {
	var red int32
	var green int32
	var blue int32
	if !resolve_color_to_rgb(cterm_c, rgb, &red, &green, &blue) {
		return default_rgb
	} else {
		return int64((red << 16) | (green << 8) | blue)
	}
}

func resolve_fallback_fg_to_rgb() {
	var fgcolor_or_gui_fgcolor int64 = int64(0x1ffffff)
	var d int64
	if p_bg.Get() == 'l' {
		d = 0x000000
	} else {
		d = 0xFFFFFF
	}
	fallback_fg_rgb = resolve_fallback_color(cterm_normal_fg_color, fgcolor_or_gui_fgcolor, d)
}

func resolve_fallback_bg_to_rgb() {
	var bgcolor_or_gui_bgcolor int64 = int64(0x1ffffff)
	var d int64
	if p_bg.Get() == 'l' {
		d = 0xFFFFFF
	} else {
		d = 0x000000
	}
	fallback_bg_rgb = resolve_fallback_color(cterm_normal_bg_color, bgcolor_or_gui_bgcolor, d)
}

func blend_cterm_colors(popup_c int32, popup_rgb int64, under_c int32, under_rgb int64, default_rgb int32, blend_val int32) int32 {
	var pr int32
	var pg int32
	var pb int32
	var ur int32
	var ug int32
	var ub int32
	var r int32
	var g int32
	var b int32

	if t_colors < 256 {
		return popup_c
	}
	if !resolve_color_to_rgb(popup_c, popup_rgb, &pr, &pg, &pb) {
		return under_c
	}
	if blend_val <= 0 {
		return rgb_to_cterm_idx(pr, pg, pb) + 1
	}
	if !resolve_color_to_rgb(under_c, under_rgb, &ur, &ug, &ub) {
		ur = (default_rgb >> 16) & 0xFF
		ug = (default_rgb >> 8) & 0xFF
		ub = default_rgb & 0xFF
	}
	if blend_val >= 100 {
		return rgb_to_cterm_idx(ur, ug, ub) + 1
	}
	r = pr + (ur-pr)*blend_val/100
	g = pg + (ug-pg)*blend_val/100
	b = pb + (ub-pb)*blend_val/100
	return rgb_to_cterm_idx(r, g, b) + 1
}

func hl_blend_attr_common(char_attr int32, popup_attr int32, blend int32, blend_fg int32) int32 {
	var char_aep *S_attr_entry = nil
	var popup_aep *S_attr_entry
	var new_en S_attr_entry
	var tmp_en S_attr_entry

	if t_colors > 1 {
		if char_attr > HL_ALL {
			char_aep = syn_cterm_attr2entry(char_attr)
		}
		if char_aep != nil {
			new_en = *char_aep
		} else {
			new_en = S_attr_entry{}
			if char_attr <= HL_ALL {
				new_en.ae_attr = int16(char_attr)
			}
		}

		if popup_attr <= HL_ALL {
			tmp_en = S_attr_entry{}
			tmp_en.ae_attr = int16(popup_attr)
			popup_aep = &tmp_en

			popup_aep.ae_u.cterm.bg_color = short_u(cterm_normal_bg_color)
		} else {
			popup_aep = syn_cterm_attr2entry(popup_attr)
		}

		if popup_aep != nil {
			var popup_bg_rgb int64 = int64(0x1ffffff)
			if (popup_bg_rgb == int64(0x1ffffff) || popup_bg_rgb == int64(0x1fffffe)) && popup_aep.ae_u.cterm.bg_color == 0 {
				popup_bg_rgb = fallback_bg_rgb
			}

			if blend_fg == 0 {
				new_en.ae_attr = popup_aep.ae_attr
				if popup_aep.ae_u.cterm.fg_color > 0 {
					new_en.ae_u.cterm.fg_color = popup_aep.ae_u.cterm.fg_color
				} else if cterm_normal_fg_color > 0 {
					new_en.ae_u.cterm.fg_color = short_u(cterm_normal_fg_color)
				} else {
					if p_bg.Get() == 'l' {
						new_en.ae_u.cterm.fg_color = 1
					} else {
						new_en.ae_u.cterm.fg_color = 16
					}
				}
				new_en.ae_u.cterm.ul_color = popup_aep.ae_u.cterm.ul_color
				new_en.ae_u.cterm.font = popup_aep.ae_u.cterm.font
			} else {
				var under_fg int32
				if char_aep != nil {
					under_fg = int32(char_aep.ae_u.cterm.fg_color)
				} else {
					under_fg = 0
				}
				var under_fg_rgb int64 = int64(0x1ffffff)
				new_en.ae_u.cterm.fg_color = short_u(blend_cterm_colors(int32(popup_aep.ae_u.cterm.bg_color), popup_bg_rgb, under_fg, under_fg_rgb, int32(fallback_fg_rgb), blend))
			}
			{
				var under_bg int32
				if char_aep != nil {
					under_bg = int32(char_aep.ae_u.cterm.bg_color)
				} else {
					under_bg = 0
				}
				var under_bg_rgb int64 = int64(0x1ffffff)
				new_en.ae_u.cterm.bg_color = short_u(blend_cterm_colors(int32(popup_aep.ae_u.cterm.bg_color), popup_bg_rgb, under_bg, under_bg_rgb, int32(fallback_bg_rgb), blend))
			}
		}
		return get_attr_entry(&cterm_attr_table, &new_en)
	}

	if char_attr > HL_ALL {
		char_aep = syn_term_attr2entry(char_attr)
	}
	if char_aep != nil {
		new_en = *char_aep
	} else {
		new_en = S_attr_entry{}
		if char_attr <= HL_ALL {
			new_en.ae_attr = int16(char_attr)
		}
	}

	return get_attr_entry(&term_attr_table, &new_en)
}

func hl_blend_attr(char_attr int32, popup_attr int32, blend int32, blend_fg int32) int32 {
	if blend >= 100 && blend_fg != 0 {
		return char_attr
	}

	return hl_blend_attr_common(char_attr, popup_attr, blend, blend_fg)
}

func hl_pum_blend_attr(char_attr int32, popup_attr int32, blend int32) int32 {
	return hl_blend_attr_common(char_attr, popup_attr, blend, TRUE)
}

func syn_attr2attr(attr int32) int32 {
	var aep *S_attr_entry

	if t_colors > 1 {
		aep = syn_cterm_attr2entry(attr)
	} else {
		aep = syn_term_attr2entry(attr)
	}

	if aep == nil {
		return 0
	}
	return int32(aep.ae_attr)
}

func syn_term_attr2entry(attr int32) *S_attr_entry {
	attr -= (HL_ALL + 1)
	if attr >= term_attr_table.ga_len {
		return nil
	}
	return GaData[S_attr_entry](&term_attr_table).Ref(int(attr))
}

func syn_cterm_attr2entry(attr int32) *S_attr_entry {
	attr -= (HL_ALL + 1)
	if attr >= cterm_attr_table.ga_len {
		return nil
	}
	return GaData[S_attr_entry](&cterm_attr_table).Ref(int(attr))
}

func highlight_list_one(id int32) {
	var sgp *hl_group_T
	var didh int32 = FALSE

	sgp = GaData[hl_group_T](&highlight_ga).Ref(int(id - 1))

	if message_filtered(sgp.sg_name) != 0 {
		return
	}

	didh = highlight_list_arg(id, didh, LIST_ATTR, sgp.sg_term, Ptr[byte]{}, S("term"))
	didh = highlight_list_arg(id, didh, LIST_STRING, 0, sgp.sg_start, S("start"))
	didh = highlight_list_arg(id, didh, LIST_STRING, 0, sgp.sg_stop, S("stop"))

	didh = highlight_list_arg(id, didh, LIST_ATTR, sgp.sg_cterm, Ptr[byte]{}, S("cterm"))
	didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_fg, Ptr[byte]{}, S("ctermfg"))
	didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_bg, Ptr[byte]{}, S("ctermbg"))
	didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_ul, Ptr[byte]{}, S("ctermul"))
	didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_font, Ptr[byte]{}, S("ctermfont"))

	if sgp.sg_link != 0 && got_int == 0 {
		_ = syn_list_header(didh, 9999, id)
		didh = TRUE
		msg_puts_attr(S("links to"), highlight_attr[int(HLF_D)])
		msg_putchar(' ')
		hl := GaData[hl_group_T](&highlight_ga)
		msg_outtrans(hl.At(int(hl.At(int(id-1)).sg_link - 1)).sg_name)
	}

	if didh == 0 {
		highlight_list_arg(id, didh, LIST_STRING, 0, S("cleared"), S(""))
	}
}

func highlight_arg_to_string(type_ int32, iarg int32, sarg Ptr[byte], buf Ptr[byte]) Ptr[byte] {
	if type_ == LIST_INT {
		vim_snprintf(buf, MAX_ATTR_LEN, S("%d"), iarg-1)
	} else if type_ == LIST_STRING {
		return sarg
	} else {
		var buflen usize

		buf.Set(0, NUL)
		buflen = 0
		for i := int32(0); i < int32(len(highlight_index_tab)); i++ {
			if iarg&highlight_index_tab[i].key != 0 {
				if buflen > 0 {
					musl_strcpy(buf.Add(int(buflen)), S(","))
					buflen++
				}
				musl_strcpy(buf.Add(int(buflen)), highlight_index_tab[i].value.string_)
				buflen += highlight_index_tab[i].value.length
				iarg &= ^highlight_index_tab[i].key
			}
		}
	}
	return buf
}

func highlight_list_arg(id int32, didh int32, type_ int32, iarg int32, sarg Ptr[byte], name Ptr[byte]) int32 {
	var buf Ptr[byte] = Mk[byte](MAX_ATTR_LEN)
	var ts Ptr[byte]

	if got_int != 0 {
		return FALSE
	}

	var skip bool
	if type_ == LIST_STRING {
		skip = sarg.Nil()
	} else {
		skip = iarg == 0
	}
	if skip {
		return didh
	}

	ts = highlight_arg_to_string(type_, iarg, sarg, buf)

	_ = syn_list_header(didh, int32(usize(vim_strsize(ts))+musl_strlen(name)+1), id)
	didh = TRUE
	if got_int == 0 {
		if name.Get() != NUL {
			msg_puts_attr(name, highlight_attr[int(HLF_D)])
			msg_puts_attr(S("="), highlight_attr[int(HLF_D)])
		}
		msg_outtrans(ts)
	}
	return didh
}

func syn_list_header(did_header int32, outlen int32, id int32) int32 {
	var endcol int32 = 19
	var newline int32 = TRUE
	var name_col int32 = 0

	if did_header == 0 {
		msg_putchar('\n')
		if got_int != 0 {
			return TRUE
		}
		msg_outtrans(GaData[hl_group_T](&highlight_ga).At(int(id - 1)).sg_name)
		name_col = msg_col
		endcol = 15
	} else if msg_col+outlen+1 >= cmdline_width {
		msg_putchar('\n')
		if got_int != 0 {
			return TRUE
		}
	} else {
		if msg_col >= endcol {
			newline = FALSE
		}
	}

	if msg_col >= endcol {
		endcol = msg_col + 1
	}
	if cmdline_width <= endcol {
		endcol = cmdline_width - 1
	}

	msg_advance(endcol)

	if did_header == 0 {
		if endcol == cmdline_width-1 && endcol <= name_col {
			msg_putchar(' ')
		}
		msg_puts_attr(S("xxx"), syn_id2attr(id))
		msg_putchar(' ')
	}

	return newline
}

func set_hl_attr(idx int32) {
	var at_en S_attr_entry
	var sgp *hl_group_T = GaData[hl_group_T](&highlight_ga).Ref(int(idx))

	if !sgp.sg_name_u.Nil() && musl_strcmp(sgp.sg_name_u, S("NORMAL")) == 0 {
		return
	}

	if sgp.sg_start.Nil() && sgp.sg_stop.Nil() {
		sgp.sg_term_attr = sgp.sg_term
	} else {
		at_en.ae_attr = int16(sgp.sg_term)
		at_en.ae_u.term.start = sgp.sg_start
		at_en.ae_u.term.stop = sgp.sg_stop
		sgp.sg_term_attr = get_attr_entry(&term_attr_table, &at_en)
	}

	if sgp.sg_cterm_fg == 0 && sgp.sg_cterm_bg == 0 && sgp.sg_cterm_ul == 0 && sgp.sg_cterm_font == 0 {
		sgp.sg_cterm_attr = sgp.sg_cterm
	} else {
		at_en.ae_attr = int16(sgp.sg_cterm)
		at_en.ae_u.cterm.fg_color = short_u(sgp.sg_cterm_fg)
		at_en.ae_u.cterm.bg_color = short_u(sgp.sg_cterm_bg)
		at_en.ae_u.cterm.ul_color = short_u(sgp.sg_cterm_ul)
		at_en.ae_u.cterm.font = short_u(sgp.sg_cterm_font)
		sgp.sg_cterm_attr = get_attr_entry(&cterm_attr_table, &at_en)
	}
}

func syn_override(id int32) int32 {
	if overrides != nil && !overrides.arr.Nil() {
		for k := int32(0); k < overrides.len_; k++ {
			if overrides.arr.At(int(k)).from == id {
				return overrides.arr.At(int(k)).to
			}
		}
	}
	return id
}

func syn_name2id_len(name Ptr[byte], len_ int32) int32 {
	var name_u Ptr[byte] = Mk[byte](MAX_SYN_NAME + 1)
	var i int32

	if len_ > MAX_SYN_NAME {
		len_ = MAX_SYN_NAME
	}
	Memmove(name_u, name, int(len_))
	name_u.Set(int(len_), NUL)
	vim_strup(name_u)
	for i = 0; i < highlight_ga.ga_len; i++ {
		if musl_strcmp(GaData[hl_group_T](&highlight_ga).At(int(i)).sg_name_u, name_u) == 0 {
			return i + 1
		}
	}
	return 0
}

func syn_namen2id(linep Ptr[byte], len_ int32) int32 {
	return syn_name2id_len(linep, len_)
}

func syn_check_group(pp Ptr[byte], len_ int32) int32 {
	var id int32
	var name Ptr[byte]

	if len_ > MAX_SYN_NAME {
		emsg(gettext_(e_highlight_group_name_too_long))
		return 0
	}
	id = syn_name2id_len(pp, len_)
	if id == 0 {
		name = vim_strnsave(pp, usize(len_))
		id = syn_add_group(name)
	}
	return id
}

func syn_add_group(name Ptr[byte]) int32 {
	var p Ptr[byte]
	var name_up Ptr[byte]

	for p = name; p.Get() != NUL; p = p.Add(1) {
		c := uint32(p.Get())
		if vim_isprintc(int32(p.Get())) == 0 {
			emsg(gettext_(e_unprintable_character_in_group_name))
			return 0
		} else if !((c-'A' < 26 || c-'a' < 26) || c-'0' < 10) && p.Get() != '_' && p.Get() != '.' && p.Get() != '-' {
			msg_source(highlight_attr[int(HLF_W)])
			msg(gettext_(S("W18: Invalid character in group name")))
			break
		}
	}

	if highlight_ga.ga_data == nil {
		highlight_ga.ga_itemsize = 88 // C: sizeof(hl_group_T) on x86-64
		highlight_ga.ga_growsize = 10
	}

	if highlight_ga.ga_len >= MAX_HL_ID {
		emsg(gettext_(e_too_many_highlight_and_syntax_groups))
		return 0
	}

	if ga_grow(&highlight_ga, 1) == FAIL {
		return 0
	}

	name_up = vim_strsave(name)
	vim_strup(name_up)

	hl := GaData[hl_group_T](&highlight_ga)
	*hl.Ref(int(highlight_ga.ga_len)) = hl_group_T{}
	hl.Ref(int(highlight_ga.ga_len)).sg_name = name
	hl.Ref(int(highlight_ga.ga_len)).sg_name_u = name_up
	highlight_ga.ga_len++

	return highlight_ga.ga_len
}

func syn_unadd_group() {
	highlight_ga.ga_len--
}

func syn_id2attr(hl_id int32) int32 {
	var attr int32
	var sgp *hl_group_T

	hl_id = syn_get_final_id(hl_id)
	sgp = GaData[hl_group_T](&highlight_ga).Ref(int(hl_id - 1))

	if t_colors > 1 {
		attr = sgp.sg_cterm_attr
	} else {
		attr = sgp.sg_term_attr
	}

	return attr
}

func syn_get_final_id(hl_id int32) int32 {
	var count int32
	var sgp *hl_group_T

	if hl_id > highlight_ga.ga_len || hl_id < 1 {
		return 0
	}

	for count = 100; ; {
		count--
		if !(count >= 0) {
			break
		}
		var tmp int32 = hl_id

		sgp = GaData[hl_group_T](&highlight_ga).Ref(int(hl_id - 1))
		if sgp.sg_link == 0 || sgp.sg_link > highlight_ga.ga_len {
			break
		}

		hl_id = syn_override(hl_id)
		if tmp != hl_id {
			continue
		}
		hl_id = sgp.sg_link
	}
	return syn_override(hl_id)
}

func highlight_changed() int32 {
	var hlf int32
	var i int32
	var p Ptr[byte]
	var default_hl Ptr[byte]
	var attr int32
	var end Ptr[byte]
	var id int32
	var wp *S_window_S

	need_highlight_changed = FALSE

	for hlf = 0; hlf < int32(HLF_COUNT); hlf++ {
		highlight_attr[hlf] = 0
		highlight_attr_raw[hlf] = 0
		highlight_ids[hlf] = 0
	}

	default_hl = get_highlight_default()

	for i = 0; i < 2; i++ {
		if i != 0 {
			if !default_hl.Nil() && !p_hl.Nil() && musl_strcmp(default_hl, p_hl) == 0 {
				continue
			}
			p = p_hl
		} else {
			p = default_hl
		}
		if p.Nil() {
			continue
		}

		for p.Get() != 0 {
			for hlf = 0; hlf < int32(HLF_COUNT); hlf++ {
				if hl_flags[hlf] == int32(p.Get()) {
					break
				}
			}
			p = p.Add(1)
			if hlf == int32(HLF_COUNT) || p.Get() == NUL {
				return FAIL
			}

			attr = 0
			id = 0
			for ; p.Get() != 0 && p.Get() != ','; p = p.Add(1) {
				if p.Get() == ' ' || p.Get() == '\t' {
					continue
				}

				if attr > HL_ALL {
					return FAIL
				}

				switch p.Get() {
				case 'b':
					attr |= HL_BOLD
				case 'i':
					attr |= HL_ITALIC
				case '-', 'n':
				case 'r':
					attr |= HL_INVERSE
				case 's':
					attr |= HL_STANDOUT
				case 'u':
					attr |= HL_UNDERLINE
				case 'c':
					attr |= HL_UNDERCURL
				case '2':
					attr |= HL_UNDERDOUBLE
				case 'd':
					attr |= HL_UNDERDOTTED
				case '=':
					attr |= HL_UNDERDASHED
				case 't':
					attr |= HL_STRIKETHROUGH
				case ':':
					p = p.Add(1)
					if attr != 0 || p.Get() == NUL {
						return FAIL
					}
					end = vim_strchr(p, ',')
					if end.Nil() {
						end = p.Add(int(musl_strlen(p)))
					}
					id = syn_check_group(p, int32(end.Sub(p)))
					if id == 0 {
						return FAIL
					}
					attr = syn_id2attr(id)
					p = end.Add(-1)
				default:
					return FAIL
				}
			}
			highlight_attr[hlf] = attr
			highlight_attr_raw[hlf] = attr
			highlight_ids[hlf] = id

			p = skip_to_option_part(p)
		}
	}

	wp = curwin
	var errmsg Ptr[byte] = update_winhighlight(wp, wp.w_onebuf_opt.wo_whl)

	if !errmsg.Nil() {
		emsg(gettext_(errmsg))
	}

	return OK
}

func update_highlight_overrides(old Ptr[hl_override_T], hl_new Ptr[hl_override_T], newlen int32) {
	if old.Nil() {
		return
	}

	for set := overrides; set != nil; set = set.next {
		if set.arr == old {
			set.arr = hl_new
			set.len_ = newlen
		}
	}
}

func set_highlight_attr(arr Ptr[hl_override_T], len_ int32, update_ids bool) {
	for i := int32(0); i < len_; i++ {
		var override *hl_override_T = arr.Ref(int(i))
		var hlf int32 = -1
		var attr int32

		if override.from <= 0 {
			hlf = -override.from
		} else {
			for k := int32(0); k < HLF_COUNT; k++ {
				if override.from == highlight_ids[k] {
					hlf = k
					break
				}
			}

			if hlf == -1 {
				continue
			}
		}

		if update_ids {
			if override.to <= 0 {
				if hlf == -override.to {
					highlight_ids[hlf] = -1
				} else {
					highlight_ids[hlf] = highlight_ids[-override.to]
				}
			} else {
				highlight_ids[hlf] = override.to
			}
		} else {
			if override.to <= 0 {
				attr = highlight_attr[-override.to]
			} else {
				attr = syn_id2attr(override.to)
			}

			highlight_attr[hlf] = attr
		}
	}
}

func push_highlight_overrides(arr Ptr[hl_override_T], len_ int32) bool {
	if overrides != nil && overrides.arr == arr {
		return false
	}

	var set *S_hl_overrides_S

	set = new(S_hl_overrides_S)

	set.arr = arr
	set.len_ = len_

	set.next = overrides
	overrides = set

	set.attr = highlight_attr

	highlight_attr = highlight_attr_raw

	if !arr.Nil() {
		set_highlight_attr(arr, len_, false)
	}

	return true
}

func pop_highlight_overrides() {
	var set *S_hl_overrides_S = overrides

	if overrides == nil {
		return
	}

	overrides = set.next

	highlight_attr = set.attr
}

func parse_winhighlight(opt Ptr[byte], len_ *int32, errmsg *Ptr[byte]) Ptr[hl_override_T] {
	var p Ptr[byte] = opt
	var arr Ptr[hl_override_T]
	var i int32 = 0
	var num int32 = 1
	var n_colons int32 = 0

	if p.Get() == NUL {
		return Ptr[hl_override_T]{}
	}

	for {
		p = vim_strchr(p, ',')
		if p.Nil() {
			break
		}
		p = p.Add(1)
		num++
	}
	p = opt
	for {
		p = vim_strchr(p, ':')
		if p.Nil() {
			break
		}
		p = p.Add(1)
		n_colons++
	}

	if num != n_colons {
		*errmsg = e_invalid_argument
		return Ptr[hl_override_T]{}
	}

	arr = Mk[hl_override_T](int(num))

	p = opt

	for true {
		var override *hl_override_T = arr.Ref(int(i))
		i++
		var fromname Ptr[byte] = p
		var toname Ptr[byte]
		var tmp Ptr[byte]
		var names [2]*Ptr[byte] = [2]*Ptr[byte]{&fromname, &toname}
		var fromlen int32
		var tolen int32
		var lens [2]*int32 = [2]*int32{&fromlen, &tolen}
		var fromid int32
		var toid int32
		var ids [2]*int32 = [2]*int32{&fromid, &toid}

		p = vim_strchr(p, ':')

		if p.Nil() {
			goto fail
		}

		fromlen = int32(p.Sub(fromname))
		if fromlen == 0 {
			goto fail
		}
		p = p.Add(1)
		if p.Get() == NUL {
			goto fail
		}

		toname = p
		tmp = vim_strchr(p, ',')

		if tmp.Nil() {
			tolen = int32(musl_strlen(p))
		} else {
			tolen = int32(tmp.Sub(toname))
			tmp = tmp.Add(1)
			p = tmp
		}
		if tolen == 0 {
			goto fail
		}

		for k := 0; k < 2; k++ {
			var name Ptr[byte] = *names[k]
			var nlen int32 = *lens[k]

			if name.Get() == '!' {
				var hlf int32

				if nlen != 2 {
					goto fail
				}

				for hlf = 0; hlf < int32(HLF_COUNT); hlf++ {
					if hl_flags[hlf] == int32(name.At(1)) {
						break
					}
				}

				if hlf >= HLF_COUNT {
					goto fail
				}

				*ids[k] = -hlf
			} else {
				if syn_check_group(name, nlen) == 0 {
					goto fail
				}

				*ids[k] = syn_namen2id(name, nlen)
				if *ids[k] == 0 {
					goto fail
				}

				if ids[k] == &fromid && musl_strcmp(GaData[hl_group_T](&highlight_ga).At(int(*ids[k]-1)).sg_name_u, S("NORMAL")) == 0 {
					*ids[k] = -HLF_WIN
				}
			}
		}

		override.from = fromid
		override.to = toid

		if tmp.Nil() {
			break
		}
	}

	*len_ = num
	return arr
fail:
	*errmsg = e_invalid_argument
	return Ptr[hl_override_T]{}
}

func update_winhighlight(wp *S_window_S, opt Ptr[byte]) Ptr[byte] {
	var err Ptr[byte] = Ptr[byte]{}
	var arr Ptr[hl_override_T]
	var num int32 = 1

	arr = parse_winhighlight(opt, &num, &err)

	if arr.Nil() && !err.Nil() {
		return err
	}

	if arr.Nil() && wp.w_hl.Nil() {
		return Ptr[byte]{}
	}

	update_highlight_overrides(wp.w_hl, arr, num)

	wp.w_hl = arr
	wp.w_hl_len = num

	wp.w_hlfwin_id = hlf_get_id(wp, HLF_WIN)

	return Ptr[byte]{}
}

func hlf_get_id(wp *S_window_S, hlf int32) int32 {
	var id int32

	if wp.w_hl.Nil() {
		return highlight_ids[hlf]
	}

	hlf_get_id_prev = highlight_ids
	set_highlight_attr(wp.w_hl, wp.w_hl_len, true)
	id = highlight_ids[hlf]
	highlight_ids = hlf_get_id_prev

	return id
}

func update_wincolor(wp *S_window_S, opt Ptr[byte]) Ptr[byte] {
	var str Ptr[byte]
	if opt.Get() == NUL {
		str = S("")
	} else {
		str = Alloc(int(4 + musl_strlen(opt)))
	}
	var errmsg Ptr[byte]

	if str.Nil() {
		return e_out_of_memory
	}

	if opt.Get() != NUL {
		vim_snprintf(str, 4+musl_strlen(opt), S("!(:%s"), opt)
	}

	errmsg = update_winhighlight(wp, str)

	if errmsg.Nil() {
		set_string_option_direct_in_win(wp, S("winhighlight"), -1, str, OPT_FREE|OPT_LOCAL, 0)
	}

	return errmsg
}

