// ==== from f08.go ====
// Transpiled by hand from editor.c: ml_add_stack .. extract_modifiers.

func init() {
	msg_attr_keep_entered = 0
	msg_source_recursive = FALSE
	do_more_prompt_entered = FALSE
	vim_beep_did_init = FALSE
}

func ml_add_stack(buf *S_file_buffer) int32 {
	var top int32
	var newstack Ptr[infoptr_T]

	top = buf.b_ml.ml_stack_top

	if top == buf.b_ml.ml_stack_size {
		newstack = Mk[infoptr_T](int(buf.b_ml.ml_stack_size + STACK_INCR))
		if top > 0 {
			Memmove(newstack, buf.b_ml.ml_stack, int(top))
		}
		buf.b_ml.ml_stack = newstack
		buf.b_ml.ml_stack_size += STACK_INCR
	}

	buf.b_ml.ml_stack_top++
	return top
}

func ml_lineadd(buf *S_file_buffer, count int32) {
	var idx int32
	var ip *infoptr_T
	var pp *PTR_BL
	var hp *bhdr_T

	for idx = buf.b_ml.ml_stack_top - 1; idx >= 0; idx-- {
		ip = buf.b_ml.ml_stack.Ref(int(idx))
		hp = ip.ip_block
		pp = hp.bh_ptr
		if int32(hp.bh_id) != ('p'<<8)+'t' {
			iemsg(e_pointer_block_id_wrong_two)
			break
		}
		pp.pb_pointer[ip.ip_index].pe_line_count += linenr_T(count)
		ip.ip_high += linenr_T(count)
	}
}

func msg(s Ptr[byte]) int32 {
	return msg_attr_keep(s, 0, FALSE)
}

func msg_attr(s Ptr[byte], attr int32) int32 {
	return msg_attr_keep(s, attr, FALSE)
}

func msg_attr_keep(s Ptr[byte], attr int32, keep int32) int32 {
	var retval int32
	var buf Ptr[byte] = Ptr[byte]{}

	if emsg_on_display == 0 && message_filtered(s) != 0 {
		return TRUE
	}

	if msg_attr_keep_entered >= 3 {
		return TRUE
	}
	msg_attr_keep_entered++

	if s != keep_msg || (s.Get() != '<' && last_msg_hist != nil && !last_msg_hist.msg.Nil() && musl_strcmp(s, last_msg_hist.msg) != 0) {
		add_msg_hist(s, -1, attr)
	}

	msg_start()
	buf = msg_strtrunc(s, FALSE)
	if !buf.Nil() {
		s = buf
	}

	msg_outtrans_attr(s, attr)
	msg_clr_eos()
	retval = msg_end()

	if keep != 0 && retval != 0 && vim_strsize(s) < int32(Rows-int64(cmdline_row)-1)*cmdline_width+sc_col {
		set_keep_msg(s, 0)
	}

	need_fileinfo = FALSE

	msg_attr_keep_entered--
	return retval
}

func msg_strtrunc(s Ptr[byte], force int32) Ptr[byte] {
	var buf Ptr[byte] = Ptr[byte]{}
	var len_ int32
	var room int32

	if (msg_scroll == 0 && need_wait_return == 0 && shortmess(SHM_TRUNCALL) != 0 && msg_silent == 0) || force != 0 {
		len_ = vim_strsize(s)
		if msg_scrolled != 0 {
			room = int32(Rows-int64(msg_row))*cmdline_width - 1
		} else {
			room = int32(Rows-int64(msg_row)-1)*cmdline_width + sc_col - 1
		}
		if len_ > room && room > 0 {
			len_ = (room + 2) * 18
			buf = Alloc(int(len_))
			trunc_string(s, buf, room, len_)
		}
	}
	return buf
}

func trunc_string(s Ptr[byte], buf Ptr[byte], room_in int32, buflen int32) {
	var room usize = usize(room_in - 3)
	var half usize
	var len_ usize = 0
	var e int32
	var i int32
	var n int32

	if s.Get() == NUL {
		if buflen > 0 {
			buf.Put(NUL)
		}
		return
	}

	if room_in < 3 {
		room = 0
	}
	half = room / 2

	for e = 0; len_ < half && e < buflen; e++ {
		if s.At(int(e)) == NUL {
			buf.Set(int(e), NUL)
			return
		}
		n = ptr2cells(s.Add(int(e)))
		if len_+usize(n) > half {
			break
		}
		len_ += usize(n)
		buf.Set(int(e), s.At(int(e)))
		for n = utfc_ptr2len(s.Add(int(e))); ; {
			n--
			if !(n > 0) {
				break
			}
			e++
			if e == buflen {
				break
			}
			buf.Set(int(e), s.At(int(e)))
		}
	}

	i = e
	i = int32(musl_strlen(s))
	half = usize(i)
	for {
		for {
			half = half - usize(utf_head_off(s, s.Add(int(half)-1))) - 1
			if !(half > 0 && utf_iscomposing(utf_ptr2char(s.Add(int(half)))) != 0) {
				break
			}
		}
		n = ptr2cells(s.Add(int(half)))
		if len_+usize(n) > room || half == 0 {
			break
		}
		len_ += usize(n)
		i = int32(half)
	}

	if i <= e+3 {
		if s != buf {
			len_ = musl_strlen(s)
			if len_ >= usize(buflen) {
				len_ = usize(buflen - 1)
			}
			len_ = len_ - usize(e) + 1
			if len_ < 1 {
				buf.Set(int(e-1), NUL)
			} else {
				Memmove(buf.Add(int(e)), s.Add(int(e)), int(len_))
			}
		}
	} else if e+3 < buflen {
		Memmove(buf.Add(int(e)), S("..."), 3)
		len_ = musl_strlen(s.Add(int(i))) + 1
		if len_ >= usize(buflen)-usize(e)-3 {
			len_ = usize(buflen - e - 3 - 1)
		}
		Memmove(buf.Add(int(e+3)), s.Add(int(i)), int(len_))
		buf.Set(int(usize(e)+3+len_-1), NUL)
	} else {
		buf.Set(int(buflen-1), NUL)
	}
}

func iobuff_room() usize {
	if IObuff.Nil() {
		return 0
	}
	return 1024 + 1
}

func emsg_iobuff_room() usize {
	if IObuff.Nil() || emsg_not_now() != 0 {
		return 0
	}
	return 1024 + 1
}

func iobuff_or(s Ptr[byte]) Ptr[byte] {
	if IObuff.Nil() {
		return s
	}
	return IObuff
}

func safelen_result(str Ptr[byte], str_m usize, str_l int32) usize {
	if str_m == 0 {
		return 0
	}
	if str_l < 0 {
		str.Put(NUL)
		return 0
	}
	if usize(str_l) >= str_m {
		return str_m - 1
	}
	return usize(str_l)
}

func append_room(str Ptr[byte], str_m usize) usize {
	var len_ usize = musl_strlen(str)

	if str_m <= len_ {
		return 0
	}
	return str_m - len_
}

func reset_last_sourcing() {
	last_sourcing_name = Ptr[byte]{}
	last_sourcing_lnum = 0
}

func other_sourcing_name() int32 {
	if (exestack.ga_data != nil && exestack.ga_len > 0) && !GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name.Nil() {
		if !last_sourcing_name.Nil() {
			return B2i(musl_strcmp(GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name, last_sourcing_name) != 0)
		}
		return TRUE
	}
	return FALSE
}

func get_emsg_source() Ptr[byte] {
	var Buf Ptr[byte]
	var p Ptr[byte]

	if (exestack.ga_data != nil && exestack.ga_len > 0) && !GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name.Nil() && other_sourcing_name() != 0 {
		var sname Ptr[byte] = estack_sfile(ESTACK_NONE)

		if sname.Nil() {
			sname = GaData[estack_T](&exestack).At(int(exestack.ga_len - 1)).es_name
		}

		p = gettext_(S("Error detected while processing %s:"))
		Buf = Alloc(int(musl_strlen(sname) + musl_strlen(p)))
		vim_snprintf(Buf, musl_strlen(sname)+musl_strlen(p), p, sname)
		return Buf
	}
	return Ptr[byte]{}
}

func get_emsg_lnum() Ptr[byte] {
	var Buf Ptr[byte]
	var p Ptr[byte]

	if !GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name.Nil() && (other_sourcing_name() != 0 || GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_lnum != int64(last_sourcing_lnum)) && GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_lnum != 0 {
		p = gettext_(S("line %4ld:"))
		Buf = Alloc(int(musl_strlen(p) + 20))
		vim_snprintf(Buf, musl_strlen(p)+20, p, int64(GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_lnum))
		return Buf
	}
	return Ptr[byte]{}
}

func msg_source(attr int32) {
	var p Ptr[byte]

	if msg_source_recursive != 0 {
		return
	}
	msg_source_recursive = TRUE

	no_wait_return++
	p = get_emsg_source()
	if !p.Nil() {
		msg_scroll = TRUE
		msg_attr(p, attr)
	}
	p = get_emsg_lnum()
	if !p.Nil() {
		msg_attr(p, highlight_attr[HLF_N])
		last_sourcing_lnum = int32(GaData[estack_T](&exestack).At(int(exestack.ga_len - 1)).es_lnum)
	}

	if GaData[estack_T](&exestack).At(int(exestack.ga_len-1)).es_name.Nil() || other_sourcing_name() != 0 {
		last_sourcing_name = Ptr[byte]{}
		if !GaData[estack_T](&exestack).At(int(exestack.ga_len - 1)).es_name.Nil() {
			last_sourcing_name = vim_strsave(GaData[estack_T](&exestack).At(int(exestack.ga_len - 1)).es_name)
		}
	}
	no_wait_return--

	msg_source_recursive = FALSE
}

func emsg_not_now() int32 {
	if emsg_off > 0 {
		return TRUE
	}
	return FALSE
}

func emsg_core(s Ptr[byte]) int32 {
	var attr int32
	var p Ptr[byte]
	var r int32

	called_emsg++

	if emsg_off == 0 {
		if emsg_silent != 0 {
			if emsg_noredir == 0 {
				msg_start()
				p = get_emsg_source()
				if !p.Nil() {
					musl_strcat(p, S("\n"))
				}
				p = get_emsg_lnum()
				if !p.Nil() {
					musl_strcat(p, S("\n"))
				}
			}
			return TRUE
		}

		msg_silent = 0
		cmd_silent = FALSE

		if global_busy != 0 {
			global_busy++
		}

		if p_eb != 0 {
			beep_flush()
		} else {
			flush_buffers(FLUSH_MINIMAL)
		}
		did_emsg++
	}

	emsg_on_display = TRUE

	attr = highlight_attr[HLF_E]
	if msg_scrolled != 0 {
		need_wait_return = TRUE
	}

	msg_scroll = TRUE
	msg_source(attr)

	msg_nowait = FALSE
	r = msg_attr(s, attr)

	return r
}

func emsg(s Ptr[byte]) int32 {
	if emsg_not_now() != 0 {
		return TRUE
	}

	return emsg_core(s)
}

func iemsg(s Ptr[byte]) {
	if emsg_not_now() != 0 {
		return
	}

	emsg_core(gettext_(e_internal_error_please_report_a_bug))

	emsg_core(s)
}

func internal_error(where Ptr[byte]) {
	emsg_core(gettext_(e_internal_error_please_report_a_bug))

	vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_internal_error_str), where)
	iemsg(iobuff_or(gettext_(e_internal_error_str)))
}

func emsg_invreg(name int32) {
	vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_register_name_str), transchar_buf(nil, name))
	emsg(iobuff_or(gettext_(e_invalid_register_name_str)))
}

func msg_trunc_attr(s Ptr[byte], force int32, attr int32) Ptr[byte] {
	var n int32
	var ts Ptr[byte]

	add_msg_hist(s, -1, attr)

	ts = msg_may_trunc(force, s)

	msg_hist_off = TRUE
	n = msg_attr(ts, attr)
	msg_hist_off = FALSE

	if n != 0 {
		return ts
	}
	return Ptr[byte]{}
}

func msg_may_trunc(force int32, s Ptr[byte]) Ptr[byte] {
	var n int32
	var room int32

	room = int32(Rows-int64(cmdline_row)-1)*cmdline_width + sc_col - 1
	if room > 0 && (force != 0 || shortmess(SHM_TRUNC) != 0) {
		n = int32(musl_strlen(s)) - room
		if n > 0 {
			var size int32 = vim_strsize(s)

			if size <= room {
				return s
			}

			for n = 0; size >= room; {
				size -= utf_ptr2cells(s.Add(int(n)))
				n += utfc_ptr2len(s.Add(int(n)))
			}
			n--
			s = s.Add(int(n))
			s.Put('<')
		}
	}
	return s
}

func add_msg_hist(s Ptr[byte], len_ int32, attr int32) {
	var p *S_msg_hist

	if msg_hist_off != 0 || msg_silent != 0 {
		return
	}

	p = new(S_msg_hist)

	if len_ < 0 {
		len_ = int32(musl_strlen(s))
	}
	for len_ > 0 && s.Get() == '\n' {
		s = s.Add(1)
		len_--
	}
	for len_ > 0 && s.At(int(len_-1)) == '\n' {
		len_--
	}
	p.msg = vim_strnsave(s, usize(len_))
	p.next = nil
	p.attr = attr
	if last_msg_hist != nil {
		last_msg_hist.next = p
	}
	last_msg_hist = p
	if first_msg_hist == nil {
		first_msg_hist = last_msg_hist
	}
	msg_hist_len++

	check_msg_hist()
}

func delete_first_msg() int32 {
	var p *S_msg_hist

	if msg_hist_len <= 0 {
		return FAIL
	}
	p = first_msg_hist
	first_msg_hist = p.next
	if first_msg_hist == nil {
		last_msg_hist = nil
	}
	msg_hist_len--
	return OK
}

func check_msg_hist() {
	for msg_hist_len > 0 && msg_hist_len > msg_hist_max {
		_ = delete_first_msg()
	}
}

func messagesopt_changed() int32 {
	var p Ptr[byte]
	var messages_flags_new int32 = 0
	var messages_wait_new int32 = 0
	var messages_history_new int32 = 0

	p = p_mopt
	for p.Get() != NUL {
		if musl_strncmp(p, S("hit-enter"), 9) == 0 {
			p = p.Add(9)
			messages_flags_new |= MESSAGES_HIT_ENTER
		} else if musl_strncmp(p, S("wait:"), 5) == 0 && uint32(p.At(5))-'0' < 10 {
			p = p.Add(5)
			messages_wait_new = int32(getdigits(Addr(&p)))
			messages_flags_new |= MESSAGES_WAIT
		} else if musl_strncmp(p, S("history:"), 8) == 0 && uint32(p.At(8))-'0' < 10 {
			p = p.Add(8)
			messages_history_new = int32(getdigits(Addr(&p)))
			messages_flags_new |= MESSAGES_HISTORY
		}

		if p.Get() != ',' && p.Get() != NUL {
			return FAIL
		}
		if p.Get() == ',' {
			p = p.Add(1)
		}
	}

	if messages_flags_new&(MESSAGES_HIT_ENTER|MESSAGES_WAIT) == 0 {
		return FAIL
	}

	if messages_flags_new&MESSAGES_HISTORY == 0 {
		return FAIL
	}

	if messages_history_new < 0 || messages_history_new > 10000 {
		return FAIL
	}

	if messages_wait_new < 0 || messages_wait_new > 10000 {
		return FAIL
	}

	msg_flags = messages_flags_new
	msg_wait = messages_wait_new

	msg_hist_max = messages_history_new
	check_msg_hist()

	return OK
}

func ex_messages(eap *S_exarg) {
	var p *S_msg_hist
	var c int32 = 0

	if musl_strcmp(eap.arg, S("clear")) == 0 {
		var keep int32
		if eap.addr_count == 0 {
			keep = 0
		} else {
			keep = int32(eap.line2)
		}

		for msg_hist_len > keep {
			_ = delete_first_msg()
		}
		return
	}

	if eap.arg.Get() != NUL {
		emsg(gettext_(e_invalid_argument))
		return
	}

	msg_hist_off = TRUE

	p = first_msg_hist
	if eap.addr_count != 0 {
		for ; p != nil && got_int == 0; p = p.next {
			c++
		}

		c = int32(int64(c) - eap.line2)

		for p = first_msg_hist; p != nil && got_int == 0 && c > 0; p, c = p.next, c-1 {
		}
	}

	for ; p != nil && got_int == 0; p = p.next {
		if !p.msg.Nil() {
			msg_attr(p.msg, p.attr)
		}
	}

	msg_hist_off = FALSE
}

func wait_return(redraw int32) {
	var c int32
	var oldState int32
	var tmpState int32
	var had_got_int int32
	var save_reg_recording int32
	const (
		k_ignore       = -(KS_EXTRA + (KE_IGNORE << 8))
		k_leftdrag     = -(KS_EXTRA + (KE_LEFTDRAG << 8))
		k_leftrelease  = -(KS_EXTRA + (KE_LEFTRELEASE << 8))
		k_middledrag   = -(KS_EXTRA + (KE_MIDDLEDRAG << 8))
		k_middlerel    = -(KS_EXTRA + (KE_MIDDLERELEASE << 8))
		k_rightdrag    = -(KS_EXTRA + (KE_RIGHTDRAG << 8))
		k_rightrelease = -(KS_EXTRA + (KE_RIGHTRELEASE << 8))
		k_mouseleft    = -(KS_EXTRA + (KE_MOUSELEFT << 8))
		k_mouseright   = -(KS_EXTRA + (KE_MOUSERIGHT << 8))
		k_mousedown    = -(KS_EXTRA + (KE_MOUSEDOWN << 8))
		k_mouseup      = -(KS_EXTRA + (KE_MOUSEUP << 8))
		k_mousemove    = -(KS_EXTRA + (KE_MOUSEMOVE << 8))
		k_leftmouse    = -(KS_EXTRA + (KE_LEFTMOUSE << 8))
		k_middlemouse  = -(KS_EXTRA + (KE_MIDDLEMOUSE << 8))
		k_rightmouse   = -(KS_EXTRA + (KE_RIGHTMOUSE << 8))
		k_x1mouse      = -(KS_EXTRA + (KE_X1MOUSE << 8))
		k_x2mouse      = -(KS_EXTRA + (KE_X2MOUSE << 8))
	)

	if redraw == TRUE {
		set_must_redraw(UPD_CLEAR)
	}

	if msg_silent != 0 {
		return
	}

	if vgetc_busy > 0 {
		return
	}
	need_wait_return = TRUE
	if no_wait_return != 0 {
		cmdline_row = msg_row
		return
	}

	oldState = State
	if quit_more != 0 {
		c = CAR
		quit_more = FALSE
		got_int = FALSE
	} else if stuff_empty() == 0 {
		c = CAR
	} else {
		screenalloc(FALSE)

		State = 0x2000 | MODE_NORMAL
		cmdline_row = msg_row

		if msg_flags&MESSAGES_HIT_ENTER != 0 {
			hit_return_msg()

			for {
				had_got_int = got_int

				no_mapping++
				allow_keys++

				save_reg_recording = reg_recording
				reg_recording = 0
				c = safe_vgetc()
				if had_got_int != 0 && global_busy == 0 {
					got_int = FALSE
				}
				no_mapping--
				allow_keys--
				reg_recording = save_reg_recording

				if KeyTyped != 0 && p_more != 0 && p_cp == 0 {
					if c == 'b' || c == Ctrl_B || c == 'k' || c == 'u' || c == 'g' || c == -('k'+('u'<<8)) || c == -('k'+('P'<<8)) {
						if int64(msg_scrolled) > Rows {
							do_more_prompt(c)
						} else {
							msg_didout = FALSE
							c = k_ignore
							msg_col = 0
						}
						if quit_more != 0 {
							c = CAR
							quit_more = FALSE
							got_int = FALSE
						} else if c != k_ignore {
							c = k_ignore
							hit_return_msg()
						}
					} else if int64(msg_scrolled) > Rows-2 && (c == 'j' || c == 'd' || c == 'f' || c == Ctrl_F || c == -('k'+('d'<<8)) || c == -('k'+('N'<<8))) {
						c = k_ignore
					}
				}
				if !((had_got_int != 0 && c == Ctrl_C) || c == k_ignore || c == k_leftdrag || c == k_leftrelease || c == k_middledrag || c == k_middlerel || c == k_rightdrag || c == k_rightrelease || c == k_mouseleft || c == k_mouseright || c == k_mousedown || c == k_mouseup || c == k_mousemove) {
					break
				}
			}
			ui_breakcheck()

			if c == k_leftmouse || c == k_middlemouse || c == k_rightmouse || c == k_x1mouse || c == k_x2mouse {
			} else if KeyTyped == 0 || (vim_strchr(S("\r\n "), c).Nil() && c != Ctrl_C && c != 'q') {
				ins_char_typebuf(vgetc_char, vgetc_mod_mask)
				do_redraw = TRUE
			}
		} else {
			c = CAR
			do_sleep(int64(msg_wait), TRUE)
		}
	}

	if c == ':' || c == '?' || c == '/' {
		cmdline_row = msg_row
		skip_redraw = TRUE
		do_redraw = FALSE
	}

	tmpState = State
	State = oldState
	msg_check()

	if swapping_screen() != 0 && termcap_active == 0 {
		newline_on_exit = TRUE
	}

	need_wait_return = FALSE
	did_wait_return = TRUE
	emsg_on_display = FALSE
	lines_left = -1
	reset_last_sourcing()
	if !keep_msg.Nil() && int64(vim_strsize(keep_msg)) >= (Rows-int64(cmdline_row)-1)*int64(cmdline_width)+int64(sc_col) {
		keep_msg = Ptr[byte]{}
	}

	if tmpState == MODE_SETWSIZE {
		starttermcap()
		shell_resized()
	} else if skip_redraw == 0 && (redraw == TRUE || (msg_scrolled != 0 && redraw != -1)) {
		starttermcap()
		redraw_later(UPD_VALID)
	}
}

func hit_return_msg() {
	var save_p_more int32 = p_more

	p_more = FALSE
	if msg_didout != 0 {
		msg_putchar('\n')
	}
	if got_int != 0 {
		msg_puts(gettext_(S("Interrupt: ")))
	}

	msg_puts_attr(gettext_(S("Press ENTER or type command to continue")), highlight_attr[HLF_R])
	if msg_use_printf() == 0 {
		msg_clr_eos()
	}
	p_more = save_p_more
}

func set_keep_msg(s Ptr[byte], attr int32) {
	if !s.Nil() && msg_silent == 0 {
		keep_msg = vim_strsave(s)
	} else {
		keep_msg = Ptr[byte]{}
	}
	keep_msg_more = FALSE
	keep_msg_attr = attr
}

func set_keep_msg_from_hist() {
	if keep_msg.Nil() && last_msg_hist != nil && msg_scrolled == 0 && State&MODE_NORMAL != 0 {
		set_keep_msg(last_msg_hist.msg, last_msg_hist.attr)
	}
}

func msg_start() {

	if msg_row < cmdline_row {
		msg_row = cmdline_row
	}

	if msg_silent == 0 {
		keep_msg = Ptr[byte]{}
		need_fileinfo = FALSE
	}

	if msg_scroll == 0 && full_screen != 0 {
		msg_row = cmdline_row
		msg_col = 0
	} else if msg_didout != 0 || in_echowindow != 0 {
		msg_putchar('\n')
		cmdline_row = msg_row
	}
	if msg_didany == 0 || lines_left < 0 {
		msg_starthere()
	}
	if msg_silent == 0 {
		msg_didout = FALSE
		cursor_off()
	}

}

func msg_starthere() {
	lines_left = cmdline_row
	msg_didany = FALSE
}

func msg_putchar(c int32) {
	msg_putchar_attr(c, 0)
}

func msg_putchar_attr(c int32, attr int32) {
	var buf Ptr[byte] = Mk[byte](MB_MAXBYTES + 1)

	if c < 0 {
		buf.Set(0, 0x80)
		if c == 0x80 {
			buf.Set(1, KS_SPECIAL)
		} else if c == NUL {
			buf.Set(1, KS_ZERO)
		} else {
			buf.Set(1, byte((-c)&0xff))
		}
		if c == 0x80 || c == NUL {
			buf.Set(2, 'X')
		} else {
			buf.Set(2, byte((uint32(-c)>>8)&0xff))
		}
		buf.Set(3, NUL)
	} else {
		buf.Set(int(utf_char2bytes(c, buf)), NUL)
	}
	msg_puts_attr(buf, attr)
}

func msg_outtrans(str Ptr[byte]) int32 {
	return msg_outtrans_attr(str, 0)
}

func msg_outtrans_attr(str Ptr[byte], attr int32) int32 {
	return msg_outtrans_len_attr(str, int32(musl_strlen(str)), attr)
}

func msg_outtrans_len(str Ptr[byte], len_ int32) int32 {
	return msg_outtrans_len_attr(str, len_, 0)
}

func msg_outtrans_len_attr(msgstr Ptr[byte], len_ int32, attr int32) int32 {
	var retval int32 = 0
	var str Ptr[byte] = msgstr
	var plain_start Ptr[byte] = msgstr
	var s Ptr[byte]
	var mb_l int32
	var c int32
	var save_got_int int32 = got_int

	got_int = FALSE

	if attr == 0 {
		attr = highlight_attr[HLF_MSG]
	}

	if attr&MSG_HIST != 0 {
		add_msg_hist(str, len_, attr)
		attr &^= MSG_HIST
	}

	if msg_silent == 0 && len_ > 0 && msg_row >= cmdline_row && msg_col == 0 {
		clear_cmdline = FALSE
		mode_displayed = FALSE
	}

	if utf_iscomposing(utf_ptr2char(msgstr)) != 0 {
		msg_puts_attr(S(" "), attr)
	}

	for {
		len_--
		if !(len_ >= 0 && got_int == 0) {
			break
		}
		mb_l = utfc_ptr2len_len(str, len_+1)
		if mb_l > 1 {
			c = utf_ptr2char(str)
			if vim_isprintc(c) != 0 {
				retval += utf_ptr2cells(str)
			} else {
				if str.Gt(plain_start) {
					msg_puts_attr_len(plain_start, int32(str.Sub(plain_start)), attr)
				}
				plain_start = str.Add(int(mb_l))
				var a int32
				if attr == 0 {
					a = highlight_attr[HLF_8]
				} else {
					a = attr
				}
				msg_puts_attr(transchar_buf(nil, c), a)
				retval += char2cells(c)
			}
			len_ -= mb_l - 1
			str = str.Add(int(mb_l))
		} else {
			s = transchar_byte_buf(nil, int32(str.Get()))
			if s.At(1) != NUL {
				if str.Gt(plain_start) {
					msg_puts_attr_len(plain_start, int32(str.Sub(plain_start)), attr)
				}
				plain_start = str.Add(1)
				var a int32
				if attr == 0 {
					a = highlight_attr[HLF_8]
				} else {
					a = attr
				}
				msg_puts_attr(s, a)
				retval += int32(musl_strlen(s))
			} else {
				retval++
			}
			str = str.Add(1)
		}
	}

	if str.Gt(plain_start) && got_int == 0 {
		msg_puts_attr_len(plain_start, int32(str.Sub(plain_start)), attr)
	}

	got_int |= save_got_int

	return retval
}

func msg_outtrans_special(strstart Ptr[byte], from int32, maxlen int32) int32 {
	var str Ptr[byte] = strstart
	var retval int32 = 0
	var text Ptr[byte]
	var attr int32
	var len_ int32

	attr = highlight_attr[HLF_8]
	for str.Get() != NUL {
		if (str == strstart || str.At(1) == NUL) && str.Get() == ' ' {
			text = S("<Space>")
			str = str.Add(1)
		} else {
			text = str2special(&str, from, FALSE)
		}
		if text.At(0) != NUL && text.At(1) == NUL {
			text = transchar_byte_buf(nil, int32(text.At(0)))
		}
		len_ = vim_strsize(text)
		if maxlen > 0 && retval+len_ >= maxlen {
			break
		}
		var a int32
		if len_ > 1 && utfc_ptr2len(text) <= 1 {
			a = attr
		} else {
			a = 0
		}
		msg_puts_attr(text, a)
		retval += len_
	}
	return retval
}

func str2special(sp *Ptr[byte], replace_spaces int32, replace_others int32) Ptr[byte] {
	var c int32
	var str Ptr[byte] = *sp
	var modifiers int32 = 0
	var special int32 = FALSE

	var p Ptr[byte]

	p = mb_unescape(sp)
	if !p.Nil() {
		return p
	}

	c = int32(str.Get())
	if c == 0x80 && str.At(1) != NUL && str.At(2) != NUL {
		if str.At(1) == KS_MODIFIER {
			modifiers = int32(str.At(2))
			str = str.Add(3)
			c = int32(str.Get())
		}
		if c == 0x80 && str.At(1) != NUL && str.At(2) != NUL {
			if str.At(1) == KS_SPECIAL {
				c = 0x80
			} else if str.At(1) == KS_ZERO {
				c = -(KS_ZERO + ('X' << 8))
			} else {
				c = -(int32(str.At(1)) + (int32(str.At(2)) << 8))
			}
			str = str.Add(2)
		}
		if c < 0 || modifiers != 0 {
			special = TRUE
		}
	}

	if !(c < 0) && mb_bytelen_tab[c] > 1 {
		var p Ptr[byte]

		*sp = str
		p = mb_unescape(sp)
		if !p.Nil() {
			c = utf_ptr2char(p)
		} else {
			*sp = str.Add(1)
		}
	} else {
		if str.Get() == NUL {
			*sp = str.Add(0)
		} else {
			*sp = str.Add(1)
		}
	}

	if special != 0 || c < ' ' || (replace_spaces != 0 && c == ' ') || (replace_others != 0 && (c == '<' || c == '|' || c == '\\')) {
		return get_special_key_name(c, modifiers)
	}
	str2special_buf.Set(0, byte(c))
	str2special_buf.Set(1, NUL)
	return str2special_buf
}

func str2specialbuf(sp Ptr[byte], buf Ptr[byte], len_ int32) {
	var s Ptr[byte]
	var buf_len usize = 0
	var s_len usize

	buf.Put(NUL)
	for sp.Get() != 0 {
		s = str2special(&sp, FALSE, FALSE)
		s_len = musl_strlen(s)
		if buf_len+s_len < usize(len_) {
			musl_strcpy(buf.Add(int(buf_len)), s)
			buf_len += s_len
		} else {
			break
		}
	}
}

func msg_prt_line(s Ptr[byte], list int32) {
	var c int32
	var col int32 = 0
	var n_extra int32 = 0
	var c_extra int32 = 0
	var c_final int32 = 0
	var p_extra Ptr[byte] = Ptr[byte]{}
	var n int32
	var attr int32 = 0
	var trail Ptr[byte] = Ptr[byte]{}
	var lead Ptr[byte] = Ptr[byte]{}
	var in_multispace int32 = FALSE
	var multispace_pos int32 = 0
	var l int32
	var buf Ptr[byte] = Mk[byte](MB_MAXBYTES + 1)

	if curwin.w_onebuf_opt.wo_list != 0 {
		list = TRUE
	}

	if list != 0 {
		if curwin.w_lcs_chars.trail != 0 {
			trail = s.Add(int(musl_strlen(s)))
			for trail.Gt(s) && (trail.At(-1) == ' ' || trail.At(-1) == '\t') {
				trail = trail.Add(-1)
			}
		}
		if curwin.w_lcs_chars.lead != 0 || !curwin.w_lcs_chars.leadmultispace.Nil() || curwin.w_lcs_chars.leadtab1 != NUL {
			lead = s
			for lead.At(0) == ' ' || lead.At(0) == '\t' {
				lead = lead.Add(1)
			}
			if lead.Get() == NUL {
				lead = Ptr[byte]{}
			}
		}
	}

	if s.Get() == NUL && !(list != 0 && curwin.w_lcs_chars.eol != NUL) {
		msg_putchar(' ')
	}

	for got_int == 0 {
		if n_extra > 0 {
			n_extra--
			if n_extra == 0 && c_final != 0 {
				c = c_final
			} else if c_extra != 0 {
				c = c_extra
			} else {
				c = int32(p_extra.Get())
				p_extra = p_extra.Add(1)
			}
		} else if l = utfc_ptr2len(s); l > 1 {
			col += utf_ptr2cells(s)
			if l >= MB_MAXBYTES {
				musl_strcpy(buf, S("?"))
			} else if curwin.w_lcs_chars.nbsp != NUL && list != 0 && (utf_ptr2char(s) == 160 || utf_ptr2char(s) == 0x202f) {
				var len_ int32 = utf_char2bytes(curwin.w_lcs_chars.nbsp, buf)

				buf.Set(int(len_), NUL)
			} else {
				Memmove(buf, s, int(l))
				buf.Set(int(l), NUL)
			}
			msg_puts(buf)
			s = s.Add(int(l))
			continue
		} else {
			attr = 0
			c = int32(s.Get())
			s = s.Add(1)
			if list != 0 {
				in_multispace = B2i(c == ' ' && (s.Get() == ' ' || (col > 0 && s.At(-2) == ' ')))
				if in_multispace == 0 {
					multispace_pos = 0
				}
			}
			if c == TAB && (list == 0 || curwin.w_lcs_chars.tab1 != 0) {
				n_extra = int32(curbuf.b_p_ts - int64(col)%curbuf.b_p_ts - 1)
				if list == 0 {
					c = ' '
					c_extra = ' '
					c_final = NUL
				} else {
					var lcs_tab1 int32 = curwin.w_lcs_chars.tab1
					var lcs_tab2 int32 = curwin.w_lcs_chars.tab2
					var lcs_tab3 int32 = curwin.w_lcs_chars.tab3

					if !lead.Nil() && s.Le(lead) && curwin.w_lcs_chars.leadtab1 != NUL {
						lcs_tab1 = curwin.w_lcs_chars.leadtab1
						lcs_tab2 = curwin.w_lcs_chars.leadtab2
						lcs_tab3 = curwin.w_lcs_chars.leadtab3
					}

					if n_extra == 0 && lcs_tab3 != 0 {
						c = lcs_tab3
					} else {
						c = lcs_tab1
					}
					c_extra = lcs_tab2
					c_final = lcs_tab3
					attr = highlight_attr[HLF_8]
				}
			} else if c == 160 && list != 0 && curwin.w_lcs_chars.nbsp != NUL {
				c = curwin.w_lcs_chars.nbsp
				attr = highlight_attr[HLF_8]
			} else if c == NUL && list != 0 && curwin.w_lcs_chars.eol != NUL {
				p_extra = S("")
				c_extra = NUL
				c_final = NUL
				n_extra = 1
				c = curwin.w_lcs_chars.eol
				attr = highlight_attr[HLF_AT]
				s = s.Add(-1)
			} else if c != NUL && func() bool { n = byte2cells(c); return n > 1 }() {
				n_extra = n - 1
				p_extra = transchar_byte_buf(nil, c)
				c_extra = NUL
				c_final = NUL
				c = int32(p_extra.Get())
				p_extra = p_extra.Add(1)
				attr = highlight_attr[HLF_8]
			} else if c == ' ' {
				if !lead.Nil() && s.Le(lead) && in_multispace != 0 && !curwin.w_lcs_chars.leadmultispace.Nil() {
					c = curwin.w_lcs_chars.leadmultispace.At(int(multispace_pos))
					multispace_pos++
					if curwin.w_lcs_chars.leadmultispace.At(int(multispace_pos)) == NUL {
						multispace_pos = 0
					}
					attr = highlight_attr[HLF_8]
				} else if !lead.Nil() && s.Le(lead) && curwin.w_lcs_chars.lead != NUL {
					c = curwin.w_lcs_chars.lead
					attr = highlight_attr[HLF_8]
				} else if !trail.Nil() && s.Gt(trail) {
					c = curwin.w_lcs_chars.trail
					attr = highlight_attr[HLF_8]
				} else if in_multispace != 0 && !curwin.w_lcs_chars.multispace.Nil() {
					c = curwin.w_lcs_chars.multispace.At(int(multispace_pos))
					multispace_pos++
					if curwin.w_lcs_chars.multispace.At(int(multispace_pos)) == NUL {
						multispace_pos = 0
					}
					attr = highlight_attr[HLF_8]
				} else if list != 0 && curwin.w_lcs_chars.space != NUL {
					c = curwin.w_lcs_chars.space
					attr = highlight_attr[HLF_8]
				}
			}
		}

		if c == NUL {
			break
		}

		msg_putchar_attr(c, attr)
		col++
	}
	msg_clr_eos()
}

func screen_puts_mbyte(s Ptr[byte], l int32, attr int32) Ptr[byte] {
	var cw int32

	msg_didout = TRUE
	cw = utf_ptr2cells(s)
	if cw > 1 && (msg_col == cmdline_width-1) {
		msg_screen_putchar('>', highlight_attr[HLF_AT])
		return s
	}

	screen_puts_len(s, l, msg_row, cmdline_col_off+msg_col, attr)
	{
		msg_col += cw
		if msg_col >= cmdline_width {
			msg_col = 0
			msg_row++
		}
	}
	return s.Add(int(l))
}

func msg_puts(s Ptr[byte]) {
	msg_puts_attr(s, 0)
}

func msg_puts_title(s Ptr[byte]) {
	msg_puts_attr(s, highlight_attr[HLF_T])
}

func msg_puts_attr(s Ptr[byte], attr int32) {
	msg_puts_attr_len(s, -1, attr)
}

func msg_puts_attr_len(str Ptr[byte], maxlen int32, attr int32) {

	if msg_silent != 0 {
		return
	}

	if attr == 0 {
		attr = highlight_attr[HLF_MSG]
	}

	if attr&MSG_HIST != 0 && maxlen < 0 {
		add_msg_hist(str, -1, attr)
		attr &^= MSG_HIST
	}

	if msg_scrolled != 0 && msg_scrolled_ign == 0 && musl_strcmp(str, S("\r")) != 0 {
		need_wait_return = TRUE
	}
	msg_didany = TRUE

	if msg_use_printf() != 0 {
		host_message(str, maxlen, B2i(info_message == 0))
		msg_didout = TRUE
	} else {
		msg_puts_display(str, maxlen, attr, FALSE)
	}

	need_fileinfo = FALSE
}

func msg_puts_display(str Ptr[byte], maxlen int32, attr int32, recurse int32) {
	var s Ptr[byte] = str
	var t_s Ptr[byte] = str
	var t_col int32 = 0
	var l int32
	var cw int32
	var sb_str Ptr[byte] = str
	var sb_col int32 = msg_col
	var wrap int32
	var did_last_char int32

	did_wait_return = FALSE
	for (maxlen < 0 || int32(s.Sub(str)) < maxlen) && s.Get() != NUL {
		var wrap_col int32 = cmdline_width - 1

		if recurse == 0 && int64(msg_row) >= Rows-1 && (s.Get() == '\n' || ((s.Get() != '\r' && msg_col+t_col >= wrap_col) || (s.Get() == TAB && msg_col+t_col >= (wrap_col&^7)) || (utf_ptr2cells(s) > 1 && msg_col+t_col >= wrap_col-1))) {
			if t_col > 0 {
				t_puts(&t_col, t_s, s, attr)
			}

			if msg_no_more != 0 && lines_left == 0 {
				break
			}

			msg_scroll_up()

			msg_row = int32(Rows - 2)
			if msg_col >= cmdline_width {
				msg_col = cmdline_width - 1
			}

			if s.Get() >= ' ' {
				if maxlen >= 0 {
					l = utfc_ptr2len_len(s, int32(str.Add(int(maxlen)).Sub(s)))
				} else {
					l = utfc_ptr2len(s)
				}
				s = screen_puts_mbyte(s, l, attr)
				did_last_char = TRUE
			} else {
				did_last_char = FALSE
			}

			if p_more != 0 {
				store_sb_text(&sb_str, s, attr, &sb_col, TRUE)
			}

			inc_msg_scrolled()
			need_wait_return = TRUE
			redraw_cmdline = TRUE
			if cmdline_row > 0 {
				cmdline_row--
			}

			if lines_left > 0 {
				lines_left--
			}
			if p_more != 0 && lines_left == 0 && State != (0x2000|MODE_NORMAL) && msg_no_more == 0 {
				_ = do_more_prompt(NUL)
				if quit_more != 0 {
					return
				}
			}

			if did_last_char != 0 {
				continue
			}
		}

		wrap = B2i(s.Get() == '\n' || msg_col+t_col >= wrap_col || (utf_ptr2cells(s) > 1 && msg_col+t_col >= wrap_col-1))
		if t_col > 0 && (wrap != 0 || s.Get() == '\r' || s.Get() == '\b' || s.Get() == '\t' || s.Get() == BELL) {
			t_puts(&t_col, t_s, s, attr)
		}

		if wrap != 0 && p_more != 0 && recurse == 0 {
			store_sb_text(&sb_str, s, attr, &sb_col, TRUE)
		}

		if s.Get() == '\n' {
			msg_didout = FALSE
			msg_col = 0
			msg_row++
			if int64(msg_row) >= Rows {
				msg_row = int32(Rows - 1)
			}
		} else if s.Get() == '\r' {
			msg_col = 0
		} else if s.Get() == '\b' {
			if msg_col != 0 {
				msg_col--
			}
		} else if s.Get() == TAB {
			for {
				msg_screen_putchar(' ', attr)
				if !(msg_col&7 != 0) {
					break
				}
			}
		} else if s.Get() == BELL {
			vim_beep(BO_SH)
		} else {
			cw = utf_ptr2cells(s)
			if maxlen >= 0 {
				l = utfc_ptr2len_len(s, int32(str.Add(int(maxlen)).Sub(s)))
			} else {
				l = utfc_ptr2len(s)
			}

			if cw > 1 && msg_col+t_col >= wrap_col {
				if l > 1 {
					s = screen_puts_mbyte(s, l, attr).Add(-1)
				} else {
					msg_screen_putchar(int32(s.Get()), attr)
				}
			} else {
				if t_col == 0 {
					t_s = s
				}
				t_col += cw
				s = s.Add(int(l - 1))
			}
		}
		s = s.Add(1)
	}

	if t_col > 0 {
		t_puts(&t_col, t_s, s, attr)
	}

	if p_more != 0 && recurse == 0 && !(s == sb_str.Add(1) && sb_str.Get() == '\n') {
		store_sb_text(&sb_str, s, attr, &sb_col, FALSE)
	}

	msg_check()
}

func message_filtered(msg Ptr[byte]) int32 {
	var match int32

	if cmdmod.cmod_filter_regmatch.regprog == nil {
		return FALSE
	}
	match = vim_regexec(&cmdmod.cmod_filter_regmatch, msg, colnr_T(0))
	if cmdmod.cmod_filter_force != 0 {
		return match
	}
	return B2i(match == 0)
}

func msg_scroll_up() {
	screen_del_lines(0, 0, 1, int32(Rows), TRUE, 0, nil)

	if can_clear(S(" ")) == 0 {
		screen_fill(int32(Rows)-1, int32(Rows), cmdline_col_off, cmdline_col_off+cmdline_width, ' ', ' ', highlight_attr[HLF_MSG])

		if ScreenAttrs.At(int(int64(LineOffset.At(int(Rows-2)))+Columns-1)) == sattr_T(0xffff) {
			screen_fill(int32(Rows)-2, int32(Rows)-1, int32(Columns)-1, int32(Columns), ' ', ' ', highlight_attr[HLF_MSG])
		}
	}
}

func inc_msg_scrolled() {
	msg_scrolled++
	set_must_redraw(UPD_VALID)
}

func store_sb_text(sb_str *Ptr[byte], s Ptr[byte], attr int32, sb_col *int32, finish int32) {
	var mp *msgchunk_T

	if do_clear_sb_text == SB_CLEAR_ALL || do_clear_sb_text == SB_CLEAR_CMDLINE_DONE {
		clear_sb_text(B2i(do_clear_sb_text == SB_CLEAR_ALL))
		msg_sb_eol()
		do_clear_sb_text = SB_CLEAR_NONE
	}

	if s.Gt(*sb_str) {
		mp = new(msgchunk_T)
		mp.sb_text = Mk[byte](s.Sub(*sb_str) + 1)
		mp.sb_eol = byte(finish)
		mp.sb_msg_col = *sb_col
		mp.sb_attr = attr
		vim_strncpy(mp.sb_text, *sb_str, usize(s.Sub(*sb_str)))

		if last_msgchunk == nil {
			last_msgchunk = mp
			mp.sb_prev = nil
		} else {
			mp.sb_prev = last_msgchunk
			last_msgchunk.sb_next = mp
			last_msgchunk = mp
		}
		mp.sb_next = nil
	} else if finish != 0 && last_msgchunk != nil {
		last_msgchunk.sb_eol = TRUE
	}

	*sb_str = s
	*sb_col = 0
}

func may_clear_sb_text() {
	do_clear_sb_text = SB_CLEAR_ALL
}

func sb_text_start_cmdline() {
	if do_clear_sb_text == SB_CLEAR_CMDLINE_BUSY {
		sb_text_restart_cmdline()
	} else {
		msg_sb_eol()
		do_clear_sb_text = SB_CLEAR_CMDLINE_BUSY
	}
}

func sb_text_restart_cmdline() {
	var tofree *msgchunk_T

	do_clear_sb_text = SB_CLEAR_CMDLINE_BUSY

	if last_msgchunk == nil || last_msgchunk.sb_eol != 0 {
		return
	}

	tofree = msg_sb_start(last_msgchunk)
	last_msgchunk = tofree.sb_prev
	if last_msgchunk != nil {
		last_msgchunk.sb_next = nil
	}
	for tofree != nil {
		var tofree_next *msgchunk_T = tofree.sb_next

		tofree = tofree_next
	}
}

func sb_text_end_cmdline() {
	do_clear_sb_text = SB_CLEAR_CMDLINE_DONE
}

func clear_sb_text(all int32) {
	var mp *msgchunk_T
	var lastp **msgchunk_T

	if all != 0 {
		lastp = &last_msgchunk
	} else {
		if last_msgchunk == nil {
			return
		}
		lastp = &msg_sb_start(last_msgchunk).sb_prev
	}

	for *lastp != nil {
		mp = (*lastp).sb_prev
		*lastp = mp
	}
}

func show_sb_text() {
	var mp *msgchunk_T

	mp = msg_sb_start(last_msgchunk)
	if mp == nil || mp.sb_prev == nil {
		vim_beep(BO_MESS)
	} else {
		do_more_prompt('G')
		wait_return(FALSE)
	}
}

func msg_sb_start(mps *S_msgchunk_S) *S_msgchunk_S {
	var mp *msgchunk_T = mps

	for mp != nil && mp.sb_prev != nil && mp.sb_prev.sb_eol == 0 {
		mp = mp.sb_prev
	}
	return mp
}

func msg_sb_eol() {
	if last_msgchunk != nil {
		last_msgchunk.sb_eol = TRUE
	}
}

func disp_sb_line(row int32, smp *S_msgchunk_S, clear_to_eol int32) *S_msgchunk_S {
	var mp *msgchunk_T = smp
	var p Ptr[byte]

	for {
		msg_row = row
		msg_col = mp.sb_msg_col
		p = mp.sb_text
		if p.Get() == '\n' {
			p = p.Add(1)
		}
		msg_puts_display(p, -1, mp.sb_attr, TRUE)

		if clear_to_eol != 0 {
			screen_fill(row, row+1, cmdline_col_off+msg_col, cmdline_col_off+cmdline_width, ' ', ' ', highlight_attr[HLF_MSG])
		}

		if mp.sb_eol != 0 || mp.sb_next == nil {
			break
		}
		mp = mp.sb_next
	}
	return mp.sb_next
}

func t_puts(t_col *int32, t_s Ptr[byte], s Ptr[byte], attr int32) {
	msg_didout = TRUE
	screen_puts_len(t_s, int32(s.Sub(t_s)), msg_row, cmdline_col_off+msg_col, attr)
	msg_col += *t_col
	*t_col = 0
	if utf_iscomposing(utf_ptr2char(t_s)) != 0 {
		msg_col--
	}
	if msg_col >= cmdline_width {
		msg_col = 0
		msg_row++
	}
}

func msg_use_printf() int32 {
	return B2i(msg_check_screen() == 0 || (swapping_screen() != 0 && termcap_active == 0))
}

func do_more_prompt(typed_char int32) int32 {
	var used_typed_char int32 = typed_char
	var oldState int32 = State
	var c int32
	var toscroll int32
	var mp_last *msgchunk_T = nil
	var mp *msgchunk_T
	var i int32
	var msg_attr int32

	msg_attr = highlight_attr[HLF_MSG]

	if do_more_prompt_entered != 0 || (State == (0x2000|MODE_NORMAL) && typed_char == 0) {
		return FALSE
	}
	do_more_prompt_entered = TRUE

	if typed_char == 'G' {
		mp_last = msg_sb_start(last_msgchunk)
		for i = 0; int64(i) < Rows-2 && mp_last != nil && mp_last.sb_prev != nil; i++ {
			mp_last = msg_sb_start(mp_last.sb_prev)
		}
	}

	State = MODE_ASKMORE
	if typed_char == NUL {
		msg_moremsg(FALSE)
	}
	for {
		if used_typed_char != NUL {
			c = used_typed_char
			used_typed_char = NUL
		} else {
			c = get_keystroke()
		}

		toscroll = 0
		switch c {
		case BS, -('k' + ('b' << 8)), 'k', -('k' + ('u' << 8)):
			toscroll = -1

		case CAR, NL, 'j', -('k' + ('d' << 8)):
			toscroll = 1

		case 'u':
			toscroll = int32(-(Rows / 2))

		case 'd':
			toscroll = int32(Rows / 2)

		case 'b', Ctrl_B, -('k' + ('P' << 8)):
			toscroll = int32(-(Rows - 1))

		case ' ', 'f', Ctrl_F, -('k' + ('N' << 8)), -(KS_EXTRA + (KE_LEFTMOUSE << 8)):
			toscroll = int32(Rows - 1)

		case 'g':
			toscroll = -999999

		case 'G':
			toscroll = 999999
			lines_left = 999999

		case ':':
			{
				typeahead_noflush(':')
				cmdline_row = int32(Rows - 1)
				skip_redraw = TRUE
				need_wait_return = FALSE
			}
			fallthrough
		case 'q', Ctrl_C, ESC:
			{
				got_int = TRUE
				quit_more = TRUE
			}
			lines_left = int32(Rows - 1)

		default:
			msg_moremsg(TRUE)
			continue
		}

		if toscroll != 0 {
			if toscroll < 0 {
				if mp_last == nil {
					mp = msg_sb_start(last_msgchunk)
				} else if mp_last.sb_prev != nil {
					mp = msg_sb_start(mp_last.sb_prev)
				} else {
					mp = nil
				}

				for i = 0; int64(i) < Rows-2 && mp != nil && mp.sb_prev != nil; i++ {
					mp = msg_sb_start(mp.sb_prev)
				}

				if mp != nil && mp.sb_prev != nil {
					for i = 0; i > toscroll; i-- {
						if mp == nil || mp.sb_prev == nil {
							break
						}
						mp = msg_sb_start(mp.sb_prev)
						if mp_last == nil {
							mp_last = msg_sb_start(last_msgchunk)
						} else {
							mp_last = msg_sb_start(mp_last.sb_prev)
						}
					}

					if toscroll == -1 && screen_ins_lines(0, 0, 1, int32(Rows), 0, nil) == OK {
						_ = disp_sb_line(0, mp, FALSE)
					} else {
						var did_clear int32 = screenclear()

						for i = 0; mp != nil && int64(i) < Rows-1; i++ {
							mp = disp_sb_line(i, mp, B2i(did_clear == 0))
							msg_scrolled++
						}
					}
					toscroll = 0
				}
			} else {
				for toscroll > 0 && mp_last != nil {
					msg_scroll_up()
					inc_msg_scrolled()
					screen_fill(int32(Rows)-2, int32(Rows)-1, cmdline_col_off, cmdline_col_off+cmdline_width, ' ', ' ', msg_attr)
					mp_last = disp_sb_line(int32(Rows)-2, mp_last, FALSE)
					toscroll--
				}
			}

			if toscroll <= 0 {
				screen_fill(int32(Rows)-1, int32(Rows), cmdline_col_off, cmdline_col_off+cmdline_width, ' ', ' ', msg_attr)
				msg_moremsg(FALSE)
				continue
			}

			lines_left = toscroll
		}

		break
	}

	screen_fill(int32(Rows)-1, int32(Rows), cmdline_col_off, cmdline_col_off+cmdline_width, ' ', ' ', msg_attr)
	State = oldState
	if quit_more != 0 {
		msg_row = int32(Rows - 1)
		msg_col = 0
	}

	do_more_prompt_entered = FALSE
	return FALSE
}

func msg_screen_putchar(c int32, attr int32) {
	msg_didout = TRUE
	screen_putchar(c, msg_row, cmdline_col_off+msg_col, attr)
	{
		msg_col++
		if msg_col >= cmdline_width {
			msg_col = 0
			msg_row++
		}
	}
}

func msg_moremsg(full int32) {
	var attr int32
	var s Ptr[byte] = gettext_(S("-- More --"))

	attr = highlight_attr[HLF_M]
	screen_puts(s, int32(Rows)-1, cmdline_col_off, attr)
	if full != 0 {
		screen_puts(gettext_(S(" SPACE/d/j: screen/page/line down, b/u/k: up, q: quit ")), int32(Rows)-1, cmdline_col_off+vim_strsize(s), attr)
	}
}

func repeat_message() {
	if State == MODE_ASKMORE {
		msg_moremsg(TRUE)
		msg_row = int32(Rows - 1)
	} else if State == MODE_EXTERNCMD {
		windgoto(msg_row, cmdline_col_off+msg_col)
	} else if State == (0x2000|MODE_NORMAL) || State == MODE_SETWSIZE {
		if int64(msg_row) == Rows-1 {
			msg_didout = FALSE
			msg_col = 0
			msg_clr_eos()
		}
		hit_return_msg()
		msg_row = int32(Rows - 1)
	}
}

func msg_check_screen() int32 {
	if full_screen == 0 || screen_valid(FALSE) == 0 {
		return FALSE
	}

	if int64(msg_row) >= Rows {
		msg_row = int32(Rows - 1)
	}
	if msg_col >= cmdline_width {
		msg_col = cmdline_width - 1
	}
	return TRUE
}

func msg_clr_eos() {
	if msg_silent == 0 {
		msg_clr_eos_force()
	}
}

func msg_clr_eos_force() {
	if msg_use_printf() != 0 {
		if full_screen != 0 {
			if term_strings[KS_CD].Get() != 0 {
				out_str(term_strings[KS_CD])
			} else if term_strings[KS_CE].Get() != 0 {
				out_str(term_strings[KS_CE])
			}
		}
	} else {
		var msg_attr int32

		msg_attr = highlight_attr[HLF_MSG]

		{
			screen_fill(msg_row, msg_row+1, cmdline_col_off+msg_col, cmdline_col_off+cmdline_width, ' ', ' ', msg_attr)
			screen_fill(msg_row+1, int32(Rows), cmdline_col_off, cmdline_col_off+cmdline_width, ' ', ' ', msg_attr)
		}
	}
}

func msg_clr_cmdline() {
	msg_row = cmdline_row
	msg_col = 0
	msg_clr_eos_force()
}

func msg_end() int32 {
	if exiting == 0 && need_wait_return != 0 && State&MODE_CMDLINE == 0 {
		wait_return(FALSE)
		return FALSE
	}
	out_flush()
	return TRUE
}

func msg_check() {
	if int64(msg_row) == Rows-1 && msg_col >= sc_col {
		need_wait_return = TRUE
		redraw_cmdline = TRUE
	}
}

func verbose_enter_scroll() {
	msg_scroll = TRUE
}

func verbose_leave_scroll() {
	cmdline_row = msg_row
}

func give_warning(message Ptr[byte], hl int32) {
	give_warning_with_source(message, hl, FALSE)
}

func give_warning_with_source(message Ptr[byte], hl int32, with_source int32) {
	if msg_silent != 0 {
		return
	}

	no_wait_return++

	keep_msg = Ptr[byte]{}
	if hl != 0 {
		keep_msg_attr = highlight_attr[HLF_W]
	} else {
		keep_msg_attr = 0
	}

	if with_source != 0 {
		msg_start()
		msg_source(highlight_attr[HLF_W])
		msg_puts(S(" "))
		msg_puts_attr(message, highlight_attr[HLF_W]|MSG_HIST)
		msg_clr_eos()
		_ = msg_end()
	} else if msg_attr(message, keep_msg_attr) != 0 && msg_scrolled == 0 {
		set_keep_msg(message, keep_msg_attr)
	}

	msg_didout = FALSE
	msg_nowait = TRUE
	msg_col = 0

	no_wait_return--
}

func msg_advance(col int32) {
	if msg_silent != 0 {
		msg_col = col
		return
	}
	if col >= cmdline_width {
		col = cmdline_width - 1
	}
	for msg_col < col {
		msg_putchar(' ')
	}
}

func msg_warn_missing_clipboard() {
	if global_busy == 0 && !did_warn_clipboard && silence_w23_w24_msg == 0 {
		msg(gettext_(S("W24: Clipboard register not available. See :h W24")))
		did_warn_clipboard = true
	}
}

func plines(lnum linenr_T) int32 {
	return plines_win(curwin, lnum, TRUE)
}

func plines_win(wp *S_window_S, lnum linenr_T, limit_winheight int32) int32 {
	var lines int32

	if wp.w_width == 0 {
		return 1
	}

	if wp.w_onebuf_opt.wo_wrap == 0 {
		lines = 1
	} else {
		lines = plines_win_nofold(wp, lnum)
	}

	if limit_winheight != 0 && lines > wp.w_height {
		return wp.w_height
	}
	return lines
}

func plines_win_nofold(wp *S_window_S, lnum linenr_T) int32 {
	var s Ptr[byte]
	var col int64
	var width int32
	var cts chartabsize_T

	s = ml_get_buf(wp.w_buffer, lnum, FALSE)
	init_chartabsize_arg(&cts, wp, lnum, 0, s, s)
	if s.Get() == NUL {
		return 1
	}
	win_linetabsize_cts(&cts, colnr_T(MAXCOL))
	col = int64(int32(cts.cts_vcol))

	if wp.w_onebuf_opt.wo_list != 0 && wp.w_lcs_chars.eol != NUL {
		col += 1
	}

	width = wp.w_width - win_col_off(wp)
	if width <= 0 {
		return 32000
	}
	if col <= int64(width) {
		return 1
	}
	col -= int64(width)
	width += win_col_off2(wp)
	return int32((col+int64(width-1))/int64(width) + 1)
}

func plines_win_col(wp *S_window_S, lnum linenr_T, column int64) int32 {
	var col int64
	var lines int32 = 0
	var width int32
	var line Ptr[byte]
	var cts chartabsize_T

	if wp.w_onebuf_opt.wo_wrap == 0 {
		return lines + 1
	}

	if wp.w_width == 0 {
		return lines + 1
	}

	line = ml_get_buf(wp.w_buffer, lnum, FALSE)

	init_chartabsize_arg(&cts, wp, lnum, 0, line, line)
	for cts.cts_ptr.Get() != NUL && cts.cts_ptr.Lt(line.Add(int(column))) {
		cts.cts_vcol += win_lbr_chartabsize(&cts, nil, nil)
		cts.cts_ptr = cts.cts_ptr.Add(int(utfc_ptr2len(cts.cts_ptr)))
	}

	col = int64(cts.cts_vcol)
	if cts.cts_ptr.Get() == TAB && State&MODE_NORMAL != 0 && (wp.w_onebuf_opt.wo_list == 0 || wp.w_lcs_chars.tab1 != 0) {
		col += int64(win_lbr_chartabsize(&cts, nil, nil) - 1)
	}

	width = wp.w_width - win_col_off(wp)
	if width <= 0 {
		return 9999
	}

	lines += 1
	if col > int64(width) {
		lines += int32((col-int64(width))/int64(width+win_col_off2(wp)) + 1)
	}
	return lines
}

func plines_m_win(wp *S_window_S, first linenr_T, last linenr_T, max_ int32) int32 {
	var count int32 = 0

	for first <= last && count < max_ {
		{
			count += plines_win(wp, first, FALSE)
			first++
		}
	}
	if max_ < count {
		return max_
	}
	return count
}

func gchar_pos(pos *pos_T) int32 {
	var ptr Ptr[byte]
	var ptrlen int32

	if pos.col == MAXCOL {
		return NUL
	}
	ptrlen = ml_get_len(pos.lnum)
	ptr = ml_get_pos(pos)
	if pos.col > ptrlen {
		return NUL
	}
	return utf_ptr2char(ptr)
	// C: an unreachable `return (int)*ptr;` follows.
}

func gchar_cursor() int32 {
	return utf_ptr2char(ml_get_cursor())
	// C: an unreachable `return (int)*ml_get_cursor();` follows.
}

func pchar_cursor(c int32) {
	ml_get_buf(curbuf, curwin.w_cursor.lnum, TRUE).Set(int(curwin.w_cursor.col), byte(c))
}

func skip_to_option_part(p Ptr[byte]) Ptr[byte] {
	if p.Get() == ',' {
		p = p.Add(1)
	}
	for p.Get() == ' ' {
		p = p.Add(1)
	}
	return p
}

func check_status(buf *S_file_buffer) {
	var wp *win_T

	wp = curwin
	if wp.w_buffer == buf && wp.w_status_height != 0 {
		wp.w_redr_status = true
		set_must_redraw(UPD_VALID)
	}
}

func ask_yesno(str Ptr[byte], direct int32) int32 {
	var r int32 = ' '
	var save_State int32 = State

	if exiting != 0 {
		term_enter()
	}
	no_wait_return++
	State = MODE_CONFIRM
	no_mapping++
	allow_keys++

	for r != 'y' && r != 'n' {
		vim_snprintf(IObuff, iobuff_room(), S("%s (y/n)?"), str)
		msg_attr(iobuff_or(S("%s (y/n)?")), highlight_attr[HLF_R])
		if direct != 0 {
			r = get_keystroke()
		} else {
			r = plain_vgetc()
		}
		if r == Ctrl_C || r == ESC {
			r = 'n'
		}
		msg_putchar(r)
		out_flush()
	}
	no_wait_return--
	State = save_State
	no_mapping--
	allow_keys--

	return r
}

func get_keystroke() int32 {
	var buf Ptr[byte] = Ptr[byte]{}
	var buflen int32 = 150
	var maxlen int32
	var len_ int32 = 0
	var n int32
	var save_mapped_ctrl_c int32 = mapped_ctrl_c
	var waited int32 = 0

	mod_mask = 0
	mapped_ctrl_c = FALSE
	for {
		cursor_on()
		out_flush()

		maxlen = (buflen - 6 - len_) / 3
		if buf.Nil() {
			buf = Alloc(int(buflen))
		} else if maxlen < 10 {
			var t_buf Ptr[byte] = buf
			var t_buflen int32 = buflen

			buflen += 100
			buf = host_alloc(usize(buflen)).(Ptr[byte])
			Memmove(buf, t_buf, int(t_buflen))
			maxlen = (buflen - 6 - len_) / 3
		}
		if buf.Nil() {
			do_outofmem_msg(usize(long_u(buflen)))
			return ESC
		}

		var wtime int64
		if len_ == 0 {
			wtime = -1
		} else {
			wtime = 100
		}
		n = ui_inchar(buf.Add(int(len_)), maxlen, wtime, 0)
		if n > 0 {
			n = fix_input_buffer(buf.Add(int(len_)), n)
			len_ += n
			waited = 0
		} else if len_ > 0 {
			waited++
		}

		n = check_termcode(1, buf, buflen, &len_)
		if n < 0 {
			var tm int64
			if p_ttm < 0 {
				tm = p_tm
			} else {
				tm = p_ttm
			}
			if p_ttimeout == 0 || int64(waited)*100 < tm {
				continue
			}
		}

		if n == KEYLEN_REMOVED {
			if must_redraw != 0 && need_wait_return == 0 && State&(MODE_CMDLINE|(0x2000|MODE_NORMAL)|MODE_ASKMORE) == 0 {
				update_screen(0)
				setcursor()
			}
			continue
		}
		if n > 0 {
			len_ = n
		}
		if len_ == 0 {
			continue
		}

		n = int32(buf.At(0))
		if n == 0x80 {
			if buf.At(1) == KS_SPECIAL {
				n = 0x80
			} else if buf.At(1) == KS_ZERO {
				n = -(KS_ZERO + ('X' << 8))
			} else {
				n = -(int32(buf.At(1)) + (int32(buf.At(2)) << 8))
			}
			if buf.At(1) == KS_MODIFIER || n == -(KS_EXTRA+(KE_IGNORE<<8)) {
				if buf.At(1) == KS_MODIFIER {
					mod_mask = int32(buf.At(2))
				}
				len_ -= 3
				if len_ > 0 {
					Memmove(buf, buf.Add(3), int(len_))
				}
				continue
			}
			break
		}
		if int32(mb_bytelen_tab[n]) > len_ {
			continue
		}
		if len_ >= buflen {
			buf.Set(int(buflen-1), NUL)
		} else {
			buf.Set(int(len_), NUL)
		}
		n = utf_ptr2char(buf)
		if n == intr_char {
			n = ESC
		}
		break
	}

	mapped_ctrl_c = save_mapped_ctrl_c
	return merge_modifyOtherKeys(n, &mod_mask)
}

func msgmore(n int64) {
	var pn int64

	if global_busy != 0 || messaging() == 0 {
		return
	}

	if !keep_msg.Nil() && keep_msg_more == 0 {
		return
	}

	if n > 0 {
		pn = n
	} else {
		pn = -n
	}

	if pn > p_report {
		if n > 0 {
			vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT(S("%ld more line"), S("%ld more lines"), uint64(pn)), pn)
		} else {
			vim_snprintf(msg_buf, MSG_BUF_LEN, NGETTEXT(S("%ld line less"), S("%ld fewer lines"), uint64(pn)), pn)
		}
		if got_int != 0 {
			vim_strcat(msg_buf, gettext_(S(" (Interrupted)")), MSG_BUF_LEN)
		}
		if msg(msg_buf) != 0 {
			set_keep_msg(msg_buf, 0)
			keep_msg_more = TRUE
		}
	}
}

func beep_flush() {
	if emsg_silent == 0 {
		flush_buffers(FLUSH_MINIMAL)
		vim_beep(BO_ERROR)
	}
}

func vim_beep(val uint32) {
	if emsg_silent != 0 || in_assert_fails != 0 {
		return
	}

	if !(bo_flags&val != 0 || bo_flags&BO_ALL != 0) {
		if vim_beep_did_init == 0 || musl_now_ms()-vim_beep_start_tv > 500 {
			vim_beep_did_init = TRUE
			vim_beep_start_tv = musl_now_ms()
			if p_vb != 0 {
				out_str_cf(term_strings[KS_VB])
			} else {
				out_char(BELL)
			}
		}
	}

}

func expand_env_esc(srcp Ptr[byte], dst Ptr[byte], dstlen int32, esc_chars Ptr[byte], one int32, startstr Ptr[byte]) usize {
	var src Ptr[byte]
	var dst_start Ptr[byte] = dst

	src = skipwhite(srcp)
	dstlen--
	for src.Get() != 0 && dstlen > 0 {
		if src.At(0) == '\\' && src.At(1) != NUL {
			dst.Put(src.Get())
			dst = dst.Add(1)
			src = src.Add(1)
			dstlen--
		}
		if dstlen > 0 {
			dst.Put(src.Get())
			dst = dst.Add(1)
			src = src.Add(1)
			dstlen--
		}
	}
	dst.Put(NUL)

	return usize(dst.Sub(dst_start))
}

func prepare_to_exit() {

	{
		windgoto(int32(Rows)-1, cmdline_col_off)

		{
			var was_full_screen int32 = full_screen

			full_screen = TRUE
			term_leave()
			full_screen = was_full_screen
		}
		stoptermcap()
		out_flush()
	}
}

func preserve_exit() {

	prepare_to_exit()

	really_exiting = TRUE

	out_str(IObuff)
	screen_start()
	out_flush()

	ml_close_notmod()

	ml_close_all(FALSE)

	out_str(S("Vim: Finished.\r\n"))

	getout(1)
}

func line_breakcheck() {
	breakcheck_count++
	if breakcheck_count >= BREAKCHECK_SKIP {
		breakcheck_count = 0
		ui_breakcheck()
	}
}

func fast_breakcheck() {
	breakcheck_count++
	if breakcheck_count >= BREAKCHECK_SKIP*10 {
		breakcheck_count = 0
		ui_breakcheck()
	}
}

func goto_im() int32 {
	return B2i(p_im != 0 && stuff_empty() != 0 && typebuf_typed() != 0)
}

func path_is_url(p Ptr[byte]) int32 {
	if musl_strncmp(p, S("://"), usize(3)) == 0 {
		return URL_SLASH
	} else if musl_strncmp(p, S(":\\\\"), usize(3)) == 0 {
		return URL_BACKSLASH
	}
	return 0
}

func vim_append_digit_long(value *int64, digit int32) int32 {
	var x int64 = *value
	if x > ((LONG_MAX - int64(digit)) / 10) {
		return FAIL
	}
	*value = x*10 + int64(digit)
	return OK
}

func trim_to_int(x vimlong_T) int32 {
	if x > INT_MAX {
		return INT_MAX
	}
	if x < INT_MIN {
		return INT_MIN
	}
	return int32(x)
}

func virtual_active() int32 {
	var cur_ve_flags uint32 = get_ve_flags()

	if cur_ve_flags == VE_ALL || (cur_ve_flags&VE_INSERT != 0 && State&MODE_INSERT != 0) {
		return TRUE
	}

	if virtual_op != MAYBE {
		return virtual_op
	}
	return B2i(cur_ve_flags&VE_BLOCK != 0 && VIsual_active != 0 && VIsual_mode == Ctrl_V)
}

func getviscol() int32 {
	var x colnr_T

	getvvcol(curwin, &curwin.w_cursor, &x, nil, nil, 0)
	return int32(x)
}

func coladvance_force(wcol colnr_T) int32 {
	var rc int32 = coladvance2(&curwin.w_cursor, TRUE, FALSE, wcol)

	if wcol == MAXCOL {
		curwin.w_valid &^= VALID_VIRTCOL
	} else {
		set_valid_virtcol(curwin, wcol)
	}
	return rc
}

func getviscol2(col colnr_T, coladd colnr_T) int32 {
	var x colnr_T
	var pos pos_T

	pos.lnum = curwin.w_cursor.lnum
	pos.col = col
	pos.coladd = coladd
	getvvcol(curwin, &pos, &x, nil, nil, 0)
	return int32(x)
}

func coladvance(wantcol colnr_T) int32 {
	var rc int32 = getvpos(&curwin.w_cursor, wantcol)

	if wantcol == MAXCOL || rc == FAIL {
		curwin.w_valid &^= VALID_VIRTCOL
	} else if ml_get_cursor().Get() != TAB {
		set_valid_virtcol(curwin, wantcol)
	}
	return rc
}

func getvpos(pos *pos_T, wantcol colnr_T) int32 {
	return coladvance2(pos, FALSE, virtual_active(), wantcol)
}

func coladvance2(pos *pos_T, addspaces int32, finetune int32, wcol_arg colnr_T) int32 {
	var wcol colnr_T = wcol_arg
	var idx int32
	var line Ptr[byte]
	var linelen int32
	var col colnr_T = 0
	var csize int32 = 0
	var one_more int32

	one_more = B2i(State&MODE_INSERT != 0 ||
		restart_edit != NUL ||
		(VIsual_active != 0 && p_sel.Get() != 'o') ||
		(get_ve_flags()&VE_ONEMORE != 0 && wcol < MAXCOL))
	line = ml_get_buf(curbuf, pos.lnum, FALSE)
	linelen = ml_get_buf_len(curbuf, pos.lnum)

	if wcol >= MAXCOL {
		idx = linelen - 1 + one_more
		col = wcol

		if (addspaces != 0 || finetune != 0) && VIsual_active == 0 {
			curwin.w_curswant = linetabsize(curwin, pos.lnum) + one_more
			if curwin.w_curswant > 0 {
				curwin.w_curswant--
			}
		}
	} else {
		var width int32 = curwin.w_width - win_col_off(curwin)
		var cts chartabsize_T

		if finetune != 0 && curwin.w_onebuf_opt.wo_wrap != 0 && curwin.w_width != 0 && wcol >= colnr_T(width) && width > 0 {
			csize = linetabsize_eol(curwin, pos.lnum)
			if csize > 0 {
				csize--
			}

			if wcol/width > colnr_T(csize)/width && (State&MODE_INSERT == 0 || int32(wcol) > csize+1) {
				wcol = (csize/width+1)*width - 1
			}
		}

		init_chartabsize_arg(&cts, curwin, pos.lnum, 0, line, line)
		for cts.cts_vcol <= wcol && cts.cts_ptr.Get() != NUL {
			csize = lbr_chartabsize_adv(&cts)
			cts.cts_vcol += csize
		}
		col = cts.cts_vcol
		idx = int32(cts.cts_ptr.Sub(line))

		if col > wcol || (virtual_active() == 0 && one_more == 0) {
			idx -= 1
			col -= csize
		}

		if virtual_active() != 0 && addspaces != 0 && wcol >= 0 && ((col != wcol && col != wcol+1) || csize > 1) {
			if line.At(int(idx)) == NUL {
				var correct int32 = wcol - col
				var newline Ptr[byte] = Alloc(int(idx + correct + 1))
				var t int32

				if newline.Nil() {
					return FAIL
				}

				for t = 0; t < idx; t++ {
					newline.Set(int(t), line.At(int(t)))
				}

				for t = 0; t < correct; t++ {
					newline.Set(int(t+idx), ' ')
				}

				newline.Set(int(idx+correct), NUL)

				ml_replace(pos.lnum, newline, FALSE)
				changed_bytes(pos.lnum, colnr_T(idx))
				idx += correct
				col = wcol
			} else {
				var correct int32 = wcol - col - csize + 1
				var newline Ptr[byte]
				var t int32
				var s int32 = 0
				var v int32

				if -correct > csize {
					return FAIL
				}

				newline = Alloc(int(linelen + csize))

				for t = 0; t < linelen; t++ {
					if t != idx {
						newline.Set(int(s), line.At(int(t)))
						s++
					} else {
						for v = 0; v < csize; v++ {
							newline.Set(int(s), ' ')
							s++
						}
					}
				}

				newline.Set(int(linelen+csize-1), NUL)

				ml_replace(pos.lnum, newline, FALSE)
				changed_bytes(pos.lnum, idx)
				idx += (csize - 1 + correct)
				col += correct
			}
		}
	}

	if idx < 0 {
		pos.col = 0
	} else {
		pos.col = idx
	}

	pos.coladd = 0

	if finetune != 0 {
		if wcol == MAXCOL {
			if one_more == 0 {
				var scol colnr_T
				var ecol colnr_T

				getvcol(curwin, pos, &scol, nil, &ecol, 0)
				pos.coladd = ecol - scol
			}
		} else {
			var b int32 = int32(wcol) - int32(col)

			if b > 0 && b < (MAXCOL-2*curwin.w_width) {
				pos.coladd = b
			}

			col += b
		}
	}

	mb_adjustpos(curbuf, pos)

	if wcol < 0 || col < wcol {
		return FAIL
	}
	return OK
}

func inc_cursor() int32 {
	return inc(&curwin.w_cursor)
}

func inc(lp *pos_T) int32 {
	var p Ptr[byte]

	if lp.col != MAXCOL {
		p = ml_get_pos(lp)
		if p.Get() != NUL {
			var l int32 = utfc_ptr2len(p)

			lp.col += l
			if p.At(int(l)) != NUL {
				return 0
			}
			return 2
			// C: an unreachable single-byte branch follows (col++, coladd = 0,
			// return p[1] != NUL ? 0 : 2).
		}
	}
	if lp.lnum != curbuf.b_ml.ml_line_count {
		lp.col = 0
		lp.lnum++
		lp.coladd = 0
		return 1
	}
	return -1
}

func incl(lp *pos_T) int32 {
	var r int32

	r = inc(lp)
	if r >= 1 && lp.col != 0 {
		r = inc(lp)
	}
	return r
}

func dec_cursor() int32 {
	return dec(&curwin.w_cursor)
}

func dec(lp *pos_T) int32 {
	var p Ptr[byte]

	lp.coladd = 0
	if lp.col == MAXCOL {
		p = ml_get(lp.lnum)
		lp.col = ml_get_len(lp.lnum)
		lp.col -= utf_head_off(p, p.Add(int(lp.col)))
		return 0
	}

	if lp.col > 0 {
		lp.col--
		p = ml_get(lp.lnum)
		lp.col -= utf_head_off(p, p.Add(int(lp.col)))
		return 0
	}

	if lp.lnum > 1 {
		lp.lnum--
		p = ml_get(lp.lnum)
		lp.col = ml_get_len(lp.lnum)
		lp.col -= utf_head_off(p, p.Add(int(lp.col)))
		return 1
	}

	return -1
}

func decl(lp *pos_T) int32 {
	var r int32

	r = dec(lp)
	if r == 1 && lp.col != 0 {
		r = dec(lp)
	}
	return r
}

func get_cursor_rel_lnum(wp *S_window_S, lnum linenr_T) linenr_T {
	var cursor linenr_T = wp.w_cursor.lnum
	var retval linenr_T = 0

	retval = lnum - cursor

	return retval
}

func check_pos(buf *S_file_buffer, pos *pos_T) {
	var len_ colnr_T

	if pos.lnum > buf.b_ml.ml_line_count {
		pos.lnum = buf.b_ml.ml_line_count
	}

	if pos.col > 0 {
		len_ = ml_get_buf_len(buf, pos.lnum)
		if pos.col > len_ {
			pos.col = len_
		}
	}
}

func check_cursor_lnum() {
	if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
		curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
	}
	if curwin.w_cursor.lnum <= 0 {
		curwin.w_cursor.lnum = 1
	}
}

func check_cursor_col() {
	check_cursor_col_win(curwin)
}

func check_cursor_col_win(win *S_window_S) {
	var len_ colnr_T
	var oldcol colnr_T = win.w_cursor.col
	var oldcoladd colnr_T = win.w_cursor.col + win.w_cursor.coladd
	var cur_ve_flags uint32 = get_ve_flags()

	len_ = ml_get_buf_len(win.w_buffer, win.w_cursor.lnum)
	if len_ == 0 {
		win.w_cursor.col = 0
	} else if win.w_cursor.col >= len_ {
		if State&MODE_INSERT != 0 || restart_edit != 0 || (VIsual_active != 0 && p_sel.Get() != 'o') || cur_ve_flags&VE_ONEMORE != 0 || virtual_active() != 0 {
			win.w_cursor.col = len_
		} else {
			win.w_cursor.col = len_ - 1
			mb_adjustpos(win.w_buffer, &win.w_cursor)
		}
	} else if win.w_cursor.col < 0 {
		win.w_cursor.col = 0
	}

	if oldcol == MAXCOL {
		win.w_cursor.coladd = 0
	} else if cur_ve_flags == VE_ALL {
		if oldcoladd > win.w_cursor.col {
			win.w_cursor.coladd = oldcoladd - win.w_cursor.col

			if win.w_cursor.col+1 < len_ {
				var cs int32
				var ce int32

				getvcol(win, &win.w_cursor, &cs, nil, &ce, 0)
				if win.w_cursor.coladd > ce-cs {
					win.w_cursor.coladd = ce - cs
				}
			}
		} else {
			win.w_cursor.coladd = 0
		}
	}
}

func check_cursor() {
	check_cursor_lnum()
	check_cursor_col()
}

func check_visual_pos() {
	if VIsual.lnum > curbuf.b_ml.ml_line_count {
		VIsual.lnum = curbuf.b_ml.ml_line_count
		VIsual.col = 0
		VIsual.coladd = 0
	} else {
		var len_ int32 = ml_get_len(VIsual.lnum)

		if VIsual.col > len_ {
			VIsual.col = len_
			VIsual.coladd = 0
		}
	}
}

func adjust_cursor_col() {
	if curwin.w_cursor.col > 0 && (VIsual_active == 0 || p_sel.Get() == 'o') && gchar_cursor() == NUL {
		curwin.w_cursor.col--
	}
}

func set_leftcol(leftcol colnr_T) int32 {
	var retval int32 = FALSE

	if curwin.w_leftcol == leftcol {
		return FALSE
	}
	curwin.w_leftcol = leftcol

	changed_cline_bef_curs()
	var lastcol int64 = int64(curwin.w_leftcol + curwin.w_width - curwin_col_off() - 1)
	validate_virtcol()

	var siso int64 = get_sidescrolloff_value()
	if curwin.w_virtcol > colnr_T(lastcol-siso) {
		retval = TRUE
		coladvance(colnr_T(lastcol - siso))
	} else if int64(curwin.w_virtcol) < int64(curwin.w_leftcol)+siso {
		retval = TRUE
		_ = coladvance(colnr_T(int64(curwin.w_leftcol) + siso))
	}

	var s colnr_T
	var e colnr_T
	getvvcol(curwin, &curwin.w_cursor, &s, nil, &e, 0)
	if e > colnr_T(lastcol) {
		retval = TRUE
		coladvance(s - 1)
	} else if s < curwin.w_leftcol {
		retval = TRUE
		if coladvance(e+1) == FAIL {
			curwin.w_leftcol = s
			changed_cline_bef_curs()
		}
	}

	if retval != 0 {
		curwin.w_set_curswant = true
	}
	redraw_later(UPD_NOT_VALID)
	return retval
}

func copy_option_part(option *Ptr[byte], buf Ptr[byte], maxlen int32, sep_chars Ptr[byte]) int32 {
	var len_ int32 = 0
	var p Ptr[byte] = *option

	if p.Get() == '.' {
		buf.Set(int(len_), p.Get())
		len_++
		p = p.Add(1)
	}
	for p.Get() != NUL && vim_strchr(sep_chars, int32(p.Get())).Nil() {
		if p.At(0) == '\\' && !vim_strchr(sep_chars, int32(p.At(1))).Nil() {
			p = p.Add(1)
		}
		if len_ < maxlen-1 {
			buf.Set(int(len_), p.Get())
			len_++
		}
		p = p.Add(1)
	}
	buf.Set(int(len_), NUL)

	if p.Get() != NUL && p.Get() != ',' {
		p = p.Add(1)
	}
	p = skip_to_option_part(p)

	*option = p
	return len_
}

func vim_isspace(x int32) int32 {
	return B2i((x >= 9 && x <= 13) || x == ' ')
}

func name_to_mod_mask(c int32) int32 {
	var i int32

	if !(c < 'a' || c > 'z') {
		c = c - ('a' - 'A')
	}
	for i = 0; mod_mask_table[i].mod_mask != 0; i++ {
		if c == int32(mod_mask_table[i].name) {
			return int32(mod_mask_table[i].mod_flag)
		}
	}
	return 0
}

func simplify_key(key int32, modifiers *int32) int32 {
	var i int32
	var key0 int32
	var key1 int32

	if *modifiers&(MOD_MASK_SHIFT|MOD_MASK_CTRL) == 0 {
		return key
	}

	if key == TAB && *modifiers&MOD_MASK_SHIFT != 0 {
		*modifiers &^= MOD_MASK_SHIFT
		return -('k' + ('B' << 8))
	}
	key0 = (-key) & 0xff
	key1 = int32((uint32(-key) >> 8) & 0xff)
	for i = 0; modifier_keys_table[i] != NUL; i += MOD_KEYS_ENTRY_SIZE {
		if key0 == int32(modifier_keys_table[i+3]) && key1 == int32(modifier_keys_table[i+4]) && *modifiers&int32(modifier_keys_table[i]) != 0 {
			*modifiers &^= int32(modifier_keys_table[i])
			return -(int32(modifier_keys_table[i+1]) + (int32(modifier_keys_table[i+2]) << 8))
		}
	}
	return key
}

func handle_x_keys(key int32) int32 {
	switch key {
	case -(KS_EXTRA + (KE_XUP << 8)):
		return -('k' + ('u' << 8))
	case -(KS_EXTRA + (KE_XDOWN << 8)):
		return -('k' + ('d' << 8))
	case -(KS_EXTRA + (KE_XLEFT << 8)):
		return -('k' + ('l' << 8))
	case -(KS_EXTRA + (KE_XRIGHT << 8)):
		return -('k' + ('r' << 8))
	case -(KS_EXTRA + (KE_XHOME << 8)):
		return -('k' + ('h' << 8))
	case -(KS_EXTRA + (KE_ZHOME << 8)):
		return -('k' + ('h' << 8))
	case -(KS_EXTRA + (KE_XEND << 8)):
		return -('@' + ('7' << 8))
	case -(KS_EXTRA + (KE_ZEND << 8)):
		return -('@' + ('7' << 8))
	case -(KS_EXTRA + (KE_XF1 << 8)):
		return -('k' + ('1' << 8))
	case -(KS_EXTRA + (KE_XF2 << 8)):
		return -('k' + ('2' << 8))
	case -(KS_EXTRA + (KE_XF3 << 8)):
		return -('k' + ('3' << 8))
	case -(KS_EXTRA + (KE_XF4 << 8)):
		return -('k' + ('4' << 8))
	case -(KS_EXTRA + (KE_S_XF1 << 8)):
		return -(KS_EXTRA + (KE_S_F1 << 8))
	case -(KS_EXTRA + (KE_S_XF2 << 8)):
		return -(KS_EXTRA + (KE_S_F2 << 8))
	case -(KS_EXTRA + (KE_S_XF3 << 8)):
		return -(KS_EXTRA + (KE_S_F3 << 8))
	case -(KS_EXTRA + (KE_S_XF4 << 8)):
		return -(KS_EXTRA + (KE_S_F4 << 8))
	}
	return key
}

func get_special_key_name(c int32, modifiers int32) Ptr[byte] {
	var string_ Ptr[byte] = get_special_key_name_string
	var i int32
	var idx int32
	var len_ int32
	var table_idx int32

	string_.Set(0, '<')
	idx = 1

	if c < 0 && (-c)&0xff == KS_KEY {
		c = int32((uint32(-c) >> 8) & 0xff)
	}

	if c < 0 {
		for i = 0; modifier_keys_table[i] != 0; i += MOD_KEYS_ENTRY_SIZE {
			if (-c)&0xff == int32(modifier_keys_table[i+1]) && int32((uint32(-c)>>8)&0xff) == int32(modifier_keys_table[i+2]) {
				modifiers |= int32(modifier_keys_table[i])
				c = -(int32(modifier_keys_table[i+3]) + (int32(modifier_keys_table[i+4]) << 8))
				break
			}
		}
	}

	table_idx = find_special_key_in_table(c)

	if c > 0 && utf_char2len(c) == 1 {
		if table_idx < 0 && (vim_isprintc(c) == 0 || (c&0x7f) == ' ') && c&0x80 != 0 {
			c &= 0x7f
			modifiers |= MOD_MASK_ALT
			table_idx = find_special_key_in_table(c)
		}
		if table_idx < 0 && vim_isprintc(c) == 0 && c < ' ' {
			c += '@'
			modifiers |= MOD_MASK_CTRL
		}
	}

	for i = 0; mod_mask_table[i].name != 'A'; i++ {
		if modifiers&int32(mod_mask_table[i].mod_mask) == int32(mod_mask_table[i].mod_flag) {
			string_.Set(int(idx), mod_mask_table[i].name)
			idx++
			string_.Set(int(idx), '-')
			idx++
		}
	}

	if table_idx < 0 {
		if c < 0 {
			string_.Set(int(idx), 't')
			idx++
			string_.Set(int(idx), '_')
			idx++
			string_.Set(int(idx), byte((-c)&0xff))
			idx++
			string_.Set(int(idx), byte((uint32(-c)>>8)&0xff))
			idx++
		} else {
			len_ = utf_char2len(c)
			if len_ == 1 && vim_isprintc(c) != 0 {
				string_.Set(int(idx), byte(c))
				idx++
			} else if len_ > 1 {
				idx += utf_char2bytes(c, string_.Add(int(idx)))
			} else {
				var s Ptr[byte] = transchar(c)
				for s.Get() != 0 {
					string_.Set(int(idx), s.Get())
					idx++
					s = s.Add(1)
				}
			}
		}
	} else {
		var s *string_T

		s = &key_names_table.Ref(int(table_idx)).name

		if s.length+usize(idx)+2 <= MAX_KEY_NAME_LEN {
			musl_strcpy(string_.Add(int(idx)), s.string_)
			idx += int32(s.length)
		}
	}
	string_.Set(int(idx), '>')
	idx++
	string_.Set(int(idx), NUL)

	return string_
}

func trans_special(srcp *Ptr[byte], dst Ptr[byte], flags int32, escape_ks int32, did_simplify *int32) int32 {
	var modifiers int32 = 0
	var key int32

	key = find_special_key(srcp, &modifiers, flags, did_simplify)
	if key == 0 {
		return 0
	}

	return special_to_buf(key, modifiers, escape_ks, dst)
}

func special_to_buf(key int32, modifiers int32, escape_ks int32, dst Ptr[byte]) int32 {
	var dlen int32 = 0

	if modifiers != 0 {
		dst.Set(int(dlen), 0x80)
		dlen++
		dst.Set(int(dlen), KS_MODIFIER)
		dlen++
		dst.Set(int(dlen), byte(modifiers))
		dlen++
	}

	if key < 0 {
		dst.Set(int(dlen), 0x80)
		dlen++
		dst.Set(int(dlen), byte((-key)&0xff))
		dlen++
		dst.Set(int(dlen), byte((uint32(-key)>>8)&0xff))
		dlen++
	} else if escape_ks != 0 {
		dlen = int32(add_char2buf(key, dst.Add(int(dlen))).Sub(dst))
	} else {
		dlen += utf_char2bytes(key, dst.Add(int(dlen)))
	}

	return dlen
}

func find_special_key(srcp *Ptr[byte], modp *int32, flags int32, did_simplify *int32) int32 {
	var last_dash Ptr[byte]
	var end_of_name Ptr[byte]
	var src Ptr[byte]
	var bp Ptr[byte]
	var in_string int32 = flags & FSK_IN_STRING
	var modifiers int32
	var bit int32
	var key int32
	var n uvarnumber_T
	var l int32

	src = *srcp
	if src.At(0) != '<' {
		return 0
	}
	if src.At(1) == '*' {
		src = src.Add(1)
	}

	last_dash = src
	for bp = src.Add(1); bp.Get() == '-' || vim_isNormalIDc(int32(bp.Get())) != 0; bp = bp.Add(1) {
		if bp.Get() == '-' {
			last_dash = bp
			if bp.At(1) != NUL {
				l = utfc_ptr2len(bp.Add(1))
				if !(in_string != 0 && bp.At(1) == '"') && bp.At(int(l+1)) == '>' {
					bp = bp.Add(int(l))
				} else if in_string != 0 && bp.At(1) == '\\' && bp.At(2) == '"' && bp.At(3) == '>' {
					bp = bp.Add(2)
				}
			}
		}
		if bp.At(0) == 't' && bp.At(1) == '_' && bp.At(2) != 0 && bp.At(3) != 0 {
			bp = bp.Add(3)
		} else if musl_strncasecmp(bp, S("char-"), 5) == 0 {
			vim_str2nr(bp.Add(5), nil, &l, STR2NR_BIN+STR2NR_OCT+STR2NR_HEX+STR2NR_OOCT, nil, nil, 0, TRUE, nil)
			if l == 0 {
				emsg(gettext_(e_invalid_argument))
				return 0
			}
			bp = bp.Add(int(l + 5))
			break
		}
	}

	if bp.Get() == '>' {
		end_of_name = bp.Add(1)

		modifiers = 0x0
		for bp = src.Add(1); bp.Lt(last_dash); bp = bp.Add(1) {
			if bp.Get() != '-' {
				bit = name_to_mod_mask(int32(bp.Get()))
				if bit == 0x0 {
					break
				}
				modifiers |= bit
			}
		}

		if bp.Ge(last_dash) {
			if musl_strncasecmp(last_dash.Add(1), S("char-"), 5) == 0 && uint32(last_dash.At(6))-'0' < 10 {
				vim_str2nr(last_dash.Add(6), nil, &l, STR2NR_BIN+STR2NR_OCT+STR2NR_HEX+STR2NR_OOCT, nil, &n, 0, TRUE, nil)
				if l == 0 {
					emsg(gettext_(e_invalid_argument))
					return 0
				}
				key = int32(n)
			} else {
				var off int32 = 1

				if in_string != 0 && last_dash.At(1) == '\\' && last_dash.At(2) == '"' {
					off = 2
				}
				l = utfc_ptr2len(last_dash.Add(int(off)))
				if modifiers != 0 && last_dash.At(int(l+off)) == '>' {
					key = utf_ptr2char(last_dash.Add(int(off)))
				} else {
					key = get_special_key_code(last_dash.Add(int(off)))
					if flags&FSK_KEEP_X_KEY == 0 {
						key = handle_x_keys(key)
					}
				}
			}

			if key != NUL {
				key = simplify_key(key, &modifiers)

				if flags&FSK_KEYCODE == 0 {
					if key == -('k' + ('b' << 8)) {
						key = BS
					} else if key == -('k'+('D'<<8)) || key == -(KS_EXTRA+(KE_KDEL<<8)) {
						key = DEL
					}
				} else if key == 27 && flags&FSK_FROM_PART != 0 && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED) {
					if flags&FSK_SIMPLIFY != 0 {
						if did_simplify != nil {
							*did_simplify = TRUE
						}
					} else {
						key = -(KS_EXTRA + (KE_ESC << 8))
					}
				}

				if !(key < 0) {
					key = extract_modifiers(key, &modifiers, flags&FSK_SIMPLIFY, did_simplify)
				}

				*modp = modifiers
				*srcp = end_of_name
				return key
			}
		}
	}
	return 0
}

func may_adjust_key_for_ctrl(modifiers int32, key int32) int32 {
	if modifiers&MOD_MASK_CTRL == 0 {
		return key
	}

	if uint32(key)-'A' < 26 || uint32(key)-'a' < 26 {
		if no_reduce_keys == 0 {
			if key < 'a' || key > 'z' {
				return key
			}
			return key - ('a' - 'A')
		}
		return key
	}
	if key == '2' {
		return '@'
	}
	if key == '6' {
		return '^'
	}
	if key == '-' {
		return '_'
	}

	if key == '$' && modifiers&MOD_MASK_SHIFT == 0 {
		return ']'
	}

	return key
}

func may_remove_shift_modifier(modifiers int32, key int32) int32 {
	if (modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT|MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT|MOD_MASK_META)) && ((key >= '!' && key <= '/') || (key >= ':' && key <= 'Z') || vim_isdigit(key) != 0 || (key >= '[' && key <= '`') || (key >= '{' && key <= '~')) {
		return modifiers &^ MOD_MASK_SHIFT
	}

	if modifiers == (MOD_MASK_SHIFT|MOD_MASK_CTRL) && (key == '{' || key == '}' || key == '|') {
		return modifiers &^ MOD_MASK_SHIFT
	}

	return modifiers
}

func extract_modifiers(key int32, modp *int32, simplify int32, did_simplify *int32) int32 {
	var modifiers int32 = *modp

	if modifiers&MOD_MASK_SHIFT != 0 && (uint32(key)-'A' < 26 || uint32(key)-'a' < 26) {
		if !(key < 'a' || key > 'z') {
			key = key - ('a' - 'A')
		}
		if simplify != 0 || modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT|MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT|MOD_MASK_META) {
			modifiers &^= MOD_MASK_SHIFT
		}
	}

	if modifiers&MOD_MASK_CTRL != 0 && (uint32(key)-'A' < 26 || uint32(key)-'a' < 26) {
		if !(key < 'a' || key > 'z') {
			key = key - ('a' - 'A')
		}
	}

	if simplify != 0 && modifiers&MOD_MASK_CTRL != 0 && ((key >= '?' && key <= '_') || (uint32(key)-'A' < 26 || uint32(key)-'a' < 26)) {
		var k int32 = key
		if !(key < 'a' || key > 'z') {
			k = key - ('a' - 'A')
		}
		key = k ^ 0x40
		modifiers &^= MOD_MASK_CTRL
		if key == NUL {
			key = -(KS_ZERO + ('X' << 8))
		}
		if did_simplify != nil {
			*did_simplify = TRUE
		}
	}

	if simplify != 0 && modifiers&MOD_MASK_ALT != 0 && key < 0x80 {
		key |= 0x80
		modifiers &^= MOD_MASK_ALT
		if did_simplify != nil {
			*did_simplify = TRUE
		}
	}

	*modp = modifiers
	return key
}

// ==== from f09.go ====
// Transpiled by hand from editor.c: find_special_key_in_table .. nv_zet.

func find_special_key_in_table(c int32) int32 {
	var i int32

	for i = 0; i < int32(key_names_table.Len()); i++ {
		if c == key_names_table.Ref(int(i)).key && key_names_table.Ref(int(i)).is_alt == 0 {
			if key_names_table.Ref(int(i)).enabled != 0 {
				return i
			}
			return -1
		}
	}

	return -1
}

func cmp_key_name_entry(a *S_key_name_entry, b *S_key_name_entry) int32 {
	p1 := a.name.string_
	p2 := b.name.string_
	var result int32 = 0

	if p1 == p2 {
		return 0
	}

	for vim_isNormalIDc(int32(p1.Get())) != 0 && p2.Get() != NUL {
		var c1, c2 int32
		if p1.Get() < 'A' || p1.Get() > 'Z' {
			c1 = int32(p1.Get())
		} else {
			c1 = int32(p1.Get()) + ('a' - 'A')
		}
		if p2.Get() < 'A' || p2.Get() > 'Z' {
			c2 = int32(p2.Get())
		} else {
			c2 = int32(p2.Get()) + ('a' - 'A')
		}
		result = c1 - c2
		if result != 0 {
			break
		}
		p1 = p1.Add(1)
		p2 = p2.Add(1)
	}

	if result == 0 {
		if p2.Get() == NUL {
			if vim_isNormalIDc(int32(p1.Get())) != 0 {
				result = 1
			}
		} else {
			result = -1
		}
	}

	return result
}
func key_name_bsearch(key *S_key_name_entry, base Ptr[S_key_name_entry], nel usize, cmp func(*S_key_name_entry, *S_key_name_entry) int32) Ptr[S_key_name_entry] {
	var tryp Ptr[S_key_name_entry]
	var sign int32

	for nel > 0 {
		tryp = base.Add(int(nel / 2))
		sign = cmp(key, tryp.P())
		if sign < 0 {
			nel /= 2
		} else if sign > 0 {
			base = tryp.Add(1)
			nel -= nel/2 + 1
		} else {
			return tryp
		}
	}
	return Ptr[S_key_name_entry]{}
}

func get_special_key_code(name Ptr[byte]) int32 {
	if name.At(0) == 't' && name.At(1) == '_' && name.At(2) != NUL && name.At(3) != NUL {
		string_ := Mk[byte](3)

		string_.Set(0, name.At(2))
		string_.Set(1, name.At(3))
		string_.Set(2, NUL)
		if add_termcap_entry(string_, FALSE) == OK {
			return -(int32(name.At(2)) + (int32(name.At(3)) << 8))
		}
	} else {
		var target S_key_name_entry
		var entry Ptr[S_key_name_entry]

		target.enabled = TRUE
		target.key = 0
		target.name.string_ = name
		target.name.length = 0

		entry = key_name_bsearch(&target, key_names_table, usize(117), cmp_key_name_entry) // C: sizeof(key_names_table) / sizeof(key_names_table.Ref(int(0)))
		if !entry.Nil() && entry.P().enabled != 0 {
			key := entry.P().key
			if key == -(KS_EXTRA + (int32(KE_TAB) << 8)) {
				return TAB
			}
			return key
		}
	}

	return 0
}

func get_real_state() int32 {
	if State&MODE_NORMAL != 0 {
		if VIsual_active != 0 {
			if VIsual_select != 0 {
				return MODE_SELECT
			}
			return MODE_VISUAL
		} else if finish_op != 0 {
			return MODE_OP_PENDING
		}
	}
	return State
}

