func validate_botline_win(wp *S_window_S) {
	if wp.w_valid&VALID_BOTLINE == 0 {
		comp_botline(wp)
	}
}

func invalidate_botline() {
	curwin.w_valid &= ^(VALID_BOTLINE | VALID_BOTLINE_AP)
}

func invalidate_botline_win(wp *S_window_S) {
	wp.w_valid &= ^(VALID_BOTLINE | VALID_BOTLINE_AP)
}

