func nv_ident(cap_ *S_cmdarg_S) {
	ptr := Ptr[byte]{}
	var buf Ptr[byte]
	var bufsize usize
	var buflen usize
	var p Ptr[byte]
	var n int32 = 0
	var cmdchar int32
	var g_cmd int32
	var aux_ptr Ptr[byte]

	if cap_.cmdchar == 'g' {
		cmdchar = cap_.nchar
		g_cmd = TRUE
	} else {
		cmdchar = cap_.cmdchar
		g_cmd = FALSE
	}

	if cmdchar == POUND {
		cmdchar = '#'
	}

	if ptr.Nil() {
		var ft int32
		if cmdchar == '*' || cmdchar == '#' {
			ft = FIND_IDENT | FIND_STRING
		} else {
			ft = FIND_IDENT
		}
		n = find_ident_under_cursor(&ptr, ft)
		if n == 0 {
			clearop(cap_.oap)
			return
		}
	}

	bufsize = usize(n*2 + 30)
	buf = Alloc(int(bufsize))
	buf.Set(0, NUL)
	buflen = 0

	setpcmark()
	curwin.w_cursor.col = colnr_T(ptr.Sub(ml_get_curline()))

	if g_cmd == 0 && vim_iswordp(ptr) != 0 {
		musl_strcpy(buf, S("\\<"))
		buflen = 2
	}
	no_smartcase = TRUE

	if cmdchar == '*' {
		if magic_isset() != 0 {
			aux_ptr = S("/.*~[^$\\")
		} else {
			aux_ptr = S("/^$\\")
		}
	} else {
		if magic_isset() != 0 {
			aux_ptr = S("/?.*~[^$\\")
		} else {
			aux_ptr = S("/?^$\\")
		}
	}

	p = buf.Add(int(buflen))
	for {
		cond := n > 0
		n--
		if !cond {
			break
		}
		if !vim_strchr(aux_ptr, int32(ptr.Get())).Nil() {
			p.Put('\\')
			p = p.Add(1)
		}

		var i int32
		len_ := utfc_ptr2len(ptr) - 1

		for i = 0; i < len_ && n >= 1; i, n = i+1, n-1 {
			p.Put(ptr.Get())
			p = p.Add(1)
			ptr = ptr.Add(1)
		}
		p.Put(ptr.Get())
		p = p.Add(1)
		ptr = ptr.Add(1)
	}
	p.Put(NUL)
	buflen = usize(p.Sub(buf))

	if g_cmd == 0 && vim_iswordp(mb_prevptr(ml_get_curline(), ptr)) != 0 {
		musl_strcpy(buf.Add(int(buflen)), S("\\>"))
		buflen += 2
	}

	init_history()
	add_to_history(HIST_SEARCH, buf, buflen, TRUE, NUL)

	var dir int32
	if cmdchar == '*' {
		dir = '/'
	} else {
		dir = '?'
	}
	normal_search(cap_, dir, buf, buflen, 0, nil)
}

func nv_tagpop(cap_ *S_cmdarg_S) {
	checkclearopq(cap_.oap)
}

func nv_scroll(cap_ *S_cmdarg_S) {
	var used int32 = 0
	var n int64
	var half int32

	cap_.oap.motion_type = MLINE
	setpcmark()

	if cap_.cmdchar == 'L' {
		validate_botline()
		curwin.w_cursor.lnum = curwin.w_botline - 1
		if cap_.count1-1 >= curwin.w_cursor.lnum {
			curwin.w_cursor.lnum = 1
		} else {
			curwin.w_cursor.lnum -= cap_.count1 - 1
		}
	} else {
		if cap_.cmdchar == 'M' {
			validate_botline()
			half = (curwin.w_height - curwin.w_empty_rows + 1) / 2
			for n = 0; curwin.w_topline+n < curbuf.b_ml.ml_line_count; n++ {
				used += plines(curwin.w_topline + n)
				if used >= half {
					break
				}
			}
			if n > 0 && used > curwin.w_height {
				n--
			}
		} else {
			n = cap_.count1 - 1
		}
		curwin.w_cursor.lnum = curwin.w_topline + n
		if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
			curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
		}
	}

	if cap_.oap.op_type == OP_NOP {
		cursor_correct()
	}
	beginline(BL_SOL | BL_FIX)
}

func nv_right(cap_ *S_cmdarg_S) {
	var n int64
	var past_line int32

	if mod_mask&(MOD_MASK_SHIFT|MOD_MASK_CTRL) != 0 {
		if mod_mask&MOD_MASK_CTRL != 0 {
			cap_.arg = TRUE
		}
		nv_wordcmd(cap_)
		return
	}

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	past_line = B2i(VIsual_active != 0 && p_sel.Get() != 'o')

	if virtual_active() != 0 {
		past_line = 0
	}

	for n = cap_.count1; n > 0; n-- {
		if (past_line == 0 && oneright() == FAIL) || (past_line != 0 && ml_get_cursor().Get() == NUL) {
			if ((cap_.cmdchar == ' ' && !vim_strchr(p_ww, 's').Nil()) || (cap_.cmdchar == 'l' && !vim_strchr(p_ww, 'l').Nil()) || (cap_.cmdchar == -('k'+('r'<<8)) && !vim_strchr(p_ww, '>').Nil())) && curwin.w_cursor.lnum < curbuf.b_ml.ml_line_count {
				if cap_.oap.op_type != OP_NOP && cap_.oap.inclusive == 0 && !(ml_get(curwin.w_cursor.lnum).Get() == NUL) {
					cap_.oap.inclusive = TRUE
				} else {
					curwin.w_cursor.lnum++
					curwin.w_cursor.col = 0
					curwin.w_cursor.coladd = 0
					curwin.w_set_curswant = true
					cap_.oap.inclusive = FALSE
				}
				continue
			}
			if cap_.oap.op_type == OP_NOP {
				if n == cap_.count1 {
					beep_flush()
				}
			} else {
				if !(ml_get(curwin.w_cursor.lnum).Get() == NUL) {
					cap_.oap.inclusive = TRUE
				}
			}
			break
		} else if past_line != 0 {
			curwin.w_set_curswant = true
			if virtual_active() != 0 {
				oneright()
			} else {
				curwin.w_cursor.col += utfc_ptr2len(ml_get_cursor())
			}
		}
	}
}

func nv_left(cap_ *S_cmdarg_S) {
	var n int64

	if mod_mask&(MOD_MASK_SHIFT|MOD_MASK_CTRL) != 0 {
		if mod_mask&MOD_MASK_CTRL != 0 {
			cap_.arg = 1
		}
		nv_bck_word(cap_)
		return
	}

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	for n = cap_.count1; n > 0; n-- {
		if oneleft() == FAIL {
			if (((cap_.cmdchar == -('k'+('b'<<8)) || cap_.cmdchar == Ctrl_H) && !vim_strchr(p_ww, 'b').Nil()) || (cap_.cmdchar == 'h' && !vim_strchr(p_ww, 'h').Nil()) || (cap_.cmdchar == -('k'+('l'<<8)) && !vim_strchr(p_ww, '<').Nil())) && curwin.w_cursor.lnum > 1 {
				curwin.w_cursor.lnum--
				coladvance(colnr_T(MAXCOL))
				curwin.w_set_curswant = true

				if (cap_.oap.op_type == OP_DELETE || cap_.oap.op_type == OP_CHANGE) && !(ml_get(curwin.w_cursor.lnum).Get() == NUL) {
					cp := ml_get_cursor()

					if cp.Get() != NUL {
						curwin.w_cursor.col += utfc_ptr2len(cp)
					}
					cap_.retval |= CA_NO_ADJ_OP_END
				}
				continue
			} else if cap_.oap.op_type == OP_NOP && n == cap_.count1 {
				beep_flush()
			}
			break
		}
	}
}

func nv_up(cap_ *S_cmdarg_S) {
	if mod_mask&MOD_MASK_SHIFT != 0 {
		cap_.arg = -1
		nv_page(cap_)
		return
	}

	cap_.oap.motion_type = MLINE
	if cursor_up(cap_.count1, B2i(cap_.oap.op_type == OP_NOP)) == FAIL {
		clearopbeep(cap_.oap)
	} else if cap_.arg != 0 {
		beginline(BL_WHITE | BL_FIX)
	}
}

func nv_down(cap_ *S_cmdarg_S) {
	if mod_mask&MOD_MASK_SHIFT != 0 {
		cap_.arg = FORWARD
		nv_page(cap_)
	} else {
		cap_.oap.motion_type = MLINE
		if cursor_down(cap_.count1, B2i(cap_.oap.op_type == OP_NOP)) == FAIL {
			clearopbeep(cap_.oap)
		} else if cap_.arg != 0 {
			beginline(BL_WHITE | BL_FIX)
		}
	}
}

func nv_end(cap_ *S_cmdarg_S) {
	if cap_.arg != 0 || (mod_mask&MOD_MASK_CTRL) != 0 {
		cap_.arg = TRUE
		nv_goto(cap_)
		cap_.count1 = 1
	}
	nv_dollar(cap_)
}

func nv_dollar(cap_ *S_cmdarg_S) {
	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = TRUE
	if virtual_active() == 0 || gchar_cursor() != NUL || cap_.oap.op_type == OP_NOP {
		curwin.w_curswant = MAXCOL
	}
	if cursor_down(int64(cap_.count1-1), B2i(cap_.oap.op_type == OP_NOP)) == FAIL {
		clearopbeep(cap_.oap)
	}
}

func nv_search(cap_ *S_cmdarg_S) {
	oap := cap_.oap
	save_cursor := curwin.w_cursor

	cap_.searchbuf = getcmdline(cap_.cmdchar, cap_.count1, 0, 0)

	if cap_.searchbuf.Nil() {
		clearop(oap)
		return
	}

	var opt int32
	if cap_.arg != 0 || !(save_cursor.lnum == curwin.w_cursor.lnum && save_cursor.col == curwin.w_cursor.col && save_cursor.coladd == curwin.w_cursor.coladd) {
		opt = 0
	} else {
		opt = SEARCH_MARK
	}
	normal_search(cap_, cap_.cmdchar, cap_.searchbuf, musl_strlen(cap_.searchbuf), opt, nil)
}

func nv_next(cap_ *S_cmdarg_S) {
	old := curwin.w_cursor
	var wrapped int32 = FALSE
	i := normal_search(cap_, 0, Ptr[byte]{}, 0, SEARCH_MARK|cap_.arg, &wrapped)

	if i == 1 && wrapped == 0 && (old.lnum == curwin.w_cursor.lnum && old.col == curwin.w_cursor.col && old.coladd == curwin.w_cursor.coladd) {
		cap_.count1 += 1
		normal_search(cap_, 0, Ptr[byte]{}, 0, SEARCH_MARK|cap_.arg, nil)
		cap_.count1 -= 1
	}

	if i > 0 && p_hls != 0 && no_hlsearch == 0 {
		redraw_later(UPD_SOME_VALID)
	}
}

func normal_search(cap_ *S_cmdarg_S, dir int32, pat Ptr[byte], patlen usize, opt int32, wrapped *int32) int32 {
	var i int32
	var sia searchit_arg_T
	prev_cursor := curwin.w_cursor

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	cap_.oap.use_reg_one = TRUE
	curwin.w_set_curswant = true

	sia = searchit_arg_T{}
	i = do_search(cap_.oap, dir, dir, pat, patlen, cap_.count1, opt|SEARCH_OPT|SEARCH_ECHO|SEARCH_MSG, &sia)
	if wrapped != nil {
		*wrapped = sia.sa_wrapped
	}
	if i == 0 {
		clearop(cap_.oap)
	} else {
		if i == 2 {
			cap_.oap.motion_type = MLINE
		}
		curwin.w_cursor.coladd = 0
	}
	if !(curwin.w_cursor.lnum == prev_cursor.lnum && curwin.w_cursor.col == prev_cursor.col && curwin.w_cursor.coladd == prev_cursor.coladd) && p_hls != 0 && no_hlsearch == 0 {
		redraw_later(UPD_SOME_VALID)
	}

	check_cursor()

	return i
}

func nv_csearch(cap_ *S_cmdarg_S) {
	var t_cmd int32
	var cursor_dec int32 = FALSE

	if p_sel.Get() == 'e' && VIsual_active != 0 && VIsual_mode == 'v' && VIsual_select_exclu_adj != 0 {
		unadjust_for_sel()
		cursor_dec = TRUE
	}

	if cap_.cmdchar == 't' || cap_.cmdchar == 'T' {
		t_cmd = TRUE
	} else {
		t_cmd = FALSE
	}

	cap_.oap.motion_type = MCHAR
	if cap_.nchar < 0 || searchc(cap_, t_cmd) == FAIL {
		clearopbeep(cap_.oap)
		if cursor_dec != 0 {
			adjust_for_sel(cap_)
		}
		return
	}

	curwin.w_set_curswant = true
	if gchar_cursor() == TAB && virtual_active() != 0 && cap_.arg == FORWARD && (t_cmd != 0 || cap_.oap.op_type != OP_NOP) {
		var scol colnr_T
		var ecol colnr_T

		getvcol(curwin, &curwin.w_cursor, &scol, nil, &ecol, 0)
		curwin.w_cursor.coladd = ecol - scol
	} else {
		curwin.w_cursor.coladd = 0
	}
	adjust_for_sel(cap_)
}

func nv_bracket_block(cap_ *S_cmdarg_S, old_pos *pos_T) {
	new_pos := pos_T{0, 0, 0}
	var pos *pos_T = nil
	var n int64
	var findc int32

	findc = cap_.nchar
	n = cap_.count1
	for ; n > 0; n-- {
		var fl int32
		if cap_.cmdchar == '[' {
			fl = FM_BACKWARD
		} else {
			fl = FM_FORWARD
		}
		pos = findmatchlimit(cap_.oap, findc, fl, 0)
		if pos == nil {
			if new_pos.lnum == 0 {
				clearopbeep(cap_.oap)
			} else {
				pos = &new_pos
			}
			break
		}
		curwin.w_cursor = *pos
		new_pos = *pos
	}
	curwin.w_cursor = *old_pos

	if pos != nil {
		setpcmark()
		curwin.w_cursor = *pos
		curwin.w_set_curswant = true
	}
}

func nv_brackets(cap_ *S_cmdarg_S) {
	var prev_pos pos_T
	pos := Ptr[pos_T]{}
	var old_pos pos_T
	var n int64

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	old_pos = curwin.w_cursor
	curwin.w_cursor.coladd = 0

	if (cap_.cmdchar == '[' && !vim_strchr(S("{("), cap_.nchar).Nil()) || (cap_.cmdchar == ']' && !vim_strchr(S("})"), cap_.nchar).Nil()) {
		nv_bracket_block(cap_, &old_pos)
	} else if cap_.nchar == 'p' || cap_.nchar == 'P' {
		nv_put_opt(cap_, TRUE)
	} else if cap_.nchar == '\'' || cap_.nchar == '`' {
		pos = Addr(&curwin.w_cursor)
		for n = cap_.count1; n > 0; n-- {
			prev_pos = pos.Get()
			var dir int32
			if cap_.cmdchar == '[' {
				dir = -1
			} else {
				dir = FORWARD
			}
			pos = getnextmark(pos, dir, B2i(cap_.nchar == '\''))
			if pos.Nil() {
				break
			}
		}
		if pos.Nil() {
			pos = Addr(&prev_pos)
		}
		nv_cursormark(cap_, B2i(cap_.nchar == '\''), pos)
	} else {
		clearopbeep(cap_.oap)
	}
}

func nv_percent(cap_ *S_cmdarg_S) {
	var pos *pos_T

	cap_.oap.inclusive = TRUE
	if cap_.count0 != 0 {
		if cap_.count0 > 100 {
			clearopbeep(cap_.oap)
		} else {
			cap_.oap.motion_type = MLINE
			setpcmark()
			if curbuf.b_ml.ml_line_count >= 21474836 {
				curwin.w_cursor.lnum = (curbuf.b_ml.ml_line_count + 99) / 100 * cap_.count0
			} else {
				curwin.w_cursor.lnum = (curbuf.b_ml.ml_line_count*cap_.count0 + 99) / 100
			}
			if curwin.w_cursor.lnum < 1 {
				curwin.w_cursor.lnum = 1
			}
			if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
				curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
			}
			beginline(BL_SOL | BL_FIX)
		}
	} else {
		var flags int32 = 0

		cap_.oap.motion_type = MCHAR
		cap_.oap.use_reg_one = TRUE
		pos = findmatchlimit(cap_.oap, NUL, flags, 0)
		if pos == nil {
			clearopbeep(cap_.oap)
		} else {
			setpcmark()
			curwin.w_cursor = *pos
			curwin.w_set_curswant = true
			curwin.w_cursor.coladd = 0
			adjust_for_sel(cap_)
		}
	}
}

func nv_mark(cap_ *S_cmdarg_S) {
	if checkclearop(cap_.oap) != 0 {
		return
	}

	if setmark(cap_.nchar) == FAIL {
		clearopbeep(cap_.oap)
	}
}

func nv_undo(cap_ *S_cmdarg_S) {
	if cap_.oap.op_type == OP_LOWER || VIsual_active != 0 {
		cap_.cmdchar = 'g'
		cap_.nchar = 'u'
		nv_operator(cap_)
	} else {
		nv_kundo(cap_)
	}
}

func nv_kundo(cap_ *S_cmdarg_S) {
	if checkclearopq(cap_.oap) != 0 {
		return
	}

	u_undo(int32(cap_.count1))
	curwin.w_set_curswant = true
}

func nv_replace(cap_ *S_cmdarg_S) {
	var had_ctrl_v int32
	var n int64

	if checkclearop(cap_.oap) != 0 {
		return
	}

	if cap_.nchar == Ctrl_V || cap_.nchar == Ctrl_Q {
		had_ctrl_v = Ctrl_V
		cap_.nchar = get_literal(FALSE)
		if cap_.nchar > DEL {
			had_ctrl_v = NUL
		}
	} else {
		had_ctrl_v = NUL
	}

	if cap_.nchar < 0 {
		clearopbeep(cap_.oap)
		return
	}

	if VIsual_active != 0 {
		if got_int != 0 {
			got_int = FALSE
		}
		if had_ctrl_v != 0 {
			if cap_.nchar == CAR {
				cap_.nchar = -1
			} else if cap_.nchar == NL {
				cap_.nchar = -2
			}
		}
		nv_operator(cap_)
		return
	}

	if virtual_active() != 0 {
		if u_save_cursor() == FAIL {
			return
		}
		if gchar_cursor() == NUL {
			coladvance_force(colnr_T(int64(getviscol()) + cap_.count1))
			curwin.w_cursor.col = colnr_T(int64(curwin.w_cursor.col) - cap_.count1)
		} else if gchar_cursor() == TAB {
			coladvance_force(getviscol())
		}
	}

	if usize(ml_get_cursor_len()) < usize(uint32(cap_.count1)) || int64(mb_charlen(ml_get_cursor())) < cap_.count1 {
		clearopbeep(cap_.oap)
		return
	}

	if had_ctrl_v != Ctrl_V && cap_.nchar == '\t' && (curbuf.b_p_et != 0 || p_sta != 0) {
		stuffnumReadbuff(cap_.count1)
		stuffcharReadbuff('R')
		stuffcharReadbuff('\t')
		stuffcharReadbuff(ESC)
		return
	}

	if u_save_cursor() == FAIL {
		return
	}

	if had_ctrl_v != Ctrl_V && (cap_.nchar == '\r' || cap_.nchar == '\n') {
		del_chars(cap_.count1, FALSE)
		stuffcharReadbuff('\r')
		stuffcharReadbuff(ESC)

		invoke_edit(cap_, TRUE, 'r', FALSE)
	} else {
		prep_redo(cap_.oap.regname, cap_.count1, NUL, 'r', NUL, had_ctrl_v, cap_.nchar)

		curbuf.b_op_start = curwin.w_cursor
		old_State := State

		if cap_.ncharC1 != 0 {
			AppendCharToRedobuff(cap_.ncharC1)
		}
		if cap_.ncharC2 != 0 {
			AppendCharToRedobuff(cap_.ncharC2)
		}

		for n = cap_.count1; n > 0; n-- {
			State = REPLACE_FLAG | MODE_INSERT
			if cap_.nchar == Ctrl_E || cap_.nchar == Ctrl_Y {
				var d linenr_T
				if cap_.nchar == Ctrl_Y {
					d = -1
				} else {
					d = 1
				}
				c := ins_copychar(curwin.w_cursor.lnum + d)
				if c != NUL {
					ins_char(c)
				} else {
					curwin.w_cursor.col++
				}
			} else {
				ins_char(cap_.nchar)
			}
			State = old_State
			if cap_.ncharC1 != 0 {
				ins_char(cap_.ncharC1)
			}
			if cap_.ncharC2 != 0 {
				ins_char(cap_.ncharC2)
			}
		}
		curwin.w_cursor.col--
		mb_adjust_cursor()
		curbuf.b_op_end = curwin.w_cursor
		curwin.w_set_curswant = true
		set_last_insert(cap_.nchar)
	}
}

func v_swap_corners(cmdchar int32) {
	var old_cursor pos_T
	var left colnr_T
	var right colnr_T

	if cmdchar == 'O' && VIsual_mode == Ctrl_V {
		old_cursor = curwin.w_cursor
		getvcols(curwin, &old_cursor, &VIsual, &left, &right, 0)
		curwin.w_cursor.lnum = VIsual.lnum
		coladvance(left)
		VIsual = curwin.w_cursor

		curwin.w_cursor.lnum = old_cursor.lnum
		curwin.w_curswant = right
		if old_cursor.lnum >= VIsual.lnum && p_sel.Get() == 'e' {
			curwin.w_curswant++
		}
		coladvance(curwin.w_curswant)
		if curwin.w_cursor.col == old_cursor.col && (virtual_active() == 0 || curwin.w_cursor.coladd == old_cursor.coladd) {
			curwin.w_cursor.lnum = VIsual.lnum
			if old_cursor.lnum <= VIsual.lnum && p_sel.Get() == 'e' {
				right++
			}
			coladvance(right)
			VIsual = curwin.w_cursor

			curwin.w_cursor.lnum = old_cursor.lnum
			coladvance(left)
			curwin.w_curswant = left
		}
	} else {
		old_cursor = curwin.w_cursor
		curwin.w_cursor = VIsual
		VIsual = old_cursor
		curwin.w_set_curswant = true
	}
}

func nv_Replace(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		cap_.cmdchar = 'c'
		cap_.nchar = NUL
		VIsual_mode_orig = VIsual_mode
		VIsual_mode = 'V'
		nv_operator(cap_)
		return
	}

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	if curbuf.b_p_ma == 0 {
		emsg(gettext_(e_cannot_make_changes_modifiable_is_off))
	} else {
		if virtual_active() != 0 {
			coladvance(getviscol())
		}
		var cmd int32
		if cap_.arg != 0 {
			cmd = 'V'
		} else {
			cmd = 'R'
		}
		invoke_edit(cap_, FALSE, cmd, FALSE)
	}
}

func nv_vreplace(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		cap_.cmdchar = 'r'
		cap_.nchar = cap_.extra_char
		nv_replace(cap_)
		return
	}

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	if curbuf.b_p_ma == 0 {
		emsg(gettext_(e_cannot_make_changes_modifiable_is_off))
	} else {
		if cap_.extra_char == Ctrl_V || cap_.extra_char == Ctrl_Q {
			cap_.extra_char = get_literal(FALSE)
		}
		if cap_.extra_char < ' ' {
			stuffcharReadbuff(Ctrl_V)
		}
		stuffcharReadbuff(cap_.extra_char)
		stuffcharReadbuff(ESC)
		if virtual_active() != 0 {
			coladvance(getviscol())
		}
		invoke_edit(cap_, TRUE, 'v', FALSE)
	}
}

func n_swapchar(cap_ *S_cmdarg_S) {
	var n int64
	var startpos pos_T
	var did_change int32 = 0

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	if ml_get(curwin.w_cursor.lnum).Get() == NUL && vim_strchr(p_ww, '~').Nil() {
		clearopbeep(cap_.oap)
		return
	}

	prep_redo_cmd(cap_)

	if u_save_cursor() == FAIL {
		return
	}

	startpos = curwin.w_cursor
	for n = cap_.count1; n > 0; n-- {
		did_change |= swapchar(cap_.oap.op_type, &curwin.w_cursor)
		inc_cursor()
		if gchar_cursor() == NUL {
			if !vim_strchr(p_ww, '~').Nil() && curwin.w_cursor.lnum < curbuf.b_ml.ml_line_count {
				curwin.w_cursor.lnum++
				curwin.w_cursor.col = 0
				if n > 1 {
					if u_savesub(curwin.w_cursor.lnum) == FAIL {
						break
					}
					u_clearline()
				}
			} else {
				break
			}
		}
	}

	check_cursor()
	curwin.w_set_curswant = true
	if did_change != 0 {
		changed_lines(startpos.lnum, startpos.col, curwin.w_cursor.lnum+1, 0)
		curbuf.b_op_start = startpos
		curbuf.b_op_end = curwin.w_cursor
		if curbuf.b_op_end.col > 0 {
			curbuf.b_op_end.col--
		}
	}
}

func nv_cursormark(cap_ *S_cmdarg_S, flag int32, pos Ptr[pos_T]) {
	if check_mark(pos) == FAIL {
		clearop(cap_.oap)
	} else {
		if cap_.cmdchar == '\'' || cap_.cmdchar == '`' || cap_.cmdchar == '[' || cap_.cmdchar == ']' {
			setpcmark()
		}
		curwin.w_cursor = pos.Get()
		if flag != 0 {
			beginline(BL_WHITE | BL_FIX)
		} else {
			check_cursor()
		}
	}
	if flag != 0 {
		cap_.oap.motion_type = MLINE
	} else {
		cap_.oap.motion_type = MCHAR
	}
	if cap_.cmdchar == '`' {
		cap_.oap.use_reg_one = TRUE
	}
	cap_.oap.inclusive = FALSE
	curwin.w_set_curswant = true
}

func v_visop(cap_ *S_cmdarg_S) {
	if musl_isupper(int32(byte(cap_.cmdchar))) != 0 {
		if VIsual_mode != Ctrl_V {
			VIsual_mode_orig = VIsual_mode
			VIsual_mode = 'V'
		} else if cap_.cmdchar == 'C' || cap_.cmdchar == 'D' {
			curwin.w_curswant = MAXCOL
		}
	}
	cap_.cmdchar = int32(vim_strchr(v_visop_trans, cap_.cmdchar).At(1))
	nv_operator(cap_)
}

func nv_subst(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		if cap_.cmdchar == 'S' {
			VIsual_mode_orig = VIsual_mode
			VIsual_mode = 'V'
		}
		cap_.cmdchar = 'c'
		nv_operator(cap_)
	} else {
		nv_optrans(cap_)
	}
}

func nv_abbrev(cap_ *S_cmdarg_S) {
	if cap_.cmdchar == -('k'+('D'<<8)) || cap_.cmdchar == -(KS_EXTRA+(KE_KDEL<<8)) {
		cap_.cmdchar = 'x'
	}

	if VIsual_active != 0 {
		v_visop(cap_)
	} else {
		nv_optrans(cap_)
	}
}

func nv_optrans(cap_ *S_cmdarg_S) {
	if checkclearopq(cap_.oap) == 0 {
		if cap_.cmdchar == 'D' && !vim_strchr(p_cpo, CPO_HASH).Nil() {
			cap_.oap.start = curwin.w_cursor
			cap_.oap.op_type = OP_DELETE
			cap_.count1 = 1
			nv_dollar(cap_)
			finish_op = TRUE
			ResetRedobuff()
			AppendCharToRedobuff('D')
		} else {
			if cap_.count0 != 0 {
				stuffnumReadbuff(cap_.count0)
			}
			stuffReadbuff(nv_optrans_ar[int32(vim_strchr(nv_optrans_str, cap_.cmdchar).Sub(nv_optrans_str))])
		}
	}
	cap_.opcount = 0
}

func init() {
	copy(v_visop_trans.Slice(17), "YyDdCcxdXdAAIIrr\x00")
	nv_optrans_ar = [8]Ptr[byte]{S("dl"), S("dh"),
		S("d$"), S("c$"),
		S("cl"), S("cc"),
		S("yy"), S(":s\r")}
	nv_optrans_str = S("xXDCsSY&")
}

func nv_gomark(cap_ *S_cmdarg_S) {
	var pos Ptr[pos_T]
	var c int32

	if cap_.cmdchar == 'g' {
		c = cap_.extra_char
	} else {
		c = cap_.nchar
	}
	pos = getmark(c, B2i(cap_.oap.op_type == OP_NOP))
	nv_cursormark(cap_, cap_.arg, pos)

	if virtual_active() == 0 {
		curwin.w_cursor.coladd = 0
	}
	check_cursor_col()
}

func nv_pcmark(cap_ *S_cmdarg_S) {
	var pos Ptr[pos_T]

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	pos = movechangelist(int32(cap_.count1))
	if !pos.Nil() {
		nv_cursormark(cap_, FALSE, pos)
	} else {
		if curbuf.b_changelistlen == 0 {
			emsg(gettext_(e_changelist_is_empty))
		} else if cap_.count1 < 0 {
			emsg(gettext_(e_at_start_of_changelist))
		} else {
			emsg(gettext_(e_at_end_of_changelist))
		}
	}
}

func nv_regname(cap_ *S_cmdarg_S) {
	if checkclearop(cap_.oap) != 0 {
		return
	}
	if cap_.nchar != NUL && valid_yank_reg(cap_.nchar, FALSE) != 0 {
		cap_.oap.regname = cap_.nchar
		cap_.opcount = cap_.count0
	} else {
		clearopbeep(cap_.oap)
	}
}

func nv_visual(cap_ *S_cmdarg_S) {
	if cap_.cmdchar == Ctrl_Q {
		cap_.cmdchar = Ctrl_V
	}

	if cap_.oap.op_type != OP_NOP {
		cap_.oap.motion_force = cap_.cmdchar
		motion_force = cap_.oap.motion_force
		finish_op = FALSE
		return
	}

	VIsual_select = cap_.arg
	if VIsual_active != 0 {
		if VIsual_mode == cap_.cmdchar {
			end_visual_mode()
		} else {
			VIsual_mode = cap_.cmdchar
			showmode()
		}
		redraw_curbuf_later(UPD_INVERTED)
	} else {
		check_visual_highlight()
		if cap_.count0 > 0 && resel_VIsual_mode != NUL {
			VIsual = curwin.w_cursor

			VIsual_active = TRUE
			VIsual_reselect = TRUE
			if cap_.arg == 0 {
				may_start_select('c')
			}
			if p_smd != 0 && msg_silent == 0 {
				redraw_cmdline = TRUE
			}
			if resel_VIsual_mode != 'v' || resel_VIsual_line_count > 1 {
				curwin.w_cursor.lnum += resel_VIsual_line_count*cap_.count0 - 1
				check_cursor()
			}
			VIsual_mode = resel_VIsual_mode
			if VIsual_mode == 'v' {
				if resel_VIsual_line_count <= 1 {
					update_curswant_force()
					curwin.w_curswant = colnr_T(int64(curwin.w_curswant) + int64(resel_VIsual_vcol)*cap_.count0)
					if p_sel.Get() != 'e' {
						curwin.w_curswant--
					}
				} else {
					curwin.w_curswant = resel_VIsual_vcol
				}
				coladvance(curwin.w_curswant)
			}
			if resel_VIsual_vcol == MAXCOL {
				curwin.w_curswant = MAXCOL
				coladvance(colnr_T(MAXCOL))
			} else if VIsual_mode == Ctrl_V {
				tmp_cursor := curwin.w_cursor
				curwin.w_cursor = VIsual
				update_curswant_force()
				curwin.w_curswant = colnr_T(int64(curwin.w_curswant) + (int64(resel_VIsual_vcol)*cap_.count0 - 1))
				curwin.w_cursor = tmp_cursor
				if p_sel.Get() == 'e' {
					curwin.w_curswant++
				}
				coladvance(curwin.w_curswant)
			} else {
				curwin.w_set_curswant = true
			}
			redraw_curbuf_later(UPD_INVERTED)
		} else {
			if cap_.arg == 0 {
				may_start_select('c')
			}
			n_start_visual_mode(cap_.cmdchar)
			if VIsual_mode != 'V' && p_sel.Get() == 'e' {
				cap_.count1++
			} else {
				VIsual_select_exclu_adj = FALSE
			}
			if cap_.count0 > 0 {
				cap_.count1--
				if cap_.count1 > 0 {
					if VIsual_mode == 'v' || VIsual_mode == Ctrl_V {
						nv_right(cap_)
					} else if VIsual_mode == 'V' {
						nv_down(cap_)
					}
				}
			}
		}
	}
}

func start_selection() {
	may_start_select('k')
	n_start_visual_mode('v')
}

func may_start_select(c int32) {
	VIsual_select = B2i((c == 'o' || (stuff_empty() != 0 && typebuf_typed() != 0)) && !vim_strchr(p_slm, c).Nil())
}

func n_start_visual_mode(c int32) {
	VIsual_mode = c
	VIsual_active = TRUE
	VIsual_reselect = TRUE

	if c == Ctrl_V && (get_ve_flags()&VE_BLOCK) != 0 && gchar_cursor() == TAB {
		validate_virtcol()
		coladvance(curwin.w_virtcol)
	}
	VIsual = curwin.w_cursor

	if p_smd != 0 && msg_silent == 0 {
		redraw_cmdline = TRUE
	}

	if curwin.w_redr_type < UPD_INVERTED {
		curwin.w_old_cursor_lnum = curwin.w_cursor.lnum
		curwin.w_old_visual_lnum = curwin.w_cursor.lnum
	}
}

func nv_suspend(cap_ *S_cmdarg_S) {
	clearop(cap_.oap)
	if VIsual_active != 0 {
		end_visual_mode()
	}
	do_cmdline_cmd(S("stop"))
}

func nv_gv_cmd(cap_ *S_cmdarg_S) {
	var tpos pos_T
	var i int32

	if curbuf.b_visual.vi_start.lnum == 0 || curbuf.b_visual.vi_start.lnum > curbuf.b_ml.ml_line_count || curbuf.b_visual.vi_end.lnum == 0 {
		beep_flush()
		return
	}

	if VIsual_active != 0 {
		i = VIsual_mode
		VIsual_mode = curbuf.b_visual.vi_mode
		curbuf.b_visual.vi_mode = i
		i = curwin.w_curswant
		curwin.w_curswant = curbuf.b_visual.vi_curswant
		curbuf.b_visual.vi_curswant = i

		tpos = curbuf.b_visual.vi_end
		curbuf.b_visual.vi_end = curwin.w_cursor
		curwin.w_cursor = curbuf.b_visual.vi_start
		curbuf.b_visual.vi_start = VIsual
	} else {
		VIsual_mode = curbuf.b_visual.vi_mode
		curwin.w_curswant = curbuf.b_visual.vi_curswant
		tpos = curbuf.b_visual.vi_end
		curwin.w_cursor = curbuf.b_visual.vi_start
	}

	VIsual_active = TRUE
	VIsual_reselect = TRUE

	check_cursor()
	VIsual = curwin.w_cursor
	curwin.w_cursor = tpos
	check_cursor()
	update_topline()

	if cap_.arg != 0 {
		VIsual_select = TRUE
		VIsual_select_reg = 0
	} else {
		may_start_select('c')
	}
	redraw_curbuf_later(UPD_INVERTED)
	showmode()
}

func nv_g_home_m_cmd(cap_ *S_cmdarg_S) {
	var i int32
	var flag int32 = FALSE

	if cap_.nchar == '^' {
		flag = TRUE
	}

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	if curwin.w_onebuf_opt.wo_wrap != 0 && curwin.w_width != 0 {
		width1 := curwin.w_width - curwin_col_off()
		width2 := width1 + curwin_col_off2()
		var virtcol int32

		validate_virtcol()
		virtcol = curwin.w_virtcol
		i = 0
		if virtcol >= colnr_T(width1) && width2 > 0 {
			i = (virtcol-width1)/width2*width2 + width1
		}

		if curwin.w_skipcol > 0 && curwin.w_cursor.lnum == curwin.w_topline {
			overlap := sms_marker_overlap(curwin, curwin.w_width-width2)
			if overlap > 0 && i == curwin.w_skipcol {
				i += overlap
			}
		}
	} else {
		i = curwin.w_leftcol
	}
	if cap_.nchar == 'm' {
		var off2 int32
		if curwin.w_onebuf_opt.wo_wrap != 0 && i > 0 {
			off2 = curwin_col_off2()
		} else {
			off2 = 0
		}
		i += (curwin.w_width - curwin_col_off() + off2) / 2
	}
	coladvance(colnr_T(i))
	if flag != 0 {
		for {
			i = gchar_cursor()
			if !((i == ' ' || i == '\t') && oneright() == OK) {
				break
			}
		}
		curwin.w_valid &^= VALID_WCOL
	}
	curwin.w_set_curswant = true
	adjust_skipcol()
}

func nv_g_underscore_cmd(cap_ *S_cmdarg_S) {
	var ptr Ptr[byte]

	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = TRUE
	curwin.w_curswant = MAXCOL
	if cursor_down(int64(cap_.count1-1), B2i(cap_.oap.op_type == OP_NOP)) == FAIL {
		clearopbeep(cap_.oap)
		return
	}

	ptr = ml_get_curline()

	if curwin.w_cursor.col > 0 && ptr.At(int(curwin.w_cursor.col)) == NUL {
		curwin.w_cursor.col--
	}

	for curwin.w_cursor.col > 0 && (ptr.At(int(curwin.w_cursor.col)) == ' ' || ptr.At(int(curwin.w_cursor.col)) == '\t') {
		curwin.w_cursor.col--
	}
	curwin.w_set_curswant = true
	adjust_for_sel(cap_)
}

func nv_g_dollar_cmd(cap_ *S_cmdarg_S) {
	oap := cap_.oap
	var i int32
	col_off := curwin_col_off()
	var flag int32 = FALSE

	if cap_.nchar == -('@'+('7'<<8)) || cap_.nchar == -('K'+('4'<<8)) {
		flag = TRUE
	}

	oap.motion_type = MCHAR
	oap.inclusive = TRUE
	if curwin.w_onebuf_opt.wo_wrap != 0 && curwin.w_width != 0 {
		curwin.w_curswant = MAXCOL
		if cap_.count1 == 1 {
			width1 := curwin.w_width - col_off
			width2 := width1 + curwin_col_off2()
			var virtcol int32

			validate_virtcol()
			virtcol = curwin.w_virtcol
			i = width1 - 1
			if virtcol >= colnr_T(width1) {
				i += ((virtcol-width1)/width2 + 1) * width2
			}
			coladvance(colnr_T(i))

			update_curswant_force()
			if curwin.w_cursor.col > 0 && curwin.w_onebuf_opt.wo_wrap != 0 {
				if curwin.w_virtcol > colnr_T(i) {
					curwin.w_cursor.col--
				}
			}
		} else if nv_screengo(oap, FORWARD, cap_.count1-1) == FAIL {
			clearopbeep(oap)
		}
	} else {
		if cap_.count1 > 1 {
			cursor_down(cap_.count1-1, FALSE)
		}

		i = curwin.w_leftcol + curwin.w_width - col_off - 1
		coladvance(colnr_T(i))

		if curwin.w_cursor.col > 0 && utf_ptr2cells(ml_get_cursor()) > 1 {
			var vcol colnr_T

			getvvcol(curwin, &curwin.w_cursor, nil, nil, &vcol, 0)
			if vcol >= curwin.w_leftcol+curwin.w_width-col_off {
				curwin.w_cursor.col--
			}
		}

		update_curswant_force()
	}
	if flag != 0 {
		for {
			i = gchar_cursor()
			if !((i == ' ' || i == '\t' || i == NUL) && oneleft() == OK) {
				break
			}
		}
		curwin.w_valid &^= VALID_WCOL
	}
}

func nv_gi_cmd(cap_ *S_cmdarg_S) {
	var i int32

	if curbuf.b_last_insert.lnum != 0 {
		curwin.w_cursor = curbuf.b_last_insert
		check_cursor_lnum()
		i = int32(ml_get_curline_len())
		if curwin.w_cursor.col > colnr_T(i) {
			if virtual_active() != 0 {
				curwin.w_cursor.coladd += curwin.w_cursor.col - i
			}
			curwin.w_cursor.col = i
		}
	}
	cap_.cmdchar = 'i'
	nv_edit(cap_)
}

func nv_g_cmd(cap_ *S_cmdarg_S) {
	oap := cap_.oap
	var i int32

	switch cap_.nchar {
	case Ctrl_A, Ctrl_X:
		if VIsual_active != 0 {
			cap_.arg = TRUE
			cap_.cmdchar = cap_.nchar
			cap_.nchar = NUL
			nv_addsub(cap_)
		} else {
			clearopbeep(oap)
		}

	case 'R':
		cap_.arg = TRUE
		nv_Replace(cap_)

	case 'r':
		nv_vreplace(cap_)

	case '&':
		do_cmdline_cmd(S("%s//~/&"))

	case 'v':
		nv_gv_cmd(cap_)

	case 'V':
		VIsual_reselect = FALSE

	case -('k' + ('b' << 8)):
		cap_.nchar = Ctrl_H
		fallthrough
	case 'h', 'H', Ctrl_H:
		cap_.cmdchar = cap_.nchar + ('v' - 'h')
		cap_.arg = TRUE
		nv_visual(cap_)

	case 'N', 'n':
		if current_search(cap_.count1, B2i(cap_.nchar == 'n')) == 0 {
			clearopbeep(oap)
		}

	case 'j', -('k' + ('d' << 8)):
		if curwin.w_onebuf_opt.wo_wrap == 0 {
			oap.motion_type = MLINE
			i = cursor_down(cap_.count1, B2i(oap.op_type == OP_NOP))
		} else {
			i = nv_screengo(oap, FORWARD, cap_.count1)
		}
		if i == FAIL {
			clearopbeep(oap)
		}

	case 'k', -('k' + ('u' << 8)):
		if curwin.w_onebuf_opt.wo_wrap == 0 {
			oap.motion_type = MLINE
			i = cursor_up(cap_.count1, B2i(oap.op_type == OP_NOP))
		} else {
			i = nv_screengo(oap, -1, cap_.count1)
		}
		if i == FAIL {
			clearopbeep(oap)
		}

	case 'J':
		nv_join(cap_)

	case '^', '0', 'm', -('k' + ('h' << 8)), -('K' + ('1' << 8)):
		nv_g_home_m_cmd(cap_)

	case 'M':
		{
			oap.motion_type = MCHAR
			oap.inclusive = FALSE
			i = linetabsize_no_outer(curwin, curwin.w_cursor.lnum)
			if cap_.count0 > 0 && cap_.count0 <= 100 {
				coladvance(colnr_T(int64(i) * cap_.count0 / 100))
			} else {
				coladvance(colnr_T(i / 2))
			}
			curwin.w_set_curswant = true
		}

	case '_':
		nv_g_underscore_cmd(cap_)

	case '$', -('@' + ('7' << 8)), -('K' + ('4' << 8)):
		nv_g_dollar_cmd(cap_)

	case '*', '#', POUND:
		nv_ident(cap_)

	case 'e', 'E':
		oap.motion_type = MCHAR
		curwin.w_set_curswant = true
		oap.inclusive = TRUE
		if bckend_word(cap_.count1, B2i(cap_.nchar == 'E'), FALSE) == FAIL {
			clearopbeep(oap)
		}

	case Ctrl_G:
		cursor_pos_info()

	case 'i':
		nv_gi_cmd(cap_)

	case 'I':
		beginline(0)
		if checkclearopq(oap) == 0 {
			invoke_edit(cap_, FALSE, 'g', FALSE)
		}

	case '\'':
		cap_.arg = TRUE
		fallthrough
	case '`':
		nv_gomark(cap_)

	case 's':
		do_sleep(cap_.count1*1000, FALSE)

	case 'a':
		do_ascii(nil)

	case '8':
		if cap_.count0 == 8 {
			utf_find_illegal()
		} else {
			show_utf8()
		}

	case '<':
		show_sb_text()

	case 'g':
		cap_.arg = FALSE
		nv_goto(cap_)

	case '~', 'u', 'U':
		nv_operator(cap_)

	case -(KS_EXTRA + (KE_MIDDLEMOUSE << 8)),
		-(KS_EXTRA + (KE_MIDDLEDRAG << 8)),
		-(KS_EXTRA + (KE_MIDDLERELEASE << 8)),
		-(KS_EXTRA + (KE_LEFTMOUSE << 8)),
		-(KS_EXTRA + (KE_LEFTDRAG << 8)),
		-(KS_EXTRA + (KE_LEFTRELEASE << 8)),
		-(KS_EXTRA + (KE_MOUSEMOVE << 8)),
		-(KS_EXTRA + (KE_RIGHTMOUSE << 8)),
		-(KS_EXTRA + (KE_RIGHTDRAG << 8)),
		-(KS_EXTRA + (KE_RIGHTRELEASE << 8)),
		-(KS_EXTRA + (KE_X1MOUSE << 8)),
		-(KS_EXTRA + (KE_X1DRAG << 8)),
		-(KS_EXTRA + (KE_X1RELEASE << 8)),
		-(KS_EXTRA + (KE_X2MOUSE << 8)),
		-(KS_EXTRA + (KE_X2DRAG << 8)),
		-(KS_EXTRA + (KE_X2RELEASE << 8)):
		mod_mask = MOD_MASK_CTRL

	case -(KS_EXTRA + (KE_IGNORE << 8)):

	case 'p', 'P':
		nv_put(cap_)

	case ',':
		nv_pcmark(cap_)

	case ';':
		cap_.count1 = -cap_.count1
		nv_pcmark(cap_)

	case 't':
		if checkclearop(oap) == 0 && cap_.count0 > 1 {
			beep_flush()
		}
	case 'T':
		checkclearop(oap)

	case TAB:
		if checkclearop(oap) == 0 {
			clearopbeep(oap)
		}

	case '+', '-':
		if checkclearopq(oap) == 0 {
			var step int64
			if cap_.nchar == '-' {
				step = -cap_.count1
			} else {
				step = cap_.count1
			}
			undo_time(step, FALSE, FALSE, FALSE)
		}

	default:
		clearopbeep(oap)
	}
}

func n_opencmd(cap_ *S_cmdarg_S) {
	if checkclearopq(cap_.oap) != 0 {
		return
	}

	curbuf.b_last_changedtick_i = curbuf.b_changedtick
	var top, bot int64
	if cap_.cmdchar == 'O' {
		top = 1
	} else {
		top = 0
	}
	if cap_.cmdchar == 'o' {
		bot = 1
	} else {
		bot = 0
	}
	var dir int32
	if cap_.cmdchar == 'O' {
		dir = -1
	} else {
		dir = FORWARD
	}
	if u_save(linenr_T(curwin.w_cursor.lnum-top), linenr_T(curwin.w_cursor.lnum+bot)) == OK && open_line(dir, 0, 0, nil) == OK {
		if !vim_strchr(p_cpo, CPO_HASH).Nil() {
			cap_.count1 = 1
		}
		invoke_edit(cap_, FALSE, cap_.cmdchar, TRUE)
	}
}

func nv_dot(cap_ *S_cmdarg_S) {
	if checkclearopq(cap_.oap) != 0 {
		return
	}

	if start_redo(cap_.count0, B2i(restart_edit != 0 && arrow_used == 0)) == FAIL {
		clearopbeep(cap_.oap)
	}
}

func nv_redo_or_register(cap_ *S_cmdarg_S) {
	if VIsual_select != 0 && VIsual_active != 0 {
		var reg int32
		no_mapping++
		allow_keys++
		reg = plain_vgetc()
		no_mapping--
		allow_keys--

		if reg == '"' {
			reg = 0
		}

		if valid_yank_reg(reg, TRUE) != 0 {
			VIsual_select_reg = reg
		} else {
			VIsual_select_reg = 0
		}
		return
	}

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	u_redo(int32(cap_.count1))
	curwin.w_set_curswant = true
}

func nv_Undo(cap_ *S_cmdarg_S) {
	if cap_.oap.op_type == OP_UPPER || VIsual_active != 0 {
		cap_.cmdchar = 'g'
		cap_.nchar = 'U'
		nv_operator(cap_)
		return
	}

	if checkclearopq(cap_.oap) != 0 {
		return
	}

	u_undoline()
	curwin.w_set_curswant = true
}

func nv_tilde(cap_ *S_cmdarg_S) {
	if p_to == 0 && VIsual_active == 0 && cap_.oap.op_type != OP_TILDE {
		n_swapchar(cap_)
	} else {
		nv_operator(cap_)
	}
}

func nv_operator(cap_ *S_cmdarg_S) {
	var op_type int32

	op_type = get_op_type(cap_.cmdchar, cap_.nchar)

	if op_type == cap_.oap.op_type {
		nv_lineop(cap_)
	} else if checkclearop(cap_.oap) == 0 {
		cap_.oap.start = curwin.w_cursor
		cap_.oap.op_type = op_type
	}
}

func nv_lineop(cap_ *S_cmdarg_S) {
	cap_.oap.motion_type = MLINE
	if cursor_down(cap_.count1-1, B2i(cap_.oap.op_type == OP_NOP)) == FAIL {
		clearopbeep(cap_.oap)
	} else if (cap_.oap.op_type == OP_DELETE && cap_.oap.motion_force != 'v' && cap_.oap.motion_force != Ctrl_V) || cap_.oap.op_type == OP_LSHIFT || cap_.oap.op_type == OP_RSHIFT {
		beginline(BL_SOL | BL_FIX)
	} else if cap_.oap.op_type != OP_YANK {
		beginline(BL_WHITE | BL_FIX)
	}
}

func nv_home(cap_ *S_cmdarg_S) {
	if mod_mask&MOD_MASK_CTRL != 0 {
		nv_goto(cap_)
	} else {
		cap_.count0 = 1
		nv_pipe(cap_)
	}
	ins_at_eol = FALSE
}

func nv_pipe(cap_ *S_cmdarg_S) {
	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	curwin.w_cursor.col = 0
	curwin.w_cursor.coladd = 0
	if cap_.count0 > 0 {
		coladvance(colnr_T(cap_.count0 - 1))
		curwin.w_curswant = colnr_T(cap_.count0 - 1)
	} else {
		curwin.w_curswant = 0
	}
	curwin.w_set_curswant = false
	adjust_skipcol()
}

func nv_bck_word(cap_ *S_cmdarg_S) {
	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	curwin.w_set_curswant = true
	if bck_word(cap_.count1, cap_.arg, FALSE) == FAIL {
		clearopbeep(cap_.oap)
	}
}

func nv_wordcmd(cap_ *S_cmdarg_S) {
	var n int32
	var word_end int32
	var flag int32 = FALSE
	startpos := curwin.w_cursor

	if cap_.cmdchar == 'e' || cap_.cmdchar == 'E' {
		word_end = TRUE
	} else {
		word_end = FALSE
	}
	cap_.oap.inclusive = word_end

	if word_end == 0 && cap_.oap.op_type == OP_CHANGE {
		n = gchar_cursor()
		if n != NUL {
			if n == ' ' || n == '\t' {
				if cap_.count1 == 1 && !vim_strchr(p_cpo, CPO_CW).Nil() {
					cap_.oap.inclusive = TRUE
					cap_.oap.motion_type = MCHAR
					return
				}
			} else {
				if !vim_strchr(p_cpo, CPO_WORD).Nil() {
					cap_.oap.inclusive = TRUE
					word_end = TRUE
				}
				flag = TRUE
			}
		}
	}

	cap_.oap.motion_type = MCHAR
	curwin.w_set_curswant = true
	if word_end != 0 {
		n = end_word(cap_.count1, cap_.arg, flag, FALSE)
	} else {
		n = fwd_word(cap_.count1, cap_.arg, B2i(cap_.oap.op_type != OP_NOP))
	}

	var lt bool
	if startpos.lnum != curwin.w_cursor.lnum {
		lt = startpos.lnum < curwin.w_cursor.lnum
	} else if startpos.col != curwin.w_cursor.col {
		lt = startpos.col < curwin.w_cursor.col
	} else {
		lt = startpos.coladd < curwin.w_cursor.coladd
	}
	if lt {
		adjust_cursor(cap_.oap)
	}

	if n == FAIL && cap_.oap.op_type == OP_NOP {
		clearopbeep(cap_.oap)
	} else {
		adjust_for_sel(cap_)
	}
}

func adjust_cursor(oap *S_oparg_S) {
	if curwin.w_cursor.col > 0 && gchar_cursor() == NUL && (VIsual_active == 0 || p_sel.Get() == 'o') && virtual_active() == 0 && (get_ve_flags()&VE_ONEMORE) == 0 {
		curwin.w_cursor.col--
		mb_adjust_cursor()
		oap.inclusive = TRUE
	}
}

func nv_beginline(cap_ *S_cmdarg_S) {
	cap_.oap.motion_type = MCHAR
	cap_.oap.inclusive = FALSE
	beginline(cap_.arg)
	ins_at_eol = FALSE
}

func adjust_for_sel(cap_ *S_cmdarg_S) {
	var lt bool
	if VIsual.lnum != curwin.w_cursor.lnum {
		lt = VIsual.lnum < curwin.w_cursor.lnum
	} else if VIsual.col != curwin.w_cursor.col {
		lt = VIsual.col < curwin.w_cursor.col
	} else {
		lt = VIsual.coladd < curwin.w_cursor.coladd
	}
	if VIsual_active != 0 && cap_.oap.inclusive != 0 && p_sel.Get() == 'e' && gchar_cursor() != NUL && lt {
		inc_cursor()
		cap_.oap.inclusive = FALSE
		VIsual_select_exclu_adj = TRUE
	}
}

func unadjust_for_sel() int32 {
	if p_sel.Get() == 'e' && !(VIsual.lnum == curwin.w_cursor.lnum && VIsual.col == curwin.w_cursor.col && VIsual.coladd == curwin.w_cursor.coladd) {
		var lt bool
		if VIsual.lnum != curwin.w_cursor.lnum {
			lt = VIsual.lnum < curwin.w_cursor.lnum
		} else if VIsual.col != curwin.w_cursor.col {
			lt = VIsual.col < curwin.w_cursor.col
		} else {
			lt = VIsual.coladd < curwin.w_cursor.coladd
		}
		var pp *pos_T
		if lt {
			pp = &curwin.w_cursor
		} else {
			pp = &VIsual
		}
		return unadjust_for_sel_inner(pp)
	}
	return FALSE
}

func unadjust_for_sel_inner(pp *pos_T) int32 {
	var cs colnr_T
	var ce colnr_T
	VIsual_select_exclu_adj = FALSE

	if pp.coladd > 0 {
		pp.coladd--
	} else if pp.col > 0 {
		pp.col--
		mb_adjustpos(curbuf, pp)
		if virtual_active() != 0 {
			getvcol(curwin, pp, &cs, nil, &ce, 0)
			pp.coladd = ce - cs
		}
	} else if pp.lnum > 1 {
		pp.lnum--
		pp.col = ml_get_len(pp.lnum)
		return TRUE
	}

	return FALSE
}

func nv_select(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		VIsual_select = TRUE
		VIsual_select_reg = 0
	} else if VIsual_reselect != 0 {
		cap_.nchar = 'v'
		cap_.arg = TRUE
		nv_g_cmd(cap_)
	}
}

func nv_goto(cap_ *S_cmdarg_S) {
	var lnum linenr_T

	if cap_.arg != 0 {
		lnum = curbuf.b_ml.ml_line_count
	} else {
		lnum = 1
	}
	cap_.oap.motion_type = MLINE
	setpcmark()

	if cap_.count0 != 0 {
		lnum = cap_.count0
	}
	if lnum < 1 {
		lnum = 1
	} else if lnum > curbuf.b_ml.ml_line_count {
		lnum = curbuf.b_ml.ml_line_count
	}
	curwin.w_cursor.lnum = lnum
	beginline(BL_SOL | BL_FIX)
}

func nv_normal(cap_ *S_cmdarg_S) {
	if cap_.nchar == Ctrl_N || cap_.nchar == Ctrl_G {
		clearop(cap_.oap)
		if restart_edit != 0 && mode_displayed != 0 {
			clear_cmdline = TRUE
		}
		restart_edit = 0
		if VIsual_active != 0 {
			end_visual_mode()
			redraw_curbuf_later(UPD_INVERTED)
		}
		if cap_.nchar == Ctrl_G && p_im != 0 {
			restart_edit = 'a'
		}
	} else {
		clearopbeep(cap_.oap)
	}
}

func nv_esc(cap_ *S_cmdarg_S) {
	var no_reason int32

	no_reason = B2i(cap_.oap.op_type == OP_NOP && cap_.opcount == 0 && cap_.count0 == 0 && cap_.oap.regname == 0 && p_im == 0)

	if cap_.arg != 0 {
		if restart_edit == 0 && VIsual_active == 0 && no_reason != 0 {
			if anyBufIsChanged() != 0 {
				ms := gettext_(S("Type  :qa!  and press <Enter> to abandon all changes and exit Vim"))

				msg(ms)
			} else {
				msg(gettext_(S("Type  :qa  and press <Enter> to exit Vim")))
			}
		}

		if restart_edit != 0 {
			redraw_mode = TRUE
		}

		if p_im == 0 {
			restart_edit = 0
		}
	}

	if VIsual_active != 0 {
		end_visual_mode()
		check_cursor_col()
		curwin.w_set_curswant = true
		redraw_curbuf_later(UPD_INVERTED)
	} else if no_reason != 0 {
		vim_beep(BO_ESC)
	}
	clearop(cap_.oap)

	if restart_edit == 0 && goto_im() != 0 && ex_normal_busy == 0 {
		restart_edit = 'a'
	}
}

func set_cursor_for_append_to_line() {
	curwin.w_set_curswant = true
	if get_ve_flags() == VE_ALL {
		save_State := State

		State = MODE_INSERT
		coladvance(colnr_T(MAXCOL))
		State = save_State
	} else {
		curwin.w_cursor.col += colnr_T(musl_strlen(ml_get_cursor()))
	}
}

func nv_edit(cap_ *S_cmdarg_S) {
	if cap_.cmdchar == -('k'+('I'<<8)) || cap_.cmdchar == -(KS_EXTRA+(KE_KINS<<8)) {
		cap_.cmdchar = 'i'
	}

	if VIsual_active != 0 && (cap_.cmdchar == 'A' || cap_.cmdchar == 'I') {
		v_visop(cap_)
	} else if (cap_.cmdchar == 'a' || cap_.cmdchar == 'i') && (cap_.oap.op_type != OP_NOP || VIsual_active != 0) {
		nv_object(cap_)
	} else if curbuf.b_p_ma == 0 && p_im == 0 {
		emsg(gettext_(e_cannot_make_changes_modifiable_is_off))
		clearop(cap_.oap)
		if cap_.cmdchar == -('P' + ('S' << 8)) {
			bracketed_paste(PASTE_INSERT, TRUE, nil)
		}
	} else if cap_.cmdchar == -('P'+('S'<<8)) && VIsual_active != 0 {
		old_pos := curwin.w_cursor
		old_visual := VIsual
		old_visual_mode := VIsual_mode

		if VIsual_mode == 'V' || curwin.w_cursor.lnum != VIsual.lnum {
			shift_delete_registers()
			cap_.oap.regname = '1'
		} else {
			cap_.oap.regname = '-'
		}
		cap_.cmdchar = 'd'
		cap_.nchar = NUL
		nv_operator(cap_)
		do_pending_operator(cap_, 0, FALSE)
		cap_.cmdchar = -('P' + ('S' << 8))

		if ml_get_cursor().Get() != NUL {
			if old_visual_mode == 'V' {
				if curwin.w_cursor.lnum < old_pos.lnum && curwin.w_cursor.lnum < old_visual.lnum {
					if u_save_cursor() == OK {
						ml_append(curwin.w_cursor.lnum, S(""), 0)
						l := curwin.w_cursor.lnum
						curwin.w_cursor.lnum++
						appended_lines(l, 1)
					}
				}
			} else if curwin.w_cursor.col < old_pos.col && curwin.w_cursor.col < old_visual.col {
				inc_cursor()
			}
		}

		invoke_edit(cap_, FALSE, cap_.cmdchar, FALSE)
	} else if checkclearopq(cap_.oap) == 0 {
		switch cap_.cmdchar {
		case 'A':
			set_cursor_for_append_to_line()

		case 'I':
			if vim_strchr(p_cpo, CPO_INSEND).Nil() {
				beginline(BL_WHITE)
			} else {
				beginline(BL_WHITE | BL_FIX)
			}

		case -('P' + ('S' << 8)):
			if curwin.w_cursor.col == 0 {
				break
			}

			fallthrough
		case 'a':
			if virtual_active() != 0 && (curwin.w_cursor.coladd > 0 || ml_get_cursor().Get() == NUL || ml_get_cursor().Get() == TAB) {
				curwin.w_cursor.coladd++
			} else if ml_get_cursor().Get() != NUL {
				inc_cursor()
			}
		}

		if curwin.w_cursor.coladd != 0 && cap_.cmdchar != 'A' {
			save_State := State

			State = MODE_INSERT
			coladvance(getviscol())
			State = save_State
		}

		invoke_edit(cap_, FALSE, cap_.cmdchar, FALSE)
	} else if cap_.cmdchar == -('P' + ('S' << 8)) {
		bracketed_paste(PASTE_INSERT, TRUE, nil)
	}
}

func invoke_edit(cap_ *S_cmdarg_S, repl int32, cmd int32, startln int32) {
	var restart_edit_save int32 = 0

	if repl != 0 || stuff_empty() == 0 {
		restart_edit_save = restart_edit
	} else {
		restart_edit_save = 0
	}

	restart_edit = 0

	if cap_.cmdchar != 'O' && cap_.cmdchar != 'o' {
		curbuf.b_last_changedtick_i = curbuf.b_changedtick
	}
	if edit(cmd, startln, cap_.count1) != 0 {
		cap_.retval |= CA_COMMAND_BUSY
	}

	if restart_edit == 0 {
		restart_edit = restart_edit_save
	}
}

func nv_object(cap_ *S_cmdarg_S) {
	var flag int32
	var include int32
	var mps_save Ptr[byte]

	if cap_.cmdchar == 'i' {
		include = FALSE
	} else {
		include = TRUE
	}

	mps_save = curbuf.b_p_mps
	curbuf.b_p_mps = S("(:),{:},[:],<:>")

	switch cap_.nchar {
	case 'w':
		flag = current_word(cap_.oap, cap_.count1, include, FALSE)
	case 'W':
		flag = current_word(cap_.oap, cap_.count1, include, TRUE)
	case 'b', '(', ')':
		flag = current_block(cap_.oap, cap_.count1, include, '(', ')')
	case 'B', '{', '}':
		flag = current_block(cap_.oap, cap_.count1, include, '{', '}')
	case '[', ']':
		flag = current_block(cap_.oap, cap_.count1, include, '[', ']')
	case '<', '>':
		flag = current_block(cap_.oap, cap_.count1, include, '<', '>')
	case '"', '\'', '`':
		flag = current_quote(cap_.oap, cap_.count1, include, cap_.nchar)
	default:
		flag = FAIL
	}

	curbuf.b_p_mps = mps_save
	if flag == FAIL {
		clearopbeep(cap_.oap)
	}
	adjust_cursor_col()
	curwin.w_set_curswant = true
}

func nv_record(cap_ *S_cmdarg_S) {
	if checkclearop(cap_.oap) != 0 {
		return
	}

	if reg_executing == 0 && do_record(cap_.nchar) == FAIL {
		clearopbeep(cap_.oap)
	}
}

func nv_at(cap_ *S_cmdarg_S) {
	if checkclearop(cap_.oap) != 0 {
		return
	}
	for {
		c := cap_.count1
		cap_.count1--
		if !(c != 0 && got_int == 0) {
			break
		}
		if do_execreg(cap_.nchar, FALSE, FALSE, FALSE) == FAIL {
			clearopbeep(cap_.oap)
			break
		}
		line_breakcheck()
	}
}

func nv_halfpage(cap_ *S_cmdarg_S) {
	var dir int32
	if cap_.cmdchar == Ctrl_D {
		dir = FORWARD
	} else {
		dir = -1
	}
	if checkclearop(cap_.oap) == 0 {
		pagescroll(dir, cap_.count0, TRUE)
	}
}

func nv_join(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		nv_operator(cap_)
		return
	}

	if checkclearop(cap_.oap) != 0 {
		return
	}

	if cap_.count0 <= 1 {
		cap_.count0 = 2
	}
	if curwin.w_cursor.lnum+cap_.count0-1 > curbuf.b_ml.ml_line_count {
		if cap_.count0 <= 2 {
			clearopbeep(cap_.oap)
			return
		}
		cap_.count0 = curbuf.b_ml.ml_line_count - curwin.w_cursor.lnum + 1
	}

	prep_redo(cap_.oap.regname, cap_.count0, NUL, cap_.cmdchar, NUL, NUL, cap_.nchar)
	do_join(cap_.count0, B2i(cap_.nchar == NUL), TRUE, TRUE, TRUE)
}

func nv_put(cap_ *S_cmdarg_S) {
	nv_put_opt(cap_, FALSE)
}

func nv_put_opt(cap_ *S_cmdarg_S, fix_indent int32) {
	var regname int32 = 0
	var reg1 *yankreg_T = nil
	var reg2 *yankreg_T = nil
	var empty int32 = FALSE
	var was_visual int32 = FALSE
	var dir int32
	var flags int32 = 0
	var keep_registers int32 = FALSE

	if cap_.oap.op_type != OP_NOP {
		clearopbeep(cap_.oap)
		return
	}

	if fix_indent != 0 {
		if cap_.cmdchar == ']' && cap_.nchar == 'p' {
			dir = FORWARD
		} else {
			dir = -1
		}
		flags |= PUT_FIXINDENT
	} else {
		if cap_.cmdchar == 'P' || ((cap_.cmdchar == 'g' || cap_.cmdchar == 'z') && cap_.nchar == 'P') {
			dir = -1
		} else {
			dir = FORWARD
		}
	}
	prep_redo_cmd(cap_)
	if cap_.cmdchar == 'g' {
		flags |= PUT_CURSEND
	} else if cap_.cmdchar == 'z' {
		flags |= PUT_BLOCK_INNER
	}

	if VIsual_active != 0 {
		was_visual = TRUE
		regname = cap_.oap.regname
		keep_registers = B2i(cap_.cmdchar == 'P')
		if regname == 0 || regname == '"' || uint32(regname)-'0' < 10 || regname == '-' {
			reg1 = get_register(regname, TRUE)
		}

		cap_.cmdchar = 'd'
		cap_.nchar = NUL
		if keep_registers != 0 {
			cap_.oap.regname = '_'
		} else {
			cap_.oap.regname = NUL
		}
		msg_silent++
		nv_operator(cap_)
		do_pending_operator(cap_, 0, FALSE)
		empty = curbuf.b_ml.ml_flags & ML_EMPTY
		msg_silent--

		cap_.oap.regname = regname

		if reg1 != nil {
			reg2 = get_register(regname, FALSE)
			put_register(regname, reg1)
		}

		if VIsual_mode == 'V' {
			flags |= PUT_LINE
		} else if VIsual_mode == 'v' {
			flags |= PUT_LINE_SPLIT
		}
		if VIsual_mode == Ctrl_V && dir == FORWARD {
			flags |= PUT_LINE_FORWARD
		}
		dir = -1
		if (VIsual_mode != 'V' && curwin.w_cursor.col < curbuf.b_op_start.col) || (VIsual_mode == 'V' && curwin.w_cursor.lnum < curbuf.b_op_start.lnum) {
			dir = FORWARD
		}
		VIsual_active = TRUE
	}
	do_put(cap_.oap.regname, Ptr[byte]{}, dir, cap_.count1, flags)

	if reg2 != nil {
		put_register(regname, reg2)
	}

	if was_visual != 0 {
		curbuf.b_visual.vi_start = curbuf.b_op_start
		curbuf.b_visual.vi_end = curbuf.b_op_end
		if p_sel.Get() == 'e' {
			inc(&curbuf.b_visual.vi_end)
		}
	}

	if empty != 0 && ml_get(curbuf.b_ml.ml_line_count).Get() == NUL {
		ml_delete_flags(curbuf.b_ml.ml_line_count, ML_DEL_MESSAGE)
		deleted_lines(curbuf.b_ml.ml_line_count+1, 1)

		if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
			curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
			coladvance(colnr_T(MAXCOL))
		}
	}
}

func nv_open(cap_ *S_cmdarg_S) {
	if VIsual_active != 0 {
		v_swap_corners(cap_.cmdchar)
	} else {
		n_opencmd(cap_)
	}
}

func nv_cursorhold(cap_ *S_cmdarg_S) {
	did_cursorhold = TRUE
	cap_.retval |= CA_COMMAND_BUSY
}

func get_op_type(char1 int32, char2 int32) int32 {
	var i int32

	if char1 == 'r' {
		return OP_REPLACE
	}
	if char1 == '~' {
		return OP_TILDE
	}
	if char1 == 'g' && char2 == Ctrl_A {
		return OP_NR_ADD
	}
	if char1 == 'g' && char2 == Ctrl_X {
		return OP_NR_SUB
	}
	if char1 == 'z' && char2 == 'y' {
		return OP_YANK
	}
	for i = 0; ; i++ {
		if int32(opchars[i][0]) == char1 && int32(opchars[i][1]) == char2 {
			break
		}
		if i == int32(len(opchars))-1 {
			internal_error(S("get_op_type()"))
			break
		}
	}
	return i
}

func op_on_lines(op int32) int32 {
	return int32(opchars[op][2]) & OPF_LINES
}

func get_op_char(optype int32) int32 {
	return int32(opchars[optype][0])
}

func get_extra_op_char(optype int32) int32 {
	return int32(opchars[optype][1])
}

func op_shift(oap *S_oparg_S, curs_top int32, amount int32) {
	var i int64
	var first_char int32
	var block_col int32 = 0

	if u_save(linenr_T(oap.start.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
		return
	}

	if oap.block_mode != 0 {
		block_col = curwin.w_cursor.col
	}

	for i = oap.line_count; ; {
		i--
		if !(i >= 0) {
			break
		}
		first_char = int32(ml_get_curline().Get())
		if first_char == NUL {
			curwin.w_cursor.col = 0
		} else if oap.block_mode != 0 {
			shift_block(oap, amount)
		} else {
			if first_char != '#' || preprocs_left() == 0 {
				shift_line(B2i(oap.op_type == OP_LSHIFT), p_sr, amount, FALSE)
			}
		}
		curwin.w_cursor.lnum++
	}

	changed_lines(oap.start.lnum, 0, oap.end.lnum+1, 0)
	if oap.block_mode != 0 {
		curwin.w_cursor.lnum = oap.start.lnum
		curwin.w_cursor.col = block_col
	} else if curs_top != 0 {
		curwin.w_cursor.lnum = oap.start.lnum
		beginline(BL_SOL | BL_FIX)
	} else {
		curwin.w_cursor.lnum--
	}

	if oap.line_count > p_report {
		var op Ptr[byte]
		var msg_line_single Ptr[byte]
		var msg_line_plural Ptr[byte]

		if oap.op_type == OP_RSHIFT {
			op = S(">")
		} else {
			op = S("<")
		}
		msg_line_single = NGETTEXT(S("%ld line %sed %d time"), S("%ld line %sed %d times"), uint64(int64(amount)))
		msg_line_plural = NGETTEXT(S("%ld lines %sed %d time"), S("%ld lines %sed %d times"), uint64(int64(amount)))
		vim_snprintf(IObuff, 1024+1, NGETTEXT(msg_line_single, msg_line_plural, uint64(oap.line_count)), oap.line_count, op, amount)
		msg_attr_keep(IObuff, 0, TRUE)
	}

	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = oap.start
		curbuf.b_op_end.lnum = oap.end.lnum
		curbuf.b_op_end.col = ml_get_len(oap.end.lnum)
		if curbuf.b_op_end.col > 0 {
			curbuf.b_op_end.col--
		}
	}
}

func get_new_sw_indent(left int32, round int32, amount vimlong_T, sw_val vimlong_T) vimlong_T {
	count := vimlong_T(get_indent())
	var i vimlong_T
	var j vimlong_T

	if round != 0 {
		i = vimlong_T(trim_to_int(count)) / sw_val
		j = vimlong_T(trim_to_int(count)) % sw_val
		if j != 0 && left != 0 {
			amount--
		}
		if left != 0 {
			i -= amount
			if i < 0 {
				i = 0
			}
		} else {
			i += amount
		}
		count = i * sw_val
	} else {
		if left != 0 {
			count -= sw_val * amount
			if count < 0 {
				count = 0
			}
		} else {
			count += sw_val * amount
		}
	}

	return count
}

func shift_line(left int32, round int32, amount int32, call_changed_bytes int32) {
	var count vimlong_T
	sw_val := curbuf.b_p_sw
	ts_val := curbuf.b_p_ts

	if sw_val != 0 {
		count = get_new_sw_indent(left, round, vimlong_T(amount), sw_val)
	} else {
		count = get_new_sw_indent(left, round, vimlong_T(amount), ts_val)
	}

	if State&VREPLACE_FLAG != 0 {
		change_indent(INDENT_SET, trim_to_int(count), FALSE, NUL, call_changed_bytes)
	} else {
		var fl int32
		if call_changed_bytes != 0 {
			fl = SIN_CHANGED
		} else {
			fl = 0
		}
		set_indent(trim_to_int(count), fl)
	}
}

func shift_block(oap *S_oparg_S, amount int32) {
	left := B2i(oap.op_type == OP_LSHIFT)
	oldstate := State
	var total int32
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var newlen usize
	var oldlen usize
	oldcol := curwin.w_cursor.col
	sw_val := int32(get_sw_value_indent(curbuf, left))
	ts_val := int32(curbuf.b_p_ts)
	var bd S_block_def
	var incr int32
	var ws_vcol colnr_T
	var added int32
	var new_line_len usize

	State = MODE_INSERT
	block_prep(oap, &bd, curwin.w_cursor.lnum, TRUE)
	if bd.is_short != 0 {
		return
	}

	total = int32(uint32(amount) * uint32(sw_val))
	if (total / sw_val) != amount {
		return
	}

	oldp = ml_get_curline()
	oldlen = usize(ml_get_curline_len())

	if left == 0 {
		var tabs int32 = 0
		var spaces int32 = 0
		var cts chartabsize_T

		total += bd.pre_whitesp
		ws_vcol = bd.start_vcol - bd.pre_whitesp
		if bd.startspaces != 0 {
			if utfc_ptr2len(bd.textstart) == 1 {
				bd.textstart = bd.textstart.Add(1)
			} else {
				ws_vcol = 0
				bd.startspaces = 0
			}
		}

		init_chartabsize_arg(&cts, curwin, curwin.w_cursor.lnum, bd.start_vcol, bd.textstart, bd.textstart)
		for cts.cts_ptr.Get() == ' ' || cts.cts_ptr.Get() == '\t' {
			incr = lbr_chartabsize_adv(&cts)
			total += incr
			cts.cts_vcol += incr
		}
		bd.textstart = cts.cts_ptr
		bd.start_vcol = cts.cts_vcol

		if curbuf.b_p_et == 0 {
			tabs = ((ws_vcol % ts_val) + total) / ts_val
		}
		if tabs > 0 {
			spaces = ((ws_vcol % ts_val) + total) % ts_val
		} else {
			spaces = total
		}
		bd.textcol -= bd.pre_whitesp_c - B2i(bd.startspaces != 0)

		new_line_len = usize(bd.textcol+tabs+spaces) + (oldlen - usize(bd.textstart.Sub(oldp)))
		newp = Alloc(int(new_line_len + 1))
		Memmove(newp, oldp, int(bd.textcol))
		newlen = usize(bd.textcol)
		Memset(newp.Add(int(newlen)), TAB, int(tabs))
		newlen += usize(tabs)
		Memset(newp.Add(int(newlen)), ' ', int(spaces))
		musl_strcpy(newp.Add(int(newlen)+int(spaces)), bd.textstart)
	} else {
		var destination_col colnr_T
		var verbatim_copy_end Ptr[byte]
		var verbatim_copy_width colnr_T
		var fill usize
		var block_space_width usize
		var shift_amount usize
		non_white := bd.textstart
		var non_white_col colnr_T
		var fixedlen usize
		var cts chartabsize_T

		if bd.startspaces != 0 {
			non_white = non_white.Add(int(utfc_ptr2len(non_white)))
		}

		non_white_col = bd.start_vcol

		init_chartabsize_arg(&cts, curwin, curwin.w_cursor.lnum, non_white_col, bd.textstart, non_white)
		for cts.cts_ptr.Get() == ' ' || cts.cts_ptr.Get() == '\t' {
			incr = lbr_chartabsize_adv(&cts)
			cts.cts_vcol += incr
		}
		non_white_col = cts.cts_vcol
		non_white = cts.cts_ptr

		block_space_width = usize(non_white_col - oap.start_vcol)
		if block_space_width < usize(total) {
			shift_amount = block_space_width
		} else {
			shift_amount = usize(total)
		}

		destination_col = colnr_T(usize(non_white_col) - shift_amount)

		verbatim_copy_end = bd.textstart
		verbatim_copy_width = bd.start_vcol

		if bd.startspaces != 0 {
			verbatim_copy_width -= bd.start_char_vcols
		}
		init_chartabsize_arg(&cts, curwin, 0, verbatim_copy_width, bd.textstart, verbatim_copy_end)
		for cts.cts_vcol < destination_col {
			incr = lbr_chartabsize(&cts)
			if cts.cts_vcol+incr > destination_col {
				break
			}
			cts.cts_vcol += incr
			cts.cts_ptr = cts.cts_ptr.Add(int(utfc_ptr2len(cts.cts_ptr)))
		}
		verbatim_copy_width = cts.cts_vcol
		verbatim_copy_end = cts.cts_ptr

		fill = usize(destination_col - verbatim_copy_width)

		fixedlen = usize(verbatim_copy_end.Sub(oldp))
		new_line_len = fixedlen + fill + (oldlen - usize(non_white.Sub(oldp)))

		newp = Alloc(int(new_line_len + 1))
		Memmove(newp, oldp, int(fixedlen))
		newlen = fixedlen
		Memset(newp.Add(int(newlen)), ' ', int(fill))
		musl_strcpy(newp.Add(int(newlen+fill)), non_white)
	}
	ml_replace(curwin.w_cursor.lnum, newp, FALSE)

	if new_line_len >= oldlen {
		added = int32(new_line_len - oldlen)
	} else {
		added = 0 - int32(oldlen-new_line_len)
	}
	inserted_bytes(curwin.w_cursor.lnum, bd.textcol, added)
	State = oldstate
	curwin.w_cursor.col = oldcol
}

func block_insert(oap *S_oparg_S, s Ptr[byte], slen usize, b_insert int32, bdp *S_block_def) {
	var ts_val int32
	var count int32 = 0
	var spaces int32 = 0
	var offset colnr_T
	var startcol colnr_T
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var lnum linenr_T
	oldstate := State

	State = MODE_INSERT

	for lnum = oap.start.lnum + 1; lnum <= oap.end.lnum; lnum++ {
		block_prep(oap, bdp, lnum, TRUE)
		if bdp.is_short != 0 && b_insert != 0 {
			continue
		}

		oldp = ml_get(lnum)

		if b_insert != 0 {
			ts_val = bdp.start_char_vcols
			spaces = bdp.startspaces
			if spaces != 0 {
				count = ts_val - 1
			}
			offset = bdp.textcol
		} else {
			ts_val = bdp.end_char_vcols
			if bdp.is_short == 0 {
				if bdp.endspaces != 0 {
					spaces = ts_val - bdp.endspaces
				} else {
					spaces = 0
				}
				if spaces != 0 {
					count = ts_val - 1
				}
				offset = bdp.textcol + bdp.textlen - B2i(spaces != 0)
			} else {
				if bdp.is_MAX == 0 {
					spaces = (oap.end_vcol - bdp.end_vcol) + 1
				}
				count = spaces
				offset = bdp.textcol + bdp.textlen
			}
		}

		if spaces > 0 {
			offset -= utf_head_off(oldp, oldp.Add(int(offset)))
		}

		if spaces < 0 {
			spaces = 0
		}

		var extra int32
		if spaces > 0 && bdp.is_short == 0 {
			extra = ts_val - spaces
		} else {
			extra = 0
		}
		newp = Alloc(int(usize(ml_get_len(lnum)+spaces) + slen + usize(extra) + usize(count) + 1))

		Memmove(newp, oldp, int(offset))
		oldp = oldp.Add(int(offset))

		Memset(newp.Add(int(offset)), ' ', int(spaces))
		startcol = offset + spaces

		Memmove(newp.Add(int(startcol)), s, int(slen))
		offset += int32(slen)

		if spaces > 0 && bdp.is_short == 0 {
			if oldp.Get() == TAB {
				Memset(newp.Add(int(offset+spaces)), ' ', int(ts_val-spaces))
				oldp = oldp.Add(1)
				count++
			} else {
				count = spaces
			}
		}

		if spaces > 0 {
			offset += count
		}
		musl_strcpy(newp.Add(int(offset)), oldp)

		ml_replace(lnum, newp, FALSE)

		if b_insert != 0 {
			inserted_bytes(lnum, startcol, int32(slen))
		}

		if lnum == oap.end.lnum {
			curbuf.b_op_end.lnum = oap.end.lnum
			curbuf.b_op_end.col = offset
			if curbuf.b_visual.vi_end.coladd != 0 {
				curbuf.b_visual.vi_end.col += curbuf.b_visual.vi_end.coladd
				curbuf.b_visual.vi_end.coladd = 0
			}
		}
	}

	changed_lines(oap.start.lnum+1, 0, oap.end.lnum+1, 0)

	State = oldstate
}

func op_delete(oap *S_oparg_S) int32 {
	var n int32
	var lnum linenr_T
	var ptr Ptr[byte]
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var bd S_block_def
	old_lcount := curbuf.b_ml.ml_line_count
	var did_yank int32 = FALSE

	if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
		return OK
	}

	if oap.empty != 0 {
		return u_save_cursor()
	}

	if curbuf.b_p_ma == 0 {
		emsg(gettext_(e_cannot_make_changes_modifiable_is_off))
		return FAIL
	}

	if VIsual_select != 0 && oap.is_VIsual != 0 {
		oap.regname = VIsual_select_reg
	}

	mb_adjust_opend(oap)

	if oap.motion_type == MCHAR && oap.is_VIsual == 0 && oap.block_mode == 0 && oap.line_count > 1 && oap.motion_force == NUL && !vim_strchr(p_cpo, CPO_WORD).Nil() && oap.op_type == OP_DELETE {
		ptr = ml_get(oap.end.lnum).Add(int(oap.end.col))
		if ptr.Get() != NUL {
			ptr = ptr.Add(int(oap.inclusive))
		}
		ptr = skipwhite(ptr)
		if ptr.Get() == NUL && inindent(0) != 0 {
			oap.motion_type = MLINE
		}
	}

	if oap.motion_type == MCHAR && oap.line_count == 1 && oap.op_type == OP_DELETE && ml_get(oap.start.lnum).Get() == NUL {
		if virtual_op != 0 {
			goto setmarks
		}
		if !vim_strchr(p_cpo, CPO_EMPTYREGION).Nil() {
			beep_flush()
		}
		return OK
	}

	if oap.regname != '_' {
		if oap.regname != 0 {
			if valid_yank_reg(oap.regname, TRUE) == 0 {
				beep_flush()
				return OK
			}
			get_yank_register(oap.regname, TRUE)
			if op_yank(oap, TRUE, FALSE) == OK {
				did_yank = TRUE
			}
		} else {
			reset_y_append()
		}

		if oap.motion_type == MLINE || oap.line_count > 1 || oap.use_reg_one != 0 {
			shift_delete_registers()
			if op_yank(oap, TRUE, FALSE) == OK {
				did_yank = TRUE
			}
		}

		if (oap.regname == 0) && oap.motion_type != MLINE && oap.line_count == 1 {
			oap.regname = '-'
			get_yank_register(oap.regname, TRUE)
			if op_yank(oap, TRUE, FALSE) == OK {
				did_yank = TRUE
			}
			oap.regname = 0
		}

		if did_yank == 0 {
			msg_silent_save := msg_silent

			msg_silent = 0
			n = ask_yesno(gettext_(S("cannot yank; delete anyway")), TRUE)
			msg_silent = msg_silent_save
			if n != 'y' {
				emsg(gettext_(e_command_aborted))
				return FAIL
			}
		}

	}

	if oap.block_mode != 0 {
		if u_save(linenr_T(oap.start.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
			return FAIL
		}

		for lnum = curwin.w_cursor.lnum; lnum <= oap.end.lnum; lnum++ {
			block_prep(oap, &bd, lnum, TRUE)
			if bd.textlen == 0 {
				continue
			}

			if lnum == curwin.w_cursor.lnum {
				curwin.w_cursor.col = bd.textcol + bd.startspaces
				curwin.w_cursor.coladd = 0
			}

			n = bd.textlen - bd.startspaces - bd.endspaces
			oldp = ml_get(lnum)
			newp = Alloc(int(ml_get_len(lnum) + 1 - n))
			Memmove(newp, oldp, int(bd.textcol))
			Memset(newp.Add(int(bd.textcol)), ' ', int(bd.startspaces+bd.endspaces))
			musl_strcpy(newp.Add(int(bd.textcol+bd.startspaces+bd.endspaces)), oldp.Add(int(bd.textcol+bd.textlen)))
			ml_replace(lnum, newp, FALSE)

		}

		check_cursor_col()
		changed_lines(curwin.w_cursor.lnum, curwin.w_cursor.col, oap.end.lnum+1, 0)
		oap.line_count = 0
	} else if oap.motion_type == MLINE {
		if oap.op_type == OP_CHANGE {
			if oap.line_count > 1 {
				lnum = curwin.w_cursor.lnum
				curwin.w_cursor.lnum++
				del_lines(int64(oap.line_count-1), TRUE)
				curwin.w_cursor.lnum = lnum
			}
			if u_save_cursor() == FAIL {
				return FAIL
			}
			if curbuf.b_p_ai != 0 {
				beginline(BL_WHITE)
				did_ai = TRUE
				ai_col = curwin.w_cursor.col
			} else {
				beginline(0)
			}
			truncate_line(FALSE)
			if oap.line_count > 1 {
				u_clearline()
			}
		} else {
			del_lines(oap.line_count, TRUE)
			beginline(BL_WHITE | BL_FIX)
			u_clearline()
		}
	} else {
		if virtual_op != 0 {
			var endcol int32 = 0

			if gchar_pos(&oap.start) == '\t' {
				if u_save_cursor() == FAIL {
					return FAIL
				}
				if oap.line_count == 1 {
					endcol = getviscol2(oap.end.col, oap.end.coladd)
				}
				coladvance_force(getviscol2(oap.start.col, oap.start.coladd))
				oap.start = curwin.w_cursor
				if oap.line_count == 1 {
					coladvance(endcol)
					oap.end.col = curwin.w_cursor.col
					oap.end.coladd = curwin.w_cursor.coladd
					curwin.w_cursor = oap.start
				}
			}

			if gchar_pos(&oap.end) == '\t' && int32(oap.end.coladd) < oap.inclusive {
				if u_save(linenr_T(oap.end.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
					return FAIL
				}
				curwin.w_cursor = oap.end
				coladvance_force(getviscol2(oap.end.col, oap.end.coladd))
				oap.end = curwin.w_cursor
				curwin.w_cursor = oap.start
			}
			mb_adjust_opend(oap)
		}

		if oap.line_count == 1 {
			if u_save_cursor() == FAIL {
				return FAIL
			}

			if !vim_strchr(p_cpo, CPO_DOLLAR).Nil() && oap.op_type == OP_CHANGE && oap.end.lnum == curwin.w_cursor.lnum && oap.is_VIsual == 0 {
				display_dollar(oap.end.col - B2i(oap.inclusive == 0))
			}

			n = oap.end.col - oap.start.col + 1 - B2i(oap.inclusive == 0)

			if virtual_op != 0 {
				len_ := int32(ml_get_curline_len())

				if oap.end.coladd != 0 && int32(oap.end.col) >= len_-1 && !(oap.start.coladd != 0 && int32(oap.end.col) >= len_-1) {
					n++
				}
				if n == 0 && oap.start.coladd != oap.end.coladd {
					n = 1
				}

				if gchar_cursor() != NUL {
					curwin.w_cursor.coladd = 0
				}
			}
			del_bytes(int64(n), B2i(virtual_op == 0), B2i(oap.op_type == OP_DELETE && oap.is_VIsual == 0))
		} else {
			var curpos pos_T

			if u_save(linenr_T(curwin.w_cursor.lnum-1), linenr_T(curwin.w_cursor.lnum+oap.line_count)) == FAIL {
				return FAIL
			}

			truncate_line(TRUE)

			curpos = curwin.w_cursor
			curwin.w_cursor.lnum++
			del_lines(int64(oap.line_count-2), FALSE)

			n = (oap.end.col + 1 - B2i(oap.inclusive == 0))
			curwin.w_cursor.col = 0
			del_bytes(int64(n), B2i(virtual_op == 0), B2i(oap.op_type == OP_DELETE && oap.is_VIsual == 0))
			curwin.w_cursor = curpos
			do_join(2, FALSE, FALSE, FALSE, FALSE)
		}
	}

	msgmore(curbuf.b_ml.ml_line_count - old_lcount)

setmarks:
	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		if oap.block_mode != 0 {
			curbuf.b_op_end.lnum = oap.end.lnum
			curbuf.b_op_end.col = oap.start.col
		} else {
			curbuf.b_op_end = oap.start
		}
		curbuf.b_op_start = oap.start
	}

	return OK
}

func mb_adjust_opend(oap *S_oparg_S) {
	var line Ptr[byte]
	var ptr Ptr[byte]

	if oap.inclusive == 0 {
		return
	}

	line = ml_get(oap.end.lnum)
	ptr = line.Add(int(oap.end.col))
	if ptr.Get() != NUL {
		ptr = ptr.Add(-int(utf_head_off(line, ptr)))
		ptr = ptr.Add(int(utfc_ptr2len(ptr) - 1))
		oap.end.col = colnr_T(ptr.Sub(line))
	}
}

func replace_character(c int32) {
	n := State

	State = REPLACE_FLAG | MODE_INSERT
	ins_char(c)
	State = n
	dec_cursor()
}

func op_replace(oap *S_oparg_S, c int32) int32 {
	var n int32
	var numc int32
	var num_chars int32
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var newlen usize
	var oldlen usize
	var bd S_block_def
	after_p := Ptr[byte]{}
	var had_ctrl_v_cr int32 = FALSE

	if (curbuf.b_ml.ml_flags&ML_EMPTY) != 0 || oap.empty != 0 {
		return OK
	}

	if c == -1 {
		had_ctrl_v_cr = TRUE
		c = CAR
	} else if c == -2 {
		had_ctrl_v_cr = TRUE
		c = NL
	}

	mb_adjust_opend(oap)

	if u_save(linenr_T(oap.start.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
		return FAIL
	}

	if oap.block_mode != 0 {
		bd.is_MAX = B2i(curwin.w_curswant == MAXCOL)
		for ; curwin.w_cursor.lnum <= oap.end.lnum; curwin.w_cursor.lnum++ {
			curwin.w_cursor.col = 0
			block_prep(oap, &bd, curwin.w_cursor.lnum, TRUE)
			if bd.textlen == 0 && (virtual_op == 0 || bd.is_MAX != 0) {
				continue
			}

			if virtual_op != 0 && bd.is_short != 0 && bd.textstart.Get() == NUL {
				var vpos pos_T

				vpos.lnum = curwin.w_cursor.lnum
				getvpos(&vpos, oap.start_vcol)
				bd.startspaces += vpos.coladd
				n = bd.startspaces
			} else {
				if bd.startspaces != 0 {
					n = bd.start_char_vcols - 1
				} else {
					n = 0
				}
			}

			if bd.endspaces != 0 && bd.is_oneChar == 0 && bd.end_char_vcols > 0 {
				n += bd.end_char_vcols - 1
			} else {
				n += 0
			}
			numc = oap.end_vcol - oap.start_vcol + 1
			if bd.is_short != 0 && (virtual_op == 0 || bd.is_MAX != 0) {
				numc -= (oap.end_vcol - bd.end_vcol) + 1
			}

			if utf_char2cells(c) > 1 {
				if (numc&1) != 0 && bd.is_short == 0 {
					bd.endspaces++
					n++
				}
				numc = numc / 2
			}

			num_chars = numc
			numc *= utf_char2len(c)
			n += numc - bd.textlen

			oldp = ml_get_curline()
			oldlen = usize(ml_get_curline_len())
			newp = Alloc(int(oldlen + 1 + usize(n)))
			Memset(newp, NUL, int(oldlen+1+usize(n)))
			Memmove(newp, oldp, int(bd.textcol))
			newlen = usize(bd.textcol)
			Memset(newp.Add(int(newlen)), ' ', int(bd.startspaces))
			newlen += usize(bd.startspaces)
			if had_ctrl_v_cr != 0 || (c != '\r' && c != '\n') {
				for {
					num_chars--
					if !(num_chars >= 0) {
						break
					}
					newlen += usize(utf_char2bytes(c, newp.Add(int(newlen))))
				}
				if bd.is_short == 0 {
					Memset(newp.Add(int(newlen)), ' ', int(bd.endspaces))
					musl_strcpy(newp.Add(int(newlen)+int(bd.endspaces)), oldp.Add(int(bd.textcol+bd.textlen)))
				}
			} else {
				after_p = Alloc(int(oldlen + 1 + usize(n) - newlen))
				musl_strcpy(after_p, oldp.Add(int(bd.textcol+bd.textlen)))
			}

			ml_replace(curwin.w_cursor.lnum, newp, FALSE)
			if !after_p.Nil() {
				l := curwin.w_cursor.lnum
				curwin.w_cursor.lnum++
				ml_append(l, after_p, 0)
				appended_lines_mark(curwin.w_cursor.lnum, 1)
				oap.end.lnum++
			}
		}
	} else {
		if oap.motion_type == MLINE {
			oap.start.col = 0
			curwin.w_cursor.col = 0
			oap.end.col = ml_get_len(oap.end.lnum)
			if oap.end.col != 0 {
				oap.end.col--
			}
		} else if oap.inclusive == 0 {
			dec(&oap.end)
		}

		for {
			var lt bool
			if curwin.w_cursor.lnum != oap.end.lnum {
				lt = curwin.w_cursor.lnum < oap.end.lnum
			} else if curwin.w_cursor.col != oap.end.col {
				lt = curwin.w_cursor.col < oap.end.col
			} else {
				lt = curwin.w_cursor.coladd < oap.end.coladd
			}
			if !(lt || (curwin.w_cursor.lnum == oap.end.lnum && curwin.w_cursor.col == oap.end.col && curwin.w_cursor.coladd == oap.end.coladd)) {
				break
			}
			var done int32 = FALSE

			n = gchar_cursor()
			if n != NUL {
				new_byte_len := utf_char2len(c)
				old_byte_len := utfc_ptr2len(ml_get_cursor())

				if new_byte_len > 1 || old_byte_len > 1 {
					if curwin.w_cursor.lnum == oap.end.lnum {
						oap.end.col += new_byte_len - old_byte_len
					}
					replace_character(c)
					done = TRUE
				} else {
					if n == TAB {
						var end_vcol int32 = 0

						if curwin.w_cursor.lnum == oap.end.lnum {
							end_vcol = getviscol2(oap.end.col, oap.end.coladd)
						}
						coladvance_force(getviscol())
						if curwin.w_cursor.lnum == oap.end.lnum {
							getvpos(&oap.end, end_vcol)
						}
					}
					if gchar_cursor() != NUL {
						pbyte(curwin.w_cursor, c)
						done = TRUE
					}
				}
			}
			if done == 0 && virtual_op != 0 && curwin.w_cursor.lnum == oap.end.lnum {
				virtcols := oap.end.coladd

				if curwin.w_cursor.lnum == oap.start.lnum && oap.start.col == oap.end.col && oap.start.coladd != 0 {
					virtcols -= oap.start.coladd
				}

				coladvance_force(getviscol2(oap.end.col, oap.end.coladd) + 1)
				curwin.w_cursor.col -= (virtcols + 1)
				for ; virtcols >= 0; virtcols-- {
					if utf_char2len(c) > 1 {
						replace_character(c)
					} else {
						pbyte(curwin.w_cursor, c)
					}
					if inc(&curwin.w_cursor) == -1 {
						break
					}
				}
			}

			if inc_cursor() == -1 {
				break
			}
		}
	}

	curwin.w_cursor = oap.start
	check_cursor()
	changed_lines(oap.start.lnum, oap.start.col, oap.end.lnum+1, 0)

	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = oap.start
		curbuf.b_op_end = oap.end
	}

	return OK
}

// ==== from f11.go ====
// Transpiled by hand from editor.c: op_tilde .. did_set_modifiable.

// f11_lt_pos is vim's LT_POS(a, b) macro, expanded inline in the C.
func f11_lt_pos(a, b pos_T) bool {
	if a.lnum != b.lnum {
		return a.lnum < b.lnum
	}
	if a.col != b.col {
		return a.col < b.col
	}
	return a.coladd < b.coladd
}

// f11_equal_pos is vim's EQUAL_POS(a, b) macro, expanded inline in the C.
func f11_equal_pos(a, b pos_T) bool {
	return a.lnum == b.lnum && a.col == b.col && a.coladd == b.coladd
}

func op_tilde(oap *S_oparg_S) {
	var pos pos_T
	var bd S_block_def
	var did_change int32 = FALSE

	if u_save(linenr_T(oap.start.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
		return
	}

	pos = oap.start
	if oap.block_mode != 0 {
		for ; pos.lnum <= oap.end.lnum; pos.lnum++ {
			var one_change int32

			block_prep(oap, &bd, pos.lnum, FALSE)
			pos.col = bd.textcol
			one_change = swapchars(oap.op_type, &pos, bd.textlen)
			did_change |= one_change

		}
		if did_change != 0 {
			changed_lines(oap.start.lnum, 0, oap.end.lnum+1, 0)
		}
	} else {
		if oap.motion_type == MLINE {
			oap.start.col = 0
			pos.col = 0
			oap.end.col = ml_get_len(oap.end.lnum)
			if oap.end.col != 0 {
				oap.end.col--
			}
		} else if oap.inclusive == 0 {
			dec(&oap.end)
		}

		if pos.lnum == oap.end.lnum {
			did_change = swapchars(oap.op_type, &pos, oap.end.col-pos.col+1)
		} else {
			for {
				var length int32
				if pos.lnum == oap.end.lnum {
					length = oap.end.col + 1
				} else {
					length = ml_get_pos_len(&pos)
				}
				did_change |= swapchars(oap.op_type, &pos, length)
				if (f11_lt_pos(oap.end, pos) || f11_equal_pos(oap.end, pos)) || inc(&pos) == -1 {
					break
				}
			}
		}
		if did_change != 0 {
			changed_lines(oap.start.lnum, oap.start.col, oap.end.lnum+1, 0)
		}
	}

	if did_change == 0 && oap.is_VIsual != 0 {
		redraw_curbuf_later(UPD_INVERTED)
	}

	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = oap.start
		curbuf.b_op_end = oap.end
	}

	if oap.line_count > p_report {
		vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("%ld line changed"), S("%ld lines changed"), uint64(oap.line_count)), oap.line_count)
		msg(iobuff_or(NGETTEXT(S("%ld line changed"), S("%ld lines changed"), uint64(oap.line_count))))
	}
}

func swapchars(op_type int32, pos *pos_T, length int32) int32 {
	var todo int32
	var did_change int32 = 0

	for todo = length; todo > 0; todo-- {
		len_ := utfc_ptr2len(ml_get_pos(pos))

		if len_ > 0 {
			todo -= len_ - 1
		}
		did_change |= swapchar(op_type, pos)
		if inc(pos) == -1 {
			break
		}
	}
	return did_change
}

func swapchar(op_type int32, pos *pos_T) int32 {
	var c int32
	var nc int32

	c = gchar_pos(pos)

	if (op_type == OP_UPPER || op_type == OP_NOP || op_type == OP_TILDE) && c == 0xdf {
		sp := curwin.w_cursor

		curwin.w_cursor = *pos
		del_char(FALSE)
		ins_char(0x1E9E)
		curwin.w_cursor = sp
		return TRUE
	}

	nc = c
	if vim_islower(c) != 0 {
		if op_type != OP_LOWER {
			nc = vim_toupper(c)
		}
	} else if vim_isupper(c) != 0 {
		if op_type != OP_UPPER {
			nc = vim_tolower(c)
		}
	}
	if nc != c {
		if c >= 0x80 || nc >= 0x80 {
			sp := curwin.w_cursor

			curwin.w_cursor = *pos
			del_bytes(int64(utf_ptr2len(ml_get_cursor())), FALSE, FALSE)
			ins_char(nc)
			curwin.w_cursor = sp
		} else {
			pbyte(*pos, nc)
		}
		return TRUE
	}
	return FALSE
}

func op_insert(oap *S_oparg_S, count1 int64) {
	var pre_textlen int64 = 0
	var ind_pre_col colnr_T = 0
	var ind_post_col colnr_T
	var ind_pre_vcol int32 = 0
	var ind_post_vcol int32 = 0
	var bd S_block_def
	var i int32
	var t1 pos_T
	var start_insert pos_T

	bd.is_MAX = B2i(curwin.w_curswant == MAXCOL)

	curwin.w_cursor.lnum = oap.start.lnum
	update_screen(UPD_INVERTED)

	if oap.block_mode != 0 {
		if curwin.w_cursor.coladd > 0 {
			old_ve_flags := int32(curwin.w_onebuf_opt.wo_ve_flags)

			if u_save_cursor() == FAIL {
				return
			}

			curwin.w_onebuf_opt.wo_ve_flags = VE_ALL
			var wcol int32
			if oap.op_type == OP_APPEND {
				wcol = oap.end_vcol + 1
			} else {
				wcol = getviscol()
			}
			coladvance_force(wcol)
			if oap.op_type == OP_APPEND {
				curwin.w_cursor.col--
			}
			curwin.w_onebuf_opt.wo_ve_flags = uint32(old_ve_flags)
		}
		block_prep(oap, &bd, oap.start.lnum, TRUE)
		ind_pre_col = colnr_T(getwhitecols_curline())
		ind_pre_vcol = get_indent()
		pre_textlen = int64(ml_get_len(oap.start.lnum) - bd.textcol)
		if oap.op_type == OP_APPEND {
			pre_textlen -= int64(bd.textlen)
		}
	}

	if oap.op_type == OP_APPEND {
		if oap.block_mode != 0 && curwin.w_cursor.coladd == 0 {
			curwin.w_set_curswant = true
			for ml_get_cursor().Get() != NUL && (curwin.w_cursor.col < bd.textcol+bd.textlen) {
				curwin.w_cursor.col++
			}
			if bd.is_short != 0 && bd.is_MAX == 0 {
				if u_save_cursor() == FAIL {
					return
				}
				for i = 0; i < bd.endspaces; i++ {
					ins_char(' ')
				}
				bd.textlen += bd.endspaces
			}
		} else {
			curwin.w_cursor = oap.end
			check_cursor_col()

			if !(ml_get(curwin.w_cursor.lnum).Get() == NUL) && oap.start_vcol != oap.end_vcol {
				inc_cursor()
			}
		}
	}

	t1 = oap.start
	start_insert = curwin.w_cursor
	edit(NUL, FALSE, int64(linenr_T(count1)))

	if t1.lnum == curbuf.b_op_start_orig.lnum && f11_lt_pos(curbuf.b_op_start_orig, t1) {
		oap.start = curbuf.b_op_start_orig
	}

	if curwin.w_cursor.lnum != oap.start.lnum || got_int != 0 {
		return
	}

	if oap.block_mode != 0 {
		var ins_len int32
		var firstline Ptr[byte]
		var ins_text Ptr[byte]
		var bd2 S_block_def
		var did_indent int32 = FALSE
		var len_ usize
		var add usize
		var offset int32 = 0

		ind_post_col = colnr_T(getwhitecols_curline())
		if curbuf.b_op_start.col > ind_pre_col && ind_post_col > ind_pre_col {
			bd.textcol += ind_post_col - ind_pre_col
			ind_post_vcol = get_indent()
			bd.start_vcol += ind_post_vcol - ind_pre_vcol
			did_indent = TRUE
		}

		if oap.start.lnum == curbuf.b_op_start_orig.lnum && bd.is_MAX == 0 && did_indent == 0 {
			t := getviscol2(curbuf.b_op_start_orig.col, curbuf.b_op_start_orig.coladd)

			if oap.op_type == OP_INSERT && oap.start.col+oap.start.coladd != curbuf.b_op_start_orig.col+curbuf.b_op_start_orig.coladd {
				oap.start.col = curbuf.b_op_start_orig.col
				pre_textlen -= int64(t - oap.start_vcol)
				oap.start_vcol = t
			} else if oap.op_type == OP_APPEND && oap.start.col+oap.start.coladd >= curbuf.b_op_start_orig.col+curbuf.b_op_start_orig.coladd {
				oap.start.col = curbuf.b_op_start_orig.col
				pre_textlen += int64(bd.textlen)
				pre_textlen -= int64(t - oap.start_vcol)
				oap.start_vcol = t
				oap.op_type = OP_INSERT
			}
		}

		if did_indent != 0 && bd.textcol-ind_post_col > 0 {
			oap.start.col += ind_post_col - ind_pre_col
			oap.start_vcol += ind_post_vcol - ind_pre_vcol
			oap.end.col += ind_post_col - ind_pre_col
			oap.end_vcol += ind_post_vcol - ind_pre_vcol
		}
		block_prep(oap, &bd2, oap.start.lnum, TRUE)
		if did_indent != 0 && bd.textcol-ind_post_col > 0 {
			oap.start.col -= ind_post_col - ind_pre_col
			oap.start_vcol -= ind_post_vcol - ind_pre_vcol
			oap.end.col -= ind_post_col - ind_pre_col
			oap.end_vcol -= ind_post_vcol - ind_pre_vcol
		}
		if bd.is_MAX == 0 || bd2.textlen < bd.textlen {
			if oap.op_type == OP_APPEND {
				pre_textlen += int64(bd2.textlen - bd.textlen)
				if bd2.endspaces != 0 {
					bd2.textlen--
				}
			}
			bd.textcol = bd2.textcol
			bd.textlen = bd2.textlen
		}

		firstline = ml_get(oap.start.lnum)
		len_ = usize(ml_get_len(oap.start.lnum))
		add = usize(bd.textcol)
		if oap.op_type == OP_APPEND {
			add += usize(bd.textlen)
			if bd.is_MAX != 0 && (start_insert.lnum == Insstart.lnum && start_insert.col > Insstart.col) {
				offset = (start_insert.col - Insstart.col)
				add -= usize(offset)
				if oap.end_vcol > offset {
					oap.end_vcol -= (offset + 1)
				} else {
					return
				}
			}
		}
		if add > len_ {
			add = len_
		}
		firstline = firstline.Add(int(add))
		len_ -= add
		if pre_textlen >= 0 {
			ins_len = int32(int64(int32(len_)) - pre_textlen - int64(offset))
		}
		if pre_textlen >= 0 && ins_len > 0 {
			ins_text = vim_strnsave(firstline, usize(ins_len))
			if u_save(oap.start.lnum, linenr_T(oap.end.lnum+1)) == OK {
				block_insert(oap, ins_text, usize(ins_len), B2i(oap.op_type == OP_INSERT), &bd)
			}

			curwin.w_cursor.col = oap.start.col
			check_cursor()
		}
	}
}

func op_change(oap *S_oparg_S) int32 {
	var l colnr_T
	var retval int32
	var linenr linenr_T
	var pre_textlen int64 = 0
	var pre_indent int64 = 0
	var firstline Ptr[byte]
	var ins_text Ptr[byte]
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var bd S_block_def

	l = oap.start.col
	if oap.motion_type == MLINE {
		l = 0
		can_si = may_do_si()
	}

	if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
		if u_save_cursor() == FAIL {
			return FALSE
		}
	} else if op_delete(oap) == FAIL {
		return FALSE
	}

	if (l > curwin.w_cursor.col) && !(ml_get(curwin.w_cursor.lnum).Get() == NUL) && virtual_op == 0 {
		inc_cursor()
	}

	if oap.block_mode != 0 {
		if virtual_op != 0 && (curwin.w_cursor.coladd > 0 || gchar_cursor() == NUL) {
			coladvance_force(getviscol())
		}
		firstline = ml_get(oap.start.lnum)
		pre_textlen = int64(ml_get_len(oap.start.lnum))
		pre_indent = int64(getwhitecols(firstline))
		bd.textcol = curwin.w_cursor.col
	}

	if oap.motion_type == MLINE {
		fix_indent()
	}

	save_finish_op := finish_op
	finish_op = FALSE

	retval = edit(NUL, FALSE, int64(linenr_T(1)))

	finish_op = save_finish_op

	if oap.block_mode != 0 && oap.start.lnum != oap.end.lnum && got_int == 0 {
		var ins_len int32

		firstline = ml_get(oap.start.lnum)
		if bd.textcol > colnr_T(pre_indent) {
			new_indent := int64(getwhitecols(firstline))

			pre_textlen += new_indent - pre_indent
			bd.textcol = colnr_T(int64(bd.textcol) + (new_indent - pre_indent))
		}

		ins_len = int32(int64(int32(ml_get_len(oap.start.lnum))) - pre_textlen)
		if ins_len > 0 {
			ins_text = Alloc(int(ins_len + 1))
			if !ins_text.Nil() {
				vim_strncpy(ins_text, firstline.Add(int(bd.textcol)), usize(ins_len))
				for linenr = oap.start.lnum + 1; linenr <= oap.end.lnum; linenr++ {
					block_prep(oap, &bd, linenr, TRUE)
					if bd.is_short == 0 || virtual_op != 0 {
						var vpos pos_T
						var newlen usize

						if bd.is_short != 0 {
							vpos.lnum = linenr
							getvpos(&vpos, oap.start_vcol)
						} else {
							vpos.coladd = 0
						}
						oldp = ml_get(linenr)
						newp = Alloc(int(ml_get_len(linenr) + vpos.coladd + ins_len + 1))
						Memmove(newp, oldp, int(usize(bd.textcol)))
						newlen = usize(bd.textcol)
						Memset(newp.Add(int(newlen)), ' ', int(usize(vpos.coladd)))
						newlen += usize(vpos.coladd)
						Memmove(newp.Add(int(newlen)), ins_text, int(ins_len))
						musl_strcpy(newp.Add(int(newlen)+int(ins_len)), oldp.Add(int(bd.textcol)))
						ml_replace(linenr, newp, FALSE)
					}
				}
				check_cursor()

				changed_lines(oap.start.lnum+1, 0, oap.end.lnum+1, 0)
			}
		}
	}

	return retval
}

func adjust_cursor_eol() {
	cur_ve_flags := get_ve_flags()

	adj_cursor := B2i(curwin.w_cursor.col > 0 && gchar_cursor() == NUL && (cur_ve_flags&VE_ONEMORE) == 0 && (cur_ve_flags&VE_ALL) == 0 && !(restart_edit != 0 || (State&MODE_INSERT) != 0))
	if adj_cursor == 0 {
		return
	}

	dec_cursor()

	if cur_ve_flags == VE_ALL {
		var scol colnr_T
		var ecol colnr_T

		getvcol(curwin, &curwin.w_cursor, &scol, nil, &ecol, 0)
		curwin.w_cursor.coladd = ecol - scol + 1
	}
}

func do_join(count int64, insert_space int32, save_undo int32, use_formatoptions int32, setmark int32) int32 {
	var curr Ptr[byte] = Ptr[byte]{}
	var curr_start Ptr[byte] = Ptr[byte]{}
	var cend Ptr[byte]
	var newp Ptr[byte]
	var newp_len usize
	var spaces Ptr[byte]
	var endcurr1 int32 = NUL
	var endcurr2 int32 = NUL
	var currsize int32 = 0
	var sumsize int32 = 0
	var t linenr_T
	var col colnr_T = 0
	var ret int32 = OK

	if save_undo != 0 && u_save(linenr_T(curwin.w_cursor.lnum-1), linenr_T(curwin.w_cursor.lnum+count)) == FAIL {
		return FAIL
	}

	spaces = Alloc(int(count))
	for t = 0; t < count; t++ {
		curr_start = ml_get(linenr_T(curwin.w_cursor.lnum + t))
		curr = curr_start
		if t == 0 && setmark != 0 && (cmdmod.cmod_flags&CMOD_LOCKMARKS) == 0 {
			curwin.w_buffer.b_op_start.lnum = curwin.w_cursor.lnum
			curwin.w_buffer.b_op_start.col = colnr_T(musl_strlen(curr))
		}
		if insert_space != 0 && t > 0 {
			curr = skipwhite(curr)
			if curr.Get() != NUL && curr.Get() != ')' && sumsize != 0 && endcurr1 != TAB {
				if endcurr1 == ' ' {
					endcurr1 = endcurr2
				} else {
					spaces.Set(int(t), spaces.At(int(t))+1)
				}
				if p_js != 0 && (endcurr1 == '.' || (vim_strchr(p_cpo, CPO_JOINSP).Nil() && (endcurr1 == '?' || endcurr1 == '!'))) {
					spaces.Set(int(t), spaces.At(int(t))+1)
				}
			}
		}
		currsize = int32(musl_strlen(curr))
		sumsize += currsize + int32(spaces.At(int(t)))
		endcurr2 = NUL
		endcurr1 = endcurr2
		if insert_space != 0 && currsize > 0 {
			cend = curr.Add(int(currsize))
			cend = cend.Add(-int(utf_head_off(curr, cend.Add(-1)) + 1))
			endcurr1 = utf_ptr2char(cend)
			if cend.Gt(curr) {
				cend = cend.Add(-int(utf_head_off(curr, cend.Add(-1)) + 1))
				endcurr2 = utf_ptr2char(cend)
			}
		}
		line_breakcheck()
		if got_int != 0 {
			ret = FAIL
			goto theend
		}
	}

	col = sumsize - currsize - int32(spaces.At(int(count-1)))

	newp_len = usize(sumsize + 1)
	newp = Alloc(int(newp_len))
	cend = newp.Add(int(sumsize))
	cend.Put(0)

	for t = count - 1; ; t-- {
		var spaces_removed int32

		cend = cend.Add(-int(currsize))
		Memmove(cend, curr, int(usize(currsize)))

		if spaces.At(int(t)) > 0 {
			cend = cend.Add(-int(spaces.At(int(t))))
			Memset(cend, ' ', int(usize(spaces.At(int(t)))))
		}

		spaces_removed = int32(int64(curr.Sub(curr_start)) - int64(spaces.At(int(t))))

		mark_col_adjust(curwin.w_cursor.lnum+t, colnr_T(0), -t, int64(cend.Sub(newp))-int64(spaces_removed), spaces_removed)
		if t == 0 {
			break
		}
		curr_start = ml_get(linenr_T(curwin.w_cursor.lnum + t - 1))
		curr = curr_start
		if insert_space != 0 && t > 1 {
			curr = skipwhite(curr)
		}
		currsize = int32(musl_strlen(curr))
	}

	ml_replace_len(curwin.w_cursor.lnum, newp, colnr_T(newp_len), TRUE, FALSE)

	if setmark != 0 && (cmdmod.cmod_flags&CMOD_LOCKMARKS) == 0 {
		curwin.w_buffer.b_op_end.lnum = curwin.w_cursor.lnum
		curwin.w_buffer.b_op_end.col = colnr_T(sumsize)
	}

	changed_lines(curwin.w_cursor.lnum, currsize, curwin.w_cursor.lnum+1, 0)
	t = curwin.w_cursor.lnum
	curwin.w_cursor.lnum++
	del_lines(count-1, FALSE)
	curwin.w_cursor.lnum = t

	if !vim_strchr(p_cpo, CPO_JOINCOL).Nil() {
		curwin.w_cursor.col = currsize
	} else {
		curwin.w_cursor.col = col
	}
	check_cursor_col()

	curwin.w_cursor.coladd = 0
	curwin.w_set_curswant = true

theend:
	return ret
}

func block_prep(oap *S_oparg_S, bdp *S_block_def, lnum linenr_T, is_del int32) {
	var incr int32 = 0
	var pend Ptr[byte]
	var pstart Ptr[byte]
	var line Ptr[byte]
	var prev_pstart Ptr[byte]
	var prev_pend Ptr[byte]
	var cts chartabsize_T

	bdp.startspaces = 0
	bdp.endspaces = 0
	bdp.textlen = 0
	bdp.start_vcol = 0
	bdp.end_vcol = 0
	bdp.is_short = FALSE
	bdp.is_oneChar = FALSE
	bdp.pre_whitesp = 0
	bdp.pre_whitesp_c = 0
	bdp.end_char_vcols = 0
	bdp.start_char_vcols = 0

	line = ml_get(lnum)
	prev_pstart = line
	init_chartabsize_arg(&cts, curwin, lnum, bdp.start_vcol, line, line)
	for cts.cts_vcol < oap.start_vcol && cts.cts_ptr.Get() != NUL {
		incr = lbr_chartabsize(&cts)
		cts.cts_vcol += incr
		if cts.cts_ptr.Get() == ' ' || cts.cts_ptr.Get() == '\t' {
			bdp.pre_whitesp += incr
			bdp.pre_whitesp_c++
		} else {
			bdp.pre_whitesp = 0
			bdp.pre_whitesp_c = 0
		}
		prev_pstart = cts.cts_ptr
		cts.cts_ptr = cts.cts_ptr.Add(int(utfc_ptr2len(cts.cts_ptr)))
	}
	bdp.start_vcol = cts.cts_vcol
	pstart = cts.cts_ptr

	bdp.start_char_vcols = incr
	if bdp.start_vcol < oap.start_vcol {
		bdp.end_vcol = bdp.start_vcol
		bdp.is_short = TRUE
		if is_del == 0 || oap.op_type == OP_APPEND {
			bdp.endspaces = oap.end_vcol - oap.start_vcol + 1
		}
	} else {
		bdp.startspaces = bdp.start_vcol - oap.start_vcol
		if is_del != 0 && bdp.startspaces != 0 {
			bdp.startspaces = bdp.start_char_vcols - bdp.startspaces
		}
		pend = pstart
		bdp.end_vcol = bdp.start_vcol
		if bdp.end_vcol > oap.end_vcol {
			bdp.is_oneChar = TRUE
			if oap.op_type == OP_INSERT {
				bdp.endspaces = bdp.start_char_vcols - bdp.startspaces
			} else if oap.op_type == OP_APPEND {
				bdp.startspaces += oap.end_vcol - oap.start_vcol + 1
				bdp.endspaces = bdp.start_char_vcols - bdp.startspaces
			} else {
				bdp.startspaces = oap.end_vcol - oap.start_vcol + 1
				if is_del != 0 && oap.op_type != OP_LSHIFT {
					bdp.startspaces = bdp.start_char_vcols - (bdp.start_vcol - oap.start_vcol)
					bdp.endspaces = bdp.end_vcol - oap.end_vcol - 1
				}
			}
		} else {
			init_chartabsize_arg(&cts, curwin, lnum, bdp.end_vcol, line, pend)
			prev_pend = pend
			for cts.cts_vcol <= oap.end_vcol && cts.cts_ptr.Get() != NUL {
				prev_pend = cts.cts_ptr
				incr = lbr_chartabsize_adv(&cts)
				cts.cts_vcol += incr
			}
			bdp.end_vcol = cts.cts_vcol
			pend = cts.cts_ptr

			if bdp.end_vcol <= oap.end_vcol && (is_del == 0 || oap.op_type == OP_APPEND || oap.op_type == OP_REPLACE) {
				bdp.is_short = TRUE
				if oap.op_type == OP_APPEND || virtual_op != 0 {
					bdp.endspaces = oap.end_vcol - bdp.end_vcol + oap.inclusive
				} else {
					bdp.endspaces = 0
				}
			} else if bdp.end_vcol > oap.end_vcol {
				bdp.endspaces = bdp.end_vcol - oap.end_vcol - 1
				if is_del == 0 && bdp.endspaces != 0 {
					bdp.endspaces = incr - bdp.endspaces
					if pend != pstart {
						pend = prev_pend
					}
				}
			}
		}
		bdp.end_char_vcols = incr
		if is_del != 0 && bdp.startspaces != 0 {
			pstart = prev_pstart
		}
		bdp.textlen = int32(pend.Sub(pstart))
	}
	bdp.textcol = colnr_T(pstart.Sub(line))
	bdp.textstart = pstart
}

func charwise_block_prep(start pos_T, end pos_T, bdp *S_block_def, lnum linenr_T, inclusive int32) {
	var startcol colnr_T = 0
	var endcol colnr_T = MAXCOL
	var cs colnr_T
	var ce colnr_T
	var p Ptr[byte]
	plen := int32(ml_get_len(lnum))

	p = ml_get(lnum)
	bdp.startspaces = 0
	bdp.endspaces = 0
	bdp.is_oneChar = FALSE
	bdp.start_char_vcols = 0

	if lnum == start.lnum {
		startcol = start.col
		if virtual_op != 0 {
			getvcol(curwin, &start, &cs, nil, &ce, 0)
			if ce != cs && start.coladd > 0 {
				bdp.start_char_vcols = ce - cs + 1
				bdp.startspaces = bdp.start_char_vcols - start.coladd
				if bdp.startspaces < 0 {
					bdp.startspaces = 0
				}
				startcol++
			}
		}
	}

	if lnum == end.lnum {
		endcol = end.col
		if virtual_op != 0 {
			getvcol(curwin, &end, &cs, nil, &ce, 0)
			if p.At(int(endcol)) == NUL || (cs+end.coladd < ce && utf_head_off(p, p.Add(int(endcol))) == 0) {
				if start.lnum == end.lnum && start.col == end.col {
					bdp.is_oneChar = TRUE
					bdp.startspaces = end.coladd - start.coladd + inclusive
					endcol = startcol
				} else {
					bdp.endspaces = end.coladd + inclusive
					endcol -= inclusive
				}
			}
		}
	}
	if endcol == MAXCOL {
		endcol = ml_get_len(lnum)
	}
	if startcol > endcol || bdp.is_oneChar != 0 {
		bdp.textlen = 0
	} else {
		bdp.textlen = endcol - startcol + inclusive
	}
	bdp.textcol = startcol
	if startcol <= plen {
		bdp.textstart = p.Add(int(startcol))
	} else {
		bdp.textstart = p
	}
}

func op_addsub(oap *S_oparg_S, Prenum1 linenr_T, g_cmd int32) {
	var pos pos_T
	var bd S_block_def
	var change_cnt int32 = 0
	var amount linenr_T = Prenum1

	if VIsual_active == 0 {
		pos = curwin.w_cursor
		if u_save_cursor() == FAIL {
			return
		}
		change_cnt = do_addsub(oap.op_type, &pos, 0, amount)
		if change_cnt != 0 {
			changed_lines(pos.lnum, 0, pos.lnum+1, 0)
		}
	} else {
		var one_change int32
		var length int32
		var startpos pos_T

		if u_save(linenr_T(oap.start.lnum-1), linenr_T(oap.end.lnum+1)) == FAIL {
			return
		}

		pos = oap.start
		for ; pos.lnum <= oap.end.lnum; pos.lnum++ {
			if oap.block_mode != 0 {
				block_prep(oap, &bd, pos.lnum, FALSE)
				pos.col = bd.textcol
				length = bd.textlen
			} else if oap.motion_type == MLINE {
				curwin.w_cursor.col = 0
				pos.col = 0
				length = ml_get_len(pos.lnum)
			} else {
				if pos.lnum == oap.start.lnum && oap.inclusive == 0 {
					dec(&oap.end)
				}
				length = ml_get_len(pos.lnum)
				pos.col = 0
				if pos.lnum == oap.start.lnum {
					pos.col += oap.start.col
					length -= oap.start.col
				}
				if pos.lnum == oap.end.lnum {
					length = ml_get_len(oap.end.lnum)
					if oap.end.col >= length {
						oap.end.col = length - 1
					}
					length = oap.end.col - pos.col + 1
				}
			}
			one_change = do_addsub(oap.op_type, &pos, length, amount)
			if one_change != 0 {
				if change_cnt == 0 {
					startpos = curbuf.b_op_start
				}
				change_cnt++
			}

			if g_cmd != 0 && one_change != 0 {
				amount += Prenum1
			}
		}

		if change_cnt != 0 {
			changed_lines(oap.start.lnum, 0, oap.end.lnum+1, 0)
		}

		if change_cnt == 0 && oap.is_VIsual != 0 {
			redraw_curbuf_later(UPD_INVERTED)
		}

		if change_cnt > 0 && (cmdmod.cmod_flags&CMOD_LOCKMARKS) == 0 {
			curbuf.b_op_start = startpos
		}

		if int64(change_cnt) > p_report {
			vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("%d line changed"), S("%d lines changed"), uint64(change_cnt)), change_cnt)
			msg(iobuff_or(NGETTEXT(S("%d line changed"), S("%d lines changed"), uint64(change_cnt))))
		}
	}
}

// f11_ascii_isalpha is vim's ASCII_ISALPHA(c) macro, expanded inline in the C.
func f11_ascii_isalpha(c int32) bool {
	return uint32(c)-'A' < 26 || uint32(c)-'a' < 26
}

// f11_charord is vim's CharOrd(x) macro, expanded inline in the C.
func f11_charord(x int32) int32 {
	if x < 'a' {
		return x - 'A'
	}
	return x - 'a'
}

func init() { do_addsub_hexupper = FALSE }

func do_addsub(op_type int32, pos *pos_T, length int32, Prenum1 linenr_T) int32 {
	var col int32
	var pre int32
	var n uvarnumber_T
	var oldn uvarnumber_T
	var ptr Ptr[byte]
	var linelen int32
	var c int32
	var todel int32
	var do_hex int32
	var do_oct int32
	var do_bin int32
	var do_alpha int32
	var do_unsigned int32
	var do_blank int32
	var blank_unsigned int32 = FALSE
	var firstdigit int32
	var subtract int32
	var negative int32 = FALSE
	var was_positive int32 = TRUE
	var visual int32 = VIsual_active
	var did_change int32 = FALSE
	var save_cursor pos_T = curwin.w_cursor
	var maxlen int32 = 0
	var startpos pos_T
	var endpos pos_T
	var save_coladd colnr_T = 0

	do_hex = B2i(!vim_strchr(curbuf.b_p_nf, 'x').Nil())
	do_oct = B2i(!vim_strchr(curbuf.b_p_nf, 'o').Nil())
	do_bin = B2i(!vim_strchr(curbuf.b_p_nf, 'b').Nil())
	do_alpha = B2i(!vim_strchr(curbuf.b_p_nf, 'p').Nil())
	do_unsigned = B2i(!vim_strchr(curbuf.b_p_nf, 'u').Nil())
	do_blank = B2i(!vim_strchr(curbuf.b_p_nf, 'k').Nil())

	if virtual_active() != 0 {
		save_coladd = pos.coladd
		pos.coladd = 0
	}

	curwin.w_cursor = *pos
	ptr = ml_get(pos.lnum)
	linelen = ml_get_len(pos.lnum)
	col = pos.col

	if col+B2i(save_coladd != 0) >= linelen {
		goto theend
	}

	if VIsual_active == 0 {
		if do_bin != 0 {
			for col > 0 && vim_isbdigit(int32(ptr.At(int(col)))) != 0 {
				col--
				col -= utf_head_off(ptr, ptr.Add(int(col)))
			}
		}

		if do_hex != 0 {
			for col > 0 && vim_isxdigit(int32(ptr.At(int(col)))) != 0 {
				col--
				col -= utf_head_off(ptr, ptr.Add(int(col)))
			}
		}

		if do_bin != 0 && do_hex != 0 && !(col > 0 && (ptr.At(int(col)) == 'X' || ptr.At(int(col)) == 'x') && ptr.At(int(col-1)) == '0' && utf_head_off(ptr, ptr.Add(int(col-1))) == 0 && vim_isxdigit(int32(ptr.At(int(col+1)))) != 0) {
			col = pos.col

			for col > 0 && vim_isdigit(int32(ptr.At(int(col)))) != 0 {
				col--
				col -= utf_head_off(ptr, ptr.Add(int(col)))
			}
		}

		if (do_hex != 0 && col > 0 && (ptr.At(int(col)) == 'X' || ptr.At(int(col)) == 'x') && ptr.At(int(col-1)) == '0' && utf_head_off(ptr, ptr.Add(int(col-1))) == 0 && vim_isxdigit(int32(ptr.At(int(col+1)))) != 0) || (do_bin != 0 && col > 0 && (ptr.At(int(col)) == 'B' || ptr.At(int(col)) == 'b') && ptr.At(int(col-1)) == '0' && utf_head_off(ptr, ptr.Add(int(col-1))) == 0 && vim_isbdigit(int32(ptr.At(int(col+1)))) != 0) {
			col--
			col -= utf_head_off(ptr, ptr.Add(int(col)))
		} else {
			col = pos.col

			for ptr.At(int(col)) != NUL && vim_isdigit(int32(ptr.At(int(col)))) == 0 && !(do_alpha != 0 && f11_ascii_isalpha(int32(ptr.At(int(col))))) {
				col += utfc_ptr2len(ptr.Add(int(col)))
			}

			for col > 0 && vim_isdigit(int32(ptr.At(int(col-1)))) != 0 && !(do_alpha != 0 && f11_ascii_isalpha(int32(ptr.At(int(col))))) {
				col--
				col -= utf_head_off(ptr, ptr.Add(int(col)))
			}
		}
	}

	if visual != 0 {
		for ptr.At(int(col)) != NUL && length > 0 && vim_isdigit(int32(ptr.At(int(col)))) == 0 && !(do_alpha != 0 && f11_ascii_isalpha(int32(ptr.At(int(col))))) {
			mb_len := utfc_ptr2len(ptr.Add(int(col)))

			col += mb_len
			length -= mb_len
		}

		if length == 0 {
			goto theend
		}

		if col > pos.col && ptr.At(int(col-1)) == '-' && utf_head_off(ptr, ptr.Add(int(col-1))) == 0 && do_unsigned == 0 {
			if do_blank != 0 && col >= 2 && !(ptr.At(int(col-2)) == ' ' || ptr.At(int(col-2)) == '\t') {
				blank_unsigned = TRUE
			} else {
				negative = TRUE
				was_positive = FALSE
			}
		}
	}

	firstdigit = int32(ptr.At(int(col)))
	if !(uint32(firstdigit)-'0' < 10) && !(do_alpha != 0 && f11_ascii_isalpha(firstdigit)) {
		beep_flush()
		goto theend
	}

	if do_alpha != 0 && f11_ascii_isalpha(firstdigit) {
		if op_type == OP_NR_SUB {
			if int64(f11_charord(firstdigit)) < Prenum1 {
				if musl_isupper(int32(byte(firstdigit))) != 0 {
					firstdigit = 'A'
				} else {
					firstdigit = 'a'
				}
			} else {
				firstdigit = int32(int64(firstdigit) - Prenum1)
			}
		} else {
			if int64(26-f11_charord(firstdigit)-1) < Prenum1 {
				if musl_isupper(int32(byte(firstdigit))) != 0 {
					firstdigit = 'Z'
				} else {
					firstdigit = 'z'
				}
			} else {
				firstdigit = int32(int64(firstdigit) + Prenum1)
			}
		}
		curwin.w_cursor.col = col
		if did_change == 0 {
			startpos = curwin.w_cursor
		}
		did_change = TRUE
		del_char(FALSE)
		ins_char(firstdigit)
		endpos = curwin.w_cursor
		curwin.w_cursor.col = col
	} else {
		var buf1 Ptr[byte]
		var buf1len int32
		buf2 := Mk[byte](NUMBUFLEN)
		var buf2len int32
		var save_pos pos_T
		var i int32

		if col > 0 && ptr.At(int(col-1)) == '-' && utf_head_off(ptr, ptr.Add(int(col-1))) == 0 && visual == 0 && do_unsigned == 0 {
			if do_blank != 0 && col >= 2 && !(ptr.At(int(col-2)) == ' ' || ptr.At(int(col-2)) == '\t') {
				blank_unsigned = TRUE
			} else {
				col--
				negative = TRUE
			}
		}

		if visual != 0 && VIsual_mode != 'V' {
			if curbuf.b_visual.vi_curswant == MAXCOL {
				maxlen = linelen - col
			} else {
				maxlen = length
			}
		}

		var overflow int32 = FALSE
		var what int32 = 0
		if do_bin != 0 {
			what += STR2NR_BIN
		}
		if do_oct != 0 {
			what += STR2NR_OCT
		}
		if do_hex != 0 {
			what += STR2NR_HEX
		}
		vim_str2nr(ptr.Add(int(col)), &pre, &length, what, nil, &n, maxlen, FALSE, &overflow)

		if pre != 0 && negative != 0 {
			col++
			length--
			negative = FALSE
		}
		subtract = FALSE
		if op_type == OP_NR_SUB {
			subtract ^= TRUE
		}
		if negative != 0 {
			subtract ^= TRUE
		}

		oldn = n
		if overflow == 0 {
			if subtract != 0 {
				n -= uvarnumber_T(Prenum1)
			} else {
				n += uvarnumber_T(Prenum1)
			}
		}

		if pre == 0 {
			if subtract != 0 {
				if n > oldn {
					n = 1 + (n ^ ^uvarnumber_T(0))
					negative ^= TRUE
				}
			} else {
				if n < oldn {
					n = (n ^ ^uvarnumber_T(0))
					negative ^= TRUE
				}
			}
			if n == 0 {
				negative = FALSE
			}
		}

		if (do_unsigned != 0 || blank_unsigned != 0) && negative != 0 {
			if subtract != 0 {
				n = uvarnumber_T(0)
			} else {
				n = ^uvarnumber_T(0)
			}
			negative = FALSE
		}

		if visual != 0 && was_positive == 0 && negative == 0 && col > 0 {
			col--
			length++
		}

		curwin.w_cursor.col = col
		if did_change == 0 {
			startpos = curwin.w_cursor
		}
		did_change = TRUE
		todel = length
		c = gchar_cursor()
		if c == '-' {
			length--
		}

		save_pos = curwin.w_cursor
		for i = 0; i < todel; i++ {
			if c < 0x100 && musl_isalpha(int32(byte(c))) != 0 {
				if musl_isupper(int32(byte(c))) != 0 {
					do_addsub_hexupper = TRUE
				} else {
					do_addsub_hexupper = FALSE
				}
			}
			inc_cursor()
			c = gchar_cursor()
		}
		curwin.w_cursor = save_pos

		buf1 = Alloc(int(length + NUMBUFLEN))
		ptr = buf1
		if negative != 0 && (visual == 0 || was_positive != 0) {
			ptr.Put('-')
			ptr = ptr.Add(1)
		}
		if pre != 0 {
			ptr.Put('0')
			ptr = ptr.Add(1)
			length--
		}
		if pre == 'b' || pre == 'B' || pre == 'x' || pre == 'X' {
			ptr.Put(byte(pre))
			ptr = ptr.Add(1)
			length--
		}

		if pre == 'b' || pre == 'B' {
			var bit int32 = 0
			var bits int32 = 64 // sizeof(uvarnumber_T) * 8

			for bit = bits; bit > 0; bit-- {
				if (n>>(bit-1))&0x1 != 0 {
					break
				}
			}

			for buf2len = 0; bit > 0 && buf2len < (NUMBUFLEN-1); bit-- {
				var d byte
				if (n>>(bit-1))&0x1 != 0 {
					d = '1'
				} else {
					d = '0'
				}
				buf2.Set(int(buf2len), d)
				buf2len++
			}

			buf2.Set(int(buf2len), NUL)
		} else if pre == 0 {
			buf2len = vim_snprintf(buf2, NUMBUFLEN, S("%llu"), n)
		} else if pre == '0' {
			buf2len = vim_snprintf(buf2, NUMBUFLEN, S("%llo"), n)
		} else if pre != 0 && do_addsub_hexupper != 0 {
			buf2len = vim_snprintf(buf2, NUMBUFLEN, S("%llX"), n)
		} else {
			buf2len = vim_snprintf(buf2, NUMBUFLEN, S("%llx"), n)
		}
		length -= buf2len

		if firstdigit == '0' && !(do_oct != 0 && pre == 0) {
			for {
				more := length > 0
				length--
				if !more {
					break
				}
				ptr.Put('0')
				ptr = ptr.Add(1)
			}
		}
		ptr.Put(NUL)
		buf1len = int32(ptr.Sub(buf1))

		musl_strcpy(buf1.Add(int(buf1len)), buf2)
		buf1len += buf2len

		save_pos = curwin.w_cursor
		if todel > 0 {
			inc_cursor()
		}
		ins_str(buf1, usize(buf1len))

		if todel > 0 {
			bytes_after := ml_get_curline_len() - curwin.w_cursor.col

			curwin.w_cursor = save_pos
			del_char(FALSE)
			curwin.w_cursor.col = ml_get_curline_len() - bytes_after
			todel--
		}
		for {
			more := todel > 0
			todel--
			if !more {
				break
			}
			del_char(FALSE)
		}

		endpos = curwin.w_cursor
		if did_change != 0 && curwin.w_cursor.col != 0 {
			curwin.w_cursor.col--
		}
	}

	if did_change != 0 && (cmdmod.cmod_flags&CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = startpos
		curbuf.b_op_end = endpos
		if curbuf.b_op_end.col > 0 {
			curbuf.b_op_end.col--
		}
	}

theend:
	if visual != 0 {
		curwin.w_cursor = save_cursor
	} else if did_change != 0 {
		curwin.w_set_curswant = true
	} else if virtual_active() != 0 {
		curwin.w_cursor.coladd = save_coladd
	}

	return did_change
}

func clear_oparg(oap *S_oparg_S) {
	*oap = S_oparg_S{}
}

func line_count_info(line Ptr[byte], wc *varnumber_T, cc *varnumber_T, limit varnumber_T, eol_size int32) varnumber_T {
	var i varnumber_T
	var words varnumber_T = 0
	var chars varnumber_T = 0
	var is_word int32 = 0

	for i = 0; i < limit && line.At(int(i)) != NUL; {
		if is_word != 0 {
			if vim_isspace(int32(line.At(int(i)))) != 0 {
				words++
				is_word = 0
			}
		} else if vim_isspace(int32(line.At(int(i)))) == 0 {
			is_word = 1
		}
		chars++
		i += varnumber_T(utfc_ptr2len(line.Add(int(i))))
	}

	if is_word != 0 {
		words++
	}
	*wc += words

	if i < limit && line.At(int(i)) == NUL {
		i += varnumber_T(eol_size)
		chars += varnumber_T(eol_size)
	}
	*cc += chars
	return i
}

func cursor_pos_info() {
	var p Ptr[byte]
	buf1 := Mk[byte](50)
	buf2 := Mk[byte](40)
	var lnum linenr_T
	var byte_count varnumber_T = 0
	var byte_count_cursor varnumber_T = 0
	var char_count varnumber_T = 0
	var char_count_cursor varnumber_T = 0
	var word_count varnumber_T = 0
	var word_count_cursor varnumber_T = 0
	var eol_size int32
	var last_check varnumber_T = 100000
	var line_count_selected int64 = 0
	var min_pos pos_T
	var max_pos pos_T
	var oparg S_oparg_S
	var bd S_block_def

	if curbuf.b_ml.ml_flags&ML_EMPTY != 0 {
		msg(gettext_(no_lines_msg))
		return
	} else {
		eol_size = 1

		if VIsual_active != 0 {
			if f11_lt_pos(VIsual, curwin.w_cursor) {
				min_pos = VIsual
				max_pos = curwin.w_cursor
			} else {
				min_pos = curwin.w_cursor
				max_pos = VIsual
			}
			if p_sel.Get() == 'e' && max_pos.col > 0 {
				max_pos.col--
			}

			if VIsual_mode == Ctrl_V {
				oparg.is_VIsual = 1
				oparg.block_mode = TRUE
				oparg.op_type = OP_NOP
				getvcols(curwin, &min_pos, &max_pos, &oparg.start_vcol, &oparg.end_vcol, 0)
				if curwin.w_curswant == MAXCOL {
					oparg.end_vcol = MAXCOL
				}
				if oparg.end_vcol < oparg.start_vcol {
					oparg.end_vcol += oparg.start_vcol
					oparg.start_vcol = oparg.end_vcol - oparg.start_vcol
					oparg.end_vcol -= oparg.start_vcol
				}
			}
			line_count_selected = max_pos.lnum - min_pos.lnum + 1
		}

		for lnum = 1; lnum <= curbuf.b_ml.ml_line_count; lnum++ {
			if byte_count > last_check {
				ui_breakcheck()
				if got_int != 0 {
					return
				}
				last_check = byte_count + 100000
			}

			if VIsual_active != 0 && lnum >= min_pos.lnum && lnum <= max_pos.lnum {
				var s Ptr[byte] = Ptr[byte]{}
				var len_ int64 = 0

				switch VIsual_mode {
				case Ctrl_V:
					virtual_op = virtual_active()
					block_prep(&oparg, &bd, lnum, 0)
					virtual_op = MAYBE
					s = bd.textstart
					len_ = int64(bd.textlen)
				case 'V':
					s = ml_get(lnum)
					len_ = MAXCOL
				case 'v':
					{
						var start_col colnr_T
						if lnum == min_pos.lnum {
							start_col = min_pos.col
						} else {
							start_col = 0
						}
						var end_col colnr_T
						if lnum == max_pos.lnum {
							end_col = max_pos.col - start_col + 1
						} else {
							end_col = MAXCOL
						}

						s = ml_get(lnum).Add(int(start_col))
						len_ = int64(end_col)
					}
				}
				if !s.Nil() {
					byte_count_cursor += line_count_info(s, &word_count_cursor, &char_count_cursor, len_, eol_size)
				}
			} else {
				if lnum == curwin.w_cursor.lnum {
					word_count_cursor += word_count
					char_count_cursor += char_count
					byte_count_cursor = byte_count + line_count_info(ml_get(lnum), &word_count_cursor, &char_count_cursor, varnumber_T(curwin.w_cursor.col+1), eol_size)
				}
			}
			byte_count += line_count_info(ml_get(lnum), &word_count, &char_count, varnumber_T(MAXCOL), eol_size)
		}

		if VIsual_active != 0 {
			if VIsual_mode == Ctrl_V && curwin.w_curswant < MAXCOL {
				getvcols(curwin, &min_pos, &max_pos, &min_pos.col, &max_pos.col, 0)
				vim_snprintf(buf1, 50, gettext_(S("%ld Cols; ")), int64(oparg.end_vcol-oparg.start_vcol+1))
			} else {
				buf1.Set(0, NUL)
			}

			if char_count_cursor == byte_count_cursor && char_count == byte_count {
				vim_snprintf(IObuff, (1024 + 1), gettext_(S("Selected %s%ld of %ld Lines; %lld of %lld Words; %lld of %lld Bytes")), buf1, line_count_selected, int64(curbuf.b_ml.ml_line_count), word_count_cursor, word_count, byte_count_cursor, byte_count)
			} else {
				vim_snprintf(IObuff, (1024 + 1), gettext_(S("Selected %s%ld of %ld Lines; %lld of %lld Words; %lld of %lld Chars; %lld of %lld Bytes")), buf1, line_count_selected, int64(curbuf.b_ml.ml_line_count), word_count_cursor, word_count, char_count_cursor, char_count, byte_count_cursor, byte_count)
			}
		} else {
			p = ml_get_curline()
			validate_virtcol()
			col_print(buf1, 50, int32(curwin.w_cursor.col)+1, int32(curwin.w_virtcol)+1)
			{
				vcol := linetabsize_str(p)

				col_print(buf2, 40, ml_get_curline_len(), vcol)
			}

			if char_count_cursor == byte_count_cursor && char_count == byte_count {
				vim_snprintf(IObuff, (1024 + 1), gettext_(S("Col %s of %s; Line %ld of %ld; Word %lld of %lld; Byte %lld of %lld")), buf1, buf2, int64(curwin.w_cursor.lnum), int64(curbuf.b_ml.ml_line_count), word_count_cursor, word_count, byte_count_cursor, byte_count)
			} else {
				vim_snprintf(IObuff, (1024 + 1), gettext_(S("Col %s of %s; Line %ld of %ld; Word %lld of %lld; Char %lld of %lld; Byte %lld of %lld")), buf1, buf2, int64(curwin.w_cursor.lnum), int64(curbuf.b_ml.ml_line_count), word_count_cursor, word_count, char_count_cursor, char_count, byte_count_cursor, byte_count)
			}
		}

		p = p_shm
		p_shm = S("")
		msg(IObuff)
		p_shm = p
	}
}

func op_colon(oap *S_oparg_S) {
	stuffcharReadbuff(':')
	if oap.is_VIsual != 0 {
		stuffReadbuff(S("'<,'>"))
	} else {
		if oap.start.lnum == curwin.w_cursor.lnum {
			stuffcharReadbuff('.')
		} else {
			stuffnumReadbuff(int64(oap.start.lnum))
		}

		if oap.end.lnum != oap.start.lnum {
			stuffcharReadbuff(',')
			if oap.end.lnum == curwin.w_cursor.lnum {
				stuffcharReadbuff('.')
			} else if oap.end.lnum == curbuf.b_ml.ml_line_count {
				stuffcharReadbuff('$')
			} else if oap.start.lnum == curwin.w_cursor.lnum {
				stuffReadbuff(S(".+"))
				stuffnumReadbuff(int64(oap.line_count) - 1)
			} else {
				stuffnumReadbuff(int64(oap.end.lnum))
			}
		}
	}
}

func get_op_vcol(oap *S_oparg_S, redo_VIsual_vcol colnr_T, initial int32) {
	var start colnr_T
	var end colnr_T

	if VIsual_mode != Ctrl_V || (initial == 0 && oap.end.col < curwin.w_width) {
		return
	}

	oap.block_mode = TRUE

	mb_adjustpos(curwin.w_buffer, &oap.end)

	getvvcol(curwin, &oap.start, &oap.start_vcol, nil, &oap.end_vcol, 0)

	if redo_VIsual_busy == 0 {
		getvvcol(curwin, &oap.end, &start, nil, &end, 0)

		if start < oap.start_vcol {
			oap.start_vcol = start
		}
		if end > oap.end_vcol {
			if initial != 0 && p_sel.Get() == 'e' && start >= 1 && start-1 >= oap.end_vcol {
				oap.end_vcol = start - 1
			} else {
				oap.end_vcol = end
			}
		}
	}

	if curwin.w_curswant == MAXCOL {
		curwin.w_cursor.col = MAXCOL
		oap.end_vcol = 0
		for curwin.w_cursor.lnum = oap.start.lnum; curwin.w_cursor.lnum <= oap.end.lnum; curwin.w_cursor.lnum++ {
			getvvcol(curwin, &curwin.w_cursor, nil, nil, &end, 0)
			if end > oap.end_vcol {
				oap.end_vcol = end
			}
		}
	} else if redo_VIsual_busy != 0 {
		oap.end_vcol = oap.start_vcol + redo_VIsual_vcol - 1
	}
	curwin.w_cursor.lnum = oap.end.lnum
	coladvance(oap.end_vcol)
	oap.end = curwin.w_cursor

	curwin.w_cursor = oap.start
	coladvance(oap.start_vcol)
	oap.start = curwin.w_cursor
}

func is_ex_cmdchar(cap_ *S_cmdarg_S) int32 {
	return B2i(cap_.cmdchar == ':' || cap_.cmdchar == (-((KS_EXTRA) + (int32(KE_COMMAND) << 8))) || cap_.cmdchar == (-((KS_EXTRA) + (int32(KE_SCRIPT_COMMAND) << 8))))
}

func init() { do_pending_operator_redo_VIsual = redo_VIsual_T{NUL, 0, 0, 0, 0} }

func do_pending_operator(cap_ *S_cmdarg_S, old_col int32, gui_yank int32) {
	oap := cap_.oap
	var old_cursor pos_T
	var empty_region_error int32
	var restart_edit_save int32

	var include_line_break int32 = FALSE

	old_cursor = curwin.w_cursor

	if (finish_op != 0 || VIsual_active != 0) && oap.op_type != OP_NOP {
		redo_yank := B2i(!vim_strchr(p_cpo, CPO_YANK).Nil() && gui_yank == 0)

		oap.is_VIsual = VIsual_active
		if oap.motion_force == 'V' {
			oap.motion_type = MLINE
		} else if oap.motion_force == 'v' {
			if oap.motion_type == MLINE {
				oap.inclusive = FALSE
			} else if oap.motion_type == MCHAR {
				oap.inclusive = B2i(oap.inclusive == 0)
			}
			oap.motion_type = MCHAR
		} else if oap.motion_force == Ctrl_V {
			if VIsual_active == 0 {
				VIsual_active = TRUE
				VIsual = oap.start
			}
			VIsual_mode = Ctrl_V
			VIsual_select = FALSE
			VIsual_reselect = FALSE
		}

		if (redo_yank != 0 || oap.op_type != OP_YANK) && ((VIsual_active == 0 || oap.motion_force != 0) || (VIsual_active != 0 && is_ex_cmdchar(cap_) != 0 && oap.op_type != OP_COLON)) && cap_.cmdchar != 'D' {
			prep_redo(oap.regname, cap_.count0, get_op_char(oap.op_type), get_extra_op_char(oap.op_type), oap.motion_force, cap_.cmdchar, cap_.nchar)
			if cap_.cmdchar == '/' || cap_.cmdchar == '?' {
				if vim_strchr(p_cpo, CPO_REDO).Nil() {
					AppendToRedobuffLit(cap_.searchbuf, -1)
				}
				AppendToRedobuff(S("\012"))
			} else if is_ex_cmdchar(cap_) != 0 {
				if repeat_cmdline.Nil() {
					ResetRedobuff()
				} else {
					if cap_.cmdchar == ':' {
						AppendToRedobuffLit(repeat_cmdline, -1)
					} else {
						AppendToRedobuffSpec(repeat_cmdline)
					}
					AppendToRedobuff(S("\012"))
					repeat_cmdline = Ptr[byte]{}
				}
			}
		}

		if redo_VIsual_busy != 0 {
			oap.start = curwin.w_cursor
			curwin.w_cursor.lnum += do_pending_operator_redo_VIsual.rv_line_count - 1
			if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
				curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
			}
			VIsual_mode = do_pending_operator_redo_VIsual.rv_mode
			if do_pending_operator_redo_VIsual.rv_vcol == MAXCOL || VIsual_mode == 'v' {
				if VIsual_mode == 'v' {
					if do_pending_operator_redo_VIsual.rv_line_count <= 1 {
						validate_virtcol()
						curwin.w_curswant = curwin.w_virtcol + do_pending_operator_redo_VIsual.rv_vcol - 1
					} else {
						curwin.w_curswant = do_pending_operator_redo_VIsual.rv_vcol
					}
				} else {
					curwin.w_curswant = MAXCOL
				}
				coladvance(curwin.w_curswant)
			}
			cap_.count0 = do_pending_operator_redo_VIsual.rv_count
			if do_pending_operator_redo_VIsual.rv_count != 0 {
				cap_.count1 = do_pending_operator_redo_VIsual.rv_count
			} else {
				cap_.count1 = 1
			}
		} else if VIsual_active != 0 {
			if gui_yank == 0 {
				curbuf.b_visual.vi_start = VIsual
				curbuf.b_visual.vi_end = curwin.w_cursor
				curbuf.b_visual.vi_mode = VIsual_mode
				restore_visual_mode()
				curbuf.b_visual.vi_curswant = curwin.w_curswant
			}

			if VIsual_select != 0 && VIsual_mode == 'V' && cap_.oap.op_type != OP_DELETE {
				if f11_lt_pos(VIsual, curwin.w_cursor) {
					VIsual.col = 0
					curwin.w_cursor.col = ml_get_len(curwin.w_cursor.lnum)
				} else {
					curwin.w_cursor.col = 0
					VIsual.col = ml_get_len(VIsual.lnum)
				}
				VIsual_mode = 'v'
			} else if VIsual_mode == 'v' {
				include_line_break = unadjust_for_sel()
			}

			oap.start = VIsual
			if VIsual_mode == 'V' {
				oap.start.col = 0
				oap.start.coladd = 0
			}
		}

		if f11_lt_pos(oap.start, curwin.w_cursor) {
			oap.end = curwin.w_cursor
			curwin.w_cursor = oap.start

			curwin.w_valid &= ^VALID_VIRTCOL
		} else {
			oap.end = oap.start
			oap.start = curwin.w_cursor
		}

		check_pos(curwin.w_buffer, &oap.end)
		oap.line_count = oap.end.lnum - oap.start.lnum + 1

		virtual_op = virtual_active()

		if VIsual_active != 0 || redo_VIsual_busy != 0 {
			get_op_vcol(oap, do_pending_operator_redo_VIsual.rv_vcol, TRUE)

			if redo_VIsual_busy == 0 && gui_yank == 0 {
				resel_VIsual_mode = VIsual_mode
				if curwin.w_curswant == MAXCOL {
					resel_VIsual_vcol = MAXCOL
				} else {
					if VIsual_mode != Ctrl_V {
						getvvcol(curwin, &oap.end, nil, nil, &oap.end_vcol, 0)
					}
					if VIsual_mode == Ctrl_V || oap.line_count <= 1 {
						if VIsual_mode != Ctrl_V {
							getvvcol(curwin, &oap.start, &oap.start_vcol, nil, nil, 0)
						}
						resel_VIsual_vcol = oap.end_vcol - oap.start_vcol + 1
					} else {
						resel_VIsual_vcol = oap.end_vcol
					}
				}
				resel_VIsual_line_count = oap.line_count
			}

			if (redo_yank != 0 || oap.op_type != OP_YANK) && oap.op_type != OP_COLON && oap.motion_force == NUL {
				if cap_.cmdchar == 'g' && (cap_.nchar == 'n' || cap_.nchar == 'N') {
					prep_redo(oap.regname, cap_.count0, get_op_char(oap.op_type), get_extra_op_char(oap.op_type), oap.motion_force, cap_.cmdchar, cap_.nchar)
				} else if is_ex_cmdchar(cap_) == 0 {
					opchar := get_op_char(oap.op_type)
					extra_opchar := get_extra_op_char(oap.op_type)
					var nchar int32
					if oap.op_type == OP_REPLACE {
						nchar = cap_.nchar
					} else {
						nchar = NUL
					}

					if nchar == (-1) {
						nchar = CAR
					} else if nchar == (-2) {
						nchar = NL
					}

					if opchar == 'g' && extra_opchar == '@' {
						prep_redo_num2(oap.regname, 0, NUL, 'v', cap_.count0, opchar, extra_opchar, nchar)
					} else {
						prep_redo(oap.regname, 0, NUL, 'v', opchar, extra_opchar, nchar)
					}
				}
				if redo_VIsual_busy == 0 {
					do_pending_operator_redo_VIsual.rv_mode = resel_VIsual_mode
					do_pending_operator_redo_VIsual.rv_vcol = resel_VIsual_vcol
					do_pending_operator_redo_VIsual.rv_line_count = resel_VIsual_line_count
					do_pending_operator_redo_VIsual.rv_count = cap_.count0
					do_pending_operator_redo_VIsual.rv_arg = cap_.arg
				}
			}

			if oap.motion_force == NUL || oap.motion_type == MLINE {
				oap.inclusive = TRUE
			}
			if VIsual_mode == 'V' {
				oap.motion_type = MLINE
			} else {
				oap.motion_type = MCHAR
				if VIsual_mode != Ctrl_V && ml_get_pos(&oap.end).Get() == NUL && (include_line_break != 0 || virtual_op == 0) {
					oap.inclusive = FALSE
					if p_sel.Get() != 'o' && op_on_lines(oap.op_type) == 0 && oap.end.lnum < curbuf.b_ml.ml_line_count {
						oap.end.lnum++
						oap.end.col = 0
						oap.end.coladd = 0
						oap.line_count++
					}
				}
			}

			redo_VIsual_busy = FALSE

			if gui_yank == 0 {
				VIsual_active = FALSE
				mouse_dragging = 0
				may_clear_cmdline()
				if (oap.op_type == OP_YANK || oap.op_type == OP_COLON) && oap.motion_force == NUL {
					redraw_curbuf_later(UPD_INVERTED)
				}
			}
		}

		if oap.inclusive != 0 {
			var l int32

			l = utfc_ptr2len(ml_get_pos(&oap.end))
			if l > 1 {
				oap.end.col += l - 1
			}
		}
		curwin.w_set_curswant = true

		oap.empty = B2i(oap.motion_type == MCHAR && (oap.inclusive == 0 || (oap.op_type == OP_YANK && gchar_pos(&oap.end) == NUL)) && f11_equal_pos(oap.start, oap.end) && !(virtual_op != 0 && oap.start.coladd != oap.end.coladd))
		empty_region_error = B2i(oap.empty != 0 && !vim_strchr(p_cpo, CPO_EMPTYREGION).Nil())

		if oap.is_VIsual != 0 && (oap.empty != 0 || curbuf.b_p_ma == 0) {
			redraw_curbuf_later(UPD_INVERTED)
		}

		if oap.motion_type == MCHAR && oap.inclusive == FALSE && (cap_.retval&CA_NO_ADJ_OP_END) == 0 && oap.end.col == 0 && (oap.is_VIsual == 0 || p_sel.Get() == 'o') && oap.block_mode == 0 && oap.line_count > 1 {
			oap.end_adjusted = TRUE
			oap.line_count--
			oap.end.lnum--
			if inindent(0) != 0 {
				oap.motion_type = MLINE
			} else {
				oap.end.col = ml_get_len(oap.end.lnum)
				if oap.end.col != 0 {
					oap.end.col--
					oap.inclusive = TRUE
				}
			}
		} else {
			oap.end_adjusted = FALSE
		}

		switch oap.op_type {
		case OP_LSHIFT, OP_RSHIFT:
			var amount int32
			if oap.is_VIsual != 0 {
				amount = int32(cap_.count1)
			} else {
				amount = 1
			}
			op_shift(oap, TRUE, amount)

		case OP_JOIN_NS, OP_JOIN:
			if oap.line_count < 2 {
				oap.line_count = 2
			}
			if curwin.w_cursor.lnum+oap.line_count-1 > curbuf.b_ml.ml_line_count {
				beep_flush()
			} else {
				do_join(oap.line_count, B2i(oap.op_type == OP_JOIN), TRUE, TRUE, TRUE)
			}

		case OP_DELETE:
			VIsual_reselect = FALSE
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				op_delete(oap)
			}

		case OP_YANK:
			if empty_region_error != 0 {
				if gui_yank == 0 {
					vim_beep(BO_OPER)
					CancelRedo()
				}
			} else {
				oap.excl_tr_ws = B2i(cap_.cmdchar == 'z')
				op_yank(oap, FALSE, B2i(gui_yank == 0))
			}
			check_cursor_col()

		case OP_CHANGE:
			VIsual_reselect = FALSE
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				if p_im != 0 || KeyTyped == 0 {
					restart_edit_save = restart_edit
				} else {
					restart_edit_save = 0
				}
				restart_edit = 0
				curbuf.b_last_changedtick_i = curbuf.b_changedtick

				if op_change(oap) != 0 {
					cap_.retval |= CA_COMMAND_BUSY
				}
				if restart_edit == 0 {
					restart_edit = restart_edit_save
				}
			}

		case OP_COLON:
			op_colon(oap)

		case OP_TILDE, OP_UPPER, OP_LOWER:
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				op_tilde(oap)
			}
			check_cursor_col()

		case OP_INSERT, OP_APPEND:
			VIsual_reselect = FALSE
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				restart_edit_save = restart_edit
				restart_edit = 0
				curbuf.b_last_changedtick_i = curbuf.b_changedtick

				op_insert(oap, cap_.count1)

				if restart_edit == 0 {
					restart_edit = restart_edit_save
				} else {
					cap_.retval |= CA_COMMAND_BUSY
				}
			}

		case OP_REPLACE:
			VIsual_reselect = FALSE
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				op_replace(oap, cap_.nchar)
			}

		case OP_NR_ADD, OP_NR_SUB:
			if empty_region_error != 0 {
				vim_beep(BO_OPER)
				CancelRedo()
			} else {
				VIsual_active = TRUE
				op_addsub(oap, cap_.count1, do_pending_operator_redo_VIsual.rv_arg)
				VIsual_active = FALSE
			}
			check_cursor_col()
		default:
			clearopbeep(oap)
		}
		virtual_op = MAYBE
		if gui_yank == 0 {
			if p_sol == 0 && oap.motion_type == MLINE && oap.end_adjusted == 0 && (oap.op_type == OP_LSHIFT || oap.op_type == OP_RSHIFT || oap.op_type == OP_DELETE) {
				curwin.w_curswant = old_col
				coladvance(curwin.w_curswant)
			}
		} else {
			curwin.w_cursor = old_cursor
		}
		oap.block_mode = FALSE
		clearop(oap)
		motion_force = NUL
	}
}

func pbyte(lp pos_T, c int32) {
	p := ml_get_buf(curbuf, lp.lnum, TRUE)
	len_ := int32(curbuf.b_ml.ml_line_len)

	if lp.col >= len_ {
		if len_ > 1 {
			lp.col = len_ - 2
		} else {
			lp.col = 0
		}
	}
	p.Add(int(lp.col)).Put(byte(c))
}

func set_init_expand_env() {
	var opt_idx int32
	var p Ptr[byte]

	for opt_idx = 0; istermoption_idx(opt_idx) == 0; opt_idx++ {
		if (options.At(int(opt_idx)).flags&P_GETTEXT) != 0 && optvar_is_null(options.At(int(opt_idx)).var_) == 0 {
			p = gettext_(options.At(int(opt_idx)).var_.ov_str.Get())
		} else {
			p = option_expand(opt_idx, Ptr[byte]{})
		}
		if !p.Nil() {
			p = vim_strsave(p)
		}
		if !p.Nil() {
			options.At(int(opt_idx)).var_.ov_str.Put(p)
			options.Ref(int(opt_idx)).def_str[VI_DEFAULT] = p
			options.Ref(int(opt_idx)).flags |= P_DEF_ALLOCED
		}
	}
}

func set_init_1() {
	p_cp = FALSE

	km_startsel = TRUE
	km_stopsel = FALSE

	set_options_default(0)

	curbuf.b_p_initialized = true
	curbuf.b_p_ul = (-123456)
	check_buf_options(curbuf)
	check_win_options(curwin)
	check_options()

	didset_options()

	mb_init()

	set_init_expand_env()

	didset_options2()

}

func set_option_default(opt_idx int32, opt_flags int32, compatible int32) {
	var varp optvar_T
	var dvi int32
	var flags long_u
	var flagsp *long_u
	both := B2i((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0)

	var scope int32
	if both != 0 {
		scope = OPT_LOCAL
	} else {
		scope = opt_flags
	}
	varp = get_varp_scope(options.Add(int(opt_idx)), scope)
	flags = options.At(int(opt_idx)).flags
	if optvar_is_null(varp) == 0 {
		if (flags&P_VI_DEF) != 0 || compatible != 0 {
			dvi = VI_DEFAULT
		} else {
			dvi = VIM_DEFAULT
		}
		if flags&P_STRING != 0 {
			if options.At(int(opt_idx)).indir != PV_NONE {
				set_string_option_direct(Ptr[byte]{}, opt_idx, options.At(int(opt_idx)).def_str[dvi], opt_flags, 0)
			} else {
				if (opt_flags&OPT_FREE) != 0 && (flags&P_ALLOCED) != 0 {
					free_string_option(varp.ov_str.Get())
				}
				varp.ov_str.Put(options.At(int(opt_idx)).def_str[dvi])
				options.Ref(int(opt_idx)).flags &= ^long_u(P_ALLOCED)
			}
		} else if flags&P_NUM != 0 {
			if options.At(int(opt_idx)).indir == idopt_T(PV_WIN+int32(WV_SCROLL)) {
				win_comp_scroll(curwin)
			} else {
				def_val := options.At(int(opt_idx)).def_num[dvi]

				if varp.ov_long == &curwin.w_onebuf_opt.wo_so || varp.ov_long == &curwin.w_onebuf_opt.wo_siso || varp.ov_long == &curwin.w_onebuf_opt.wo_sop {
					*varp.ov_long = -1
				} else {
					*varp.ov_long = def_val
				}
				if both != 0 {
					*get_varp_scope(options.Add(int(opt_idx)), OPT_GLOBAL).ov_long = def_val
				}
			}
		} else {
			*varp.ov_int = int32(options.At(int(opt_idx)).def_num[dvi])
			if both != 0 {
				*get_varp_scope(options.Add(int(opt_idx)), OPT_GLOBAL).ov_int = *varp.ov_int
			}
		}

		flagsp = &options.Ref(int(opt_idx)).flags
		*flagsp = *flagsp & ^long_u(P_INSECURE)
		if both != 0 {
			flagsp = &options.Ref(int(opt_idx)).flags
			*flagsp = *flagsp & ^long_u(P_INSECURE)
		}
	}

}

func set_options_default(opt_flags int32) {
	var i int32
	var wp *S_window_S

	for i = 0; istermoption_idx(i) == 0; i++ {
		if (options.At(int(i)).flags & P_NODEFAULT) == 0 {
			set_option_default(i, opt_flags, p_cp)
		}
	}

	wp = curwin
	win_comp_scroll(wp)
}

func set_string_default_esc(name Ptr[byte], val Ptr[byte], escape int32) {
	var p Ptr[byte]
	var opt_idx int32

	if escape != 0 && !vim_strchr(val, ' ').Nil() {
		p = vim_strsave_escaped(val, S(" "))
	} else {
		p = vim_strsave(val)
	}
	if p.Nil() {
		return
	}

	opt_idx = findoption(name)
	if opt_idx < 0 {
		return
	}

	options.Ref(int(opt_idx)).def_str[VI_DEFAULT] = p
	options.Ref(int(opt_idx)).flags |= P_DEF_ALLOCED
}

func set_string_default(name Ptr[byte], val Ptr[byte]) {
	set_string_default_esc(name, val, FALSE)
}

func find_dup_item(origval Ptr[byte], newval Ptr[byte], newvallen usize, flags long_u) Ptr[byte] {
	var bs int32 = 0
	var s Ptr[byte]

	if origval.Nil() {
		return Ptr[byte]{}
	}

	for s = origval; s.Get() != NUL; s = s.Add(1) {
		if ((flags&P_COMMA) == 0 || s == origval || (s.At(-1) == ',' && (bs&1) == 0)) && musl_strncmp(s, newval, newvallen) == 0 && ((flags&P_COMMA) == 0 || s.At(int(newvallen)) == ',' || s.At(int(newvallen)) == NUL) {
			return s
		}
		if (s.Gt(origval.Add(1)) && s.At(-1) == '\\' && s.At(-2) != ',') || (s == origval.Add(1) && s.At(-1) == '\\') {
			bs++
		} else {
			bs = 0
		}
	}
	return Ptr[byte]{}
}

func set_number_default(name Ptr[byte], val int64) {
	var opt_idx int32

	opt_idx = findoption(name)
	if opt_idx >= 0 {
		options.Ref(int(opt_idx)).def_num[VI_DEFAULT] = val
	}
}

func set_init_2() {
	var idx int32

	idx = findoption(S("scroll"))
	if idx >= 0 && (options.At(int(idx)).flags&P_WAS_SET) == 0 {
		set_option_default(idx, OPT_LOCAL, p_cp)
	}
	comp_col()

	if option_was_set(S("window")) == 0 {
		p_window = Rows - 1
	}
	set_number_default(S("window"), Rows-1)

	idx = findoption(S("bg"))
	if idx >= 0 && (options.At(int(idx)).flags&P_WAS_SET) == 0 && term_bg_default().Get() == 'd' {
		set_string_option_direct(Ptr[byte]{}, idx, S("dark"), OPT_FREE, 0)
		options.Ref(int(idx)).flags &= ^long_u(P_WAS_SET)
	}

}

func ex_set(eap *S_exarg) {
	var flags int32 = 0

	{
		if eap.forceit != 0 {
			flags |= OPT_ONECOLUMN
		}
		do_set(eap.arg, flags)
	}
}

func get_option_prefix(argp *Ptr[byte]) set_prefix_T {
	var prefix int32 = PREFIX_NONE
	arg := *argp

	if musl_strncmp(arg, S("no"), 2) == 0 && musl_strncmp(arg, S("novice"), 6) != 0 {
		prefix = PREFIX_NO
		arg = arg.Add(2)
	} else if musl_strncmp(arg, S("inv"), 3) == 0 {
		prefix = PREFIX_INV
		arg = arg.Add(3)
	}

	*argp = arg
	return prefix
}

func parse_option_name(arg Ptr[byte], opt_idxp *int32, lenp *int32, keyp *int32) int32 {
	var key int32 = 0
	var len_ int32
	var opt_idx int32

	if arg.Get() == '<' {
		opt_idx = -1
		if arg.At(1) == 't' && arg.At(2) == '_' && arg.At(3) != 0 && arg.At(4) != 0 {
			len_ = 5
		} else {
			len_ = 1
			for arg.At(int(len_)) != NUL && arg.At(int(len_)) != '>' {
				len_++
			}
		}
		if arg.At(int(len_)) != '>' {
			return FAIL
		}

		arg.Set(int(len_), NUL)
		if arg.At(1) == 't' && arg.At(2) == '_' {
			opt_idx = findoption(arg.Add(1))
		}
		arg.Set(int(len_), '>')
		len_++
		if opt_idx == -1 {
			key = find_key_option(arg.Add(1), TRUE)
		}
	} else {
		var nextchar int32

		len_ = 0
		if arg.At(0) == 't' && arg.At(1) == '_' && arg.At(2) != 0 && arg.At(3) != 0 {
			len_ = 4
		} else {
			for f11_ascii_isalpha(int32(arg.At(int(len_)))) || uint32(arg.At(int(len_)))-'0' < 10 || arg.At(int(len_)) == '_' {
				len_++
			}
		}
		nextchar = int32(arg.At(int(len_)))
		arg.Set(int(len_), NUL)
		opt_idx = findoption(arg)
		arg.Set(int(len_), byte(nextchar))
		if opt_idx == -1 {
			key = find_key_option(arg, FALSE)
		}
	}

	*keyp = key
	*lenp = len_
	*opt_idxp = opt_idx

	return OK
}

func get_opt_op(arg Ptr[byte]) set_op_T {
	var op set_op_T = OP_NONE

	if arg.Get() != NUL && arg.At(1) == '=' {
		if arg.Get() == '+' {
			op = OP_ADDING
		} else if arg.Get() == '^' {
			op = OP_PREPENDING
		} else if arg.Get() == '-' {
			op = OP_REMOVING
		}
	}

	return op
}

func validate_opt_idx(opt_idx int32, opt_flags int32, flags long_u, errmsg *Ptr[byte], prefix set_prefix_T) int32 {
	if (opt_flags&OPT_WINONLY) != 0 && (opt_idx < 0 || options.At(int(opt_idx)).var_.ov_win == 0) {
		return FAIL
	}

	if (opt_flags&OPT_NOWIN) != 0 && opt_idx >= 0 && options.At(int(opt_idx)).var_.ov_win != 0 {
		return FAIL
	}

	return OK
}

func stropt_get_default_val(opt_idx int32, varp optvar_T, flags int32, cp_val int32) Ptr[byte] {
	var newval Ptr[byte]

	var dvi int32
	if (flags&P_VI_DEF) != 0 || cp_val != 0 {
		dvi = VI_DEFAULT
	} else {
		dvi = VIM_DEFAULT
	}
	newval = options.At(int(opt_idx)).def_str[dvi]
	if varp.ov_str == Addr(&p_bg) {
		newval = term_bg_default()
	}

	if newval.Nil() {
		newval = empty_option
	} else {
		s := option_expand(opt_idx, newval)
		if s.Nil() {
			s = newval
		}
		newval = vim_strsave(s)
	}

	return newval
}

func opt_backspace_nr2str(varp optvar_T, origval_p *Ptr[byte], origval_l_p *Ptr[byte], origval_g_p *Ptr[byte], oldval_p *Ptr[byte]) {
	i := int32(getdigits(varp.ov_str))

	switch i {
	case 0:
		varp.ov_str.Put(empty_option)
	case 1:
		varp.ov_str.Put(vim_strnsave(S("indent,eol"), 10))
	case 2:
		varp.ov_str.Put(vim_strnsave(S("indent,eol,start"), 16))
	case 3:
		varp.ov_str.Put(vim_strnsave(S("indent,eol,nostop"), 17))
	}
	if *origval_p == *oldval_p {
		*origval_p = varp.ov_str.Get()
	}
	if *origval_l_p == *oldval_p {
		*origval_l_p = varp.ov_str.Get()
	}
	if *origval_g_p == *oldval_p {
		*origval_g_p = varp.ov_str.Get()
	}
	*oldval_p = varp.ov_str.Get()
}

func opt_whichwrap_nr2str(argp Ptr[Ptr[byte]], whichwrap Ptr[byte]) Ptr[byte] {
	var len_ usize = 0

	whichwrap.Put(NUL)
	i := int32(getdigits(argp))
	if i&1 != 0 {
		musl_strcpy(whichwrap, S("b,"))
		len_ += 2
	}
	if i&2 != 0 {
		musl_strcpy(whichwrap.Add(int(len_)), S("s,"))
		len_ += 2
	}
	if i&4 != 0 {
		musl_strcpy(whichwrap.Add(int(len_)), S("h,l,"))
		len_ += 4
	}
	if i&8 != 0 {
		musl_strcpy(whichwrap.Add(int(len_)), S("<,>,"))
		len_ += 4
	}
	if i&16 != 0 {
		musl_strcpy(whichwrap.Add(int(len_)), S("[,],"))
		len_ += 4
	}
	if whichwrap.Get() != NUL {
		whichwrap.Set(int(len_-1), NUL)
	}

	return whichwrap
}

func stropt_copy_value(origval Ptr[byte], argp *Ptr[byte], op set_op_T, flags int32) Ptr[byte] {
	arg := *argp
	var newlen uint32
	var newval Ptr[byte]
	var s Ptr[byte] = Ptr[byte]{}

	newlen = uint32(musl_strlen(arg)) + 1
	if op != OP_NONE {
		newlen += uint32(musl_strlen(origval)) + 1
	}
	newval = Alloc(int(newlen))
	s = newval

	for arg.Get() != NUL && !(arg.Get() == ' ' || arg.Get() == '\t') {
		var i int32

		if arg.Get() == '\\' && arg.At(1) != NUL {
			arg = arg.Add(1)
		}
		i = utfc_ptr2len(arg)
		if i > 1 {
			Memmove(s, arg, int(usize(i)))
			arg = arg.Add(int(i))
			s = s.Add(int(i))
		} else {
			s.Put(arg.Get())
			s = s.Add(1)
			arg = arg.Add(1)
		}
	}
	s.Put(NUL)

	*argp = arg
	return newval
}

func stropt_expand_envvar(opt_idx int32, origval Ptr[byte], newval Ptr[byte], op set_op_T) Ptr[byte] {
	s := option_expand(opt_idx, newval)
	if s.Nil() {
		return newval
	}

	newlen := uint32(musl_strlen(s)) + 1
	if op != OP_NONE {
		newlen += uint32(musl_strlen(origval)) + 1
	}

	newval = Alloc(int(newlen))

	musl_strcpy(newval, s)

	return newval
}

func stropt_concat_with_comma(origval Ptr[byte], newval Ptr[byte], op set_op_T, flags int32) {
	var len_ int32 = 0

	comma := B2i((flags&P_COMMA) != 0 && origval.Get() != NUL && newval.Get() != NUL)
	if op == OP_ADDING {
		len_ = int32(musl_strlen(origval))
		if comma != 0 && len_ > 1 && (flags&P_ONECOMMA) == P_ONECOMMA && origval.At(int(len_-1)) == ',' && origval.At(int(len_-2)) != '\\' {
			len_--
		}
		Memmove(newval.Add(int(len_+comma)), newval, int(musl_strlen(newval)+1))
		Memmove(newval, origval, int(usize(len_)))
	} else {
		len_ = int32(musl_strlen(newval))
		Memmove(newval.Add(int(len_+comma)), origval, int(musl_strlen(origval)+1))
	}
	if comma != 0 {
		newval.Set(int(len_), ',')
	}
}

func stropt_remove_val(origval Ptr[byte], newval Ptr[byte], flags int32, strval Ptr[byte], len_ int32) {
	musl_strcpy(newval, origval)
	if strval.Get() != 0 {
		if flags&P_COMMA != 0 {
			if strval == origval {
				if strval.At(int(len_)) == ',' {
					len_++
				}
			} else {
				strval = strval.Add(-1)
				len_++
			}
		}
		Memmove(newval.Add(strval.Sub(origval)), strval.Add(int(len_)), int(musl_strlen(strval.Add(int(len_)))+1))
	}
}

func find_key_item(src Ptr[byte], key Ptr[byte], keylen int32, itemlenp *int32) Ptr[byte] {
	p := src

	for p.Get() != NUL {
		if (p == src || p.At(-1) == ',') && musl_strncmp(p, key, usize(keylen)) == 0 {
			end := vim_strchr(p, ',')
			if end.Nil() {
				end = p.Add(int(musl_strlen(p)))
			}
			*itemlenp = int32(end.Sub(p))
			return p
		}
		p = p.Add(1)
	}
	return Ptr[byte]{}
}

func remove_comma_item(str Ptr[byte], item Ptr[byte], itemlen int32) {
	if item.At(int(itemlen)) == ',' {
		Memmove(item, item.Add(int(itemlen+1)), int(musl_strlen(item.Add(int(itemlen+1)))+1))
	} else if item.Gt(str) && item.At(-1) == ',' {
		Memmove(item.Add(-1), item.Add(int(itemlen)), int(musl_strlen(item.Add(int(itemlen)))+1))
	} else {
		item.Put(NUL)
	}
}

func remove_key_item(str Ptr[byte], key Ptr[byte], keylen int32, skip Ptr[byte]) {
	var itemlen int32
	var found Ptr[byte]

	for {
		found = find_key_item(str, key, keylen, &itemlen)
		if found.Nil() {
			break
		}
		if found == skip {
			next := found.Add(int(itemlen))
			if next.Get() == ',' {
				next = next.Add(1)
			}
			found = find_key_item(next, key, keylen, &itemlen)
			if found.Nil() {
				break
			}
		}

		remove_comma_item(str, found, itemlen)
	}
}

func append_item(str Ptr[byte], item Ptr[byte], item_len int32) {
	len_ := int32(musl_strlen(str))

	if len_ > 0 {
		str.Set(int(len_), ',')
		len_++
	}
	Memmove(str.Add(int(len_)), item, int(usize(item_len)))
	str.Set(int(len_+item_len), NUL)
}

func prepend_item(str Ptr[byte], item Ptr[byte], item_len int32) {
	len_ := int32(musl_strlen(str))
	var comma int32
	if len_ > 0 {
		comma = 1
	} else {
		comma = 0
	}

	Memmove(str.Add(int(item_len+comma)), str, int(usize(len_)+1))
	Memmove(str, item, int(usize(item_len)))
	if comma != 0 {
		str.Set(int(item_len), ',')
	}
}

func stropt_handle_keymatch(origval Ptr[byte], newval Ptr[byte], op set_op_T, flags int32) bool {
	var p Ptr[byte]
	var item_start Ptr[byte]

	if vim_strchr(newval, ':').Nil() && vim_strchr(newval, ',').Nil() {
		return false
	}

	newval_copy := vim_strsave(newval)
	if newval_copy.Nil() {
		return false
	}

	musl_strcpy(newval, origval)

	item_start = newval_copy
	for {
		p = vim_strchr(item_start, ',')
		var item_len int32
		if p.Nil() {
			item_len = int32(musl_strlen(item_start))
		} else {
			item_len = int32(p.Sub(item_start))
		}

		if item_len > 0 {
			colon := vim_strchr(item_start, ':')
			if !colon.Nil() && colon.Lt(item_start.Add(int(item_len))) {
				keylen := int32(colon.Sub(item_start)) + 1

				if op == OP_ADDING || op == OP_PREPENDING {
					var old_itemlen int32
					found := find_key_item(newval, item_start, keylen, &old_itemlen)
					if !found.Nil() {
						if old_itemlen == item_len && musl_strncmp(found, item_start, usize(item_len)) == 0 {
							remove_key_item(newval, item_start, keylen, found)
						} else {
							remove_key_item(newval, item_start, keylen, Ptr[byte]{})
							if op == OP_PREPENDING {
								prepend_item(newval, item_start, item_len)
							} else {
								append_item(newval, item_start, item_len)
							}
						}
					} else {
						if op == OP_PREPENDING {
							prepend_item(newval, item_start, item_len)
						} else {
							append_item(newval, item_start, item_len)
						}
					}
				} else if op == OP_REMOVING {
					remove_key_item(newval, item_start, keylen, Ptr[byte]{})
				}
			} else {
				if op == OP_ADDING || op == OP_PREPENDING {
					found := find_dup_item(newval, item_start, usize(item_len), P_COMMA)
					if found.Nil() {
						if op == OP_PREPENDING {
							prepend_item(newval, item_start, item_len)
						} else {
							append_item(newval, item_start, item_len)
						}
					}
				} else if op == OP_REMOVING {
					found := find_dup_item(newval, item_start, usize(item_len), P_COMMA)
					if !found.Nil() {
						remove_comma_item(newval, found, item_len)
					}
				}
			}
		}

		if p.Nil() {
			break
		}
		item_start = p.Add(1)
	}

	return true
}

func stropt_remove_dupflags(newval Ptr[byte], flags int32) {
	s := newval

	for s.Get() != 0 {
		if flags&P_ONECOMMA != 0 {
			if s.Get() != ',' && s.At(1) == ',' && !vim_strchr(s.Add(2), int32(s.Get())).Nil() {
				Memmove(s, s.Add(2), int(musl_strlen(s.Add(2))+1))
				continue
			}
		} else {
			if ((flags&P_COMMA) == 0 || s.Get() != ',') && !vim_strchr(s.Add(1), int32(s.Get())).Nil() {
				Memmove(s, s.Add(1), int(musl_strlen(s.Add(1))+1))
				continue
			}
		}
		s = s.Add(1)
	}
}

func stropt_get_newval(nextchar int32, opt_idx int32, argp *Ptr[byte], varp optvar_T, origval_arg *Ptr[byte], origval_l_arg *Ptr[byte], origval_g_arg *Ptr[byte], oldval_arg *Ptr[byte], op_arg *set_op_T, flags int32, cp_val int32) Ptr[byte] {
	arg := *argp
	origval := *origval_arg
	origval_l := *origval_l_arg
	origval_g := *origval_g_arg
	oldval := *oldval_arg
	op := *op_arg
	var save_arg Ptr[byte] = Ptr[byte]{}
	var newval Ptr[byte]
	var s Ptr[byte] = Ptr[byte]{}
	whichwrap := Mk[byte](80)

	if nextchar == '&' {
		newval = stropt_get_default_val(opt_idx, varp, flags, cp_val)
	} else {
		arg = arg.Add(1)

		if varp.ov_str == Addr(&p_bs) && uint32(varp.ov_str.Get().Get())-'0' < 10 {
			opt_backspace_nr2str(varp, &origval, &origval_l, &origval_g, &oldval)
		} else if varp.ov_str == Addr(&p_ww) && uint32(arg.Get())-'0' < 10 {
			t := opt_whichwrap_nr2str(Addr(&arg), whichwrap)
			save_arg = arg
			arg = t
		}
		newval = stropt_copy_value(origval, &arg, op, flags)

		if op == OP_NONE || (flags&P_COMMA) != 0 {
			newval = stropt_expand_envvar(opt_idx, origval, newval, op)
			if newval.Nil() {
				goto done
			}
		}

		if (flags&P_COMMA) != 0 && (int64(flags)&P_COLON) != 0 && op != OP_NONE && stropt_handle_keymatch(origval, newval, op, flags) {
		} else {
			var len_ int32 = 0
			if op == OP_REMOVING || (flags&P_NODUP) != 0 {
				len_ = int32(musl_strlen(newval))
				s = find_dup_item(origval, newval, usize(len_), long_u(flags))

				if (op == OP_ADDING || op == OP_PREPENDING) && !s.Nil() {
					op = OP_NONE
					musl_strcpy(newval, origval)
				}

				if s.Nil() {
					s = origval.Add(int(int32(musl_strlen(origval))))
				}
			}

			if op == OP_ADDING || op == OP_PREPENDING {
				stropt_concat_with_comma(origval, newval, op, flags)
			} else if op == OP_REMOVING {
				stropt_remove_val(origval, newval, flags, s, len_)
			}
		}

		if flags&P_FLAGLIST != 0 {
			stropt_remove_dupflags(newval, flags)
		}
	}

done:
	if !save_arg.Nil() {
		arg = save_arg
	}
	*argp = arg
	*origval_arg = origval
	*origval_l_arg = origval_l
	*origval_g_arg = origval_g
	*oldval_arg = oldval
	*op_arg = op

	return newval
}

func do_set_option_string(opt_idx int32, opt_flags int32, argp *Ptr[byte], nextchar int32, op_arg set_op_T, flags long_u, cp_val int32, varp_arg optvar_T, errbuf Ptr[byte], errbuflen usize, value_checked *int32, errmsg *Ptr[byte]) int32 {
	arg := *argp
	op := op_arg
	varp := varp_arg
	var oldval Ptr[byte] = Ptr[byte]{}
	var newval Ptr[byte]
	var origval Ptr[byte] = Ptr[byte]{}
	var origval_l Ptr[byte] = Ptr[byte]{}
	var origval_g Ptr[byte] = Ptr[byte]{}

	if (opt_flags&(OPT_LOCAL|OPT_GLOBAL)) == 0 && (int32(options.At(int(opt_idx)).indir)&PV_BOTH) != 0 {
		varp = options.At(int(opt_idx)).var_
	}

	oldval = varp.ov_str.Get()

	if (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 {
		origval_l = get_varp_scope(options.Add(int(opt_idx)), OPT_LOCAL).ov_str.Get()
		origval_g = get_varp_scope(options.Add(int(opt_idx)), OPT_GLOBAL).ov_str.Get()

		if (int32(options.At(int(opt_idx)).indir)&PV_BOTH) != 0 && origval_l == empty_option {
			origval_l = origval_g
		}
	}

	if (int32(options.At(int(opt_idx)).indir)&PV_BOTH) != 0 && (opt_flags&OPT_LOCAL) != 0 {
		origval = get_varp(options.Add(int(opt_idx))).ov_str.Get()
	} else {
		origval = oldval
	}

	newval = stropt_get_newval(nextchar, opt_idx, &arg, varp, &origval, &origval_l, &origval_g, &oldval, &op, int32(flags), cp_val)

	varp.ov_str.Put(newval)
	if newval.Nil() {
		varp.ov_str.Put(empty_option)
	}

	{
		p := &options.Ref(int(opt_idx)).flags
		secure_saved := secure

		if op != OP_NONE && (*p&P_INSECURE) != 0 {
			secure = 1
		}

		*errmsg = did_set_string_option(opt_idx, varp.ov_str, oldval, newval, errbuf, errbuflen, opt_flags, op, value_checked)

		secure = secure_saved
	}

	*argp = arg
	if (*errmsg).Nil() {
		return OK
	}
	return FAIL
}

func do_set_option_bool(opt_idx int32, opt_flags int32, prefix set_prefix_T, flags long_u, varp optvar_T, nextchar int32, afterchar int32, cp_val int32) Ptr[byte] {
	var value varnumber_T

	if nextchar == '=' || nextchar == ':' {
		return e_invalid_argument
	}
	if opt_idx < 0 || optvar_is_null(varp) != 0 {
		return Ptr[byte]{}
	}

	if nextchar == '!' {
		value = varnumber_T(*varp.ov_int ^ 1)
	} else if nextchar == '&' {
		var dvi int32
		if (flags&P_VI_DEF) != 0 || cp_val != 0 {
			dvi = VI_DEFAULT
		} else {
			dvi = VIM_DEFAULT
		}
		value = varnumber_T(int32(options.At(int(opt_idx)).def_num[dvi]))
	} else {
		if nextchar != NUL && !(afterchar == ' ' || afterchar == '\t') {
			return e_trailing_characters
		}
		if prefix == PREFIX_INV {
			value = varnumber_T(*varp.ov_int ^ 1)
		} else {
			if prefix == PREFIX_NO {
				value = 0
			} else {
				value = 1
			}
		}
	}

	return set_bool_option(opt_idx, varp, int32(value), opt_flags)
}

func do_set_option_numeric(opt_idx int32, opt_flags int32, argp *Ptr[byte], nextchar int32, op set_op_T, flags long_u, cp_val int32, varp optvar_T, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	arg := *argp
	var value varnumber_T
	var i int32
	var errmsg Ptr[byte] = Ptr[byte]{}

	if opt_idx < 0 || optvar_is_null(varp) != 0 {
		return Ptr[byte]{}
	}
	arg = arg.Add(1)
	if nextchar == '&' {
		var dvi int32
		if (flags&P_VI_DEF) != 0 || cp_val != 0 {
			dvi = VI_DEFAULT
		} else {
			dvi = VIM_DEFAULT
		}
		value = options.At(int(opt_idx)).def_num[dvi]
	} else if arg.Get() == '-' || uint32(arg.Get())-'0' < 10 {
		vim_str2nr(arg, nil, &i, (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT), &value, nil, 0, TRUE, nil)
		if i == 0 || (arg.At(int(i)) != NUL && !(arg.At(int(i)) == ' ' || arg.At(int(i)) == '\t')) {
			errmsg = e_number_required_after_equal
			goto skip
		}
	} else {
		errmsg = e_number_required_after_equal
		goto skip
	}

	if op == OP_ADDING {
		value = *varp.ov_long + value
	} else if op == OP_PREPENDING {
		value = *varp.ov_long * value
	} else if op == OP_REMOVING {
		value = *varp.ov_long - value
	}

	if varp.ov_long == &curwin.w_onebuf_opt.wo_sop && value < -1 {
		errmsg = e_invalid_argument
		goto skip
	}

	errmsg = set_num_option(opt_idx, varp, value, errbuf, errbuflen, opt_flags)

skip:
	*argp = arg
	return errmsg
}

func do_set_option_keycode(argp *Ptr[byte], key_name Ptr[byte], nextchar int32) Ptr[byte] {
	arg := *argp
	var p Ptr[byte]

	if nextchar == '&' {
		if add_termcap_entry(key_name, TRUE) == FAIL {
			return e_not_found_in_termcap
		}
	} else {
		arg = arg.Add(1)
		for p = arg; p.Get() != 0 && !(p.Get() == ' ' || p.Get() == '\t'); p = p.Add(1) {
			if p.Get() == '\\' && p.At(1) != NUL {
				p = p.Add(1)
			}
		}
		nextchar = int32(p.Get())
		p.Put(NUL)
		add_termcode(key_name, arg, FALSE)
		p.Put(byte(nextchar))
	}
	if full_screen != 0 {
		ttest(FALSE)
	}
	redraw_all_later(UPD_CLEAR)

	*argp = arg
	return Ptr[byte]{}
}

func do_set_option_value(opt_idx int32, opt_flags int32, argp *Ptr[byte], prefix set_prefix_T, op set_op_T, flags long_u, varp optvar_T, key_name Ptr[byte], nextchar int32, afterchar int32, cp_val int32, stopopteval *int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	var value_checked int32 = FALSE
	var errmsg Ptr[byte] = Ptr[byte]{}
	arg := *argp

	if flags&P_BOOL != 0 {
		errmsg = do_set_option_bool(opt_idx, opt_flags, prefix, flags, varp, nextchar, afterchar, cp_val)
		if !errmsg.Nil() {
			goto skip
		}
	} else {
		if vim_strchr(S("=:&<"), nextchar).Nil() || prefix != PREFIX_NONE {
			errmsg = e_invalid_argument
			goto skip
		}

		if flags&P_NUM != 0 {
			errmsg = do_set_option_numeric(opt_idx, opt_flags, &arg, nextchar, op, flags, cp_val, varp, errbuf, errbuflen)
			if !errmsg.Nil() {
				goto skip
			}
		} else if opt_idx >= 0 {
			if do_set_option_string(opt_idx, opt_flags, &arg, nextchar, op, flags, cp_val, varp, errbuf, errbuflen, &value_checked, &errmsg) == FAIL {
				if !errmsg.Nil() {
					goto skip
				}
				*stopopteval = TRUE
				goto skip
			}
		} else {
			errmsg = do_set_option_keycode(&arg, key_name, nextchar)
			if !errmsg.Nil() {
				goto skip
			}
		}
	}

	if opt_idx >= 0 {
		did_set_option(opt_idx, opt_flags, B2i(op == OP_NONE), value_checked)
	}

skip:
	*argp = arg
	return errmsg
}

func do_set_option(opt_flags int32, argp *Ptr[byte], arg_start Ptr[byte], startarg *Ptr[byte], did_show *int32, stopopteval *int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	var opt_idx int32
	var arg Ptr[byte]
	var prefix set_prefix_T
	var op set_op_T
	var flags long_u
	var varp optvar_T
	key_name := Mk[byte](2)
	var nextchar int32
	var afterchar int32
	var errmsg Ptr[byte] = Ptr[byte]{}
	var key int32
	var len_ int32
	var cp_val int32

	prefix = get_option_prefix(argp)
	arg = *argp

	key = 0
	if parse_option_name(arg, &opt_idx, &len_, &key) == FAIL {
		return e_invalid_argument
	}

	afterchar = int32(arg.At(int(len_)))

	for arg.At(int(len_)) == ' ' || arg.At(int(len_)) == '\t' {
		len_++
	}

	op = get_opt_op(arg.Add(int(len_)))
	if op != OP_NONE {
		len_++
	}

	nextchar = int32(arg.At(int(len_)))

	if opt_idx == -1 && key == 0 {
		errmsg = e_unknown_option
		goto skip
	}

	if opt_idx >= 0 {
		if optvar_is_null(options.At(int(opt_idx)).var_) != 0 {
			if vim_strchr(S("=:!&<"), nextchar).Nil() && ((options.At(int(opt_idx)).flags&P_BOOL) == 0 || nextchar == '?') {
				errmsg = e_option_not_supported
			}
			goto skip
		}

		flags = options.At(int(opt_idx)).flags
		varp = get_varp_scope(options.Add(int(opt_idx)), opt_flags)
	} else {
		flags = P_STRING
		varp = optvar_none()
		if key < 0 {
			key_name.Set(0, byte((-(key))&0xff))
			key_name.Set(1, byte((uint32(-(key))>>8)&0xff))
		} else {
			key_name.Set(0, KS_KEY)
			key_name.Set(1, byte(key&0xff))
		}
	}

	if validate_opt_idx(opt_idx, opt_flags, flags, &errmsg, prefix) == FAIL {
		goto skip
	}

	cp_val = p_cp
	if !vim_strchr(S("?=:!&"), nextchar).Nil() {
		arg = arg.Add(int(len_))
		if nextchar == '&' && arg.At(1) == 'v' && arg.At(2) == 'i' {
			if arg.At(3) == 'm' {
				cp_val = FALSE
				arg = arg.Add(3)
			} else {
				cp_val = TRUE
				arg = arg.Add(2)
			}
		}
		if !vim_strchr(S("?!&<"), nextchar).Nil() && arg.At(1) != NUL && !(arg.At(1) == ' ' || arg.At(1) == '\t') {
			errmsg = e_trailing_characters
			goto skip
		}
	}

	if nextchar == '?' || (prefix == PREFIX_NONE && vim_strchr(S("=:&<"), nextchar).Nil() && (flags&P_BOOL) == 0) {
		if *did_show != 0 {
			msg_putchar('\n')
		} else {
			gotocmdline(TRUE)
			*did_show = TRUE
		}
		if opt_idx >= 0 {
			showoneopt(options.Add(int(opt_idx)), opt_flags)
		} else {
			var p Ptr[byte]

			p = find_termcode(key_name)
			if p.Nil() {
				errmsg = e_key_code_not_set
				goto skip
			} else {
				show_one_termcode(key_name, p, TRUE)
			}
		}
		if nextchar != '?' && nextchar != NUL && !(afterchar == ' ' || afterchar == '\t') {
			errmsg = e_trailing_characters
		}
	} else {
		errmsg = do_set_option_value(opt_idx, opt_flags, &arg, prefix, op, flags, varp, key_name, nextchar, afterchar, cp_val, stopopteval, errbuf, errbuflen)
	}

skip:
	*argp = arg
	return errmsg
}

func do_set(arg_start Ptr[byte], opt_flags int32) int32 {
	arg := arg_start
	var i int32
	var did_show int32 = FALSE

	if arg.Get() == NUL {
		showoptions(0, opt_flags)
		did_show = TRUE
		goto theend
	}

	for arg.Get() != NUL {
		if musl_strncmp(arg, S("all"), 3) == 0 && !f11_ascii_isalpha(int32(arg.At(3))) {
			arg = arg.Add(3)
			if arg.Get() == '&' {
				arg = arg.Add(1)
				set_options_default(OPT_FREE | opt_flags)
				didset_options()
				didset_options2()
				redraw_all_later(UPD_CLEAR)
			} else {
				showoptions(1, opt_flags)
				did_show = TRUE
			}
		} else if musl_strncmp(arg, S("termcap"), 7) == 0 {
			showoptions(2, opt_flags)
			show_termcodes(opt_flags)
			did_show = TRUE
			arg = arg.Add(7)
		} else {
			var stopopteval int32 = FALSE
			var errmsg Ptr[byte] = Ptr[byte]{}
			errbuf := Mk[byte](ERR_BUFLEN)
			startarg := arg

			errmsg = do_set_option(opt_flags, &arg, arg_start, &startarg, &did_show, &stopopteval, errbuf, ERR_BUFLEN)
			if stopopteval != 0 {
				break
			}

			for i = 0; i < 2; i++ {
				for arg.Get() != NUL && !(arg.Get() == ' ' || arg.Get() == '\t') {
					c := arg.Get()
					arg = arg.Add(1)
					if c == '\\' && arg.Get() != NUL {
						arg = arg.Add(1)
					}
				}
				arg = skipwhite(arg)
				if arg.Get() != '=' {
					break
				}
			}

			if !errmsg.Nil() {
				i = vim_snprintf(IObuff, (1024+1), S("%s"), gettext_(errmsg)) + 2
				if int64(i)+int64(arg.Sub(startarg)) < (1024 + 1) {
					musl_strcpy(IObuff.Add(int(i-2)), S(": "))
					Memmove(IObuff.Add(int(i)), startarg, arg.Sub(startarg))
					IObuff.Set(int(i)+arg.Sub(startarg), NUL)
				}
				trans_characters(IObuff, (1024 + 1))

				no_wait_return++
				emsg(IObuff)
				no_wait_return--

				return FAIL
			}
		}

		arg = skipwhite(arg)
	}

theend:
	_ = did_show

	return OK
}

func did_set_option(opt_idx int32, opt_flags int32, new_value int32, value_checked int32) {
	var flagsp *long_u
	var flagsp_local *long_u = nil
	both := B2i((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0)

	options.Ref(int(opt_idx)).flags |= P_WAS_SET

	flagsp = &options.Ref(int(opt_idx)).flags
	if both != 0 {
		flagsp_local = &options.Ref(int(opt_idx)).flags
	}
	if value_checked == 0 && secure != 0 {
		*flagsp = *flagsp | P_INSECURE
		if flagsp_local != nil {
			*flagsp_local = *flagsp_local | P_INSECURE
		}
	} else if new_value != 0 {
		*flagsp = *flagsp & ^long_u(P_INSECURE)
		if flagsp_local != nil {
			*flagsp_local = *flagsp_local & ^long_u(P_INSECURE)
		}
	}
}

func option_expand(opt_idx int32, val Ptr[byte]) Ptr[byte] {
	if (options.At(int(opt_idx)).flags&P_EXPAND) == 0 || optvar_is_null(options.At(int(opt_idx)).var_) != 0 {
		return Ptr[byte]{}
	}

	if !val.Nil() && musl_strlen(val) > PATH_MAX {
		return Ptr[byte]{}
	}

	if val.Nil() {
		val = options.At(int(opt_idx)).var_.ov_str.Get()
	}

	var esc int32 = FALSE

	var esc_chars Ptr[byte]
	if esc != 0 {
		esc_chars = S(" \t")
	} else {
		esc_chars = Ptr[byte]{}
	}
	expand_env_esc(val, NameBuff, PATH_MAX, esc_chars, FALSE, Ptr[byte]{})
	if musl_strcmp(NameBuff, val) == 0 {
		return Ptr[byte]{}
	}

	return NameBuff
}

