func did_set_paste(args *optset_T) Ptr[byte] {
	var buf *S_file_buffer

	if p_paste != 0 {
		if did_set_paste_old_p_paste == 0 {
			buf = curbuf
			buf.b_p_tw_nopaste = buf.b_p_tw
			buf.b_p_wm_nopaste = buf.b_p_wm
			buf.b_p_sts_nopaste = buf.b_p_sts
			buf.b_p_ai_nopaste = buf.b_p_ai
			buf.b_p_et_nopaste = buf.b_p_et

			did_set_paste_save_sm = p_sm
			did_set_paste_save_sta = p_sta
			did_set_paste_save_ru = p_ru
			p_ai_nopaste = p_ai
			p_et_nopaste = p_et
			p_sts_nopaste = p_sts
			p_tw_nopaste = p_tw
			p_wm_nopaste = p_wm
		}

		buf = curbuf
		buf.b_p_tw = 0
		buf.b_p_wm = 0
		buf.b_p_sts = 0
		buf.b_p_ai = 0
		buf.b_p_et = 0

		p_sm = 0
		p_sta = 0
		if p_ru != 0 {
			status_redraw_all()
		}
		p_ru = 0
		p_tw = 0
		p_wm = 0
		p_sts = 0
		p_ai = 0
		p_et = 0
	} else if did_set_paste_old_p_paste != 0 {
		buf = curbuf
		buf.b_p_tw = buf.b_p_tw_nopaste
		buf.b_p_wm = buf.b_p_wm_nopaste
		buf.b_p_sts = buf.b_p_sts_nopaste
		buf.b_p_ai = buf.b_p_ai_nopaste
		buf.b_p_et = buf.b_p_et_nopaste

		p_sm = did_set_paste_save_sm
		p_sta = did_set_paste_save_sta
		if p_ru != did_set_paste_save_ru {
			status_redraw_all()
		}
		p_ru = did_set_paste_save_ru
		p_ai = p_ai_nopaste
		p_et = p_et_nopaste
		p_sts = p_sts_nopaste
		p_tw = p_tw_nopaste
		p_wm = p_wm_nopaste
	}

	did_set_paste_old_p_paste = p_paste

	return Ptr[byte]{}
}

