func after_copy_winopt(wp *S_window_S) {
	errmsg := update_winhighlight(wp, wp.w_onebuf_opt.wo_whl)

	if !errmsg.Nil() {
		emsg(gettext_(errmsg))
	}

	if wp.w_onebuf_opt.wo_wrap != 0 {
		wp.w_leftcol = 0
	} else {
		wp.w_skipcol = 0
	}
	set_listchars_option(wp, wp.w_onebuf_opt.wo_lcs, TRUE, Ptr[byte]{}, 0)
	set_fillchars_option(wp, wp.w_onebuf_opt.wo_fcs, TRUE, Ptr[byte]{}, 0)
}

func copy_option_val(val Ptr[byte]) Ptr[byte] {
	if val == empty_option {
		return empty_option
	}
	return vim_strsave(val)
}

func copy_winopt(from *winopt_T, to *winopt_T) {
	to.wo_list = from.wo_list
	to.wo_lcs = copy_option_val(from.wo_lcs)
	to.wo_fcs = copy_option_val(from.wo_fcs)
	to.wo_nu = from.wo_nu
	to.wo_rnu = from.wo_rnu
	to.wo_ve = copy_option_val(from.wo_ve)
	to.wo_ve_flags = from.wo_ve_flags
	to.wo_wrap = from.wo_wrap
	to.wo_wcr = copy_option_val(from.wo_wcr)
	to.wo_sms = from.wo_sms
	to.wo_siso = from.wo_siso
	to.wo_so = from.wo_so
	to.wo_sop = from.wo_sop

	to.wo_wrap_flags = from.wo_wrap_flags
	to.wo_whl = copy_option_val(from.wo_whl)

	check_winopt(to)
}

