func buf_copy_options(buf *S_file_buffer, flags int32) {
	should_copy := int32(TRUE)
	var save_p_isk Ptr[byte]
	var dont_do_help int32
	did_isk := int32(FALSE)

	if !p_cpo.Nil() {
		if (vim_strchr(p_cpo, CPO_BUFOPTGLOB).Nil() || (flags&BCO_ENTER) == 0) && (buf.b_p_initialized || ((flags&BCO_ENTER) == 0 && !vim_strchr(p_cpo, CPO_BUFOPT).Nil())) {
			should_copy = FALSE
		}

		if should_copy != 0 || (flags&BCO_ALWAYS) != 0 {
			dont_do_help = B2i(((flags&BCO_NOHELP) != 0 && buf.b_help) || buf.b_p_initialized)
			if dont_do_help != 0 {
				save_p_isk = buf.b_p_isk
				buf.b_p_isk = Ptr[byte]{}
			}
			if !buf.b_p_initialized {
				free_buf_options(buf, TRUE)
			} else {
				free_buf_options(buf, FALSE)
			}

			buf.b_p_ai = p_ai
			buf.b_p_ai_nopaste = p_ai_nopaste
			buf.b_p_sw = p_sw
			buf.b_p_tw = p_tw
			buf.b_p_tw_nopaste = p_tw_nopaste
			buf.b_p_wm = p_wm
			buf.b_p_wm_nopaste = p_wm_nopaste
			buf.b_p_et = p_et
			buf.b_p_et_nopaste = p_et_nopaste
			buf.b_p_sts = p_sts
			buf.b_p_sts_nopaste = p_sts_nopaste
			buf.b_p_nf = vim_strsave(p_nf)
			buf.b_p_mps = vim_strsave(p_mps)
			buf.b_p_si = p_si
			buf.b_p_ci = p_ci

			buf.b_p_pi = p_pi

			buf.b_p_ul = -123456
			buf.b_bkc_flags = 0
			buf.b_tc_flags = 0
			buf.b_cot_flags = 0
			buf.b_p_qe = vim_strsave(p_qe)

			if dont_do_help != 0 {
				buf.b_p_isk = save_p_isk
			} else {
				buf.b_p_isk = vim_strsave(p_isk)
				did_isk = TRUE
				buf.b_p_ts = p_ts
				buf.b_help = false
				buf.b_p_ma = p_ma
			}
		}

		if should_copy != 0 {
			buf.b_p_initialized = true
		}
	}

	check_buf_options(buf)
	if did_isk != 0 {
		buf_init_chartab(buf, FALSE)
	}
}

func option_value2string(opp Ptr[S_vimoption], scope int32) {
	var varp optvar_T

	varp = get_varp_scope(opp, scope)

	if (opp.P().flags & P_NUM) != 0 {
		vim_snprintf(NameBuff, PATH_MAX, S("%ld"), *varp.ov_long)
	} else {
		s := varp.ov_str.Get()

		if s.Nil() {
			NameBuff.Set(0, NUL)
		} else if (opp.P().flags & P_EXPAND) != 0 {
			home_replace(nil, s, NameBuff, PATH_MAX, FALSE)
		} else if opp.P().var_.ov_str == Addr(&p_pt) {
			str2specialbuf(p_pt, NameBuff, PATH_MAX)
		} else {
			vim_strncpy(NameBuff, s, PATH_MAX-1)
		}
	}
}

func shortmess(x int32) int32 {
	return B2i(!p_shm.Nil() &&
		(!vim_strchr(p_shm, x).Nil() || (!vim_strchr(p_shm, 'a').Nil() && !vim_strchr(S("rmfixlnw"), x).Nil())))
}

func option_was_set(name Ptr[byte]) int32 {
	var idx int32

	idx = findoption(name)
	if idx < 0 {
		return FALSE
	}
	if (options.At(int(idx)).flags & P_WAS_SET) != 0 {
		return TRUE
	}
	return FALSE
}

func reset_option_was_set(name Ptr[byte]) int32 {
	idx := findoption(name)

	if idx < 0 {
		return FAIL
	}

	options.Ref(int(idx)).flags &^= P_WAS_SET
	return OK
}

func compatible_set() {
	var opt_idx int32

	for opt_idx = 0; istermoption_idx(opt_idx) == 0; opt_idx++ {
		if ((options.At(int(opt_idx)).flags&P_VIM) != 0 && p_cp != 0) || ((options.At(int(opt_idx)).flags&P_VI_DEF) == 0 && p_cp == 0) {
			set_option_default(opt_idx, OPT_FREE, p_cp)
		}
	}
	didset_options()
	didset_options2()
}

func can_bs(what int32) int32 {
	switch p_bs.Get() {
	case '3':
		return TRUE
	case '2':
		return B2i(what != BS_NOSTOP)
	case '1':
		return B2i(what != BS_START)
	case '0':
		return FALSE
	}
	return B2i(!vim_strchr(p_bs, what).Nil())
}

