func illegal_char(errbuf Ptr[byte], errbuflen usize, c int32) Ptr[byte] {
	if errbuf.Nil() {
		return S("")
	}
	vim_snprintf(errbuf, errbuflen, gettext_(e_illegal_character_str), transchar(c))
	return errbuf
}

