func did_set_global_listfillchars(val Ptr[byte], opt_lcs int32, opt_flags int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	var errmsg Ptr[byte]
	var local_ptr *Ptr[byte]
	if opt_lcs != 0 {
		local_ptr = &curwin.w_onebuf_opt.wo_lcs
	} else {
		local_ptr = &curwin.w_onebuf_opt.wo_fcs
	}

	if opt_lcs != 0 {
		errmsg = set_listchars_option(curwin, val, B2i((*local_ptr).Get() == NUL || (opt_flags&OPT_GLOBAL) == 0), errbuf, errbuflen)
	} else {
		errmsg = set_fillchars_option(curwin, val, B2i((*local_ptr).Get() == NUL || (opt_flags&OPT_GLOBAL) == 0), errbuf, errbuflen)
	}
	if !errmsg.Nil() {
		return errmsg
	}

	var wp *S_window_S

	if (opt_flags & OPT_GLOBAL) == 0 {
		clear_string_option(local_ptr)
	}
	wp = curwin
	if opt_lcs != 0 {
		if wp.w_onebuf_opt.wo_lcs.Get() == NUL {
			set_listchars_option(wp, wp.w_onebuf_opt.wo_lcs, TRUE, Ptr[byte]{}, 0)
		}
	} else {
		if wp.w_onebuf_opt.wo_fcs.Get() == NUL {
			set_fillchars_option(wp, wp.w_onebuf_opt.wo_fcs, TRUE, Ptr[byte]{}, 0)
		}
	}

	redraw_all_later(UPD_NOT_VALID)

	return Ptr[byte]{}
}

