func did_set_matchpairs(args *optset_T) Ptr[byte] {
	varp := args.os_varp.ov_str
	var p Ptr[byte]

	for p = varp.Get(); p.Get() != NUL; p = p.Add(1) {
		x2 := int32(-1)
		x3 := int32(-1)

		p = p.Add(int(utfc_ptr2len(p)))
		if p.Get() != NUL {
			x2 = int32(p.Get())
			p = p.Add(1)
		}
		if p.Get() != NUL {
			x3 = utf_ptr2char(p)
			p = p.Add(int(utfc_ptr2len(p)))
		}
		if x2 != ':' || x3 == -1 || (p.Get() != NUL && p.Get() != ',') {
			return e_invalid_argument
		}
		if p.Get() == NUL {
			break
		}
	}

	return Ptr[byte]{}
}

