func did_set_string_option(opt_idx int32, varp Ptr[Ptr[byte]], oldval Ptr[byte], value Ptr[byte], errbuf Ptr[byte], errbuflen usize, opt_flags int32, op set_op_T, value_checked *int32) Ptr[byte] {
	var errmsg Ptr[byte]
	free_oldval := get_option_flags(opt_idx) & P_ALLOCED
	did_set_cb := get_option_did_set_cb(opt_idx)
	var args optset_T

	if varp == View(term_strings[:]).Add(int(KS_NAME)) {
		opt_idx = findoption(S("term"))
		if opt_idx >= 0 {
			free_oldval = get_option_flags(opt_idx) & P_ALLOCED
			did_set_cb = get_option_did_set_cb(opt_idx)
		}
	}

	args = optset_T{}

	if secure != 0 && (get_option_flags(opt_idx)&P_SECURE) != 0 {
		errmsg = e_not_allowed_here
	} else if check_illegal_path_names(opt_idx, varp) != 0 {
		errmsg = e_invalid_argument
	} else if did_set_cb != nil {
		args.os_varp = optvar_str(varp)
		args.os_idx = opt_idx
		args.os_flags = opt_flags
		args.os_op = op
		args.os_oldval.string_ = oldval
		args.os_newval.string_ = value
		args.os_errbuf = errbuf
		args.os_errbuflen = errbuflen
		errmsg = did_set_cb(&args)

		*value_checked = args.os_value_checked
	}

	if !errmsg.Nil() {
		free_string_option(varp.Get())
		varp.Put(oldval)
		if args.os_restore_chartab != 0 {
			init_chartab()
		}
		if varp == Addr(&p_hl) {
			highlight_changed()
		}
	} else {
		if free_oldval != 0 {
			free_string_option(oldval)
		}
		set_option_flag(opt_idx, P_ALLOCED)

		if (opt_flags&(OPT_LOCAL|OPT_GLOBAL)) == 0 && is_global_local_option(opt_idx) != 0 {
			p := get_option_varp_scope(opt_idx, OPT_LOCAL).ov_str
			free_string_option(p.Get())
			p.Put(empty_option)
		} else if (opt_flags&OPT_LOCAL) == 0 && opt_flags != OPT_GLOBAL {
			set_string_option_global(opt_idx, varp)
		}
	}

	if curwin.w_curswant != MAXCOL && (get_option_flags(opt_idx)&(P_CURSWANT|P_RALL)) != 0 && (get_option_flags(opt_idx)&P_HLONLY) == 0 {
		curwin.w_set_curswant = true
	}

	if (opt_flags & OPT_NO_REDRAW) == 0 {
		check_redraw(get_option_flags(opt_idx))
	}

	return errmsg
}

func check_opt_strings(val Ptr[byte], values Ptr[Ptr[byte]], list int32) int32 {
	return opt_strings_flags(val, values, nil, list)
}

func opt_strings_flags(val Ptr[byte], values Ptr[Ptr[byte]], flagp *uint32, list int32) int32 {
	var i int32
	var len_ int32
	var new_flags uint32 = 0

	for val.Get() != 0 {
		for i = 0; ; i++ {
			if values.At(int(i)).Nil() {
				return FAIL
			}

			len_ = int32(musl_strlen(values.At(int(i))))
			if musl_strncmp(values.At(int(i)), val, usize(len_)) == 0 && ((list != 0 && val.At(int(len_)) == ',') || val.At(int(len_)) == NUL) {
				val = val.Add(int(len_) + int(B2i(val.At(int(len_)) == ',')))
				new_flags |= 1 << uint(i)
				break
			}
		}
	}
	if flagp != nil {
		*flagp = new_flags
	}

	return OK
}

