func WaitForChar(msec int64, interrupted *int32, ignore_input int32) int32 {
	var avail int32

	if ignore_input == 0 && input_available() != 0 {
		return 1
	}

	avail = RealWaitForChar(read_cmd_fd, msec, nil, interrupted)
	return avail
}

func RealWaitForChar(fd int32, msec int64, check_for_gpm *int32, interrupted *int32) int32 {
	return musl_wait_for_input(msec)
}

func no_Magic(x int32) int32 {
	if x < 0 {
		return x + 256
	}
	return x
}

func toggle_Magic(x int32) int32 {
	if x < 0 {
		return x + 256
	}
	return x - 256
}

func re_multi_type(c int32) int32 {
	if c == int32('@')-256 || c == int32('=')-256 || c == int32('?')-256 {
		return MULTI_ONE
	}
	if c == int32('*')-256 || c == int32('+')-256 || c == int32('{')-256 {
		return MULTI_MULT
	}
	return NOT_MULTI
}

func backslash_trans(c int32) int32 {
	switch c {
	case 'r':
		return CAR
	case 't':
		return TAB
	case 'e':
		return ESC
	case 'b':
		return BS
	}
	return c
}

func get_char_class(pp *Ptr[byte]) int32 {
	if (*pp).At(1) == ':' && uint32((*pp).At(2))-'a' < 26 && uint32((*pp).At(3))-'a' < 26 && uint32((*pp).At(4))-'a' < 26 {
		var target keyvalue_T
		var entry Ptr[keyvalue_T]

		target.key = 0
		target.value.string_ = (*pp).Add(2)
		target.value.length = 0

		if !get_char_class_last_entry.Nil() && cmp_keyvalue_value_n(&target, get_char_class_last_entry) == 0 {
			entry = get_char_class_last_entry
		} else {
			entry = keyvalue_bsearch(&target, get_char_class_char_class_tab, 19, func(kv1 *keyvalue_T, kv2 *keyvalue_T) int32 { return cmp_keyvalue_value_n(kv1, Addr(kv2)) })
		}
		if !entry.Nil() {
			get_char_class_last_entry = entry
			*pp = (*pp).Add(int(entry.P().value.length) + 2)
			return entry.P().key
		}
	}
	return CLASS_NONE
}

func init_class_tab() {
	var i int32

	if init_class_tab_done != 0 {
		return
	}

	for i = 0; i < 256; i++ {
		if i >= '0' && i <= '7' {
			class_tab[i] = RI_DIGIT + RI_HEX + RI_OCTAL + RI_WORD
		} else if i >= '8' && i <= '9' {
			class_tab[i] = RI_DIGIT + RI_HEX + RI_WORD
		} else if i >= 'a' && i <= 'f' {
			class_tab[i] = RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER
		} else if i >= 'g' && i <= 'z' {
			class_tab[i] = RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER
		} else if i >= 'A' && i <= 'F' {
			class_tab[i] = RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER
		} else if i >= 'G' && i <= 'Z' {
			class_tab[i] = RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER
		} else if i == '_' {
			class_tab[i] = RI_WORD + RI_HEAD
		} else {
			class_tab[i] = 0
		}
	}
	class_tab[' '] |= RI_WHITE
	class_tab['\t'] |= RI_WHITE
	init_class_tab_done = TRUE
}

func re_multiline(prog *S_regprog) int32 {
	return int32(prog.regflags & RF_HASNL)
}

func get_coll_element(pp *Ptr[byte]) int32 {
	var c int32
	var l int32 = 1
	p := *pp

	if p.At(0) != NUL && p.At(1) == '.' && p.At(2) != NUL {
		l = utfc_ptr2len(p.Add(2))
		if p.At(int(l)+2) == '.' && p.At(int(l)+3) == ']' {
			c = utf_ptr2char(p.Add(2))
			*pp = (*pp).Add(int(l) + 4)
			return c
		}
	}
	return 0
}

func get_cpo_flags() {
	reg_cpo_lit = B2i(!vim_strchr(p_cpo, CPO_LITERAL).Nil())
	reg_cpo_bsl = B2i(!vim_strchr(p_cpo, CPO_BACKSL).Nil())
}

func skip_anyof(p Ptr[byte]) Ptr[byte] {
	var l int32

	if p.Get() == '^' {
		p = p.Add(1)
	}
	if p.Get() == ']' || p.Get() == '-' {
		p = p.Add(1)
	}
	for p.Get() != NUL && p.Get() != ']' {
		l = utfc_ptr2len(p)
		if l > 1 {
			p = p.Add(int(l))
		} else {
			if p.Get() == '-' {
				p = p.Add(1)
				if p.Get() != ']' && p.Get() != NUL {
					p = p.Add(int(utfc_ptr2len(p)))
				}
			} else if p.Get() == '\\' && reg_cpo_bsl == 0 && (!vim_strchr(REGEXP_INRANGE, int32(p.At(1))).Nil() || (reg_cpo_lit == 0 && !vim_strchr(REGEXP_ABBR, int32(p.At(1))).Nil())) {
				p = p.Add(2)
			} else if p.Get() == '[' {
				if get_char_class(&p) == CLASS_NONE && get_coll_element(&p) == 0 && p.Get() != NUL {
					p = p.Add(1)
				}
			} else {
				p = p.Add(1)
			}
		}
	}

	return p
}

func skip_regexp(startp Ptr[byte], delim int32, magic int32) Ptr[byte] {
	return skip_regexp_ex(startp, delim, magic, nil, nil, nil)
}

func skip_regexp_ex(startp Ptr[byte], dirc int32, magic int32, newp *Ptr[byte], dropped *int32, magic_val *magic_T) Ptr[byte] {
	var mymagic magic_T
	p := startp
	var startplen usize = 0

	if magic != 0 {
		mymagic = MAGIC_ON
	} else {
		mymagic = MAGIC_OFF
	}
	get_cpo_flags()

	for ; p.At(0) != NUL; p = p.Add(int(utfc_ptr2len(p))) {
		if int32(p.At(0)) == dirc {
			break
		}
		if (p.At(0) == '[' && mymagic >= MAGIC_ON) || (p.At(0) == '\\' && p.At(1) == '[' && mymagic <= MAGIC_OFF) {
			p = skip_anyof(p.Add(1))
			if p.At(0) == NUL {
				break
			}
		} else if p.At(0) == '\\' && p.At(1) != NUL {
			if dirc == '?' && newp != nil && p.At(1) == '?' {
				if startplen == 0 {
					startplen = musl_strlen(startp)
				}
				if (*newp).Nil() {
					*newp = vim_strnsave(startp, startplen)
					if !(*newp).Nil() {
						p = (*newp).Add(p.Sub(startp))
						startp = *newp
					}
				}
				if dropped != nil {
					*dropped++
				}
				if !(*newp).Nil() {
					Memmove(p, p.Add(1), int(startplen-usize(p.Add(1).Sub(startp))+1))
				} else {
					p = p.Add(1)
				}
			} else {
				p = p.Add(1)
			}
			if p.Get() == 'v' {
				mymagic = MAGIC_ALL
			} else if p.Get() == 'V' {
				mymagic = MAGIC_NONE
			}
		}
	}
	if magic_val != nil {
		*magic_val = mymagic
	}
	return p
}

func initchr(str Ptr[byte]) {
	regparse = str
	prevchr_len = 0
	nextchr = -1
	prevchr = nextchr
	prevprevchr = prevchr
	curchr = prevprevchr
	at_start = TRUE
	prev_at_start = FALSE
}

func peekchr() int32 {
	if curchr != -1 {
		return curchr
	}

	curchr = int32(regparse.At(0))
	switch curchr {
	case '.', '[', '~':
		if reg_magic >= MAGIC_ON {
			curchr = curchr - 256
		}
	case '(', ')', '{', '%', '+', '=', '?', '@', '!', '&', '|', '<', '>', '#', '"', '\'', ',', '-', ':', ';', '`', '/':
		if reg_magic == MAGIC_ALL {
			curchr = curchr - 256
		}
	case '*':
		if reg_magic >= MAGIC_ON && at_start == 0 && !(prev_at_start != 0 && prevchr == int32('^')-256) && (peekchr_after_slash != 0 || (prevchr != int32('(')-256 && prevchr != int32('&')-256 && prevchr != int32('|')-256)) {
			curchr = int32('*') - 256
		}
	case '^':
		if reg_magic >= MAGIC_OFF && (at_start != 0 || reg_magic == MAGIC_ALL || prevchr == int32('(')-256 || prevchr == int32('|')-256 || prevchr == int32('&')-256 || prevchr == int32('n')-256 || (no_Magic(prevchr) == '(' && prevprevchr == int32('%')-256)) {
			curchr = int32('^') - 256
			at_start = TRUE
			prev_at_start = FALSE
		}
	case '$':
		if reg_magic >= MAGIC_OFF {
			p := regparse.Add(1)
			is_magic_all := B2i(reg_magic == MAGIC_ALL)

			for p.At(0) == '\\' && (p.At(1) == 'c' || p.At(1) == 'C' || p.At(1) == 'm' || p.At(1) == 'M' || p.At(1) == 'v' || p.At(1) == 'V' || p.At(1) == 'Z') {
				if p.At(1) == 'v' {
					is_magic_all = TRUE
				} else if p.At(1) == 'm' || p.At(1) == 'M' || p.At(1) == 'V' {
					is_magic_all = FALSE
				}
				p = p.Add(2)
			}
			if p.At(0) == NUL || (p.At(0) == '\\' && (p.At(1) == '|' || p.At(1) == '&' || p.At(1) == ')' || p.At(1) == 'n')) || (is_magic_all != 0 && (p.At(0) == '|' || p.At(0) == '&' || p.At(0) == ')')) || reg_magic == MAGIC_ALL {
				curchr = int32('$') - 256
			}
		}
	case '\\':
		{
			c := int32(regparse.At(1))

			if c == NUL {
				curchr = '\\'
			} else if c <= '~' && META_flags[c] != 0 {
				curchr = -1
				prev_at_start = at_start
				at_start = FALSE
				regparse = regparse.Add(1)
				peekchr_after_slash++
				peekchr()
				regparse = regparse.Add(-1)
				peekchr_after_slash--
				curchr = toggle_Magic(curchr)
			} else if !vim_strchr(REGEXP_ABBR, c).Nil() {
				curchr = backslash_trans(c)
			} else if reg_magic == MAGIC_NONE && (c == '$' || c == '^') {
				curchr = toggle_Magic(c)
			} else {
				if c >= 0x80 {
					curchr = utf_ptr2char(regparse.Add(1))
				} else {
					curchr = c
				}
			}
		}

	default:
		if curchr >= 0x80 {
			curchr = utf_ptr2char(regparse)
		}
	}

	return curchr
}

func skipchr() {
	if regparse.Get() == '\\' {
		prevchr_len = 1
	} else {
		prevchr_len = 0
	}
	if regparse.At(int(prevchr_len)) != NUL {
		if regparse.At(int(prevchr_len)) < 0x80 {
			prevchr_len++
		} else {
			prevchr_len += utf_ptr2len(regparse.Add(int(prevchr_len)))
		}
	}
	regparse = regparse.Add(int(prevchr_len))
	prev_at_start = at_start
	at_start = FALSE
	prevprevchr = prevchr
	prevchr = curchr
	curchr = nextchr
	nextchr = -1
}

func skipchr_keepstart() {
	as := prev_at_start
	pr := prevchr
	prpr := prevprevchr

	skipchr()
	at_start = as
	prevchr = pr
	prevprevchr = prpr
}

func getchr() int32 {
	chr := peekchr()

	skipchr()
	return chr
}

func ungetchr() {
	nextchr = curchr
	curchr = prevchr
	prevchr = prevprevchr
	at_start = prev_at_start
	prev_at_start = FALSE

	regparse = regparse.Add(-int(prevchr_len))
}

func gethexchrs(maxinputlen int32) vimlong_T {
	var nr long_u = 0
	var c int32
	var i int32

	for i = 0; i < maxinputlen; i++ {
		c = int32(regparse.At(0))
		if vim_isxdigit(c) == 0 {
			break
		}
		nr <<= 4
		nr |= long_u(int64(hex2nr(c)))
		regparse = regparse.Add(1)
	}

	if i == 0 {
		return -1
	}
	return vimlong_T(nr)
}

func getdecchrs() vimlong_T {
	var nr long_u = 0
	var c int32
	var i int32

	for i = 0; ; i++ {
		c = int32(regparse.At(0))
		if c < '0' || c > '9' {
			break
		}
		nr *= 10
		nr += long_u(int64(c - '0'))
		regparse = regparse.Add(1)
		curchr = -1
	}

	if i == 0 {
		return -1
	}
	return vimlong_T(nr)
}

func getoctchrs() int64 {
	var nr long_u = 0
	var c int32
	var i int32

	for i = 0; i < 3 && nr < 0o40; i++ {
		c = int32(regparse.At(0))
		if c < '0' || c > '7' {
			break
		}
		nr <<= 3
		nr |= long_u(int64(hex2nr(c)))
		regparse = regparse.Add(1)
	}

	if i == 0 {
		return -1
	}
	return int64(nr)
}

func read_limits(minval *int64, maxval *int64) int32 {
	reverse := int32(FALSE)
	var first_char Ptr[byte]
	var tmp int64

	if regparse.Get() == '-' {
		regparse = regparse.Add(1)
		reverse = TRUE
	}
	first_char = regparse
	*minval = getdigits(Addr(&regparse))
	if regparse.Get() == ',' {
		regparse = regparse.Add(1)
		if vim_isdigit(int32(regparse.Get())) != 0 {
			*maxval = getdigits(Addr(&regparse))
		} else {
			*maxval = 32767 << 16
		}
	} else if uint32(first_char.Get())-'0' < 10 {
		*maxval = *minval
	} else {
		*maxval = 32767 << 16
	}
	if regparse.Get() == '\\' {
		regparse = regparse.Add(1)
	}
	if regparse.Get() != '}' {
		var bsl Ptr[byte]
		if reg_magic == MAGIC_ALL {
			bsl = S("")
		} else {
			bsl = S("\\")
		}
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_syntax_error_in_str_curlies), bsl)
		emsg(iobuff_or(gettext_(e_syntax_error_in_str_curlies)))
		rc_did_emsg = TRUE
		return FAIL
	}

	if (reverse == 0 && *minval > *maxval) || (reverse != 0 && *minval < *maxval) {
		tmp = *minval
		*minval = *maxval
		*maxval = tmp
	}
	skipchr()
	return OK
}

func reg_iswordc(c int32) int32 {
	return vim_iswordc_buf(c, rex.reg_buf)
}

func reg_getline_common(lnum linenr_T, flags reg_getline_flags_T, line *Ptr[byte], length *colnr_T) {
	get_line := flags & RGLF_LINE
	get_length := flags & RGLF_LENGTH
	var firstlnum linenr_T
	var maxline linenr_T

	{
		firstlnum = rex.reg_firstlnum + lnum
		maxline = rex.reg_maxline
	}

	if firstlnum < 1 {
		if get_line != 0 {
			*line = Ptr[byte]{}
		}
		if get_length != 0 {
			*length = 0
		}

		return
	}

	if lnum > maxline {
		if get_line != 0 {
			*line = S("")
		}
		if get_length != 0 {
			*length = 0
		}

		return
	}

	if get_line != 0 {
		*line = ml_get_buf(rex.reg_buf, firstlnum, FALSE)
	}
	if get_length != 0 {
		*length = ml_get_buf_len(rex.reg_buf, firstlnum)
	}
}

func reg_getline(lnum linenr_T) Ptr[byte] {
	var line Ptr[byte]

	reg_getline_common(lnum, RGLF_LINE, &line, nil)

	return line
}

func reg_getline_len(lnum linenr_T) colnr_T {
	var length colnr_T

	reg_getline_common(lnum, RGLF_LENGTH, nil, &length)

	return length
}

func reg_prev_class() int32 {
	if rex.input.Gt(rex.line) {
		return mb_get_class_buf(rex.input.Add(-1-int(utf_head_off(rex.line, rex.input.Add(-1)))), rex.reg_buf)
	}
	return -1
}

func reg_match_visual() int32 {
	var top pos_T
	var bot pos_T
	var lnum linenr_T
	var col colnr_T
	var wp *S_window_S
	var mode int32
	var start colnr_T
	var end colnr_T
	var start2 colnr_T
	var end2 colnr_T
	var cols colnr_T
	var curswant colnr_T

	if rex.reg_win == nil {
		wp = curwin
	} else {
		wp = rex.reg_win
	}

	// C: the LT_POS() macro
	lt_pos := func(a, b pos_T) bool {
		if a.lnum != b.lnum {
			return a.lnum < b.lnum
		}
		if a.col != b.col {
			return a.col < b.col
		}
		return a.coladd < b.coladd
	}

	if rex.reg_buf != curbuf || VIsual.lnum == 0 || !(rex.reg_match == nil) {
		return FALSE
	}

	if VIsual_active != 0 {
		if lt_pos(VIsual, wp.w_cursor) {
			top = VIsual
			bot = wp.w_cursor
		} else {
			top = wp.w_cursor
			bot = VIsual
		}
		mode = VIsual_mode
		curswant = wp.w_curswant
	} else {
		if lt_pos(curbuf.b_visual.vi_start, curbuf.b_visual.vi_end) {
			top = curbuf.b_visual.vi_start
			bot = curbuf.b_visual.vi_end
		} else {
			top = curbuf.b_visual.vi_end
			bot = curbuf.b_visual.vi_start
		}
		if bot.lnum > curbuf.b_ml.ml_line_count {
			bot.lnum = curbuf.b_ml.ml_line_count
		}
		mode = curbuf.b_visual.vi_mode
		curswant = curbuf.b_visual.vi_curswant
	}
	lnum = rex.lnum + rex.reg_firstlnum
	if lnum < top.lnum || lnum > bot.lnum {
		return FALSE
	}

	col = colnr_T(rex.input.Sub(rex.line))
	if mode == 'v' {
		if (lnum == top.lnum && col < top.col) || (lnum == bot.lnum && col >= bot.col+B2i(p_sel.Get() != 'e')) {
			return FALSE
		}
	} else if mode == Ctrl_V {
		getvvcol(wp, &top, &start, nil, &end, 0)
		getvvcol(wp, &bot, &start2, nil, &end2, 0)
		if start2 < start {
			start = start2
		}
		if end2 > end {
			end = end2
		}
		if top.col == MAXCOL || bot.col == MAXCOL || curswant == MAXCOL {
			end = MAXCOL
		}

		rex.line = reg_getline(rex.lnum)
		rex.input = rex.line.Add(int(col))

		cols = win_linetabsize(wp, rex.reg_firstlnum+rex.lnum, rex.line, col)
		if cols < start || cols > end-B2i(p_sel.Get() == 'e') {
			return FALSE
		}
	}
	return TRUE
}

func prog_magic_wrong() int32 {
	var prog *S_regprog

	if rex.reg_match == nil {
		prog = rex.reg_mmatch.regprog
	} else {
		prog = rex.reg_match.regprog
	}
	if int32(prog.program.Get()) != REGMAGIC {
		iemsg(e_corrupted_regexp_program)
		return TRUE
	}
	return FALSE
}

func cleanup_subexpr() {
	if rex.need_clear_subexpr == 0 {
		return
	}

	if rex.reg_match == nil {
		// C: memset(..., 0xff, ...) of lpos_T: every member -1
		for k := 0; k < NSUBEXP; k++ {
			rex.reg_startpos.Set(k, lpos_T{-1, -1})
			rex.reg_endpos.Set(k, lpos_T{-1, -1})
		}
	} else {
		Zero(rex.reg_startp, NSUBEXP)
		Zero(rex.reg_endp, NSUBEXP)
	}
	rex.need_clear_subexpr = FALSE
}

func reg_nextline() {
	rex.lnum++
	rex.line = reg_getline(rex.lnum)
	rex.input = rex.line
	fast_breakcheck()
}

func match_with_backref(start_lnum linenr_T, start_col colnr_T, end_lnum linenr_T, end_col colnr_T, bytelen *int32) int32 {
	clnum := start_lnum
	ccol := start_col
	var len_ int32
	var p Ptr[byte]

	if bytelen != nil {
		*bytelen = 0
	}
	for {
		if rex.line != reg_tofree {
			len_ = int32(musl_strlen(rex.line))
			if reg_tofree.Nil() || len_ >= int32(reg_tofreelen) {
				len_ += 50
				reg_tofree = Alloc(int(len_))
				reg_tofreelen = uint32(len_)
			}
			musl_strcpy(reg_tofree, rex.line)
			rex.input = reg_tofree.Add(rex.input.Sub(rex.line))
			rex.line = reg_tofree
		}

		p = reg_getline(clnum)
		if clnum == end_lnum {
			len_ = end_col - ccol
		} else {
			len_ = int32(reg_getline_len(clnum)) - ccol
		}

		if (rex.reg_ic == 0 && cstrncmp(p.Add(int(ccol)), rex.input, &len_) != 0) || (rex.reg_ic != 0 && mb_strnicmp(p.Add(int(ccol)), rex.input, usize(len_)) != 0) {
			return RA_NOMATCH
		}
		if bytelen != nil {
			*bytelen += len_
		}
		if clnum == end_lnum {
			break
		}
		if rex.lnum >= rex.reg_maxline {
			return RA_NOMATCH
		}

		reg_nextline()
		if bytelen != nil {
			*bytelen = 0
		}
		clnum++
		ccol = 0
		if got_int != 0 {
			return RA_FAIL
		}
	}

	return RA_MATCH
}

func re_mult_next(what Ptr[byte]) int32 {
	if re_multi_type(peekchr()) == MULTI_MULT {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_nfa_regexp_cannot_repeat_str), what)
		emsg(iobuff_or(gettext_(e_nfa_regexp_cannot_repeat_str)))
		rc_did_emsg = TRUE
		return FAIL
	}
	return OK
}

func mb_decompose(c int32, c1 *int32, c2 *int32, c3 *int32) {
	var d decomp_T

	if c >= 0xfb20 && c <= 0xfb4f {
		d = decomp_table[c-0xfb20]
		*c1 = d.a
		*c2 = d.b
		*c3 = d.c
	} else {
		*c1 = c
		*c2 = 0
		*c3 = 0
	}
}

func cstrncmp(s1 Ptr[byte], s2 Ptr[byte], n *int32) int32 {
	var result int32

	if rex.reg_ic == 0 {
		result = musl_strncmp(s1, s2, usize(*n))
	} else {
		p := s1
		var n2 int32 = 0
		n1 := *n
		for n1 > 0 && p.Get() != NUL {
			n1 -= utfc_ptr2len(p)
			p = p.Add(int(utfc_ptr2len(p)))
			n2++
		}
		p = s2
		for {
			ok := n2 > 0
			n2--
			if !(ok && p.Get() != NUL) {
				break
			}
			p = p.Add(int(utfc_ptr2len(p)))
		}

		n2 = int32(p.Sub(s2))

		result = mb_strnicmp2(s1, s2, usize(*n), usize(n2))
		if result == 0 && n2 < *n {
			*n = n2
		}
	}

	if result != 0 && rex.reg_icombine != 0 {
		var str1 Ptr[byte]
		var str2 Ptr[byte]
		var c1 int32
		var c2 int32
		var c11 int32
		var c12 int32
		var junk int32

		str1 = s1
		str2 = s2
		c2 = 0
		c1 = c2
		for int32(str1.Sub(s1)) < *n {
			c1 = mb_ptr2char_adv(&str1)
			c2 = mb_ptr2char_adv(&str2)

			if c1 != c2 && (rex.reg_ic == 0 || utf_fold(c1) != utf_fold(c2)) {
				mb_decompose(c1, &c11, &junk, &junk)
				mb_decompose(c2, &c12, &junk, &junk)
				c1 = c11
				c2 = c12
				if c11 != c12 && (rex.reg_ic == 0 || utf_fold(c11) != utf_fold(c12)) {
					break
				}
			}
		}
		result = c2 - c1
		if result == 0 {
			*n = int32(str2.Sub(s2))
		}
	}

	return result
}

func cstrchr(s Ptr[byte], c int32) Ptr[byte] {
	var p Ptr[byte]
	var cc int32
	var lc int32

	if rex.reg_ic == 0 {
		return vim_strchr(s, c)
	}

	if c > 0x80 {
		cc = utf_fold(c)
		lc = cc
	} else {
		if vim_isupper(c) != 0 {
			cc = vim_tolower(c)
			lc = cc
		} else if vim_islower(c) != 0 {
			cc = vim_toupper(c)
			lc = c
		} else {
			return vim_strchr(s, c)
		}
	}

	for p = s; p.Get() != NUL; p = p.Add(int(utfc_ptr2len(p))) {
		uc := utf_ptr2char(p)
		if c > 0x80 || uc > 0x80 {
			if (uc < 0x80 || uc != int32(p.Get())) && utf_fold(uc) == lc {
				return p
			}
		} else if int32(p.Get()) == c || int32(p.Get()) == cc {
			return p
		}
	}

	return Ptr[byte]{}
}

func do_upper(d *int32, c int32) {
	*d = vim_toupper(c)
}

func do_lower(d *int32, c int32) {
	*d = vim_tolower(c)
}

func regtilde(source Ptr[byte], magic int32) Ptr[byte] {
	newsub := source
	var p Ptr[byte]
	var newsublen usize = 0
	tilde := Mk[byte](3)
	tilde.Set(0, '~')
	tilde.Set(1, NUL)
	tilde.Set(2, NUL)
	var tildelen usize = 1
	error_ := int32(FALSE)

	if magic == 0 {
		tilde.Set(0, '\\')
		tilde.Set(1, '~')
		tilde.Set(2, NUL)
		tildelen = 2
	}

	for p = newsub; p.Get() != 0; p = p.Add(1) {
		if musl_strncmp(p, tilde, tildelen) == 0 {
			prefixlen := usize(p.Sub(newsub))
			postfix := p.Add(int(tildelen))
			var postfixlen usize
			var tmpsublen usize

			if newsublen == 0 {
				newsublen = musl_strlen(newsub)
			}
			newsublen -= tildelen
			postfixlen = newsublen - prefixlen
			tmpsublen = prefixlen + reg_prev_sublen + postfixlen

			if tmpsublen > 0 && !reg_prev_sub.Nil() {
				var tmpsub Ptr[byte]

				if tmpsublen > MAXCOL {
					emsg(gettext_(e_resulting_text_too_long))
					error_ = TRUE
					break
				}

				tmpsub = Alloc(int(tmpsublen + 1))

				Memmove(tmpsub, newsub, int(prefixlen))
				Memmove(tmpsub.Add(int(prefixlen)), reg_prev_sub, int(reg_prev_sublen))
				musl_strcpy(tmpsub.Add(int(prefixlen+reg_prev_sublen)), postfix)

				newsub = tmpsub
				newsublen = tmpsublen
				p = newsub.Add(int(prefixlen + reg_prev_sublen))
			} else {
				Memmove(p, postfix, int(postfixlen+1))
			}

			p = p.Add(-1)
		} else {
			if p.Get() == '\\' && p.At(1) != 0 {
				p = p.Add(1)
			}
			p = p.Add(int(utfc_ptr2len(p)) - 1)
		}
	}

	if error_ != 0 {
		return source
	}

	newsublen = usize(p.Sub(newsub))
	if newsublen == 0 {
		reg_prev_sub = Ptr[byte]{}
	} else {
		reg_prev_sub = vim_strnsave(newsub, newsublen)
	}

	if reg_prev_sub.Nil() {
		reg_prev_sublen = 0
	} else {
		reg_prev_sublen = newsublen
	}

	return newsub
}

func vim_regsub_multi(rmp *regmmatch_T, lnum linenr_T, source Ptr[byte], dest Ptr[byte], destlen int32, flags int32) int32 {
	var result int32
	var rex_save regexec_T
	rex_in_use_save := rex_in_use

	if rex_in_use != 0 {
		rex_save = rex
	}
	rex_in_use = TRUE

	rex.reg_match = nil
	rex.reg_mmatch = rmp
	rex.reg_buf = curbuf
	rex.reg_firstlnum = lnum
	rex.reg_maxline = curbuf.b_ml.ml_line_count - lnum
	rex.reg_line_lbr = FALSE
	result = vim_regsub_both(source, dest, destlen, flags)

	rex_in_use = rex_in_use_save
	if rex_in_use != 0 {
		rex = rex_save
	}

	return result
}

func vim_regsub_both(source Ptr[byte], dest Ptr[byte], destlen int32, flags int32) int32 {
	var src Ptr[byte]
	var dst Ptr[byte]
	var s Ptr[byte]
	var c int32
	var cc int32
	var no int32 = -1
	var func_all fptr_T = nil
	var func_one fptr_T = nil
	var clnum linenr_T = 0
	var len_ int32 = 0
	copy_ := flags & REGSUB_COPY
	var totlen, charlen, clen, l int32

	if source.Nil() || dest.Nil() {
		iemsg(e_null_argument)
		return 0
	}
	if prog_magic_wrong() != 0 {
		return 0
	}
	src = source
	dst = dest

	if source.At(0) == '\\' && source.At(1) == '=' {
	} else {
		for {
			c = int32(src.Get())
			src = src.Add(1)
			if c == NUL {
				break
			}
			if c == '&' && (flags&REGSUB_MAGIC) != 0 {
				no = 0
			} else if c == '\\' && src.Get() != NUL {
				if src.Get() == '&' && (flags&REGSUB_MAGIC) == 0 {
					src = src.Add(1)
					no = 0
				} else if '0' <= src.Get() && src.Get() <= '9' {
					no = int32(src.Get()) - '0'
					src = src.Add(1)
				} else if !vim_strchr(S("uUlLeE"), int32(src.Get())).Nil() {
					sc := src.Get()
					src = src.Add(1)
					switch sc {
					case 'u':
						func_one = do_upper
						continue
					case 'U':
						func_all = do_upper
						continue
					case 'l':
						func_one = do_lower
						continue
					case 'L':
						func_all = do_lower
						continue
					case 'e', 'E':
						func_all = nil
						func_one = func_all
						continue
					}
				}
			}
			if no < 0 {
				if c == 0x80 && src.At(0) != NUL && src.At(1) != NUL {
					if copy_ != 0 {
						if dst.Add(3).Gt(dest.Add(int(destlen))) {
							iemsg(S("vim_regsub_both(): not enough space"))
							return 0
						}
						dst.Put(byte(c))
						dst = dst.Add(1)
						dst.Put(src.Get())
						dst = dst.Add(1)
						src = src.Add(1)
						dst.Put(src.Get())
						dst = dst.Add(1)
						src = src.Add(1)
					} else {
						dst = dst.Add(3)
						src = src.Add(2)
					}
					continue
				}

				if c == '\\' && src.Get() != NUL {
					switch src.Get() {
					case 'r':
						c = CAR
						src = src.Add(1)
					case 'n':
						c = NL
						src = src.Add(1)
					case 't':
						c = TAB
						src = src.Add(1)
					case 'b':
						c = Ctrl_H
						src = src.Add(1)

					default:
						if (flags & REGSUB_BACKSLASH) != 0 {
							if copy_ != 0 {
								if dst.Add(1).Gt(dest.Add(int(destlen))) {
									iemsg(S("vim_regsub_both(): not enough space"))
									return 0
								}
								dst.Put('\\')
							}
							dst = dst.Add(1)
						}
						c = int32(src.Get())
						src = src.Add(1)
					}
				} else {
					c = utf_ptr2char(src.Add(-1))
				}

				if func_one != nil {
					func_one(&cc, c)
					func_one = nil
				} else if func_all != nil {
					func_all(&cc, c)
				} else {
					cc = c
				}

				totlen = utfc_ptr2len(src.Add(-1))
				charlen = utf_char2len(cc)

				if copy_ != 0 {
					if dst.Add(int(charlen)).Gt(dest.Add(int(destlen))) {
						iemsg(S("vim_regsub_both(): not enough space"))
						return 0
					}
					utf_char2bytes(cc, dst)
				}
				dst = dst.Add(int(charlen) - 1)
				clen = utf_ptr2len(src.Add(-1))

				if clen < totlen {
					if copy_ != 0 {
						if dst.Add(int(totlen - clen)).Gt(dest.Add(int(destlen))) {
							iemsg(S("vim_regsub_both(): not enough space"))
							return 0
						}
						Memmove(dst.Add(1), src.Add(-1+int(clen)), int(totlen-clen))
					}
					dst = dst.Add(int(totlen - clen))
				}
				src = src.Add(int(totlen) - 1)
				dst = dst.Add(1)
			} else {
				if rex.reg_match == nil {
					clnum = rex.reg_mmatch.startpos[no].lnum
					if clnum < 0 || rex.reg_mmatch.endpos[no].lnum < 0 {
						s = Ptr[byte]{}
					} else {
						s = reg_getline(clnum).Add(int(rex.reg_mmatch.startpos[no].col))
						if rex.reg_mmatch.endpos[no].lnum == clnum {
							len_ = rex.reg_mmatch.endpos[no].col - rex.reg_mmatch.startpos[no].col
						} else {
							len_ = int32(reg_getline_len(clnum)) - rex.reg_mmatch.startpos[no].col
						}
					}
				} else {
					s = rex.reg_match.startp[no]
					if rex.reg_match.endp[no].Nil() {
						s = Ptr[byte]{}
					} else {
						len_ = int32(rex.reg_match.endp[no].Sub(s))
					}
				}
				if !s.Nil() {
					for {
						if len_ == 0 {
							if rex.reg_match == nil {
								if rex.reg_mmatch.endpos[no].lnum == clnum {
									break
								}
								if copy_ != 0 {
									if dst.Add(1).Gt(dest.Add(int(destlen))) {
										iemsg(S("vim_regsub_both(): not enough space"))
										return 0
									}
									dst.Put(CAR)
								}
								dst = dst.Add(1)
								clnum++
								s = reg_getline(clnum)
								if rex.reg_mmatch.endpos[no].lnum == clnum {
									len_ = rex.reg_mmatch.endpos[no].col
								} else {
									len_ = int32(reg_getline_len(clnum))
								}
							} else {
								break
							}
						} else if s.Get() == NUL {
							if copy_ != 0 {
								iemsg(e_damaged_match_string)
							}
							goto exit
						} else {
							if (flags&REGSUB_BACKSLASH) != 0 && (s.Get() == CAR || s.Get() == '\\') {
								if copy_ != 0 {
									if dst.Add(2).Gt(dest.Add(int(destlen))) {
										iemsg(S("vim_regsub_both(): not enough space"))
										return 0
									}
									dst.Set(0, '\\')
									dst.Set(1, s.Get())
								}
								dst = dst.Add(2)
							} else {
								c = utf_ptr2char(s)

								if func_one != nil {
									func_one(&cc, c)
									func_one = nil
								} else if func_all != nil {
									func_all(&cc, c)
								} else {
									cc = c
								}

								l = utf_ptr2len(s) - 1

								s = s.Add(int(l))
								len_ -= l
								charlen = utf_char2len(cc)
								if copy_ != 0 {
									if dst.Add(int(charlen)).Gt(dest.Add(int(destlen))) {
										iemsg(S("vim_regsub_both(): not enough space"))
										return 0
									}
									utf_char2bytes(cc, dst)
								}
								dst = dst.Add(int(charlen) - 1)
								dst = dst.Add(1)
							}

							s = s.Add(1)
							len_--
						}
					}
				}
				no = -1
			}
		}
	}
	if copy_ != 0 {
		dst.Put(NUL)
	}

exit:
	return int32(dst.Sub(dest) + 1)
}

// ==== from f13.go ====
// Transpiled by hand from editor.c: init_regexec_multi .. bt_regexec_both.

// reg_calc_size_node is regcode while regcomp only measures the program: a
// byte no real regcode can equal, only ever compared.
var reg_calc_size_node = Mk[byte](1)

// sizeof(regitem_T), sizeof(regstar_T), sizeof(regbehind_T) and
// sizeof(backpos_T): C's x86-64 struct sizes.  The three regexp stacks are
// typed growarrays, but regstack_bytes keeps the byte count C's does -- the
// sum of these sizes over what the stacks hold -- because 'maxmempattern'
// (E363) is measured against it; regstack's itemsize and REGSTACK_INITIAL /
// sizeof(regitem_T) use them too.
const (
	f13_sizeof_regitem   = 40
	f13_sizeof_regstar   = 32
	f13_sizeof_regbehind = 376
	f13_sizeof_backpos   = 32
)

func regstack_star_top() Ptr[S_regstar_S] {
	return GaData[regstar_T](&regstack_star).Add(int(regstack_star.ga_len - 1))
}
func regstack_behind_top() Ptr[S_regbehind_S] {
	return GaData[regbehind_T](&regstack_behind).Add(int(regstack_behind.ga_len - 1))
}

// f13_magic_arg is the `cond ? "" : "\\"` argument of the EMSG2 macros.
func f13_magic_arg(cond bool) Ptr[byte] {
	if cond {
		return S("")
	}
	return S("\\")
}

// f13_emsg_ret_null is EMSG_RET_NULL(m).
func f13_emsg_ret_null(m Ptr[byte]) Ptr[byte] {
	emsg(gettext_(m))
	rc_did_emsg = TRUE
	return Ptr[byte]{}
}

// f13_emsg2_ret_null is EMSG2_RET_NULL(m, cond).
func f13_emsg2_ret_null(m Ptr[byte], cond bool) Ptr[byte] {
	vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(m), f13_magic_arg(cond))
	emsg(iobuff_or(gettext_(m)))
	rc_did_emsg = TRUE
	return Ptr[byte]{}
}

// f13_emsg3_ret_null is EMSG3_RET_NULL(m, cond, c).
func f13_emsg3_ret_null(m Ptr[byte], cond bool, c int32) Ptr[byte] {
	vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(m), f13_magic_arg(cond), c)
	emsg(iobuff_or(gettext_(m)))
	rc_did_emsg = TRUE
	return Ptr[byte]{}
}

// f13_operand_min is OPERAND_MIN(p): the long stored big-endian at p + 3.
func f13_operand_min(p Ptr[byte]) int64 {
	return (int64(p.At(3)) << 24) + (int64(p.At(4)) << 16) + (int64(p.At(5)) << 8) + int64(p.At(6))
}

// f13_ri is ri_digit(c) and its kin: (c < 0x100 && (class_tab[c] & mask)).
func f13_ri(c int32, mask int32) bool {
	return c < 0x100 && int32(class_tab[c])&mask != 0
}

func init_regexec_multi(rmp *regmmatch_T, win *S_window_S, buf *S_file_buffer, lnum linenr_T) {
	rex.reg_match = nil
	rex.reg_mmatch = rmp
	rex.reg_buf = buf
	rex.reg_win = win
	rex.reg_firstlnum = lnum
	rex.reg_maxline = rex.reg_buf.b_ml.ml_line_count - lnum
	rex.reg_line_lbr = FALSE
	rex.reg_ic = rmp.rmm_ic
	rex.reg_icombine = FALSE
	rex.reg_maxcol = rmp.rmm_maxcol
}

func regcomp_start(expr Ptr[byte], re_flags int32) {
	initchr(expr)
	if re_flags&RE_MAGIC != 0 {
		reg_magic = MAGIC_ON
	} else {
		reg_magic = MAGIC_OFF
	}
	reg_string = re_flags & RE_STRING
	reg_strict = re_flags & RE_STRICT
	get_cpo_flags()

	num_complex_braces = 0
	regnpar = 1
	had_endbrace = [10]byte{}
	regsize = 0
	reg_toolong = FALSE
	bt_reg_parse_depth = 0
	regflags = 0
}

func use_multibytecode(c int32) int32 {
	return B2i(utf_char2len(c) > 1 && (re_multi_type(peekchr()) != NOT_MULTI || utf_iscomposing(c) != 0))
}

func regc(b int32) {
	if regcode == reg_calc_size_node {
		regsize++
	} else {
		regcode.Put(byte(b))
		regcode = regcode.Add(1)
	}
}

func regmbc(c int32) {
	if regcode == reg_calc_size_node {
		regsize += int64(utf_char2len(c))
	} else {
		regcode = regcode.Add(int(utf_char2bytes(c, regcode)))
	}
}

func regnode(op int32) Ptr[byte] {
	var ret Ptr[byte]

	ret = regcode
	if ret == reg_calc_size_node {
		regsize += 3
	} else {
		regcode.Put(byte(op))
		regcode = regcode.Add(1)
		regcode.Put(NUL)
		regcode = regcode.Add(1)
		regcode.Put(NUL)
		regcode = regcode.Add(1)
	}
	return ret
}

func re_put_long(p Ptr[byte], val long_u) Ptr[byte] {
	p.Put(byte((val >> 24) & 0377))
	p = p.Add(1)
	p.Put(byte((val >> 16) & 0377))
	p = p.Add(1)
	p.Put(byte((val >> 8) & 0377))
	p = p.Add(1)
	p.Put(byte(val & 0377))
	p = p.Add(1)
	return p
}

func regnext(p Ptr[byte]) Ptr[byte] {
	var offset int32

	if p == reg_calc_size_node || reg_toolong != 0 {
		return Ptr[byte]{}
	}

	offset = ((int32(p.At(1)) & 0377) << 8) + (int32(p.At(2)) & 0377)
	if offset == 0 {
		return Ptr[byte]{}
	}

	if int32(p.Get()) == BACK {
		return p.Add(-int(offset))
	} else {
		return p.Add(int(offset))
	}
}

func regtail(p Ptr[byte], val Ptr[byte]) {
	var scan Ptr[byte]
	var temp Ptr[byte]
	var offset int32

	if p == reg_calc_size_node {
		return
	}

	scan = p
	for {
		temp = regnext(scan)
		if temp.Nil() {
			break
		}
		scan = temp
	}

	if int32(scan.Get()) == BACK {
		offset = int32(scan.Sub(val))
	} else {
		offset = int32(val.Sub(scan))
	}
	if offset > 0xffff {
		reg_toolong = TRUE
	} else {
		scan.Set(1, byte((uint32(offset)>>8)&0377))
		scan.Set(2, byte(offset&0377))
	}
}

func regoptail(p Ptr[byte], val Ptr[byte]) {
	if p.Nil() || p == reg_calc_size_node || (int32(p.Get()) != BRANCH && (int32(p.Get()) < BRACE_COMPLEX || int32(p.Get()) > BRACE_COMPLEX+9)) {
		return
	}
	regtail(p.Add(3), val)
}

func reginsert(op int32, opnd Ptr[byte]) {
	var src Ptr[byte]
	var dst Ptr[byte]
	var place Ptr[byte]

	if regcode == reg_calc_size_node {
		regsize += 3
		return
	}
	src = regcode
	regcode = regcode.Add(3)
	dst = regcode
	for src.Gt(opnd) {
		dst = dst.Add(-1)
		src = src.Add(-1)
		dst.Put(src.Get())
	}

	place = opnd
	place.Put(byte(op))
	place = place.Add(1)
	place.Put(NUL)
	place = place.Add(1)
	place.Put(NUL)
}

func reginsert_nr(op int32, val int64, opnd Ptr[byte]) {
	var src Ptr[byte]
	var dst Ptr[byte]
	var place Ptr[byte]

	if regcode == reg_calc_size_node {
		regsize += 7
		return
	}
	src = regcode
	regcode = regcode.Add(7)
	dst = regcode
	for src.Gt(opnd) {
		dst = dst.Add(-1)
		src = src.Add(-1)
		dst.Put(src.Get())
	}

	place = opnd
	place.Put(byte(op))
	place = place.Add(1)
	place.Put(NUL)
	place = place.Add(1)
	place.Put(NUL)
	place = place.Add(1)
	re_put_long(place, long_u(val))
}

func reginsert_limits(op int32, minval int64, maxval int64, opnd Ptr[byte]) {
	var src Ptr[byte]
	var dst Ptr[byte]
	var place Ptr[byte]

	if regcode == reg_calc_size_node {
		regsize += 11
		return
	}
	src = regcode
	regcode = regcode.Add(11)
	dst = regcode
	for src.Gt(opnd) {
		dst = dst.Add(-1)
		src = src.Add(-1)
		dst.Put(src.Get())
	}

	place = opnd
	place.Put(byte(op))
	place = place.Add(1)
	place.Put(NUL)
	place = place.Add(1)
	place.Put(NUL)
	place = place.Add(1)
	place = re_put_long(place, long_u(minval))
	place = re_put_long(place, long_u(maxval))
	regtail(opnd, place)
}

func seen_endbrace(refnum int32) int32 {
	if had_endbrace[refnum] == 0 {
		var p Ptr[byte]

		for p = regparse; p.Get() != NUL; p = p.Add(1) {
			if p.At(0) == '@' && p.At(1) == '<' && (p.At(2) == '!' || p.At(2) == '=') {
				break
			}
		}
		if p.Get() == NUL {
			emsg(gettext_(e_illegal_back_reference))
			rc_did_emsg = TRUE
			return FALSE
		}
	}
	return TRUE
}

func regatom_delim(c int32, delim_nl int32, flagp *int32) Ptr[byte] {
	var ret Ptr[byte]

	var base int32 = F_PCLOSE
	var idx int32

	if c == 'f' || c == 't' {
		if c == 't' {
			base = T_PCLOSE
		}
		c = no_Magic(getchr())
	}
	switch c {
	case ')':
		idx = 0
	case ']':
		idx = 1
	case '}':
		idx = 2
	case '>':
		idx = 3
	default:
		var bsl Ptr[byte]
		if reg_magic == MAGIC_ALL {
			bsl = S("")
		} else {
			bsl = S("\\")
		}
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_character_after_str), bsl)
		emsg(iobuff_or(gettext_(e_invalid_character_after_str)))
		rc_did_emsg = TRUE
		return Ptr[byte]{}
	}
	if delim_nl != 0 {
		idx += DELIM_NL
		*flagp |= HASNL
	}
	ret = regnode(base + idx)

	if base == F_PCLOSE {
		*flagp |= HASWIDTH
	}
	return ret
}

func regatom(flagp *int32) Ptr[byte] {
	var ret Ptr[byte]
	var flags int32
	var c int32
	var sw int32
	var p Ptr[byte]
	var extra int32 = 0
	var delim_nl int32 = FALSE
	var save_prev_at_start int32 = prev_at_start

	*flagp = WORST

	c = getchr()
	sw = c
	for {
		switch sw {
		case '^' - 256:
			ret = regnode(BOL)

		case '$' - 256:
			ret = regnode(EOL)

		case '<' - 256:
			ret = regnode(BOW)

		case '>' - 256:
			ret = regnode(EOW)

		case '_' - 256:
			c = no_Magic(getchr())
			if c == '%' {
				delim_nl = TRUE
				c = no_Magic(getchr())
				if c == ')' || c == ']' || c == '}' || c == '>' || c == 'f' || c == 't' {
					ret = regatom_delim(c, delim_nl, flagp)
					if ret.Nil() {
						return Ptr[byte]{}
					}
					break
				}
				return f13_emsg2_ret_null(e_invalid_character_after_str, reg_magic == MAGIC_ALL)
			}
			if c == '^' {
				ret = regnode(BOL)
				break
			}
			if c == '$' {
				ret = regnode(EOL)
				break
			}

			extra = ADD_NL
			*flagp |= HASNL

			if c == '[' {
				sw = '[' - 256
				continue
			}
			fallthrough

		case '.' - 256, 'i' - 256, 'I' - 256, 'k' - 256, 'K' - 256, 'f' - 256, 'F' - 256,
			'p' - 256, 'P' - 256, 's' - 256, 'S' - 256, 'd' - 256, 'D' - 256, 'x' - 256,
			'X' - 256, 'o' - 256, 'O' - 256, 'w' - 256, 'W' - 256, 'h' - 256, 'H' - 256,
			'a' - 256, 'A' - 256, 'l' - 256, 'L' - 256, 'u' - 256, 'U' - 256:
			p = vim_strchr(classchars, no_Magic(c))
			if p.Nil() {
				return f13_emsg_ret_null(e_invalid_use_of_underscore)
			}

			if c == '.'-256 && utf_iscomposing(peekchr()) != 0 {
				c = getchr()
				ret = regnode(MULTIBYTECODE)
				regmbc(c)
				*flagp |= HASWIDTH | SIMPLE
				break
			}
			ret = regnode(classcodes[p.Sub(classchars)] + extra)
			*flagp |= HASWIDTH | SIMPLE

		case 'n' - 256:
			if reg_string != 0 {
				ret = regnode(EXACTLY)
				regc(NL)
				regc(NUL)
				*flagp |= HASWIDTH | SIMPLE
			} else {
				ret = regnode(NEWL)
				*flagp |= HASWIDTH | HASNL
			}

		case '(' - 256:
			if one_exactly != 0 {
				return f13_emsg2_ret_null(e_invalid_item_in_str_brackets, reg_magic == MAGIC_ALL)
			}
			ret = reg(REG_PAREN, &flags)
			if ret.Nil() {
				return Ptr[byte]{}
			}
			*flagp |= flags & (HASWIDTH | SPSTART | HASNL | HASLOOKBH)

		case NUL, '|' - 256, '&' - 256, ')' - 256:
			if one_exactly != 0 {
				return f13_emsg2_ret_null(e_invalid_item_in_str_brackets, reg_magic == MAGIC_ALL)
			}
			iemsg(e_internal_error_in_regexp)
			rc_did_emsg = TRUE
			return Ptr[byte]{}

		case '=' - 256, '?' - 256, '+' - 256, '@' - 256, '{' - 256, '*' - 256:
			c = no_Magic(c)
			var cond bool
			if c == '*' {
				cond = reg_magic >= MAGIC_ON
			} else {
				cond = reg_magic == MAGIC_ALL
			}
			return f13_emsg3_ret_null(e_str_chr_follows_nothing, cond, c)

		case '~' - 256:
			if !reg_prev_sub.Nil() {
				var lp Ptr[byte]

				ret = regnode(EXACTLY)
				lp = reg_prev_sub
				for lp.Get() != NUL {
					ch := lp.Get()
					lp = lp.Add(1)
					regc(int32(ch))
				}
				regc(NUL)
				if reg_prev_sub.Get() != NUL {
					*flagp |= HASWIDTH
					if lp.Sub(reg_prev_sub) == 1 {
						*flagp |= SIMPLE
					}
				}
			} else {
				return f13_emsg_ret_null(e_no_previous_substitute_regular_expression)
			}

		case '1' - 256, '2' - 256, '3' - 256, '4' - 256, '5' - 256, '6' - 256, '7' - 256, '8' - 256, '9' - 256:
			{
				var refnum int32

				refnum = c - ('0' - 256)
				if seen_endbrace(refnum) == 0 {
					return Ptr[byte]{}
				}
				ret = regnode(BACKREF + refnum)
			}

		case 'z' - 256:
			c = no_Magic(getchr())
			switch c {
			case 's':
				ret = regnode(MOPEN + 0)
				if re_mult_next(S("\\zs")) == FAIL {
					return Ptr[byte]{}
				}

			case 'e':
				ret = regnode(MCLOSE + 0)
				if re_mult_next(S("\\ze")) == FAIL {
					return Ptr[byte]{}
				}

			default:
				return f13_emsg_ret_null(e_invalid_character_after_bsl_z)
			}

		case '%' - 256:
			c = no_Magic(getchr())
			switch c {
			case '(':
				if one_exactly != 0 {
					return f13_emsg2_ret_null(e_invalid_item_in_str_brackets, reg_magic == MAGIC_ALL)
				}
				ret = reg(REG_NPAREN, &flags)
				if ret.Nil() {
					return Ptr[byte]{}
				}
				*flagp |= flags & (HASWIDTH | SPSTART | HASNL | HASLOOKBH)

			case '^':
				ret = regnode(RE_BOF)

			case '$':
				ret = regnode(RE_EOF)

			case '#':
				if regparse.At(0) == '=' && regparse.At(1) >= 48 && regparse.At(1) <= 50 {
					vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_atom_engine_must_be_at_start_of_pattern), int32(regparse.At(1)))
					emsg(iobuff_or(gettext_(e_atom_engine_must_be_at_start_of_pattern)))
					return Ptr[byte]{} // C: return FAIL (0) from a char_u * function
				}
				ret = regnode(CURSOR)

			case 'V':
				ret = regnode(RE_VISUAL)

			case 'C':
				ret = regnode(RE_COMPOSING)

			case '[':
				if one_exactly != 0 {
					return f13_emsg2_ret_null(e_invalid_item_in_str_brackets, reg_magic == MAGIC_ALL)
				}
				{
					var lastbranch Ptr[byte]
					var lastnode Ptr[byte]
					var br Ptr[byte]

					ret = Ptr[byte]{}
					for {
						c = getchr()
						if c == ']' {
							break
						}
						if c == NUL {
							return f13_emsg2_ret_null(e_missing_sb_after_str, reg_magic == MAGIC_ALL)
						}
						br = regnode(BRANCH)
						if ret.Nil() {
							ret = br
						} else {
							regtail(lastnode, br)
							if reg_toolong != 0 {
								return Ptr[byte]{}
							}
						}

						ungetchr()
						one_exactly = TRUE
						lastnode = regatom(flagp)
						one_exactly = FALSE
						if lastnode.Nil() {
							return Ptr[byte]{}
						}
					}
					if ret.Nil() {
						return f13_emsg2_ret_null(e_empty_str_brackets, reg_magic == MAGIC_ALL)
					}
					lastbranch = regnode(BRANCH)
					br = regnode(NOTHING)
					if ret != reg_calc_size_node {
						regtail(lastnode, br)
						regtail(lastbranch, br)
						for br = ret; br != lastnode; {
							if int32(br.Get()) == BRANCH {
								regtail(br, lastbranch)
								if reg_toolong != 0 {
									return Ptr[byte]{}
								}
								br = br.Add(3)
							} else {
								br = regnext(br)
							}
						}
					}
					*flagp &^= HASWIDTH | SIMPLE
				}

			case 'd', 'o', 'x', 'u', 'U':
				{
					var i vimlong_T

					switch c {
					case 'd':
						i = getdecchrs()
					case 'o':
						i = getoctchrs()
					case 'x':
						i = gethexchrs(2)
					case 'u':
						i = gethexchrs(4)
					case 'U':
						i = gethexchrs(8)
					default:
						i = -1
					}

					if i < 0 || i > INT_MAX {
						return f13_emsg2_ret_null(e_invalid_character_after_str_2, reg_magic == MAGIC_ALL)
					}
					if use_multibytecode(int32(i)) != 0 {
						ret = regnode(MULTIBYTECODE)
					} else {
						ret = regnode(EXACTLY)
					}
					if i == 0 {
						regc(0x0a)
					} else {
						regmbc(int32(i))
					}
					regc(NUL)
					*flagp |= HASWIDTH
				}

			case ')', ']', '}', 'f', 't':
				ret = regatom_delim(c, delim_nl, flagp)
				if ret.Nil() {
					return Ptr[byte]{}
				}

			case '>':
				if !(uint32(regparse.Get())-'0' < 10) && regparse.Get() != '\'' && regparse.Get() != '.' {
					ret = regatom_delim(c, delim_nl, flagp)
					if ret.Nil() {
						return Ptr[byte]{}
					}
					break
				}
				fallthrough
			default:
				if uint32(c)-'0' < 10 || c == '<' || c == '>' || c == '\'' || c == '.' {
					var n long_u = 0
					var cmp int32
					var cur int32 = FALSE
					var got_digit int32 = FALSE

					cmp = c
					if cmp == '<' || cmp == '>' {
						c = getchr()
					}
					if no_Magic(c) == '.' {
						cur = TRUE
						c = getchr()
					}
					for uint32(c)-'0' < 10 {
						got_digit = TRUE
						n = n*10 + long_u(c-'0')
						c = getchr()
					}
					if no_Magic(c) == '\'' && n == 0 {
						c = getchr()
						ret = regnode(RE_MARK)
						if ret == reg_calc_size_node {
							regsize += 2
						} else {
							regcode.Put(byte(c))
							regcode = regcode.Add(1)
							regcode.Put(byte(cmp))
							regcode = regcode.Add(1)
						}
						break
					} else if (c == 'l' || c == 'c' || c == 'v') && (cur != 0 || got_digit != 0) {
						if cur != 0 && n != 0 {
							vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_regexp_number_after_dot_pos_search_chr), no_Magic(c))
							emsg(iobuff_or(gettext_(e_regexp_number_after_dot_pos_search_chr)))
							rc_did_emsg = TRUE
							return Ptr[byte]{}
						}
						if c == 'l' {
							if cur != 0 {
								n = long_u(curwin.w_cursor.lnum)
							}
							ret = regnode(RE_LNUM)
							if save_prev_at_start != 0 {
								at_start = TRUE
							}
						} else if c == 'c' {
							if cur != 0 {
								n = long_u(curwin.w_cursor.col)
								n++
							}
							ret = regnode(RE_COL)
						} else {
							if cur != 0 {
								var vcol colnr_T = 0

								getvvcol(curwin, &curwin.w_cursor, nil, nil, &vcol, 0)
								vcol++
								n = long_u(vcol)
							}
							ret = regnode(RE_VCOL)
						}
						if ret == reg_calc_size_node {
							regsize += 5
						} else {
							regcode = re_put_long(regcode, n)
							regcode.Put(byte(cmp))
							regcode = regcode.Add(1)
						}
						break
					}
				}

				return f13_emsg2_ret_null(e_invalid_character_after_str, reg_magic == MAGIC_ALL)
			}

		case '[' - 256:
			{
				var lp Ptr[byte]

				lp = skip_anyof(regparse)
				if lp.Get() == ']' {
					var startc int32 = -1
					var endc int32

					if regparse.Get() == '^' {
						ret = regnode(ANYBUT + extra)
						regparse = regparse.Add(1)
					} else {
						ret = regnode(ANYOF + extra)
					}

					if regparse.Get() == ']' || regparse.Get() == '-' {
						startc = int32(regparse.Get())
						ch := regparse.Get()
						regparse = regparse.Add(1)
						regc(int32(ch))
					}

					for regparse.Get() != NUL && regparse.Get() != ']' {
						if regparse.Get() == '-' {
							regparse = regparse.Add(1)
							if regparse.Get() == ']' || regparse.Get() == NUL || startc == -1 || (regparse.At(0) == '\\' && regparse.At(1) == 'n') {
								regc('-')
								startc = '-'
							} else {
								endc = 0
								if regparse.Get() == '[' {
									endc = get_coll_element(&regparse)
								}
								if endc == 0 {
									endc = mb_ptr2char_adv(&regparse)
								}

								if endc == '\\' && reg_cpo_lit == 0 && reg_cpo_bsl == 0 {
									endc = coll_get_char()
								}

								if startc > endc {
									return f13_emsg_ret_null(e_reverse_range_in_character_class)
								}
								if utf_char2len(startc) > 1 || utf_char2len(endc) > 1 {
									if endc > startc+256 {
										return f13_emsg_ret_null(e_range_too_large_in_character_class)
									}
									for {
										startc++
										if !(startc <= endc) {
											break
										}
										regmbc(startc)
									}
								} else {
									for {
										startc++
										if !(startc <= endc) {
											break
										}
										regc(startc)
									}
								}
								startc = -1
							}
						} else if regparse.Get() == '\\' && reg_cpo_bsl == 0 && (!vim_strchr(REGEXP_INRANGE, int32(regparse.At(1))).Nil() || (reg_cpo_lit == 0 && !vim_strchr(REGEXP_ABBR, int32(regparse.At(1))).Nil())) {
							regparse = regparse.Add(1)
							if regparse.Get() == 'n' {
								if ret != reg_calc_size_node {
									if int32(ret.Get()) == ANYOF {
										ret.Put(ANYOF + ADD_NL)
										*flagp |= HASNL
									}
								}
								regparse = regparse.Add(1)
								startc = -1
							} else if regparse.Get() == 'd' || regparse.Get() == 'o' || regparse.Get() == 'x' || regparse.Get() == 'u' || regparse.Get() == 'U' {
								startc = coll_get_char()
								if startc == INT_MAX {
									return f13_emsg_ret_null(e_unicode_val_too_large)
								}
								if startc == 0 {
									regc(0x0a)
								} else {
									regmbc(startc)
								}
							} else {
								ch := regparse.Get()
								regparse = regparse.Add(1)
								startc = backslash_trans(int32(ch))
								regc(startc)
							}
						} else if regparse.Get() == '[' {
							var c_class int32
							var cu int32

							c_class = get_char_class(&regparse)
							startc = -1
							switch c_class {
							case CLASS_NONE:
								c_class = get_coll_element(&regparse)
								if c_class != 0 {
									regmbc(c_class)
								} else {
									startc = int32(regparse.Get())
									regparse = regparse.Add(1)
									regc(startc)
								}
							case CLASS_ALNUM:
								for cu = 1; cu < 128; cu++ {
									if musl_isalnum(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_ALPHA:
								for cu = 1; cu < 128; cu++ {
									if musl_isalpha(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_BLANK:
								regc(' ')
								regc('\t')
							case CLASS_CNTRL:
								for cu = 1; cu <= 127; cu++ {
									if musl_iscntrl(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_DIGIT:
								for cu = 1; cu <= 127; cu++ {
									if uint32(cu)-'0' < 10 {
										regmbc(cu)
									}
								}
							case CLASS_GRAPH:
								for cu = 1; cu <= 127; cu++ {
									if musl_isgraph(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_LOWER:
								for cu = 1; cu <= 255; cu++ {
									if vim_islower(cu) != 0 && cu != 170 && cu != 186 {
										regmbc(cu)
									}
								}
							case CLASS_PRINT:
								for cu = 1; cu <= 255; cu++ {
									if vim_isprintc(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_PUNCT:
								for cu = 1; cu < 128; cu++ {
									if musl_ispunct(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_SPACE:
								for cu = 9; cu <= 13; cu++ {
									regc(cu)
								}
								regc(' ')
							case CLASS_UPPER:
								for cu = 1; cu <= 255; cu++ {
									if vim_isupper(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_XDIGIT:
								for cu = 1; cu <= 255; cu++ {
									if vim_isxdigit(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_TAB:
								regc('\t')
							case CLASS_RETURN:
								regc('\r')
							case CLASS_BACKSPACE:
								regc('\b')
							case CLASS_ESCAPE:
								regc('\033')
							case CLASS_IDENT:
								for cu = 1; cu <= 255; cu++ {
									if vim_isIDc(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_KEYWORD:
								for cu = 1; cu <= 255; cu++ {
									if reg_iswordc(cu) != 0 {
										regmbc(cu)
									}
								}
							case CLASS_FNAME:
								for cu = 1; cu <= 255; cu++ {
									if vim_isfilec(cu) != 0 {
										regmbc(cu)
									}
								}
							}
						} else {
							var len_ int32

							startc = utf_ptr2char(regparse)
							len_ = utfc_ptr2len(regparse)
							if utf_char2len(startc) != len_ {
								startc = -1
							}
							for {
								len_--
								if !(len_ >= 0) {
									break
								}
								ch := regparse.Get()
								regparse = regparse.Add(1)
								regc(int32(ch))
							}
						}
					}
					regc(NUL)
					prevchr_len = 1
					if regparse.Get() != ']' {
						return f13_emsg_ret_null(e_too_many_brackets)
					}
					skipchr()
					*flagp |= HASWIDTH | SIMPLE
					break
				} else if reg_strict != 0 {
					return f13_emsg2_ret_null(e_missing_rsb_after_str_lsb, reg_magic > MAGIC_OFF)
				}
			}
			fallthrough

		default:
			{
				var len_ int32

				if use_multibytecode(c) != 0 {
					ret = regnode(MULTIBYTECODE)
					regmbc(c)
					*flagp |= HASWIDTH | SIMPLE
					break
				}

				ret = regnode(EXACTLY)

				for len_ = 0; c != NUL && (len_ == 0 || (re_multi_type(peekchr()) == NOT_MULTI && one_exactly == 0 && !(c < 0))); len_++ {
					c = no_Magic(c)
					regmbc(c)
					var l int32

					for {
						l = utf_ptr2len(regparse)
						if utf_iscomposing(utf_ptr2char(regparse.Add(int(l)))) == 0 {
							break
						}
						regmbc(utf_ptr2char(regparse))
						skipchr()
					}
					c = getchr()
				}
				ungetchr()

				regc(NUL)
				*flagp |= HASWIDTH
				if len_ == 1 {
					*flagp |= SIMPLE
				}
			}
		}
		break
	}

	return ret
}

func regpiece(flagp *int32) Ptr[byte] {
	var ret Ptr[byte]
	var op int32
	var next Ptr[byte]
	var flags int32
	var minval int64
	var maxval int64

	ret = regatom(&flags)
	if ret.Nil() {
		return Ptr[byte]{}
	}

	op = peekchr()
	if re_multi_type(op) == NOT_MULTI {
		*flagp = flags
		return ret
	}
	*flagp = WORST | SPSTART | (flags & (HASNL | HASLOOKBH))

	skipchr()
	switch op {
	case '*' - 256:
		if flags&SIMPLE != 0 {
			reginsert(STAR, ret)
		} else {
			reginsert(BRANCH, ret)
			regoptail(ret, regnode(BACK))
			regoptail(ret, ret)
			regtail(ret, regnode(BRANCH))
			regtail(ret, regnode(NOTHING))
		}

	case '+' - 256:
		if flags&SIMPLE != 0 {
			reginsert(PLUS, ret)
		} else {
			next = regnode(BRANCH)
			regtail(ret, next)
			regtail(regnode(BACK), ret)
			regtail(next, regnode(BRANCH))
			regtail(ret, regnode(NOTHING))
		}
		*flagp = WORST | HASWIDTH | (flags & (HASNL | HASLOOKBH))

	case '@' - 256:
		{
			var lop int32 = END
			var nr int64

			nr = int64(getdecchrs())
			switch no_Magic(getchr()) {
			case '=':
				lop = MATCH
			case '!':
				lop = NOMATCH
			case '>':
				lop = SUBPAT
			case '<':
				switch no_Magic(getchr()) {
				case '=':
					lop = BEHIND
				case '!':
					lop = NOBEHIND
				}
			}
			if lop == END {
				return f13_emsg2_ret_null(e_invalid_character_after_str_at, reg_magic == MAGIC_ALL)
			}
			if lop == BEHIND || lop == NOBEHIND {
				regtail(ret, regnode(BHPOS))
				*flagp |= HASLOOKBH
			}
			regtail(ret, regnode(END))
			if lop == BEHIND || lop == NOBEHIND {
				if nr < 0 {
					nr = 0
				}
				reginsert_nr(lop, nr, ret)
			} else {
				reginsert(lop, ret)
			}
		}

	case '?' - 256, '=' - 256:
		reginsert(BRANCH, ret)
		regtail(ret, regnode(BRANCH))
		next = regnode(NOTHING)
		regtail(ret, next)
		regoptail(ret, next)

	case '{' - 256:
		if read_limits(&minval, &maxval) == 0 {
			return Ptr[byte]{}
		}
		if flags&SIMPLE != 0 {
			reginsert(BRACE_SIMPLE, ret)
			reginsert_limits(BRACE_LIMITS, minval, maxval, ret)
		} else {
			if num_complex_braces >= 10 {
				return f13_emsg2_ret_null(e_too_many_complex_str_curly, reg_magic == MAGIC_ALL)
			}
			reginsert(BRACE_COMPLEX+num_complex_braces, ret)
			regoptail(ret, regnode(BACK))
			regoptail(ret, ret)
			reginsert_limits(BRACE_LIMITS, minval, maxval, ret)
			num_complex_braces++
		}
		if minval > 0 && maxval > 0 {
			*flagp = HASWIDTH | (flags & (HASNL | HASLOOKBH))
		}
	}
	if re_multi_type(peekchr()) != NOT_MULTI {
		if peekchr() == '*'-256 {
			return f13_emsg2_ret_null(e_nested_str, reg_magic >= MAGIC_ON)
		}
		return f13_emsg3_ret_null(e_nested_str_chr, reg_magic == MAGIC_ALL, no_Magic(peekchr()))
	}

	return ret
}

func regconcat(flagp *int32) Ptr[byte] {
	var first Ptr[byte]
	var chain Ptr[byte]
	var latest Ptr[byte]
	var flags int32
	var cont int32 = TRUE

	*flagp = WORST

	for cont != 0 {
		switch peekchr() {
		case NUL, '|' - 256, '&' - 256, ')' - 256:
			cont = FALSE
		case 'Z' - 256:
			regflags |= RF_ICOMBINE
			skipchr_keepstart()
		case 'c' - 256:
			regflags |= RF_ICASE
			skipchr_keepstart()
		case 'C' - 256:
			regflags |= RF_NOICASE
			skipchr_keepstart()
		case 'v' - 256:
			reg_magic = MAGIC_ALL
			skipchr_keepstart()
			curchr = -1
		case 'm' - 256:
			reg_magic = MAGIC_ON
			skipchr_keepstart()
			curchr = -1
		case 'M' - 256:
			reg_magic = MAGIC_OFF
			skipchr_keepstart()
			curchr = -1
		case 'V' - 256:
			reg_magic = MAGIC_NONE
			skipchr_keepstart()
			curchr = -1
		default:
			latest = regpiece(&flags)
			if latest.Nil() || reg_toolong != 0 {
				return Ptr[byte]{}
			}
			*flagp |= flags & (HASWIDTH | HASNL | HASLOOKBH)
			if chain.Nil() {
				*flagp |= flags & SPSTART
			} else {
				regtail(chain, latest)
			}
			chain = latest
			if first.Nil() {
				first = latest
			}
		}
	}
	if first.Nil() {
		first = regnode(NOTHING)
	}
	return first
}

func regbranch(flagp *int32) Ptr[byte] {
	var ret Ptr[byte]
	var chain Ptr[byte]
	var latest Ptr[byte]
	var flags int32

	*flagp = WORST | HASNL

	ret = regnode(BRANCH)
	for {
		latest = regconcat(&flags)
		if latest.Nil() {
			return Ptr[byte]{}
		}
		*flagp |= flags & (HASWIDTH | SPSTART | HASLOOKBH)
		*flagp &= ^HASNL | (flags & HASNL)
		if !chain.Nil() {
			regtail(chain, latest)
		}
		if peekchr() != '&'-256 {
			break
		}
		skipchr()
		regtail(latest, regnode(END))
		if reg_toolong != 0 {
			break
		}
		reginsert(MATCH, latest)
		chain = latest
	}

	return ret
}

func reg(paren int32, flagp *int32) Ptr[byte] {
	var ret Ptr[byte]
	var br Ptr[byte]
	var ender Ptr[byte]
	var parno int32 = 0
	var flags int32
	var endop int32

	*flagp = HASWIDTH

	if paren == REG_PAREN {
		if regnpar >= NSUBEXP {
			return f13_emsg2_ret_null(e_too_many_str_open, reg_magic == MAGIC_ALL)
		}
		parno = regnpar
		regnpar++
		ret = regnode(MOPEN + parno)
	} else if paren == REG_NPAREN {
		ret = regnode(NOPEN)
	} else {
		ret = Ptr[byte]{}
	}

	if bt_reg_parse_depth >= REG_MAX_PAREN_DEPTH {
		return f13_emsg_ret_null(e_command_too_complex)
	}
	bt_reg_parse_depth++

	br = regbranch(&flags)
	if br.Nil() {
		ret = Ptr[byte]{}
		goto theend
	}
	if !ret.Nil() {
		regtail(ret, br)
	} else {
		ret = br
	}
	if flags&HASWIDTH == 0 {
		*flagp &^= HASWIDTH
	}
	*flagp |= flags & (SPSTART | HASNL | HASLOOKBH)
	for peekchr() == '|'-256 {
		skipchr()
		br = regbranch(&flags)
		if br.Nil() || reg_toolong != 0 {
			ret = Ptr[byte]{}
			goto theend
		}
		regtail(ret, br)
		if flags&HASWIDTH == 0 {
			*flagp &^= HASWIDTH
		}
		*flagp |= flags & (SPSTART | HASNL | HASLOOKBH)
	}

	if paren == REG_PAREN {
		endop = MCLOSE + parno
	} else if paren == REG_NPAREN {
		endop = NCLOSE
	} else {
		endop = END
	}
	ender = regnode(endop)
	regtail(ret, ender)

	for br = ret; !br.Nil(); br = regnext(br) {
		regoptail(br, ender)
	}

	if paren != REG_NOPAREN && getchr() != ')'-256 {
		if paren == REG_NPAREN {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_unmatched_str_percent_open), f13_magic_arg(reg_magic == MAGIC_ALL))
			emsg(iobuff_or(gettext_(e_unmatched_str_percent_open)))
			rc_did_emsg = TRUE
			ret = Ptr[byte]{}
			goto theend
		} else {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_unmatched_str_open), f13_magic_arg(reg_magic == MAGIC_ALL))
			emsg(iobuff_or(gettext_(e_unmatched_str_open)))
			rc_did_emsg = TRUE
			ret = Ptr[byte]{}
			goto theend
		}
	} else if paren == REG_NOPAREN && peekchr() != NUL {
		if curchr == ')'-256 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_unmatched_str_close), f13_magic_arg(reg_magic == MAGIC_ALL))
			emsg(iobuff_or(gettext_(e_unmatched_str_close)))
			rc_did_emsg = TRUE
			ret = Ptr[byte]{}
			goto theend
		} else {
			emsg(gettext_(e_trailing_characters))
			rc_did_emsg = TRUE
			ret = Ptr[byte]{}
			goto theend
		}
	}
	if paren == REG_PAREN {
		had_endbrace[parno] = TRUE
	}

theend:
	bt_reg_parse_depth--
	return ret
}

func bt_regcomp(expr Ptr[byte], re_flags int32) *S_regprog {
	var r *S_regprog
	var scan Ptr[byte]
	var longest Ptr[byte]
	var len_ int32
	var flags int32

	if expr.Nil() {
		iemsg(e_null_argument)
		rc_did_emsg = TRUE
		return nil
	}

	init_class_tab()

	regcomp_start(expr, re_flags)
	regcode = reg_calc_size_node
	regc(REGMAGIC)
	if reg(REG_NOPAREN, &flags).Nil() {
		return nil
	}

	r = new(S_regprog)
	r.program = Mk[byte](int(regsize))
	r.re_in_use = FALSE

	regcomp_start(expr, re_flags)
	regcode = r.program
	regc(REGMAGIC)
	if reg(REG_NOPAREN, &flags).Nil() || reg_toolong != 0 {
		if reg_toolong != 0 {
			emsg(gettext_(e_pattern_too_long))
			rc_did_emsg = TRUE
			return nil
		}
		return nil
	}

	r.regstart = NUL
	r.reganch = 0
	r.regmust = Ptr[byte]{}
	r.regmlen = 0
	r.regflags = regflags
	if flags&HASNL != 0 {
		r.regflags |= RF_HASNL
	}
	if flags&HASLOOKBH != 0 {
		r.regflags |= RF_LOOKBH
	}
	scan = r.program.Add(1)
	if int32(regnext(scan).Get()) == END {
		scan = scan.Add(3)

		if int32(scan.Get()) == BOL || int32(scan.Get()) == RE_BOF {
			r.reganch++
			scan = regnext(scan)
		}

		if int32(scan.Get()) == EXACTLY {
			r.regstart = utf_ptr2char(scan.Add(3))
		} else if (int32(scan.Get()) == BOW || int32(scan.Get()) == EOW || int32(scan.Get()) == NOTHING || int32(scan.Get()) == MOPEN+0 || int32(scan.Get()) == NOPEN || int32(scan.Get()) == MCLOSE+0 || int32(scan.Get()) == NCLOSE) && int32(regnext(scan).Get()) == EXACTLY {
			r.regstart = utf_ptr2char(regnext(scan).Add(3))
		}

		if (flags&SPSTART != 0 || int32(scan.Get()) == BOW || int32(scan.Get()) == EOW) && flags&HASNL == 0 {
			var scanlen usize

			longest = Ptr[byte]{}
			len_ = 0
			for ; !scan.Nil(); scan = regnext(scan) {
				if int32(scan.Get()) == EXACTLY {
					scanlen = musl_strlen(scan.Add(3))
					if scanlen >= usize(len_) {
						longest = scan.Add(3)
						len_ = int32(scanlen)
					}
				}
			}
			r.regmust = longest
			r.regmlen = len_
		}
	}
	return r
}

func coll_get_char() int32 {
	var nr vimlong_T = -1

	ch := regparse.Get()
	regparse = regparse.Add(1)
	switch ch {
	case 'd':
		nr = getdecchrs()
	case 'o':
		nr = getoctchrs()
	case 'x':
		nr = gethexchrs(2)
	case 'u':
		nr = gethexchrs(4)
	case 'U':
		nr = gethexchrs(8)
	}
	if nr < 0 {
		regparse = regparse.Add(-1)
		nr = '\\'
	}
	if nr > INT_MAX {
		nr = INT_MAX
	}
	return int32(nr)
}

func bt_regfree(prog *S_regprog) {
}

func reg_save(save *regsave_T, gap *S_growarray) {
	if rex.reg_match == nil {
		save.rs_u.pos.col = colnr_T(rex.input.Sub(rex.line))
		save.rs_u.pos.lnum = rex.lnum
	} else {
		save.rs_u.ptr = rex.input
	}
	save.rs_len = gap.ga_len
}

func reg_restore(save *regsave_T, gap *S_growarray) {
	if rex.reg_match == nil {
		if rex.lnum != save.rs_u.pos.lnum {
			rex.lnum = save.rs_u.pos.lnum
			rex.line = reg_getline(rex.lnum)
		}
		rex.input = rex.line.Add(int(save.rs_u.pos.col))
	} else {
		rex.input = save.rs_u.ptr
	}
	gap.ga_len = save.rs_len
}

func reg_save_equal(save *regsave_T) int32 {
	if rex.reg_match == nil {
		return B2i(rex.lnum == save.rs_u.pos.lnum && rex.input == rex.line.Add(int(save.rs_u.pos.col)))
	}
	return B2i(rex.input == save.rs_u.ptr)
}

func save_se_multi(savep *save_se_T, posp Ptr[lpos_T]) {
	savep.se_u.pos = posp.Get()
	posp.P().lnum = rex.lnum
	posp.P().col = colnr_T(rex.input.Sub(rex.line))
}

func save_se_one(savep *save_se_T, pp Ptr[Ptr[byte]]) {
	savep.se_u.ptr = pp.Get()
	pp.Put(rex.input)
}

func regrepeat(p Ptr[byte], maxcount int64) int32 {
	var count int64 = 0
	var scan Ptr[byte]
	var opnd Ptr[byte]
	var mask int32
	var testval int32 = 0

	scan = rex.input
	opnd = p.Add(3)
	pop := int32(p.Get())
	withNL := pop >= ANY+ADD_NL && pop <= NUPPER+ADD_NL
	switch pop {
	case ANY, ANY + ADD_NL:
		for count < maxcount {
			for scan.Get() != NUL && count < maxcount {
				count++
				scan = scan.Add(int(utfc_ptr2len(scan)))
			}
			if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 || count == maxcount {
				break
			}
			count++
			reg_nextline()
			scan = rex.input
			if got_int != 0 {
				break
			}
		}

	case IDENT, IDENT + ADD_NL:
		testval = TRUE
		fallthrough
	case SIDENT, SIDENT + ADD_NL:
		for count < maxcount {
			if vim_isIDc(utf_ptr2char(scan)) != 0 && (testval != 0 || !(uint32(scan.Get())-'0' < 10)) {
				scan = scan.Add(int(utfc_ptr2len(scan)))
			} else if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else {
				break
			}
			count++
		}

	case KWORD, KWORD + ADD_NL:
		testval = TRUE
		fallthrough
	case SKWORD, SKWORD + ADD_NL:
		for count < maxcount {
			if vim_iswordp_buf(scan, rex.reg_buf) != 0 && (testval != 0 || !(uint32(scan.Get())-'0' < 10)) {
				scan = scan.Add(int(utfc_ptr2len(scan)))
			} else if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else {
				break
			}
			count++
		}

	case FNAME, FNAME + ADD_NL:
		testval = TRUE
		fallthrough
	case SFNAME, SFNAME + ADD_NL:
		for count < maxcount {
			if vim_isfilec(utf_ptr2char(scan)) != 0 && (testval != 0 || !(uint32(scan.Get())-'0' < 10)) {
				scan = scan.Add(int(utfc_ptr2len(scan)))
			} else if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else {
				break
			}
			count++
		}

	case PRINT, PRINT + ADD_NL:
		testval = TRUE
		fallthrough
	case SPRINT, SPRINT + ADD_NL:
		for count < maxcount {
			if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if vim_isprintc(utf_ptr2char(scan)) == 1 && (testval != 0 || !(uint32(scan.Get())-'0' < 10)) {
				scan = scan.Add(int(utfc_ptr2len(scan)))
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else {
				break
			}
			count++
		}

	case RE_WHITE, RE_WHITE + ADD_NL,
		NWHITE, NWHITE + ADD_NL,
		DIGIT, DIGIT + ADD_NL,
		NDIGIT, NDIGIT + ADD_NL,
		HEX, HEX + ADD_NL,
		NHEX, NHEX + ADD_NL,
		OCTAL, OCTAL + ADD_NL,
		NOCTAL, NOCTAL + ADD_NL,
		WORD, WORD + ADD_NL,
		NWORD, NWORD + ADD_NL,
		HEAD, HEAD + ADD_NL,
		NHEAD, NHEAD + ADD_NL,
		ALPHA, ALPHA + ADD_NL,
		NALPHA, NALPHA + ADD_NL,
		LOWER, LOWER + ADD_NL,
		NLOWER, NLOWER + ADD_NL,
		UPPER, UPPER + ADD_NL,
		NUPPER, NUPPER + ADD_NL:
		switch pop {
		case RE_WHITE, RE_WHITE + ADD_NL:
			mask = RI_WHITE
			testval = mask
		case NWHITE, NWHITE + ADD_NL:
			mask = RI_WHITE
		case DIGIT, DIGIT + ADD_NL:
			mask = RI_DIGIT
			testval = mask
		case NDIGIT, NDIGIT + ADD_NL:
			mask = RI_DIGIT
		case HEX, HEX + ADD_NL:
			mask = RI_HEX
			testval = mask
		case NHEX, NHEX + ADD_NL:
			mask = RI_HEX
		case OCTAL, OCTAL + ADD_NL:
			mask = RI_OCTAL
			testval = mask
		case NOCTAL, NOCTAL + ADD_NL:
			mask = RI_OCTAL
		case WORD, WORD + ADD_NL:
			mask = RI_WORD
			testval = mask
		case NWORD, NWORD + ADD_NL:
			mask = RI_WORD
		case HEAD, HEAD + ADD_NL:
			mask = RI_HEAD
			testval = mask
		case NHEAD, NHEAD + ADD_NL:
			mask = RI_HEAD
		case ALPHA, ALPHA + ADD_NL:
			mask = RI_ALPHA
			testval = mask
		case NALPHA, NALPHA + ADD_NL:
			mask = RI_ALPHA
		case LOWER, LOWER + ADD_NL:
			mask = RI_LOWER
			testval = mask
		case NLOWER, NLOWER + ADD_NL:
			mask = RI_LOWER
		case UPPER, UPPER + ADD_NL:
			mask = RI_UPPER
			testval = mask
		case NUPPER, NUPPER + ADD_NL:
			mask = RI_UPPER
		}
		for count < maxcount {
			var l int32

			if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if l = utfc_ptr2len(scan); l > 1 {
				if testval != 0 {
					break
				}
				scan = scan.Add(int(l))
			} else if int32(class_tab[scan.Get()])&mask == testval {
				scan = scan.Add(1)
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else {
				break
			}
			count++
		}

	case EXACTLY:
		{
			var cu int32
			var cl int32

			if rex.reg_ic != 0 {
				cu = vim_toupper(int32(opnd.Get()))
				cl = vim_tolower(int32(opnd.Get()))
				for count < maxcount && (int32(scan.Get()) == cu || int32(scan.Get()) == cl) {
					count++
					scan = scan.Add(1)
				}
			} else {
				cu = int32(opnd.Get())
				for count < maxcount && int32(scan.Get()) == cu {
					count++
					scan = scan.Add(1)
				}
			}
		}

	case MULTIBYTECODE:
		{
			var i int32
			var len_ int32
			var cf int32 = 0

			len_ = utfc_ptr2len(opnd)
			if len_ > 1 {
				if rex.reg_ic != 0 {
					cf = utf_fold(utf_ptr2char(opnd))
				}
				for count < maxcount && utfc_ptr2len(scan) >= len_ {
					for i = 0; i < len_; i++ {
						if opnd.At(int(i)) != scan.At(int(i)) {
							break
						}
					}
					if i < len_ && (rex.reg_ic == 0 || utf_fold(utf_ptr2char(scan)) != cf) {
						break
					}
					scan = scan.Add(int(len_))
					count++
				}
			}
		}

	case ANYOF, ANYOF + ADD_NL:
		testval = TRUE
		fallthrough

	case ANYBUT, ANYBUT + ADD_NL:
		for count < maxcount {
			var len_ int32

			if scan.Get() == NUL {
				if !(rex.reg_match == nil) || !withNL || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0 {
					break
				}
				reg_nextline()
				scan = rex.input
				if got_int != 0 {
					break
				}
			} else if rex.reg_line_lbr != 0 && scan.Get() == '\n' && withNL {
				scan = scan.Add(1)
			} else if len_ = utfc_ptr2len(scan); len_ > 1 {
				if B2i(cstrchr(opnd, utf_ptr2char(scan)).Nil()) == testval {
					break
				}
				scan = scan.Add(int(len_))
			} else {
				if B2i(cstrchr(opnd, int32(scan.Get())).Nil()) == testval {
					break
				}
				scan = scan.Add(1)
			}
			count++
		}

	case NEWL:
		for count < maxcount && ((scan.Get() == NUL && rex.lnum <= rex.reg_maxline && rex.reg_line_lbr == 0 && rex.reg_match == nil) || (scan.Get() == '\n' && rex.reg_line_lbr != 0)) {
			count++
			if rex.reg_line_lbr != 0 {
				rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
			} else {
				reg_nextline()
			}
			scan = rex.input
			if got_int != 0 {
				break
			}
		}

	default:
		iemsg(e_corrupted_regexp_program)
	}

	rex.input = scan

	return int32(count)
}

func regstack_push(state regstate_T, scan Ptr[byte]) Ptr[S_regitem_S] {
	var rp Ptr[regitem_T]

	if int64(uint32(regstack_bytes)>>10) >= p_mmp {
		emsg(gettext_(e_pattern_uses_more_memory_than_maxmempattern))
		return Ptr[S_regitem_S]{}
	}
	if ga_grow(&regstack, 1) == FAIL {
		return Ptr[S_regitem_S]{}
	}

	rp = GaData[regitem_T](&regstack).Add(int(regstack.ga_len))
	rp.P().rs_state = state
	rp.P().rs_scan = scan

	regstack.ga_len++
	regstack_bytes += f13_sizeof_regitem
	return rp
}

func regstack_pop(scan *Ptr[byte]) {
	var rp Ptr[regitem_T]

	rp = GaData[regitem_T](&regstack).Add(int(regstack.ga_len - 1))
	*scan = rp.P().rs_scan

	regstack.ga_len--
	regstack_bytes -= f13_sizeof_regitem
}

func save_subexpr(bp Ptr[S_regbehind_S]) {
	var i int32

	bp.P().save_need_clear_subexpr = rex.need_clear_subexpr
	if rex.need_clear_subexpr != 0 {
		return
	}

	for i = 0; i < NSUBEXP; i++ {
		if rex.reg_match == nil {
			bp.P().save_start[i].se_u.pos = rex.reg_startpos.At(int(i))
			bp.P().save_end[i].se_u.pos = rex.reg_endpos.At(int(i))
		} else {
			bp.P().save_start[i].se_u.ptr = rex.reg_startp.At(int(i))
			bp.P().save_end[i].se_u.ptr = rex.reg_endp.At(int(i))
		}
	}
}

func restore_subexpr(bp Ptr[S_regbehind_S]) {
	var i int32

	rex.need_clear_subexpr = bp.P().save_need_clear_subexpr
	if rex.need_clear_subexpr != 0 {
		return
	}

	for i = 0; i < NSUBEXP; i++ {
		if rex.reg_match == nil {
			rex.reg_startpos.Set(int(i), bp.P().save_start[i].se_u.pos)
			rex.reg_endpos.Set(int(i), bp.P().save_end[i].se_u.pos)
		} else {
			rex.reg_startp.Set(int(i), bp.P().save_start[i].se_u.ptr)
			rex.reg_endp.Set(int(i), bp.P().save_end[i].se_u.ptr)
		}
	}
}

func regmatch(scan Ptr[byte], timed_out *int32) int32 {
	var next Ptr[byte]
	var op int32
	var c int32
	var rp Ptr[regitem_T]
	var no int32
	var status int32

	_ = timed_out

	regstack.ga_len = 0
	regstack_star.ga_len = 0
	regstack_behind.ga_len = 0
	regstack_bytes = 0
	backpos.ga_len = 0

	for {
		fast_breakcheck()

		for {
			if got_int != 0 || scan.Nil() {
				status = RA_FAIL
				break
			}
			status = RA_CONT

			next = regnext(scan)

			op = int32(scan.Get())
			if rex.reg_line_lbr == 0 && (op >= ANY+ADD_NL && op <= NUPPER+ADD_NL) && rex.reg_match == nil && rex.input.Get() == NUL && rex.lnum <= rex.reg_maxline {
				reg_nextline()
			} else if rex.reg_line_lbr != 0 && (op >= ANY+ADD_NL && op <= NUPPER+ADD_NL) && rex.input.Get() == '\n' {
				rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
			} else {
				if op >= ANY+ADD_NL && op <= NUPPER+ADD_NL {
					op -= ADD_NL
				}
				c = utf_ptr2char(rex.input)
				switch op {
				case BOL:
					if rex.input != rex.line {
						status = RA_NOMATCH
					}

				case EOL:
					if c != NUL {
						status = RA_NOMATCH
					}

				case RE_BOF:
					if rex.lnum != 0 || rex.input != rex.line || (rex.reg_match == nil && rex.reg_firstlnum > 1) {
						status = RA_NOMATCH
					}

				case RE_EOF:
					if rex.lnum != rex.reg_maxline || c != NUL {
						status = RA_NOMATCH
					}

				case CURSOR:
					if rex.reg_win == nil || (rex.lnum+rex.reg_firstlnum != rex.reg_win.w_cursor.lnum) || (colnr_T(rex.input.Sub(rex.line)) != rex.reg_win.w_cursor.col) {
						status = RA_NOMATCH
					}

				case RE_MARK:
					{
						var mark int32 = int32(scan.Add(3).At(0))
						var cmp int32 = int32(scan.Add(3).At(1))
						var pos Ptr[pos_T]
						var col usize

						if rex.reg_match == nil {
							col = usize(rex.input.Sub(rex.line))
						} else {
							col = 0
						}

						pos = getmark_buf(rex.reg_buf, mark, FALSE)

						if rex.reg_match == nil {
							rex.line = reg_getline(rex.lnum)
							rex.input = rex.line.Add(int(col))
						}

						if pos.Nil() || pos.P().lnum <= 0 {
							status = RA_NOMATCH
						} else {
							var pos_col colnr_T
							var nomatch bool

							if pos.P().lnum == rex.lnum+rex.reg_firstlnum && pos.P().col == MAXCOL {
								pos_col = reg_getline_len(pos.P().lnum - rex.reg_firstlnum)
							} else {
								pos_col = pos.P().col
							}

							if pos.P().lnum == rex.lnum+rex.reg_firstlnum {
								if pos_col == colnr_T(rex.input.Sub(rex.line)) {
									nomatch = cmp == '<' || cmp == '>'
								} else if pos_col < colnr_T(rex.input.Sub(rex.line)) {
									nomatch = cmp != '>'
								} else {
									nomatch = cmp != '<'
								}
							} else if pos.P().lnum < rex.lnum+rex.reg_firstlnum {
								nomatch = cmp != '>'
							} else {
								nomatch = cmp != '<'
							}
							if nomatch {
								status = RA_NOMATCH
							}
						}
					}

				case RE_VISUAL:
					if reg_match_visual() == 0 {
						status = RA_NOMATCH
					}

				case RE_LNUM:
					if !(rex.reg_match == nil) || re_num_cmp(long_u(rex.lnum+rex.reg_firstlnum), scan) == 0 {
						status = RA_NOMATCH
					}

				case RE_COL:
					if re_num_cmp(long_u(rex.input.Sub(rex.line))+1, scan) == 0 {
						status = RA_NOMATCH
					}

				case RE_VCOL:
					{
						var wp *S_window_S
						var lnum linenr_T
						var vcol long_u

						if rex.reg_win == nil {
							wp = curwin
						} else {
							wp = rex.reg_win
						}
						if rex.reg_match == nil {
							lnum = rex.reg_firstlnum + rex.lnum
						} else {
							lnum = 1
						}

						if rex.reg_match == nil && (lnum <= 0 || lnum > wp.w_buffer.b_ml.ml_line_count) {
							lnum = 1
						}
						vcol = long_u(win_linetabsize(wp, lnum, rex.line, colnr_T(rex.input.Sub(rex.line))))
						if re_num_cmp(vcol+1, scan) == 0 {
							status = RA_NOMATCH
						}
					}

				case BOW:
					if c == NUL {
						status = RA_NOMATCH
					} else {
						var this_class int32

						this_class = mb_get_class_buf(rex.input, rex.reg_buf)
						if this_class <= 1 {
							status = RA_NOMATCH
						} else if reg_prev_class() == this_class {
							status = RA_NOMATCH
						}
					}

				case EOW:
					if rex.input == rex.line {
						status = RA_NOMATCH
					} else {
						var this_class int32
						var prev_class int32

						this_class = mb_get_class_buf(rex.input, rex.reg_buf)
						prev_class = reg_prev_class()
						if this_class == prev_class || prev_class == 0 || prev_class == 1 {
							status = RA_NOMATCH
						}
					}

				case ANY:
					if c == NUL {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case IDENT:
					if vim_isIDc(c) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case SIDENT:
					if uint32(rex.input.Get())-'0' < 10 || vim_isIDc(c) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case KWORD:
					if vim_iswordp_buf(rex.input, rex.reg_buf) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case SKWORD:
					if uint32(rex.input.Get())-'0' < 10 || vim_iswordp_buf(rex.input, rex.reg_buf) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case FNAME:
					if vim_isfilec(c) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case SFNAME:
					if uint32(rex.input.Get())-'0' < 10 || vim_isfilec(c) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case PRINT:
					if vim_isprintc(utf_ptr2char(rex.input)) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case SPRINT:
					if uint32(rex.input.Get())-'0' < 10 || vim_isprintc(utf_ptr2char(rex.input)) == 0 {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case RE_WHITE:
					if !(c == ' ' || c == '\t') {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NWHITE:
					if c == NUL || (c == ' ' || c == '\t') {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case DIGIT:
					if !f13_ri(c, RI_DIGIT) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NDIGIT:
					if c == NUL || f13_ri(c, RI_DIGIT) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case HEX:
					if !f13_ri(c, RI_HEX) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NHEX:
					if c == NUL || f13_ri(c, RI_HEX) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case OCTAL:
					if !f13_ri(c, RI_OCTAL) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NOCTAL:
					if c == NUL || f13_ri(c, RI_OCTAL) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case WORD:
					if !f13_ri(c, RI_WORD) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NWORD:
					if c == NUL || f13_ri(c, RI_WORD) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case HEAD:
					if !f13_ri(c, RI_HEAD) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NHEAD:
					if c == NUL || f13_ri(c, RI_HEAD) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case ALPHA:
					if !f13_ri(c, RI_ALPHA) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NALPHA:
					if c == NUL || f13_ri(c, RI_ALPHA) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case LOWER:
					if !f13_ri(c, RI_LOWER) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NLOWER:
					if c == NUL || f13_ri(c, RI_LOWER) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case UPPER:
					if !f13_ri(c, RI_UPPER) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case NUPPER:
					if c == NUL || f13_ri(c, RI_UPPER) {
						status = RA_NOMATCH
					} else {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					}

				case EXACTLY:
					{
						var len_ int32
						var opnd Ptr[byte]

						opnd = scan.Add(3)
						if opnd.Get() != rex.input.Get() && rex.reg_ic == 0 {
							status = RA_NOMATCH
						} else if opnd.Get() == NUL {
						} else {
							if opnd.At(1) == NUL && rex.reg_ic == 0 {
								len_ = 1
							} else {
								len_ = int32(musl_strlen(opnd))
								if cstrncmp(opnd, rex.input, &len_) != 0 {
									status = RA_NOMATCH
								}
							}
							if status != RA_NOMATCH && utf_iscomposing(utf_ptr2char(rex.input.Add(int(len_)))) != 0 && rex.reg_icombine == 0 && int32(next.Get()) != RE_COMPOSING {
								status = RA_NOMATCH
							}
							if status != RA_NOMATCH {
								rex.input = rex.input.Add(int(len_))
							}
						}
					}

				case ANYOF, ANYBUT:
					{
						var q Ptr[byte] = scan.Add(3)

						if c == NUL {
							status = RA_NOMATCH
						} else if cstrchr(q, c).Nil() == (op == ANYOF) {
							status = RA_NOMATCH
						} else {
							var len_ int32 = 0
							var i int32

							len_ = utfc_ptr2len(q) - utf_ptr2len(q)

							rex.input = rex.input.Add(int(utf_ptr2len(rex.input)))
							q = q.Add(int(utf_ptr2len(q)))

							if len_ == 0 {
								break
							}

							for i = 0; i < len_; i++ {
								if q.At(int(i)) != rex.input.At(int(i)) {
									status = RA_NOMATCH
									break
								}
							}
							rex.input = rex.input.Add(int(len_))
						}
					}

				case MULTIBYTECODE:
					var i int32
					var len_ int32
					var opnd Ptr[byte]
					var opndc int32 = 0
					var inpc int32

					opnd = scan.Add(3)
					if len_ = utfc_ptr2len(opnd); len_ < 2 {
						status = RA_NOMATCH
						break
					}
					opndc = utf_ptr2char(opnd)
					if utf_iscomposing(opndc) != 0 {
						status = RA_NOMATCH
						for i = 0; rex.input.At(int(i)) != NUL; i += utf_ptr2len(rex.input.Add(int(i))) {
							inpc = utf_ptr2char(rex.input.Add(int(i)))
							if utf_iscomposing(inpc) == 0 {
								if i > 0 {
									break
								}
							} else if opndc == inpc {
								len_ = i + utfc_ptr2len(rex.input.Add(int(i)))
								status = RA_MATCH
								break
							}
						}
					} else {
						if cstrncmp(opnd, rex.input, &len_) != 0 {
							status = RA_NOMATCH
							break
						}
					}
					rex.input = rex.input.Add(int(len_))

				case RE_COMPOSING:
					for utf_iscomposing(utf_ptr2char(rex.input)) != 0 {
						rex.input = rex.input.Add(int(utf_ptr2len(rex.input)))
					}

				case NOTHING:

				case BACK:
					{
						var i int32
						var bp Ptr[backpos_T]

						bp = GaData[backpos_T](&backpos)
						for i = 0; i < backpos.ga_len; i++ {
							if bp.At(int(i)).bp_scan == scan {
								break
							}
						}
						if i == backpos.ga_len {
							if backpos.ga_maxlen-backpos.ga_len < 1 && ga_grow_inner(&backpos, 1) == FAIL {
								status = RA_FAIL
							} else {
								bp = GaData[backpos_T](&backpos)
								bp.Ref(int(i)).bp_scan = scan
								backpos.ga_len++
							}
						} else if reg_save_equal(&bp.Ref(int(i)).bp_pos) != 0 {
							status = RA_NOMATCH
						}

						if status != RA_FAIL && status != RA_NOMATCH {
							reg_save(&bp.Ref(int(i)).bp_pos, &backpos)
						}
					}

				case MOPEN + 0, MOPEN + 1, MOPEN + 2, MOPEN + 3, MOPEN + 4,
					MOPEN + 5, MOPEN + 6, MOPEN + 7, MOPEN + 8, MOPEN + 9:
					no = op - MOPEN
					cleanup_subexpr()
					rp = regstack_push(RS_MOPEN, scan)
					if rp.Nil() {
						status = RA_FAIL
					} else {
						rp.P().rs_no = int16(no)
						if rex.reg_match == nil {
							save_se_multi(&rp.P().rs_un.sesave, rex.reg_startpos.Add(int(no)))
						} else {
							save_se_one(&rp.P().rs_un.sesave, rex.reg_startp.Add(int(no)))
						}
					}

				case NOPEN, NCLOSE:
					if regstack_push(RS_NOPEN, scan).Nil() {
						status = RA_FAIL
					}

				case MCLOSE + 0, MCLOSE + 1, MCLOSE + 2, MCLOSE + 3, MCLOSE + 4,
					MCLOSE + 5, MCLOSE + 6, MCLOSE + 7, MCLOSE + 8, MCLOSE + 9:
					no = op - MCLOSE
					cleanup_subexpr()
					rp = regstack_push(RS_MCLOSE, scan)
					if rp.Nil() {
						status = RA_FAIL
					} else {
						rp.P().rs_no = int16(no)
						if rex.reg_match == nil {
							save_se_multi(&rp.P().rs_un.sesave, rex.reg_endpos.Add(int(no)))
						} else {
							save_se_one(&rp.P().rs_un.sesave, rex.reg_endp.Add(int(no)))
						}
					}

				case BACKREF + 1, BACKREF + 2, BACKREF + 3, BACKREF + 4, BACKREF + 5,
					BACKREF + 6, BACKREF + 7, BACKREF + 8, BACKREF + 9:
					{
						var len_ int32

						no = op - BACKREF
						cleanup_subexpr()
						if !(rex.reg_match == nil) {
							if rex.reg_startp.At(int(no)).Nil() || rex.reg_endp.At(int(no)).Nil() {
								len_ = 0
							} else {
								len_ = int32(rex.reg_endp.At(int(no)).Sub(rex.reg_startp.At(int(no))))
								if cstrncmp(rex.reg_startp.At(int(no)), rex.input, &len_) != 0 {
									status = RA_NOMATCH
								}
							}
						} else {
							if rex.reg_startpos.At(int(no)).lnum < 0 || rex.reg_endpos.At(int(no)).lnum < 0 {
								len_ = 0
							} else {
								if rex.reg_startpos.At(int(no)).lnum == rex.lnum && rex.reg_endpos.At(int(no)).lnum == rex.lnum {
									len_ = rex.reg_endpos.At(int(no)).col - rex.reg_startpos.At(int(no)).col
									if cstrncmp(rex.line.Add(int(rex.reg_startpos.At(int(no)).col)), rex.input, &len_) != 0 {
										status = RA_NOMATCH
									}
								} else {
									var r int32 = match_with_backref(rex.reg_startpos.At(int(no)).lnum, rex.reg_startpos.At(int(no)).col, rex.reg_endpos.At(int(no)).lnum, rex.reg_endpos.At(int(no)).col, &len_)

									if r != RA_MATCH {
										status = r
									}
								}
							}
						}

						rex.input = rex.input.Add(int(len_))
					}

				case BRANCH:
					if int32(next.Get()) != BRANCH {
						next = scan.Add(3)
					} else {
						rp = regstack_push(RS_BRANCH, scan)
						if rp.Nil() {
							status = RA_FAIL
						} else {
							status = RA_BREAK
						}
					}

				case BRACE_LIMITS:
					if int32(next.Get()) == BRACE_SIMPLE {
						bl_minval = f13_operand_min(scan)
						bl_maxval = f13_operand_min(scan.Add(4))
					} else if int32(next.Get()) >= BRACE_COMPLEX && int32(next.Get()) < BRACE_COMPLEX+10 {
						no = int32(next.Get()) - BRACE_COMPLEX
						brace_min[no] = f13_operand_min(scan)
						brace_max[no] = f13_operand_min(scan.Add(4))
						brace_count[no] = 0
					} else {
						internal_error(S("BRACE_LIMITS"))
						status = RA_FAIL
					}

				case BRACE_COMPLEX + 0, BRACE_COMPLEX + 1, BRACE_COMPLEX + 2, BRACE_COMPLEX + 3, BRACE_COMPLEX + 4,
					BRACE_COMPLEX + 5, BRACE_COMPLEX + 6, BRACE_COMPLEX + 7, BRACE_COMPLEX + 8, BRACE_COMPLEX + 9:
					{
						var lim int64

						no = op - BRACE_COMPLEX
						brace_count[no]++

						if brace_min[no] <= brace_max[no] {
							lim = brace_min[no]
						} else {
							lim = brace_max[no]
						}
						if int64(brace_count[no]) <= lim {
							rp = regstack_push(RS_BRCPLX_MORE, scan)
							if rp.Nil() {
								status = RA_FAIL
							} else {
								rp.P().rs_no = int16(no)
								reg_save(&rp.P().rs_un.regsave, &backpos)
								next = scan.Add(3)
							}
							break
						}

						if brace_min[no] <= brace_max[no] {
							if int64(brace_count[no]) <= brace_max[no] {
								rp = regstack_push(RS_BRCPLX_LONG, scan)
								if rp.Nil() {
									status = RA_FAIL
								} else {
									rp.P().rs_no = int16(no)
									reg_save(&rp.P().rs_un.regsave, &backpos)
									next = scan.Add(3)
								}
							}
						} else {
							if int64(brace_count[no]) <= brace_min[no] {
								rp = regstack_push(RS_BRCPLX_SHORT, scan)
								if rp.Nil() {
									status = RA_FAIL
								} else {
									reg_save(&rp.P().rs_un.regsave, &backpos)
								}
							}
						}
					}

				case BRACE_SIMPLE, STAR, PLUS:
					{
						var rst regstar_T
						var enough bool

						if int32(next.Get()) == EXACTLY {
							rst.nextb = int32(next.Add(3).Get())
							if rex.reg_ic != 0 {
								if vim_isupper(rst.nextb) != 0 {
									rst.nextb_ic = vim_tolower(rst.nextb)
								} else {
									rst.nextb_ic = vim_toupper(rst.nextb)
								}
							} else {
								rst.nextb_ic = rst.nextb
							}
						} else {
							rst.nextb = NUL
							rst.nextb_ic = NUL
						}
						if op != BRACE_SIMPLE {
							if op == STAR {
								rst.minval = 0
							} else {
								rst.minval = 1
							}
							rst.maxval = int64(32767) << 16
						} else {
							rst.minval = bl_minval
							rst.maxval = bl_maxval
						}

						rst.count = int64(regrepeat(scan.Add(3), rst.maxval))
						if got_int != 0 {
							status = RA_FAIL
							break
						}
						if rst.minval <= rst.maxval {
							enough = rst.count >= rst.minval
						} else {
							enough = rst.count >= rst.maxval
						}
						if enough {
							if int64(uint32(regstack_bytes)>>10) >= p_mmp {
								emsg(gettext_(e_pattern_uses_more_memory_than_maxmempattern))
								status = RA_FAIL
							} else if ga_grow(&regstack_star, 1) == FAIL {
								status = RA_FAIL
							} else {
								var state regstate_T

								regstack_star.ga_len++
								regstack_bytes += f13_sizeof_regstar
								if rst.minval <= rst.maxval {
									state = RS_STAR_LONG
								} else {
									state = RS_STAR_SHORT
								}
								rp = regstack_push(state, scan)
								if rp.Nil() {
									status = RA_FAIL
								} else {
									regstack_star_top().Put(rst)
									status = RA_BREAK
								}
							}
						} else {
							status = RA_NOMATCH
						}
					}

				case NOMATCH, MATCH, SUBPAT:
					rp = regstack_push(RS_NOMATCH, scan)
					if rp.Nil() {
						status = RA_FAIL
					} else {
						rp.P().rs_no = int16(op)
						reg_save(&rp.P().rs_un.regsave, &backpos)
						next = scan.Add(3)
					}

				case BEHIND, NOBEHIND:
					if int64(uint32(regstack_bytes)>>10) >= p_mmp {
						emsg(gettext_(e_pattern_uses_more_memory_than_maxmempattern))
						status = RA_FAIL
					} else if ga_grow(&regstack_behind, 1) == FAIL {
						status = RA_FAIL
					} else {
						regstack_behind.ga_len++
						regstack_bytes += f13_sizeof_regbehind
						rp = regstack_push(RS_BEHIND1, scan)
						if rp.Nil() {
							status = RA_FAIL
						} else {
							save_subexpr(regstack_behind_top())

							rp.P().rs_no = int16(op)
							reg_save(&rp.P().rs_un.regsave, &backpos)
						}
					}

				case BHPOS:
					if rex.reg_match == nil {
						if behind_pos.rs_u.pos.col != colnr_T(rex.input.Sub(rex.line)) || behind_pos.rs_u.pos.lnum != rex.lnum {
							status = RA_NOMATCH
						}
					} else if behind_pos.rs_u.ptr != rex.input {
						status = RA_NOMATCH
					}

				case NEWL:
					if (c != NUL || !(rex.reg_match == nil) || rex.lnum > rex.reg_maxline || rex.reg_line_lbr != 0) && (c != '\n' || rex.reg_line_lbr == 0) {
						status = RA_NOMATCH
					} else if rex.reg_line_lbr != 0 {
						rex.input = rex.input.Add(int(utfc_ptr2len(rex.input)))
					} else {
						reg_nextline()
					}

				case END:
					status = RA_MATCH

				case F_PCLOSE, F_QCLOSE, F_RCLOSE, F_ACLOSE, F_PCLOSE_NL, F_QCLOSE_NL, F_RCLOSE_NL, F_ACLOSE_NL,
					T_PCLOSE, T_QCLOSE, T_RCLOSE, T_ACLOSE, T_PCLOSE_NL, T_QCLOSE_NL, T_RCLOSE_NL, T_ACLOSE_NL:
					{
						var till int32 = B2i(op >= T_PCLOSE)
						var idx int32
						var with_nl int32
						var oc int32
						var cc int32
						var level int32 = 1
						var s Ptr[byte] = rex.input
						var save_lnum linenr_T = rex.lnum
						var save_col colnr_T = colnr_T(rex.input.Sub(rex.line))

						if till != 0 {
							idx = op - T_PCLOSE
						} else {
							idx = op - F_PCLOSE
						}
						with_nl = B2i(idx >= DELIM_NL)
						if with_nl != 0 {
							idx -= DELIM_NL
						}
						oc = int32(S("([{<").At(int(idx)))
						cc = int32(S(")]}>").At(int(idx)))

						for {
							if s.Get() == NUL {
								if with_nl == 0 || !(rex.reg_match == nil) || rex.reg_line_lbr != 0 || rex.lnum >= rex.reg_maxline {
									break
								}
								reg_nextline()
								s = rex.input
								if got_int != 0 {
									break
								}
								continue
							}
							if int32(s.Get()) == oc {
								level++
							} else if int32(s.Get()) == cc {
								level--
							}
							if s.Get() < 0x80 {
								s = s.Add(1)
							} else {
								s = s.Add(int(utfc_ptr2len(s)))
							}
							if level < 1 {
								break
							}
						}
						if level >= 1 {
							if rex.reg_match == nil && rex.lnum != save_lnum {
								rex.lnum = save_lnum
								rex.line = reg_getline(rex.lnum)
							}
							rex.input = rex.line.Add(int(save_col))
							status = RA_NOMATCH
						} else {
							if till != 0 {
								rex.input = s.Add(-1)
							} else {
								rex.input = s
							}
						}
					}

				default:
					iemsg(e_corrupted_regexp_program)
					status = RA_FAIL
				}
			}

			if status != RA_CONT {
				break
			}

			scan = next
		}

		for regstack.ga_len > 0 && status != RA_FAIL {
			rp = GaData[regitem_T](&regstack).Add(int(regstack.ga_len - 1))
			switch rp.P().rs_state {
			case RS_NOPEN:
				regstack_pop(&scan)

			case RS_MOPEN:
				if status == RA_NOMATCH {
					if rex.reg_match == nil {
						rex.reg_startpos.Set(int(rp.P().rs_no), rp.P().rs_un.sesave.se_u.pos)
					} else {
						rex.reg_startp.Set(int(rp.P().rs_no), rp.P().rs_un.sesave.se_u.ptr)
					}
				}
				regstack_pop(&scan)

			case RS_MCLOSE:
				if status == RA_NOMATCH {
					if rex.reg_match == nil {
						rex.reg_endpos.Set(int(rp.P().rs_no), rp.P().rs_un.sesave.se_u.pos)
					} else {
						rex.reg_endp.Set(int(rp.P().rs_no), rp.P().rs_un.sesave.se_u.ptr)
					}
				}
				regstack_pop(&scan)

			case RS_BRANCH:
				if status == RA_MATCH {
					regstack_pop(&scan)
				} else {
					if status != RA_BREAK {
						reg_restore(&rp.P().rs_un.regsave, &backpos)
						scan = rp.P().rs_scan
					}
					if scan.Nil() || int32(scan.Get()) != BRANCH {
						status = RA_NOMATCH
						regstack_pop(&scan)
					} else {
						rp.P().rs_scan = regnext(scan)
						reg_save(&rp.P().rs_un.regsave, &backpos)
						scan = scan.Add(3)
					}
				}

			case RS_BRCPLX_MORE:
				if status == RA_NOMATCH {
					reg_restore(&rp.P().rs_un.regsave, &backpos)
					brace_count[rp.P().rs_no]--
				}
				regstack_pop(&scan)

			case RS_BRCPLX_LONG:
				if status == RA_NOMATCH {
					reg_restore(&rp.P().rs_un.regsave, &backpos)
					brace_count[rp.P().rs_no]--
					status = RA_CONT
				}
				regstack_pop(&scan)
				if status == RA_CONT {
					scan = regnext(scan)
				}

			case RS_BRCPLX_SHORT:
				if status == RA_NOMATCH {
					reg_restore(&rp.P().rs_un.regsave, &backpos)
				}
				regstack_pop(&scan)
				if status == RA_NOMATCH {
					scan = scan.Add(3)
					status = RA_CONT
				}

			case RS_NOMATCH:
				var want int32
				if int32(rp.P().rs_no) == NOMATCH {
					want = RA_MATCH
				} else {
					want = RA_NOMATCH
				}
				if status == want {
					status = RA_NOMATCH
				} else {
					status = RA_CONT
					if int32(rp.P().rs_no) != SUBPAT {
						reg_restore(&rp.P().rs_un.regsave, &backpos)
					}
				}
				regstack_pop(&scan)
				if status == RA_CONT {
					scan = regnext(scan)
				}

			case RS_BEHIND1:
				if status == RA_NOMATCH {
					regstack_pop(&scan)
					regstack_behind.ga_len--
					regstack_bytes -= f13_sizeof_regbehind
				} else {
					reg_save(&regstack_behind_top().P().save_after, &backpos)

					regstack_behind_top().P().save_behind = behind_pos
					behind_pos = rp.P().rs_un.regsave

					rp.P().rs_state = RS_BEHIND2

					reg_restore(&rp.P().rs_un.regsave, &backpos)
					scan = rp.P().rs_scan.Add(3).Add(4)
				}

			case RS_BEHIND2:
				if status == RA_MATCH && reg_save_equal(&behind_pos) != 0 {
					behind_pos = regstack_behind_top().P().save_behind
					if int32(rp.P().rs_no) == BEHIND {
						reg_restore(&regstack_behind_top().P().save_after, &backpos)
					} else {
						status = RA_NOMATCH
						restore_subexpr(regstack_behind_top())
					}
					regstack_pop(&scan)
					regstack_behind.ga_len--
					regstack_bytes -= f13_sizeof_regbehind
				} else {
					var limit int64
					rs := &rp.P().rs_un.regsave

					no = OK
					limit = f13_operand_min(rp.P().rs_scan)
					if rex.reg_match == nil {
						var endcol colnr_T
						if rs.rs_u.pos.lnum < behind_pos.rs_u.pos.lnum {
							endcol = colnr_T(musl_strlen(rex.line))
						} else {
							endcol = behind_pos.rs_u.pos.col
						}
						if limit > 0 && int64(endcol-rs.rs_u.pos.col) >= limit {
							no = FAIL
						} else if rs.rs_u.pos.col == 0 {
							if rs.rs_u.pos.lnum < behind_pos.rs_u.pos.lnum {
								no = FAIL
							} else {
								rs.rs_u.pos.lnum--
								if reg_getline(rs.rs_u.pos.lnum).Nil() {
									no = FAIL
								} else {
									reg_restore(rs, &backpos)
									rs.rs_u.pos.col = colnr_T(musl_strlen(rex.line))
								}
							}
						} else {
							var line Ptr[byte] = reg_getline(rs.rs_u.pos.lnum)

							rs.rs_u.pos.col -= utf_head_off(line, line.Add(int(rs.rs_u.pos.col)-1)) + 1
						}
					} else {
						if rs.rs_u.ptr == rex.line {
							no = FAIL
						} else {
							rs.rs_u.ptr = rs.rs_u.ptr.Add(-int(utf_head_off(rex.line, rs.rs_u.ptr.Add(-1)) + 1))
							if limit > 0 && int64(behind_pos.rs_u.ptr.Sub(rs.rs_u.ptr)) > limit {
								no = FAIL
							}
						}
					}
					if no == OK {
						reg_restore(rs, &backpos)
						scan = rp.P().rs_scan.Add(3).Add(4)
						if status == RA_MATCH {
							status = RA_NOMATCH
							restore_subexpr(regstack_behind_top())
						}
					} else {
						behind_pos = regstack_behind_top().P().save_behind
						if int32(rp.P().rs_no) == NOBEHIND {
							reg_restore(&regstack_behind_top().P().save_after, &backpos)
							status = RA_MATCH
						} else {
							if status == RA_MATCH {
								status = RA_NOMATCH
								restore_subexpr(regstack_behind_top())
							}
						}
						regstack_pop(&scan)
						regstack_behind.ga_len--
						regstack_bytes -= f13_sizeof_regbehind
					}
				}

			case RS_STAR_LONG, RS_STAR_SHORT:
				{
					var rst *regstar_T = regstack_star_top().P()

					if status == RA_MATCH {
						regstack_pop(&scan)
						regstack_star.ga_len--
						regstack_bytes -= f13_sizeof_regstar
						break
					}

					if status != RA_BREAK {
						reg_restore(&rp.P().rs_un.regsave, &backpos)
					}

					for {
						if status != RA_BREAK {
							if rp.P().rs_state == RS_STAR_LONG {
								rst.count--
								if rst.count < rst.minval {
									break
								}
								if rex.input == rex.line {
									if rex.lnum == 0 {
										status = RA_NOMATCH
										break
									}
									rex.lnum--
									rex.line = reg_getline(rex.lnum)
									if rex.line.Nil() {
										break
									}
									rex.input = rex.line.Add(int(reg_getline_len(rex.lnum)))
									fast_breakcheck()
								} else {
									rex.input = rex.input.Add(-int(utf_head_off(rex.line, rex.input.Add(-1)) + 1))
								}
							} else {
								if rst.count == rst.minval || regrepeat(rp.P().rs_scan.Add(3), 1) == 0 {
									break
								}
								rst.count++
							}
							if got_int != 0 {
								break
							}
						} else {
							status = RA_NOMATCH
						}

						if rst.nextb == NUL || int32(rex.input.Get()) == rst.nextb || int32(rex.input.Get()) == rst.nextb_ic {
							reg_save(&rp.P().rs_un.regsave, &backpos)
							scan = regnext(rp.P().rs_scan)
							status = RA_CONT
							break
						}
					}
					if status != RA_CONT {
						regstack_pop(&scan)
						regstack_star.ga_len--
						regstack_bytes -= f13_sizeof_regstar
						status = RA_NOMATCH
					}
				}
			}

			if status == RA_CONT || rp == GaData[regitem_T](&regstack).Add(int(regstack.ga_len-1)) {
				break
			}
		}

		if status == RA_CONT {
			continue
		}

		if regstack.ga_len == 0 || status == RA_FAIL {
			if scan.Nil() {
				iemsg(e_corrupted_regexp_program)
			}
			return B2i(status == RA_MATCH)
		}
	}
}

func regtry(prog *S_regprog, col colnr_T, timed_out *int32) int64 {
	rex.input = rex.line.Add(int(col))
	rex.need_clear_subexpr = TRUE

	if regmatch(prog.program.Add(1), timed_out) == 0 {
		return 0
	}

	cleanup_subexpr()
	if rex.reg_match == nil {
		if rex.reg_startpos.At(0).lnum < 0 {
			rex.reg_startpos.P().lnum = 0
			rex.reg_startpos.P().col = col
		}
		if rex.reg_endpos.At(0).lnum < 0 {
			rex.reg_endpos.P().lnum = rex.lnum
			rex.reg_endpos.P().col = int32(rex.input.Sub(rex.line))
		} else {
			rex.lnum = rex.reg_endpos.At(0).lnum
		}
	} else {
		if rex.reg_startp.At(0).Nil() {
			rex.reg_startp.Set(0, rex.line.Add(int(col)))
		}
		if rex.reg_endp.At(0).Nil() {
			rex.reg_endp.Set(0, rex.input)
		}
	}
	return 1 + rex.lnum
}

// bt_regexec_both: the regstack's storage is made at once (GaData) so that
// `regstack.ga_data == NULL` means what it means in C.  REGSTACK_INITIAL /
// sizeof(regitem_T) is C's size_t division with regitem_T's x86-64 size.
func bt_regexec_both(line Ptr[byte], startcol colnr_T, timed_out *int32) int64 {
	var prog *S_regprog
	var s Ptr[byte]
	var col colnr_T = startcol
	var retval int64 = 0

	if regstack.ga_data == nil {
		ga_init2(&regstack, f13_sizeof_regitem, int32(REGSTACK_INITIAL/f13_sizeof_regitem))
		ga_grow(&regstack, int32(REGSTACK_INITIAL/f13_sizeof_regitem))
		GaData[regitem_T](&regstack)
		regstack.ga_growsize = int32(REGSTACK_INITIAL * 8 / f13_sizeof_regitem)
		ga_init2(&regstack_star, f13_sizeof_regstar, 16)
		ga_init2(&regstack_behind, f13_sizeof_regbehind, 4)
	}

	if backpos.ga_data == nil {
		ga_init2(&backpos, f13_sizeof_backpos, BACKPOS_INITIAL)
		ga_grow(&backpos, BACKPOS_INITIAL)
		GaData[backpos_T](&backpos)
		backpos.ga_growsize = BACKPOS_INITIAL * 8
	}

	if rex.reg_match == nil {
		prog = rex.reg_mmatch.regprog
		line = reg_getline(0)
		rex.reg_startpos = View(rex.reg_mmatch.startpos[:])
		rex.reg_endpos = View(rex.reg_mmatch.endpos[:])
	} else {
		prog = rex.reg_match.regprog
		rex.reg_startp = View(rex.reg_match.startp[:])
		rex.reg_endp = View(rex.reg_match.endp[:])
	}

	if prog == nil || line.Nil() {
		iemsg(e_null_argument)
		goto theend
	}

	if prog_magic_wrong() != 0 {
		goto theend
	}

	if rex.reg_maxcol > 0 && col >= rex.reg_maxcol {
		goto theend
	}

	if prog.regflags&RF_ICASE != 0 {
		rex.reg_ic = TRUE
	} else if prog.regflags&RF_NOICASE != 0 {
		rex.reg_ic = FALSE
	}

	if prog.regflags&RF_ICOMBINE != 0 {
		rex.reg_icombine = TRUE
	}

	if !prog.regmust.Nil() {
		var c int32

		c = utf_ptr2char(prog.regmust)
		s = line.Add(int(col))

		if rex.reg_ic == 0 {
			for {
				s = vim_strchr(s, c)
				if s.Nil() {
					break
				}
				if cstrncmp(s, prog.regmust, &prog.regmlen) == 0 {
					break
				}
				s = s.Add(int(utfc_ptr2len(s)))
			}
		} else {
			for {
				s = cstrchr(s, c)
				if s.Nil() {
					break
				}
				if cstrncmp(s, prog.regmust, &prog.regmlen) == 0 {
					break
				}
				s = s.Add(int(utfc_ptr2len(s)))
			}
		}
		if s.Nil() {
			goto theend
		}
	}

	rex.line = line
	rex.lnum = 0
	reg_toolong = FALSE

	if prog.reganch != 0 {
		var c int32

		c = utf_ptr2char(rex.line.Add(int(col)))
		if prog.regstart == NUL || prog.regstart == c || (rex.reg_ic != 0 && ((utf_fold(prog.regstart) == utf_fold(c)) || (c < 255 && prog.regstart < 255 && vim_tolower(prog.regstart) == vim_tolower(c)))) {
			retval = regtry(prog, col, timed_out)
		} else {
			retval = 0
		}
	} else {
		for got_int == 0 {
			if prog.regstart != NUL {
				s = cstrchr(rex.line.Add(int(col)), prog.regstart)
				if s.Nil() {
					retval = 0
					break
				}
				col = int32(s.Sub(rex.line))
			}

			if rex.reg_maxcol > 0 && col >= rex.reg_maxcol {
				retval = 0
				break
			}

			retval = regtry(prog, col, timed_out)
			if retval > 0 {
				break
			}

			if rex.lnum != 0 {
				rex.lnum = 0
				rex.line = reg_getline(0)
			}
			if rex.line.At(int(col)) == NUL {
				break
			}
			col += utfc_ptr2len(rex.line.Add(int(col)))
		}
	}

theend:
	if reg_tofreelen > 400 {
		reg_tofree = Ptr[byte]{}
	}
	if regstack.ga_maxlen > int32(REGSTACK_INITIAL/f13_sizeof_regitem) {
		ga_clear(&regstack)
	}
	if backpos.ga_maxlen > BACKPOS_INITIAL {
		ga_clear(&backpos)
	}

	if retval > 0 {
		if rex.reg_match == nil {
			var start *lpos_T = &rex.reg_mmatch.startpos[0]
			var end *lpos_T = &rex.reg_mmatch.endpos[0]

			if end.lnum < start.lnum || (end.lnum == start.lnum && end.col < start.col) {
				rex.reg_mmatch.endpos[0] = rex.reg_mmatch.startpos[0]
			}

			rex.reg_mmatch.rmm_matchcol = col
		} else {
			if rex.reg_match.endp[0].Lt(rex.reg_match.startp[0]) {
				rex.reg_match.endp[0] = rex.reg_match.startp[0]
			}

			rex.reg_match.rm_matchcol = col
		}
	}

	return retval
}

// ==== from f14.go ====
// Transpiled by hand from editor.c: bt_regexec_nl .. win_do_lines.

func bt_regexec_nl(rmp *regmatch_T, line Ptr[byte], col colnr_T, line_lbr int32) int32 {
	rex.reg_match = rmp
	rex.reg_mmatch = nil
	rex.reg_maxline = 0
	rex.reg_line_lbr = line_lbr
	rex.reg_buf = curbuf
	rex.reg_win = nil
	rex.reg_ic = rmp.rm_ic
	rex.reg_icombine = FALSE
	rex.reg_maxcol = 0

	return int32(bt_regexec_both(line, col, nil))
}

func bt_regexec_multi(rmp *regmmatch_T, win *S_window_S, buf *S_file_buffer, lnum linenr_T, col colnr_T, timed_out *int32) int64 {
	init_regexec_multi(rmp, win, buf, lnum)
	return bt_regexec_both(Ptr[byte]{}, col, timed_out)
}

func re_num_cmp(val long_u, scan Ptr[byte]) int32 {
	var n long_u = long_u((int64(scan.At(3)) << 24) + (int64(scan.At(4)) << 16) + (int64(scan.At(5)) << 8) + int64(scan.At(6)))

	if scan.At(7) == '>' {
		return B2i(val > n)
	}
	if scan.At(7) == '<' {
		return B2i(val < n)
	}
	return B2i(val == n)
}

func vim_regcomp(expr_arg Ptr[byte], re_flags int32) *S_regprog {
	var prog *S_regprog = nil
	var expr Ptr[byte] = expr_arg

	rex.reg_buf = curbuf

	prog = bt_regcomp(expr, re_flags)

	if prog != nil {
		prog.re_engine = BACKTRACKING_ENGINE
		prog.re_flags = uint32(re_flags)
	}

	return prog
}

func vim_regfree(prog *S_regprog) {
	if prog != nil {
		bt_regfree(prog)
	}
}

func vim_regexec_string(rmp *regmatch_T, line Ptr[byte], col colnr_T, nl int32) int32 {
	var result int32
	var rex_save regexec_T
	var rex_in_use_save int32 = rex_in_use

	if rmp.regprog.re_in_use != 0 {
		emsg(gettext_(e_cannot_use_pattern_recursively))
		return FALSE
	}
	rmp.regprog.re_in_use = TRUE

	if rex_in_use != 0 {
		rex_save = rex
	}
	rex_in_use = TRUE

	rex.reg_startp = Ptr[Ptr[byte]]{}
	rex.reg_endp = Ptr[Ptr[byte]]{}
	rex.reg_startpos = Ptr[lpos_T]{}
	rex.reg_endpos = Ptr[lpos_T]{}

	result = bt_regexec_nl(rmp, line, col, nl)
	rmp.regprog.re_in_use = FALSE

	rex_in_use = rex_in_use_save
	if rex_in_use != 0 {
		rex = rex_save
	}

	return B2i(result > 0)
}

func vim_regexec(rmp *regmatch_T, line Ptr[byte], col colnr_T) int32 {
	return vim_regexec_string(rmp, line, col, FALSE)
}

func vim_regexec_multi(rmp *regmmatch_T, win *S_window_S, buf *S_file_buffer, lnum linenr_T, col colnr_T, timed_out *int32) int64 {
	var result int32
	var rex_save regexec_T
	var rex_in_use_save int32 = rex_in_use

	if rmp.regprog.re_in_use != 0 {
		emsg(gettext_(e_cannot_use_pattern_recursively))
		return FALSE
	}
	rmp.regprog.re_in_use = TRUE

	if rex_in_use != 0 {
		rex_save = rex
	}
	rex_in_use = TRUE

	result = int32(bt_regexec_multi(rmp, win, buf, lnum, col, timed_out))
	rmp.regprog.re_in_use = FALSE

	rex_in_use = rex_in_use_save
	if rex_in_use != 0 {
		rex = rex_save
	}

	if result <= 0 {
		return 0
	}
	return int64(result)
}

func reset_y_append() {
	y_append = FALSE
}

func valid_yank_reg(regname int32, writing int32) int32 {
	if (regname > 0 && ((uint32(regname)-'A' < 26 || uint32(regname)-'a' < 26) || uint32(regname)-'0' < 10)) || (writing == 0 && !vim_strchr(S("/#.%:"), regname).Nil()) || regname == '"' || regname == '-' || regname == '_' {
		return TRUE
	} else if regname == '*' || regname == '+' {
		msg_warn_missing_clipboard()
		return FALSE
	}
	return FALSE
}

func get_yank_register(regname int32, writing int32) int32 {
	var i int32
	var ret int32 = FALSE

	y_append = FALSE
	if (regname == 0 || regname == '"') && writing == 0 && !y_previous.Nil() {
		y_current = y_previous
		return ret
	}
	i = regname
	if uint32(i)-'0' < 10 {
		i -= '0'
	} else if uint32(i)-'a' < 26 {
		i = (i - 'a') + 10
	} else if uint32(i)-'A' < 26 {
		i = (i - 'A') + 10
		y_append = TRUE
	} else if regname == '-' {
		i = DELETION_REGISTER
	} else {
		i = 0
	}
	y_current = View(y_regs[:]).Add(int(i))
	if writing != 0 {
		y_previous = y_current
	}
	return ret
}

func get_register(name int32, copy_ int32) *yankreg_T {
	var reg *yankreg_T
	var i int32

	get_yank_register(name, 0)
	reg = new(yankreg_T)

	*reg = *y_current.P()
	if copy_ != 0 {
		if reg.y_size == 0 || y_current.P().y_array.Nil() {
			reg.y_array = Ptr[string_T]{}
		} else {
			reg.y_array = Mk[string_T](int(reg.y_size))
		}
		if !reg.y_array.Nil() {
			for i = 0; int64(i) < reg.y_size; i++ {
				reg.y_array.Ref(int(i)).string_ = vim_strnsave(y_current.P().y_array.At(int(i)).string_, y_current.P().y_array.At(int(i)).length)

				reg.y_array.Ref(int(i)).length = y_current.P().y_array.At(int(i)).length
			}
		}
	} else {
		y_current.P().y_array = Ptr[string_T]{}
	}
	return reg
}

func put_register(name int32, reg *yankreg_T) {
	get_yank_register(name, 0)
	free_yank_all()
	*y_current.P() = *reg
}

func do_record(c int32) int32 {
	var p Ptr[byte]
	var old_y_previous Ptr[yankreg_T]
	var old_y_current Ptr[yankreg_T]
	var retval int32

	if reg_recording == 0 {
		if c < 0 || (!((uint32(c)-'A' < 26 || uint32(c)-'a' < 26) || uint32(c)-'0' < 10) && c != '"') {
			retval = FAIL
		} else {
			reg_recording = c
			showmode()
			do_record_regname = c
			retval = OK
		}
	} else {
		reg_recording = 0
		msg(S(""))
		p = get_recorded()
		if p.Nil() {
			retval = FAIL
		} else {
			vim_unescape_csi(p)

			old_y_previous = y_previous
			old_y_current = y_current

			retval = stuff_yank(do_record_regname, p)

			y_previous = old_y_previous
			y_current = old_y_current
		}
	}
	return retval
}

func stuff_yank(regname int32, p Ptr[byte]) int32 {
	var plen usize

	if regname != 0 && valid_yank_reg(regname, TRUE) == 0 {
		return FAIL
	}
	if regname == '_' {
		return OK
	}

	plen = musl_strlen(p)
	get_yank_register(regname, TRUE)
	if y_append != 0 && !y_current.P().y_array.Nil() {
		var pp *string_T
		var tmp Ptr[byte]
		var tmplen usize

		pp = y_current.P().y_array.Ref(int(y_current.P().y_size - 1))
		tmplen = pp.length + plen
		tmp = Alloc(int(tmplen + 1))
		musl_strcpy(tmp, pp.string_)
		musl_strcpy(tmp.Add(int(pp.length)), p)
		pp.string_ = tmp
		pp.length = tmplen
	} else {
		free_yank_all()
		y_current.P().y_array = Mk[string_T](1)
		if y_current.P().y_array.Nil() {
			return FAIL
		}
		y_current.P().y_array.Ref(0).string_ = p
		y_current.P().y_array.Ref(0).length = plen
		y_current.P().y_size = 1
		y_current.P().y_type = MCHAR
	}
	return OK
}

func execreg_line_continuation(lines Ptr[string_T], idx *int64) Ptr[byte] {
	var ga garray_T
	var cmd_start int64 = *idx
	var cmd_end int64 = *idx
	var tmp *string_T
	var j int32
	var str Ptr[byte]

	ga_init2(&ga, 1, 400)

	for {
		cmd_start--
		if !(cmd_start > 0) {
			break
		}
		var p Ptr[byte]

		p = skipwhite(lines.At(int(cmd_start)).string_)
		if p.Get() != '\\' && (p.At(0) != '"' || p.At(1) != '\\' || p.At(2) != ' ') {
			break
		}
	}

	tmp = lines.Ref(int(cmd_start))
	ga_concat_len(&ga, tmp.string_, tmp.length)
	for j = int32(cmd_start + 1); int64(j) <= cmd_end; j++ {
		var p Ptr[byte]

		tmp = lines.Ref(int(j))
		p = skipwhite(tmp.string_)
		if p.Get() == '\\' {
			if ga.ga_len > 400 {
				if ga.ga_len > 8000 {
					ga.ga_growsize = 8000
				} else {
					ga.ga_growsize = ga.ga_len
				}
			}
			p = p.Add(1)
			ga_concat_len(&ga, p, usize(tmp.string_.Add(int(tmp.length)).Sub(p)))
		}
	}
	ga_append(&ga, NUL)
	str = vim_strnsave(GaData[byte](&ga), usize(ga.ga_len))
	ga_clear(&ga)

	*idx = cmd_start
	return str
}

func do_execreg(regname int32, colon int32, addcr int32, silent int32) int32 {
	var i int64
	var p Ptr[byte]
	var retval int32 = OK
	var remap int32

	if regname == '@' {
		if execreg_lastc == NUL {
			emsg(gettext_(e_no_previously_used_register))
			return FAIL
		}
		regname = execreg_lastc
	}
	if regname == '%' || regname == '#' || valid_yank_reg(regname, FALSE) == 0 {
		emsg_invreg(regname)
		return FAIL
	}
	execreg_lastc = regname

	if regname == '_' {
		return OK
	}

	if regname == ':' {
		if last_cmdline.Nil() {
			emsg(gettext_(e_no_previous_command_line))
			return FAIL
		}
		new_last_cmdline = Ptr[byte]{}
		p = vim_strsave_escaped_ext(last_cmdline, S("\001\002\003\004\005\006\007"+"\010\011\012\013\014\015\016\017"+"\020\021\022\023\024\025\026\027"+"\030\031\032\033\034\035\036\037"), Ctrl_V, FALSE)
		if VIsual_active != 0 && musl_strncmp(p, S("'<,'>"), 5) == 0 {
			retval = put_in_typebuf(p.Add(5), TRUE, TRUE, silent)
		} else {
			retval = put_in_typebuf(p, TRUE, TRUE, silent)
		}
	} else if regname == '.' {
		p = get_last_insert_save()
		if p.Nil() {
			emsg(gettext_(e_no_inserted_text_yet))
			return FAIL
		}
		retval = put_in_typebuf(p, FALSE, colon, silent)
	} else {
		get_yank_register(regname, FALSE)
		if y_current.P().y_array.Nil() {
			return FAIL
		}

		if colon != 0 {
			remap = -1
		} else {
			remap = REMAP_YES
		}

		put_reedit_in_typebuf(silent)
		for i = y_current.P().y_size - 1; i >= 0; i-- {
			var escaped Ptr[byte]
			var str Ptr[byte]

			if y_current.P().y_type == MLINE || i < y_current.P().y_size-1 || addcr != 0 {
				if ins_typebuf(S("\n"), remap, 0, TRUE, silent) == FAIL {
					return FAIL
				}
			}

			str = y_current.P().y_array.At(int(i)).string_
			if colon != 0 && i > 0 {
				p = skipwhite(str)
				if p.Get() == '\\' || (p.At(0) == '"' && p.At(1) == '\\' && p.At(2) == ' ') {
					str = execreg_line_continuation(y_current.P().y_array, &i)
				}
			}
			escaped = vim_strsave_escape_csi(str)
			retval = ins_typebuf(escaped, remap, 0, TRUE, silent)
			if retval == FAIL {
				return FAIL
			}
			if colon != 0 && ins_typebuf(S(":"), remap, 0, TRUE, silent) == FAIL {
				return FAIL
			}
		}
		if regname == 0 {
			reg_executing = '"'
		} else {
			reg_executing = regname
		}
		pending_end_reg_executing = FALSE
	}
	return retval
}

func put_reedit_in_typebuf(silent int32) {
	if restart_edit == NUL {
		return
	}

	buf := Mk[byte](11)
	for k, c := range []byte{0x80, KS_EXTRA, KE_COMMAND, 's', 't', 'a', 'r', 't', 'i', CAR, NUL} {
		buf.Set(k, c)
	}
	if restart_edit == 'R' {
		buf.Set(8, 'r')
	} else if restart_edit == 'V' {
		buf.Set(8, 'g')
	} else if restart_edit == 'A' {
		buf.Set(8, '!')
	}
	if ins_typebuf(buf, -1, 0, TRUE, silent) == OK {
		restart_edit = NUL
	}
}

func put_in_typebuf(s Ptr[byte], esc int32, colon int32, silent int32) int32 {
	var retval int32 = OK

	put_reedit_in_typebuf(silent)
	if colon != 0 {
		retval = ins_typebuf(S("\n"), -1, 0, TRUE, silent)
	}
	if retval == OK {
		var p Ptr[byte]

		if esc != 0 {
			p = vim_strsave_escape_csi(s)
		} else {
			p = s
		}
		if p.Nil() {
			retval = FAIL
		} else {
			var remap int32
			if esc != 0 {
				remap = -1
			} else {
				remap = REMAP_YES
			}
			retval = ins_typebuf(p, remap, 0, TRUE, silent)
		}
	}
	if colon != 0 && retval == OK {
		retval = ins_typebuf(S(":"), -1, 0, TRUE, silent)
	}
	return retval
}

func insert_reg(regname int32, literally_arg int32) int32 {
	var i int64
	var retval int32 = OK
	var arg Ptr[byte]
	var allocated int32
	var literally int32 = literally_arg

	ui_breakcheck()
	if got_int != 0 {
		return FAIL
	}

	if regname != NUL && valid_yank_reg(regname, FALSE) == 0 {
		return FAIL
	}

	if regname == '.' {
		retval = stuff_inserted(NUL, 1, TRUE)
	} else if get_spec_reg(regname, &arg, &allocated, TRUE) != 0 {
		if arg.Nil() {
			return FAIL
		}
		stuffescaped(arg, literally)
	} else {
		if get_yank_register(regname, FALSE) != 0 {
			literally = TRUE
		}
		if y_current.P().y_array.Nil() {
			retval = FAIL
		} else {
			for i = 0; i < y_current.P().y_size; i++ {
				if regname == '-' && y_current.P().y_type == MCHAR {
					var dir int32 = -1
					if (State & REPLACE_FLAG) != 0 {
						var curpos pos_T
						if u_save_cursor() == FAIL {
							return FAIL
						}
						del_chars(int64(mb_charlen(y_current.P().y_array.At(0).string_)), TRUE)
						curpos = curwin.w_cursor
						if oneright() == FAIL {
							dir = FORWARD
						}
						curwin.w_cursor = curpos
					}

					AppendCharToRedobuff(Ctrl_R)
					AppendCharToRedobuff(regname)
					do_put(regname, Ptr[byte]{}, dir, 1, PUT_CURSEND)
				} else {
					stuffescaped(y_current.P().y_array.At(int(i)).string_, literally)
					if y_current.P().y_type == MLINE || i < y_current.P().y_size-1 {
						stuffcharReadbuff('\n')
					}
				}
			}
		}
	}

	return retval
}

func get_spec_reg(regname int32, argp *Ptr[byte], allocated *int32, errmsg int32) int32 {
	var cnt int32

	*argp = Ptr[byte]{}
	*allocated = FALSE
	switch regname {
	case '%':
		if errmsg != 0 {
			check_fname()
		}
		*argp = Ptr[byte]{}
		return TRUE

	case '#':
		*argp = getaltfname(errmsg)
		return TRUE

	case ':':
		if last_cmdline.Nil() && errmsg != 0 {
			emsg(gettext_(e_no_previous_command_line))
		}
		*argp = last_cmdline
		return TRUE

	case '/':
		if last_search_pat().Nil() && errmsg != 0 {
			emsg(gettext_(e_no_previous_regular_expression))
		}
		*argp = last_search_pat()
		return TRUE

	case '.':
		*argp = get_last_insert_save()
		*allocated = TRUE
		if (*argp).Nil() && errmsg != 0 {
			emsg(gettext_(e_no_inserted_text_yet))
		}
		return TRUE

	case Ctrl_F, Ctrl_P:
		if errmsg == 0 {
			return FALSE
		}
		{
			var exp int32 = 0
			if regname == Ctrl_P {
				exp = FNAME_EXP
			}
			*argp = file_name_at_cursor(FNAME_MESS|FNAME_HYP|exp, 1, nil)
		}
		*allocated = TRUE
		return TRUE

	case Ctrl_W, Ctrl_A:
		if errmsg == 0 {
			return FALSE
		}
		{
			var ft int32 = FIND_STRING
			if regname == Ctrl_W {
				ft = FIND_IDENT | FIND_STRING
			}
			cnt = find_ident_under_cursor(argp, ft)
		}
		if cnt != 0 {
			*argp = vim_strnsave(*argp, usize(cnt))
		} else {
			*argp = Ptr[byte]{}
		}
		*allocated = TRUE
		return TRUE

	case Ctrl_L:
		if errmsg == 0 {
			return FALSE
		}

		*argp = ml_get_buf(curwin.w_buffer, curwin.w_cursor.lnum, FALSE)
		return TRUE

	case '_':
		*argp = S("")
		return TRUE
	}

	return FALSE
}

func cmdline_paste_reg(regname int32, literally_arg int32, remcr int32) int32 {
	var i int64
	var literally int32 = literally_arg

	if get_yank_register(regname, FALSE) != 0 {
		literally = TRUE
	}
	if y_current.P().y_array.Nil() {
		return FAIL
	}

	for i = 0; i < y_current.P().y_size; i++ {
		cmdline_paste_str(y_current.P().y_array.At(int(i)).string_, literally)

		if (y_current.P().y_type == MLINE || i < y_current.P().y_size-1) && remcr == 0 {
			cmdline_paste_str(S("\r"), literally)
		}

		ui_breakcheck()
		if got_int != 0 {
			return FAIL
		}
	}
	return OK
}

func shift_delete_registers() {
	var n int32

	y_current = View(y_regs[:]).Add(9)
	free_yank_all()
	for n = 9; n > 1; n-- {
		y_regs[n] = y_regs[n-1]
	}
	y_current = View(y_regs[:]).Add(1)
	if y_append == 0 {
		y_previous = y_current
	}
	y_regs[1].y_array = Ptr[string_T]{}
}

func init_yank() {
	var i int32

	for i = 0; i < NUM_REGISTERS; i++ {
		y_regs[i].y_array = Ptr[string_T]{}
	}
}

func free_yank(n int64) {
	if y_current.P().y_array.Nil() {
		return
	}

	var i int64

	for i = n - 1; i >= 0; i-- {
		y_current.P().y_array.Ref(int(i)).string_ = Ptr[byte]{}
		y_current.P().y_array.Ref(int(i)).length = 0
	}
	y_current.P().y_array = Ptr[string_T]{}
}

func free_yank_all() {
	free_yank(y_current.P().y_size)
}

func op_yank(oap *S_oparg_S, deleting int32, mess int32) int32 {
	var y_idx int64
	var curr Ptr[yankreg_T]
	var newreg yankreg_T
	var lnum linenr_T
	var yanktype int32 = oap.motion_type
	var yanklines int64 = oap.line_count
	var yankendlnum linenr_T = oap.end.lnum
	var pnew Ptr[byte]
	var bd S_block_def
	var new_ptr Ptr[string_T]
	var j int64

	if oap.regname != 0 && valid_yank_reg(oap.regname, TRUE) == 0 {
		beep_flush()
		return FAIL
	}
	if oap.regname == '_' {
		return OK
	}

	if deleting == 0 {
		get_yank_register(oap.regname, TRUE)
	}

	curr = y_current
	if y_append != 0 && !y_current.P().y_array.Nil() {
		y_current = Addr(&newreg)
	} else {
		free_yank_all()
	}

	if oap.motion_type == MCHAR && oap.start.col == 0 && oap.inclusive == 0 && (oap.is_VIsual == 0 || p_sel.Get() == 'o') && oap.block_mode == 0 && oap.end.col == 0 && yanklines > 1 {
		yanktype = MLINE
		yankendlnum--
		yanklines--
	}

	y_current.P().y_size = yanklines
	y_current.P().y_type = char_u(yanktype)
	y_current.P().y_width = 0
	y_current.P().y_array = Mk[string_T](int(yanklines))

	y_idx = 0
	lnum = oap.start.lnum

	if oap.block_mode != 0 {
		y_current.P().y_type = MBLOCK
		y_current.P().y_width = oap.end_vcol - oap.start_vcol

		if curwin.w_curswant == MAXCOL && y_current.P().y_width > 0 {
			y_current.P().y_width--
		}
	}

	for ; lnum <= yankendlnum; lnum, y_idx = lnum+1, y_idx+1 {
		switch y_current.P().y_type {
		case MBLOCK:
			block_prep(oap, &bd, lnum, FALSE)
			if yank_copy_line(&bd, y_idx, oap.excl_tr_ws) == FAIL {
				goto fail
			}

		case MLINE:
			y_current.P().y_array.Ref(int(y_idx)).length = usize(ml_get_len(lnum))
			y_current.P().y_array.Ref(int(y_idx)).string_ = vim_strnsave(ml_get(lnum), y_current.P().y_array.At(int(y_idx)).length)

		case MCHAR:
			{
				var tmp int32

				charwise_block_prep(oap.start, oap.end, &bd, lnum, oap.inclusive)

				tmp = int32(musl_strlen(bd.textstart))
				if tmp < bd.textlen {
					bd.textlen = tmp
				}

				if yank_copy_line(&bd, y_idx, FALSE) == FAIL {
					goto fail
				}
			}
		}
	}

	if curr != y_current {
		new_ptr = Mk[string_T](int(curr.P().y_size + y_current.P().y_size))
		for j = 0; j < curr.P().y_size; j++ {
			new_ptr.Set(int(j), curr.P().y_array.At(int(j)))
		}
		curr.P().y_array = new_ptr

		if yanktype == MLINE {
			curr.P().y_type = MLINE
		}

		if curr.P().y_type == MCHAR && vim_strchr(p_cpo, CPO_REGAPPEND).Nil() {
			pnew = Alloc(int(curr.P().y_array.At(int(curr.P().y_size-1)).length + y_current.P().y_array.At(0).length + 1))

			j--
			musl_strcpy(pnew, curr.P().y_array.At(int(j)).string_)
			musl_strcpy(pnew.Add(int(curr.P().y_array.At(int(j)).length)), y_current.P().y_array.At(0).string_)
			curr.P().y_array.Ref(int(j)).string_ = pnew
			curr.P().y_array.Ref(int(j)).length = curr.P().y_array.At(int(j)).length + y_current.P().y_array.At(0).length
			j++
			y_current.P().y_array.Ref(0).string_ = Ptr[byte]{}
			y_current.P().y_array.Ref(0).length = 0
			y_idx = 1
		} else {
			y_idx = 0
		}
		for y_idx < y_current.P().y_size {
			curr.P().y_array.Set(int(j), y_current.P().y_array.At(int(y_idx)))
			j++
			y_idx++
		}
		curr.P().y_size = j
		y_current = curr
	}

	if mess != 0 {
		if yanktype == MCHAR && oap.block_mode == 0 && yanklines == 1 {
			yanklines = 0
		}
		if yanklines > p_report {
			namebuf := Mk[byte](100)

			if oap.regname == NUL {
				namebuf.Put(NUL)
			} else {
				vim_snprintf(namebuf, 100, gettext_(S(" into \"%c")), oap.regname)
			}

			update_topline_redraw()
			if oap.block_mode != 0 {
				vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("block of %ld line yanked%s"), S("block of %ld lines yanked%s"), uint64(yanklines)), yanklines, namebuf)
				msg(iobuff_or(NGETTEXT(S("block of %ld line yanked%s"), S("block of %ld lines yanked%s"), uint64(yanklines))))
			} else {
				vim_snprintf(IObuff, iobuff_room(), NGETTEXT(S("%ld line yanked%s"), S("%ld lines yanked%s"), uint64(yanklines)), yanklines, namebuf)
				msg(iobuff_or(NGETTEXT(S("%ld line yanked%s"), S("%ld lines yanked%s"), uint64(yanklines))))
			}
		}
	}

	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0 {
		curbuf.b_op_start = oap.start
		curbuf.b_op_end = oap.end
		if yanktype == MLINE && oap.block_mode == 0 {
			curbuf.b_op_start.col = 0
			curbuf.b_op_end.col = MAXCOL
		}
		if yanktype != MLINE && oap.inclusive == 0 {
			decl(&curbuf.b_op_end)
		}
	}

	return OK

fail:
	free_yank(y_idx + 1)
	y_current = curr
	return FAIL
}

func yank_copy_line(bd *S_block_def, y_idx int64, exclude_trailing_space int32) int32 {
	var pnew Ptr[byte]

	if exclude_trailing_space != 0 {
		bd.endspaces = 0
	}
	pnew = Alloc(int(bd.startspaces + bd.endspaces + bd.textlen + 1))
	y_current.P().y_array.Ref(int(y_idx)).string_ = pnew
	Memset(pnew, ' ', int(usize(bd.startspaces)))
	pnew = pnew.Add(int(bd.startspaces))
	Memmove(pnew, bd.textstart, int(usize(bd.textlen)))
	pnew = pnew.Add(int(bd.textlen))
	Memset(pnew, ' ', int(usize(bd.endspaces)))
	pnew = pnew.Add(int(bd.endspaces))
	if exclude_trailing_space != 0 {
		var s int32 = bd.textlen + bd.endspaces

		for s > 0 && (bd.textstart.At(int(s-1)) == ' ' || bd.textstart.At(int(s-1)) == '\t') {
			s = s - utf_head_off(bd.textstart, bd.textstart.Add(int(s-1))) - 1
			pnew = pnew.Add(-1)
		}
	}
	pnew.Put(NUL)

	y_current.P().y_array.Ref(int(y_idx)).length = usize(pnew.Sub(y_current.P().y_array.At(int(y_idx)).string_))

	return OK
}

func do_put(regname int32, expr_result Ptr[byte], dir int32, count int64, flags int32) {
	var ptr Ptr[byte]
	var newp Ptr[byte]
	var oldp Ptr[byte]
	var yanklen int32
	var totlen int32 = 0
	var lnum linenr_T
	var col colnr_T
	var i int64
	var y_type int32
	var y_size int64
	var oldlen int32
	var y_width int64 = 0
	var vcol colnr_T
	var y_array Ptr[string_T] = Ptr[string_T]{}
	var y_current_used Ptr[yankreg_T] = Ptr[yankreg_T]{}
	var nr_lines int64 = 0
	var insert_string string_T
	var allocated int32 = FALSE
	var orig_start pos_T = curbuf.b_op_start
	var orig_end pos_T = curbuf.b_op_end
	var cur_ve_flags uint32 = get_ve_flags()
	var len_ int32

	curbuf.b_op_start = curwin.w_cursor
	curbuf.b_op_end = curwin.w_cursor

	if regname == '.' {
		if VIsual_active != 0 {
			stuffcharReadbuff(VIsual_mode)
		}

		{
			var c int32
			if dir == FORWARD {
				if count == -1 {
					c = 'o'
				} else {
					c = 'a'
				}
			} else {
				if count == -1 {
					c = 'O'
				} else {
					c = 'i'
				}
			}
			stuff_inserted(c, count, FALSE)
		}

		if (flags&PUT_CURSEND) != 0 && gchar_cursor() != NUL {
			stuffcharReadbuff('l')
		}
		return
	}

	insert_string.string_ = Ptr[byte]{}
	if regname == '=' && !expr_result.Nil() {
		insert_string.string_ = expr_result
	} else if get_spec_reg(regname, &insert_string.string_, &allocated, TRUE) != 0 && insert_string.string_.Nil() {
		return
	}

	if u_save(curwin.w_cursor.lnum, curwin.w_cursor.lnum+1) == FAIL {
		goto end
	}

	if !insert_string.string_.Nil() {
		insert_string.length = musl_strlen(insert_string.string_)

		y_type = MCHAR
		{
			y_size = 1
			y_array = Addr(&insert_string)
		}
	} else {
		get_yank_register(regname, FALSE)

		y_type = int32(y_current.P().y_type)
		y_width = int64(y_current.P().y_width)
		y_size = y_current.P().y_size
		y_array = y_current.P().y_array
		y_current_used = y_current
	}

	if y_type == MLINE {
		if (flags & PUT_LINE_SPLIT) != 0 {
			var p_orig Ptr[byte]
			var p Ptr[byte]
			var plen usize

			if u_save_cursor() == FAIL {
				goto end
			}
			p = ml_get_cursor()
			p_orig = p
			plen = usize(ml_get_cursor_len())
			if dir == FORWARD && p.Get() != NUL {
				p = p.Add(int(utfc_ptr2len(p)))
			}
			ptr = vim_strnsave(p, plen-usize(p.Sub(p_orig)))
			ml_append(curwin.w_cursor.lnum, ptr, 0)

			oldp = ml_get_curline()
			p = oldp.Add(int(curwin.w_cursor.col))
			if dir == FORWARD && p.Get() != NUL {
				p = p.Add(int(utfc_ptr2len(p)))
			}
			ptr = vim_strnsave(oldp, usize(p.Sub(oldp)))
			ml_replace(curwin.w_cursor.lnum, ptr, FALSE)
			nr_lines++
			dir = FORWARD
		}
		if (flags & PUT_LINE_FORWARD) != 0 {
			curwin.w_cursor = curbuf.b_visual.vi_end
			dir = FORWARD
		}
		curbuf.b_op_start = curwin.w_cursor
		curbuf.b_op_end = curwin.w_cursor
	}

	if (flags & PUT_LINE) != 0 {
		y_type = MLINE
	}

	if y_size == 0 || y_array.Nil() {
		var rn Ptr[byte]
		if regname == 0 {
			rn = S("\"")
		} else {
			rn = transchar(regname)
		}
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_nothing_in_register_str), rn)
		emsg(iobuff_or(gettext_(e_nothing_in_register_str)))
		goto end
	}

	if y_type == MBLOCK {
		lnum = curwin.w_cursor.lnum + y_size + 1
		if lnum > curbuf.b_ml.ml_line_count {
			lnum = curbuf.b_ml.ml_line_count + 1
		}
		if u_save(curwin.w_cursor.lnum-1, lnum) == FAIL {
			goto end
		}
	} else if y_type == MLINE {
		lnum = curwin.w_cursor.lnum
		if dir == FORWARD {
			lnum++
		}
		var r int32
		if curbuf.b_ml.ml_line_count == 1 && ml_get(1).Get() == NUL {
			r = u_save(0, 2)
		} else {
			r = u_save(lnum-1, lnum)
		}
		if r == FAIL {
			goto end
		}
	} else if u_save_cursor() == FAIL {
		goto end
	}

	if cur_ve_flags == VE_ALL && y_type == MCHAR {
		if gchar_cursor() == TAB {
			var viscol int32 = getviscol()
			var ts int32 = int32(curbuf.b_p_ts)
			var cond bool

			if dir == FORWARD {
				cond = ts-(viscol%ts) != 1
			} else {
				cond = curwin.w_cursor.coladd > 0
			}
			if cond {
				coladvance_force(viscol)
			} else {
				curwin.w_cursor.coladd = 0
			}
		} else if curwin.w_cursor.coladd > 0 || gchar_cursor() == NUL {
			coladvance_force(getviscol() + B2i(dir == FORWARD))
		}
	}

	lnum = curwin.w_cursor.lnum
	col = curwin.w_cursor.col

	if y_type == MBLOCK {
		var delcount int32
		var incr int32 = 0
		var bd S_block_def
		var j int64
		var c int32 = gchar_cursor()
		var endcol2 colnr_T = 0

		if dir == FORWARD && c != NUL {
			if cur_ve_flags == VE_ALL {
				getvcol(curwin, &curwin.w_cursor, &col, nil, &endcol2, 0)
			} else {
				getvcol(curwin, &curwin.w_cursor, nil, nil, &col, 0)
			}

			curwin.w_cursor.col += utfc_ptr2len(ml_get_cursor())
			col++
		} else {
			getvcol(curwin, &curwin.w_cursor, &col, nil, &endcol2, 0)
		}

		col += curwin.w_cursor.coladd
		if cur_ve_flags == VE_ALL && (curwin.w_cursor.coladd > 0 || endcol2 == curwin.w_cursor.col) {
			if dir == FORWARD && c == NUL {
				col++
			}
			if dir != FORWARD && c != NUL && curwin.w_cursor.coladd > 0 {
				curwin.w_cursor.col++
			}
			if c == TAB {
				if dir == -1 && curwin.w_cursor.col != 0 {
					curwin.w_cursor.col--
				}
				if dir == FORWARD && col-1 == endcol2 {
					curwin.w_cursor.col++
				}
			}
		}
		curwin.w_cursor.coladd = 0
		bd.textcol = 0
		for i = 0; i < y_size; i++ {
			var spaces int32 = 0
			var shortline byte
			var cts chartabsize_T

			bd.startspaces = 0
			bd.endspaces = 0
			vcol = 0
			delcount = 0

			if curwin.w_cursor.lnum > curbuf.b_ml.ml_line_count {
				if ml_append(curbuf.b_ml.ml_line_count, S(""), 1) == FAIL {
					break
				}
				nr_lines++
			}
			oldp = ml_get_curline()
			oldlen = ml_get_curline_len()
			init_chartabsize_arg(&cts, curwin, curwin.w_cursor.lnum, 0, oldp, oldp)

			for cts.cts_vcol < col && cts.cts_ptr.Get() != NUL {
				incr = lbr_chartabsize_adv(&cts)
				cts.cts_vcol += incr
			}
			vcol = cts.cts_vcol
			ptr = cts.cts_ptr
			bd.textcol = colnr_T(ptr.Sub(oldp))

			shortline = byte(B2i((vcol < col) || (vcol == col && ptr.Get() == 0)))

			if vcol < col {
				bd.startspaces = col - vcol
			} else if vcol > col {
				bd.endspaces = vcol - col
				bd.startspaces = incr - bd.endspaces
				bd.textcol--
				delcount = 1
				bd.textcol -= utf_head_off(oldp, oldp.Add(int(bd.textcol)))
				if oldp.At(int(bd.textcol)) != TAB {
					delcount = 0
					bd.endspaces = 0
				}
			}

			yanklen = int32(y_array.At(int(i)).length)

			if (flags & PUT_BLOCK_INNER) == 0 {
				spaces = int32(y_width + 1)
				init_chartabsize_arg(&cts, curwin, 0, 0, y_array.At(int(i)).string_, y_array.At(int(i)).string_)

				for cts.cts_ptr.Get() != NUL {
					spaces -= lbr_chartabsize_adv(&cts)
					cts.cts_vcol = 0
				}
				if spaces < 0 {
					spaces = 0
				}
			}

			if yanklen+spaces != 0 && count > int64((INT_MAX-(bd.startspaces+bd.endspaces))/(yanklen+spaces)) {
				emsg(gettext_(e_resulting_text_too_long))
				break
			}

			totlen = int32(count*int64(yanklen+spaces) + int64(bd.startspaces) + int64(bd.endspaces))
			newp = Alloc(int(totlen + oldlen + 1))

			ptr = newp
			Memmove(ptr, oldp, int(usize(bd.textcol)))
			ptr = ptr.Add(int(bd.textcol))

			Memset(ptr, ' ', int(usize(bd.startspaces)))
			ptr = ptr.Add(int(bd.startspaces))

			for j = 0; j < count; j++ {
				Memmove(ptr, y_array.At(int(i)).string_, int(usize(yanklen)))
				ptr = ptr.Add(int(yanklen))

				if (j < count-1 || shortline == 0) && spaces > 0 {
					Memset(ptr, ' ', int(usize(spaces)))
					ptr = ptr.Add(int(spaces))
				} else {
					totlen -= spaces
				}
			}

			Memset(ptr, ' ', int(usize(bd.endspaces)))
			ptr = ptr.Add(int(bd.endspaces))

			Memmove(ptr, oldp.Add(int(bd.textcol+delcount)), int(usize(oldlen-bd.textcol-delcount+1)))
			ml_replace(curwin.w_cursor.lnum, newp, FALSE)

			curwin.w_cursor.lnum++
			if i == 0 {
				curwin.w_cursor.col += bd.startspaces
			}
		}

		changed_lines(lnum, 0, curwin.w_cursor.lnum-nr_lines, nr_lines)

		curbuf.b_op_start = curwin.w_cursor
		curbuf.b_op_start.lnum = lnum

		curbuf.b_op_end.lnum = curwin.w_cursor.lnum - 1
		curbuf.b_op_end.col = bd.textcol + totlen - 1
		if curbuf.b_op_end.col < 0 {
			curbuf.b_op_end.col = 0
		}
		curbuf.b_op_end.coladd = 0
		if (flags & PUT_CURSEND) != 0 {
			var len_ colnr_T

			curwin.w_cursor = curbuf.b_op_end
			curwin.w_cursor.col++

			len_ = ml_get_curline_len()
			if curwin.w_cursor.col > len_ {
				curwin.w_cursor.col = len_
			}
		} else {
			curwin.w_cursor.lnum = lnum
		}
	} else {
		var new_cursor pos_T

		yanklen = int32(y_array.At(0).length)

		if y_type == MCHAR {
			if dir == FORWARD && gchar_cursor() != NUL {
				var bytelen int32 = utfc_ptr2len(ml_get_cursor())

				col += bytelen
				if yanklen != 0 {
					curwin.w_cursor.col += bytelen
					curbuf.b_op_end.col += bytelen
				}
			}
			curbuf.b_op_start = curwin.w_cursor
		} else if dir == -1 {
			lnum--
		}
		new_cursor = curwin.w_cursor

		if y_type == MCHAR && y_size == 1 {
			var end_lnum linenr_T = 0
			var start_lnum linenr_T = lnum
			var first_byte_off int32 = 0

			if VIsual_active != 0 {
				end_lnum = curbuf.b_visual.vi_end.lnum
				if end_lnum < curbuf.b_visual.vi_start.lnum {
					end_lnum = curbuf.b_visual.vi_start.lnum
				}
				if end_lnum > start_lnum {
					var pos pos_T

					pos.lnum = lnum
					pos.col = col
					pos.coladd = 0
					getvcol(curwin, &pos, nil, &vcol, nil, 0)
				}
			}

			if count == 0 || yanklen == 0 {
				if VIsual_active != 0 {
					lnum = end_lnum
				}
			} else if count > int64(INT_MAX/yanklen) {
				emsg(gettext_(e_resulting_text_too_long))
			} else {
				totlen = int32(count * int64(yanklen))
				// C: do { ... continue; ... } while (VIsual_active && lnum <= end_lnum);
				for first := true; first || (VIsual_active != 0 && lnum <= end_lnum); first = false {
					oldp = ml_get(lnum)
					oldlen = ml_get_len(lnum)
					if lnum > start_lnum {
						var pos pos_T

						pos.lnum = lnum
						if getvpos(&pos, vcol) == OK {
							col = pos.col
						} else {
							col = MAXCOL
						}
					}
					if VIsual_active != 0 && col > oldlen {
						lnum++
						continue
					}
					newp = Alloc(int(totlen + oldlen + 1))
					Memmove(newp, oldp, int(usize(col)))
					ptr = newp.Add(int(col))
					for i = 0; i < count; i++ {
						Memmove(ptr, y_array.At(0).string_, int(usize(yanklen)))
						ptr = ptr.Add(int(yanklen))
					}
					Memmove(ptr, oldp.Add(int(col)), int(usize(oldlen-col)+1))

					first_byte_off = utf_head_off(newp, ptr.Add(-1))

					ml_replace(lnum, newp, FALSE)

					inserted_bytes(lnum, col, totlen)

					if lnum == curwin.w_cursor.lnum {
						changed_cline_bef_curs()
						invalidate_botline()
						curwin.w_cursor.col += colnr_T(totlen - 1)
					}
					if VIsual_active != 0 {
						lnum++
					}
				}

				if VIsual_active != 0 {
					lnum--
				}
			}

			curbuf.b_op_end = curwin.w_cursor
			curbuf.b_op_end.col -= first_byte_off

			if totlen != 0 && (restart_edit != 0 || (flags&PUT_CURSEND) != 0) {
				curwin.w_cursor.col++
			} else {
				curwin.w_cursor.col -= first_byte_off
			}
		} else {
			var new_lnum linenr_T = new_cursor.lnum
			var indent int32
			var orig_indent int32 = 0
			var indent_diff int32 = 0
			var first_indent int32 = TRUE
			var lendiff int32 = 0
			var cnt int64

			if (flags & PUT_FIXINDENT) != 0 {
				orig_indent = get_indent()
			}

			for cnt = 1; cnt <= count; cnt++ {
				i = 0
				if y_type == MCHAR {
					lnum = new_cursor.lnum
					ptr = ml_get(lnum).Add(int(col))
					totlen = int32(y_array.At(int(y_size - 1)).length)
					newp = Alloc(int(ml_get_len(lnum) - col + totlen + 1))
					musl_strcpy(newp, y_array.At(int(y_size-1)).string_)
					musl_strcpy(newp.Add(int(totlen)), ptr)
					ml_append(lnum, newp, 0)
					new_lnum++

					oldp = ml_get(lnum)
					newp = Alloc(int(col + yanklen + 1))
					Memmove(newp, oldp, int(usize(col)))
					Memmove(newp.Add(int(col)), y_array.At(0).string_, int(usize(yanklen+1)))
					ml_replace(lnum, newp, FALSE)

					curwin.w_cursor.lnum = lnum
					i = 1
				}

				for ; i < y_size; i++ {
					if y_type != MCHAR || i < y_size-1 {
						if ml_append(lnum, y_array.At(int(i)).string_, 0) == FAIL {
							goto error
						}
						new_lnum++
					}
					lnum++
					nr_lines++
					if (flags & PUT_FIXINDENT) != 0 {
						var old_pos pos_T = curwin.w_cursor

						curwin.w_cursor.lnum = lnum
						ptr = ml_get(lnum)
						if cnt == count && i == y_size-1 {
							lendiff = ml_get_len(lnum)
						}
						if ptr.Get() == '#' && preprocs_left() != 0 {
							indent = 0
						} else if ptr.Get() == NUL {
							indent = 0
						} else if first_indent != 0 {
							indent_diff = orig_indent - get_indent()
							indent = orig_indent
							first_indent = FALSE
						} else {
							indent = get_indent() + indent_diff
							if indent < 0 {
								indent = 0
							}
						}
						set_indent(indent, 0)
						curwin.w_cursor = old_pos
						if cnt == count && i == y_size-1 {
							lendiff -= ml_get_len(lnum)
						}
					}
				}
				if cnt == 1 {
					new_lnum = lnum
				}
			}

		error:
			if y_type == MLINE {
				curbuf.b_op_start.col = 0
				if dir == FORWARD {
					curbuf.b_op_start.lnum++
				}
			}
			mark_adjust(curbuf.b_op_start.lnum+linenr_T(B2i(y_type == MCHAR)), linenr_T(LONG_MAX), nr_lines, 0)

			if y_type == MCHAR {
				changed_lines(curwin.w_cursor.lnum, col, curwin.w_cursor.lnum+1, nr_lines)
			} else {
				changed_lines(curbuf.b_op_start.lnum, 0, curbuf.b_op_start.lnum, nr_lines)
			}
			if !y_current_used.Nil() && (y_current_used != y_current || y_current.P().y_array != y_array) {
				emsg(gettext_(e_yank_register_changed_while_using_it))
				goto end
			}

			curbuf.b_op_end.lnum = new_lnum
			if 0 > colnr_T(y_array.At(int(y_size-1)).length)-lendiff {
				col = 0
			} else {
				col = colnr_T(y_array.At(int(y_size-1)).length) - lendiff
			}
			if col > 1 {
				curbuf.b_op_end.col = col - 1
				if y_array.At(int(y_size-1)).length > 0 {
					curbuf.b_op_end.col -= utf_head_off(y_array.At(int(y_size-1)).string_, y_array.At(int(y_size-1)).string_.Add(int(y_array.At(int(y_size-1)).length)-1))
				}
			} else {
				curbuf.b_op_end.col = 0
			}

			if (flags & PUT_CURSLINE) != 0 {
				curwin.w_cursor.lnum = lnum
				beginline(BL_WHITE | BL_FIX)
			} else if (flags & PUT_CURSEND) != 0 {
				if y_type == MLINE {
					if lnum >= curbuf.b_ml.ml_line_count {
						curwin.w_cursor.lnum = curbuf.b_ml.ml_line_count
					} else {
						curwin.w_cursor.lnum = lnum + 1
					}
					curwin.w_cursor.col = 0
				} else {
					curwin.w_cursor.lnum = new_lnum
					curwin.w_cursor.col = col
					curbuf.b_op_end = curwin.w_cursor
					if col > 1 {
						curbuf.b_op_end.col = col - 1
					}
				}
			} else if y_type == MLINE {
				curwin.w_cursor.col = 0
				if dir == FORWARD {
					curwin.w_cursor.lnum++
				}
				beginline(BL_WHITE | BL_FIX)
			} else {
				curwin.w_cursor = new_cursor
			}
		}
	}

	msgmore(nr_lines)
	curwin.w_set_curswant = true

	len_ = ml_get_curline_len()
	if curwin.w_cursor.col > len_ {
		if cur_ve_flags == VE_ALL {
			curwin.w_cursor.coladd = curwin.w_cursor.col - len_
		}
		curwin.w_cursor.col = len_
	}

end:
	if (cmdmod.cmod_flags & CMOD_LOCKMARKS) != 0 {
		curbuf.b_op_start = orig_start
		curbuf.b_op_end = orig_end
	}

	if regname == '=' {
	}

	VIsual_active = FALSE

	adjust_cursor_eol()
}

func get_register_name(num int32) int32 {
	if num == -1 {
		return '"'
	} else if num < 10 {
		return num + '0'
	} else if num == DELETION_REGISTER {
		return '-'
	} else {
		return num + 'a' - 10
	}
}

func ex_display(eap *S_exarg) {
	var i int32
	var n int32
	var j int64
	var p Ptr[byte]
	var yb Ptr[yankreg_T]
	var name int32
	var attr int32
	var arg Ptr[byte] = eap.arg
	var clen int32
	var type_ int32
	var insert string_T

	silence_w23_w24_msg++
	if !arg.Nil() && arg.Get() == NUL {
		arg = Ptr[byte]{}
	}
	attr = highlight_attr[int(HLF_8)]

	msg_puts_title(gettext_(S("\nType Name Content")))
	for i = -1; i < NUM_REGISTERS && got_int == 0; i++ {
		name = get_register_name(i)
		switch get_reg_type(name, nil) {
		case MLINE:
			type_ = 'l'
		case MCHAR:
			type_ = 'c'
		default:
			type_ = 'b'
		}
		if !arg.Nil() && vim_strchr(arg, name).Nil() {
			continue
		}

		if i == -1 {
			if !y_previous.Nil() {
				yb = y_previous
			} else {
				yb = View(y_regs[:]).Add(0)
			}
		} else {
			yb = View(y_regs[:]).Add(int(i))
		}

		if !yb.P().y_array.Nil() {
			var do_show int32 = FALSE

			for j = 0; do_show == 0 && j < yb.P().y_size; j++ {
				do_show = B2i(message_filtered(yb.P().y_array.At(int(j)).string_) == 0)
			}

			if do_show != 0 || yb.P().y_size == 0 {
				msg_putchar('\n')
				msg_puts(S("  "))
				msg_putchar(type_)
				msg_puts(S("  "))
				msg_putchar('"')
				msg_putchar(name)
				msg_puts(S("   "))

				n = int32(Columns) - 11
				for j = 0; j < yb.P().y_size && n > 1; j++ {
					if j != 0 {
						msg_puts_attr(S("^J"), attr)
						n -= 2
					}
					for p = yb.P().y_array.At(int(j)).string_; ; p = p.Add(1) {
						if p.Get() == NUL {
							break
						}
						n -= ptr2cells(p)
						if !(n >= 0) {
							break
						}
						clen = utfc_ptr2len(p)
						msg_outtrans_len(p, clen)
						p = p.Add(int(clen - 1))
					}
				}
				if n > 1 && yb.P().y_type == MLINE {
					msg_puts_attr(S("^J"), attr)
				}
				out_flush()
			}
			ui_breakcheck()
		}
	}

	insert = get_last_insert()
	p = insert.string_
	if !p.Nil() && (arg.Nil() || !vim_strchr(arg, '.').Nil()) && got_int == 0 && message_filtered(p) == 0 {
		msg_puts(S("\n  c  \".   "))
		dis_msg(p, TRUE)
	}

	if !last_cmdline.Nil() && (arg.Nil() || !vim_strchr(arg, ':').Nil()) && got_int == 0 && message_filtered(last_cmdline) == 0 {
		msg_puts(S("\n  c  \":   "))
		dis_msg(last_cmdline, FALSE)
	}

	if !last_search_pat().Nil() && (arg.Nil() || !vim_strchr(arg, '/').Nil()) && got_int == 0 && message_filtered(last_search_pat()) == 0 {
		msg_puts(S("\n  c  \"/   "))
		dis_msg(last_search_pat(), FALSE)
	}

	silence_w23_w24_msg--
}

func dis_msg(p Ptr[byte], skip_esc int32) {
	var n int32
	var l int32

	n = int32(Columns) - 6
	for {
		if !(p.Get() != NUL && !(p.Get() == ESC && skip_esc != 0 && p.At(1) == NUL)) {
			break
		}
		n -= ptr2cells(p)
		if !(n >= 0) {
			break
		}
		l = utfc_ptr2len(p)
		if l > 1 {
			msg_outtrans_len(p, l)
			p = p.Add(int(l))
		} else {
			q := p
			p = p.Add(1)
			msg_outtrans_len(q, 1)
		}
	}
	ui_breakcheck()
}

func get_reg_type(regname int32, reglen *int64) char_u {
	switch regname {
	case '%', '#', '=', ':', '/', '.', Ctrl_F, Ctrl_P, Ctrl_W, Ctrl_A, '_':
		return MCHAR
	}

	if regname != NUL && valid_yank_reg(regname, FALSE) == 0 {
		return MAUTO
	}

	get_yank_register(regname, FALSE)

	if !y_current.P().y_array.Nil() {
		if reglen != nil && y_current.P().y_type == MBLOCK {
			*reglen = int64(y_current.P().y_width)
		}
		return y_current.P().y_type
	}
	return MAUTO
}

func get_win_attr(wp *S_window_S) int32 {
	var win_attr int32 = wp.w_hlfwin_id
	var override_success bool = push_highlight_overrides(wp.w_hl, wp.w_hl_len)

	if win_attr != 0 {
		if win_attr != -1 {
			win_attr = syn_id2attr(win_attr)
		} else {
			win_attr = 0
		}
	}

	if override_success {
		pop_highlight_overrides()
	}
	return win_attr
}

func screen_fill_end(wp *S_window_S, c1 int32, c2 int32, off int32, width int32, row int32, endrow int32, attr int32) int32 {
	var nn int32 = off + width

	if nn > wp.w_width {
		nn = wp.w_width
	}
	screen_fill(wp.w_winrow+row, wp.w_winrow+endrow, wp.w_wincol+off, wp.w_wincol+nn, c1, c2, attr)
	return nn
}

func win_draw_end(wp *S_window_S, c1 int32, c2 int32, draw_margin int32, row int32, endrow int32, hl hlf_T) {
	var n int32 = 0
	var attr int32 = highlight_attr[int(hl)]
	var win_attr int32 = get_win_attr(wp)
	var override_success bool = push_highlight_overrides(wp.w_hl, wp.w_hl_len)

	attr = hl_combine_attr(win_attr, attr)

	if draw_margin != 0 {
		if (wp.w_onebuf_opt.wo_nu != 0 || wp.w_onebuf_opt.wo_rnu != 0) && vim_strchr(p_cpo, CPO_NUMCOL).Nil() {
			n = screen_fill_end(wp, ' ', ' ', n, 7+1, row, endrow, hl_combine_attr(win_attr, highlight_attr[int(HLF_N)]))
		}
	}

	{
		screen_fill(wp.w_winrow+row, wp.w_winrow+endrow, wp.w_wincol+n, wp.w_wincol+wp.w_width, c1, c2, attr)
	}

	set_empty_rows(wp, row)

	if override_success {
		pop_highlight_overrides()
	}
}

func comp_char_differs(off_from int32, off_to int32) int32 {
	var i int32

	for i = 0; i < Screen_mco; i++ {
		if ScreenLinesC[i].At(int(off_from)) != ScreenLinesC[i].At(int(off_to)) {
			return TRUE
		}
		if ScreenLinesC[i].At(int(off_from)) == 0 {
			break
		}
	}
	return FALSE
}

func char_needs_redraw(off_from int32, off_to int32, cols int32) int32 {
	if cols > 0 && ((ScreenLines.At(int(off_from)) != ScreenLines.At(int(off_to)) || ScreenAttrs.At(int(off_from)) != ScreenAttrs.At(int(off_to))) || (ScreenLinesUC.At(int(off_from)) != ScreenLinesUC.At(int(off_to)) || (ScreenLinesUC.At(int(off_from)) != 0 && comp_char_differs(off_from, off_to) != 0) || (utf_off2cells(uint32(off_from), uint32(off_from+cols)) > 1 && ScreenLines.At(int(off_from+1)) != ScreenLines.At(int(off_to+1))))) {
		return TRUE
	}
	return FALSE
}

func reset_screen_attr() {
	screen_attr = HL_BOLD | HL_UNDERLINE | HL_INVERSE | HL_STRIKETHROUGH
}

func screen_line(wp *S_window_S, row int32, coloff int32, endcol int32, clear_width int32, last_vcol colnr_T, flags int32) {
	var off_from uint32
	var off_to uint32
	var max_off_from uint32
	var max_off_to uint32
	var col int32 = 0
	var hl int32
	var force int32 = FALSE
	var redraw_this int32
	var redraw_next int32
	var clear_next int32 = FALSE
	var char_cells int32
	var override_success bool = push_highlight_overrides(wp.w_hl, wp.w_hl_len)

	if int64(row) >= Rows {
		row = int32(Rows - 1)
	}
	if int64(endcol) > Columns {
		endcol = int32(Columns)
	}

	off_from = uint32(current_ScreenLine.Sub(ScreenLines))
	off_to = LineOffset.At(int(row)) + uint32(coloff)
	max_off_from = off_from + uint32(screen_Columns)
	max_off_to = LineOffset.At(int(row)) + uint32(screen_Columns)

	redraw_next = char_needs_redraw(int32(off_from), int32(off_to), endcol-col)

	for col < endcol {
		if col+1 < endcol {
			char_cells = utf_off2cells(off_from, max_off_from)
		} else {
			char_cells = 1
		}

		redraw_this = redraw_next
		redraw_next = B2i(force != 0 || char_needs_redraw(int32(off_from+uint32(char_cells)), int32(off_to+uint32(char_cells)), endcol-col-char_cells) != 0)

		if redraw_this != 0 {
			if p_wiv != 0 && force == 0 && ScreenAttrs.At(int(off_to)) != 0 && ScreenAttrs.At(int(off_from)) != ScreenAttrs.At(int(off_to)) {
				windgoto(row, col+coloff)
				out_str(term_strings[int(KS_CE)])
				screen_start()
				force = TRUE
				redraw_next = TRUE

				if col+coloff > 0 && ScreenAttrs.At(int(off_to-1)) != 0 {
					screen_attr = int32(ScreenAttrs.At(int(off_to - 1)))
					term_windgoto(row, col+coloff)
					screen_stop_highlight()
				} else {
					screen_attr = 0
				}
			}
			if col+char_cells == endcol && ((char_cells == 1 && utf_off2cells(off_to, max_off_to) > 1) || (char_cells == 2 && utf_off2cells(off_to, max_off_to) == 1 && utf_off2cells(off_to+1, max_off_to) > 1)) {
				clear_next = TRUE
			}

			ScreenLines.Set(int(off_to), ScreenLines.At(int(off_from)))
			ScreenLinesUC.Set(int(off_to), ScreenLinesUC.At(int(off_from)))
			if ScreenLinesUC.At(int(off_from)) != 0 {
				var i int32

				for i = 0; i < Screen_mco; i++ {
					ScreenLinesC[i].Set(int(off_to), ScreenLinesC[i].At(int(off_from)))
				}
			}
			if char_cells == 2 {
				ScreenLines.Set(int(off_to+1), ScreenLines.At(int(off_from+1)))
				ScreenLinesUC.Set(int(off_to+1), 0)
			}

			if term_is_xterm != 0 {
				hl = int32(ScreenAttrs.At(int(off_to)))
				if hl > HL_ALL {
					hl = syn_attr2attr(hl)
				}
				if (hl & HL_BOLD) != 0 {
					redraw_next = TRUE
				}
			}

			ScreenAttrs.Set(int(off_to), ScreenAttrs.At(int(off_from)))
			if char_cells == 2 {
				ScreenAttrs.Set(int(off_to+1), ScreenAttrs.At(int(off_to)))
			}

			screen_char(off_to, row, col+coloff)
		} else if p_wiv != 0 && col+coloff > 0 && off_to > 0 {
			if ScreenAttrs.At(int(off_to)) == ScreenAttrs.At(int(off_to-1)) {
				screen_attr = 0
			} else if screen_attr != 0 {
				screen_stop_highlight()
			}
		}

		{
			ScreenCols.Set(int(off_to), ScreenCols.At(int(off_from)))
			if char_cells == 2 {
				ScreenCols.Set(int(off_to+1), ScreenCols.At(int(off_from+1)))
			}
		}

		off_to += uint32(char_cells)
		off_from += uint32(char_cells)
		col += char_cells
	}

	if clear_next != 0 {
		ScreenLines.Set(int(off_to), ' ')
		ScreenLinesUC.Set(int(off_to), 0)
		screen_char(off_to, row, col+coloff)
	}

	if clear_width > 0 {
		for col < clear_width && ScreenLines.At(int(off_to)) == ' ' && ScreenAttrs.At(int(off_to)) == 0 && ScreenLinesUC.At(int(off_to)) == 0 {
			if (flags & SLF_INC_VCOL) != 0 {
				last_vcol++
				ScreenCols.Set(int(off_to), last_vcol)
			} else {
				ScreenCols.Set(int(off_to), last_vcol)
			}
			off_to++
			col++
		}
		if col < clear_width {
			screen_fill(row, row+1, col+coloff, clear_width+coloff, ' ', ' ', 0)
			for col < clear_width {
				k := off_to
				off_to++
				if (flags & SLF_INC_VCOL) != 0 {
					last_vcol++
					ScreenCols.Set(int(k), last_vcol)
				} else {
					ScreenCols.Set(int(k), last_vcol)
				}
				col++
			}
		}
	}

	if clear_width > 0 {
		if coloff+col < curwin.w_wincol+topframe.fr_width {
			var c int32
			var uc int32

			c = fillchar_vsep(&hl, wp, row)
			if c >= 0x80 {
				uc = c
			} else {
				uc = 0
			}
			if ScreenLines.At(int(off_to)) != schar_T(c) || int32(ScreenLinesUC.At(int(off_to))) != uc || int32(ScreenAttrs.At(int(off_to))) != hl {
				ScreenLines.Set(int(off_to), byte(c))
				ScreenAttrs.Set(int(off_to), sattr_T(hl))
				if c >= 0x80 {
					ScreenLinesUC.Set(int(off_to), u8char_T(c))
					ScreenLinesC[0].Set(int(off_to), 0)
					ScreenLines.Set(int(off_to), 0x80)
				} else {
					ScreenLinesUC.Set(int(off_to), 0)
				}
				screen_char(off_to, row, col+coloff)
			}
		} else {
			LineWraps.Set(int(row), FALSE)
		}
	}

	if override_success {
		pop_highlight_overrides()
	}
}

func draw_vsep_win(wp *S_window_S, row int32) {
	if wp.w_vsep_width == 0 {
		return
	}

	var content_end int32 = wp.w_winrow + wp.w_height

	var start_row int32
	if row == 0 {
		start_row = wp.w_winrow
	} else {
		start_row = wp.w_winrow + row
	}
	for r := start_row; r < content_end; r++ {
		var hl int32
		var c int32 = fillchar_vsep(&hl, wp, r)
		screen_fill(r, r+1, wp.w_wincol+wp.w_width, wp.w_wincol+wp.w_width+1, c, ' ', hl)
	}

	if wp.w_status_height != 0 {
		var hl int32
		var c int32
		c = fillchar_vsep(&hl, wp, content_end)
		for r := content_end; r < content_end+wp.w_status_height; r++ {
			screen_fill(r, r+1, wp.w_wincol+wp.w_width, wp.w_wincol+wp.w_width+1, c, ' ', hl)
		}
	}
}

func screen_putchar(c int32, row int32, col int32, attr int32) {
	buf := Mk[byte](MB_MAXBYTES + 1)

	buf.Set(int(utf_char2bytes(c, buf)), NUL)
	screen_puts(buf, row, col, attr)
}

func screen_getbytes(row int32, col int32, bytes Ptr[byte], attrp *int32) {
	var off uint32

	if ScreenLines.Nil() || row >= screen_Rows || col >= screen_Columns {
		return
	}

	off = LineOffset.At(int(row)) + uint32(col)
	if attrp != nil {
		*attrp = int32(ScreenAttrs.At(int(off)))
	}
	bytes.Set(0, ScreenLines.At(int(off)))
	bytes.Set(1, NUL)

	if ScreenLinesUC.At(int(off)) != 0 {
		bytes.Set(int(utfc_char2bytes(int32(off), bytes)), NUL)
	}
}

func screen_comp_differs(off int32, u8cc Ptr[int32]) int32 {
	var i int32

	for i = 0; i < Screen_mco; i++ {
		if ScreenLinesC[i].At(int(off)) != u8char_T(u8cc.At(int(i))) {
			return TRUE
		}
		if u8cc.At(int(i)) == 0 {
			break
		}
	}
	return FALSE
}

func screen_puts(text Ptr[byte], row int32, col int32, attr int32) {
	screen_puts_len(text, -1, row, col, attr)
}

func screen_puts_len(text Ptr[byte], textlen int32, row int32, col int32, attr_arg int32) {
	var attr int32 = attr_arg
	var off uint32
	var ptr Ptr[byte] = text
	var len_ int32 = textlen
	var c int32
	var max_off uint32
	var mbyte_blen int32 = 1
	var mbyte_cells int32 = 1
	var u8c int32 = 0
	u8cc := Mk[int32](MAX_MCO)
	var clear_next_cell int32 = FALSE
	var force_redraw_this int32
	var force_redraw_next int32 = FALSE
	var need_redraw int32

	if ScreenLines.Nil() || row >= screen_Rows || row < 0 || col >= screen_Columns || col < 0 {
		return
	}
	off = LineOffset.At(int(row)) + uint32(col)

	if col > 0 && col < screen_Columns && mb_fix_col(col, row) != col {
		ScreenLines.Set(int(off-1), ' ')
		ScreenLinesUC.Set(int(off-1), 0)
		ScreenLinesC[0].Set(int(off-1), 0)
		screen_char(off-1, row, col-1)
		force_redraw_next = TRUE
	}

	max_off = LineOffset.At(int(row)) + uint32(screen_Columns)
	for col < screen_Columns && (len_ < 0 || int32(ptr.Sub(text)) < len_) && ptr.Get() != NUL {
		c = int32(ptr.Get())
		if len_ > 0 {
			mbyte_blen = utfc_ptr2len_len(ptr, int32(text.Add(int(len_)).Sub(ptr)))
		} else {
			mbyte_blen = utfc_ptr2len(ptr)
		}
		if len_ >= 0 {
			u8c = utfc_ptr2char_len(ptr, u8cc, int32(text.Add(int(len_)).Sub(ptr)))
		} else {
			u8c = utfc_ptr2char(ptr, u8cc)
		}
		mbyte_cells = utf_char2cells(u8c)
		if col+mbyte_cells > screen_Columns {
			c = '>'
			mbyte_cells = 1
		}

		force_redraw_this = force_redraw_next
		force_redraw_next = FALSE

		var cell_attr int32 = attr
		if screen_pum_blend > 0 && !pum_bg_attrs.Nil() && row >= pum_bg_top && row < pum_bg_bot && col < pum_bg_cols {
			var soff int32 = (row-pum_bg_top)*pum_bg_cols + col
			cell_attr = hl_blend_attr(int32(pum_bg_attrs.At(int(soff))), attr, screen_pum_blend, FALSE)
		}

		{
			var want int32
			if c < 0x80 && u8cc.At(0) == 0 {
				want = 0
			} else {
				want = u8c
			}
			need_redraw = B2i(int32(ScreenLines.At(int(off))) != c || (mbyte_cells == 2 && ScreenLines.At(int(off+1)) != 0) || false || (ScreenLinesUC.At(int(off)) != u8char_T(want) || (ScreenLinesUC.At(int(off)) != 0 && screen_comp_differs(int32(off), u8cc) != 0)) || int32(ScreenAttrs.At(int(off))) != cell_attr)
		}

		if need_redraw != 0 || force_redraw_this != 0 {
			if need_redraw != 0 && ScreenLines.At(int(off)) != ' ' && term_is_xterm != 0 {
				var n int32 = int32(ScreenAttrs.At(int(off)))

				if n > HL_ALL {
					n = syn_attr2attr(n)
				}
				if (n & HL_BOLD) != 0 {
					force_redraw_next = TRUE
				}
			}
			if clear_next_cell != 0 {
				clear_next_cell = FALSE
			} else {
				var at_end bool
				if len_ < 0 {
					at_end = ptr.At(int(mbyte_blen)) == NUL
				} else {
					at_end = ptr.Add(int(mbyte_blen)).Ge(text.Add(int(len_)))
				}
				if at_end && ((mbyte_cells == 1 && utf_off2cells(off, max_off) > 1) || (mbyte_cells == 2 && utf_off2cells(off, max_off) == 1 && utf_off2cells(off+1, max_off) > 1)) {
					clear_next_cell = TRUE
				}
			}

			ScreenLines.Set(int(off), byte(c))
			ScreenAttrs.Set(int(off), sattr_T(cell_attr))
			ScreenCols.Set(int(off), -1)
			if c < 0x80 && u8cc.At(0) == 0 {
				ScreenLinesUC.Set(int(off), 0)
			} else {
				var i int32

				ScreenLinesUC.Set(int(off), u8char_T(u8c))
				for i = 0; i < Screen_mco; i++ {
					ScreenLinesC[i].Set(int(off), u8char_T(u8cc.At(int(i))))
					if u8cc.At(int(i)) == 0 {
						break
					}
				}
			}
			if mbyte_cells == 2 {
				ScreenLines.Set(int(off+1), 0)
				ScreenLinesUC.Set(int(off+1), 0)
				for ci := int32(0); ci < Screen_mco; ci++ {
					ScreenLinesC[ci].Set(int(off+1), 0)
				}
				ScreenAttrs.Set(int(off+1), sattr_T(cell_attr))
				ScreenCols.Set(int(off+1), -1)
			}
			screen_char(off, row, col)
		}
		off += uint32(mbyte_cells)
		col += mbyte_cells
		ptr = ptr.Add(int(mbyte_blen))
		if clear_next_cell != 0 {
			ptr = S(" ")
			len_ = -1
			attr = int32(ScreenAttrs.At(int(off)))
		}
	}

	if force_redraw_next != 0 && col < screen_Columns {
		screen_char(off, row, col)
	}
}

func start_search_hl() {
	if p_hls == 0 || no_hlsearch != 0 {
		return
	}

	end_search_hl()
	last_pat_prog(&screen_search_hl.rm)
}

func end_search_hl() {
	if screen_search_hl.rm.regprog == nil {
		return
	}

	vim_regfree(screen_search_hl.rm.regprog)
	screen_search_hl.rm.regprog = nil
}

func screen_start_highlight(attr int32) {
	var aep *S_attr_entry = nil

	screen_attr = attr
	if full_screen == 0 {
		return
	}

	if attr > HL_ALL {
		if t_colors > 1 {
			aep = syn_cterm_attr2entry(attr)
		} else {
			aep = syn_term_attr2entry(attr)
		}
		if aep == nil {
			attr = 0
		} else {
			attr = int32(aep.ae_attr)
		}
	}
	if (attr&HL_BOLD) != 0 && term_strings[KS_MD].Get() != NUL {
		out_str(term_strings[KS_MD])
	} else if aep != nil && cterm_normal_fg_bold != 0 && (t_colors > 1 && aep.ae_u.cterm.fg_color != 0) {
		out_str(term_strings[KS_ME])
	}
	if (attr&HL_STANDOUT) != 0 && term_strings[KS_SO].Get() != NUL {
		out_str(term_strings[KS_SO])
	}
	if (attr&HL_UNDERCURL) != 0 && term_strings[KS_UCS].Get() != NUL {
		out_str(term_strings[KS_UCS])
	}
	if (attr&HL_UNDERDOUBLE) != 0 && term_strings[KS_USS].Get() != NUL {
		out_str(term_strings[KS_USS])
	}
	if (attr&HL_UNDERDOTTED) != 0 && term_strings[KS_DS].Get() != NUL {
		out_str(term_strings[KS_DS])
	}
	if (attr&HL_UNDERDASHED) != 0 && term_strings[KS_CDS].Get() != NUL {
		out_str(term_strings[KS_CDS])
	}
	if ((attr&HL_UNDERLINE) != 0 || ((attr&HL_UNDERCURL) != 0 && term_strings[KS_UCS].Get() == NUL) || ((attr&HL_UNDERDOUBLE) != 0 && term_strings[KS_USS].Get() == NUL) || ((attr&HL_UNDERDOTTED) != 0 && term_strings[KS_DS].Get() == NUL) || ((attr&HL_UNDERDASHED) != 0 && term_strings[KS_CDS].Get() == NUL)) && term_strings[KS_US].Get() != NUL {
		out_str(term_strings[KS_US])
	}
	if (attr&HL_ITALIC) != 0 && term_strings[KS_CZH].Get() != NUL {
		out_str(term_strings[KS_CZH])
	}
	if (attr&HL_INVERSE) != 0 && term_strings[KS_MR].Get() != NUL {
		out_str(term_strings[KS_MR])
	}
	if (attr&HL_STRIKETHROUGH) != 0 && term_strings[KS_STS].Get() != NUL {
		out_str(term_strings[KS_STS])
	}

	if aep != nil {
		if t_colors > 1 && aep.ae_u.cterm.font > 0 && aep.ae_u.cterm.font < 12 {
			term_font(int32(aep.ae_u.cterm.font))
		}
		if t_colors > 1 {
			if aep.ae_u.cterm.fg_color != 0 {
				term_fg_color(int32(aep.ae_u.cterm.fg_color) - 1)
			}
		}
		if t_colors > 1 {
			if aep.ae_u.cterm.bg_color != 0 {
				term_bg_color(int32(aep.ae_u.cterm.bg_color) - 1)
			}
		}
		if t_colors > 1 {
			if aep.ae_u.cterm.ul_color != 0 {
				term_ul_color(int32(aep.ae_u.cterm.ul_color) - 1)
			}
		}

		if !(t_colors > 1) {
			if !aep.ae_u.term.start.Nil() {
				out_str(aep.ae_u.term.start)
			}
		}
	}
}

func screen_stop_highlight() {
	var do_ME int32 = FALSE

	if screen_attr != 0 {
		{
			var is_under int32

			if screen_attr > HL_ALL {
				var aep *S_attr_entry

				if t_colors > 1 {
					aep = syn_cterm_attr2entry(screen_attr)
					if aep != nil && (aep.ae_u.cterm.fg_color != 0 || aep.ae_u.cterm.bg_color != 0) {
						do_ME = TRUE
					}
				} else {
					aep = syn_term_attr2entry(screen_attr)
					if aep != nil && !aep.ae_u.term.stop.Nil() {
						if musl_strcmp(aep.ae_u.term.stop, term_strings[KS_ME]) == 0 {
							do_ME = TRUE
						} else {
							out_str(aep.ae_u.term.stop)
						}
					}
				}
				if aep == nil {
					screen_attr = 0
				} else {
					screen_attr = int32(aep.ae_attr)
				}
			}

			if (screen_attr & HL_STANDOUT) != 0 {
				if musl_strcmp(term_strings[KS_SE], term_strings[KS_ME]) == 0 {
					do_ME = TRUE
				} else {
					out_str(term_strings[KS_SE])
				}
			}
			is_under = screen_attr & (HL_UNDERCURL | HL_UNDERDOUBLE | HL_UNDERDOTTED | HL_UNDERDASHED)
			if is_under != 0 && term_strings[KS_UCE].Get() != NUL {
				if musl_strcmp(term_strings[KS_UCE], term_strings[KS_ME]) == 0 {
					do_ME = TRUE
				} else {
					out_str(term_strings[KS_UCE])
				}
			}
			if (screen_attr&HL_UNDERLINE) != 0 || (is_under != 0 && term_strings[KS_UCE].Get() == NUL) {
				if musl_strcmp(term_strings[KS_UE], term_strings[KS_ME]) == 0 {
					do_ME = TRUE
				} else {
					out_str(term_strings[KS_UE])
				}
			}
			if (screen_attr & HL_ITALIC) != 0 {
				if musl_strcmp(term_strings[KS_CZR], term_strings[KS_ME]) == 0 {
					do_ME = TRUE
				} else {
					out_str(term_strings[KS_CZR])
				}
			}
			if (screen_attr & HL_STRIKETHROUGH) != 0 {
				if musl_strcmp(term_strings[KS_STE], term_strings[KS_ME]) == 0 {
					do_ME = TRUE
				} else {
					out_str(term_strings[KS_STE])
				}
			}
			if do_ME != 0 || (screen_attr&(HL_BOLD|HL_INVERSE)) != 0 {
				out_str(term_strings[KS_ME])
			}

			{
				if t_colors > 1 {
					if cterm_normal_fg_color != 0 {
						term_fg_color(cterm_normal_fg_color - 1)
					}
					if cterm_normal_bg_color != 0 {
						term_bg_color(cterm_normal_bg_color - 1)
					}
					if cterm_normal_ul_color != 0 {
						term_ul_color(cterm_normal_ul_color - 1)
					}
					if cterm_normal_fg_bold != 0 {
						out_str(term_strings[KS_MD])
					}
				}
			}
		}
	}
	screen_attr = 0
}

func reset_cterm_colors() {
	if !(t_colors > 1) {
		return
	}

	if cterm_normal_fg_color > 0 || cterm_normal_bg_color > 0 {
		out_str(term_strings[KS_OP])
		screen_attr = -1
	}
	if cterm_normal_fg_bold != 0 {
		out_str(term_strings[KS_ME])
		screen_attr = -1
	}
}

func screen_char(off uint32, row int32, col int32) {
	var attr int32

	if row >= screen_Rows || col >= screen_Columns {
		return
	}

	if term_strings[KS_XN].Get() == NUL && row == screen_Rows-1 && col == screen_Columns-1 {
		ScreenAttrs.Set(int(off), ^sattr_T(0)) // (sattr_T)-1
		ScreenCols.Set(int(off), -1)
		return
	}

	if screen_char_attr != 0 {
		attr = screen_char_attr
	} else {
		attr = int32(ScreenAttrs.At(int(off)))
	}
	if screen_attr != attr {
		screen_stop_highlight()
	}

	windgoto(row, col)

	if screen_attr != attr {
		screen_start_highlight(attr)
	}

	if ScreenLinesUC.At(int(off)) != 0 {
		buf := Mk[byte](MB_MAXBYTES + 1)

		if utf_ambiguous_width(int32(ScreenLinesUC.At(int(off)))) != 0 {
			if p_ambw.Get() == 'd' {
				out_str(S("  "))
				term_windgoto(row, col)
			}
			screen_cur_col = 9999
		} else if utf_char2cells(int32(ScreenLinesUC.At(int(off)))) > 1 {
			screen_cur_col++
		}

		buf.Set(int(utfc_char2bytes(int32(off), buf)), NUL)
		out_str(buf)
	} else {
		out_char(uint32(ScreenLines.At(int(off))))
	}

	screen_cur_col++
}

func screen_draw_rectangle(row int32, col int32, height int32, width int32, invert int32) {
	var r int32
	var c int32
	var off int32
	var max_off int32

	if ScreenLines.Nil() {
		return
	}

	if invert != 0 {
		screen_char_attr = HL_INVERSE
	}
	for r = row; r < row+height; r++ {
		off = int32(LineOffset.At(int(r)))
		max_off = off + screen_Columns
		for c = col; c < col+width; c++ {
			screen_char(uint32(off+c), r, c)
			if utf_off2cells(uint32(off+c), uint32(max_off)) > 1 {
				c++
			}
		}
	}
	screen_char_attr = 0
}

func redraw_block(row int32, end int32, wp *S_window_S) {
	var col int32
	var width int32

	if wp == nil {
		col = curwin.w_wincol
		width = topframe.fr_width
	} else {
		col = wp.w_wincol
		width = wp.w_width
	}
	screen_draw_rectangle(row, col, end-row, width, FALSE)
}

func space_to_screenline(off int32, attr int32) {
	ScreenLines.Set(int(off), ' ')
	ScreenAttrs.Set(int(off), sattr_T(attr))
	ScreenCols.Set(int(off), -1)
	ScreenLinesUC.Set(int(off), 0)
}

func screen_fill(start_row int32, end_row int32, start_col int32, end_col int32, c1 int32, c2 int32, attr int32) {
	var row int32
	var col int32
	var off int32
	var end_off int32
	var did_delete int32
	var c int32
	var norm_term int32
	var force_next int32 = FALSE

	if end_row > screen_Rows {
		end_row = screen_Rows
	}
	if end_col > screen_Columns {
		end_col = screen_Columns
	}
	if ScreenLines.Nil() || start_row < 0 || start_row >= end_row || start_col >= end_col {
		return
	}

	norm_term = B2i(!(t_colors > 1))
	for row = start_row; row < end_row; row++ {
		if start_col > 0 && mb_fix_col(start_col, row) != start_col {
			var left_attr int32 = int32(ScreenAttrs.At(int(LineOffset.At(int(row)) + uint32(start_col) - 1)))
			screen_puts_len(S(" "), 1, row, start_col-1, left_attr)
		}
		if end_col < screen_Columns && mb_fix_col(end_col, row) != end_col {
			var right_attr int32 = int32(ScreenAttrs.At(int(LineOffset.At(int(row)) + uint32(end_col))))
			screen_puts_len(S(" "), 1, row, end_col, right_attr)
		}
		did_delete = FALSE
		if c2 == ' ' && int64(end_col) == Columns && can_clear(term_strings[KS_CE]) != 0 && (attr == 0 || (norm_term != 0 && attr <= HL_ALL && ((attr & ^(HL_BOLD | HL_ITALIC)) == 0))) {
			col = start_col
			if c1 != ' ' {
				col++
			}

			off = int32(LineOffset.At(int(row)) + uint32(col))
			end_off = int32(LineOffset.At(int(row)) + uint32(end_col))

			for off < end_off && ScreenLines.At(int(off)) == ' ' && ScreenAttrs.At(int(off)) == 0 && ScreenLinesUC.At(int(off)) == 0 {
				off++
			}
			if off < end_off {
				col = int32(uint32(off) - LineOffset.At(int(row)))
				screen_stop_highlight()
				term_windgoto(row, col)
				out_str(term_strings[KS_CE])
				screen_start()
				col = end_col - col
				for {
					c0 := col
					col--
					if c0 == 0 {
						break
					}
					space_to_screenline(off, 0)
					off++
				}
			}
			did_delete = TRUE
		}

		off = int32(LineOffset.At(int(row)) + uint32(start_col))
		c = c1
		for col = start_col; col < end_col; col++ {
			var uc int32
			if c >= 0x80 {
				uc = c
			} else {
				uc = 0
			}
			if int32(ScreenLines.At(int(off))) != c || int32(ScreenLinesUC.At(int(off))) != uc || int32(ScreenAttrs.At(int(off))) != attr || must_redraw == UPD_CLEAR || force_next != 0 {
				if screen_pum_blend > 0 && c == ' ' && !pum_bg_attrs.Nil() && row >= pum_bg_top && row < pum_bg_bot && col < pum_bg_cols {
					var soff int32 = (row-pum_bg_top)*pum_bg_cols + col

					if !pum_bg_linesUC.Nil() && col > start_col && pum_bg_linesUC.At(int(soff)) == 0 && pum_bg_linesUC.At(int(soff-1)) != 0 && utf_char2cells(int32(pum_bg_linesUC.At(int(soff-1)))) == 2 {
						ScreenLines.Set(int(off), 0)
						if !ScreenLinesUC.Nil() {
							ScreenLinesUC.Set(int(off), 0)
						}
						ScreenAttrs.Set(int(off), ScreenAttrs.At(int(off-1)))
						goto next_col
					}

					var underlying_attr int32 = int32(pum_bg_attrs.At(int(soff)))

					if !pum_bg_linesUC.Nil() && ((pum_bg_linesUC.At(int(soff)) != 0 && utf_char2cells(int32(pum_bg_linesUC.At(int(soff)))) == 2 && col+1 >= end_col) || (col == start_col && pum_bg_linesUC.At(int(soff)) == 0 && col > 0 && pum_bg_linesUC.At(int(soff-1)) != 0 && utf_char2cells(int32(pum_bg_linesUC.At(int(soff-1)))) == 2)) {
						ScreenLines.Set(int(off), ' ')
						if !ScreenLinesUC.Nil() {
							ScreenLinesUC.Set(int(off), 0)
						}
						ScreenAttrs.Set(int(off), sattr_T(hl_pum_blend_attr(underlying_attr, attr, screen_pum_blend)))
						screen_char(uint32(off), row, col)
						goto next_col
					}

					ScreenLines.Set(int(off), pum_bg_lines.At(int(soff)))
					if !pum_bg_linesUC.Nil() && !ScreenLinesUC.Nil() {
						var k int32
						ScreenLinesUC.Set(int(off), pum_bg_linesUC.At(int(soff)))
						for k = 0; k < MAX_MCO; k++ {
							if !pum_bg_linesC[k].Nil() && !ScreenLinesC[k].Nil() {
								ScreenLinesC[k].Set(int(off), pum_bg_linesC[k].At(int(soff)))
							}
						}
					}
					ScreenAttrs.Set(int(off), sattr_T(hl_pum_blend_attr(underlying_attr, attr, screen_pum_blend)))
					screen_char(uint32(off), row, col)
					goto next_col
				}
				if term_is_xterm != 0 {
					if ScreenLines.At(int(off)) != ' ' && (int32(ScreenAttrs.At(int(off))) > HL_ALL || (ScreenAttrs.At(int(off))&HL_BOLD) != 0) {
						force_next = TRUE
					} else {
						force_next = FALSE
					}
				}
				ScreenLines.Set(int(off), byte(c))
				if c >= 0x80 {
					ScreenLinesUC.Set(int(off), u8char_T(c))
					ScreenLinesC[0].Set(int(off), 0)
					ScreenLines.Set(int(off), 0x80)
				} else {
					ScreenLinesUC.Set(int(off), 0)
				}
				ScreenAttrs.Set(int(off), sattr_T(attr))
				if did_delete == 0 || c != ' ' {
					screen_char(uint32(off), row, col)
				}
			}
		next_col:
			ScreenCols.Set(int(off), -1)
			off++
			if col == start_col {
				if did_delete != 0 {
					break
				}
				c = c2
			}
		}
		if int64(end_col) == Columns {
			LineWraps.Set(int(row), FALSE)
		}
		if int64(row) == Rows-1 {
			redraw_cmdline = TRUE
			if ((start_col == 0 && int64(end_col) == Columns) || (start_col == cmdline_col_off && end_col == cmdline_col_off+cmdline_width)) && c1 == ' ' && c2 == ' ' && attr == 0 {
				clear_cmdline = FALSE
			}
			if start_col == 0 || start_col == cmdline_col_off {
				mode_displayed = FALSE
			}
		}
	}
}

func check_for_delay(check_msg_scroll int32) {
	if (emsg_on_display != 0 || (check_msg_scroll != 0 && msg_scroll != 0)) && did_wait_return == 0 && emsg_silent == 0 && in_assert_fails == 0 {
		out_flush()
		ui_delay(1006, TRUE)
		emsg_on_display = FALSE
		if check_msg_scroll != 0 {
			msg_scroll = FALSE
		}
	}
}

func clear_TabPageIdxs() {
	var scol int32

	for scol = 0; int64(scol) < Columns; scol++ {
		TabPageIdxs.Set(int(scol), 0)
	}
}

func screen_valid(doclear int32) int32 {
	screenalloc(doclear)
	return B2i(!ScreenLines.Nil())
}

func init() {
	screenalloc_entered = FALSE
	screenalloc_done_outofmem_msg = FALSE
}

func screenalloc(doclear int32) {
	var new_row int32
	var old_row int32
	var wp *S_window_S
	var outofmem int32 = FALSE
	var len_ int32
	var new_ScreenLines Ptr[schar_T]
	var new_ScreenLinesUC Ptr[u8char_T] = Ptr[u8char_T]{}
	var new_ScreenLinesC [MAX_MCO]Ptr[u8char_T]
	var new_ScreenLines2 Ptr[schar_T] = Ptr[schar_T]{}
	var new_ScreenAttrs Ptr[sattr_T]
	var new_ScreenCols Ptr[colnr_T]
	var new_LineOffset Ptr[uint32]
	var new_LineWraps Ptr[byte]
	var new_TabPageIdxs Ptr[int16]
	var retry_count int32 = 0
	var found_null int32

retry:
	if (!ScreenLines.Nil() && Rows == int64(screen_Rows) && Columns == int64(screen_Columns) && TRUE == B2i(!ScreenLinesUC.Nil()) && FALSE == B2i(!ScreenLines2.Nil()) && p_mco == int64(Screen_mco)) || Rows == 0 || Columns == 0 || (full_screen == 0 && ScreenLines.Nil()) {
		return
	}

	if screenalloc_entered != 0 {
		return
	}
	screenalloc_entered = TRUE

	RedrawingDisabled++

	win_new_shellsize()

	comp_col()

	wp = curwin
	win_free_lsize(wp)
	new_ScreenLines = Mk[schar_T](int((Rows + 1) * Columns))
	new_ScreenLinesC = [MAX_MCO]Ptr[u8char_T]{}
	new_ScreenLinesUC = Mk[u8char_T](int((Rows + 1) * Columns))
	for i := 0; int64(i) < p_mco; i++ {
		new_ScreenLinesC[i] = Mk[u8char_T](int((Rows + 1) * Columns))
	}
	new_ScreenAttrs = Mk[sattr_T](int((Rows + 1) * Columns))
	new_ScreenCols = Mk[colnr_T](int((Rows + 1) * Columns))
	new_LineOffset = Mk[uint32](int(Rows))
	new_LineWraps = Mk[byte](int(Rows))
	new_TabPageIdxs = Mk[int16](int(Columns))

	wp = curwin
	if win_alloc_lines(wp) == FAIL {
		outofmem = TRUE
		goto give_up
	}
give_up:
	found_null = FALSE
	for i := 0; int64(i) < p_mco; i++ {
		if new_ScreenLinesC[i].Nil() {
			found_null = TRUE
			break
		}
	}
	if new_ScreenLines.Nil() || (new_ScreenLinesUC.Nil() || found_null != 0) || new_ScreenAttrs.Nil() || new_ScreenCols.Nil() || new_LineOffset.Nil() || new_LineWraps.Nil() || new_TabPageIdxs.Nil() || outofmem != 0 {
		if !ScreenLines.Nil() || screenalloc_done_outofmem_msg == 0 {
			do_outofmem_msg(usize(long_u((Rows + 1) * Columns)))

			screenalloc_done_outofmem_msg = TRUE
		}
		new_ScreenLines = Ptr[schar_T]{}
		new_ScreenLinesUC = Ptr[u8char_T]{}
		for i := 0; int64(i) < p_mco; i++ {
			new_ScreenLinesC[i] = Ptr[u8char_T]{}
		}
		new_ScreenLines2 = Ptr[schar_T]{}
		new_ScreenAttrs = Ptr[sattr_T]{}
		new_ScreenCols = Ptr[colnr_T]{}
		new_LineOffset = Ptr[uint32]{}
		new_LineWraps = Ptr[byte]{}
		new_TabPageIdxs = Ptr[int16]{}
	} else {
		screenalloc_done_outofmem_msg = FALSE

		for new_row = 0; int64(new_row) < Rows; new_row++ {
			new_LineOffset.Set(int(new_row), uint32(int64(new_row)*Columns))
			new_LineWraps.Set(int(new_row), FALSE)

			Memset(new_ScreenLines.Add(int(int64(new_row)*Columns)), ' ', int(usize(Columns)))
			Zero(new_ScreenLinesUC.Add(int(int64(new_row)*Columns)), int(Columns))
			for i := 0; int64(i) < p_mco; i++ {
				Zero(new_ScreenLinesC[i].Add(int(int64(new_row)*Columns)), int(Columns))
			}
			Zero(new_ScreenAttrs.Add(int(int64(new_row)*Columns)), int(Columns))
			Zero(new_ScreenCols.Add(int(int64(new_row)*Columns)), int(Columns))

			if doclear == 0 {
				old_row = int32(int64(new_row) + (int64(screen_Rows) - Rows))
				if old_row >= 0 && !ScreenLines.Nil() {
					if int64(screen_Columns) < Columns {
						len_ = screen_Columns
					} else {
						len_ = int32(Columns)
					}
					if !ScreenLinesUC.Nil() && p_mco == int64(Screen_mco) {
						Memmove(new_ScreenLines.Add(int(new_LineOffset.At(int(new_row)))), ScreenLines.Add(int(LineOffset.At(int(old_row)))), int(len_))
					}
					if !ScreenLinesUC.Nil() && p_mco == int64(Screen_mco) {
						Memmove(new_ScreenLinesUC.Add(int(new_LineOffset.At(int(new_row)))), ScreenLinesUC.Add(int(LineOffset.At(int(old_row)))), int(len_))
						for i := 0; int64(i) < p_mco; i++ {
							Memmove(new_ScreenLinesC[i].Add(int(new_LineOffset.At(int(new_row)))), ScreenLinesC[i].Add(int(LineOffset.At(int(old_row)))), int(len_))
						}
					}
					Memmove(new_ScreenAttrs.Add(int(new_LineOffset.At(int(new_row)))), ScreenAttrs.Add(int(LineOffset.At(int(old_row)))), int(len_))
					Memmove(new_ScreenCols.Add(int(new_LineOffset.At(int(new_row)))), ScreenCols.Add(int(LineOffset.At(int(old_row)))), int(len_))
				}
			}
		}
		current_ScreenLine = new_ScreenLines.Add(int(Rows * Columns))

	}

	free_screenlines()

	ScreenLines = new_ScreenLines
	ScreenLinesUC = new_ScreenLinesUC
	for i := 0; int64(i) < p_mco; i++ {
		ScreenLinesC[i] = new_ScreenLinesC[i]
	}
	Screen_mco = int32(p_mco)
	ScreenLines2 = new_ScreenLines2
	ScreenAttrs = new_ScreenAttrs
	ScreenCols = new_ScreenCols
	LineOffset = new_LineOffset
	LineWraps = new_LineWraps
	TabPageIdxs = new_TabPageIdxs

	screen_Rows = int32(Rows)
	screen_Columns = int32(Columns)

	set_must_redraw(UPD_CLEAR)
	if doclear != 0 {
		screenclear2(TRUE)
	}
	clear_TabPageIdxs()

	screenalloc_entered = FALSE
	if RedrawingDisabled > 0 {
		RedrawingDisabled--
	}

	if starting == 0 {
		retry_count++
		if retry_count <= 3 {
			goto retry
		}
	}
}

func free_screenlines() {
	var i int32

	ScreenLinesUC = Ptr[u8char_T]{}
	for i = 0; i < Screen_mco; i++ {
		ScreenLinesC[i] = Ptr[u8char_T]{}
	}
	ScreenLines2 = Ptr[schar_T]{}
	ScreenLines = Ptr[schar_T]{}
	ScreenAttrs = Ptr[sattr_T]{}
	ScreenCols = Ptr[colnr_T]{}
	LineOffset = Ptr[uint32]{}
	LineWraps = Ptr[byte]{}
	TabPageIdxs = Ptr[int16]{}
}

func screenclear() int32 {
	check_for_delay(FALSE)
	screenalloc(FALSE)
	return screenclear2(TRUE)
}

func redraw_as_cleared() {
	screenclear2(FALSE)
}

func screenclear2(doclear int32) int32 {
	var i int32
	var did_clear int32 = FALSE

	if starting == NO_SCREEN || ScreenLines.Nil() {
		return FALSE
	}

	screen_attr = -1
	screen_stop_highlight()

	for i = 0; int64(i) < Rows; i++ {
		lineclear(LineOffset.At(int(i)), int32(Columns), 0)
		LineWraps.Set(int(i), FALSE)
	}

	if doclear != 0 && can_clear(term_strings[KS_CL]) != 0 {
		out_str(term_strings[KS_CL])
		did_clear = TRUE
		clear_cmdline = FALSE
		mode_displayed = FALSE
	} else {
		for i = 0; int64(i) < Rows; i++ {
			lineinvalid(LineOffset.At(int(i)), int32(Columns))
		}
		clear_cmdline = TRUE
	}

	screen_cleared = TRUE

	win_rest_invalid(curwin)
	redraw_cmdline = TRUE
	redraw_tabline = TRUE
	if must_redraw == UPD_CLEAR {
		must_redraw = UPD_NOT_VALID
	}
	msg_scrolled = 0
	compute_cmdrow()
	msg_row = cmdline_row
	msg_col = 0
	screen_start()
	msg_didany = FALSE
	msg_didout = FALSE

	return did_clear
}

// lineclear and lineinvalid: the C memsets ScreenAttrs (uint16) and
// ScreenCols (int32) bytewise, so every element becomes the byte repeated.
func lineclear(off uint32, width int32, attr int32) {
	Memset(ScreenLines.Add(int(off)), ' ', int(usize(width)))
	Zero(ScreenLinesUC.Add(int(off)), int(width))
	{
		v := sattr_T(byte(attr)) * 0x0101
		s := ScreenAttrs.Add(int(off)).Slice(int(width))
		for k := range s {
			s[k] = v
		}
	}
	{
		s := ScreenCols.Add(int(off)).Slice(int(width))
		for k := range s {
			s[k] = -1
		}
	}
}

func lineinvalid(off uint32, width int32) {
	{
		s := ScreenAttrs.Add(int(off)).Slice(int(width))
		for k := range s {
			s[k] = ^sattr_T(0)
		}
	}
	{
		s := ScreenCols.Add(int(off)).Slice(int(width))
		for k := range s {
			s[k] = -1
		}
	}
}

func linecopy(to int32, from int32, wp *S_window_S) {
	var off_to uint32 = LineOffset.At(int(to)) + uint32(wp.w_wincol)
	var off_from uint32 = LineOffset.At(int(from)) + uint32(wp.w_wincol)

	Memmove(ScreenLines.Add(int(off_to)), ScreenLines.Add(int(off_from)), int(wp.w_width))
	var i int32

	Memmove(ScreenLinesUC.Add(int(off_to)), ScreenLinesUC.Add(int(off_from)), int(wp.w_width))
	for i = 0; int64(i) < p_mco; i++ {
		Memmove(ScreenLinesC[i].Add(int(off_to)), ScreenLinesC[i].Add(int(off_from)), int(wp.w_width))
	}
	Memmove(ScreenAttrs.Add(int(off_to)), ScreenAttrs.Add(int(off_from)), int(wp.w_width))
	Memmove(ScreenCols.Add(int(off_to)), ScreenCols.Add(int(off_from)), int(wp.w_width))
}

func can_clear(p Ptr[byte]) int32 {
	return B2i(p.Get() != NUL && (t_colors <= 1 || cterm_normal_bg_color == 0 || term_strings[KS_UT].Get() != NUL))
}

func screen_start() {
	screen_cur_col = 9999
	screen_cur_row = screen_cur_col
}

func windgoto(row int32, col int32) {
	var p Ptr[sattr_T]
	var i int32
	var plan int32
	var cost int32
	var wouldbe_col int32
	var noinvcurs int32
	var bs Ptr[byte]
	var goto_cost int32
	var attr int32

	if ScreenLines.Nil() {
		return
	}
	if col == screen_cur_col && row == screen_cur_row {
		return
	}

	if row < 0 {
		row = 0
	}
	if row >= screen_Rows {
		row = screen_Rows - 1
	}
	if col >= screen_Columns {
		col = screen_Columns - 1
	}

	if screen_attr != 0 && term_strings[KS_MS].Get() == NUL {
		noinvcurs = HIGHL_COST
	} else {
		noinvcurs = 0
	}
	goto_cost = GOTO_COST + noinvcurs

	if row >= screen_cur_row && int64(screen_cur_col) < Columns {
		bs = Ptr[byte]{}
		attr = screen_attr
		if row == screen_cur_row && col < screen_cur_col {
			if term_strings[KS_LE].Get() != 0 {
				bs = term_strings[KS_LE]
			} else {
				bs = term_strings[KS_BC]
			}
			if bs.Get() != 0 {
				cost = (screen_cur_col - col) * int32(musl_strlen(bs))
			} else {
				cost = 999
			}
			if col+1 < cost {
				plan = PLAN_CR
				wouldbe_col = 0
				cost = 1
			} else {
				plan = PLAN_LE
				wouldbe_col = col
			}
			if noinvcurs != 0 {
				cost += noinvcurs
				attr = 0
			}
		} else if row > screen_cur_row {
			plan = PLAN_NL
			wouldbe_col = 0
			cost = (row - screen_cur_row) * 2
			if noinvcurs != 0 {
				cost += noinvcurs
				attr = 0
			}
		} else {
			plan = PLAN_WRITE
			wouldbe_col = screen_cur_col
			cost = 0
		}

		i = col - wouldbe_col
		if i > 0 {
			cost += i
		}
		if cost < goto_cost && i > 0 {
			p = ScreenAttrs.Add(int(LineOffset.At(int(row))) + int(wouldbe_col))
			for i != 0 {
				v := p.Get()
				p = p.Add(1)
				if int32(v) != attr {
					break
				}
				i--
			}
			if i != 0 {
				p = p.Add(-1)
				if p.Get() == 0 {
					cost += noinvcurs
					for i != 0 {
						v := p.Get()
						p = p.Add(1)
						if v != 0 {
							break
						}
						i--
					}
				}
				if i != 0 {
					cost = 999
				}
			}
			for i = wouldbe_col; i < col; i++ {
				if ScreenLinesUC.At(int(LineOffset.At(int(row))+uint32(i))) != 0 {
					cost = 999
					break
				}
			}
		}

		if cost < goto_cost {
			if plan == PLAN_LE {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				for screen_cur_col > col {
					out_str(bs)
					screen_cur_col--
				}
			} else if plan == PLAN_CR {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				out_char('\r')
				screen_cur_col = 0
			} else if plan == PLAN_NL {
				if noinvcurs != 0 {
					screen_stop_highlight()
				}
				for screen_cur_row < row {
					out_char('\n')
					screen_cur_row++
				}
				screen_cur_col = 0
			}

			i = col - screen_cur_col
			if i > 0 {
				if term_strings[KS_ND].At(0) != NUL && term_strings[KS_ND].At(1) == NUL {
					for {
						c0 := i
						i--
						if !(c0 > 0) {
							break
						}
						out_char(uint32(term_strings[KS_ND].Get()))
					}
				} else {
					var off int32

					off = int32(LineOffset.At(int(row)) + uint32(screen_cur_col))
					for {
						c0 := i
						i--
						if !(c0 > 0) {
							break
						}
						if int32(ScreenAttrs.At(int(off))) != screen_attr {
							screen_stop_highlight()
						}
						out_char(uint32(ScreenLines.At(int(off))))
						off++
					}
				}
			}
		}
	} else {
		cost = 999
	}

	if cost >= goto_cost {
		if noinvcurs != 0 {
			screen_stop_highlight()
		}
		if row == screen_cur_row && col > screen_cur_col && term_strings[KS_CRI].Get() != NUL {
			term_cursor_right(col - screen_cur_col)
		} else {
			term_windgoto(row, col)
		}
	}
	screen_cur_row = row
	screen_cur_col = col
}

func setcursor() {
	setcursor_mayforce(FALSE)
}

func setcursor_mayforce(force int32) {
	if force != 0 || redrawing() != 0 {
		validate_cursor()
		windgoto(curwin.w_winrow+curwin.w_wrow, curwin.w_wincol+curwin.w_wcol)
	}
}

func win_ins_lines(wp *S_window_S, row int32, line_count int32, invalid int32, mayclear int32) int32 {
	var did_delete int32
	var nextrow int32
	var lastrow int32
	var retval int32

	if invalid != 0 {
		wp.w_lines_valid = 0
	}

	if wp.w_height < 5 {
		return FAIL
	}

	if line_count > wp.w_height-row {
		line_count = wp.w_height - row
	}

	retval = win_do_lines(wp, row, line_count, mayclear, FALSE, 0)
	if retval != MAYBE {
		return retval
	}

	did_delete = FALSE
	if wp.w_status_height != 0 {
		if screen_del_lines(0, wp.w_winrow+wp.w_height-line_count, line_count, int32(Rows), FALSE, 0, nil) == OK {
			did_delete = TRUE
		}
	}
	if did_delete == 0 {
		wp.w_redr_status = true
		redraw_cmdline = TRUE
		nextrow = wp.w_winrow + wp.w_height + wp.w_status_height
		lastrow = nextrow + line_count
		if int64(lastrow) > Rows {
			lastrow = int32(Rows)
		}
		screen_fill(nextrow-line_count, lastrow-line_count, wp.w_wincol, wp.w_wincol+wp.w_width, ' ', ' ', 0)
	}

	if screen_ins_lines(0, wp.w_winrow+row, line_count, int32(Rows), 0, nil) == FAIL {
		if did_delete != 0 {
			wp.w_redr_status = true
		}
		return FAIL
	}

	return OK
}

func win_del_lines(wp *S_window_S, row int32, line_count int32, invalid int32, mayclear int32, clear_attr int32) int32 {
	var retval int32

	if invalid != 0 {
		wp.w_lines_valid = 0
	}

	if line_count > wp.w_height-row {
		line_count = wp.w_height - row
	}

	retval = win_do_lines(wp, row, line_count, mayclear, TRUE, clear_attr)
	if retval != MAYBE {
		return retval
	}

	if screen_del_lines(0, wp.w_winrow+row, line_count, int32(Rows), FALSE, clear_attr, nil) == FAIL {
		return FAIL
	}

	if wp.w_status_height != 0 || int64(cmdline_row) < Rows-1 {
		if screen_ins_lines(0, wp.w_winrow+wp.w_height-line_count, line_count, int32(Rows), clear_attr, nil) == FAIL {
			wp.w_redr_status = true
		}
	} else {
		redraw_cmdline = TRUE
	}
	return OK
}

func win_do_lines(wp *S_window_S, row int32, line_count int32, mayclear int32, del int32, clear_attr int32) int32 {
	var retval int32

	if redrawing() == 0 || line_count <= 0 {
		return FAIL
	}

	if no_win_do_lines_ins != 0 && del == 0 {
		return FAIL
	}

	if mayclear != 0 && Rows-int64(line_count) < 5 && wp.w_width == topframe.fr_width {
		if no_win_do_lines_ins == 0 {
			redraw_as_cleared()
		}
		return FAIL
	}

	if row+line_count >= wp.w_height {
		screen_fill(wp.w_winrow+row, wp.w_winrow+wp.w_height, wp.w_wincol, wp.w_wincol+wp.w_width, ' ', ' ', 0)
		return OK
	}

	if no_win_do_lines_ins == 0 {
		clear_cmdline = TRUE
	}

	if scroll_region != 0 || wp.w_width != topframe.fr_width {
		if scroll_region != 0 && (wp.w_width == topframe.fr_width || term_strings[KS_CSV].Get() != NUL) {
			scroll_region_set(wp, row)
		}
		if del != 0 {
			retval = screen_del_lines(wp.w_winrow+row, 0, line_count, wp.w_height-row, FALSE, clear_attr, wp)
		} else {
			retval = screen_ins_lines(wp.w_winrow+row, 0, line_count, wp.w_height-row, clear_attr, wp)
		}
		if scroll_region != 0 && (wp.w_width == topframe.fr_width || term_strings[KS_CSV].Get() != NUL) {
			scroll_region_reset()
		}
		return retval
	}

	return MAYBE
}

// ==== from f15.go ====
// Transpiled by hand from editor.c: win_rest_invalid .. report_term_error.

func win_rest_invalid(wp *S_window_S) {
	redraw_win_later(wp, UPD_NOT_VALID)
	wp.w_redr_status = true
	redraw_cmdline = TRUE
}

func screen_ins_lines(off int32, row int32, line_count int32, end int32, clear_attr int32, wp *S_window_S) int32 {
	var i int32
	var j int32
	var temp uint32
	var cursor_row int32
	var cursor_col int32 = 0
	var type_ int32
	var result_empty int32
	var can_ce int32 = can_clear(term_strings[int32(KS_CE)])

	if screen_valid(TRUE) == 0 || line_count <= 0 || int64(line_count) > p_ttyscroll || int64(end) > Rows {
		return FAIL
	}

	result_empty = B2i(row+line_count >= end)
	if wp != nil && wp.w_width != topframe.fr_width && term_strings[int32(KS_CSV)].Get() == NUL {
		if line_count > 3 {
			return FAIL
		}
		type_ = USE_REDRAW
	} else if can_clear(term_strings[int32(KS_CD)]) != 0 && result_empty != 0 {
		type_ = USE_T_CD
	} else if term_strings[int32(KS_CAL)].Get() != NUL && (line_count > 1 || term_strings[int32(KS_AL)].Get() == NUL) {
		type_ = USE_T_CAL
	} else if term_strings[int32(KS_CDL)].Get() != NUL && result_empty != 0 && (line_count > 1 || can_ce == 0) {
		type_ = USE_T_CDL
	} else if term_strings[int32(KS_AL)].Get() != NUL {
		type_ = USE_T_AL
	} else if can_ce != 0 && result_empty != 0 {
		type_ = USE_T_CE
	} else if term_strings[int32(KS_DL)].Get() != NUL && result_empty != 0 {
		type_ = USE_T_DL
	} else if term_strings[int32(KS_SR)].Get() != NUL && row == 0 && (term_strings[int32(KS_DA)].Get() == NUL || can_ce != 0) {
		type_ = USE_T_SR
	} else {
		return FAIL
	}

	if type_ == USE_T_CD || type_ == USE_T_CDL || type_ == USE_T_CE || type_ == USE_T_DL {
		return screen_del_lines(off, row, line_count, end, FALSE, 0, wp)
	}

	if term_strings[int32(KS_DB)].Get() != 0 {
		screen_del_lines(off, end-line_count, line_count, end, FALSE, 0, wp)
	}

	if wp != nil && wp.w_wincol != 0 && term_strings[int32(KS_CSV)].Get() != NUL && term_strings[int32(KS_CCS)].Get() == NUL {
		cursor_col = wp.w_wincol
	}

	if term_strings[int32(KS_CCS)].Get() != NUL {
		cursor_row = row
	} else {
		cursor_row = row + off
	}

	row += off
	end += off
	for i = 0; i < line_count; i++ {
		if wp != nil && wp.w_width != topframe.fr_width {
			j = end - 1 - i
			for {
				j -= line_count
				if !(j >= row) {
					break
				}
				linecopy(j+line_count, j, wp)
			}
			j += line_count
			if can_clear(S(" ")) != 0 {
				lineclear(LineOffset.At(int(j))+uint32(wp.w_wincol), wp.w_width, clear_attr)
			} else {
				lineinvalid(LineOffset.At(int(j))+uint32(wp.w_wincol), wp.w_width)
			}
			LineWraps.Set(int(j), FALSE)
		} else {
			j = end - 1 - i
			temp = LineOffset.At(int(j))
			for {
				j -= line_count
				if !(j >= row) {
					break
				}
				LineOffset.Set(int(j+line_count), LineOffset.At(int(j)))
				LineWraps.Set(int(j+line_count), LineWraps.At(int(j)))
			}
			LineOffset.Set(int(j+line_count), temp)
			LineWraps.Set(int(j+line_count), FALSE)
			if can_clear(S(" ")) != 0 {
				lineclear(temp, int32(Columns), clear_attr)
			} else {
				lineinvalid(temp, int32(Columns))
			}
		}
	}

	screen_stop_highlight()
	windgoto(cursor_row, cursor_col)
	if clear_attr != 0 {
		screen_start_highlight(clear_attr)
	}

	if type_ == USE_REDRAW {
		redraw_block(row, end, wp)
	} else if type_ == USE_T_CAL {
		term_append_lines(line_count)
		screen_start()
	} else {
		for i = 0; i < line_count; i++ {
			if type_ == USE_T_AL {
				if i != 0 && cursor_row != 0 {
					windgoto(cursor_row, cursor_col)
				}
				out_str(term_strings[int32(KS_AL)])
			} else {
				out_str(term_strings[int32(KS_SR)])
			}
			screen_start()
		}
	}

	if type_ == USE_T_SR && term_strings[int32(KS_DA)].Get() != 0 {
		for i = 0; i < line_count; i++ {
			windgoto(off+i, cursor_col)
			out_str(term_strings[int32(KS_CE)])
			screen_start()
		}
	}

	return OK
}

func screen_del_lines(off int32, row int32, line_count int32, end int32, force int32, clear_attr int32, wp *S_window_S) int32 {
	var j int32
	var i int32
	var temp uint32
	var cursor_row int32
	var cursor_col int32 = 0
	var cursor_end int32
	var result_empty int32
	var can_delete int32
	var type_ int32

	if screen_valid(TRUE) == 0 || line_count <= 0 || (force == 0 && int64(line_count) > p_ttyscroll) || int64(end) > Rows {
		return FAIL
	}

	result_empty = B2i(row+line_count >= end)

	can_delete = B2i(term_strings[int32(KS_DB)].Get() == NUL || can_clear(term_strings[int32(KS_CE)]) != 0)

	if wp != nil && wp.w_width != topframe.fr_width && term_strings[int32(KS_CSV)].Get() == NUL {
		if line_count > 3 {
			return FAIL
		}
		type_ = USE_REDRAW
	} else if can_clear(term_strings[int32(KS_CD)]) != 0 && result_empty != 0 {
		type_ = USE_T_CD
	} else if row == 0 && (line_count == 1 || term_strings[int32(KS_CDL)].Get() == NUL) {
		type_ = USE_NL
	} else if term_strings[int32(KS_CDL)].Get() != NUL && line_count > 1 && can_delete != 0 {
		type_ = USE_T_CDL
	} else if can_clear(term_strings[int32(KS_CE)]) != 0 && result_empty != 0 && (wp == nil || wp.w_width == topframe.fr_width) {
		type_ = USE_T_CE
	} else if term_strings[int32(KS_DL)].Get() != NUL && can_delete != 0 {
		type_ = USE_T_DL
	} else if term_strings[int32(KS_CDL)].Get() != NUL && can_delete != 0 {
		type_ = USE_T_CDL
	} else {
		return FAIL
	}

	if wp != nil && wp.w_wincol != 0 && term_strings[int32(KS_CSV)].Get() != NUL && term_strings[int32(KS_CCS)].Get() == NUL {
		cursor_col = wp.w_wincol
	}

	if term_strings[int32(KS_CCS)].Get() != NUL {
		cursor_row = row
		cursor_end = end
	} else {
		cursor_row = row + off
		cursor_end = end + off
	}

	row += off
	end += off
	for i = 0; i < line_count; i++ {
		if wp != nil && wp.w_width != topframe.fr_width {
			j = row + i
			for {
				j += line_count
				if !(j <= end-1) {
					break
				}
				linecopy(j-line_count, j, wp)
			}
			j -= line_count
			if can_clear(S(" ")) != 0 {
				lineclear(LineOffset.At(int(j))+uint32(wp.w_wincol), wp.w_width, clear_attr)
			} else {
				lineinvalid(LineOffset.At(int(j))+uint32(wp.w_wincol), wp.w_width)
			}
			LineWraps.Set(int(j), FALSE)
		} else {
			j = row + i
			temp = LineOffset.At(int(j))
			for {
				j += line_count
				if !(j <= end-1) {
					break
				}
				LineOffset.Set(int(j-line_count), LineOffset.At(int(j)))
				LineWraps.Set(int(j-line_count), LineWraps.At(int(j)))
			}
			LineOffset.Set(int(j-line_count), temp)
			LineWraps.Set(int(j-line_count), FALSE)
			if can_clear(S(" ")) != 0 {
				lineclear(temp, int32(Columns), clear_attr)
			} else {
				lineinvalid(temp, int32(Columns))
			}
		}
	}

	if screen_attr != clear_attr {
		screen_stop_highlight()
	}
	if clear_attr != 0 {
		screen_start_highlight(clear_attr)
	}

	if type_ == USE_REDRAW {
		redraw_block(row, end, wp)
	} else if type_ == USE_T_CD {
		windgoto(cursor_row, cursor_col)
		out_str(term_strings[int32(KS_CD)])
		screen_start()
	} else if type_ == USE_T_CDL {
		windgoto(cursor_row, cursor_col)
		term_delete_lines(line_count)
		screen_start()
	} else if type_ == USE_NL {
		windgoto(cursor_end-1, cursor_col)
		i = line_count
		for {
			i--
			if !(i >= 0) {
				break
			}
			out_char('\n')
		}
	} else {
		i = line_count
		for {
			i--
			if !(i >= 0) {
				break
			}
			if type_ == USE_T_DL {
				windgoto(cursor_row, cursor_col)
				out_str(term_strings[int32(KS_DL)])
			} else {
				windgoto(cursor_row+i, cursor_col)
				out_str(term_strings[int32(KS_CE)])
			}
			screen_start()
		}
	}

	if term_strings[int32(KS_DB)].Get() != 0 && (type_ == USE_T_DL || type_ == USE_T_CDL) {
		for i = line_count; i > 0; i-- {
			windgoto(cursor_end-i, cursor_col)
			out_str(term_strings[int32(KS_CE)])
			screen_start()
		}
	}

	return OK
}

func skip_showmode() int32 {
	if global_busy != 0 || msg_silent != 0 || redrawing() == 0 || ((stuff_empty() == 0 || typebuf.tb_len > 0) && KeyTyped == 0) {
		redraw_mode = TRUE
		return TRUE
	}
	return FALSE
}

func showmode() int32 {
	var need_clear int32
	var length int32 = 0
	var do_mode int32
	var attr int32
	var nwr_save int32
	var sub_attr int32
	var show_ruler_with_pum int32 = FALSE

	do_mode = B2i(p_smd != 0 && msg_silent == 0 &&
		((State&MODE_INSERT) != 0 || restart_edit != NUL || VIsual_active != 0))
	if do_mode != 0 || reg_recording != 0 {
		if skip_showmode() != 0 {
			return 0
		}

		nwr_save = need_wait_return

		check_for_delay(FALSE)

		need_clear = clear_cmdline
		if clear_cmdline != 0 && int64(cmdline_row) < Rows-1 {
			msg_clr_cmdline()
		}

		msg_pos_mode()
		cursor_off()
		attr = highlight_attr[int32(HLF_CM)]
		if do_mode != 0 {
			msg_puts_attr(S("--"), attr)
			if !edit_submode.Nil() && shortmess(SHM_COMPLETIONMENU) == 0 {
				length = int32((Rows-int64(msg_row))*int64(cmdline_width) - 3)
				if !edit_submode_extra.Nil() {
					length -= vim_strsize(edit_submode_extra)
				}
				if length > 0 {
					if !edit_submode_pre.Nil() {
						length -= vim_strsize(edit_submode_pre)
					}
					if length-vim_strsize(edit_submode) > 0 {
						if !edit_submode_pre.Nil() {
							msg_puts_attr(edit_submode_pre, attr)
						}
						msg_puts_attr(edit_submode, attr)
					}
					if !edit_submode_extra.Nil() {
						msg_puts_attr(S(" "), attr)
						if int32(edit_submode_highl) < int32(HLF_COUNT) {
							sub_attr = highlight_attr[int32(edit_submode_highl)]
						} else {
							sub_attr = attr
						}
						msg_puts_attr(edit_submode_extra, sub_attr)
					}
				}
			} else {
				if (State & VREPLACE_FLAG) != 0 {
					msg_puts_attr(gettext_(S(" VREPLACE")), attr)
				} else if (State & REPLACE_FLAG) != 0 {
					msg_puts_attr(gettext_(S(" REPLACE")), attr)
				} else if (State & MODE_INSERT) != 0 {
					msg_puts_attr(gettext_(S(" INSERT")), attr)
				} else if restart_edit == 'I' || restart_edit == 'i' || restart_edit == 'a' || restart_edit == 'A' {
					msg_puts_attr(gettext_(S(" (insert)")), attr)
				} else if restart_edit == 'R' {
					msg_puts_attr(gettext_(S(" (replace)")), attr)
				} else if restart_edit == 'V' {
					msg_puts_attr(gettext_(S(" (vreplace)")), attr)
				}
				if (State&MODE_INSERT) != 0 && p_paste != 0 {
					msg_puts_attr(gettext_(S(" (paste)")), attr)
				}

				if VIsual_active != 0 {
					var p Ptr[byte]
					var sel int32
					if VIsual_select != 0 {
						sel = 4
					} else {
						sel = 0
					}

					switch sel + B2i(VIsual_mode == Ctrl_V)*2 + B2i(VIsual_mode == 'V') {
					case 0:
						p = S(" VISUAL")
					case 1:
						p = S(" VISUAL LINE")
					case 2:
						p = S(" VISUAL BLOCK")
					case 4:
						p = S(" SELECT")
					case 5:
						p = S(" SELECT LINE")
					default:
						p = S(" SELECT BLOCK")
					}
					msg_puts_attr(gettext_(p), attr)
				}
				msg_puts_attr(S(" --"), attr)
				show_ruler_with_pum = TRUE
			}

			need_clear = TRUE
		}
		if reg_recording != 0 && edit_submode.Nil() {
			recording_mode(attr)
			need_clear = TRUE
		}

		mode_displayed = TRUE
		if need_clear != 0 || clear_cmdline != 0 || redraw_mode != 0 {
			msg_clr_eos()
		}
		msg_didout = FALSE
		length = msg_col
		msg_col = 0
		need_wait_return = nwr_save
	} else if clear_cmdline != 0 && msg_silent == 0 {
		msg_clr_cmdline()
	} else if redraw_mode != 0 {
		msg_pos_mode()
		msg_clr_eos()
	}

	if VIsual_active != 0 {
		clear_showcmd()
	}

	if redrawing() != 0 && curwin.w_status_height == 0 {
		win_redr_ruler(curwin, TRUE, show_ruler_with_pum)
	}

	redraw_cmdline = FALSE
	redraw_mode = FALSE
	clear_cmdline = FALSE

	return length
}

func msg_pos_mode() {
	msg_col = 0
	msg_row = int32(Rows - 1)
}

func unshowmode(force int32) {
	if redrawing() == 0 || (force == 0 && char_avail() != 0 && KeyTyped == 0) {
		redraw_cmdline = TRUE
	} else {
		clearmode()
	}
}

func clearmode() {
	var save_msg_row int32 = msg_row
	var save_msg_col int32 = msg_col

	msg_pos_mode()
	if reg_recording != 0 {
		recording_mode(highlight_attr[int32(HLF_CM)])
	}
	msg_clr_eos()

	msg_col = save_msg_col
	msg_row = save_msg_row
}

func recording_mode(attr int32) {
	msg_puts_attr(gettext_(S("recording")), attr)
	if shortmess(SHM_RECORDING) != 0 {
		return
	}

	s := Mk[byte](4)

	vim_snprintf(s, 4, S(" @%c"), reg_recording)
	msg_puts_attr(s, attr)
}

func draw_tabline() {
	redraw_tabline = FALSE
}

func get_trans_bufname(buf *S_file_buffer) {
	vim_strncpy(NameBuff, buf_spname(buf), PATH_MAX-1)
	trans_characters(NameBuff, PATH_MAX)
}

func fillchar_status(attr *int32, wp *S_window_S) int32 {
	var fill int32
	var override_success bool = push_highlight_overrides(wp.w_hl, wp.w_hl_len)

	if wp == curwin {
		*attr = highlight_attr[int32(HLF_S)]
		fill = wp.w_fill_chars.stl
	} else {
		*attr = highlight_attr[int32(HLF_SNC)]
		fill = wp.w_fill_chars.stlnc
	}

	if override_success {
		pop_highlight_overrides()
	}
	return fill
}

func vsep_row_is_curwin(wp *S_window_S, row int32) bool {
	if wp == curwin {
		return true
	}

	if curwin.w_wincol == (wp.w_wincol+wp.w_width)+wp.w_vsep_width && row >= curwin.w_winrow && row < (curwin.w_winrow)+curwin.w_height+curwin.w_status_height {
		return true
	}

	return false
}

func fillchar_vsep(attr *int32, wp *S_window_S, row int32) int32 {
	var override_success bool = push_highlight_overrides(wp.w_hl, wp.w_hl_len)
	if vsep_row_is_curwin(wp, row) {
		*attr = highlight_attr[int32(HLF_C)]
	} else {
		*attr = highlight_attr[int32(HLF_CNC)]
	}
	if override_success {
		pop_highlight_overrides()
	}

	if *attr == 0 && wp.w_fill_chars.vert == ' ' {
		return '|'
	} else {
		return wp.w_fill_chars.vert
	}
}

func typed_ahead() int32 {
	return char_avail()
}

func redrawing() int32 {
	return B2i((RedrawingDisabled == 0) && !(p_lz != 0 && typed_ahead() != 0 && KeyTyped == 0 && do_redraw == 0))
}

func messaging() int32 {
	return B2i(!(p_lz != 0 && typed_ahead() != 0 && KeyTyped == 0))
}

func comp_col() {
	var last_has_status int32 = B2i(last_stl_height(FALSE) > 0)

	sc_col = 0
	ru_col = 0
	if p_ru != 0 {
		ru_col = COL_RULER + 1
		if last_has_status == 0 {
			sc_col = ru_col
		}
	}
	if p_sc != 0 && p_sloc.Get() == 'l' {
		sc_col += SHOWCMD_COLS
		if p_ru == 0 || last_has_status != 0 {
			sc_col++
		}
	}
	sc_col = cmdline_width - sc_col
	ru_col = cmdline_width - ru_col
	if sc_col <= 0 {
		sc_col = 1
	}
	if ru_col <= 0 {
		ru_col = 1
	}
}

func get_encoded_char_adv(p *Ptr[byte]) int32 {
	var s Ptr[byte] = *p

	if s.At(0) == '\\' && (s.At(1) == 'x' || s.At(1) == 'u' || s.At(1) == 'U') {
		var num varnumber_T = 0
		var bytes int32
		var n int32

		if s.At(1) == 'x' {
			bytes = 1
		} else if s.At(1) == 'u' {
			bytes = 2
		} else {
			bytes = 4
		}
		for ; bytes > 0; bytes-- {
			*p = (*p).Add(2)
			n = hexhex2nr(*p)
			if n < 0 {
				return 0
			}
			num = num*256 + varnumber_T(n)
		}
		*p = (*p).Add(2)
		return int32(num)
	}
	return mb_ptr2char_adv(p)
}

func field_value_err(errbuf Ptr[byte], errbuflen usize, fmt Ptr[byte], field Ptr[byte]) Ptr[byte] {
	if errbuf.Nil() {
		return S("")
	}
	vim_snprintf(errbuf, errbuflen, gettext_(fmt), field)
	return errbuf
}

func set_chars_option(wp *S_window_S, value Ptr[byte], is_listchars int32, apply int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	var round int32
	var i int32
	var entries int32
	var p Ptr[byte]
	var s Ptr[byte]
	var c1 int32 = 0
	var c2 int32 = 0
	var c3 int32 = 0
	var last_multispace Ptr[byte]
	var last_lmultispace Ptr[byte]
	var multispace_len int32 = 0
	var lead_multispace_len int32 = 0

	var tab Ptr[S_charstab]

	if is_listchars != 0 {
		tab = lcstab
		lcs_chars = lcs_chars_T{}
		entries = 12
		if wp.w_onebuf_opt.wo_lcs.At(0) == NUL {
			value = p_lcs
		}
	} else {
		tab = filltab
		entries = 13
		if wp.w_onebuf_opt.wo_fcs.At(0) == NUL {
			value = p_fcs
		}
	}

	var rounds int32
	if apply != 0 {
		rounds = 1
	} else {
		rounds = 0
	}
	for round = 0; round <= rounds; round++ {
		var has_tab int32 = FALSE
		var has_leadtab int32 = FALSE

		if round > 0 {
			if is_listchars != 0 {
				for i = 0; i < entries; i++ {
					if tab.At(int(i)).cp != nil {
						*(tab.At(int(i)).cp) = NUL
					}
				}
				lcs_chars.tab1 = NUL
				lcs_chars.tab3 = NUL
				lcs_chars.leadtab1 = NUL
				lcs_chars.leadtab3 = NUL

				if multispace_len > 0 {
					lcs_chars.multispace = Mk[int32](int(multispace_len + 1))
					lcs_chars.multispace.Set(int(multispace_len), NUL)
				} else {
					lcs_chars.multispace = Ptr[int32]{}
				}

				if lead_multispace_len > 0 {
					lcs_chars.leadmultispace = Mk[int32](int(lead_multispace_len + 1))
					if !lcs_chars.leadmultispace.Nil() {
						lcs_chars.leadmultispace.Set(int(lead_multispace_len), NUL)
					}
				} else {
					lcs_chars.leadmultispace = Ptr[int32]{}
				}
			} else {
				fill_chars.stl = ' '
				fill_chars.stlnc = ' '
				fill_chars.vert = '|'
				fill_chars.fold = '-'
				fill_chars.foldopen = '-'
				fill_chars.foldclosed = '+'
				fill_chars.foldsep = '|'
				fill_chars.foldinner = NUL
				fill_chars.diff = '-'
				fill_chars.eob = '~'
				fill_chars.lastline = '@'
				fill_chars.trunc = '>'
				fill_chars.truncrl = '<'
			}
		}
		p = value
		for p.Get() != 0 {
			for i = 0; i < entries; i++ {
				if !(musl_strncmp(p, tab.At(int(i)).name.string_, tab.At(int(i)).name.length) == 0 && p.At(int(tab.At(int(i)).name.length)) == ':') {
					continue
				}

				s = p.Add(int(tab.At(int(i)).name.length) + 1)

				if is_listchars != 0 && musl_strcmp(tab.At(int(i)).name.string_, S("multispace")) == 0 {
					if round == 0 {
						last_multispace = p
						multispace_len = 0
						for s.Get() != NUL && s.Get() != ',' {
							c1 = get_encoded_char_adv(&s)
							if char2cells(c1) > 1 {
								return field_value_err(errbuf, errbuflen, e_wrong_character_width_for_field_str, tab.At(int(i)).name.string_)
							}
							multispace_len++
						}
						if multispace_len == 0 {
							return field_value_err(errbuf, errbuflen, e_wrong_number_of_characters_for_field_str, tab.At(int(i)).name.string_)
						}
					} else {
						var multispace_pos int32 = 0

						for s.Get() != NUL && s.Get() != ',' {
							c1 = get_encoded_char_adv(&s)
							if p == last_multispace && !lcs_chars.multispace.Nil() {
								lcs_chars.multispace.Set(int(multispace_pos), c1)
								multispace_pos++
							}
						}
					}
					p = s
					break
				}

				if is_listchars != 0 && musl_strcmp(tab.At(int(i)).name.string_, S("leadmultispace")) == 0 {
					if round == 0 {
						last_lmultispace = p
						lead_multispace_len = 0
						for s.Get() != NUL && s.Get() != ',' {
							c1 = get_encoded_char_adv(&s)
							if char2cells(c1) > 1 {
								return field_value_err(errbuf, errbuflen, e_wrong_character_width_for_field_str, tab.At(int(i)).name.string_)
							}
							lead_multispace_len++
						}
						if lead_multispace_len == 0 {
							return field_value_err(errbuf, errbuflen, e_wrong_number_of_characters_for_field_str, tab.At(int(i)).name.string_)
						}
					} else {
						var multispace_pos int32 = 0

						for s.Get() != NUL && s.Get() != ',' {
							c1 = get_encoded_char_adv(&s)
							if p == last_lmultispace && !lcs_chars.leadmultispace.Nil() {
								lcs_chars.leadmultispace.Set(int(multispace_pos), c1)
								multispace_pos++
							}
						}
					}
					p = s
					break
				}

				c3 = 0
				c2 = c3
				if s.Get() == NUL {
					return field_value_err(errbuf, errbuflen, e_wrong_number_of_characters_for_field_str, tab.At(int(i)).name.string_)
				}
				c1 = get_encoded_char_adv(&s)
				if char2cells(c1) > 1 {
					return field_value_err(errbuf, errbuflen, e_wrong_character_width_for_field_str, tab.At(int(i)).name.string_)
				}
				if tab.At(int(i)).cp == &lcs_chars.tab2 || tab.At(int(i)).cp == &lcs_chars.leadtab2 {
					if s.Get() == NUL {
						return field_value_err(errbuf, errbuflen, e_wrong_number_of_characters_for_field_str, tab.At(int(i)).name.string_)
					}
					c2 = get_encoded_char_adv(&s)
					if char2cells(c2) > 1 {
						return field_value_err(errbuf, errbuflen, e_wrong_character_width_for_field_str, tab.At(int(i)).name.string_)
					}
					if !(s.Get() == ',' || s.Get() == NUL) {
						c3 = get_encoded_char_adv(&s)
						if char2cells(c3) > 1 {
							return field_value_err(errbuf, errbuflen, e_wrong_character_width_for_field_str, tab.At(int(i)).name.string_)
						}
					}
					if tab.At(int(i)).cp == &lcs_chars.tab2 {
						has_tab = TRUE
					} else {
						has_leadtab = TRUE
					}
				}

				if s.Get() == ',' || s.Get() == NUL {
					if round > 0 {
						if tab.At(int(i)).cp == &lcs_chars.tab2 {
							lcs_chars.tab1 = c1
							lcs_chars.tab2 = c2
							lcs_chars.tab3 = c3
						} else if tab.At(int(i)).cp == &lcs_chars.leadtab2 {
							lcs_chars.leadtab1 = c1
							lcs_chars.leadtab2 = c2
							lcs_chars.leadtab3 = c3
						} else if tab.At(int(i)).cp != nil {
							*(tab.At(int(i)).cp) = c1
						}
					}
					p = s
					break
				} else {
					return field_value_err(errbuf, errbuflen, e_wrong_number_of_characters_for_field_str, tab.At(int(i)).name.string_)
				}
			}

			if i == entries {
				return e_invalid_argument
			}

			if p.Get() == ',' {
				p = p.Add(1)
			}
		}

		if is_listchars != 0 && has_leadtab != 0 && has_tab == 0 {
			return e_leadtab_requires_tab
		}
	}

	if apply != 0 {
		if is_listchars != 0 {
			wp.w_lcs_chars = lcs_chars
		} else {
			wp.w_fill_chars = fill_chars
		}
	}

	return Ptr[byte]{}
}

func set_fillchars_option(wp *S_window_S, val Ptr[byte], apply int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	return set_chars_option(wp, val, FALSE, apply, errbuf, errbuflen)
}

func set_listchars_option(wp *S_window_S, val Ptr[byte], apply int32, errbuf Ptr[byte], errbuflen usize) Ptr[byte] {
	return set_chars_option(wp, val, TRUE, apply, errbuf, errbuflen)
}

func check_chars_options() Ptr[byte] {
	var wp *S_window_S

	if !set_listchars_option(curwin, p_lcs, FALSE, Ptr[byte]{}, 0).Nil() {
		return e_conflicts_with_value_of_listchars
	}
	if !set_fillchars_option(curwin, p_fcs, FALSE, Ptr[byte]{}, 0).Nil() {
		return e_conflicts_with_value_of_fillchars
	}
	wp = curwin
	if !set_listchars_option(wp, wp.w_onebuf_opt.wo_lcs, FALSE, Ptr[byte]{}, 0).Nil() {
		return e_conflicts_with_value_of_listchars
	}
	if !set_fillchars_option(wp, wp.w_onebuf_opt.wo_fcs, FALSE, Ptr[byte]{}, 0).Nil() {
		return e_conflicts_with_value_of_fillchars
	}
	return Ptr[byte]{}
}

func estack_init() {
	var entry Ptr[estack_T]

	if ga_grow(&exestack, 10) == FAIL {
		mch_exit(0)
	}
	entry = GaData[estack_T](&exestack).Add(int(exestack.ga_len))
	entry.P().es_type = ETYPE_TOP
	entry.P().es_name = Ptr[byte]{}
	entry.P().es_lnum = 0
	exestack.ga_len++
}

func estack_push(type_ etype_T, name Ptr[byte], lnum int64) Ptr[estack_T] {
	var entry Ptr[estack_T]

	if ga_grow(&exestack, 1) == FAIL {
		return Ptr[estack_T]{}
	}

	entry = GaData[estack_T](&exestack).Add(int(exestack.ga_len))
	entry.P().es_type = type_
	entry.P().es_name = name
	entry.P().es_lnum = lnum
	exestack.ga_len++
	return entry
}

func estack_pop() Ptr[estack_T] {
	if exestack.ga_len == 0 {
		return Ptr[estack_T]{}
	}
	exestack.ga_len--
	return GaData[estack_T](&exestack).Add(int(exestack.ga_len))
}

func estack_sfile(which estack_arg_T) Ptr[byte] {
	var entry Ptr[estack_T]

	entry = GaData[estack_T](&exestack).Add(int(exestack.ga_len - 1))
	{
		if entry.P().es_name.Nil() {
			return Ptr[byte]{}
		}
		return vim_strsave(entry.P().es_name)
	}
}

func search_regcomp(pat Ptr[byte], patlen usize, used_pat *Ptr[byte], pat_save int32, pat_use int32, options int32, regmatch *regmmatch_T) int32 {
	var magic int32

	rc_did_emsg = FALSE
	magic = magic_isset()

	if pat.Nil() || pat.Get() == NUL {
		var i int32

		if pat_use == RE_LAST {
			i = last_idx
		} else {
			i = pat_use
		}
		if spats[i].pat.Nil() {
			if pat_use == RE_SUBST {
				emsg(gettext_(e_no_previous_substitute_regular_expression))
			} else {
				emsg(gettext_(e_no_previous_regular_expression))
			}
			rc_did_emsg = TRUE
			return FAIL
		}
		pat = spats[i].pat
		patlen = spats[i].patlen
		magic = spats[i].magic
		no_smartcase = spats[i].no_scs
	} else if (options & SEARCH_HIS) != 0 {
		add_to_history(HIST_SEARCH, pat, patlen, TRUE, NUL)
	}

	if used_pat != nil {
		*used_pat = pat
	}

	mr_pattern = vim_strnsave(pat, patlen)

	if (options&SEARCH_KEEP) == 0 && (cmdmod.cmod_flags&CMOD_KEEPPATTERNS) == 0 {
		if pat_save == RE_SEARCH || pat_save == RE_BOTH {
			save_re_pat(RE_SEARCH, pat, patlen, magic)
		}
		if pat_save == RE_SUBST || pat_save == RE_BOTH {
			save_re_pat(RE_SUBST, pat, patlen, magic)
		}
	}

	regmatch.rmm_ic = ignorecase(pat)
	regmatch.rmm_maxcol = 0
	var re_flags int32
	if magic != 0 {
		re_flags = RE_MAGIC
	} else {
		re_flags = 0
	}
	regmatch.regprog = vim_regcomp(pat, re_flags)
	if regmatch.regprog == nil {
		return FAIL
	}
	return OK
}

func get_search_pat() Ptr[byte] {
	return mr_pattern
}

func save_re_pat(idx int32, pat Ptr[byte], patlen usize, magic int32) {
	if spats[idx].pat == pat {
		return
	}

	spats[idx].pat = vim_strnsave(pat, patlen)
	spats[idx].patlen = patlen
	spats[idx].magic = magic
	spats[idx].no_scs = no_smartcase
	last_idx = idx
	if p_hls != 0 {
		redraw_all_later(UPD_SOME_VALID)
	}
	set_no_hlsearch(FALSE)
}

func save_last_search_pattern() {
	did_save_last_search_spat++
	if did_save_last_search_spat != 1 {
		return
	}

	saved_last_search_spat = spats[RE_SEARCH]
	if !spats[RE_SEARCH].pat.Nil() {
		saved_last_search_spat.pat = vim_strnsave(spats[RE_SEARCH].pat, spats[RE_SEARCH].patlen)
		saved_last_search_spat.patlen = spats[RE_SEARCH].patlen
	}
	saved_last_idx = last_idx
	saved_no_hlsearch = no_hlsearch
}

func restore_last_search_pattern() {
	did_save_last_search_spat--
	if did_save_last_search_spat > 0 {
		return
	}
	if did_save_last_search_spat != 0 {
		iemsg(S("restore_last_search_pattern() called more often than save_last_search_pattern()"))
		return
	}

	spats[RE_SEARCH] = saved_last_search_spat
	saved_last_search_spat.pat = Ptr[byte]{}
	saved_last_search_spat.patlen = 0
	last_idx = saved_last_idx
	set_no_hlsearch(saved_no_hlsearch)
}

func ignorecase(pat Ptr[byte]) int32 {
	return ignorecase_opt(pat, p_ic, p_scs)
}

func ignorecase_opt(pat Ptr[byte], ic_in int32, scs int32) int32 {
	var ic int32 = ic_in

	if ic != 0 && no_smartcase == 0 && scs != 0 {
		ic = B2i(pat_has_uppercase(pat) == 0)
	}
	no_smartcase = FALSE

	return ic
}

func pat_has_uppercase(pat Ptr[byte]) int32 {
	var p Ptr[byte] = pat
	var magic_val magic_T = MAGIC_ON

	skip_regexp_ex(pat, NUL, magic_isset(), nil, nil, &magic_val)

	for p.Get() != NUL {
		var l int32

		l = utfc_ptr2len(p)
		if l > 1 {
			if utf_isupper(utf_ptr2char(p)) != 0 {
				return TRUE
			}
			p = p.Add(int(l))
		} else if p.Get() == '\\' && magic_val <= MAGIC_ON {
			if p.At(1) == '_' && p.At(2) != NUL {
				p = p.Add(3)
			} else if p.At(1) == '%' && p.At(2) != NUL {
				p = p.Add(3)
			} else if p.At(1) != NUL {
				p = p.Add(2)
			} else {
				p = p.Add(1)
			}
		} else if (p.Get() == '%' || p.Get() == '_') && magic_val == MAGIC_ALL {
			if p.At(1) != NUL {
				p = p.Add(2)
			} else {
				p = p.Add(1)
			}
		} else if vim_isupper(int32(p.Get())) != 0 {
			return TRUE
		} else {
			p = p.Add(1)
		}
	}
	return FALSE
}

func set_csearch_direction(cdir int32) {
	lastcdir = cdir
}

func set_csearch_until(t_cmd int32) {
	last_t_cmd = t_cmd
}

func last_search_pat() Ptr[byte] {
	return spats[last_idx].pat
}

func last_pat_prog(regmatch *regmmatch_T) {
	if spats[last_idx].pat.Nil() {
		regmatch.regprog = nil
		return
	}
	emsg_off++
	search_regcomp(S(""), 0, nil, 0, last_idx, SEARCH_KEEP, regmatch)
	emsg_off--
}

func searchit(win *S_window_S, buf *S_file_buffer, pos *pos_T, end_pos *pos_T, dir int32, pat Ptr[byte], patlen usize, count int64, options int32, pat_use int32, extra_arg *searchit_arg_T) int32 {
	var found int32
	var lnum linenr_T
	var col colnr_T
	var regmatch regmmatch_T
	var ptr Ptr[byte]
	var matchcol colnr_T
	var endpos lpos_T
	var matchpos lpos_T
	var loop int32
	var start_pos pos_T
	var at_first_line int32
	var extra_col int32
	var start_char_len int32
	var match_ok int32
	var nmatched int64
	var submatch int32 = 0
	var first_match int32 = TRUE
	var called_emsg_before int32 = called_emsg
	var break_loop int32 = FALSE
	var stop_lnum linenr_T = 0
	var unused_timeout_flag int32 = FALSE
	var timed_out *int32 = &unused_timeout_flag
	var search_from_match_end int32

	if search_regcomp(pat, patlen, nil, RE_SEARCH, pat_use, (options&(SEARCH_HIS+SEARCH_KEEP)), &regmatch) == FAIL {
		if (options&SEARCH_MSG) != 0 && rc_did_emsg == 0 {
			vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_invalid_search_string_str), mr_pattern)
			emsg(iobuff_or(gettext_(e_invalid_search_string_str)))
		}
		return FAIL
	}

	search_from_match_end = B2i(!vim_strchr(p_cpo, CPO_SEARCH).Nil())

	if extra_arg != nil {
		stop_lnum = extra_arg.sa_stop_lnum
	}

	for {
		if pos.col == MAXCOL {
			start_char_len = 0
		} else if pos.lnum >= 1 && pos.lnum <= buf.b_ml.ml_line_count && pos.col < MAXCOL-2 {
			ptr = ml_get_buf(buf, pos.lnum, FALSE)
			if ml_get_buf_len(buf, pos.lnum) <= pos.col {
				start_char_len = 1
			} else {
				start_char_len = utfc_ptr2len(ptr.Add(int(pos.col)))
			}
		} else {
			start_char_len = 1
		}
		if dir == FORWARD {
			if (options & SEARCH_START) != 0 {
				extra_col = 0
			} else {
				extra_col = start_char_len
			}
		} else {
			if (options & SEARCH_START) != 0 {
				extra_col = start_char_len
			} else {
				extra_col = 0
			}
		}

		start_pos = *pos
		found = 0
		at_first_line = TRUE
		if pos.lnum == 0 {
			pos.lnum = 1
			pos.col = 0
			at_first_line = FALSE
		}

		if dir == (-1) && start_pos.col == 0 && (options&SEARCH_START) == 0 {
			lnum = pos.lnum - 1
			at_first_line = FALSE
		} else {
			lnum = pos.lnum
		}

		for loop = 0; loop <= 1; loop++ {
			for ; lnum > 0 && lnum <= buf.b_ml.ml_line_count; lnum, at_first_line = lnum+linenr_T(dir), FALSE {
				if stop_lnum != 0 {
					var past bool
					if dir == FORWARD {
						past = lnum > stop_lnum
					} else {
						past = lnum < stop_lnum
					}
					if past {
						break
					}
				}
				if *timed_out != 0 {
					break
				}

				if at_first_line != 0 && (options&SEARCH_COL) != 0 {
					col = pos.col
				} else {
					col = colnr_T(0)
				}
				nmatched = vim_regexec_multi(&regmatch, win, buf, lnum, col, timed_out)
				if regmatch.regprog == nil {
					break
				}
				if called_emsg > called_emsg_before || *timed_out != 0 {
					break
				}
				if nmatched > 0 {
					matchpos = regmatch.startpos[0]
					endpos = regmatch.endpos[0]
					if lnum+matchpos.lnum > buf.b_ml.ml_line_count {
						ptr = S("")
					} else {
						ptr = ml_get_buf(buf, lnum+matchpos.lnum, FALSE)
					}

					if dir == FORWARD && at_first_line != 0 {
						match_ok = TRUE

						for {
							var more bool = false
							if matchpos.lnum == 0 {
								if (options&SEARCH_END) != 0 && first_match != 0 {
									more = nmatched == 1 && int32(endpos.col)-1 < int32(start_pos.col)+extra_col
								} else {
									more = int32(matchpos.col)-B2i(ptr.At(int(matchpos.col)) == NUL) < int32(start_pos.col)+extra_col
								}
							}
							if !more {
								break
							}
							if search_from_match_end != 0 {
								if nmatched > 1 {
									match_ok = FALSE
									break
								}
								matchcol = endpos.col
								if matchcol == matchpos.col && ptr.At(int(matchcol)) != NUL {
									matchcol += utfc_ptr2len(ptr.Add(int(matchcol)))
								}
							} else {
								matchcol = regmatch.rmm_matchcol
								if ptr.At(int(matchcol)) != NUL {
									matchcol += utfc_ptr2len(ptr.Add(int(matchcol)))
								}
							}
							if matchcol == 0 && (options&SEARCH_START) != 0 {
								break
							}
							if ptr.At(int(matchcol)) == NUL {
								match_ok = FALSE
								break
							}
							nmatched = vim_regexec_multi(&regmatch, win, buf, lnum+matchpos.lnum, matchcol, timed_out)
							if nmatched == 0 {
								match_ok = FALSE
								break
							}
							if regmatch.regprog == nil {
								break
							}
							matchpos = regmatch.startpos[0]
							endpos = regmatch.endpos[0]

							ptr = ml_get_buf(buf, lnum+matchpos.lnum, FALSE)
						}
						if match_ok == 0 {
							continue
						}
					}
					if dir == (-1) {
						match_ok = FALSE
						for {
							var before bool
							if loop != 0 {
								before = true
							} else if (options & SEARCH_END) != 0 {
								before = lnum+regmatch.endpos[0].lnum < start_pos.lnum || (lnum+regmatch.endpos[0].lnum == start_pos.lnum && int32(regmatch.endpos[0].col)-1 < int32(start_pos.col)+extra_col)
							} else {
								before = lnum+regmatch.startpos[0].lnum < start_pos.lnum || (lnum+regmatch.startpos[0].lnum == start_pos.lnum && int32(regmatch.startpos[0].col) < int32(start_pos.col)+extra_col)
							}
							if before {
								match_ok = TRUE
								matchpos = regmatch.startpos[0]
								endpos = regmatch.endpos[0]
							} else {
								break
							}

							if search_from_match_end != 0 {
								if nmatched > 1 {
									break
								}
								matchcol = endpos.col
								if matchcol == matchpos.col && ptr.At(int(matchcol)) != NUL {
									matchcol += utfc_ptr2len(ptr.Add(int(matchcol)))
								}
							} else {
								if matchpos.lnum > 0 {
									break
								}
								matchcol = matchpos.col
								if ptr.At(int(matchcol)) != NUL {
									matchcol += utfc_ptr2len(ptr.Add(int(matchcol)))
								}
							}
							var nomore bool
							if ptr.At(int(matchcol)) == NUL {
								nomore = true
							} else {
								nmatched = vim_regexec_multi(&regmatch, win, buf, lnum+matchpos.lnum, matchcol, timed_out)
								nomore = nmatched == 0
							}
							if nomore {
								if *timed_out != 0 {
									match_ok = FALSE
								}
								break
							}
							if regmatch.regprog == nil {
								break
							}

							ptr = ml_get_buf(buf, lnum+matchpos.lnum, FALSE)
						}

						if match_ok == 0 {
							continue
						}
					}

					if (options&SEARCH_END) != 0 && (options&SEARCH_NOOF) == 0 && !(matchpos.lnum == endpos.lnum && matchpos.col == endpos.col) {
						pos.lnum = lnum + endpos.lnum
						pos.col = endpos.col
						if endpos.col == 0 {
							if pos.lnum > 1 {
								pos.lnum--
								pos.col = ml_get_buf_len(buf, pos.lnum)
							}
						} else {
							pos.col--
							if pos.lnum <= buf.b_ml.ml_line_count {
								ptr = ml_get_buf(buf, pos.lnum, FALSE)
								pos.col -= utf_head_off(ptr, ptr.Add(int(pos.col)))
							}
						}
						if end_pos != nil {
							end_pos.lnum = lnum + matchpos.lnum
							end_pos.col = matchpos.col
						}
					} else {
						pos.lnum = lnum + matchpos.lnum
						pos.col = matchpos.col
						if end_pos != nil {
							end_pos.lnum = lnum + endpos.lnum
							end_pos.col = endpos.col
						}
					}
					pos.coladd = 0
					if end_pos != nil {
						end_pos.coladd = 0
					}
					found = 1
					first_match = FALSE

					search_match_lines = endpos.lnum - matchpos.lnum
					search_match_endcol = endpos.col
					break
				}
				line_breakcheck()
				if got_int != 0 {
					break
				}

				if (options&SEARCH_PEEK) != 0 && ((lnum-pos.lnum)&0x3f) == 0 && char_avail() != 0 {
					break_loop = TRUE
					break
				}

				if loop != 0 && lnum == start_pos.lnum {
					break
				}
			}
			at_first_line = FALSE

			if regmatch.regprog == nil {
				break
			}

			if p_ws == 0 || stop_lnum != 0 || got_int != 0 || called_emsg > called_emsg_before || *timed_out != 0 || break_loop != 0 || found != 0 || loop != 0 {
				break
			}

			if dir == (-1) {
				lnum = buf.b_ml.ml_line_count
			} else {
				lnum = 1
			}
			if shortmess(SHM_SEARCH) == 0 && shortmess(SHM_SEARCHCOUNT) != 0 && (options&SEARCH_MSG) != 0 {
				var msg Ptr[byte]
				if dir == (-1) {
					msg = top_bot_msg
				} else {
					msg = bot_top_msg
				}
				give_warning(gettext_(msg), TRUE)
			}
			if extra_arg != nil {
				extra_arg.sa_wrapped = TRUE
			}
		}
		if got_int != 0 || called_emsg > called_emsg_before || *timed_out != 0 || break_loop != 0 {
			break
		}
		count--
		if !(count > 0 && found != 0) {
			break
		}
	}

	vim_regfree(regmatch.regprog)

	if found == 0 {
		if got_int != 0 {
			emsg(gettext_(e_interrupted))
		} else if (options & SEARCH_MSG) == SEARCH_MSG {
			if p_ws != 0 {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_pattern_not_found_str), mr_pattern)
				emsg(iobuff_or(gettext_(e_pattern_not_found_str)))
			} else if lnum == 0 {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_search_hit_top_without_match_for_str), mr_pattern)
				emsg(iobuff_or(gettext_(e_search_hit_top_without_match_for_str)))
			} else {
				vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_search_hit_bottom_without_match_for_str), mr_pattern)
				emsg(iobuff_or(gettext_(e_search_hit_bottom_without_match_for_str)))
			}
		}
		return FAIL
	}

	if pos.lnum > buf.b_ml.ml_line_count {
		pos.lnum = buf.b_ml.ml_line_count
		pos.col = ml_get_buf_len(buf, pos.lnum)
		if pos.col > 0 {
			pos.col--
		}
	}

	return submatch + 1
}

func parse_search_pattern_offset(pat *Ptr[byte], patlen *usize, search_delim int32, options int32, strcopy *Ptr[byte], searchstr *Ptr[byte], searchstrlen *usize, dircp *Ptr[byte], offset *S_soffset) int32 {
	var cmdlen int32 = 0
	var p Ptr[byte]
	var ps Ptr[byte]

	if (*pat).Nil() || (*pat).Get() == NUL {
		return 0
	}

	ps = *strcopy
	*searchstr = *pat
	*searchstrlen = *patlen
	*dircp = Ptr[byte]{}

	p = skip_regexp_ex(*pat, search_delim, magic_isset(), strcopy, nil, nil)
	if *strcopy != ps {
		var len_ usize = musl_strlen(*strcopy)
		cmdlen += int32(*patlen - len_)
		*pat = *strcopy
		*patlen = len_
		*searchstr = *strcopy
		*searchstrlen = len_
	}
	if int32(p.Get()) == search_delim {
		*searchstrlen = usize(p.Sub(*pat))
		*dircp = p
		p.Put(NUL)
		p = p.Add(1)
	}

	offset.line = FALSE
	offset.end = FALSE
	offset.off = 0
	if p.Get() == '+' || p.Get() == '-' || (uint32(p.Get())-'0' < 10) {
		offset.line = TRUE
	} else if (options&SEARCH_OPT) != 0 && (p.Get() == 'e' || p.Get() == 's' || p.Get() == 'b') {
		if p.Get() == 'e' {
			offset.end = SEARCH_END
		}
		p = p.Add(1)
	}
	if (uint32(p.Get())-'0' < 10) || p.Get() == '+' || p.Get() == '-' {
		if (uint32(p.Get())-'0' < 10) || (uint32(p.At(1))-'0' < 10) {
			offset.off = musl_atol(p)
		} else if p.Get() == '-' {
			offset.off = -1
		} else {
			offset.off = 1
		}
		p = p.Add(1)
		for uint32(p.Get())-'0' < 10 {
			p = p.Add(1)
		}
	}

	cmdlen += int32(p.Sub(*pat))
	*patlen -= usize(p.Sub(*pat))
	*pat = p

	return cmdlen
}

func do_search(oap *S_oparg_S, dirc int32, search_delim int32, pat Ptr[byte], patlen usize, count int64, options int32, sia *searchit_arg_T) int32 {
	var pos pos_T
	var searchstr Ptr[byte]
	var searchstrlen usize
	var old_off soffset_T
	var retval int32
	var p Ptr[byte]
	var c int64
	var dircp Ptr[byte]
	var strcopy Ptr[byte]
	var show_search_stats int32
	var msgbuf Ptr[byte]
	var msgbuflen usize = 0
	var has_offset int32 = FALSE

	searchcmdlen = 0

	if spats[0].off.line != 0 && !vim_strchr(p_cpo, CPO_LINEOFF).Nil() {
		spats[0].off.line = FALSE
		spats[0].off.off = 0
	}

	old_off = spats[0].off

	pos = curwin.w_cursor

	if dirc == 0 {
		dirc = spats[0].off.dir
	} else {
		spats[0].off.dir = dirc
	}
	if (options & SEARCH_REV) != 0 {
		if dirc == '/' {
			dirc = '?'
		} else {
			dirc = '/'
		}
	}

	if no_hlsearch != 0 && (options&SEARCH_KEEP) == 0 {
		redraw_all_later(UPD_SOME_VALID)
		set_no_hlsearch(FALSE)
	}

	for {
		var show_top_bot_msg int32 = FALSE

		searchstr = pat
		searchstrlen = patlen

		dircp = Ptr[byte]{}
		if pat.Nil() || pat.Get() == NUL || int32(pat.Get()) == search_delim {
			if spats[RE_SEARCH].pat.Nil() {
				if spats[RE_SUBST].pat.Nil() {
					emsg(gettext_(e_no_previous_regular_expression))
					retval = 0
					goto end_do_search
				}
				searchstr = spats[RE_SUBST].pat
				searchstrlen = spats[RE_SUBST].patlen
			} else {
				searchstr = S("")
				searchstrlen = 0
			}
		}

		if !pat.Nil() && pat.Get() != NUL {
			searchcmdlen += parse_search_pattern_offset(&pat, &patlen, search_delim, options, &strcopy, &searchstr, &searchstrlen, &dircp, &spats[0].off)
		}

		show_search_stats = FALSE
		if (options&SEARCH_ECHO) != 0 && messaging() != 0 && msg_silent == 0 && (cmd_silent == 0 || shortmess(SHM_SEARCHCOUNT) == 0) {
			off_buf := Mk[byte](40)
			var off_len usize = 0
			var plen usize
			var msgbufsize usize

			msg_start()

			if cmd_silent == 0 && (spats[0].off.line != 0 || spats[0].off.end != 0 || spats[0].off.off != 0) {
				off_buf.Set(int(off_len), byte(dirc))
				off_len++
				if spats[0].off.end != 0 {
					off_buf.Set(int(off_len), 'e')
					off_len++
				} else if spats[0].off.line == 0 {
					off_buf.Set(int(off_len), 's')
					off_len++
				}
				off_buf.Set(int(off_len), NUL)
				if spats[0].off.off != 0 || spats[0].off.line != 0 {
					off_len += usize(vim_snprintf(off_buf.Add(int(off_len)), 40-off_len, S("%+ld"), spats[0].off.off))
				}
			}

			if searchstr.Get() == NUL {
				p = spats[0].pat
				plen = spats[0].patlen
			} else {
				p = searchstr
				plen = searchstrlen
			}

			if shortmess(SHM_SEARCHCOUNT) == 0 || cmd_silent != 0 {
				if msg_scrolled != 0 && cmd_silent == 0 {
					msgbufsize = usize(int32(Rows-int64(msg_row))*cmdline_width - 1)
				} else {
					msgbufsize = usize(int32(Rows-int64(msg_row)-1)*cmdline_width + sc_col - 1)
				}
				if msgbufsize < plen+off_len+SEARCH_STAT_BUF_LEN+3 {
					msgbufsize = plen + off_len + SEARCH_STAT_BUF_LEN + 3
				}
			} else {
				msgbufsize = plen + off_len + 3
			}

			msgbuf = Alloc(int(msgbufsize))
			Memset(msgbuf, ' ', int(msgbufsize))
			msgbuflen = msgbufsize - 1
			msgbuf.Set(int(msgbuflen), NUL)
			if cmd_silent == 0 {
				var trunc Ptr[byte]

				msgbuf.Set(0, byte(dirc))

				if utf_iscomposing(utf_ptr2char(p)) != 0 {
					msgbuf.Set(1, ' ')
					Memmove(msgbuf.Add(2), p, int(plen))
				} else {
					Memmove(msgbuf.Add(1), p, int(plen))
				}
				if off_len > 0 {
					Memmove(msgbuf.Add(int(plen+1)), off_buf, int(off_len))
				}

				trunc = msg_strtrunc(msgbuf, TRUE)
				if !trunc.Nil() {
					msgbuf = trunc
					msgbuflen = musl_strlen(msgbuf)
				}

				msg_outtrans(msgbuf)
				msg_clr_eos()
				msg_check()

				gotocmdline(FALSE)
				out_flush()
				msg_nowait = TRUE
			}

			if shortmess(SHM_SEARCHCOUNT) == 0 {
				show_search_stats = TRUE
			}
		}

		if spats[0].off.line == 0 && spats[0].off.off != 0 && pos.col < MAXCOL-2 {
			if spats[0].off.off > 0 {
				for c = spats[0].off.off; c != 0; c-- {
					if decl(&pos) == -1 {
						break
					}
				}
				if c != 0 {
					pos.lnum = 0
					pos.col = MAXCOL
				}
			} else {
				for c = spats[0].off.off; c != 0; c++ {
					if incl(&pos) == -1 {
						break
					}
				}
				if c != 0 {
					pos.lnum = curbuf.b_ml.ml_line_count + 1
					pos.col = 0
				}
			}
		}

		{
			var sdir int32
			if dirc == '/' {
				sdir = FORWARD
			} else {
				sdir = (-1)
			}
			var noof int32
			if !pat.Nil() && pat.Get() == ';' {
				noof = 0
			} else {
				noof = SEARCH_NOOF
			}
			c = int64(searchit(curwin, curbuf, &pos, nil, sdir, searchstr, searchstrlen, count, spats[0].off.end+(options&(SEARCH_KEEP+SEARCH_PEEK+SEARCH_HIS+SEARCH_MSG+SEARCH_START+noof)), RE_LAST, sia))
		}

		if !dircp.Nil() {
			dircp.Put(byte(search_delim))
		}

		if shortmess(SHM_SEARCH) == 0 && sia != nil && sia.sa_wrapped != 0 {
			show_top_bot_msg = TRUE
		}

		if c == FAIL {
			retval = 0
			goto end_do_search
		}
		if spats[0].off.end != 0 && oap != nil {
			oap.inclusive = TRUE
		}

		retval = 1

		if (options&SEARCH_NOOF) == 0 || (!pat.Nil() && pat.Get() == ';') {
			var org_pos pos_T = pos

			if spats[0].off.line != 0 {
				c = pos.lnum + spats[0].off.off
				if c < 1 {
					pos.lnum = 1
				} else if c > curbuf.b_ml.ml_line_count {
					pos.lnum = curbuf.b_ml.ml_line_count
				} else {
					pos.lnum = c
				}
				pos.col = 0

				retval = 2
			} else if pos.col < MAXCOL-2 {
				c = spats[0].off.off
				if c > 0 {
					for {
						c--
						if !(c+1 > 0) {
							break
						}
						if incl(&pos) == -1 {
							break
						}
					}
				} else {
					for {
						c++
						if !(c-1 < 0) {
							break
						}
						if decl(&pos) == -1 {
							break
						}
					}
				}
			}
			if !((pos.lnum == org_pos.lnum) && (pos.col == org_pos.col) && (pos.coladd == org_pos.coladd)) {
				has_offset = TRUE
			}
		}

		if show_search_stats != 0 {
			cmdline_search_stat(dirc, &pos, &curwin.w_cursor, show_top_bot_msg, msgbuf, msgbuflen, B2i(count != 1 || has_offset != 0), int32(p_msc), SEARCH_STAT_DEF_TIMEOUT)
		}

		if (options&SEARCH_OPT) == 0 || pat.Nil() || pat.Get() != ';' {
			break
		}

		pat = pat.Add(1)
		dirc = int32(pat.Get())
		search_delim = dirc
		if dirc != '?' && dirc != '/' {
			retval = 0
			emsg(gettext_(e_expected_question_or_slash_after_semicolon))
			goto end_do_search
		}
		pat = pat.Add(1)
		patlen--
	}

	if (options & SEARCH_MARK) != 0 {
		setpcmark()
	}
	curwin.w_cursor = pos
	curwin.w_set_curswant = true

end_do_search:
	if (options&SEARCH_KEEP) != 0 || (cmdmod.cmod_flags&CMOD_KEEPPATTERNS) != 0 {
		spats[0].off = old_off
	}

	return retval
}

func searchc(cap_ *S_cmdarg_S, t_cmd int32) int32 {
	var c int32 = cap_.nchar
	var dir int32 = cap_.arg
	var count int64 = cap_.count1
	var col int32
	var p Ptr[byte]
	var len_ int32
	var stop int32 = TRUE

	if c != NUL {
		if KeyStuffed == 0 {
			lastc[0] = byte(c)
			set_csearch_direction(dir)
			set_csearch_until(t_cmd)
			lastc_bytelen = utf_char2bytes(c, lastc_bytes)
			if cap_.ncharC1 != 0 {
				lastc_bytelen += utf_char2bytes(cap_.ncharC1, lastc_bytes.Add(int(lastc_bytelen)))
				if cap_.ncharC2 != 0 {
					lastc_bytelen += utf_char2bytes(cap_.ncharC2, lastc_bytes.Add(int(lastc_bytelen)))
				}
			}
		}
	} else {
		if lastc[0] == NUL && lastc_bytelen <= 1 {
			return FAIL
		}
		if dir != 0 {
			dir = -lastcdir
		} else {
			dir = lastcdir
		}
		t_cmd = last_t_cmd
		c = int32(lastc[0])

		if vim_strchr(p_cpo, CPO_SCOLON).Nil() && count == 1 && t_cmd != 0 {
			stop = FALSE
		}
	}

	if dir == (-1) {
		cap_.oap.inclusive = FALSE
	} else {
		cap_.oap.inclusive = TRUE
	}

	p = ml_get_curline()
	col = curwin.w_cursor.col
	len_ = ml_get_curline_len()

	for {
		old := count
		count--
		if old == 0 {
			break
		}
		for {
			if dir > 0 {
				col += utfc_ptr2len(p.Add(int(col)))
				if col >= len_ {
					return FAIL
				}
			} else {
				if col == 0 {
					return FAIL
				}
				col -= utf_head_off(p, p.Add(int(col)-1)) + 1
			}
			if lastc_bytelen <= 1 {
				if int32(p.At(int(col))) == c && stop != 0 {
					break
				}
			} else if musl_strncmp(p.Add(int(col)), lastc_bytes, usize(lastc_bytelen)) == 0 && stop != 0 {
				break
			}
			stop = TRUE
		}
	}

	if t_cmd != 0 {
		col -= dir
		if dir < 0 {
			col += lastc_bytelen - 1
		} else {
			col -= utf_head_off(p, p.Add(int(col)))
		}
	}
	curwin.w_cursor.col = col

	return OK
}

func findmatch(oap *S_oparg_S, initc int32) *pos_T {
	return findmatchlimit(oap, initc, 0, 0)
}

func check_prevcol(linep Ptr[byte], col int32, ch int32, prevcol *int32) int32 {
	col--
	if col > 0 {
		col -= utf_head_off(linep, linep.Add(int(col)))
	}
	if prevcol != nil {
		*prevcol = col
	}
	if col >= 0 && int32(linep.At(int(col))) == ch {
		return TRUE
	}
	return FALSE
}

func find_rawstring_end(linep Ptr[byte], startpos *pos_T, endpos *pos_T) int32 {
	var p Ptr[byte]
	var delim_copy Ptr[byte]
	var delim_len usize
	var lnum linenr_T
	var found int32 = FALSE

	for p = linep.Add(int(startpos.col) + 1); p.Get() != 0 && p.Get() != '('; p = p.Add(1) {
	}
	delim_len = usize(int64(p.Sub(linep)) - int64(startpos.col) - 1)
	delim_copy = vim_strnsave(linep.Add(int(startpos.col)+1), delim_len)
	for lnum = startpos.lnum; lnum <= endpos.lnum; lnum++ {
		var line Ptr[byte] = ml_get(lnum)

		var start int
		if lnum == startpos.lnum {
			start = int(startpos.col + 1)
		} else {
			start = 0
		}
		for p = line.Add(start); p.Get() != 0; p = p.Add(1) {
			if lnum == endpos.lnum && colnr_T(p.Sub(line)) >= endpos.col {
				break
			}
			if p.Get() == ')' && musl_strncmp(delim_copy, p.Add(1), delim_len) == 0 && p.At(int(delim_len+1)) == '"' {
				found = TRUE
				break
			}
		}
		if found != 0 {
			break
		}
	}
	return found
}

func find_mps_values(initc *int32, findc *int32, backwards *int32, switchit int32) {
	var ptr Ptr[byte]

	ptr = curbuf.b_p_mps
	for ptr.Get() != NUL {
		var prev Ptr[byte]

		if utf_ptr2char(ptr) == *initc {
			if switchit != 0 {
				*findc = *initc
				*initc = utf_ptr2char(ptr.Add(int(utfc_ptr2len(ptr)) + 1))
				*backwards = TRUE
			} else {
				*findc = utf_ptr2char(ptr.Add(int(utfc_ptr2len(ptr)) + 1))
				*backwards = FALSE
			}
			return
		}
		prev = ptr
		ptr = ptr.Add(int(utfc_ptr2len(ptr)) + 1)
		if utf_ptr2char(ptr) == *initc {
			if switchit != 0 {
				*findc = *initc
				*initc = utf_ptr2char(prev)
				*backwards = FALSE
			} else {
				*findc = utf_ptr2char(prev)
				*backwards = TRUE
			}
			return
		}
		ptr = ptr.Add(int(utfc_ptr2len(ptr)))
		if ptr.Get() == ',' {
			ptr = ptr.Add(1)
		}
	}
}

func findmatchlimit(oap *S_oparg_S, initc int32, flags int32, maxtravel int32) *pos_T {
	var pos *pos_T = &findmatchlimit_pos // static pos_T pos
	var findc int32 = 0
	var c int32
	var count int32 = 0
	var backwards int32 = FALSE
	var raw_string int32 = FALSE
	var inquote int32 = FALSE
	var linep Ptr[byte]
	var ptr Ptr[byte]
	var do_quotes int32
	var at_start int32
	var hash_dir int32 = 0
	var comment_dir int32 = 0
	var match_pos pos_T
	var start_in_quotes int32
	var traveled int32 = 0
	var ignore_cend int32 = FALSE
	var cpo_match int32
	var cpo_bsl int32
	var match_escaped int32 = 0
	var dir int32
	var comment_col int32 = MAXCOL
	var skip_comments int32 = B2i((flags & FM_SKIPCOMM) != 0)
	var in_block_comment int32 = FALSE

	*pos = curwin.w_cursor
	pos.coladd = 0
	linep = ml_get(pos.lnum)

	cpo_match = B2i(!vim_strchr(p_cpo, CPO_MATCH).Nil())
	cpo_bsl = B2i(!vim_strchr(p_cpo, CPO_MATCHBSL).Nil())

	if (flags & FM_BACKWARD) != 0 {
		dir = (-1)
	} else if (flags & FM_FORWARD) != 0 {
		dir = FORWARD
	} else {
		dir = 0
	}

	if initc == '/' || initc == '*' || initc == 'R' {
		comment_dir = dir
		if initc == '/' {
			ignore_cend = TRUE
		}
		if dir == FORWARD {
			backwards = FALSE
		} else {
			backwards = TRUE
		}
		raw_string = B2i(initc == 'R')
		initc = NUL
	} else if initc != '#' && initc != NUL {
		find_mps_values(&initc, &findc, &backwards, TRUE)
		if dir != 0 {
			if dir == FORWARD {
				backwards = FALSE
			} else {
				backwards = TRUE
			}
		}
		if findc == NUL {
			return nil
		}
	} else {
		if initc == '#' {
			hash_dir = dir
		} else {
			if cpo_match == 0 {
				ptr = skipwhite(linep)
				if ptr.Get() == '#' && pos.col <= colnr_T(ptr.Sub(linep)) {
					ptr = skipwhite(ptr.Add(1))
					if musl_strncmp(ptr, S("if"), 2) == 0 || musl_strncmp(ptr, S("endif"), 5) == 0 || musl_strncmp(ptr, S("el"), 2) == 0 {
						hash_dir = 1
					}
				} else if linep.At(int(pos.col)) == '/' {
					if linep.At(int(pos.col+1)) == '*' {
						comment_dir = FORWARD
						backwards = FALSE
						pos.col++
					} else if pos.col > 0 && linep.At(int(pos.col-1)) == '*' {
						comment_dir = (-1)
						backwards = TRUE
						pos.col--
					}
				} else if linep.At(int(pos.col)) == '*' {
					if linep.At(int(pos.col+1)) == '/' {
						comment_dir = (-1)
						backwards = TRUE
					} else if pos.col > 0 && linep.At(int(pos.col-1)) == '/' {
						comment_dir = FORWARD
						backwards = FALSE
					}
				}
			}

			if hash_dir == 0 && comment_dir == 0 {
				if linep.At(int(pos.col)) == NUL && pos.col != 0 {
					pos.col--
				}
				for {
					initc = utf_ptr2char(linep.Add(int(pos.col)))
					if initc == NUL {
						break
					}

					find_mps_values(&initc, &findc, &backwards, FALSE)
					if findc != 0 {
						break
					}
					pos.col += utfc_ptr2len(linep.Add(int(pos.col)))
				}
				if findc == 0 {
					if cpo_match == 0 && skipwhite(linep).Get() == '#' {
						hash_dir = 1
					} else {
						return nil
					}
				} else if cpo_bsl == 0 {
					var col int32
					var bslcnt int32 = 0

					for col = pos.col; check_prevcol(linep, col, '\\', &col) != 0; {
						bslcnt++
					}
					match_escaped = (bslcnt & 1)
				}
			}
		}
		if hash_dir != 0 {
			if oap != nil {
				oap.motion_type = MLINE
			}
			if initc != '#' {
				ptr = skipwhite(skipwhite(linep).Add(1))
				if musl_strncmp(ptr, S("if"), 2) == 0 || musl_strncmp(ptr, S("el"), 2) == 0 {
					hash_dir = 1
				} else if musl_strncmp(ptr, S("endif"), 5) == 0 {
					hash_dir = -1
				} else {
					return nil
				}
			}
			pos.col = 0
			for got_int == 0 {
				if hash_dir > 0 {
					if pos.lnum == curbuf.b_ml.ml_line_count {
						break
					}
				} else if pos.lnum == 1 {
					break
				}
				pos.lnum += linenr_T(hash_dir)
				linep = ml_get(pos.lnum)
				line_breakcheck()
				ptr = skipwhite(linep)
				if ptr.Get() != '#' {
					continue
				}
				pos.col = colnr_T(ptr.Sub(linep))
				ptr = skipwhite(ptr.Add(1))
				if hash_dir > 0 {
					if musl_strncmp(ptr, S("if"), 2) == 0 {
						count++
					} else if musl_strncmp(ptr, S("el"), 2) == 0 {
						if count == 0 {
							return pos
						}
					} else if musl_strncmp(ptr, S("endif"), 5) == 0 {
						if count == 0 {
							return pos
						}
						count--
					}
				} else {
					if musl_strncmp(ptr, S("if"), 2) == 0 {
						if count == 0 {
							return pos
						}
						count--
					} else if initc == '#' && musl_strncmp(ptr, S("el"), 2) == 0 {
						if count == 0 {
							return pos
						}
					} else if musl_strncmp(ptr, S("endif"), 5) == 0 {
						count++
					}
				}
			}
			return nil
		}
	}

	do_quotes = -1
	start_in_quotes = MAYBE
	match_pos.lnum = 0
	match_pos.col = 0
	match_pos.coladd = 0

	if (backwards != 0 && comment_dir != 0) || skip_comments != 0 {
		comment_col = check_linecomment(linep)
	}
	if skip_comments != 0 && in_block_comment == 0 && comment_col != MAXCOL && backwards != 0 && pos.col > colnr_T(comment_col) {
		pos.col = comment_col
	}

	for got_int == 0 {
		if backwards != 0 {
			if pos.col == 0 {
				if pos.lnum == 1 {
					break
				}
				pos.lnum--

				if maxtravel > 0 {
					traveled++
					if traveled > maxtravel {
						break
					}
				}

				linep = ml_get(pos.lnum)
				pos.col = ml_get_len(pos.lnum)
				do_quotes = -1
				line_breakcheck()

				if comment_dir != 0 || skip_comments != 0 {
					comment_col = check_linecomment(linep)
				}
				if skip_comments != 0 && in_block_comment == 0 && comment_col != MAXCOL && pos.col > colnr_T(comment_col) {
					pos.col = comment_col
				}
			} else {
				pos.col--
				pos.col -= utf_head_off(linep, linep.Add(int(pos.col)))
			}
		} else {
			if linep.At(int(pos.col)) == NUL {
				if pos.lnum == curbuf.b_ml.ml_line_count {
					break
				}
				pos.lnum++

				if maxtravel != 0 {
					t := traveled
					traveled++
					if t > maxtravel {
						break
					}
				}

				linep = ml_get(pos.lnum)
				pos.col = 0
				do_quotes = -1
				line_breakcheck()
				if skip_comments != 0 {
					comment_col = check_linecomment(linep)
				}
			} else {
				pos.col += utfc_ptr2len(linep.Add(int(pos.col)))
			}
		}

		if skip_comments != 0 && comment_dir == 0 && inquote == 0 {
			if backwards != 0 {
				if in_block_comment == 0 && pos.col > 0 && linep.At(int(pos.col-1)) == '*' && linep.At(int(pos.col)) == '/' && (comment_col == MAXCOL || int32(pos.col) < comment_col) {
					in_block_comment = TRUE
				} else if in_block_comment != 0 && pos.col > 0 && linep.At(int(pos.col-1)) == '/' && linep.At(int(pos.col)) == '*' {
					in_block_comment = FALSE
				}
			} else {
				if in_block_comment == 0 && linep.At(int(pos.col)) == '/' && linep.At(int(pos.col+1)) == '*' && (comment_col == MAXCOL || int32(pos.col) < comment_col) {
					in_block_comment = TRUE
				} else if in_block_comment != 0 && pos.col > 0 && linep.At(int(pos.col-1)) == '*' && linep.At(int(pos.col)) == '/' {
					in_block_comment = FALSE
				}
			}
		}

		if pos.col == 0 && (flags&FM_BLOCKSTOP) != 0 && (linep.At(0) == '{' || linep.At(0) == '}') {
			if int32(linep.At(0)) == findc && count == 0 {
				return pos
			}
			break
		}

		if comment_dir != 0 {
			if comment_dir == FORWARD {
				if linep.At(int(pos.col)) == '*' && linep.At(int(pos.col+1)) == '/' {
					pos.col++
					return pos
				}
			} else {
				if pos.col == 0 {
					continue
				} else if raw_string != 0 {
					if linep.At(int(pos.col-1)) == 'R' && linep.At(int(pos.col)) == '"' && !vim_strchr(linep.Add(int(pos.col)+1), '(').Nil() {
						var ep *pos_T
						if count > 0 {
							ep = &match_pos
						} else {
							ep = &curwin.w_cursor
						}
						if find_rawstring_end(linep, pos, ep) == 0 {
							count++
							match_pos = *pos
							match_pos.col--
						}
						linep = ml_get(pos.lnum)
					}
				} else if linep.At(int(pos.col-1)) == '/' && linep.At(int(pos.col)) == '*' && (pos.col == 1 || linep.At(int(pos.col-2)) != '*') && int32(pos.col) < comment_col {
					count++
					match_pos = *pos
					match_pos.col--
				} else if linep.At(int(pos.col-1)) == '*' && linep.At(int(pos.col)) == '/' {
					if count > 0 {
						*pos = match_pos
					} else if pos.col > 1 && linep.At(int(pos.col-2)) == '/' && int32(pos.col) <= comment_col {
						pos.col -= 2
					} else if ignore_cend != 0 {
						continue
					} else {
						return nil
					}
					return pos
				}
			}
			continue
		}

		if cpo_match != 0 {
			do_quotes = 0
		} else if do_quotes == -1 {
			at_start = do_quotes
			for ptr = linep; ptr.Get() != 0; ptr = ptr.Add(1) {
				if ptr == linep.Add(int(pos.col+backwards)) {
					at_start = (do_quotes & 1)
				}
				if ptr.Get() == '"' && (ptr == linep || ptr.At(-1) != '\'' || ptr.At(1) != '\'') {
					do_quotes++
				}
				if ptr.Get() == '\\' && ptr.At(1) != NUL {
					ptr = ptr.Add(1)
				}
			}
			do_quotes &= 1

			if do_quotes == 0 {
				inquote = FALSE
				if ptr.At(-1) == '\\' {
					do_quotes = 1
					if start_in_quotes == MAYBE {
						inquote = at_start
						if inquote != 0 {
							start_in_quotes = TRUE
						}
					} else if backwards != 0 {
						inquote = TRUE
					}
				}
				if pos.lnum > 1 {
					ptr = ml_get(pos.lnum - 1)
					if ptr.Get() != 0 && ptr.At(int(ml_get_len(pos.lnum-1))-1) == '\\' {
						do_quotes = 1
						if start_in_quotes == MAYBE {
							inquote = at_start
							if inquote != 0 {
								start_in_quotes = TRUE
							}
						} else if backwards == 0 {
							inquote = TRUE
						}
					}

					linep = ml_get(pos.lnum)
				}
			}
		}
		if start_in_quotes == MAYBE {
			start_in_quotes = FALSE
		}

		c = utf_ptr2char(linep.Add(int(pos.col)))
		switch c {
		case NUL:
			if pos.col == 0 || linep.At(int(pos.col-1)) != '\\' {
				inquote = FALSE
				start_in_quotes = FALSE
			}

		case '"':
			if do_quotes != 0 {
				var col int32

				for col = pos.col - 1; col >= 0; col-- {
					if linep.At(int(col)) != '\\' {
						break
					}
				}
				if ((int32(pos.col) - 1 - col) & 1) == 0 {
					inquote = B2i(inquote == 0)
					start_in_quotes = FALSE
				}
			}

		case '\'':
			if cpo_match == 0 && initc != '\'' && findc != '\'' {
				if backwards != 0 {
					if pos.col > 1 {
						if linep.At(int(pos.col-2)) == '\'' {
							pos.col -= 2
							break
						} else if linep.At(int(pos.col-2)) == '\\' && pos.col > 2 && linep.At(int(pos.col-3)) == '\'' {
							pos.col -= 3
							break
						}
					}
				} else if linep.At(int(pos.col+1)) != 0 {
					if linep.At(int(pos.col+1)) == '\\' && linep.At(int(pos.col+2)) != 0 && linep.At(int(pos.col+3)) == '\'' {
						pos.col += 3
						break
					} else if linep.At(int(pos.col+2)) == '\'' {
						pos.col += 2
						break
					}
				}
			}
			fallthrough

		default:
			if skip_comments != 0 && (in_block_comment != 0 || (comment_col != MAXCOL && int32(pos.col) >= comment_col)) {
				break
			}

			if (inquote == 0 || start_in_quotes == TRUE) && (c == initc || c == findc) {
				var col int32
				var bslcnt int32 = 0

				if cpo_bsl == 0 {
					for col = pos.col; check_prevcol(linep, col, '\\', &col) != 0; {
						bslcnt++
					}
				}
				if cpo_bsl != 0 || (bslcnt&1) == match_escaped {
					if c == initc {
						count++
					} else {
						if count == 0 {
							return pos
						}
						count--
					}
				}
			}
		}
	}

	if comment_dir == (-1) && count > 0 {
		*pos = match_pos
		return pos
	}
	return nil
}

func showmatch(c int32) {
	var lpos *pos_T
	var save_cursor pos_T
	var mpos pos_T
	var vcol colnr_T
	var save_so int64
	var save_siso int64
	var save_dollar_vcol colnr_T
	var p Ptr[byte]
	var so *int64
	var siso *int64
	if curwin.w_onebuf_opt.wo_so >= 0 {
		so = &curwin.w_onebuf_opt.wo_so
	} else {
		so = &p_so
	}
	if curwin.w_onebuf_opt.wo_siso >= 0 {
		siso = &curwin.w_onebuf_opt.wo_siso
	} else {
		siso = &p_siso
	}

	for p = curbuf.b_p_mps; p.Get() != NUL; p = p.Add(1) {
		p = p.Add(int(utfc_ptr2len(p)) + 1)
		if utf_ptr2char(p) == c {
			break
		}
		p = p.Add(int(utfc_ptr2len(p)))
		if p.Get() == NUL {
			return
		}
	}
	if p.Get() == NUL {
		return
	}

	lpos = findmatch(nil, NUL)
	if lpos == nil {
		vim_beep(BO_MATCH)
		return
	}

	if lpos.lnum < curwin.w_topline || lpos.lnum >= curwin.w_botline {
		return
	}

	if curwin.w_onebuf_opt.wo_wrap == 0 {
		getvcol(curwin, lpos, nil, &vcol, nil, 0)
	}

	var col_visible int32 = B2i(curwin.w_onebuf_opt.wo_wrap != 0 || (vcol >= curwin.w_leftcol && vcol < curwin.w_leftcol+curwin.w_width))
	if col_visible == 0 {
		return
	}

	mpos = *lpos
	save_cursor = curwin.w_cursor
	save_so = *so
	save_siso = *siso
	if dollar_vcol >= 0 && dollar_vcol == curwin.w_virtcol {
		dollar_vcol = -1
	}
	curwin.w_virtcol++
	update_screen(UPD_VALID)

	save_dollar_vcol = dollar_vcol
	curwin.w_cursor = mpos
	*so = 0
	*siso = 0
	showruler(FALSE)
	setcursor()
	cursor_on()
	out_flush_cursor(TRUE, FALSE)

	dollar_vcol = save_dollar_vcol

	if !vim_strchr(p_cpo, CPO_SHOWMATCH).Nil() {
		ui_delay(p_mat*100+8, TRUE)
	} else if char_avail() == 0 {
		ui_delay(p_mat*100+9, FALSE)
	}
	curwin.w_cursor = save_cursor
	*so = save_so
	*siso = save_siso
}

func is_zero_width(pattern Ptr[byte], patternlen usize, move int32, cur *pos_T, direction int32) int32 {
	var regmatch regmmatch_T
	var nmatched int32 = 0
	var result int32 = -1
	var pos pos_T
	var called_emsg_before int32 = called_emsg
	var flag int32 = 0

	if pattern.Nil() {
		pattern = spats[last_idx].pat
		patternlen = spats[last_idx].patlen
	}

	if search_regcomp(pattern, patternlen, nil, RE_SEARCH, RE_SEARCH, SEARCH_KEEP, &regmatch) == FAIL {
		return -1
	}

	regmatch.startpos[0].col = -1
	if move != 0 {
		pos.lnum = 0
		pos.col = 0
		pos.coladd = 0
	} else {
		pos = *cur
		flag = SEARCH_START
	}

	if searchit(curwin, curbuf, &pos, nil, direction, pattern, patternlen, 1, SEARCH_KEEP+flag, RE_SEARCH, nil) != FAIL {
		for {
			regmatch.startpos[0].col++
			nmatched = int32(vim_regexec_multi(&regmatch, curwin, curbuf, pos.lnum, regmatch.startpos[0].col, nil))
			if nmatched != 0 {
				break
			}
			var more bool
			if direction == FORWARD {
				more = regmatch.startpos[0].col < pos.col
			} else {
				more = regmatch.startpos[0].col > pos.col
			}
			if !(regmatch.regprog != nil && more) {
				break
			}
		}

		if called_emsg == called_emsg_before {
			result = B2i(nmatched != 0 && regmatch.startpos[0].lnum == regmatch.endpos[0].lnum && regmatch.startpos[0].col == regmatch.endpos[0].col)
		}
	}

	vim_regfree(regmatch.regprog)
	return result
}

func current_search(count int64, forward int32) int32 {
	var start_pos pos_T
	var end_pos pos_T
	var orig_pos pos_T
	var pos pos_T
	var i int32
	var dir int32
	var result int32
	var old_p_ws byte = byte(p_ws)
	var flags int32 = 0
	var save_VIsual pos_T = VIsual
	var zero_width int32
	var skip_first_backward int32

	// LT_POS and EQUAL_POS
	lt := func(a, b pos_T) bool {
		if a.lnum != b.lnum {
			return a.lnum < b.lnum
		}
		if a.col != b.col {
			return a.col < b.col
		}
		return a.coladd < b.coladd
	}
	eq := func(a, b pos_T) bool {
		return a.lnum == b.lnum && a.col == b.col && a.coladd == b.coladd
	}

	if VIsual_active != 0 && p_sel.Get() == 'e' && lt(VIsual, curwin.w_cursor) {
		dec_cursor()
	}

	skip_first_backward = B2i(forward != 0 && VIsual_active != 0 && lt(curwin.w_cursor, VIsual))

	pos = curwin.w_cursor
	orig_pos = pos
	if VIsual_active != 0 {
		if forward != 0 {
			incl(&pos)
		} else {
			decl(&pos)
		}
	}

	zero_width = is_zero_width(spats[last_idx].pat, spats[last_idx].patlen, TRUE, &curwin.w_cursor, FORWARD)
	if zero_width == -1 {
		return FAIL
	}

	for i = 0; i < 2; i++ {
		if forward != 0 {
			if i == 0 && skip_first_backward != 0 {
				continue
			}
			dir = i
		} else {
			dir = B2i(i == 0)
		}

		flags = 0
		if dir == 0 && zero_width == 0 {
			flags = SEARCH_END
		}
		end_pos = pos

		if i == 0 {
			p_ws = FALSE
		}

		var sdir int32
		if dir != 0 {
			sdir = FORWARD
		} else {
			sdir = (-1)
		}
		var cnt int64
		if i != 0 {
			cnt = count
		} else {
			cnt = 1
		}
		result = searchit(curwin, curbuf, &pos, &end_pos, sdir, spats[last_idx].pat, spats[last_idx].patlen, cnt, SEARCH_KEEP|flags, RE_SEARCH, nil)

		p_ws = int32(old_p_ws)

		if i == 1 && result == 0 {
			curwin.w_cursor = orig_pos
			if VIsual_active != 0 {
				VIsual = save_VIsual
			}
			return FAIL
		} else if i == 0 && result == 0 {
			if forward != 0 {
				pos.lnum = 0
				pos.col = 0
				pos.coladd = 0
			} else {
				pos.lnum = curwin.w_buffer.b_ml.ml_line_count
				pos.col = ml_get_len(curwin.w_buffer.b_ml.ml_line_count)
			}
		}
	}

	start_pos = pos

	if VIsual_active == 0 {
		VIsual = start_pos
	}

	curwin.w_cursor = end_pos
	if lt(VIsual, end_pos) && forward != 0 {
		if skip_first_backward != 0 {
			curwin.w_cursor = pos
		} else {
			dec_cursor()
		}
	} else if VIsual_active != 0 && lt(curwin.w_cursor, VIsual) && forward != 0 {
		curwin.w_cursor = pos
	}
	VIsual_active = TRUE
	VIsual_mode = 'v'

	if p_sel.Get() == 'e' {
		if forward != 0 && (lt(VIsual, curwin.w_cursor) || eq(VIsual, curwin.w_cursor)) {
			inc_cursor()
		} else if forward == 0 && (lt(curwin.w_cursor, VIsual) || eq(curwin.w_cursor, VIsual)) {
			inc(&VIsual)
		}
	}

	may_start_select('c')
	redraw_curbuf_later(UPD_INVERTED)
	showmode()

	return OK
}

func cmdline_search_stat(dirc int32, pos *pos_T, cursor_pos *pos_T, show_top_bot_msg int32, msgbuf Ptr[byte], msgbuflen usize, recompute int32, maxcount int32, timeout int64) {
	var stat searchstat_T

	update_search_stat(dirc, pos, cursor_pos, &stat, recompute, maxcount, timeout)
	if stat.cur <= 0 {
		return
	}

	t := Mk[byte](SEARCH_STAT_BUF_LEN)
	var len_ usize

	{
		if stat.incomplete == 1 {
			len_ = usize(vim_snprintf(t, SEARCH_STAT_BUF_LEN, S("[?/??]")))
		} else if stat.cnt > maxcount && stat.cur > maxcount {
			len_ = usize(vim_snprintf(t, SEARCH_STAT_BUF_LEN, S("[>%d/>%d]"), maxcount, maxcount))
		} else if stat.cnt > maxcount {
			len_ = usize(vim_snprintf(t, SEARCH_STAT_BUF_LEN, S("[%d/>%d]"), stat.cur, maxcount))
		} else {
			len_ = usize(vim_snprintf(t, SEARCH_STAT_BUF_LEN, S("[%d/%d]"), stat.cur, stat.cnt))
		}
	}

	if show_top_bot_msg != 0 && len_+2 < SEARCH_STAT_BUF_LEN {
		Memmove(t.Add(2), t, int(len_))
		t.Set(0, 'W')
		t.Set(1, ' ')
		len_ += 2
	}

	if len_ > msgbuflen {
		len_ = msgbuflen
	}
	Memmove(msgbuf.Add(int(msgbuflen-len_)), t, int(len_))

	if dirc == '?' && stat.cur == maxcount+1 {
		stat.cur = -1
	}

	msg_hist_off = TRUE
	give_warning(msgbuf, FALSE)
	msg_hist_off = FALSE
}

func init() {
	update_search_stat_lastpos = pos_T{0, 0, 0}
	update_search_stat_cur = 0
	update_search_stat_cnt = 0
	update_search_stat_exact_match = FALSE
	update_search_stat_incomplete = 0
	update_search_stat_last_maxcount = 0
	update_search_stat_chgtick = 0
	update_search_stat_lastpat = Ptr[byte]{}
	update_search_stat_lastpatlen = 0
	update_search_stat_lbuf = nil
}

func update_search_stat(dirc int32, pos *pos_T, cursor_pos *pos_T, stat *S_searchstat, recompute int32, maxcount int32, timeout int64) {
	var save_ws int32 = p_ws
	var wraparound int32 = FALSE
	var p pos_T = (*pos)

	// LT_POS and EQUAL_POS
	lt := func(a, b pos_T) bool {
		if a.lnum != b.lnum {
			return a.lnum < b.lnum
		}
		if a.col != b.col {
			return a.col < b.col
		}
		return a.coladd < b.coladd
	}
	eq := func(a, b pos_T) bool {
		return a.lnum == b.lnum && a.col == b.col && a.coladd == b.coladd
	}

	*stat = S_searchstat{}

	if dirc == 0 && recompute == 0 && !(update_search_stat_lastpos.lnum == 0 && update_search_stat_lastpos.col == 0 && update_search_stat_lastpos.coladd == 0) {
		stat.cur = update_search_stat_cur
		stat.cnt = update_search_stat_cnt
		stat.exact_match = update_search_stat_exact_match
		stat.incomplete = update_search_stat_incomplete
		stat.last_maxcount = update_search_stat_last_maxcount
		return
	}
	update_search_stat_last_maxcount = maxcount

	wraparound = B2i((dirc == '?' && lt(update_search_stat_lastpos, p)) || (dirc == '/' && lt(p, update_search_stat_lastpos)))

	if !(int64(update_search_stat_chgtick) == curbuf.b_changedtick && (!update_search_stat_lastpat.Nil() && musl_strncmp(update_search_stat_lastpat, spats[last_idx].pat, update_search_stat_lastpatlen) == 0 && update_search_stat_lastpatlen == spats[last_idx].patlen) && eq(update_search_stat_lastpos, *cursor_pos) && update_search_stat_lbuf == curbuf) || wraparound != 0 || update_search_stat_cur < 0 || (maxcount > 0 && update_search_stat_cur > maxcount) || recompute != 0 {
		update_search_stat_cur = 0
		update_search_stat_cnt = 0
		update_search_stat_exact_match = FALSE
		update_search_stat_incomplete = 0
		update_search_stat_lastpos.lnum = 0
		update_search_stat_lastpos.col = 0
		update_search_stat_lastpos.coladd = 0
		update_search_stat_lbuf = curbuf
	}

	var cond bool
	if dirc == 0 || dirc == '/' {
		cond = update_search_stat_cur < update_search_stat_cnt
	} else {
		cond = update_search_stat_cur > 1
	}
	if eq(update_search_stat_lastpos, *cursor_pos) && wraparound == 0 && cond {
		if dirc == 0 {
			update_search_stat_cur += 0
		} else if dirc == '/' {
			update_search_stat_cur += 1
		} else {
			update_search_stat_cur += -1
		}
	} else {
		var done_search int32 = FALSE
		var endpos pos_T = pos_T{0, 0, 0}

		p_ws = FALSE
		for got_int == 0 && searchit(curwin, curbuf, &update_search_stat_lastpos, &endpos, FORWARD, Ptr[byte]{}, 0, 1, SEARCH_KEEP, RE_LAST, nil) != FAIL {
			done_search = TRUE
			update_search_stat_cnt++
			if lt(update_search_stat_lastpos, p) || eq(update_search_stat_lastpos, p) {
				update_search_stat_cur = update_search_stat_cnt
				if lt(p, endpos) {
					update_search_stat_exact_match = TRUE
				}
			}
			fast_breakcheck()
			if maxcount > 0 && update_search_stat_cnt > maxcount {
				update_search_stat_incomplete = 2
				break
			}
		}
		if got_int != 0 {
			update_search_stat_cur = -1
		}
		if done_search != 0 {
			update_search_stat_lastpat = vim_strnsave(spats[last_idx].pat, spats[last_idx].patlen)
			update_search_stat_lastpatlen = spats[last_idx].patlen
			update_search_stat_chgtick = int32(curbuf.b_changedtick)
			update_search_stat_lbuf = curbuf
			update_search_stat_lastpos = p
		}
	}
	stat.cur = update_search_stat_cur
	stat.cnt = update_search_stat_cnt
	stat.exact_match = update_search_stat_exact_match
	stat.incomplete = update_search_stat_incomplete
	stat.last_maxcount = update_search_stat_last_maxcount
	p_ws = save_ws
}

func vim_strsave(string_ Ptr[byte]) Ptr[byte] {
	var p Ptr[byte]
	var len_ usize

	len_ = musl_strlen(string_) + 1
	p = Alloc(int(len_))
	Memmove(p, string_, int(len_))
	return p
}

func vim_strnsave(string_ Ptr[byte], len_ usize) Ptr[byte] {
	var p Ptr[byte]

	p = Alloc(int(len_ + 1))

	musl_strncpy(p, string_, len_)
	p.Set(int(len_), NUL)
	return p
}

func vim_strsave_escaped(string_ Ptr[byte], esc_chars Ptr[byte]) Ptr[byte] {
	return vim_strsave_escaped_ext(string_, esc_chars, '\\', FALSE)
}

func vim_strsave_escaped_ext(string_ Ptr[byte], esc_chars Ptr[byte], cc int32, bsl int32) Ptr[byte] {
	var p Ptr[byte]
	var p2 Ptr[byte]
	var escaped_string Ptr[byte]
	var length uint32
	var l int32

	length = 1
	for p = string_; p.Get() != 0; p = p.Add(1) {
		l = utfc_ptr2len(p)
		if l > 1 {
			length += uint32(l)
			p = p.Add(int(l - 1))
			continue
		}
		if !vim_strchr(esc_chars, int32(p.Get())).Nil() || (bsl != 0 && rem_backslash(p) != 0) {
			length++
		}
		length++
	}
	escaped_string = Alloc(int(length))
	p2 = escaped_string
	for p = string_; p.Get() != 0; p = p.Add(1) {
		l = utfc_ptr2len(p)
		if l > 1 {
			Memmove(p2, p, int(l))
			p2 = p2.Add(int(l))
			p = p.Add(int(l - 1))
			continue
		}
		if !vim_strchr(esc_chars, int32(p.Get())).Nil() || (bsl != 0 && rem_backslash(p) != 0) {
			p2.Put(byte(cc))
			p2 = p2.Add(1)
		}
		p2.Put(p.Get())
		p2 = p2.Add(1)
	}
	p2.Put(NUL)
	return escaped_string
}

func vim_strnsave_up(string_ Ptr[byte], len_ usize) Ptr[byte] {
	var p1 Ptr[byte]

	p1 = vim_strnsave(string_, len_)
	vim_strup(p1)
	return p1
}

func vim_strup(p Ptr[byte]) {
	var p2 Ptr[byte]
	var c int32

	if p.Nil() {
		return
	}

	p2 = p
	for {
		c = int32(p2.Get())
		if c == NUL {
			break
		}
		if c < 'a' || c > 'z' {
			p2.Put(byte(c))
		} else {
			p2.Put(byte(c - 0x20))
		}
		p2 = p2.Add(1)
	}
}

func del_trailing_spaces(ptr Ptr[byte]) {
	var q Ptr[byte]

	q = ptr.Add(int(musl_strlen(ptr)))
	for {
		q = q.Add(-1)
		if !(q.Gt(ptr) && (q.At(0) == ' ' || q.At(0) == '\t') && q.At(-1) != '\\' && q.At(-1) != Ctrl_V) {
			break
		}
		q.Put(NUL)
	}
}

func vim_strncpy(to Ptr[byte], from Ptr[byte], len_ usize) {
	musl_strncpy(to, from, len_)
	to.Set(int(len_), NUL)
}

func vim_strcat(to Ptr[byte], from Ptr[byte], tosize usize) {
	var tolen usize = musl_strlen(to)
	var fromlen usize = musl_strlen(from)

	if tolen+fromlen+1 > tosize {
		Memmove(to.Add(int(tolen)), from, int(tosize-tolen-1))
		to.Set(int(tosize-1), NUL)
	} else {
		Memmove(to.Add(int(tolen)), from, int(fromlen+1))
	}
}

func vim_strnicmp_asc(s1 Ptr[byte], s2 Ptr[byte], len_ usize) int32 {
	var i int32 = 0

	for len_ > 0 {
		// C's plain char is signed here: read each byte as signed char.
		var a int32 = int32(int8(s1.Get()))
		var b int32 = int32(int8(s2.Get()))
		if a < 'A' || a > 'Z' {
		} else {
			a = a + ('a' - 'A')
		}
		if b < 'A' || b > 'Z' {
		} else {
			b = b + ('a' - 'A')
		}
		i = a - b
		if i != 0 {
			break
		}
		if s1.Get() == NUL {
			break
		}
		s1 = s1.Add(1)
		s2 = s2.Add(1)
		len_--
	}
	return i
}

func vim_strchr(string_ Ptr[byte], c int32) Ptr[byte] {
	var p Ptr[byte]
	var b int32

	p = string_
	if c > 0 && c < 0x80 {
		return vim_strbyte(string_, c)
	}
	if c >= 0x80 {
		for p.Get() != NUL {
			var l int32 = utfc_ptr2len(p)

			if utf_ptr2char(p) == c && l > 1 {
				return p
			}
			p = p.Add(int(l))
		}
		return Ptr[byte]{}
	}
	for {
		b = int32(p.Get())
		if b == NUL {
			break
		}
		if b == c {
			return p
		}
		p = p.Add(int(utfc_ptr2len(p)))
	}
	return Ptr[byte]{}
	for {
		b = int32(p.Get())
		if b == NUL {
			break
		}
		if b == c {
			return p
		}
		p = p.Add(1)
	}
	return Ptr[byte]{}
}

func vim_strbyte(string_ Ptr[byte], c int32) Ptr[byte] {
	if c <= 0 || c > 255 {
		return Ptr[byte]{}
	}
	return musl_strchr(string_, c)
}

func sort_strings(files Ptr[Ptr[byte]], count int32) {
	var i int32
	var j int32
	var s Ptr[byte]

	for i = 1; i < count; i++ {
		s = files.At(int(i))
		for j = i; j > 0 && musl_strcmp(files.At(int(j-1)), s) > 0; j-- {
			files.Set(int(j), files.At(int(j-1)))
		}
		files.Set(int(j), s)
	}
}

func concat_str(str1 Ptr[byte], str2 Ptr[byte]) Ptr[byte] {
	var dest Ptr[byte]
	var l usize
	if str1.Nil() {
		l = 0
	} else {
		l = musl_strlen(str1)
	}

	var l2 usize
	if str2.Nil() {
		l2 = 0
	} else {
		l2 = musl_strlen(str2)
	}
	dest = Alloc(int(l + l2 + 1))
	if str1.Nil() {
		dest.Put(NUL)
	} else {
		musl_strcpy(dest, str1)
	}
	if !str2.Nil() {
		musl_strcpy(dest.Add(int(l)), str2)
	}
	return dest
}

func set_rgb_term_prop() {
	if t_colors == 0x1000000 {
		term_props[TPR_RGB].tpr_status = TPR_YES
	} else {
		term_props[TPR_RGB].tpr_status = TPR_UNKNOWN
	}
}

func init_term_props(all int32) {
	var i int32

	term_props[TPR_CURSOR_STYLE].tpr_name = S("cursor_style")
	term_props[TPR_CURSOR_STYLE].tpr_set_by_termresponse = FALSE
	term_props[TPR_CURSOR_BLINK].tpr_name = S("cursor_blink_mode")
	term_props[TPR_CURSOR_BLINK].tpr_set_by_termresponse = FALSE
	term_props[TPR_UNDERLINE_RGB].tpr_name = S("underline_rgb")
	term_props[TPR_UNDERLINE_RGB].tpr_set_by_termresponse = TRUE
	term_props[TPR_MOUSE].tpr_name = S("mouse")
	term_props[TPR_MOUSE].tpr_set_by_termresponse = TRUE
	term_props[TPR_KITTY].tpr_name = S("kitty")
	term_props[TPR_KITTY].tpr_set_by_termresponse = FALSE
	term_props[TPR_DECRQM].tpr_name = S("decrqm")
	term_props[TPR_DECRQM].tpr_set_by_termresponse = TRUE
	term_props[TPR_RGB].tpr_name = S("rgb")
	term_props[TPR_RGB].tpr_set_by_termresponse = FALSE

	for i = 0; i < TPR_COUNT; i++ {
		if all != 0 || term_props[i].tpr_set_by_termresponse != 0 {
			term_props[i].tpr_status = TPR_UNKNOWN
		}
	}

	set_rgb_term_prop()
}

func find_builtin_term(term Ptr[byte]) Ptr[tcap_entry_T] {
	for i := int32(0); ; i++ {
		var name Ptr[byte] = builtin_terminals[i].bitc_name
		if name.Nil() {
			break
		}
		if musl_strcmp(term, name) == 0 {
			return builtin_terminals[i].bitc_table
		}
	}
	return Ptr[tcap_entry_T]{}
}

func apply_builtin_tcap(term Ptr[byte], entries Ptr[tcap_entry_T], overwrite int32) {
	var term_8bit int32 = term_is_8bit(term)

	for p := entries; p.P().bt_entry != int32(KS_NAME) && p.P().bt_entry != BT_EXTRA_KEYS; p = p.Add(1) {
		if int32(p.P().bt_entry) >= 0 {
			if term_strings[p.P().bt_entry].Nil() || term_strings[p.P().bt_entry] == empty_option || overwrite != 0 {
				if term_8bit != 0 && term_7to8bit(p.P().bt_string) != 0 {
					var s Ptr[byte]
					var t Ptr[byte]

					s = vim_strsave(p.P().bt_string)
					for t = s; t.Get() != 0; t = t.Add(1) {
						if term_7to8bit(t) != 0 {
							t.Put(byte(term_7to8bit(t)))
							Memmove(t.Add(1), t.Add(2), int(musl_strlen(t.Add(2))+1))
						}
					}
					term_strings[p.P().bt_entry] = s
					set_term_option_alloced(View(term_strings[:]).Add(int(p.P().bt_entry)))
				} else {
					term_strings[p.P().bt_entry] = p.P().bt_string
				}
			}
		} else {
			name := Mk[byte](2)
			name.Set(0, byte((-int32(p.P().bt_entry))&0xff))
			name.Set(1, byte((uint32(-int32(p.P().bt_entry))>>8)&0xff))
			if find_termcode(name).Nil() || overwrite != 0 {
				add_termcode(name, p.P().bt_string, term_8bit)
			}
		}
	}
}

func apply_keyprotocol(term Ptr[byte], prot keyprot_T) {
	if prot == KEYPROTOCOL_KITTY {
		apply_builtin_tcap(term, builtin_kitty, TRUE)
	}
	if prot == KEYPROTOCOL_MOK2 {
		apply_builtin_tcap(term, builtin_mok2, TRUE)
	}

	if prot != KEYPROTOCOL_NONE {
		accept_modifiers_for_function_keys()
	}
}

func parse_builtin_tcap(term Ptr[byte]) {
	var entries Ptr[tcap_entry_T] = find_builtin_term(term)
	if !entries.Nil() {
		apply_builtin_tcap(term, entries, FALSE)
	}
}

func set_color_count(nr int32) {
	nr_colors := Mk[byte](20)

	t_colors = nr
	if t_colors > 1 {
		vim_snprintf(nr_colors, 20, S("%d"), t_colors)
	} else {
		nr_colors.Put(NUL)
	}
	set_string_option_direct(S("t_Co"), -1, nr_colors, OPT_FREE, 0)
}

func may_adjust_color_count(val int32) {
	if val == t_colors {
		return
	}

	set_keep_msg_from_hist()
	set_color_count(val)
	init_highlight(TRUE, FALSE)
	redraw_asap(UPD_CLEAR)
}

func term_strings_not_set(idx int32) int32 {
	return B2i(term_strings[int32(idx)].Nil() || term_strings[int32(idx)] == empty_option)
}

func report_term_error(error_msg Ptr[byte], term Ptr[byte]) {
	buf := Mk[byte](1024)

	if !error_msg.Nil() {
		vim_snprintf(buf, 1024, S("\r\n%s\r\n'%s%s\r\n"), error_msg, term, gettext_(S("' not known")))
	} else {
		vim_snprintf(buf, 1024, S("\r\n'%s%s\r\n"), term, gettext_(S("' not known")))
	}
	host_message(buf, -1, TRUE)
}

// ==== from f16.go ====
// Transpiled by hand from editor.c: match_keyprotocol .. ui_inchar.

func match_keyprotocol(term Ptr[byte]) keyprot_T {
	var len_ int32
	var buf Ptr[byte]
	var ret keyprot_T
	var p Ptr[byte]
	var colon Ptr[byte]
	var prot keyprot_T
	var regmatch regmatch_T
	var match int32

	len_ = int32(musl_strlen(p_kpc)) + 1
	buf = Alloc(int(len_))
	if buf.Nil() {
		return KEYPROTOCOL_FAIL
	}

	ret = KEYPROTOCOL_FAIL
	p = p_kpc
	for p.Get() != NUL {
		copy_option_part(&p, buf, len_, S(","))
		colon = vim_strchr(buf, ':')
		if colon.Nil() || colon == buf || colon.At(1) == NUL {
			goto theend
		}
		colon.Put(NUL)

		if musl_strcmp(colon.Add(1), S("none")) == 0 {
			prot = KEYPROTOCOL_NONE
		} else if musl_strcmp(colon.Add(1), S("mok2")) == 0 {
			prot = KEYPROTOCOL_MOK2
		} else if musl_strcmp(colon.Add(1), S("kitty")) == 0 {
			prot = KEYPROTOCOL_KITTY
		} else {
			goto theend
		}

		regmatch = regmatch_T{}
		regmatch.rm_ic = TRUE
		regmatch.regprog = vim_regcomp(buf, RE_MAGIC)
		if regmatch.regprog == nil {
			goto theend
		}

		match = B2i(!term.Nil() && vim_regexec(&regmatch, term, colnr_T(0)) != 0)
		vim_regfree(regmatch.regprog)
		if match != 0 {
			ret = prot
			goto theend
		}
	}

	ret = KEYPROTOCOL_NONE

theend:
	return ret
}

func set_termname(term Ptr[byte]) int32 {
	var width int32 = 0
	var height int32 = 0
	var error_msg Ptr[byte]
	var bs_p Ptr[byte]
	var del_p Ptr[byte]

	detected_8bit = FALSE

	if term_is_builtin(term) != 0 {
		term = term.Add(8)
	}

	{
		termp := find_builtin_term(term)
		if termp.Nil() {
			report_term_error(error_msg, term)

			screen_start()
			wait_return(TRUE)
			return FAIL
		}
		out_flush()
		clear_termoptions()
		parse_builtin_tcap(term)

		if !musl_strstr(term, S("256color")).Nil() && (term_strings_not_set(KS_CCO) != 0 || musl_atoi(term_strings[KS_CCO]) < 256) {
			apply_builtin_tcap(term, builtin_256colors, TRUE)
		}
	}

	{
		kpc := match_keyprotocol(term)
		apply_keyprotocol(term, kpc)
	}

	if musl_strcmp(term, S("pcterm")) == 0 {
		term_strings[KS_CCS] = S("yes")
	} else {
		term_strings[KS_CCS] = empty_option
	}

	if !musl_strstr(term, S("kitty")).Nil() && (term_strings[KS_CRV].Nil() || term_strings[KS_CRV].Get() == NUL) {
		term_strings[KS_CRV] = S("\033[>c")
	}

	get_stty()

	{
		bs_p = find_termcode(S("kb"))
		del_p = find_termcode(S("kD"))
		if bs_p.Nil() || bs_p.Get() == NUL {
			bs_p = S("\010")
			add_termcode(S("kb"), bs_p, FALSE)
		}
		if (del_p.Nil() || del_p.Get() == NUL) && (bs_p.Nil() || bs_p.Get() != DEL) {
			add_termcode(S("kD"), S("\177"), FALSE)
		}
	}

	term_is_xterm = vim_is_xterm(term)

	{
		name := Mk[byte](3)

		name.Set(0, KS_EXTRA)
		name.Set(1, KE_FOCUSGAINED)
		name.Set(2, NUL)
		add_termcode(name, S("\033[I"), FALSE)

		name.Set(1, KE_FOCUSLOST)
		add_termcode(name, S("\033[O"), FALSE)

		need_gather = TRUE
	}
	focus_state = MAYBE

	ttest(TRUE)

	full_screen = TRUE
	set_term_defaults()

	if starting != NO_SCREEN {
		starttermcap()
	}

	if width <= 0 || height <= 0 {
		width = 80
		height = 24
	}
	set_shellsize(width, height, FALSE)
	if starting != NO_SCREEN {
		if scroll_region != 0 {
			scroll_region_reset()
		}
		check_map_keycodes()
	}

	return OK
}

func add_termcap_entry(name Ptr[byte], force int32) int32 {
	var term Ptr[byte]
	var key int32

	if force == 0 && !find_termcode(name).Nil() {
		return OK
	}

	term = term_strings[KS_NAME]
	if term.Nil() || term.Get() == NUL {
		return FAIL
	}

	if term_is_builtin(term) != 0 {
		term = term.Add(8)
	}

	{
		termp := find_builtin_term(term)
		if !termp.Nil() {
			key = -(int32(name.At(0)) + (int32(name.At(1)) << 8))
			termp = termp.Add(1)
			for termp.P().bt_entry != int32(KS_NAME) {
				if termp.P().bt_entry == key {
					add_termcode(name, termp.P().bt_string, term_is_8bit(term))
					return OK
				}
				termp = termp.Add(1)
			}
		}
	}

	if GaData[estack_T](&exestack).At(int(exestack.ga_len - 1)).es_name.Nil() {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_no_str_entry_in_termcap), name)
		emsg(iobuff_or(gettext_(e_no_str_entry_in_termcap)))
	}
	return FAIL
}

func term_is_builtin(name Ptr[byte]) int32 {
	return B2i(musl_strncmp(name, S("builtin_"), usize(8)) == 0)
}

func term_is_8bit(name Ptr[byte]) int32 {
	return B2i(detected_8bit != 0 || !musl_strstr(name, S("8bit")).Nil())
}

func term_7to8bit(p Ptr[byte]) int32 {
	if p.Get() != ESC {
		return 0
	}

	if p.At(1) == '[' {
		return CSI
	} else if p.At(1) == ']' {
		return OSC
	} else if p.At(1) == 'O' {
		return 0x8f
	}
	return 0
}

func tltoa(i uint64) Ptr[byte] {
	var p Ptr[byte]

	p = tltoa_buf.Add(15)
	p.Put('\000')
	for {
		p = p.Add(-1)
		p.Put(byte(i%10 + '0'))
		i /= 10
		if !(i > 0 && p.Gt(tltoa_buf)) {
			break
		}
	}
	return p
}

func tgoto(cm Ptr[byte], x int32, y int32) Ptr[byte] {
	var p Ptr[byte]
	var s Ptr[byte]
	var e Ptr[byte]

	if cm.Nil() {
		return S("OOPS")
	}
	e = tgoto_buf.Add(29)
	for s = tgoto_buf; s.Lt(e) && cm.Get() != 0; cm = cm.Add(1) {
		if cm.Get() != '%' {
			s.Put(cm.Get())
			s = s.Add(1)
			continue
		}
		cm = cm.Add(1)
		switch cm.Get() {
		case 'd':
			p = tltoa(uint64(y))
			y = x
			for p.Get() != 0 {
				s.Put(p.Get())
				s = s.Add(1)
				p = p.Add(1)
			}
		case 'i':
			x++
			y++
		case '+':
			cm = cm.Add(1)
			s.Put(byte(int32(int8(cm.Get())) + y))
			s = s.Add(1)
			y = x
		case '%':
			s.Put(cm.Get())
			s = s.Add(1)
		default:
			return S("OOPS")
		}
	}
	s.Put('\000')
	return tgoto_buf
}

func termcapinit() {
	var term Ptr[byte] = S("xterm-256color")

	set_string_option_direct(S("term"), -1, term, OPT_FREE, 0)

	set_string_default(S("term"), term)
	set_string_default(S("ttytype"), term)

	if !term_strings[KS_NAME].Nil() {
		set_termname(term_strings[KS_NAME])
	} else {
		set_termname(term)
	}
}

func out_flush() {
	var len_ int32

	if out_pos == 0 {
		return
	}

	len_ = out_pos
	out_pos = 0
	ui_write(out_buf, len_)
}

func out_flush_cursor(force int32, clear_selection int32) {
	out_flush()
}

func out_char(c uint32) {
	if c == '\n' {
		out_char('\r')
	}

	out_buf.Set(int(out_pos), byte(c))
	out_pos++

	if out_pos >= OUT_SIZE || p_wd != 0 {
		out_flush()
	}
}

func out_char_nf(c int32) int32 {
	out_buf.Set(int(out_pos), byte(uint32(c)))
	out_pos++

	if out_pos >= OUT_SIZE {
		out_flush()
	}
	return int32(uint32(c))
}

func out_str_nf(s Ptr[byte]) {
	if out_pos > OUT_SIZE-MAX_ESC_SEQ_LEN {
		out_flush()
	}

	for p := s; p.Get() != NUL; p = p.Add(1) {
		out_char_nf(int32(p.Get()))
	}

	if p_wd != 0 {
		out_flush()
	}
}

func out_str_cf(s Ptr[byte]) {
	if s.Nil() || s.Get() == NUL {
		return
	}

	if out_pos > OUT_SIZE-MAX_ESC_SEQ_LEN {
		out_flush()
	}
	for s.Get() != 0 {
		c := s.Get()
		s = s.Add(1)
		out_char_nf(int32(c))
	}

	if p_wd != 0 {
		out_flush()
	}
}

func out_str(s Ptr[byte]) {
	if s.Nil() || s.Get() == NUL {
		return
	}

	if out_pos > OUT_SIZE-MAX_ESC_SEQ_LEN {
		out_flush()
	}
	for s.Get() != 0 {
		c := s.Get()
		s = s.Add(1)
		out_char_nf(int32(c))
	}

	if p_wd != 0 {
		out_flush()
	}
}

func term_windgoto(row int32, col int32) {
	out_str(tgoto(term_strings[KS_CM], col, row))
}

func term_cursor_right(i int32) {
	out_str(tgoto(term_strings[KS_CRI], 0, i))
}

func term_append_lines(line_count int32) {
	out_str(tgoto(term_strings[KS_CAL], 0, line_count))
}

func term_delete_lines(line_count int32) {
	out_str(tgoto(term_strings[KS_CDL], 0, line_count))
}

func term_set_winsize(height int32, width int32) {
	out_str(tgoto(term_strings[KS_CWS], width, height))
}

func term_font(n int32) {
	if term_strings[KS_CF].Get() != 0 {
		buf := Mk[byte](20)
		vim_snprintf(buf, 20, term_strings[KS_CF], 9+n)
		out_str(buf)
	}
}

func term_color(s Ptr[byte], n int32) {
	var buf Ptr[byte] = Mk[byte](20)
	var i int32
	var cond bool

	if s.Get() == CSI {
		i = 1
	} else {
		i = 2
	}

	// C: the test assigns i = 1 inside its short-circuit; split out in order.
	if n >= 8 && t_colors >= 16 {
		lead_ok := false
		if s.At(0) == ESC && s.At(1) == '[' {
			lead_ok = true
		} else if s.At(0) == CSI {
			i = 1
			lead_ok = true
		}
		if lead_ok && s.At(int(i)) != NUL && (musl_strcmp(s.Add(int(i+1)), S("%p1%dm")) == 0 || musl_strcmp(s.Add(int(i+1)), S("%dm")) == 0) && (s.At(int(i)) == '3' || s.At(int(i)) == '4') {
			cond = true
		}
	}
	if cond {
		var format Ptr[byte] = S("%s%s%%dm")
		var lead Ptr[byte]
		var tail Ptr[byte]
		var arg int32
		if i == 2 {
			lead = S("\033[")
		} else {
			lead = S("\233")
		}
		if s.At(int(i)) == '3' {
			if n >= 16 {
				tail = S("38;5;")
			} else {
				tail = S("9")
			}
		} else {
			if n >= 16 {
				tail = S("48;5;")
			} else {
				tail = S("10")
			}
		}

		vim_snprintf(buf, 20, format, lead, tail)
		if n >= 16 {
			arg = n
		} else {
			arg = n - 8
		}
		out_str(tgoto(buf, 0, arg))
	} else {
		out_str(tgoto(s, 0, n))
	}
}

