func clear_termcodes() {
	for tc_len > 0 {
		tc_len--
	}
	termcodes = Ptr[S_termcode]{}
	tc_max_len = 0

	need_gather = TRUE
}

func adjust_modlen(idx int32) {
	var j int32
	termcodes.Ref(int(idx)).modlen = 0
	j = termcode_star(termcodes.Ref(int(idx)).code, termcodes.Ref(int(idx)).len_)
	if j <= 0 {
		return
	}

	termcodes.Ref(int(idx)).modlen = termcodes.Ref(int(idx)).len_ - 1 - j
	if termcodes.Ref(int(idx)).code.At(int(termcodes.Ref(int(idx)).modlen-1)) == '@' {
		termcodes.Ref(int(idx)).modlen--
	}
}

func add_termcode(name Ptr[byte], string_ Ptr[byte], flags int32) {
	var new_tc Ptr[S_termcode]
	var i int32
	var j int32
	var s Ptr[byte]
	var len_ int32

	if string_.Nil() || string_.Get() == NUL {
		del_termcode(name)
		return
	}

	s = vim_strsave(string_)
	if s.Nil() {
		return
	}

	if flags != 0 && flags != ATC_FROM_TERM && term_7to8bit(string_) != 0 {
		Memmove(s, s.Add(1), int(musl_strlen(s.Add(1))+1))
		s.Set(0, byte(term_7to8bit(string_)))
	}

	len_ = int32(musl_strlen(s))

	need_gather = TRUE

	if tc_len == tc_max_len {
		tc_max_len += 20
		new_tc = Mk[S_termcode](int(tc_max_len))
		for i = 0; i < tc_len; i++ {
			new_tc.Set(int(i), termcodes.At(int(i)))
		}
		termcodes = new_tc
	}

	for i = 0; i < tc_len; i++ {
		if termcodes.Ref(int(i)).name[0] < name.At(0) {
			continue
		}
		if termcodes.Ref(int(i)).name[0] == name.At(0) {
			if termcodes.Ref(int(i)).name[1] < name.At(1) {
				continue
			}
			if termcodes.Ref(int(i)).name[1] == name.At(1) {
				star := false
				if flags == ATC_FROM_TERM {
					j = termcode_star(termcodes.Ref(int(i)).code, termcodes.Ref(int(i)).len_)
					star = j > 0
				}
				if star {
					if len_ == termcodes.Ref(int(i)).len_-j && musl_strncmp(s, termcodes.Ref(int(i)).code, usize(len_-1)) == 0 && s.At(int(len_-1)) == termcodes.Ref(int(i)).code.At(int(termcodes.Ref(int(i)).len_-1)) {
						return
					}
				} else {
					tc_len--
					break
				}
			}
		}
		for j = tc_len; j > i; j-- {
			termcodes.Set(int(j), termcodes.At(int(j-1)))
		}
		break
	}

	termcodes.Ref(int(i)).name[0] = name.At(0)
	termcodes.Ref(int(i)).name[1] = name.At(1)
	termcodes.Ref(int(i)).code = s
	termcodes.Ref(int(i)).len_ = len_
	adjust_modlen(i)

	tc_len++
}

func accept_modifiers_for_function_keys() {
	var regmatch regmatch_T
	regmatch = regmatch_T{}
	regmatch.rm_ic = TRUE
	regmatch.regprog = vim_regcomp(S("^\033[\\d\\+\\~$"), RE_MAGIC)

	for i := int32(0); i < tc_len; i++ {
		if regmatch.regprog == nil {
			return
		}

		if termcodes.Ref(int(i)).name[0] == 'P' && (termcodes.Ref(int(i)).name[1] == 'S' || termcodes.Ref(int(i)).name[1] == 'E') {
			continue
		}

		s := termcodes.Ref(int(i)).code
		if !s.Nil() && vim_regexec(&regmatch, s, colnr_T(0)) != 0 {
			len_ := musl_strlen(s)
			ns := Alloc(int(len_ + 3))
			if !ns.Nil() {
				Memmove(ns, s, int(len_-1))
				Memmove(ns.Add(int(len_-1)), S(";*~"), 4)
				termcodes.Ref(int(i)).code = ns
				termcodes.Ref(int(i)).len_ += 2
				adjust_modlen(i)
			}
		}
	}

	vim_regfree(regmatch.regprog)
}

func termcode_star(code Ptr[byte], len_ int32) int32 {
	if len_ >= 3 && code.At(int(len_-2)) == '*' {
		if len_ >= 5 && code.At(int(len_-3)) == ';' {
			return 2
		} else {
			return 1
		}
	}
	return 0
}

func find_termcode(name Ptr[byte]) Ptr[byte] {
	var i int32

	for i = 0; i < tc_len; i++ {
		if termcodes.Ref(int(i)).name[0] == name.At(0) && termcodes.Ref(int(i)).name[1] == name.At(1) {
			return termcodes.Ref(int(i)).code
		}
	}
	return Ptr[byte]{}
}

func del_termcode(name Ptr[byte]) {
	var i int32

	if termcodes.Nil() {
		return
	}

	need_gather = TRUE

	for i = 0; i < tc_len; i++ {
		if termcodes.Ref(int(i)).name[0] == name.At(0) && termcodes.Ref(int(i)).name[1] == name.At(1) {
			del_termcode_idx(i)
			return
		}
	}
}

func del_termcode_idx(idx int32) {
	var i int32

	tc_len--
	for i = idx; i < tc_len; i++ {
		termcodes.Set(int(i), termcodes.At(int(i+1)))
	}
}

func switch_to_8bit() {
	var i int32
	var c int32

	if term_is_8bit(term_strings[KS_NAME]) == 0 {
		for i = 0; i < tc_len; i++ {
			c = term_7to8bit(termcodes.Ref(int(i)).code)
			if c != 0 {
				code := termcodes.Ref(int(i)).code
				Memmove(code.Add(1), code.Add(2), int(musl_strlen(code.Add(2))+1))
				code.Set(0, byte(c))
			}
		}
		need_gather = TRUE
	}
	detected_8bit = TRUE
}

func put_string_in_typebuf(offset int32, slen int32, string_ Ptr[byte], new_slen int32, buf Ptr[byte], bufsize int32, buflen *int32) int32 {
	var extra int32 = new_slen - slen

	string_.Set(int(new_slen), NUL)
	if buf.Nil() {
		if extra < 0 {
			del_typebuf(-extra, offset)
		} else if extra > 0 {
			if ins_typebuf(string_.Add(int(slen)), REMAP_YES, offset, FALSE, FALSE) == FAIL {
				return FAIL
			}
		}

		Memmove(typebuf.tb_buf.Add(int(typebuf.tb_off+offset)), string_, int(usize(new_slen)))
	} else {
		if extra < 0 {
			Memmove(buf.Add(int(offset)), buf.Add(int(offset-extra)), int(usize(*buflen+offset+extra)))
		} else if extra > 0 {
			if *buflen+extra+new_slen >= bufsize {
				return FAIL
			}
			Memmove(buf.Add(int(offset+extra)), buf.Add(int(offset)), int(usize(*buflen-offset)))
		}
		Memmove(buf.Add(int(offset)), string_, int(usize(new_slen)))
		*buflen = *buflen + extra + new_slen
	}
	return OK
}

func decode_modifiers(n int32) int32 {
	var code int32 = n - 1
	var modifiers int32 = 0

	if code&1 != 0 {
		modifiers |= MOD_MASK_SHIFT
	}
	if code&2 != 0 {
		modifiers |= MOD_MASK_ALT
	}
	if code&4 != 0 {
		modifiers |= MOD_MASK_CTRL
	}
	if code&8 != 0 {
		modifiers |= MOD_MASK_META
	}

	return modifiers
}

func modifiers2keycode(modifiers int32, key *int32, string_ Ptr[byte]) int32 {
	var new_slen int32 = 0

	if modifiers == 0 {
		return 0
	}

	*key = simplify_key(*key, &modifiers)
	if modifiers != 0 {
		string_.Set(int(new_slen), 0x80)
		new_slen++
		string_.Set(int(new_slen), byte(KS_MODIFIER))
		new_slen++
		string_.Set(int(new_slen), byte(modifiers))
		new_slen++
	}
	return new_slen
}

func handle_u7_response(arg Ptr[int32], tp Ptr[byte], csi_len int32) {
	if arg.At(0) == 2 && arg.At(1) >= 2 {
		var aw Ptr[byte]

		u7_status.tr_progress = STATUS_GOT
		did_cursorhold = TRUE
		if arg.At(1) == 2 {
			aw = S("single")
		} else if arg.At(1) == 3 {
			aw = S("double")
		}
		if !aw.Nil() && musl_strcmp(aw, p_ambw) != 0 {
			set_option_value_give_err(S("ambw"), 0, aw, 0)
			redraw_asap(UPD_CLEAR)
		}
	} else if arg.At(0) == 3 {
		var value int32

		xcc_status.tr_progress = STATUS_GOT

		if arg.At(1) == 1 {
			value = TPR_YES
		} else {
			value = TPR_NO
		}
		term_props[TPR_CURSOR_STYLE].tpr_status = value
		term_props[TPR_CURSOR_BLINK].tpr_status = value
	}
}

func handle_version_response(first int32, arg Ptr[int32], argc int32, tp Ptr[byte]) {
	var version int32 = arg.At(1)

	crv_status.tr_progress = STATUS_GOT
	did_cursorhold = TRUE

	init_term_props(FALSE)

	if tp.At(0) == CSI {
		switch_to_8bit()
	}

	if version > 20000 {
		version = 0
	}

	if first == '>' && argc == 3 {
		if arg.At(0) == 77 {
			term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
		}

		if (version == 100 || version == 115) && arg.At(0) == 0 && arg.At(2) == 0 {
			may_adjust_color_count(256)
			term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
		}

		if version == 95 {
			if arg.At(0) == 1 && arg.At(2) == 0 {
				term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
				term_props[TPR_DECRQM].tpr_status = TPR_NO
			} else if arg.At(0) == 0 && arg.At(2) == 0 {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
				term_props[TPR_DECRQM].tpr_status = TPR_YES
			} else if arg.At(0) == 0 && arg.At(2) == -1 {
				term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES
			}
		}

		if arg.At(0) == 83 {
			if arg.At(1) >= 40700 {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
			} else {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM
			}
		}

		if term_props[TPR_MOUSE].tpr_status == TPR_UNKNOWN {
			if version >= 277 {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
			} else if version >= 95 {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM2
			}
		}

		if arg.At(1) >= 2500 {
			term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES
		} else if version == 136 && arg.At(2) == 0 {
			term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES

			if arg.At(0) == 0 {
				term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
			}
		}

		if arg.At(0) == 1 && arg.At(1) >= 4000 && arg.At(1) <= 4009 {
			term_props[TPR_KITTY].tpr_status = TPR_YES
			term_props[TPR_KITTY].tpr_set_by_termresponse = TRUE

			term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
			term_props[TPR_DECRQM].tpr_status = TPR_YES
		}

		if arg.At(0) == 1 && version == 12700 && arg.At(2) == 0 {
			term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR
			term_props[TPR_DECRQM].tpr_status = TPR_YES
		}

		if arg.At(0) == 83 && arg.At(1) >= 30600 {
			term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO
			term_props[TPR_CURSOR_BLINK].tpr_status = TPR_NO
			term_props[TPR_DECRQM].tpr_status = TPR_NO
		}

		if version < 95 {
			term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES
		}

		if version < 279 {
			term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO
		}

		if term_props[TPR_UNDERLINE_RGB].tpr_status != TPR_YES && term_strings[KS_8U].Get() != NUL && option_was_set(S("t_8u")) == 0 {
			set_string_option_direct(S("t_8u"), -1, S(""), OPT_FREE, 0)
		}
	}
}

func add_key_to_buf(key int32, buf Ptr[byte]) int32 {
	var idx int32 = 0

	if key < 0 {
		buf.Set(int(idx), 0x80)
		idx++
		buf.Set(int(idx), byte((-key)&0xff))
		idx++
		buf.Set(int(idx), byte((uint32(-key)>>8)&0xff))
		idx++
	} else {
		idx += utf_char2bytes(key, buf.Add(int(idx)))
	}
	return idx
}

func put_key_modifiers_in_typebuf(key_arg int32, modifiers_arg int32, csi_len int32, offset int32, buf Ptr[byte], bufsize int32, buflen *int32) int32 {
	var key int32 = key_arg
	var modifiers int32 = modifiers_arg
	var string_ Ptr[byte]
	var new_slen int32

	key = may_adjust_key_for_ctrl(modifiers, key)

	modifiers = may_remove_shift_modifier(modifiers, key)

	string_ = Mk[byte](MAX_KEY_CODE_LEN + 2)
	new_slen = modifiers2keycode(modifiers, &key, string_)

	if key > 0x10FFFF {
		return -1
	}

	new_slen += add_key_to_buf(key, string_.Add(int(new_slen)))

	string_.Set(int(new_slen), NUL)
	if put_string_in_typebuf(offset, csi_len, string_, new_slen, buf, bufsize, buflen) == FAIL {
		return -1
	}
	return new_slen - csi_len + offset
}

func parse_csi_f_keys(arg int32) int32 {
	var key_name = [2]byte{0, 0}

	switch arg {
	case 11:
		key_name[0] = 'k'
		key_name[1] = '1'
	case 12:
		key_name[0] = 'k'
		key_name[1] = '2'
	case 13:
		key_name[0] = 'k'
		key_name[1] = '3'
	case 14:
		key_name[0] = 'k'
		key_name[1] = '4'
	case 15:
		key_name[0] = 'k'
		key_name[1] = '5'
	case 17:
		key_name[0] = 'k'
		key_name[1] = '6'
	case 18:
		key_name[0] = 'k'
		key_name[1] = '7'
	case 19:
		key_name[0] = 'k'
		key_name[1] = '8'
	case 20:
		key_name[0] = 'k'
		key_name[1] = '9'
	case 21:
		key_name[0] = 'F'
		key_name[1] = ';'
	case 23:
		key_name[0] = 'F'
		key_name[1] = '1'
	case 24:
		key_name[0] = 'F'
		key_name[1] = '2'
	}
	if key_name[0] != 0 {
		return -(int32(key_name[0]) + (int32(key_name[1]) << 8))
	}
	return arg
}

func handle_key_with_modifier(arg Ptr[int32], csi_len int32, offset int32, buf Ptr[byte], bufsize int32, buflen *int32, iskitty int32, trail int32) int32 {
	var key int32
	var modifiers int32

	if iskitty == 0 && (kitty_protocol_state == KKPS_INITIAL || kitty_protocol_state == KKPS_OFF || kitty_protocol_state == KKPS_AFTER_T_TE) && term_props[TPR_KITTY].tpr_status != TPR_YES {
		seenModifyOtherKeys = TRUE
	}

	if iskitty != 0 {
		key = arg.At(0)
	} else {
		key = arg.At(2)
	}
	modifiers = decode_modifiers(arg.At(1))

	if (modifiers&MOD_MASK_SHIFT) != 0 && key >= 'a' && key <= 'z' {
		key += 'A' - 'a'
	}

	if key == ESC {
		key = -(KS_EXTRA + (int32(KE_ESC) << 8))
	} else if arg.At(0) >= 11 && arg.At(0) <= 24 && trail == '~' {
		key = parse_csi_f_keys(arg.At(0))
	}

	return put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen)
}

func handle_key_without_modifier(arg Ptr[int32], csi_len int32, offset int32, buf Ptr[byte], bufsize int32, buflen *int32, trail int32) int32 {
	var string_ Ptr[byte] = Mk[byte](MAX_KEY_CODE_LEN + 1)
	var new_slen int32

	if arg.At(0) == ESC {
		string_.Set(0, 0x80)
		string_.Set(1, KS_EXTRA)
		string_.Set(2, KE_ESC)
		new_slen = 3
	} else if arg.At(0) >= 11 && arg.At(0) <= 24 && trail == '~' {
		key := parse_csi_f_keys(arg.At(0))
		string_.Set(0, 0x80)
		string_.Set(1, byte((-key)&0xff))
		string_.Set(2, byte((uint32(-key)>>8)&0xff))
		new_slen = 3
	} else {
		new_slen = add_key_to_buf(arg.At(0), string_)
	}

	if put_string_in_typebuf(offset, csi_len, string_, new_slen, buf, bufsize, buflen) == FAIL {
		return -1
	}
	return new_slen - csi_len + offset
}

func handle_csi_function_key(argc int32, arg Ptr[int32], trail int32, csi_len int32, key_name Ptr[byte], offset int32, buf Ptr[byte], bufsize int32, buflen *int32) int32 {
	var key int32
	var modifiers int32

	key_name.Set(0, 'k')
	switch trail {
	case 'A':
		key_name.Set(1, 'u')
	case 'B':
		key_name.Set(1, 'd')
	case 'C':
		key_name.Set(1, 'r')
	case 'D':
		key_name.Set(1, 'l')

	case 'F':
		key_name.Set(0, '@')
		key_name.Set(1, '7')
	case 'H':
		key_name.Set(1, 'h')

	case 'P':
		key_name.Set(1, '1')
	case 'Q':
		key_name.Set(1, '2')
	case 'R':
		key_name.Set(1, '3')
	case 'S':
		key_name.Set(1, '4')

	default:
		return 0
	}

	key = -(int32(key_name.At(0)) + (int32(key_name.At(1)) << 8))
	if argc == 2 {
		modifiers = decode_modifiers(arg.At(1))
	} else {
		modifiers = 0
	}
	put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen)
	return csi_len
}

func handle_csi(tp Ptr[byte], len_ int32, argp Ptr[byte], offset int32, buf Ptr[byte], bufsize int32, buflen *int32, key_name Ptr[byte], slen *int32) int32 {
	var first int32 = -1
	var trail int32
	var arg Ptr[int32] = Mk[int32](3)
	var argc int32 = 0
	var ap Ptr[byte] = argp
	var csi_len int32

	arg.Set(0, -1)
	arg.Set(1, -1)
	arg.Set(2, -1)

	if !(uint32(ap.Get())-'0' < 10) {
		first = int32(ap.Get())
		ap = ap.Add(1)
	}

	if first >= 'A' && first <= 'Z' {
		trail = first
		first = -1
		ap = ap.Add(-1)
	} else {
		for argc = 0; argc < 3; {
			if ap.Ge(tp.Add(int(len_))) {
				return -1
			}
			if ap.Get() == ';' {
				arg.Set(int(argc), -1)
				argc++
			} else if uint32(ap.Get())-'0' < 10 {
				arg.Set(int(argc), 0)
				for {
					if ap.Ge(tp.Add(int(len_))) {
						return -1
					}
					if !(uint32(ap.Get())-'0' < 10) {
						break
					}
					if arg.At(int(argc)) <= (INT_MAX-9)/10 {
						arg.Set(int(argc), arg.At(int(argc))*10+(int32(ap.Get())-'0'))
					}
					ap = ap.Add(1)
				}
				argc++
			}
			if ap.Get() == ';' {
				ap = ap.Add(1)
			} else {
				break
			}
		}

		for ap.Lt(tp.Add(int(len_))) && !(ap.Get() >= '{' && ap.Get() <= '~') && !(uint32(ap.Get())-'A' < 26 || uint32(ap.Get())-'a' < 26) {
			ap = ap.Add(1)
		}
		if ap.Ge(tp.Add(int(len_))) {
			return -1
		}
		trail = int32(ap.Get())
	}

	csi_len = int32(ap.Sub(tp)) + 1

	if first == '>' && (argc == 1 || argc == 2) && trail == 'm' {
		if arg.At(0) == 4 && argc == 2 {
			if arg.At(1) == 2 {
				modify_otherkeys_state = MOKS_ENABLED
			} else {
				modify_otherkeys_state = MOKS_OFF
			}
		}

		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
		*slen = csi_len
	} else if first == -1 && uint32(trail)-'A' < 26 && (argc == 0 || (argc == 2 && arg.At(0) == 1)) {
		res := handle_csi_function_key(argc, arg, trail, csi_len, key_name, offset, buf, bufsize, buflen)
		if res <= 0 {
			return res
		}
		return len_ + res
	} else if first == -1 && argc == 2 && trail == 'R' {
		handle_u7_response(arg, tp, csi_len)

		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
		*slen = csi_len
	} else if first == '?' && trail == 'c' {
		*slen = csi_len

		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
	} else if first == '?' && trail == 'y' && argc == 2 && arg.At(0) == 2026 {
		setting := arg.At(1)

		*slen = csi_len
		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))

		if setting >= 0 && setting <= 4 {
			switch arg.At(0) {
			case 2026:
				sync_output_setting = setting
				set_option_value_give_err(S("termsync"), int64(B2i(setting == 1 || setting == 2)), Ptr[byte]{}, 0)
			}
		}
	} else if first == '?' && argc == 1 && arg.At(0) == 1 && trail == 'z' {
		*slen = csi_len
		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
		do_cmdline_cmd(S("stop"))
	} else if argc >= 3 && arg.At(0) == 48 {
		height := arg.At(1)
		width := arg.At(2)

		*slen = csi_len
		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))

		set_shellsize(width, height, TRUE)
	} else if term_strings[KS_CRV].Get() != NUL && ap.Gt(argp.Add(1)) && trail == 'c' {
		handle_version_response(first, arg, argc, tp)

		*slen = csi_len
		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
	} else if first == '?' && argc == 1 && trail == 'u' {
		if arg.At(0) == '0' {
			kitty_protocol_state = KKPS_OFF
		} else {
			kitty_protocol_state = KKPS_ENABLED

			seenModifyOtherKeys = FALSE
		}

		key_name.Set(0, byte(KS_EXTRA))
		key_name.Set(1, byte(KE_IGNORE))
		*slen = csi_len
	} else if (arg.At(0) == 27 && argc == 3 && trail == '~') || (argc == 2 && (trail == 'u' || trail == '~')) {
		iskitty := B2i(argc == 2 && (trail == 'u' || trail == '~'))
		return len_ + handle_key_with_modifier(arg, csi_len, offset, buf, bufsize, buflen, iskitty, trail)
	} else if argc == 1 && (trail == 'u' || trail == '~') {
		return len_ + handle_key_without_modifier(arg, csi_len, offset, buf, bufsize, buflen, trail)
	}

	return 0
}

func check_for_color_response(resp Ptr[byte], len_ int32) {
	var i int32
	var j int32
	var argp Ptr[byte]

	j = 1 + B2i(resp.At(0) == ESC)
	argp = resp.Add(int(j))

	if len_ >= j+3 && (argp.At(0) != '1' || (argp.At(1) != '1' && argp.At(1) != '0') || argp.At(2) != ';') {
		i = 0
	} else {
		for i = j; i < len_; i++ {
			var ends bool
			if resp.At(int(i)) == '\007' {
				ends = true
			} else if resp.At(0) == OSC {
				ends = resp.At(int(i)) == STERM
			} else {
				ends = resp.At(int(i)) == ESC && i+1 < len_ && resp.At(int(i+1)) == '\\'
			}
			if ends {
				is_bg := B2i(argp.At(1) == '1')
				is_4digit := B2i(i-j >= 21 && resp.At(int(j+11)) == '/' && resp.At(int(j+16)) == '/')

				if i-j >= 15 && musl_strncmp(resp.Add(int(j+3)), S("rgb:"), 4) == 0 && (is_4digit != 0 || (resp.At(int(j+9)) == '/' && resp.At(int(j+12)) == '/')) {
					tp_r := resp.Add(int(j + 7))
					var tp_g, tp_b Ptr[byte]
					if is_4digit != 0 {
						tp_g = resp.Add(int(j + 12))
						tp_b = resp.Add(int(j + 17))
					} else {
						tp_g = resp.Add(int(j + 10))
						tp_b = resp.Add(int(j + 13))
					}
					if is_bg != 0 {
						var new_bg_val Ptr[byte]
						if 3*'6' < int32(tp_r.Get())+int32(tp_g.Get())+int32(tp_b.Get()) {
							new_bg_val = S("light")
						} else {
							new_bg_val = S("dark")
						}

						if option_was_set(S("bg")) == 0 && musl_strcmp(p_bg, new_bg_val) != 0 {
							set_option_value_give_err(S("bg"), 0, new_bg_val, 0)
							reset_option_was_set(S("bg"))
							redraw_asap(UPD_CLEAR)
						}
					}
				}

				break
			}
		}
	}
}

func in_osc_sequence() bool {
	return osc_state.processing != 0
}

func handle_osc(tp Ptr[byte], len_ int32, key_name Ptr[byte], slen *int32) int32 {
	var last_char byte

	if osc_state.processing == 0 {
		var cur int32

		cur = 1 + B2i(tp.At(0) == ESC)

		if len_ < cur+1+B2i(tp.At(0) != OSC) {
			return FAIL
		}

		ga_init2(&osc_state.buf, 1, 1024)
		osc_state.start_tv = musl_now_ms()
		osc_state.processing = TRUE
		osc_state.start_char = tp.At(0)
		last_char = 0
	} else {
		last_char = GaData[byte](&osc_state.buf).At(int(osc_state.buf.ga_len - 1))
	}

	key_name.Set(0, byte(KS_EXTRA))

	for i := int32(0); i < len_; i++ {
		var ends bool
		if tp.At(int(i)) == '\007' {
			ends = true
		} else if osc_state.start_char == OSC {
			ends = tp.At(int(i)) == STERM
		} else {
			ends = (tp.At(int(i)) == ESC && i+1 < len_ && tp.At(int(i+1)) == '\\') || (i == 0 && tp.At(int(i)) == '\\' && last_char == ESC)
		}
		if ends {
			osc_state.processing = FALSE

			key_name.Set(1, byte(KE_OSC))

			ga_concat_len(&osc_state.buf, tp, usize(i+1+B2i(tp.At(int(i)) == ESC)))
			ga_append(&osc_state.buf, NUL)
			*slen = i + 1 + B2i(tp.At(int(i)) == ESC)
			check_for_color_response(GaData[byte](&osc_state.buf), osc_state.buf.ga_len-1)

			savebg := p_bg.Get()
			if p_bg.Get() != savebg {
				redraw_asap(UPD_CLEAR)
			}
			return OK
		}
	}

	key_name.Set(1, byte(KE_IGNORE))

	if musl_now_ms()-osc_state.start_tv >= p_ost {
		vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(e_osc_response_timed_out), osc_state.buf.ga_len, GaData[byte](&osc_state.buf))
		emsg(iobuff_or(gettext_(e_osc_response_timed_out)))

		ga_clear(&osc_state.buf)
		osc_state.processing = FALSE
		return FAIL
	}

	ga_concat(&osc_state.buf, tp)
	*slen = len_

	return OK
}

func handle_dcs(tp Ptr[byte], argp Ptr[byte], len_ int32, key_name Ptr[byte], slen *int32) int32 {
	var i int32
	var j int32

	j = 1 + B2i(tp.At(0) == ESC)
	if len_ < j+3 {
		i = len_
	} else if (argp.At(1) != '+' && argp.At(1) != '$') || (argp.At(2) != 'r' && argp.At(2) != 'R') {
		i = 0
	} else if argp.At(1) == '+' {
		for i = j; i < len_; i++ {
			if (tp.At(int(i)) == ESC && i+1 < len_ && tp.At(int(i+1)) == '\\') || tp.At(int(i)) == STERM {
				key_name.Set(0, byte(KS_EXTRA))
				key_name.Set(1, byte(KE_IGNORE))
				*slen = i + 1 + B2i(tp.At(int(i)) == ESC)
				break
			}
		}
	} else {
		for i = j + 3; i < len_; i++ {
			if i-j == 3 && musl_isdigit(int32(tp.At(int(i)))) == 0 {
				break
			}
			if i-j == 4 && tp.At(int(i)) != ' ' {
				break
			}
			if i-j == 5 && tp.At(int(i)) != 'q' {
				break
			}
			if i-j == 6 && tp.At(int(i)) != ESC && tp.At(int(i)) != STERM {
				break
			}
			if (i-j == 6 && tp.At(int(i)) == STERM) || (i-j == 7 && tp.At(int(i)) == '\\') {
				key_name.Set(0, byte(KS_EXTRA))
				key_name.Set(1, byte(KE_IGNORE))
				*slen = i + 1
				break
			}
		}
	}

	if i == len_ {
		return FAIL
	}
	return OK
}

func check_termcode(max_offset int32, buf Ptr[byte], bufsize int32, buflen *int32) int32 {
	var tp Ptr[byte]
	var p Ptr[byte]
	var slen int32 = 0
	var modslen int32
	var len_ int32
	var retval int32 = 0
	var offset int32
	var key_name Ptr[byte] = Mk[byte](2)
	var modifiers int32
	var modifiers_start Ptr[byte]
	var key int32
	var new_slen int32
	var string_ Ptr[byte] = Mk[byte](MAX_KEY_CODE_LEN + 1)
	var i int32
	var j int32
	var idx int32 = 0
	var cpo_koffset int32

	cpo_koffset = B2i(!vim_strchr(p_cpo, CPO_KOFFSET).Nil())

	if need_gather != 0 {
		gather_termleader()
	}

	for offset = 0; offset < max_offset; offset++ {
		if buf.Nil() {
			if offset >= typebuf.tb_len {
				break
			}
			tp = typebuf.tb_buf.Add(int(typebuf.tb_off + offset))
			len_ = typebuf.tb_len - offset
		} else {
			if offset >= *buflen {
				break
			}
			tp = buf.Add(int(offset))
			len_ = *buflen - offset
		}

		if tp.Get() == 0x80 {
			offset += 2
			continue
		}

		if osc_state.processing != 0 {
			tp.Set(int(len_), NUL)
			key_name.Set(0, NUL)
			key_name.Set(1, NUL)
			modifiers = 0
			if handle_osc(tp, len_, key_name, &slen) == FAIL {
				return -1
			}
		} else {
			i = int32(tp.Get())
			for p = termleader; p.Get() != 0 && int32(p.Get()) != i; p = p.Add(1) {
			}
			if p.Get() == NUL {
				continue
			}

			if tp.Get() == ESC && p_ek == 0 && (State&MODE_INSERT) != 0 {
				continue
			}

			tp.Set(int(len_), NUL)
			key_name.Set(0, NUL)
			key_name.Set(1, NUL)
			modifiers = 0

			{
				keypad_index_found := int32(-1)
				keypad_slen_found := int32(0)

				for idx = 0; idx < tc_len; idx++ {
					is_keypad := int32(FALSE)
					tc := termcodes.Ref(int(idx))
					slen = tc.len_
					modifiers_start = Ptr[byte]{}
					if cpo_koffset != 0 && offset != 0 && len_ < slen {
						continue
					}
					cmplen := slen
					if slen > len_ {
						cmplen = len_
					}
					if musl_strncmp(tc.code, tp, usize(cmplen)) == 0 {
						if len_ < slen {
							return -1
						}

						if tc.name[0] == 'K' && (uint32(tc.name[1])-'0' < 10 || uint32(tc.name[1])-'A' < 26) {
							is_keypad = TRUE
							if keypad_index_found < 0 {
								keypad_index_found = idx
								keypad_slen_found = slen
							}
						}

						if is_keypad == 0 {
							key_name.Set(0, tc.name[0])
							key_name.Set(1, tc.name[1])
							break
						}
					}

					if tc.modlen > 0 {
						modslen = tc.modlen
						if cpo_koffset != 0 && offset != 0 && len_ < modslen {
							continue
						}
						cmplen = modslen
						if modslen > len_ {
							cmplen = len_
						}
						if musl_strncmp(tc.code, tp, usize(cmplen)) == 0 {
							var n int32

							if len_ <= modslen {
								return -1
							}

							if tp.At(int(modslen)) == tc.code.At(int(slen-1)) {
								slen = modslen + 1
							} else if tp.At(int(modslen)) != ';' && modslen == slen-3 {
								continue
							} else if tc.code.At(int(modslen)) == '@' && (tp.At(int(modslen)) != '1' || tp.At(int(modslen+1)) != ';') {
								continue
							} else {
								for j = slen - 2; j < len_ && (musl_isdigit(int32(tp.At(int(j)))) != 0 || tp.At(int(j)) == '-' || tp.At(int(j)) == ';'); j++ {
								}
								j++
								if len_ < j {
									return -1
								}
								if tp.At(int(j-1)) != tc.code.At(int(slen-1)) {
									continue
								}

								modifiers_start = tp.Add(int(slen - 2))

								n = musl_atoi(modifiers_start)
								modifiers |= decode_modifiers(n)

								slen = j
							}
							if tc.name[0] == 'K' && (uint32(tc.name[1])-'0' < 10 || uint32(tc.name[1])-'A' < 26) {
								is_keypad = TRUE
								if keypad_index_found < 0 {
									keypad_index_found = idx
									keypad_slen_found = slen
								}
							}
							if is_keypad == 0 {
								key_name.Set(0, tc.name[0])
								key_name.Set(1, tc.name[1])
								break
							}
						}
					}
				}
				if idx == tc_len && keypad_index_found >= 0 {
					key_name.Set(0, termcodes.Ref(int(keypad_index_found)).name[0])
					key_name.Set(1, termcodes.Ref(int(keypad_index_found)).name[1])
					slen = keypad_slen_found
				}
			}

			if key_name.At(0) == NUL {
				var argp Ptr[byte]
				if tp.At(0) == ESC {
					argp = tp.Add(2)
				} else {
					argp = tp.Add(1)
				}

				if ((tp.At(0) == ESC && len_ >= 3 && tp.At(1) == '[') || (tp.At(0) == CSI && len_ >= 2)) && !vim_strchr(S("0123456789>?ABCDEFHPQRS"), int32(argp.Get())).Nil() {
					resp := handle_csi(tp, len_, argp, offset, buf, bufsize, buflen, key_name, &slen)
					if resp != 0 {
						return resp
					}
				} else if (tp.At(0) == ESC && len_ >= 2 && tp.At(1) == ']') || tp.At(0) == OSC {
					if handle_osc(tp, len_, key_name, &slen) == FAIL {
						return -1
					}
				} else if (tp.At(0) == ESC && len_ >= 2 && tp.At(1) == 'P') || tp.At(0) == DCS {
					if handle_dcs(tp, argp, len_, key_name, &slen) == FAIL {
						return -1
					}
				}
			}
		}

		if key_name.At(0) == NUL {
			continue
		}

		if key_name.At(0) == KS_EXTRA {
			if key_name.At(1) == KE_FOCUSGAINED {
				if focus_state == 0 {
					ui_focus_change(TRUE)
					did_cursorhold = TRUE
					focus_state = TRUE
				}
				key_name.Set(1, byte(KE_IGNORE))
			} else if key_name.At(1) == KE_FOCUSLOST {
				if focus_state != 0 {
					ui_focus_change(FALSE)
					did_cursorhold = TRUE
					focus_state = FALSE
				}
				key_name.Set(1, byte(KE_IGNORE))
			}
		}

		key = handle_x_keys(-(int32(key_name.At(0)) + (int32(key_name.At(1)) << 8)))

		new_slen = modifiers2keycode(modifiers, &key, string_)

		key_name.Set(0, byte((-key)&0xff))
		key_name.Set(1, byte((uint32(-key)>>8)&0xff))
		if key_name.At(0) == KS_KEY {
			new_slen += utf_char2bytes(int32(key_name.At(1)), string_.Add(int(new_slen)))
		} else if osc_state.processing != 0 || (new_slen == 0 && key_name.At(0) == KS_EXTRA && key_name.At(1) == KE_IGNORE) {
			retval = KEYLEN_REMOVED
		} else {
			string_.Set(int(new_slen), 0x80)
			new_slen++
			string_.Set(int(new_slen), key_name.At(0))
			new_slen++
			string_.Set(int(new_slen), key_name.At(1))
			new_slen++
		}
		if put_string_in_typebuf(offset, slen, string_, new_slen, buf, bufsize, buflen) == FAIL {
			return -1
		}
		if retval == 0 {
			return len_ + new_slen - slen + offset
		}
		return retval
	}

	return 0
}

func replace_termcodes(from Ptr[byte], bufp *Ptr[byte], sid_arg scid_T, flags int32, did_simplify *int32) Ptr[byte] {
	var i int32
	var slen int32
	var key int32
	var dlen usize = 0
	var src Ptr[byte]
	var do_backslash int32
	var do_special int32
	var do_key_code int32
	var result Ptr[byte]
	var ga garray_T

	do_backslash = B2i(vim_strchr(p_cpo, CPO_BSLASH).Nil())
	do_special = B2i(vim_strchr(p_cpo, CPO_SPECI).Nil() || (flags&REPTERM_SPECIAL) != 0)
	do_key_code = B2i(vim_strchr(p_cpo, CPO_KEYCODE).Nil())
	src = from

	ga_init2(&ga, 1, 100)
	if ga_grow(&ga, int32(musl_strlen(src)*6+1)) == FAIL {
		*bufp = Ptr[byte]{}
		return from
	}
	result = GaData[byte](&ga)

	if (flags&REPTERM_FROM_PART) != 0 && src.At(0) == '#' && uint32(src.At(1))-'0' < 10 {
		result.Set(int(dlen), 0x80)
		dlen++
		result.Set(int(dlen), 'k')
		dlen++
		if src.At(1) == '0' {
			result.Set(int(dlen), ';')
			dlen++
		} else {
			result.Set(int(dlen), src.At(1))
			dlen++
		}
		src = src.Add(2)
	}

	for src.Get() != NUL {
		if do_special != 0 && ((flags&REPTERM_DO_LT) != 0 || musl_strncmp(src, S("<lt>"), 4) != 0) {
			var fsk_flags int32 = FSK_KEYCODE
			if (flags & REPTERM_NO_SIMPLIFY) == 0 {
				fsk_flags |= FSK_SIMPLIFY
			}
			if (flags & REPTERM_FROM_PART) != 0 {
				fsk_flags |= FSK_FROM_PART
			}
			slen = trans_special(&src, result.Add(int(dlen)), fsk_flags, TRUE, did_simplify)
			if slen > 0 {
				dlen += usize(slen)
				continue
			}
		}

		if do_key_code != 0 {
			var len_ int32
			i = find_term_bykeys(src, &len_)
			if i >= 0 {
				result.Set(int(dlen), 0x80)
				dlen++
				result.Set(int(dlen), termcodes.Ref(int(i)).name[0])
				dlen++
				result.Set(int(dlen), termcodes.Ref(int(i)).name[1])
				dlen++
				src = src.Add(int(len_))
				continue
			}
		}

		key = int32(src.Get())
		if key == Ctrl_V || (do_backslash != 0 && key == '\\') {
			src = src.Add(1)
			if src.Get() == NUL {
				if (flags & REPTERM_FROM_PART) != 0 {
					result.Set(int(dlen), byte(key))
					dlen++
				}
				break
			}
		}

		for i = utfc_ptr2len(src); i > 0; i-- {
			if src.Get() == 0x80 {
				result.Set(int(dlen), 0x80)
				dlen++
				result.Set(int(dlen), KS_SPECIAL)
				dlen++
				result.Set(int(dlen), 'X')
				dlen++
			} else {
				result.Set(int(dlen), src.Get())
				dlen++
			}
			src = src.Add(1)
		}
	}
	result.Set(int(dlen), NUL)

	*bufp = vim_strsave(result)
	if !(*bufp).Nil() {
		from = *bufp
	}
	return from
}

func find_term_bykeys(src Ptr[byte], matchlen *int32) int32 {
	var i int32
	var j int32
	var len_ int32 = int32(musl_strlen(src))
	var found int32 = -1
	var foundlen int32 = 1
	var slen int32
	var modslen int32
	var thislen int32

	if need_gather != 0 {
		gather_termleader()
	}
	if src.Get() == NUL || vim_strchr(termleader, int32(src.Get())).Nil() {
		return -1
	}

	for i = 0; i < tc_len; i++ {
		tc := termcodes.Ref(int(i))
		slen = tc.len_
		modslen = tc.modlen

		if modslen > 0 {
			if len_ > modslen && musl_strncmp(tc.code, src, usize(modslen)) == 0 {
				thislen = 0

				if src.At(int(modslen)) == tc.code.At(int(slen-1)) {
					thislen = modslen + 1
				} else if src.At(int(modslen)) != ';' && modslen == slen-3 {
					continue
				} else if tc.code.At(int(modslen)) == '@' && (src.At(int(modslen)) != '1' || src.At(int(modslen+1)) != ';') {
					continue
				} else {
					for j = slen - 2; j < len_ && (musl_isdigit(int32(src.At(int(j)))) != 0 || src.At(int(j)) == '-' || src.At(int(j)) == ';'); j++ {
					}
					j++
					if len_ < j {
						continue
					}
					if src.At(int(j-1)) != tc.code.At(int(slen-1)) {
						continue
					}

					thislen = j
				}

				if thislen > foundlen {
					found = i
					foundlen = thislen
				}
			}
		} else {
			if slen > foundlen && len_ >= slen && musl_strncmp(tc.code, src, usize(slen)) == 0 {
				found = i
				foundlen = slen
			}
		}
	}

	if matchlen != nil && found >= 0 {
		*matchlen = foundlen
	}

	return found
}

func gather_termleader() {
	var i int32
	var len_ int32 = 0

	termleader.Set(int(len_), NUL)

	for i = 0; i < tc_len; i++ {
		if vim_strchr(termleader, int32(termcodes.Ref(int(i)).code.At(0))).Nil() {
			termleader.Set(int(len_), termcodes.Ref(int(i)).code.At(0))
			len_++
			termleader.Set(int(len_), NUL)
		}
	}

	need_gather = FALSE
}

func show_termcodes(flags int32) {
	var col int32
	var items Ptr[int32]
	var item_count int32
	var run int32
	var row int32
	var rows int32
	var cols int32
	var i int32
	var len_ int32

	if tc_len == 0 {
		return
	}
	items = Mk[int32](int(tc_len))

	msg_puts_title(gettext_(S("\n--- Terminal keys ---")))

	if (flags & OPT_ONECOLUMN) != 0 {
		run = 3
	} else {
		run = 1
	}
	for ; run <= 3 && got_int == 0; run++ {
		item_count = 0
		for i = 0; i < tc_len; i++ {
			len_ = show_one_termcode(View(termcodes.Ref(int(i)).name[:]), termcodes.Ref(int(i)).code, FALSE)
			var sel bool
			if (flags & OPT_ONECOLUMN) != 0 {
				sel = true
			} else if len_ <= INC3-TERMCODE_GAP {
				sel = run == 1
			} else if len_ <= INC2-TERMCODE_GAP {
				sel = run == 2
			} else {
				sel = run == 3
			}
			if sel {
				items.Set(int(item_count), i)
				item_count++
			}
		}

		if run <= 2 {
			var inc int64
			if run == 1 {
				inc = INC3
			} else {
				inc = INC2
			}
			cols = int32((Columns + TERMCODE_GAP) / inc)
			if cols == 0 {
				cols = 1
			}
			rows = (item_count + cols - 1) / cols
		} else {
			rows = item_count
		}
		for row = 0; row < rows && got_int == 0; row++ {
			msg_putchar('\n')
			if got_int != 0 {
				break
			}
			col = 0
			for i = row; i < item_count; i += rows {
				msg_col = col
				show_one_termcode(View(termcodes.Ref(int(items.At(int(i)))).name[:]), termcodes.Ref(int(items.At(int(i)))).code, TRUE)
				if run == 2 {
					col += INC2
				} else {
					col += INC3
				}
			}
			out_flush()
			ui_breakcheck()
		}
	}
}

func show_one_termcode(name Ptr[byte], code Ptr[byte], printit int32) int32 {
	var p Ptr[byte]
	var len_ int32

	if name.At(0) > '~' {
		IObuff.Set(0, ' ')
		IObuff.Set(1, ' ')
		IObuff.Set(2, ' ')
		IObuff.Set(3, ' ')
	} else {
		IObuff.Set(0, 't')
		IObuff.Set(1, '_')
		IObuff.Set(2, name.At(0))
		IObuff.Set(3, name.At(1))
	}
	IObuff.Set(4, ' ')

	p = get_special_key_name(-(int32(name.At(0)) + (int32(name.At(1)) << 8)), 0)
	if p.At(1) != 't' {
		musl_strcpy(IObuff.Add(5), p)
	} else {
		IObuff.Set(5, NUL)
	}
	len_ = int32(musl_strlen(IObuff))
	for {
		IObuff.Set(int(len_), ' ')
		len_++
		if !(len_ < 17) {
			break
		}
	}
	IObuff.Set(int(len_), NUL)
	if code.Nil() {
		len_ += 4
	} else {
		len_ += vim_strsize(code)
	}

	if printit != 0 {
		msg_puts(IObuff)
		if code.Nil() {
			msg_puts(S("NULL"))
		} else {
			msg_outtrans(code)
		}
	}
	return len_
}

func term_disable_dec() {
	term_set_sync_output(TERM_SYNC_OUTPUT_OFF)
	out_flush()
}

func sync_output_active() int32 {
	return B2i(p_tsy != 0 && (sync_output_setting == 1 || sync_output_setting == 2) && term_strings[KS_BSU].Get() != NUL && term_strings[KS_ESU].Get() != NUL)
}

func term_set_sync_output(flags int32) {
	var allowed bool
	var in_gui bool = false

	allowed = p_tsy != 0 && (sync_output_setting == 1 || sync_output_setting == 2)

	if (flags & TERM_SYNC_OUTPUT_FLUSH) != 0 {
		if allowed && !in_gui && sync_output_state > 0 && term_strings[KS_ESU].Get() != NUL && term_strings[KS_BSU].Get() != NUL {
			out_str_nf(term_strings[KS_ESU])
			out_str_nf(term_strings[KS_BSU])
			out_flush()
		}
		return
	}

	if (flags & TERM_SYNC_OUTPUT_OFF) != 0 {
		if sync_output_state > 0 && term_strings[KS_ESU].Get() != NUL {
			out_str_nf(term_strings[KS_ESU])
			out_flush()
			sync_output_state = 0
		}
		return
	}

	if !allowed || in_gui || term_strings[KS_BSU].Get() == NUL || term_strings[KS_ESU].Get() == NUL {
		return
	}

	if (flags & TERM_SYNC_OUTPUT_ENABLE) != 0 {
		old := sync_output_state
		sync_output_state++
		if old > 0 {
			return
		}
		out_str_nf(term_strings[KS_BSU])
	} else if (flags & TERM_SYNC_OUTPUT_DISABLE) != 0 {
		if sync_output_state == 0 {
			return
		}
		sync_output_state--
		if sync_output_state > 0 {
			return
		}
		out_str_nf(term_strings[KS_ESU])
		out_flush()
	} else {
		vim_snprintf(IObuff, emsg_iobuff_room(), S("Unknown sync output value %d"), flags)
		iemsg(iobuff_or(S("Unknown sync output value %d")))
		return
	}
}

func internal_format(textwidth int32, second_indent int32, flags int32, format_only int32, c int32) {
	var cc int32
	var save_char int32 = NUL
	var haveto_redraw int32 = FALSE
	var safe_tw int32 = trim_to_int(8 * vimlong_T(textwidth))

	if curbuf.b_p_ai == 0 && (State&VREPLACE_FLAG) == 0 {
		cc = gchar_cursor()
		if cc == ' ' || cc == '\t' {
			save_char = cc
			pchar_cursor('x')
		}
	}

	for got_int == 0 {
		var startcol int32
		var wantcol int32
		var foundcol int32
		var end_foundcol int32 = 0
		var len_ colnr_T
		var virtcol colnr_T
		var orig_col int32 = 0
		var saved_text Ptr[byte]
		var end_col colnr_T
		var first_pass int32

		if curwin.w_cursor.col < safe_tw {
			var ch int32
			if c != NUL {
				ch = c
			} else {
				ch = gchar_cursor()
			}
			virtcol = get_nolist_virtcol() + char2cells(ch)
			if virtcol <= colnr_T(textwidth) {
				break
			}
		}

		if p_paste != 0 {
			break
		}
		startcol = curwin.w_cursor.col
		if startcol == 0 {
			break
		}

		coladvance(colnr_T(textwidth))
		wantcol = curwin.w_cursor.col

		if startcol < safe_tw {
			curwin.w_cursor.col = startcol
		} else {
			curwin.w_cursor.col = safe_tw
		}

		foundcol = 0
		first_pass = TRUE

		for {
			if first_pass != 0 && c != NUL {
				cc = c
				first_pass = FALSE
			} else {
				cc = gchar_cursor()
			}
			if (cc == ' ' || cc == '\t') && utf_iscomposing(utf_ptr2char(ml_get_cursor().Add(1))) == 0 {
				end_col = curwin.w_cursor.col

				for curwin.w_cursor.col > 0 && ((cc == ' ' || cc == '\t') && utf_iscomposing(utf_ptr2char(ml_get_cursor().Add(1))) == 0) {
					dec_cursor()
					cc = gchar_cursor()
				}
				if curwin.w_cursor.col == 0 && ((cc == ' ' || cc == '\t') && utf_iscomposing(utf_ptr2char(ml_get_cursor().Add(1))) == 0) {
					break
				}

				inc_cursor()

				end_foundcol = end_col + 1
				foundcol = curwin.w_cursor.col
				if curwin.w_cursor.col <= colnr_T(wantcol) {
					break
				}
			}
			if curwin.w_cursor.col == 0 {
				break
			}
			dec_cursor()
		}

		if foundcol == 0 {
			curwin.w_cursor.col = startcol
			break
		}

		undisplay_dollar()

		if (State & VREPLACE_FLAG) != 0 {
			orig_col = startcol
		} else {
			replace_offset = startcol - end_foundcol
		}

		curwin.w_cursor.col = foundcol
		for {
			cc = gchar_cursor()
			if !((cc == ' ' || cc == '\t') && utf_iscomposing(utf_ptr2char(ml_get_cursor().Add(1))) == 0) {
				break
			}
			inc_cursor()
		}
		startcol -= curwin.w_cursor.col
		if startcol < 0 {
			startcol = 0
		}

		if (State & VREPLACE_FLAG) != 0 {
			{
				len := ml_get_cursor_len()

				saved_text = vim_strnsave(ml_get_cursor(), usize(len))
			}
			curwin.w_cursor.col = orig_col
			if saved_text.Nil() {
				break
			}
			saved_text.Set(int(startcol), NUL)

			backspace_until_column(foundcol)
		} else {
			curwin.w_cursor.col = foundcol
		}

		open_line(FORWARD, OPENLINE_DELSPACES+OPENLINE_MARKFIX, old_indent, nil)
		old_indent = 0

		replace_offset = 0
		if (State & VREPLACE_FLAG) != 0 {
			ins_bytes(saved_text)
		} else {
			curwin.w_cursor.col += startcol
			len_ = ml_get_curline_len()
			if curwin.w_cursor.col > len_ {
				curwin.w_cursor.col = len_
			}
		}

		haveto_redraw = TRUE
		did_ai = FALSE
		did_si = FALSE
		can_si = FALSE
		can_si_back = FALSE
		line_breakcheck()
	}

	if save_char != NUL {
		pchar_cursor(save_char)
	}

	if haveto_redraw != 0 {
		update_topline()
		redraw_curbuf_later(UPD_VALID)
	}
}

func comp_textwidth() int32 {
	var textwidth int32

	textwidth = int32(curbuf.b_p_tw)
	if textwidth == 0 && curbuf.b_p_wm != 0 {
		textwidth = int32(int64(curwin.w_width) - curbuf.b_p_wm)
		if curwin.w_onebuf_opt.wo_nu != 0 || curwin.w_onebuf_opt.wo_rnu != 0 {
			textwidth -= 8
		}
	}
	if textwidth < 0 {
		textwidth = 0
	}
	return textwidth
}

func cls() int32 {
	var c int32

	c = gchar_cursor()
	if c == ' ' || c == '\t' || c == NUL {
		return 0
	}
	c = utf_class(c)
	if c != 0 && cls_bigword != 0 {
		return 1
	}
	return c
	// C: unreachable code follows the return above (the non-UTF-8 path); omitted.
}

func fwd_word(count int64, bigword int32, eol int32) int32 {
	var sclass int32
	var i int32
	var last_line int32

	curwin.w_cursor.coladd = 0
	cls_bigword = bigword
	for {
		count--
		if !(count >= 0) {
			break
		}
		sclass = cls()

		last_line = B2i(curwin.w_cursor.lnum == curbuf.b_ml.ml_line_count)
		i = inc_cursor()
		if i == -1 || (i >= 1 && last_line != 0) {
			return FAIL
		}
		if i >= 1 && eol != 0 && count == 0 {
			return OK
		}

		if sclass != 0 {
			for cls() == sclass {
				i = inc_cursor()
				if i == -1 || (i >= 1 && eol != 0 && count == 0) {
					return OK
				}
			}
		}

		for cls() == 0 {
			if curwin.w_cursor.col == 0 && ml_get_curline().Get() == NUL {
				break
			}

			i = inc_cursor()
			if i == -1 || (i >= 1 && eol != 0 && count == 0) {
				return OK
			}
		}
	}
	return OK
}

func bck_word(count int64, bigword int32, stop int32) int32 {
	var sclass int32

	curwin.w_cursor.coladd = 0
	cls_bigword = bigword
	for {
		count--
		if !(count >= 0) {
			break
		}
		sclass = cls()
		if dec_cursor() == -1 {
			return FAIL
		}

		if stop == 0 || sclass == cls() || sclass == 0 {
			for cls() == 0 {
				if curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).Get() == NUL {
					goto finished
				}
				if dec_cursor() == -1 {
					return OK
				}
			}

			if skip_chars(cls(), -1) != 0 {
				return OK
			}
		}

		inc_cursor()
	finished:
		stop = FALSE
	}
	adjust_skipcol()
	return OK
}

func end_word(count int64, bigword int32, stop int32, empty int32) int32 {
	var sclass int32

	curwin.w_cursor.coladd = 0
	cls_bigword = bigword

	if p_sel.Get() == 'e' && VIsual_active != 0 && VIsual_mode == 'v' && VIsual_select_exclu_adj != 0 {
		unadjust_for_sel()
	}

	for {
		count--
		if !(count >= 0) {
			break
		}
		sclass = cls()
		if inc_cursor() == -1 {
			return FAIL
		}

		if cls() == sclass && sclass != 0 {
			if skip_chars(sclass, FORWARD) != 0 {
				return FAIL
			}
		} else if stop == 0 || sclass == 0 {
			for cls() == 0 {
				if empty != 0 && curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).Get() == NUL {
					goto finished
				}
				if inc_cursor() == -1 {
					return FAIL
				}
			}

			if skip_chars(cls(), FORWARD) != 0 {
				return FAIL
			}
		}
		dec_cursor()
	finished:
		stop = FALSE
	}
	return OK
}

func bckend_word(count int64, bigword int32, eol int32) int32 {
	var sclass int32
	var i int32

	curwin.w_cursor.coladd = 0
	cls_bigword = bigword
	for {
		count--
		if !(count >= 0) {
			break
		}
		sclass = cls()
		i = dec_cursor()
		if i == -1 {
			return FAIL
		}
		if eol != 0 && i == 1 {
			return OK
		}

		if sclass != 0 {
			for cls() == sclass {
				i = dec_cursor()
				if i == -1 || (eol != 0 && i == 1) {
					return OK
				}
			}
		}

		for cls() == 0 {
			if curwin.w_cursor.col == 0 && ml_get(curwin.w_cursor.lnum).Get() == NUL {
				break
			}
			i = dec_cursor()
			if i == -1 || (eol != 0 && i == 1) {
				return OK
			}
		}
	}
	adjust_skipcol()
	return OK
}

func skip_chars(cclass int32, dir int32) int32 {
	for cls() == cclass {
		var r int32
		if dir == FORWARD {
			r = inc_cursor()
		} else {
			r = dec_cursor()
		}
		if r == -1 {
			return TRUE
		}
	}
	return FALSE
}

func back_in_line() {
	var sclass int32

	sclass = cls()
	for {
		if curwin.w_cursor.col == 0 {
			break
		}
		dec_cursor()
		if cls() != sclass {
			inc_cursor()
			break
		}
	}
}

// f16_ltpos is C's LT_POS(a, b) macro, expanded inline in the C.
func f16_ltpos(a pos_T, b pos_T) bool {
	if a.lnum != b.lnum {
		return a.lnum < b.lnum
	}
	if a.col != b.col {
		return a.col < b.col
	}
	return a.coladd < b.coladd
}

// f16_equalpos is C's EQUAL_POS(a, b) macro, expanded inline in the C.
func f16_equalpos(a pos_T, b pos_T) bool {
	return a.lnum == b.lnum && a.col == b.col && a.coladd == b.coladd
}

func current_word(oap *S_oparg_S, count int64, include int32, bigword int32) int32 {
	var start_pos pos_T
	var pos pos_T
	var inclusive int32 = TRUE
	var include_white int32 = FALSE

	cls_bigword = bigword
	start_pos.lnum = 0
	start_pos.col = 0
	start_pos.coladd = 0

	if VIsual_active != 0 && p_sel.Get() == 'e' && f16_ltpos(VIsual, curwin.w_cursor) {
		dec_cursor()
	}

	if VIsual_active == 0 || f16_equalpos(curwin.w_cursor, VIsual) {
		back_in_line()
		start_pos = curwin.w_cursor

		if B2i(cls() == 0) == include {
			if end_word(1, bigword, TRUE, TRUE) == FAIL {
				return FAIL
			}
		} else {
			fwd_word(1, bigword, TRUE)
			if curwin.w_cursor.col == 0 {
				decl(&curwin.w_cursor)
			} else {
				oneleft()
			}

			if include != 0 {
				include_white = TRUE
			}
		}

		if VIsual_active != 0 {
			VIsual = start_pos
			redraw_curbuf_later(UPD_INVERTED)
		} else {
			oap.start = start_pos
			oap.motion_type = MCHAR
		}
		count--
	}

	for count > 0 {
		inclusive = TRUE
		if VIsual_active != 0 && f16_ltpos(curwin.w_cursor, VIsual) {
			if decl(&curwin.w_cursor) == -1 {
				return FAIL
			}
			if include != B2i(cls() != 0) {
				if bck_word(1, bigword, TRUE) == FAIL {
					return FAIL
				}
			} else {
				if bckend_word(1, bigword, TRUE) == FAIL {
					return FAIL
				}
				incl(&curwin.w_cursor)
			}
		} else {
			if incl(&curwin.w_cursor) == -1 {
				return FAIL
			}
			if include != B2i(cls() == 0) {
				if fwd_word(1, bigword, TRUE) == FAIL && count > 1 {
					return FAIL
				}
				if oneleft() == FAIL {
					inclusive = FALSE
				}
			} else {
				if end_word(1, bigword, TRUE, TRUE) == FAIL {
					return FAIL
				}
			}
		}
		count--
	}

	if include_white != 0 && (cls() != 0 || (curwin.w_cursor.col == 0 && inclusive == 0)) {
		pos = curwin.w_cursor
		curwin.w_cursor = start_pos
		if oneleft() == OK {
			back_in_line()
			if cls() == 0 && curwin.w_cursor.col > 0 {
				if VIsual_active != 0 {
					VIsual = curwin.w_cursor
				} else {
					oap.start = curwin.w_cursor
				}
			}
		}
		curwin.w_cursor = pos
	}

	if VIsual_active != 0 {
		if p_sel.Get() == 'e' && inclusive != 0 && (f16_ltpos(VIsual, curwin.w_cursor) || f16_equalpos(VIsual, curwin.w_cursor)) {
			inc_cursor()
		}
		if VIsual_mode == 'V' {
			VIsual_mode = 'v'
			redraw_cmdline = TRUE
		}
	} else {
		oap.inclusive = inclusive
	}

	return OK
}

func current_block(oap *S_oparg_S, count int64, include int32, what int32, other int32) int32 {
	var old_pos pos_T
	var pos *pos_T = nil
	var start_pos pos_T
	var end_pos *pos_T
	var old_start pos_T
	var old_end pos_T
	var save_cpo Ptr[byte]
	var sol int32 = FALSE

	old_pos = curwin.w_cursor
	old_end = curwin.w_cursor
	old_start = old_end

	if VIsual_active == 0 || f16_equalpos(VIsual, curwin.w_cursor) {
		setpcmark()
		if what == '{' {
			for inindent(1) != 0 {
				if inc_cursor() != 0 {
					break
				}
			}
		}
		if gchar_cursor() == what {
			curwin.w_cursor.col++
		}
	} else if f16_ltpos(VIsual, curwin.w_cursor) {
		old_start = VIsual
		curwin.w_cursor = VIsual
	} else {
		old_end = VIsual
	}

	save_cpo = p_cpo
	if !vim_strchr(p_cpo, CPO_MATCHBSL).Nil() {
		p_cpo = S("%M")
	} else {
		p_cpo = S("%")
	}
	pos = findmatch(nil, what)
	if pos != nil {
		for {
			cnt := count
			count--
			if !(cnt > 0) {
				break
			}
			pos = findmatch(nil, what)
			if pos == nil {
				break
			}
			curwin.w_cursor = *pos
			start_pos = *pos
		}
	} else {
		for {
			cnt := count
			count--
			if !(cnt > 0) {
				break
			}
			pos = findmatchlimit(nil, what, FM_FORWARD, 0)
			if pos == nil {
				break
			}
			curwin.w_cursor = *pos
			start_pos = *pos
		}
	}
	p_cpo = save_cpo

	if pos == nil {
		curwin.w_cursor = old_pos
		return FAIL
	}
	end_pos = findmatch(nil, other)
	if end_pos == nil {
		curwin.w_cursor = old_pos
		return FAIL
	}
	curwin.w_cursor = *end_pos

	for include == 0 {
		incl(&start_pos)
		sol = B2i(curwin.w_cursor.col == 0)
		decl(&curwin.w_cursor)
		for inindent(1) != 0 {
			sol = TRUE
			if decl(&curwin.w_cursor) != 0 {
				break
			}
		}

		if f16_equalpos(start_pos, *end_pos) && VIsual_active != 0 {
			curwin.w_cursor = old_pos
			return FAIL
		}

		if !f16_ltpos(start_pos, old_start) && !f16_ltpos(old_end, curwin.w_cursor) && !f16_equalpos(start_pos, curwin.w_cursor) && VIsual_active != 0 {
			curwin.w_cursor = old_start
			decl(&curwin.w_cursor)
			pos = findmatch(nil, what)
			if pos == nil {
				curwin.w_cursor = old_pos
				return FAIL
			}
			start_pos = *pos
			curwin.w_cursor = *pos
			end_pos = findmatch(nil, other)
			if end_pos == nil {
				curwin.w_cursor = old_pos
				return FAIL
			}
			curwin.w_cursor = *end_pos
		} else {
			break
		}
	}

	if VIsual_active != 0 {
		if p_sel.Get() == 'e' {
			inc(&curwin.w_cursor)
		}
		if sol != 0 && gchar_cursor() != NUL {
			inc(&curwin.w_cursor)
		}
		VIsual = start_pos
		VIsual_mode = 'v'
		redraw_curbuf_later(UPD_INVERTED)
		showmode()
	} else {
		oap.start = start_pos
		oap.motion_type = MCHAR
		oap.inclusive = FALSE
		if sol != 0 {
			incl(&curwin.w_cursor)
		} else if f16_ltpos(start_pos, curwin.w_cursor) || f16_equalpos(start_pos, curwin.w_cursor) {
			oap.inclusive = TRUE
		} else {
			curwin.w_cursor = start_pos
		}
	}

	return OK
}

func find_next_quote(line Ptr[byte], col int32, quotechar int32, escape Ptr[byte]) int32 {
	var c int32

	for {
		c = int32(line.At(int(col)))
		if c == NUL {
			return -1
		} else if !escape.Nil() && !vim_strchr(escape, c).Nil() {
			col++
			if line.At(int(col)) == NUL {
				return -1
			}
		} else if c == quotechar {
			break
		}
		col += utfc_ptr2len(line.Add(int(col)))
	}
	return col
}

func find_prev_quote(line Ptr[byte], col_start int32, quotechar int32, escape Ptr[byte]) int32 {
	var n int32

	for col_start > 0 {
		col_start--
		col_start -= utf_head_off(line, line.Add(int(col_start)))
		n = 0
		if !escape.Nil() {
			for col_start-n > 0 && !vim_strchr(escape, int32(line.At(int(col_start-n-1)))).Nil() {
				n++
			}
		}
		if n&1 != 0 {
			col_start -= n
		} else if int32(line.At(int(col_start))) == quotechar {
			break
		}
	}
	return col_start
}

func current_quote(oap *S_oparg_S, count int64, include int32, quotechar int32) int32 {
	var line Ptr[byte] = ml_get_curline()
	var col_end int32
	var col_start int32 = curwin.w_cursor.col
	var inclusive int32 = FALSE
	var vis_empty int32 = TRUE
	var vis_bef_curs int32 = FALSE
	var did_exclusive_adj int32 = FALSE
	var inside_quotes int32 = FALSE
	var selected_quote int32 = FALSE
	var i int32
	var restore_vis_bef int32 = FALSE

	if VIsual_active != 0 {
		if VIsual.lnum != curwin.w_cursor.lnum {
			return FALSE
		}

		vis_bef_curs = B2i(f16_ltpos(VIsual, curwin.w_cursor))
		vis_empty = B2i(f16_equalpos(VIsual, curwin.w_cursor))
		if p_sel.Get() == 'e' {
			if vis_bef_curs != 0 {
				dec_cursor()
				did_exclusive_adj = TRUE
			} else if vis_empty == 0 {
				dec(&VIsual)
				did_exclusive_adj = TRUE
			}
			vis_empty = B2i(f16_equalpos(VIsual, curwin.w_cursor))
			if vis_bef_curs == 0 && vis_empty == 0 {
				t := curwin.w_cursor

				curwin.w_cursor = VIsual
				VIsual = t
				vis_bef_curs = TRUE
				restore_vis_bef = TRUE
			}
		}
	}

	if vis_empty == 0 {
		if vis_bef_curs != 0 {
			inside_quotes = B2i(VIsual.col > 0 && int32(line.At(int(VIsual.col-1))) == quotechar && line.At(int(curwin.w_cursor.col)) != NUL && int32(line.At(int(curwin.w_cursor.col+1))) == quotechar)
			i = VIsual.col
			col_end = curwin.w_cursor.col
		} else {
			inside_quotes = B2i(curwin.w_cursor.col > 0 && int32(line.At(int(curwin.w_cursor.col-1))) == quotechar && line.At(int(VIsual.col)) != NUL && int32(line.At(int(VIsual.col+1))) == quotechar)
			i = curwin.w_cursor.col
			col_end = VIsual.col
		}

		for i <= col_end {
			if line.At(int(i)) == NUL {
				break
			}
			ch := line.At(int(i))
			i++
			if int32(ch) == quotechar {
				selected_quote = TRUE
				break
			}
		}
	}

	if vis_empty == 0 && int32(line.At(int(col_start))) == quotechar {
		if vis_bef_curs != 0 {
			col_start = find_next_quote(line, col_start+1, quotechar, Ptr[byte]{})
			if col_start < 0 {
				goto abort_search
			}
			col_end = find_next_quote(line, col_start+1, quotechar, curbuf.b_p_qe)
			if col_end < 0 {
				col_end = col_start
				col_start = curwin.w_cursor.col
			}
		} else {
			col_end = find_prev_quote(line, col_start, quotechar, Ptr[byte]{})
			if int32(line.At(int(col_end))) != quotechar {
				goto abort_search
			}
			col_start = find_prev_quote(line, col_end, quotechar, curbuf.b_p_qe)
			if int32(line.At(int(col_start))) != quotechar {
				col_start = col_end
				col_end = curwin.w_cursor.col
			}
		}
	} else {
		if int32(line.At(int(col_start))) == quotechar || vis_empty == 0 {
			first_col := col_start

			if vis_empty == 0 {
				if vis_bef_curs != 0 {
					first_col = find_next_quote(line, col_start, quotechar, Ptr[byte]{})
				} else {
					first_col = find_prev_quote(line, col_start, quotechar, Ptr[byte]{})
				}
			}

			col_start = 0
			for {
				col_start = find_next_quote(line, col_start, quotechar, Ptr[byte]{})
				if col_start < 0 || col_start > first_col {
					goto abort_search
				}
				col_end = find_next_quote(line, col_start+1, quotechar, curbuf.b_p_qe)
				if col_end < 0 {
					goto abort_search
				}
				if col_start <= first_col && first_col <= col_end {
					break
				}
				col_start = col_end + 1
			}
		} else {
			col_start = find_prev_quote(line, col_start, quotechar, curbuf.b_p_qe)
			if int32(line.At(int(col_start))) != quotechar {
				col_start = find_next_quote(line, col_start, quotechar, Ptr[byte]{})
				if col_start < 0 {
					goto abort_search
				}
			}

			col_end = find_next_quote(line, col_start+1, quotechar, curbuf.b_p_qe)
			if col_end < 0 {
				goto abort_search
			}
		}
	}

	if include != 0 {
		if line.At(int(col_end+1)) == ' ' || line.At(int(col_end+1)) == '\t' {
			for line.At(int(col_end+1)) == ' ' || line.At(int(col_end+1)) == '\t' {
				col_end++
			}
		} else {
			for col_start > 0 && (line.At(int(col_start-1)) == ' ' || line.At(int(col_start-1)) == '\t') {
				col_start--
			}
		}
	}

	if include == 0 && count < 2 && (vis_empty != 0 || inside_quotes == 0) {
		col_start++
	}
	curwin.w_cursor.col = col_start
	if VIsual_active != 0 {
		if vis_empty != 0 || (vis_bef_curs != 0 && selected_quote == 0 && (inside_quotes != 0 || (int32(line.At(int(VIsual.col))) != quotechar && (VIsual.col == 0 || int32(line.At(int(VIsual.col-1))) != quotechar)))) {
			VIsual = curwin.w_cursor
			redraw_curbuf_later(UPD_INVERTED)
		}
	} else {
		oap.start = curwin.w_cursor
		oap.motion_type = MCHAR
	}

	curwin.w_cursor.col = col_end
	if (include != 0 || count > 1 || (vis_empty == 0 && inside_quotes != 0)) && inc_cursor() == 2 {
		inclusive = TRUE
	}
	if VIsual_active != 0 {
		if vis_empty != 0 || vis_bef_curs != 0 {
			if p_sel.Get() != 'e' {
				dec_cursor()
			}
		} else {
			if inside_quotes != 0 || (selected_quote == 0 && int32(line.At(int(VIsual.col))) != quotechar && (line.At(int(VIsual.col)) == NUL || int32(line.At(int(VIsual.col+1))) != quotechar)) {
				dec_cursor()
				VIsual = curwin.w_cursor
			}
			curwin.w_cursor.col = col_start
		}
		if VIsual_mode == 'V' {
			VIsual_mode = 'v'
			redraw_cmdline = TRUE
		}
	} else {
		oap.inclusive = inclusive
	}

	return OK

abort_search:
	if VIsual_active != 0 && p_sel.Get() == 'e' {
		if did_exclusive_adj != 0 {
			inc_cursor()
		}
		if restore_vis_bef != 0 {
			t := curwin.w_cursor

			curwin.w_cursor = VIsual
			VIsual = t
		}
	}
	return FALSE
}

