func ui_inchar(buf Ptr[byte], maxlen int32, wtime int64, tb_change_cnt int32) int32 {
	var retval int32 = 0

	if wtime == -1 || wtime > 100 {
		vim_handle_signal(-2)

		if ((mapped_ctrl_c | curbuf.b_mapped_ctrl_c) & get_real_state()) != 0 {
			ctrl_c_interrupts = FALSE
		}
	}

	retval = mch_inchar(buf, maxlen, wtime, tb_change_cnt)

	if wtime == -1 || wtime > 100 {
		vim_handle_signal(-1)
	}

	ctrl_c_interrupts = TRUE

	return retval
}

// ==== from f17.go ====
// Transpiled by hand from editor.c: inchar_loop .. vim_main.

func inchar_loop(buf Ptr[byte], maxlen int32, wtime int64, tb_change_cnt int32, wait_func func(int64, *int32, int32) int32, resize_func func(int32) int32) int32 {
	var len_ int32
	var interrupted int32 = FALSE
	var did_call_wait_func int32 = FALSE
	var wait_time int64
	var elapsed_time int64 = 0
	var start_tv int64

	start_tv = musl_now_ms()

	for {
		if resize_func != nil {
			resize_func(FALSE)
		}

		if wtime < 0 {
			wait_time = -1
		} else {
			elapsed_time = musl_now_ms() - start_tv
			wait_time = wtime - elapsed_time

			if wait_time <= 0 && did_call_wait_func != 0 {
				return 0
			}
		}

		did_call_wait_func = TRUE
		if wait_func(wait_time, &interrupted, FALSE) != 0 {
			if typebuf_changed(tb_change_cnt) != 0 {
				return 0
			}

			if buf.Nil() {
				return input_available()
			}

			len_ = read_from_input_buf(buf, int64(maxlen))
			if len_ > 0 {
				return len_
			}
			continue
		}

		if (resize_func != nil && resize_func(TRUE) != 0) || wait_time > 0 {
			continue
		}

		break
	}
	return 0
}

